public class ObjectBounce : MonoBehaviour
{
	public delegate void BounceEvent();

	public float bounceFactor;

	public float speedThreshold = 1f;

	public bool playSound;

	public AudioClip[] clips;

	public int chanceToPlay = 100;

	public float pitchMin = 1f;

	public float pitchMax = 1f;

	public bool playAnimationOnBounce;

	public string animationName;

	public float animPause = 0.5f;

	public bool sendFSMEvent;

	private float speed;

	private float animTimer;

	private tk2dSpriteAnimator animator;

	private PlayMakerFSM fsm;

	private Vector2 velocity;

	private Vector2 lastPos;

	private Rigidbody2D rb;

	private AudioSource audio;

	private int chooser;

	private bool bouncing = true;

	private int stepCounter;

	public event BounceEvent OnBounce;

	private void Start()
	{
		rb = GetComponent<Rigidbody2D>();
		audio = GetComponent<AudioSource>();
		animator = GetComponent<tk2dSpriteAnimator>();
		if (sendFSMEvent)
		{
			fsm = GetComponent<PlayMakerFSM>();
		}
	}

	private void FixedUpdate()
	{
		if (bouncing)
		{
			if (stepCounter >= 3)
			{
				Vector2 vector = new Vector2(base.transform.position.x, base.transform.position.y);
				velocity = vector - lastPos;
				lastPos = vector;
				speed = (rb ? rb.velocity.magnitude : 0f);
				stepCounter = 0;
			}
			else
			{
				stepCounter++;
			}
		}
	}

	private void Update()
	{
		if (animTimer > 0f)
		{
			animTimer -= Time.deltaTime;
		}
	}

	private void OnCollisionEnter2D(Collision2D col)
	{
		if (!rb || rb.isKinematic || !bouncing || !(speed > speedThreshold))
		{
			return;
		}
		Vector3 inNormal = col.GetSafeContact().Normal;
		Vector3 normalized = Vector3.Reflect(velocity.normalized, inNormal).normalized;
		rb.velocity = new Vector2(normalized.x, normalized.y) * (speed * (bounceFactor * UnityEngine.Random.Range(0.8f, 1.2f)));
		if (playSound)
		{
			chooser = UnityEngine.Random.Range(1, 100);
			int num = UnityEngine.Random.Range(0, clips.Length - 1);
			AudioClip clip = clips[num];
			if (chooser <= chanceToPlay)
			{
				float pitch = UnityEngine.Random.Range(pitchMin, pitchMax);
				audio.pitch = pitch;
				audio.PlayOneShot(clip);
			}
		}
		if (playAnimationOnBounce && animTimer <= 0f)
		{
			animator.Play(animationName);
			animator.PlayFromFrame(0);
			animTimer = animPause;
		}
		if (sendFSMEvent && (bool)fsm)
		{
			fsm.SendEvent("BOUNCE");
		}
		if (OnBounce != null)
		{
			OnBounce();
		}
	}

	public void StopBounce()
	{
		bouncing = false;
	}

	public void StartBounce()
	{
		bouncing = true;
	}

	public void SetBounceFactor(float value)
	{
		bounceFactor = value;
	}

	public void SetBounceAnimation(bool set)
	{
		playAnimationOnBounce = set;
	}
}
public class Bullet : MonoBehaviour
{
	public Explosion explosionPrefab;

	public float shootDistance;

	public float shootSpeed;

	private void OnEnable()
	{
		StartCoroutine(Shoot());
	}

	private void OnDisable()
	{
		StopAllCoroutines();
	}

	private IEnumerator Shoot()
	{
		float travelledDistance = 0f;
		while (travelledDistance < shootDistance)
		{
			travelledDistance += shootSpeed * Time.deltaTime;
			transform.position += transform.forward * (shootSpeed * Time.deltaTime);
			yield return 0;
		}
		explosionPrefab.Spawn(transform.position);
		gameObject.Recycle();
	}
}
public class Explosion : MonoBehaviour
{
	public AnimationCurve animationCurve;

	public float duration;

	private void OnEnable()
	{
		StartCoroutine(Shrink());
	}

	private IEnumerator Shrink()
	{
		transform.localScale = Vector3.one;
		float elapsed = 0f;
		while (elapsed < duration)
		{
			float num = 1f - animationCurve.Evaluate(elapsed / duration);
			transform.localScale = new Vector3(num, num, num);
			elapsed += Time.deltaTime;
			yield return 0;
		}
		gameObject.Recycle();
	}
}
public class Turret : MonoBehaviour
{
	public Bullet bulletPrefab;

	public Transform gun;

	public GameObject testPrefab;

	private void Awake()
	{
	}

	private void Update()
	{
		Plane plane = new Plane(Vector3.up, base.transform.position);
		Ray ray = Camera.main.ScreenPointToRay(Input.mousePosition);
		if (plane.Raycast(ray, out var enter))
		{
			Quaternion to = Quaternion.LookRotation(Vector3.Normalize(ray.GetPoint(enter) - base.transform.position));
			base.transform.rotation = Quaternion.RotateTowards(base.transform.rotation, to, 360f * Time.deltaTime);
			if (Input.GetMouseButtonDown(0))
			{
				bulletPrefab.Spawn(gun.position, gun.rotation);
			}
			if (Input.GetMouseButtonDown(1))
			{
				testPrefab.Spawn(gun.position, gun.rotation);
			}
		}
		if (Input.GetKeyDown(KeyCode.Space))
		{
			bulletPrefab.DestroyPooled();
		}
		if (Input.GetKeyDown(KeyCode.Z))
		{
			bulletPrefab.DestroyAll();
		}
	}
}
public sealed class ObjectPool : MonoBehaviour
{
	[Serializable]
	public class StartupPool
	{
		public int size;

		public GameObject prefab;
	}

	private static List<GameObject> tempList = new List<GameObject>();

	private static List<GameObject> destroyList = new List<GameObject>();

	private Dictionary<GameObject, List<GameObject>> pooledObjects = new Dictionary<GameObject, List<GameObject>>();

	private Dictionary<GameObject, GameObject> spawnedObjects = new Dictionary<GameObject, GameObject>();

	public StartupPool[] startupPools;

	private bool startupPoolsCreated;

	private static Vector2 activeStashLocation = new Vector2(-20f, -20f);

	private static bool isRecycling;

	private static ObjectPool _instance;

	public static ObjectPool instance
	{
		get
		{
			if (_instance == null)
			{
				_instance = UnityEngine.Object.FindObjectOfType<ObjectPool>();
				if (_instance == null)
				{
					UnityEngine.Debug.LogError("Couldn't find an Object Pool, make sure a Game Manager exists in the scene.");
				}
				else
				{
					UnityEngine.Object.DontDestroyOnLoad(_instance.gameObject);
				}
			}
			return _instance;
		}
	}

	private void Awake()
	{
		if (_instance == null)
		{
			_instance = this;
			UnityEngine.Object.DontDestroyOnLoad(this);
		}
		else if (this != _instance)
		{
			UnityEngine.Debug.LogErrorFormat("An extra Global Object Pool has been created by {0} please remove this script. Master Object Pool: {1} (Scene: {2} at time: {3})", base.transform.parent.name, _instance.name, Application.loadedLevelName, Time.realtimeSinceStartup);
			if (base.transform.parent.name == "_GameManager")
			{
				UnityEngine.Debug.Log("Object Pool instance is no longer set to master object pool, another Object Pool exists in this scene. Instance currently set to : " + _instance.name);
				_instance = this;
			}
			else
			{
				UnityEngine.Object.Destroy(base.gameObject);
			}
		}
	}

	private void Start()
	{
		if (!instance.startupPoolsCreated)
		{
			CreateStartupPools();
			return;
		}
		for (int i = 0; i < startupPools.Length; i++)
		{
			startupPools[i].prefab.CreatePool(startupPools[i].size);
		}
	}

	public static void CreateStartupPools()
	{
		if (instance.startupPoolsCreated)
		{
			return;
		}
		instance.startupPoolsCreated = true;
		StartupPool[] array = instance.startupPools;
		if (array != null && array.Length != 0)
		{
			for (int i = 0; i < array.Length; i++)
			{
				CreatePool(array[i].prefab, array[i].size);
			}
		}
	}

	public static void CreatePool<T>(T prefab, int initialPoolSize) where T : Component
	{
		CreatePool(prefab.gameObject, initialPoolSize);
	}

	public static void CreatePool(GameObject prefab, int initialPoolSize)
	{
		try
		{
			orig_CreatePool(prefab, initialPoolSize);
		}
		catch (NullReferenceException) when (!ModLoader.LoadState.HasFlag(ModLoader.ModLoadState.Preloaded))
		{
		}
	}

	public void RevertToStartState()
	{
		RecycleAll();
		List<GameObject> list = new List<GameObject>();
		foreach (KeyValuePair<GameObject, List<GameObject>> pooledObject in pooledObjects)
		{
			GameObject key = pooledObject.Key;
			List<GameObject> value = pooledObject.Value;
			int num = 0;
			for (int i = 0; i < startupPools.Length; i++)
			{
				StartupPool startupPool = startupPools[i];
				if (startupPool.prefab == key)
				{
					num = startupPool.size;
					break;
				}
			}
			while (value.Count > num)
			{
				UnityEngine.Object.Destroy(value[0]);
				value.RemoveAt(0);
			}
			if (value.Count < num)
			{
				CreatePool(key, num - value.Count);
			}
			else if (num == 0)
			{
				list.Add(key);
			}
		}
		foreach (GameObject item in list)
		{
			pooledObjects.Remove(item);
		}
	}

	public static T Spawn<T>(T prefab, Transform parent, Vector3 position, Quaternion rotation) where T : Component
	{
		return Spawn(prefab.gameObject, parent, position, rotation).GetComponent<T>();
	}

	public static T Spawn<T>(T prefab, Vector3 position, Quaternion rotation) where T : Component
	{
		return Spawn(prefab.gameObject, null, position, rotation).GetComponent<T>();
	}

	public static T Spawn<T>(T prefab, Transform parent, Vector3 position) where T : Component
	{
		return Spawn(prefab.gameObject, parent, position, Quaternion.identity).GetComponent<T>();
	}

	public static T Spawn<T>(T prefab, Vector3 position) where T : Component
	{
		return Spawn(prefab.gameObject, null, position, Quaternion.identity).GetComponent<T>();
	}

	public static T Spawn<T>(T prefab, Transform parent) where T : Component
	{
		return Spawn(prefab.gameObject, parent, Vector3.zero, Quaternion.identity).GetComponent<T>();
	}

	public static T Spawn<T>(T prefab) where T : Component
	{
		return Spawn(prefab.gameObject, null, Vector3.zero, Quaternion.identity).GetComponent<T>();
	}

	public static GameObject Spawn(GameObject prefab, Transform parent, Vector3 position, Quaternion rotation)
	{
		try
		{
			return ModHooks.OnObjectPoolSpawn(orig_Spawn(prefab, parent, position, rotation));
		}
		catch (NullReferenceException) when (!ModLoader.LoadState.HasFlag(ModLoader.ModLoadState.Preloaded))
		{
			return null;
		}
	}

	public static GameObject Spawn(GameObject prefab, Transform parent, Vector3 position)
	{
		return Spawn(prefab, parent, position, Quaternion.identity);
	}

	public static GameObject Spawn(GameObject prefab, Vector3 position, Quaternion rotation)
	{
		return Spawn(prefab, null, position, rotation);
	}

	public static GameObject Spawn(GameObject prefab, Transform parent)
	{
		return Spawn(prefab, parent, Vector3.zero, Quaternion.identity);
	}

	public static GameObject Spawn(GameObject prefab, Vector3 position)
	{
		return Spawn(prefab, null, position, Quaternion.identity);
	}

	public static GameObject Spawn(GameObject prefab)
	{
		return Spawn(prefab, null, Vector3.zero, Quaternion.identity);
	}

	public static void Recycle<T>(T obj) where T : Component
	{
		Recycle(obj.gameObject);
	}

	public static void Recycle(GameObject obj)
	{
		if (instance != null && instance.spawnedObjects.TryGetValue(obj, out var value))
		{
			Recycle(obj, value);
			return;
		}
		ObjectPoolAuditor.RecordDespawned(obj, willReuse: false);
		UnityEngine.Object.Destroy(obj);
	}

	private static void Recycle(GameObject obj, GameObject prefab)
	{
		isRecycling = true;
		if (obj != null && prefab != null)
		{
			instance.pooledObjects[prefab].Add(obj);
			instance.spawnedObjects.Remove(obj);
			obj.transform.parent = instance.transform;
			if (obj.GetComponent<ActiveRecycler>() != null)
			{
				obj.transform.SetPosition2D(activeStashLocation);
				FSMUtility.SendEventToGameObject(obj, "A RECYCLE");
			}
			else
			{
				obj.SetActive(value: false);
			}
			ObjectPoolAuditor.RecordDespawned(obj, willReuse: true);
		}
		isRecycling = false;
	}

	public static void RecycleAll<T>(T prefab) where T : Component
	{
		RecycleAll(prefab.gameObject);
	}

	public static void RecycleAll(GameObject prefab)
	{
		foreach (KeyValuePair<GameObject, GameObject> spawnedObject in instance.spawnedObjects)
		{
			if (spawnedObject.Value == prefab)
			{
				tempList.Add(spawnedObject.Key);
			}
		}
		for (int i = 0; i < tempList.Count; i++)
		{
			Recycle(tempList[i]);
		}
		tempList.Clear();
	}

	public static void RecycleAll()
	{
		tempList.AddRange(instance.spawnedObjects.Keys);
		for (int i = 0; i < tempList.Count; i++)
		{
			Recycle(tempList[i]);
		}
		tempList.Clear();
	}

	public static bool IsSpawned(GameObject obj)
	{
		return instance.spawnedObjects.ContainsKey(obj);
	}

	public static int CountPooled<T>(T prefab) where T : Component
	{
		return CountPooled(prefab.gameObject);
	}

	public static int CountPooled(GameObject prefab)
	{
		if (instance.pooledObjects.TryGetValue(prefab, out var value))
		{
			return value.Count;
		}
		return 0;
	}

	public static int CountSpawned<T>(T prefab) where T : Component
	{
		return CountSpawned(prefab.gameObject);
	}

	public static int CountSpawned(GameObject prefab)
	{
		int num = 0;
		foreach (GameObject value in instance.spawnedObjects.Values)
		{
			if (prefab == value)
			{
				num++;
			}
		}
		return num;
	}

	public static int CountAllPooled()
	{
		int num = 0;
		foreach (List<GameObject> value in instance.pooledObjects.Values)
		{
			num += value.Count;
		}
		return num;
	}

	public static List<GameObject> GetPooled(GameObject prefab, List<GameObject> list, bool appendList)
	{
		if (list == null)
		{
			list = new List<GameObject>();
		}
		if (!appendList)
		{
			list.Clear();
		}
		if (instance.pooledObjects.TryGetValue(prefab, out var value))
		{
			list.AddRange(value);
		}
		return list;
	}

	public static List<T> GetPooled<T>(T prefab, List<T> list, bool appendList) where T : Component
	{
		if (list == null)
		{
			list = new List<T>();
		}
		if (!appendList)
		{
			list.Clear();
		}
		if (instance.pooledObjects.TryGetValue(prefab.gameObject, out var value))
		{
			for (int i = 0; i < value.Count; i++)
			{
				list.Add(value[i].GetComponent<T>());
			}
		}
		return list;
	}

	public static List<GameObject> GetSpawned(GameObject prefab, List<GameObject> list, bool appendList)
	{
		if (list == null)
		{
			list = new List<GameObject>();
		}
		if (!appendList)
		{
			list.Clear();
		}
		foreach (KeyValuePair<GameObject, GameObject> spawnedObject in instance.spawnedObjects)
		{
			if (spawnedObject.Value == prefab)
			{
				list.Add(spawnedObject.Key);
			}
		}
		return list;
	}

	public static List<T> GetSpawned<T>(T prefab, List<T> list, bool appendList) where T : Component
	{
		if (list == null)
		{
			list = new List<T>();
		}
		if (!appendList)
		{
			list.Clear();
		}
		GameObject gameObject = prefab.gameObject;
		foreach (KeyValuePair<GameObject, GameObject> spawnedObject in instance.spawnedObjects)
		{
			if (spawnedObject.Value == gameObject)
			{
				list.Add(spawnedObject.Key.GetComponent<T>());
			}
		}
		return list;
	}

	public static void DestroyPooled(GameObject prefab)
	{
		if (instance.pooledObjects.TryGetValue(prefab, out var value))
		{
			for (int i = 0; i < value.Count; i++)
			{
				UnityEngine.Object.Destroy(value[i]);
			}
			value.Clear();
		}
	}

	public static void DestroyPooled<T>(T prefab) where T : Component
	{
		DestroyPooled(prefab.gameObject);
	}

	public static void DestroyPooled(GameObject prefab, int amountToRemove)
	{
		RecycleAll(prefab);
		if (!instance.pooledObjects.TryGetValue(prefab, out var value))
		{
			return;
		}
		for (int i = 0; i < amountToRemove; i++)
		{
			if (value.Count <= 0)
			{
				break;
			}
			UnityEngine.Object.Destroy(value[0]);
			value.RemoveAt(0);
		}
	}

