[ActionCategory("Hollow Knight")]
public class PreSpawnGameObjects : FsmStateAction
{
	public FsmGameObject prefab;

	[UIHint(UIHint.Variable)]
	[ArrayEditor(VariableType.GameObject, "", 0, 0, 65536)]
	public FsmArray storeArray;

	public FsmInt spawnAmount;

	public FsmInt spawnAmountMultiplier;

	public override void Reset()
	{
		prefab = null;
		storeArray = null;
		spawnAmount = null;
		spawnAmountMultiplier = 1;
	}

	public override void OnEnter()
	{
		if ((bool)prefab.Value && !storeArray.IsNone && spawnAmount.Value > 0 && spawnAmountMultiplier.Value > 0)
		{
			int num = spawnAmount.Value * spawnAmountMultiplier.Value;
			storeArray.Resize(num);
			for (int i = 0; i < num; i++)
			{
				storeArray.Values[i] = UnityEngine.Object.Instantiate(prefab.Value);
				((GameObject)storeArray.Values[i]).SetActive(value: false);
			}
		}
		Finish();
	}
}
[ActionCategory("Hollow Knight")]
public class GetNextPreSpawnedGameObject : FsmStateAction
{
	[UIHint(UIHint.Variable)]
	[ArrayEditor(VariableType.GameObject, "", 0, 0, 65536)]
	public FsmArray storedArray;

	public FsmVector3 spawnPosition;

	[UIHint(UIHint.Variable)]
	public FsmGameObject storeObject;

	[UIHint(UIHint.Variable)]
	public FsmInt currentIndex;

	public override void Reset()
	{
		storedArray = null;
		spawnPosition = null;
		storeObject = null;
	}

	public override void OnEnter()
	{
		if (!currentIndex.IsNone && currentIndex.Value < storedArray.Length)
		{
			GameObject gameObject = (GameObject)storedArray.Values[currentIndex.Value];
			if (!spawnPosition.IsNone)
			{
				gameObject.transform.position = spawnPosition.Value;
			}
			gameObject.SetActive(value: true);
			storeObject.Value = gameObject;
			currentIndex.Value++;
		}
		Finish();
	}
}
[ActionCategory("Hollow Knight")]
public class RestoreGameObjectPositions : FsmStateAction
{
	private Dictionary<GameObject, Vector3> positions;

	public override void Reset()
	{
		base.Reset();
		positions = null;
	}

	public override void OnEnter()
	{
		base.OnEnter();
		if (positions == null)
		{
			positions = new Dictionary<GameObject, Vector3>(base.Owner.transform.childCount);
			foreach (Transform item in base.Owner.transform)
			{
				positions.Add(item.gameObject, item.localPosition);
			}
		}
		else
		{
			foreach (KeyValuePair<GameObject, Vector3> position in positions)
			{
				position.Key.transform.localPosition = position.Value;
			}
		}
		Finish();
	}
}
