[ExecuteInEditMode]
public class PlanarRealtimeReflection : MonoBehaviour
{
	public bool m_DisablePixelLights = true;

	public int m_TextureResolution = 1024;

	public float m_clipPlaneOffset = 0.07f;

	private float m_finalClipPlaneOffset;

	public bool m_NormalsFromMesh;

	public bool m_BaseClipOffsetFromMesh;

	public bool m_BaseClipOffsetFromMeshInverted;

	private Vector3 m_calculatedNormal = Vector3.zero;

	public LayerMask m_ReflectLayers = -1;

	private Hashtable m_ReflectionCameras = new Hashtable();

	private RenderTexture m_ReflectionTexture;

	private int m_OldReflectionTextureSize;

	private static bool s_InsideRendering;

	public void OnWillRenderObject()
	{
		if (!base.enabled || !GetComponent<Renderer>() || !GetComponent<Renderer>().sharedMaterial || !GetComponent<Renderer>().enabled)
		{
			return;
		}
		Camera current = Camera.current;
		if (!current)
		{
			return;
		}
		if (m_NormalsFromMesh && GetComponent<MeshFilter>() != null)
		{
			m_calculatedNormal = base.transform.TransformDirection(GetComponent<MeshFilter>().sharedMesh.normals[0]);
		}
		if (m_BaseClipOffsetFromMesh && GetComponent<MeshFilter>() != null)
		{
			m_finalClipPlaneOffset = (base.transform.position - base.transform.TransformPoint(GetComponent<MeshFilter>().sharedMesh.vertices[0])).magnitude + m_clipPlaneOffset;
		}
		else if (m_BaseClipOffsetFromMeshInverted && GetComponent<MeshFilter>() != null)
		{
			m_finalClipPlaneOffset = 0f - (base.transform.position - base.transform.TransformPoint(GetComponent<MeshFilter>().sharedMesh.vertices[0])).magnitude + m_clipPlaneOffset;
		}
		else
		{
			m_finalClipPlaneOffset = m_clipPlaneOffset;
		}
		if (s_InsideRendering)
		{
			return;
		}
		s_InsideRendering = true;
		CreateSurfaceObjects(current, out var reflectionCamera);
		Vector3 position = base.transform.position;
		Vector3 vector = ((m_NormalsFromMesh && GetComponent<MeshFilter>() != null) ? m_calculatedNormal : base.transform.up);
		int pixelLightCount = QualitySettings.pixelLightCount;
		if (m_DisablePixelLights)
		{
			QualitySettings.pixelLightCount = 0;
		}
		UpdateCameraModes(current, reflectionCamera);
		float w = 0f - Vector3.Dot(vector, position) - m_finalClipPlaneOffset;
		Vector4 plane = new Vector4(vector.x, vector.y, vector.z, w);
		Matrix4x4 reflectionMat = Matrix4x4.zero;
		CalculateReflectionMatrix(ref reflectionMat, plane);
		Vector3 position2 = current.transform.position;
		Vector3 position3 = reflectionMat.MultiplyPoint(position2);
		reflectionCamera.worldToCameraMatrix = current.worldToCameraMatrix * reflectionMat;
		Vector4 clipPlane = CameraSpacePlane(reflectionCamera, position, vector, 1f);
		Matrix4x4 projection = current.projectionMatrix;
		CalculateObliqueMatrix(ref projection, clipPlane);
		reflectionCamera.projectionMatrix = projection;
		reflectionCamera.cullingMask = -17 & m_ReflectLayers.value;
		reflectionCamera.targetTexture = m_ReflectionTexture;
		GL.SetRevertBackfacing(revertBackFaces: true);
		reflectionCamera.transform.position = position3;
		Vector3 eulerAngles = current.transform.eulerAngles;
		reflectionCamera.transform.eulerAngles = new Vector3(0f, eulerAngles.y, eulerAngles.z);
		reflectionCamera.Render();
		reflectionCamera.transform.position = position2;
		GL.SetRevertBackfacing(revertBackFaces: false);
		Material[] sharedMaterials = GetComponent<Renderer>().sharedMaterials;
		Material[] array = sharedMaterials;
		foreach (Material material in array)
		{
			if (material.HasProperty("_ReflectionTex"))
			{
				material.SetTexture("_ReflectionTex", m_ReflectionTexture);
			}
		}
		Matrix4x4 matrix4x = Matrix4x4.TRS(new Vector3(0.5f, 0.5f, 0.5f), Quaternion.identity, new Vector3(0.5f, 0.5f, 0.5f));
		Vector3 lossyScale = base.transform.lossyScale;
		Matrix4x4 matrix4x2 = base.transform.localToWorldMatrix * Matrix4x4.Scale(new Vector3(1f / lossyScale.x, 1f / lossyScale.y, 1f / lossyScale.z));
		matrix4x2 = matrix4x * current.projectionMatrix * current.worldToCameraMatrix * matrix4x2;
		array = sharedMaterials;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].SetMatrix("_ProjMatrix", matrix4x2);
		}
		if (m_DisablePixelLights)
		{
			QualitySettings.pixelLightCount = pixelLightCount;
		}
		s_InsideRendering = false;
	}

	private void OnDisable()
	{
		if ((bool)m_ReflectionTexture)
		{
			UnityEngine.Object.DestroyImmediate(m_ReflectionTexture);
			m_ReflectionTexture = null;
		}
		foreach (DictionaryEntry reflectionCamera in m_ReflectionCameras)
		{
			UnityEngine.Object.DestroyImmediate(((Camera)reflectionCamera.Value).gameObject);
		}
		m_ReflectionCameras.Clear();
	}

	private void UpdateCameraModes(Camera src, Camera dest)
	{
		if (dest == null)
		{
			return;
		}
		dest.clearFlags = src.clearFlags;
		dest.backgroundColor = src.backgroundColor;
		if (src.clearFlags == CameraClearFlags.Skybox)
		{
			Skybox skybox = src.GetComponent(typeof(Skybox)) as Skybox;
			Skybox skybox2 = dest.GetComponent(typeof(Skybox)) as Skybox;
			if (!skybox || !skybox.material)
			{
				skybox2.enabled = false;
			}
			else
			{
				skybox2.enabled = true;
				skybox2.material = skybox.material;
			}
		}
		dest.farClipPlane = src.farClipPlane;
		dest.nearClipPlane = src.nearClipPlane;
		dest.orthographic = src.orthographic;
		dest.fieldOfView = src.fieldOfView;
		dest.aspect = src.aspect;
		dest.orthographicSize = src.orthographicSize;
	}

	private void CreateSurfaceObjects(Camera currentCamera, out Camera reflectionCamera)
	{
		reflectionCamera = null;
		if (!m_ReflectionTexture || m_OldReflectionTextureSize != m_TextureResolution)
		{
			if ((bool)m_ReflectionTexture)
			{
				UnityEngine.Object.DestroyImmediate(m_ReflectionTexture);
			}
			m_ReflectionTexture = new RenderTexture(m_TextureResolution, m_TextureResolution, 16);
			m_ReflectionTexture.name = "__SurfaceReflection" + GetInstanceID();
			m_ReflectionTexture.isPowerOfTwo = true;
			m_ReflectionTexture.hideFlags = HideFlags.DontSave;
			m_OldReflectionTextureSize = m_TextureResolution;
		}
		reflectionCamera = m_ReflectionCameras[currentCamera] as Camera;
		if (!reflectionCamera)
		{
			GameObject gameObject = new GameObject("Surface Refl Camera id" + GetInstanceID() + " for " + currentCamera.GetInstanceID(), typeof(Camera), typeof(Skybox));
			reflectionCamera = gameObject.GetComponent<Camera>();
			reflectionCamera.enabled = false;
			reflectionCamera.transform.position = base.transform.position;
			reflectionCamera.transform.rotation = base.transform.rotation;
			reflectionCamera.gameObject.AddComponent<FlareLayer>();
			gameObject.hideFlags = HideFlags.HideAndDontSave;
			m_ReflectionCameras[currentCamera] = reflectionCamera;
		}
	}

	private static float sgn(float a)
	{
		if (a > 0f)
		{
			return 1f;
		}
		if (a < 0f)
		{
			return -1f;
		}
		return 0f;
	}

	private Vector4 CameraSpacePlane(Camera cam, Vector3 pos, Vector3 normal, float sideSign)
	{
		Vector3 point = pos + normal * m_finalClipPlaneOffset;
		Matrix4x4 worldToCameraMatrix = cam.worldToCameraMatrix;
		Vector3 lhs = worldToCameraMatrix.MultiplyPoint(point);
		Vector3 rhs = worldToCameraMatrix.MultiplyVector(normal).normalized * sideSign;
		return new Vector4(rhs.x, rhs.y, rhs.z, 0f - Vector3.Dot(lhs, rhs));
	}

	private static void CalculateObliqueMatrix(ref Matrix4x4 projection, Vector4 clipPlane)
	{
		Vector4 b = projection.inverse * new Vector4(sgn(clipPlane.x), sgn(clipPlane.y), 1f, 1f);
		Vector4 vector = clipPlane * (2f / Vector4.Dot(clipPlane, b));
		projection[2] = vector.x - projection[3];
		projection[6] = vector.y - projection[7];
		projection[10] = vector.z - projection[11];
		projection[14] = vector.w - projection[15];
	}

	private static void CalculateReflectionMatrix(ref Matrix4x4 reflectionMat, Vector4 plane)
	{
		reflectionMat.m00 = 1f - 2f * plane[0] * plane[0];
		reflectionMat.m01 = -2f * plane[0] * plane[1];
		reflectionMat.m02 = -2f * plane[0] * plane[2];
		reflectionMat.m03 = -2f * plane[3] * plane[0];
		reflectionMat.m10 = -2f * plane[1] * plane[0];
		reflectionMat.m11 = 1f - 2f * plane[1] * plane[1];
		reflectionMat.m12 = -2f * plane[1] * plane[2];
		reflectionMat.m13 = -2f * plane[3] * plane[1];
		reflectionMat.m20 = -2f * plane[2] * plane[0];
		reflectionMat.m21 = -2f * plane[2] * plane[1];
		reflectionMat.m22 = 1f - 2f * plane[2] * plane[2];
		reflectionMat.m23 = -2f * plane[3] * plane[2];
		reflectionMat.m30 = 0f;
		reflectionMat.m31 = 0f;
		reflectionMat.m32 = 0f;
		reflectionMat.m33 = 1f;
	}
}
public class RealtimeReflections : MonoBehaviour
{
	public int cubemapSize = 128;

	public float nearClip = 0.01f;

	public float farClip = 500f;

	public bool oneFacePerFrame;

	public Material[] materials;

	public ReflectionProbe[] reflectionProbes;

	public LayerMask layerMask = -1;

	private Camera cam;

	private RenderTexture renderTexture;

	private void OnEnable()
	{
		layerMask.value = -1;
	}

	private void Start()
	{
		ReflectionProbe[] array = reflectionProbes;
		foreach (ReflectionProbe obj in array)
		{
			obj.mode = ReflectionProbeMode.Realtime;
			obj.boxProjection = true;
			obj.resolution = cubemapSize;
			obj.transform.parent = base.transform.parent;
			obj.transform.localPosition = Vector3.zero;
		}
		if (materials.Length != 0)
		{
			UpdateCubemap(63);
		}
	}

	private void LateUpdate()
	{
		if (materials.Length != 0)
		{
			if (oneFacePerFrame)
			{
				int num = Time.frameCount % 6;
				int faceMask = 1 << num;
				UpdateCubemap(faceMask);
			}
			else
			{
				UpdateCubemap(63);
			}
		}
	}

	private void UpdateCubemap(int faceMask)
	{
		if (!cam)
		{
			GameObject gameObject = new GameObject("CubemapCamera", typeof(Camera));
			gameObject.hideFlags = HideFlags.HideAndDontSave;
			gameObject.transform.position = base.transform.position;
			gameObject.transform.rotation = Quaternion.identity;
			cam = gameObject.GetComponent<Camera>();
			cam.cullingMask = layerMask;
			cam.nearClipPlane = nearClip;
			cam.farClipPlane = farClip;
			cam.enabled = false;
		}
		if (!renderTexture)
		{
			renderTexture = new RenderTexture(cubemapSize, cubemapSize, 16);
			renderTexture.isPowerOfTwo = true;
			renderTexture.isCubemap = true;
			renderTexture.hideFlags = HideFlags.HideAndDontSave;
			Renderer[] componentsInChildren = GetComponentsInChildren<Renderer>();
			for (int i = 0; i < componentsInChildren.Length; i++)
			{
				Material[] sharedMaterials = componentsInChildren[i].sharedMaterials;
				foreach (Material material in sharedMaterials)
				{
					if (material.HasProperty("_Cube"))
					{
						material.SetTexture("_Cube", renderTexture);
					}
				}
			}
			ReflectionProbe[] array = reflectionProbes;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].customBakedTexture = renderTexture;
			}
		}
		cam.transform.position = base.transform.position;
		cam.RenderToCubemap(renderTexture, faceMask);
	}

	private void OnDisable()
	{
		UnityEngine.Object.DestroyImmediate(cam);
		UnityEngine.Object.DestroyImmediate(renderTexture);
	}
}
public class AcidCorpseSplash : MonoBehaviour
{
	public TriggerEnterEvent corpseDetector;

	[Space]
	public GameObject acidSplashPrefab;

	public GameObject acidSteamPrefab;

	public ParticleSystem sporeCloudPrefab;

	public ParticleSystem bubCloudPrefab;

	[Space]
	public AudioSource audioPlayerPefab;

	public AudioEvent splashSound;

	private void Start()
	{
		if ((bool)corpseDetector)
		{
			corpseDetector.OnTriggerEntered += delegate(Collider2D col, GameObject sender)
			{
				StartCoroutine(CorpseSplash(col.gameObject));
			};
		}
	}

	private IEnumerator CorpseSplash(GameObject corpseObject)
	{
		Corpse component = corpseObject.GetComponent<Corpse>();
		if (!component)
		{
			yield break;
		}
		component.Acid();
		Rigidbody2D body = corpseObject.GetComponent<Rigidbody2D>();
		splashSound.SpawnAndPlayOneShot(audioPlayerPefab, corpseObject.transform.position);
		Vector3 position = corpseObject.transform.position;
		if ((bool)corpseDetector)
		{
			BoxCollider2D component2 = corpseDetector.GetComponent<BoxCollider2D>();
			if ((bool)component2)
			{
				position.y = component2.bounds.max.y;
			}
		}
		if ((bool)acidSplashPrefab)
		{
			UnityEngine.Object.Instantiate(acidSplashPrefab, position + new Vector3(0f, 0f, -0.1f), acidSplashPrefab.transform.rotation);
		}
		if ((bool)acidSteamPrefab)
		{
			UnityEngine.Object.Instantiate(acidSteamPrefab, position, acidSteamPrefab.transform.rotation);
		}
		ParticleSystem acidBubble = null;
		if ((bool)bubCloudPrefab)
		{
			acidBubble = UnityEngine.Object.Instantiate(bubCloudPrefab, position, bubCloudPrefab.transform.rotation);
			if ((bool)acidBubble)
			{
				acidBubble.Play();
			}
		}
		ParticleSystem acidSpore = null;
		if ((bool)sporeCloudPrefab)
		{
			acidSpore = UnityEngine.Object.Instantiate(sporeCloudPrefab, position, sporeCloudPrefab.transform.rotation);
			if ((bool)acidSpore)
			{
				acidSpore.Play();
			}
		}
		for (float elapsed = 0f; elapsed <= 0.5f; elapsed += Time.fixedDeltaTime)
		{
			if ((bool)body)
			{
				body.velocity *= 0.1f;
			}
			yield return new WaitForFixedUpdate();
		}
		if ((bool)body)
		{
			body.isKinematic = true;
		}
		if ((bool)corpseObject)
		{
			tk2dSprite rend = corpseObject.GetComponent<tk2dSprite>();
			if ((bool)rend)
			{
				float elapsed = 0f;
				for (float fadeTime = 1f; elapsed <= fadeTime; elapsed += Time.deltaTime)
				{
					rend.color = Color.Lerp(Color.white, Color.clear, elapsed / fadeTime);
					yield return null;
				}
			}
		}
		if ((bool)acidBubble)
		{
			acidBubble.Stop();
		}
		if ((bool)acidSpore)
		{
			acidSpore.Stop();
		}
	}
}
