public class ChainSequence : SkippableSequence
{
	public delegate void TransitionedToNextSequenceDelegate();

	[SerializeField]
	private SkippableSequence[] sequences;

	private int currentSequenceIndex;

	private float fadeByController;

	private bool isSkipped;

	private SkippableSequence CurrentSequence
	{
		get
		{
			if (currentSequenceIndex < 0 || currentSequenceIndex >= sequences.Length)
			{
				return null;
			}
			return sequences[currentSequenceIndex];
		}
	}

	public bool IsCurrentSkipped
	{
		get
		{
			if (CurrentSequence != null)
			{
				return CurrentSequence.IsSkipped;
			}
			return false;
		}
	}

	public override bool IsSkipped => isSkipped;

	public override bool IsPlaying
	{
		get
		{
			if (currentSequenceIndex < sequences.Length - 1)
			{
				return true;
			}
			if (CurrentSequence == null)
			{
				return false;
			}
			return CurrentSequence.IsPlaying;
		}
	}

	public override float FadeByController
	{
		get
		{
			return fadeByController;
		}
		set
		{
			fadeByController = Mathf.Clamp01(value);
			for (int i = 0; i < sequences.Length; i++)
			{
				sequences[i].FadeByController = fadeByController;
			}
		}
	}

	public event TransitionedToNextSequenceDelegate TransitionedToNextSequence;

	protected void Awake()
	{
		fadeByController = 1f;
	}

	protected void Update()
	{
		if (CurrentSequence != null && !CurrentSequence.IsPlaying && !isSkipped)
		{
			Next();
		}
	}

	public override void Begin()
	{
		isSkipped = false;
		currentSequenceIndex = -1;
		Next();
	}

	private void Next()
	{
		SkippableSequence currentSequence = CurrentSequence;
		if (currentSequence != null)
		{
			currentSequence.gameObject.SetActive(value: false);
		}
		currentSequenceIndex++;
		if (!isSkipped)
		{
			if (CurrentSequence != null)
			{
				CurrentSequence.gameObject.SetActive(value: true);
				CurrentSequence.Begin();
			}
			if (TransitionedToNextSequence != null)
			{
				TransitionedToNextSequence();
			}
		}
	}

	public override void Skip()
	{
		isSkipped = true;
		for (int i = 0; i < sequences.Length; i++)
		{
			sequences[i].Skip();
		}
	}

	public void SkipSingle()
	{
		if (CurrentSequence != null)
		{
			CurrentSequence.Skip();
		}
	}
}
public class CheckpointSprite : MonoBehaviour
{
	private enum States
	{
		NotStarted,
		Starting,
		Looping,
		Ending
	}

	private Image image;

	private AudioSource audioSource;

	[SerializeField]
	private Sprite[] startSprites;

	[SerializeField]
	private Sprite[] loopSprites;

	[SerializeField]
	private Sprite[] endSprites;

	[SerializeField]
	private float framesPerSecond;

	private bool isShowing;

	private States state;

	private float frameTimer;

	protected void Awake()
	{
		image = GetComponent<Image>();
		audioSource = GetComponent<AudioSource>();
	}

	protected void OnEnable()
	{
		state = States.NotStarted;
		image.enabled = false;
		Update(0f);
	}

	protected void Start()
	{
	}

	public void Show()
	{
		isShowing = true;
		if (base.isActiveAndEnabled)
		{
			Update(0f);
		}
	}

	public void Hide()
	{
		isShowing = false;
	}

	protected void Update()
	{
		Update(Mathf.Min(1f / 60f, Time.unscaledDeltaTime));
	}

	private void Update(float deltaTime)
	{
		bool flag = false;
		frameTimer += deltaTime * framesPerSecond;
		if (state == States.NotStarted && isShowing)
		{
			frameTimer = 0f;
			state = States.Starting;
			audioSource.Play();
			image.enabled = true;
		}
		if (state == States.Starting)
		{
			int num = (int)frameTimer;
			if (num < startSprites.Length)
			{
				image.sprite = startSprites[num];
			}
			else
			{
				frameTimer -= startSprites.Length;
				if (isShowing | flag)
				{
					state = States.Looping;
				}
				else
				{
					state = States.Ending;
				}
			}
		}
		if (state == States.Looping)
		{
			int num2 = (int)frameTimer;
			if (num2 >= loopSprites.Length)
			{
				frameTimer -= loopSprites.Length * (num2 / loopSprites.Length);
				if (!isShowing && !flag)
				{
					state = States.Ending;
				}
				else
				{
					image.sprite = loopSprites[num2 % loopSprites.Length];
				}
			}
			else
			{
				image.sprite = loopSprites[num2];
			}
		}
		if (state == States.Ending)
		{
			int num3 = (int)frameTimer;
			if (num3 < endSprites.Length)
			{
				image.sprite = endSprites[num3];
				return;
			}
			image.enabled = false;
			state = States.NotStarted;
		}
	}
}
[RequireComponent(typeof(AudioSource))]
[RequireComponent(typeof(MeshRenderer))]
public class CinematicPlayer : MonoBehaviour
{
	public enum MovieTrigger
	{
		ON_START,
		MANUAL_TRIGGER
	}

	public enum FadeInSpeed
	{
		NORMAL,
		SLOW,
		NONE
	}

	public enum FadeOutSpeed
	{
		NORMAL,
		SLOW,
		NONE
	}

	public enum VideoType
	{
		OpeningCutscene,
		StagTravel,
		InGameVideo,
		OpeningPrologue,
		EndingA,
		EndingB,
		EndingC,
		EndingGG
	}

	[SerializeField]
	private CinematicVideoReference videoClip;

	private CinematicVideoPlayer cinematicVideoPlayer;

	[SerializeField]
	private AudioSource additionalAudio;

	[SerializeField]
	private bool additionalAudioContinuesPastVideo;

	[SerializeField]
	private MeshRenderer selfBlanker;

	[Header("Cinematic Settings")]
	[UnityEngine.Tooltip("Determines what will trigger the video playing.")]
	public MovieTrigger playTrigger;

	[UnityEngine.Tooltip("The speed of the fade in, comes in different flavours.")]
	public FadeInSpeed fadeInSpeed;

	[UnityEngine.Tooltip("The amount of time to wait before fading in the camera. Camera will stay black and the video will play.")]
	[Range(0f, 10f)]
	public float delayBeforeFadeIn;

	[UnityEngine.Tooltip("Allows the player to skip the video.")]
	public SkipPromptMode skipMode;

	[UnityEngine.Tooltip("Prevents the skip action from taking place until the lock is released. Useful for animators delaying skip feature.")]
	public bool startSkipLocked;

	[UnityEngine.Tooltip("The speed of the fade in, comes in different flavours.")]
	public FadeOutSpeed fadeOutSpeed;

	[UnityEngine.Tooltip("Video keeps looping until the player is explicitly told to stop.")]
	public bool loopVideo;

	[Space(6f)]
	[UnityEngine.Tooltip("The name of the scene to load when the video ends. Leaving this blank will load the \"next scene\" as set in PlayerData.")]
	public VideoType videoType;

	public CinematicVideoFaderStyles faderStyle;

	private AudioSource audioSource;

	private MeshRenderer myRenderer;

	private GameManager gm;

	private UIManager ui;

	private PlayerData pd;

	private PlayMakerFSM cameraFSM;

	private bool videoTriggered;

	private bool loadingLevel;

	[SerializeField]
	private AudioMixerSnapshot masterOff;

	[SerializeField]
	private AudioMixerSnapshot masterResume;

	private void Awake()
	{
		audioSource = GetComponent<AudioSource>();
		myRenderer = GetComponent<MeshRenderer>();
		if (videoType == VideoType.InGameVideo)
		{
			myRenderer.enabled = false;
		}
	}

	protected void OnDestroy()
	{
		if (cinematicVideoPlayer != null)
		{
			cinematicVideoPlayer.Dispose();
			cinematicVideoPlayer = null;
		}
	}

	private void Start()
	{
		gm = GameManager.instance;
		ui = UIManager.instance;
		pd = PlayerData.instance;
		if (startSkipLocked)
		{
			gm.inputHandler.SetSkipMode(SkipPromptMode.NOT_SKIPPABLE);
		}
		else
		{
			gm.inputHandler.SetSkipMode(skipMode);
		}
		if (playTrigger == MovieTrigger.ON_START)
		{
			StartCoroutine(StartVideo());
		}
	}

	private void Update()
	{
		if (cinematicVideoPlayer != null)
		{
			cinematicVideoPlayer.Update();
		}
		if (Time.frameCount % 10 == 0)
		{
			Update10();
		}
	}

	private void Update10()
	{
		if ((cinematicVideoPlayer == null || (!cinematicVideoPlayer.IsLoading && !cinematicVideoPlayer.IsPlaying)) && !loadingLevel && videoTriggered)
		{
			if (videoType == VideoType.InGameVideo)
			{
				FinishInGameVideo();
			}
			else
			{
				FinishVideo();
			}
		}
	}

	public IEnumerator SkipVideo()
	{
		if (!videoTriggered)
		{
			yield break;
		}
		if (videoType == VideoType.InGameVideo)
		{
			if (fadeOutSpeed != FadeOutSpeed.NONE)
			{
				float duration = 0f;
				if (fadeOutSpeed == FadeOutSpeed.NORMAL)
				{
					duration = 0.5f;
				}
				else if (fadeOutSpeed == FadeOutSpeed.SLOW)
				{
					duration = 2.3f;
				}
				selfBlanker.enabled = true;
				float timer = 0f;
				while (videoTriggered && timer < duration)
				{
					float a = Mathf.Clamp01(timer / duration);
					selfBlanker.material.color = new Color(0f, 0f, 0f, a);
					yield return null;
					timer += Time.unscaledDeltaTime;
				}
			}
			else
			{
				yield return null;
			}
		}
		else if (fadeOutSpeed == FadeOutSpeed.NORMAL)
		{
			PlayMakerFSM.BroadcastEvent("JUST FADE");
			yield return new WaitForSeconds(0.5f);
		}
		else if (fadeOutSpeed == FadeOutSpeed.SLOW)
		{
			PlayMakerFSM.BroadcastEvent("START FADE");
			yield return new WaitForSeconds(2.3f);
		}
		else
		{
			yield return null;
		}
		if (cinematicVideoPlayer != null)
		{
			cinematicVideoPlayer.Stop();
		}
	}

	public void TriggerStartVideo()
	{
		StartCoroutine(StartVideo());
	}

	public void TriggerStopVideo()
	{
		if (videoType == VideoType.InGameVideo)
		{
			StartCoroutine(SkipVideo());
		}
	}

	public void UnlockSkip()
	{
		gm.inputHandler.SetSkipMode(skipMode);
	}

	private IEnumerator StartVideo()
	{
		if (masterOff != null)
		{
			masterOff.TransitionTo(0f);
		}
		videoTriggered = true;
		if (videoType == VideoType.InGameVideo)
		{
			gm.gameState = GameState.CUTSCENE;
			if (cinematicVideoPlayer == null)
			{
				UnityEngine.Debug.LogFormat("Creating new CinematicVideoPlayer for in game video");
				cinematicVideoPlayer = CinematicVideoPlayer.Create(new CinematicVideoPlayerConfig(videoClip, myRenderer, audioSource, faderStyle, GameManager.instance.GetImplicitCinematicVolume()));
			}
			UnityEngine.Debug.LogFormat("Waiting for CinematicVideoPlayer in game video load...");
			while (cinematicVideoPlayer != null && cinematicVideoPlayer.IsLoading)
			{
				yield return null;
			}
			UnityEngine.Debug.LogFormat("Starting cinematic video player in game video.");
			if (cinematicVideoPlayer != null)
			{
				cinematicVideoPlayer.IsLooping = loopVideo;
				cinematicVideoPlayer.Play();
				myRenderer.enabled = true;
			}
			if (additionalAudio != null)
			{
				additionalAudio.Play();
			}
			yield return new WaitForSeconds(delayBeforeFadeIn);
			if (fadeInSpeed == FadeInSpeed.SLOW)
			{
				GameCameras.instance.cameraFadeFSM.Fsm.Event("FADE SCENE IN SLOWLY");
			}
			else if (fadeInSpeed == FadeInSpeed.NORMAL)
			{
				GameCameras.instance.cameraFadeFSM.Fsm.Event("FADE SCENE IN");
			}
		}
		else if (videoType == VideoType.StagTravel)
		{
			GameCameras.instance.DisableImageEffects();
			if (cinematicVideoPlayer == null)
			{
				cinematicVideoPlayer = CinematicVideoPlayer.Create(new CinematicVideoPlayerConfig(videoClip, myRenderer, audioSource, faderStyle, GameManager.instance.GetImplicitCinematicVolume()));
			}
			while (cinematicVideoPlayer != null && cinematicVideoPlayer.IsLoading)
			{
				yield return null;
			}
			if (cinematicVideoPlayer != null)
			{
				cinematicVideoPlayer.IsLooping = loopVideo;
				cinematicVideoPlayer.Play();
				myRenderer.enabled = true;
			}
			yield return new WaitForSeconds(delayBeforeFadeIn);
			if (fadeInSpeed == FadeInSpeed.SLOW)
			{
				GameCameras.instance.cameraFadeFSM.Fsm.Event("FADE SCENE IN SLOWLY");
			}
			else if (fadeInSpeed == FadeInSpeed.NORMAL)
			{
				GameCameras.instance.cameraFadeFSM.Fsm.Event("FADE SCENE IN");
			}
			StartCoroutine(WaitForStagFadeOut());
			pd.SetBoolSwappedArgs(value: true, "disablePause");
		}
		else
		{
			GameCameras.instance.DisableImageEffects();
			if (cinematicVideoPlayer == null)
			{
				cinematicVideoPlayer = CinematicVideoPlayer.Create(new CinematicVideoPlayerConfig(videoClip, myRenderer, audioSource, faderStyle, GameManager.instance.GetImplicitCinematicVolume()));
			}
			while (cinematicVideoPlayer != null && cinematicVideoPlayer.IsLoading)
			{
				yield return null;
			}
			if (cinematicVideoPlayer != null)
			{
				cinematicVideoPlayer.IsLooping = loopVideo;
				cinematicVideoPlayer.Play();
				myRenderer.enabled = true;
			}
			yield return new WaitForSeconds(delayBeforeFadeIn);
			if (fadeInSpeed == FadeInSpeed.SLOW)
			{
				GameCameras.instance.cameraFadeFSM.Fsm.Event("FADE SCENE IN SLOWLY");
			}
			else if (fadeInSpeed == FadeInSpeed.NORMAL)
			{
				GameCameras.instance.cameraFadeFSM.Fsm.Event("FADE SCENE IN");
			}
		}
	}

	private void FinishVideo()
	{
		GameCameras.instance.EnableImageEffects(gm.IsGameplayScene(), isBloomForced: false);
		videoTriggered = false;
		if (videoType == VideoType.OpeningCutscene)
		{
			GameCameras.instance.cameraFadeFSM.Fsm.Event("JUST FADE");
			ui.SetState(UIState.INACTIVE);
			loadingLevel = true;
			StartCoroutine(gm.LoadFirstScene());
		}
		else if (videoType == VideoType.OpeningPrologue)
		{
			GameCameras.instance.cameraFadeFSM.Fsm.Event("JUST FADE");
			ui.SetState(UIState.INACTIVE);
			loadingLevel = true;
			gm.LoadOpeningCinematic();
		}
		else if (videoType == VideoType.EndingA || videoType == VideoType.EndingB || videoType == VideoType.EndingC)
		{
			GameCameras.instance.cameraFadeFSM.Fsm.Event("JUST FADE");
			ui.SetState(UIState.INACTIVE);
			loadingLevel = true;
			gm.LoadScene("End_Credits");
		}
		else if (videoType == VideoType.StagTravel)
		{
			ui.SetState(UIState.INACTIVE);
			loadingLevel = true;
			gm.ChangeToScene(pd.GetString("nextScene"), "door_stagExit", 0f);
		}
		else if (videoType == VideoType.EndingGG)
		{
			GameCameras.instance.cameraFadeFSM.Fsm.Event("JUST FADE");
			ui.SetState(UIState.INACTIVE);
			loadingLevel = true;
			if (gm.playerData.GetBool("bossRushMode"))
			{
				gm.LoadScene("GG_End_Sequence");
			}
			else
			{
				gm.LoadScene("End_Credits");
			}
		}
	}

	private void FinishInGameVideo()
	{
		UnityEngine.Debug.LogFormat("Finishing in-game video.");
		PlayMakerFSM.BroadcastEvent("CINEMATIC END");
		GameCameras.instance.EnableImageEffects(gm.IsGameplayScene(), isBloomForced: false);
		myRenderer.enabled = false;
		selfBlanker.enabled = false;
		if (masterResume != null)
		{
			masterResume.TransitionTo(0f);
		}
		if (!additionalAudioContinuesPastVideo && additionalAudio != null)
		{
			additionalAudio.Stop();
		}
		if (cinematicVideoPlayer != null)
		{
			cinematicVideoPlayer.Stop();
			cinematicVideoPlayer.Dispose();
			cinematicVideoPlayer = null;
		}
		videoTriggered = false;
		gm.gameState = GameState.PLAYING;
	}

	private IEnumerator WaitForStagFadeOut()
	{
		yield return new WaitForSeconds(2.6f);
		GameCameras.instance.cameraFadeFSM.Fsm.Event("JUST FADE");
	}
}
[RequireComponent(typeof(AudioSource))]
public class CinematicSequence : SkippableSequence
{
	private AudioSource audioSource;

	[SerializeField]
	private AudioMixerSnapshot atmosSnapshot;

	[SerializeField]
	private float atmosSnapshotTransitionDuration;

	[SerializeField]
	private CinematicVideoReference videoReference;

	[SerializeField]
	private bool isLooping;

	[SerializeField]
	private MeshRenderer targetRenderer;

	[SerializeField]
	private MeshRenderer blankerRenderer;

	private CinematicVideoPlayer videoPlayer;

	private bool didPlay;

	private bool isSkipped;

	private int framesSinceBegan;

	private float fadeByController;

	public CinematicVideoPlayer VideoPlayer => videoPlayer;

	public override bool IsSkipped => isSkipped;

	public bool IsLooping
	{
		get
		{
			if (videoPlayer != null)
			{
				return videoPlayer.IsLooping;
			}
			return isLooping;
		}
		set
		{
			if (videoPlayer != null)
			{
				videoPlayer.IsLooping = value;
			}
			isLooping = value;
		}
	}

	public override bool IsPlaying
	{
		get
		{
			bool flag = framesSinceBegan < 10 || !didPlay;
			if (!isSkipped)
			{
				if (!flag)
				{
					if (videoPlayer != null)
					{
						return videoPlayer.IsPlaying;
					}
					return false;
				}
				return true;
			}
			return false;
		}
	}

	public override float FadeByController
	{
		get
		{
			return fadeByController;
		}
		set
		{
			fadeByController = value;
			if (videoPlayer != null)
			{
				videoPlayer.Volume = fadeByController;
			}
			UpdateBlanker(1f - fadeByController);
		}
	}

	protected void Awake()
	{
		audioSource = GetComponent<AudioSource>();
		fadeByController = 1f;
	}

	protected void OnDestroy()
	{
		if (videoPlayer != null)
		{
			videoPlayer.Dispose();
			videoPlayer = null;
		}
	}

	protected void Update()
	{
		if (videoPlayer == null)
		{
			return;
		}
		framesSinceBegan++;
		videoPlayer.Update();
		if (!videoPlayer.IsLoading && !didPlay)
		{
			didPlay = true;
			if (atmosSnapshot != null)
			{
				atmosSnapshot.TransitionTo(atmosSnapshotTransitionDuration);
			}
			UnityEngine.Debug.LogFormat(this, "Started cinematic '{0}'", videoReference.name);
			videoPlayer.Play();
		}
		if (!videoPlayer.IsPlaying && !videoPlayer.IsLoading && framesSinceBegan >= 10)
		{
			UnityEngine.Debug.LogFormat(this, "Stopped cinematic '{0}'", videoReference.name);
			videoPlayer.Dispose();
			videoPlayer = null;
			targetRenderer.enabled = false;
		}
		else if (isSkipped)
		{
			UnityEngine.Debug.LogFormat(this, "Skipped cinematic '{0}'", videoReference.name);
			videoPlayer.Stop();
		}
	}

	public override void Begin()
	{
		if (videoPlayer != null && videoPlayer.IsPlaying)
		{
			UnityEngine.Debug.LogErrorFormat(this, "Can't play a cinematic sequence that is already playing");
			return;
		}
		if (videoPlayer != null)
		{
			videoPlayer.Dispose();
			videoPlayer = null;
			targetRenderer.enabled = false;
		}
		targetRenderer.enabled = true;
		videoPlayer = CinematicVideoPlayer.Create(new CinematicVideoPlayerConfig(videoReference, targetRenderer, audioSource, CinematicVideoFaderStyles.Black, GameManager.instance.GetImplicitCinematicVolume()));
		videoPlayer.IsLooping = isLooping;
		videoPlayer.Volume = fadeByController;
		isSkipped = false;
		framesSinceBegan = 0;
		UpdateBlanker(1f - fadeByController);
		UnityEngine.Debug.LogFormat(this, "Started cinematic '{0}'", videoReference.name);
	}

	private void UpdateBlanker(float alpha)
	{
		if (alpha > Mathf.Epsilon)
		{
			if (!blankerRenderer.enabled)
			{
				blankerRenderer.enabled = true;
			}
			blankerRenderer.material.color = new Color(0f, 0f, 0f, alpha);
		}
		else if (blankerRenderer.enabled)
		{
			blankerRenderer.enabled = false;
		}
	}

	public override void Skip()
	{
		isSkipped = true;
	}
}
public enum CinematicVideoFaderStyles
{
	Black,
	White
}
public enum CinematicFormats
{
	MP4_H264_720_60_AAC_48000,
	MP4_H264_1080_Any_AAC_48000,
	WEBM_VP8_1080_Any_Vorbis_48000
}
public static class CinematicFormatUtils
{
	public static string GetExtension(CinematicFormats format)
	{
		switch (format)
		{
		case CinematicFormats.MP4_H264_720_60_AAC_48000:
		case CinematicFormats.MP4_H264_1080_Any_AAC_48000:
			return ".mp4";
		case CinematicFormats.WEBM_VP8_1080_Any_Vorbis_48000:
			return ".webm";
		default:
			return "";
		}
	}
}
