public class SpriteFadeMaterial : MonoBehaviour
{
	public Material initialMaterial;

	public float fadeBackDuration = 1f;

	private SpriteRenderer[] sprites;

	private Coroutine fadeRoutine;

	private Action onFadeEnd;

	private void Awake()
	{
		sprites = GetComponentsInChildren<SpriteRenderer>();
	}

	private void Start()
	{
		SpriteRenderer[] array = sprites;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].sharedMaterial = initialMaterial;
		}
	}

	public void FadeBack()
	{
		if (fadeRoutine != null)
		{
			StopCoroutine(fadeRoutine);
		}
		if (onFadeEnd != null)
		{
			onFadeEnd();
			onFadeEnd = null;
		}
		fadeRoutine = StartCoroutine(FadeBackRoutine());
	}

	private IEnumerator FadeBackRoutine()
	{
		SpriteRenderer[] newSprites = new SpriteRenderer[sprites.Length];
		for (int i = 0; i < newSprites.Length; i++)
		{
			newSprites[i] = UnityEngine.Object.Instantiate(sprites[i], sprites[i].transform.parent);
			newSprites[i].transform.Translate(new Vector3(0f, 0f, -0.001f), Space.World);
			newSprites[i].gameObject.name = sprites[i].gameObject.name;
			newSprites[i].sharedMaterial = initialMaterial;
			newSprites[i].color = Color.clear;
		}
		onFadeEnd = delegate
		{
			SpriteRenderer[] array2 = newSprites;
			for (int j = 0; j < array2.Length; j++)
			{
				array2[j].color = Color.white;
			}
			for (int k = 0; k < sprites.Length; k++)
			{
				UnityEngine.Object.DestroyImmediate(sprites[k].gameObject);
			}
			Animator component = GetComponent<Animator>();
			if ((bool)component)
			{
				component.Rebind();
			}
			sprites = newSprites;
		};
		for (float elapsed = 0f; elapsed <= fadeBackDuration; elapsed += Time.deltaTime)
		{
			SpriteRenderer[] array = newSprites;
			for (int num = 0; num < array.Length; num++)
			{
				array[num].color = Color.Lerp(Color.clear, Color.white, elapsed / fadeBackDuration);
			}
			yield return null;
		}
		if (onFadeEnd != null)
		{
			onFadeEnd();
			onFadeEnd = null;
		}
		fadeRoutine = null;
	}
}
public class SpriteFlash : MonoBehaviour
{
	private Renderer rend;

	private Color flashColour;

	private float amount;

	private float timeUp;

	private float stayTime;

	private float timeDown;

	private int flashingState;

	private float flashTimer;

	private float amountCurrent;

	private float t;

	private bool repeatFlash;

	private bool cancelFlash;

	private float geoTimer;

	private bool geoFlash;

	private MaterialPropertyBlock block;

	private bool sendToChildren = true;

	private void Start()
	{
		if (rend == null)
		{
			rend = GetComponent<Renderer>();
		}
		if (block == null)
		{
			block = new MaterialPropertyBlock();
		}
	}

	private void OnDisable()
	{
		if (rend == null)
		{
			rend = GetComponent<Renderer>();
		}
		if (block == null)
		{
			block = new MaterialPropertyBlock();
		}
		block.SetFloat("_FlashAmount", 0f);
		rend.SetPropertyBlock(block);
		flashTimer = 0f;
		flashingState = 0;
		repeatFlash = false;
		cancelFlash = false;
		geoFlash = false;
	}

	private void Update()
	{
		if (cancelFlash)
		{
			block.SetFloat("_FlashAmount", 0f);
			rend.SetPropertyBlock(block);
			flashingState = 0;
			cancelFlash = false;
		}
		if (flashingState == 1)
		{
			if (flashTimer < timeUp)
			{
				flashTimer += Time.deltaTime;
				t = flashTimer / timeUp;
				amountCurrent = Mathf.Lerp(0f, amount, t);
				block.SetFloat("_FlashAmount", amountCurrent);
				rend.SetPropertyBlock(block);
			}
			else
			{
				block.SetFloat("_FlashAmount", amount);
				rend.SetPropertyBlock(block);
				flashTimer = 0f;
				flashingState = 2;
			}
		}
		if (flashingState == 2)
		{
			if (flashTimer < stayTime)
			{
				flashTimer += Time.deltaTime;
			}
			else
			{
				flashTimer = 0f;
				flashingState = 3;
			}
		}
		if (flashingState == 3)
		{
			if (flashTimer < timeDown)
			{
				flashTimer += Time.deltaTime;
				t = flashTimer / timeDown;
				amountCurrent = Mathf.Lerp(amount, 0f, t);
				block.SetFloat("_FlashAmount", amountCurrent);
				rend.SetPropertyBlock(block);
			}
			else
			{
				block.SetFloat("_FlashAmount", 0f);
				rend.SetPropertyBlock(block);
				flashTimer = 0f;
				if (repeatFlash)
				{
					flashingState = 1;
				}
				else
				{
					flashingState = 0;
				}
			}
		}
		if (geoFlash)
		{
			if (geoTimer > 0f)
			{
				geoTimer -= Time.deltaTime;
				return;
			}
			FlashingSuperDash();
			geoFlash = false;
		}
	}

	public void GeoFlash()
	{
		geoFlash = true;
		geoTimer = 0.25f;
	}

	public void flash(Color flashColour_var, float amount_var, float timeUp_var, float stayTime_var, float timeDown_var)
	{
		flashColour = flashColour_var;
		amount = amount_var;
		timeUp = timeUp_var;
		stayTime = stayTime_var;
		timeDown = timeDown_var;
		block.Clear();
		block.SetColor("_FlashColor", flashColour);
		flashingState = 1;
		flashTimer = 0f;
		repeatFlash = false;
	}

	public void CancelFlash()
	{
		cancelFlash = true;
	}

	public void FlashingSuperDash()
	{
		flashColour = new Color(1f, 1f, 1f);
		amount = 0.7f;
		timeUp = 0.1f;
		stayTime = 0.01f;
		timeDown = 0.1f;
		block.Clear();
		block.SetColor("_FlashColor", flashColour);
		flashingState = 1;
		flashTimer = 0f;
		repeatFlash = true;
		SendToChildren(FlashingSuperDash);
	}

	public void FlashingGhostWounded()
