	private void SendToChildren(Action function)
	{
		if (!sendToChildren)
		{
			return;
		}
		SpriteFlash[] componentsInChildren = GetComponentsInChildren<SpriteFlash>();
		foreach (SpriteFlash spriteFlash in componentsInChildren)
		{
			if (!(spriteFlash == this))
			{
				spriteFlash.sendToChildren = false;
				spriteFlash.GetType().GetMethod(function.Method.Name).Invoke(spriteFlash, null);
			}
		}
	}
}
public class StagTravel : MonoBehaviour
{
	private class StagTravelAsyncLoadInfo : GameManager.SceneLoadInfo
	{
		private StagTravel stagTravel;

		public StagTravelAsyncLoadInfo(StagTravel stagTravel)
		{
			this.stagTravel = stagTravel;
		}

		public override void NotifyFetchComplete()
		{
			base.NotifyFetchComplete();
			stagTravel.NotifyFetchComplete();
		}

		public override bool IsReadyToActivate()
		{
			if (base.IsReadyToActivate())
			{
				return stagTravel.IsReadyToActivate;
			}
			return false;
		}

		public override void NotifyFinished()
		{
			base.NotifyFinished();
			GameCameras.instance.cameraFadeFSM.Fsm.Event("FADE SCENE OUT INSTANT");
			GameCameras.instance.EnableImageEffects(isGameplayLevel: true, isBloomForced: false);
		}
	}

	[SerializeField]
	private CinematicSequence cinematicSequence;

	[SerializeField]
	private float minimumDuration;

	[SerializeField]
	private float fadeRate;

	private bool isAsync;

	private float currentDuration;

	private bool isFetchComplete;

	private bool isReadyToActivate;

	private bool isSkipping;

	private bool isSkipFadeComplete;

	protected bool IsReadyToActivate => isReadyToActivate;

	protected IEnumerator Start()
	{
		isAsync = Platform.Current.FetchScenesBeforeFade;
		GameCameras.instance.DisableImageEffects();
		if (!isAsync)
		{
			GameCameras.instance.cameraFadeFSM.Fsm.Event("FADE SCENE IN");
			GameManager.instance.inputHandler.SetSkipMode(SkipPromptMode.SKIP_INSTANT);
			cinematicSequence.IsLooping = false;
			cinematicSequence.Begin();
			while (cinematicSequence.IsPlaying && !isSkipFadeComplete && cinematicSequence.VideoPlayer != null && cinematicSequence.VideoPlayer.CurrentTime < 3.9f)
			{
				yield return null;
			}
			GameCameras.instance.cameraFadeFSM.Fsm.Event("FADE OUT INSTANT");
			yield return null;
			GameManager.instance.BeginSceneTransition(new GameManager.SceneLoadInfo
			{
				EntryGateName = "door_stagExit",
				SceneName = GameManager.instance.playerData.GetString("nextScene"),
				PreventCameraFadeOut = true,
				Visualization = GameManager.SceneLoadVisualizations.Custom
			});
			isReadyToActivate = true;
		}
		else
		{
			StartCoroutine("FadeInRoutine");
			cinematicSequence.IsLooping = true;
			cinematicSequence.Begin();
			GameManager.instance.BeginSceneTransition(new StagTravelAsyncLoadInfo(this)
			{
				EntryGateName = "door_stagExit",
				SceneName = GameManager.instance.playerData.GetString("nextScene"),
				PreventCameraFadeOut = true,
				Visualization = GameManager.SceneLoadVisualizations.Custom
			});
		}
	}

	private IEnumerator FadeInRoutine()
	{
		GameCameras.instance.cameraFadeFSM.Fsm.Event("FADE OUT INSTANT");
		yield return new WaitForSeconds(1.5f);
		GameCameras.instance.cameraFadeFSM.Fsm.Event("FADE SCENE IN");
	}

	protected void Update()
	{
		currentDuration += Time.unscaledDeltaTime;
		if (isAsync && !isSkipping && isFetchComplete && currentDuration > minimumDuration)
		{
			StartCoroutine(Skip());
		}
	}

	protected void NotifyFetchComplete()
	{
		isFetchComplete = true;
	}

	public IEnumerator Skip()
	{
		if (!isSkipping)
		{
			StopCoroutine("FadeInRoutine");
			isSkipping = true;
			GameCameras.instance.cameraFadeFSM.Fsm.Event("FADE OUT");
			yield return new WaitForSecondsRealtime(0.5f);
			isSkipFadeComplete = true;
			isReadyToActivate = true;
		}
	}
}
[RequireComponent(typeof(Animator))]
public class StopAnimatorsAtPoint : MonoBehaviour
{
	public EventRegister stopEvent;

	public EventRegister stopInstantEvent;

	private bool canStop;

	private bool shouldStop;

	public float stopInstantHeight = 1.75f;

	private Animator animator;

	private void Awake()
	{
		animator = GetComponent<Animator>();
	}

	private void Start()
	{
		if ((bool)stopEvent)
		{
			stopEvent.OnReceivedEvent += delegate
			{
				shouldStop = true;
				animator.cullingMode = AnimatorCullingMode.AlwaysAnimate;
			};
		}
		if ((bool)stopInstantEvent)
		{
			stopInstantEvent.OnReceivedEvent += delegate
			{
				animator.enabled = false;
				Vector3 localPosition = base.transform.localPosition;
				localPosition.y = stopInstantHeight;
				base.transform.localPosition = localPosition;
			};
		}
	}

	public void SetCanStop()
	{
		canStop = true;
	}

	public void SetCannotStop()
	{
		canStop = false;
	}

	private void Update()
	{
		if (shouldStop && canStop && animator.enabled)
		{
			animator.enabled = false;
			canStop = false;
			shouldStop = false;
		}
	}
}
public class TinkEffect : MonoBehaviour
{
	public GameObject blockEffect;

	public bool useNailPosition;

	public bool sendFSMEvent;

	public string FSMEvent;

	public PlayMakerFSM fsm;

	public bool sendDirectionalFSMEvents;

	private BoxCollider2D boxCollider;

	private bool hasBoxCollider;

	private HeroController heroController;

	private GameCameras gameCam;

	private Vector2 centre;

	private float halfWidth;

	private float halfHeight;

	private const float repeatDelay = 0.25f;

	private float nextTinkTime;

	private void Awake()
	{
		boxCollider = base.gameObject.GetComponent<BoxCollider2D>();
	}

	private void Start()
	{
		gameCam = GameCameras.instance;
	}

	private void OnTriggerEnter2D(Collider2D collision)
	{
		if (!(collision.tag == "Nail Attack") || Time.time < nextTinkTime)
		{
			return;
		}
		nextTinkTime = Time.time + 0.25f;
		PlayMakerFSM playMakerFSM = PlayMakerFSM.FindFsmOnGameObject(collision.gameObject, "damages_enemy");
		float degrees = ((playMakerFSM != null) ? playMakerFSM.FsmVariables.FindFsmFloat("direction").Value : 0f);
		if ((bool)gameCam)
		{
			gameCam.cameraShakeFSM.SendEvent("EnemyKillShake");
		}
		Vector3 vector = new Vector3(0f, 0f, 0f);
		Vector3 euler = new Vector3(0f, 0f, 0f);
		Vector3 position = HeroController.instance.transform.position;
		Vector3 position2 = collision.gameObject.transform.position;
		bool flag = boxCollider != null;
		if (useNailPosition)
		{
			flag = false;
		}
		Vector2 vector2 = Vector2.zero;
		float num = 0f;
		float num2 = 0f;
		if (flag)
		{
			vector2 = base.transform.TransformPoint(boxCollider.offset);
			num = boxCollider.bounds.size.x * 0.5f;
			num2 = boxCollider.bounds.size.y * 0.5f;
		}
		switch (DirectionUtils.GetCardinalDirection(degrees))
		{
		case 0:
			HeroController.instance.RecoilLeft();
			if (sendDirectionalFSMEvents)
			{
				fsm.SendEvent("TINK RIGHT");
			}
			vector = ((!flag) ? new Vector3(position.x + 2f, position.y, 0.002f) : new Vector3(vector2.x - num, position2.y, 0.002f));
			break;
		case 1:
			HeroController.instance.RecoilDown();
			if (sendDirectionalFSMEvents)
			{
				fsm.SendEvent("TINK UP");
			}
			vector = ((!flag) ? new Vector3(position.x, position.y + 2f, 0.002f) : new Vector3(position2.x, Mathf.Max(vector2.y - num2, position2.y), 0.002f));
			euler = new Vector3(0f, 0f, 90f);
			break;
		case 2:
			HeroController.instance.RecoilRight();
			if (sendDirectionalFSMEvents)
			{
				fsm.SendEvent("TINK LEFT");
			}
			vector = ((!flag) ? new Vector3(position.x - 2f, position.y, 0.002f) : new Vector3(vector2.x + num, position2.y, 0.002f));
			euler = new Vector3(0f, 0f, 180f);
			break;
		default:
			if (sendDirectionalFSMEvents)
			{
				fsm.SendEvent("TINK DOWN");
			}
			vector = ((!flag) ? new Vector3(position.x, position.y - 2f, 0.002f) : new Vector3(position2.x, Mathf.Min(vector2.y + num2, position2.y), 0.002f));
			euler = new Vector3(0f, 0f, 270f);
			break;
		}
		blockEffect.Spawn(vector, Quaternion.Euler(euler)).GetComponent<AudioSource>().pitch = UnityEngine.Random.Range(0.85f, 1.15f);
		if (sendFSMEvent)
		{
			fsm.SendEvent(FSMEvent);
		}
	}
}
public class XB1CinematicVideoPlayer : CinematicVideoPlayer
{
	private VideoPlayer videoPlayer;

	private Texture originalMainTexture;

	private RenderTexture renderTexture;

	private const string TexturePropertyName = "_MainTex";

	private bool isPlayEnqueued;

	public override float Volume
	{
		get
		{
			if (base.Config.AudioSource != null)
			{
				return base.Config.AudioSource.volume;
			}
			return 1f;
		}
		set
		{
			if (base.Config.AudioSource != null)
			{
				base.Config.AudioSource.volume = value;
			}
		}
	}

	public override bool IsLoading => false;

	public override bool IsLooping
	{
		get
		{
			if (videoPlayer != null)
			{
				return videoPlayer.isLooping;
			}
			return false;
		}
		set
		{
			if (videoPlayer != null)
			{
				videoPlayer.isLooping = value;
			}
		}
	}

	public override bool IsPlaying
	{
		get
		{
			if (videoPlayer != null && videoPlayer.isPrepared)
			{
				return videoPlayer.isPlaying;
			}
			return isPlayEnqueued;
		}
	}

	public XB1CinematicVideoPlayer(CinematicVideoPlayerConfig config)
		: base(config)
	{
		originalMainTexture = config.MeshRenderer.material.GetTexture("_MainTex");
		renderTexture = new RenderTexture(Screen.width, Screen.height, 0);
		Graphics.Blit((config.FaderStyle == CinematicVideoFaderStyles.White) ? Texture2D.whiteTexture : Texture2D.blackTexture, renderTexture);
		videoPlayer = config.MeshRenderer.gameObject.AddComponent<VideoPlayer>();
		videoPlayer.playOnAwake = false;
		videoPlayer.audioOutputMode = VideoAudioOutputMode.AudioSource;
		videoPlayer.SetTargetAudioSource(0, config.AudioSource);
		videoPlayer.renderMode = VideoRenderMode.RenderTexture;
		videoPlayer.targetTexture = renderTexture;
		config.MeshRenderer.material.SetTexture("_MainTex", renderTexture);
		VideoClip embeddedVideoClip = config.VideoReference.EmbeddedVideoClip;
		videoPlayer.clip = embeddedVideoClip;
		videoPlayer.prepareCompleted += OnPrepareCompleted;
		videoPlayer.Prepare();
	}

	public override void Dispose()
	{
		base.Dispose();
		if (videoPlayer != null)
		{
			videoPlayer.Stop();
			UnityEngine.Object.Destroy(videoPlayer);
			videoPlayer = null;
			MeshRenderer meshRenderer = base.Config.MeshRenderer;
			if (meshRenderer != null)
			{
				meshRenderer.material.SetTexture("_MainTex", originalMainTexture);
			}
		}
		if (renderTexture != null)
		{
			UnityEngine.Object.Destroy(renderTexture);
			renderTexture = null;
		}
	}

	public override void Play()
	{
		if (videoPlayer != null && videoPlayer.isPrepared)
		{
			videoPlayer.Play();
		}
		isPlayEnqueued = true;
	}

	public override void Stop()
	{
		if (videoPlayer != null)
		{
			videoPlayer.Stop();
		}
		isPlayEnqueued = false;
	}

	private void OnPrepareCompleted(VideoPlayer source)
	{
		if (source == videoPlayer && videoPlayer != null && isPlayEnqueued)
		{
			videoPlayer.Play();
			isPlayEnqueued = false;
		}
	}
}
