public class HazardRespawnTrigger : MonoBehaviour
{
	public HazardRespawnMarker respawnMarker;

	private PlayerData playerData;

	public bool fireOnce;

	private bool inactive;

	private void Awake()
	{
		playerData = PlayerData.instance;
		if (playerData == null)
		{
			UnityEngine.Debug.LogError(base.name + "- Player Data reference is null, please check this is being set correctly.");
		}
	}

	private void Start()
	{
		if (respawnMarker == null)
		{
			UnityEngine.Debug.LogWarning(base.name + " does not have a Hazard Respawn Marker Set");
		}
	}

	private void OnTriggerEnter2D(Collider2D otherCollider)
	{
		if (!inactive && otherCollider.gameObject.layer == 9)
		{
			playerData.SetHazardRespawn(respawnMarker);
			if (fireOnce)
			{
				inactive = true;
			}
		}
	}
}
public class RespawnMarker : MonoBehaviour
{
	public bool respawnFacingRight;
}
public class RespawnTrigger : MonoBehaviour
{
	public RespawnMarker respawnMarker;

	[UnityEngine.Tooltip("If true, trigger deactivates itself after the first instance the hero uses it.")]
	public bool singleUse;

	[UnityEngine.Tooltip("0 = face down, 1 = on bench")]
	public int respawnType;

	private GameManager gm;

	private PlayerData playerData;

	private PlayMakerFSM myFsm;

	private void Awake()
	{
		gm = GameManager.instance;
		playerData = PlayerData.instance;
		if (playerData == null)
		{
			UnityEngine.Debug.LogError(base.name + "- Player Data reference is null, please check this is being set correctly.");
		}
		if (singleUse)
		{
			myFsm = GetComponent<PlayMakerFSM>();
			if (myFsm == null)
			{
				UnityEngine.Debug.LogError(base.name + " - Respawn Trigger set to Single Use but has no PlayMakerFSM attached.");
			}
		}
	}

	private void Start()
	{
		if (respawnMarker == null)
		{
			UnityEngine.Debug.LogWarning(base.name + " does not have a Death Respawn Marker Set");
		}
	}

	private void OnTriggerEnter2D(Collider2D otherCollider)
	{
		if (otherCollider.gameObject.layer != 9)
		{
			return;
		}
		if (singleUse)
		{
			if (!myFsm.FsmVariables.GetFsmBool("Activated").Value)
			{
				playerData.SetBenchRespawn(respawnMarker, gm.sceneName, respawnType);
				myFsm.FsmVariables.GetFsmBool("Activated").Value = true;
				GameManager.instance.SetCurrentMapZoneAsRespawn();
			}
		}
		else
		{
			playerData.SetBenchRespawn(respawnMarker, gm.sceneName, respawnType);
			GameManager.instance.SetCurrentMapZoneAsRespawn();
		}
	}
}
public class SimpleFadeOut : MonoBehaviour
{
	private SpriteRenderer spriteRenderer;

	public float fadeDuration = 1f;

	public bool waitForCall;

	private Color startColor;

	private Color fadeColor;

	private float currentLerpTime;

	private void Awake()
	{
		spriteRenderer = GetComponent<SpriteRenderer>();
		startColor = spriteRenderer.color;
		fadeColor = new Color(startColor.r, startColor.g, startColor.b, 0f);
	}

	private void OnEnable()
	{
		currentLerpTime = 0f;
	}

	private void Update()
	{
		if (!waitForCall)
		{
			currentLerpTime += Time.deltaTime;
			if (currentLerpTime > fadeDuration)
			{
				currentLerpTime = fadeDuration;
				base.gameObject.SetActive(value: false);
			}
			float t = currentLerpTime / fadeDuration;
			spriteRenderer.color = Color.Lerp(startColor, fadeColor, t);
		}
	}

	public void FadeOut()
	{
		waitForCall = false;
	}
}
public class SimpleSpriteFade : MonoBehaviour
{
	public Color fadeInColor;

	private SpriteRenderer spriteRenderer;

	private Color normalColor;

	public float fadeDuration;

	private bool fadingIn;

	private bool fadingOut;

	private float currentLerpTime;

	public bool fadeInOnStart;

	public bool deactivateOnFadeIn;

	public bool recycleOnFadeIn;

	private void Awake()
	{
		spriteRenderer = GetComponent<SpriteRenderer>();
		normalColor = spriteRenderer.color;
	}

	private void OnEnable()
	{
		spriteRenderer.color = normalColor;
		if (fadeInOnStart)
		{
			FadeIn();
		}
	}

	private void Update()
	{
		if (!fadingIn && !fadingOut)
		{
			return;
		}
		if (fadingIn)
		{
			currentLerpTime += Time.deltaTime;
			if (currentLerpTime > fadeDuration)
			{
				currentLerpTime = fadeDuration;
				fadingIn = false;
				if (recycleOnFadeIn)
				{
					base.gameObject.Recycle();
				}
				if (deactivateOnFadeIn)
				{
					base.gameObject.SetActive(value: false);
				}
			}
		}
		else if (fadingOut)
		{
			currentLerpTime -= Time.deltaTime;
			if (currentLerpTime < 0f)
			{
				currentLerpTime = 0f;
				fadingOut = false;
			}
		}
		float t = currentLerpTime / fadeDuration;
		spriteRenderer.color = Color.Lerp(normalColor, fadeInColor, t);
	}

	public void FadeIn()
	{
		fadingIn = true;
		currentLerpTime = 0f;
	}

	public void FadeOut()
	{
		fadingOut = true;
		currentLerpTime = fadeDuration;
	}
}
public class SpriteFadePulse : MonoBehaviour
{
	public float lowAlpha;

	public float highAlpha;

	public float fadeDuration;

	private SpriteRenderer spriteRenderer;

	private int state;

	private float currentLerpTime;

	private float currentAlpha;

	private void Awake()
	{
		spriteRenderer = GetComponent<SpriteRenderer>();
	}

	private void OnEnable()
	{
		FadeIn();
	}

	private void Update()
	{
		float num = currentLerpTime / fadeDuration;
		currentAlpha = Mathf.Lerp(lowAlpha, highAlpha, num);
		Color color = spriteRenderer.color;
		color.a = num;
		spriteRenderer.color = color;
		if (state == 0)
		{
			currentLerpTime += Time.deltaTime;
			if (currentLerpTime > fadeDuration)
			{
				FadeOut();
			}
		}
		else
		{
			currentLerpTime -= Time.deltaTime;
			if (currentLerpTime < 0f)
			{
				FadeIn();
			}
		}
	}

	public void FadeIn()
	{
		state = 0;
		currentLerpTime = 0f;
	}

	public void FadeOut()
	{
		state = 1;
		currentLerpTime = fadeDuration;
	}
}
public class WalkArea : MonoBehaviour
{
	private Collider2D myCollider;

	private GameManager gm;

	private HeroController heroCtrl;

	private bool activated;

	private bool verboseMode;

	protected void Awake()
	{
		myCollider = GetComponent<Collider2D>();
	}

	private void Start()
	{
		gm = GameManager.instance;
		gm.UnloadingLevel += Deactivate;
		heroCtrl = HeroController.instance;
	}

	private void OnTriggerEnter2D(Collider2D otherCollider)
	{
		if (otherCollider.gameObject.layer == 9)
		{
			if (verboseMode)
			{
				UnityEngine.Debug.Log("ENTER Activated Walk Zone");
			}
			activated = true;
			heroCtrl.SetWalkZone(inWalkZone: true);
		}
	}

	private void OnTriggerStay2D(Collider2D otherCollider)
	{
		if (!activated && myCollider.enabled && otherCollider.gameObject.layer == 9)
		{
			if (verboseMode)
			{
				UnityEngine.Debug.Log("STAY Activated Walk Zone");
			}
			activated = true;
			heroCtrl.SetWalkZone(inWalkZone: true);
		}
	}

	private void OnTriggerExit2D(Collider2D otherCollider)
	{
		if (otherCollider.gameObject.layer == 9)
		{
			if (verboseMode)
			{
				UnityEngine.Debug.Log("EXIT Deactivated Walk Zone");
			}
			activated = false;
			heroCtrl.SetWalkZone(inWalkZone: false);
		}
	}

	private void Deactivate()
	{
		if (verboseMode)
		{
			UnityEngine.Debug.Log("UNLOAD Deactivated Walk Zone");
		}
		activated = false;
		heroCtrl.SetWalkZone(inWalkZone: false);
	}

	private void OnDisable()
	{
		if (gm != null)
		{
			gm.UnloadingLevel -= Deactivate;
		}
	}
}
[AttributeUsage(AttributeTargets.Property | AttributeTargets.Field, AllowMultiple = false, Inherited = true)]
public class ArrayForEnumAttribute : PropertyAttribute
{
	public readonly Type EnumType;

	public readonly int EnumLength;

	public bool IsValid
	{
		get
		{
			if (EnumType != null && EnumType.IsEnum)
			{
				return EnumLength > 0;
			}
			return false;
		}
	}

	public ArrayForEnumAttribute(Type enumType)
	{
		EnumType = enumType;
		if (enumType != null && enumType.IsEnum)
		{
			int num = 0;
			Array values = Enum.GetValues(enumType);
			for (int i = 0; i < values.Length; i++)
			{
				int num2 = (int)values.GetValue(i);
				if (num2 >= 0 && num < num2)
				{
					num = num2 + 1;
				}
			}
			EnumLength = num;
		}
		else
		{
			EnumLength = 0;
		}
	}

	public static void EnsureArraySize<T>(ref T[] array, Type enumType)
	{
		int num = Enum.GetNames(enumType).Length;
		if (array != null)
		{
			if (array.Length != num)
			{
				T[] array2 = array;
				array = new T[num];
				for (int i = 0; i < Mathf.Min(num, array2.Length); i++)
				{
					array[i] = array2[i];
				}
			}
		}
		else
		{
			array = new T[num];
		}
	}
}
