	private bool[] isChannelEnabled;

	public AudioMixerSnapshot Snapshot => snapshot;

	public bool IsChannelEnabled(AtmosChannels channel)
	{
		if (channel < AtmosChannels.CaveWind || (int)channel >= isChannelEnabled.Length)
