[CreateAssetMenu(fileName = "MusicCue", menuName = "Hollow Knight/Music Cue", order = 1000)]
public class MusicCue : ScriptableObject
{
	[Serializable]
	public class MusicChannelInfo
	{
		[SerializeField]
		private AudioClip clip;

		[SerializeField]
		private MusicChannelSync sync;

		public AudioClip Clip => clip;

		public bool IsEnabled => clip != null;

		public bool IsSyncRequired
		{
			get
			{
				if (sync == MusicChannelSync.Implicit)
				{
					return clip != null;
				}
				if (sync == MusicChannelSync.ExplicitOn)
				{
					return true;
				}
				return false;
			}
		}
	}

	[Serializable]
	public struct Alternative
	{
		public string PlayerDataBoolKey;

		public MusicCue Cue;
	}

	[SerializeField]
	private string originalMusicEventName;

	[SerializeField]
	private int originalMusicTrackNumber;

	[SerializeField]
	private AudioMixerSnapshot snapshot;

	[SerializeField]
	[ArrayForEnum(typeof(MusicChannels))]
	private MusicChannelInfo[] channelInfos;

	[SerializeField]
	private Alternative[] alternatives;

	public string OriginalMusicEventName => originalMusicEventName;

	public int OriginalMusicTrackNumber => originalMusicTrackNumber;

	public AudioMixerSnapshot Snapshot => snapshot;

	public MusicChannelInfo GetChannelInfo(MusicChannels channel)
	{
		if (channel < MusicChannels.Main || (int)channel >= channelInfos.Length)
		{
			return null;
		}
		return channelInfos[(int)channel];
	}

	public MusicCue ResolveAlternatives(PlayerData playerData)
	{
		if (alternatives != null)
		{
			for (int i = 0; i < alternatives.Length; i++)
			{
				Alternative alternative = alternatives[i];
				if (playerData.GetBool(alternative.PlayerDataBoolKey))
				{
					MusicCue cue = alternative.Cue;
					if (!(cue != null))
					{
						return null;
					}
					return cue.ResolveAlternatives(playerData);
				}
			}
		}
		return this;
	}
}
public enum MusicChannelSync
{
	Implicit,
	ExplicitOn,
	ExplicitOff
}
public class MusicRegion : MonoBehaviour
{
	public bool dirtmouth;

	public bool minesDelay;

	[Space]
	public MusicCue enterMusicCue;

	public AudioMixerSnapshot enterMusicSnapshot;

	public string enterTrackEvent;

	public float enterTransitionTime;

	[Space]
	public MusicCue exitMusicCue;

	public AudioMixerSnapshot exitMusicSnapshot;

	public string exitTrackEvent;

	public float exitTransitionTime;

	private Coroutine fadeInRoutine;

	private void Reset()
	{
		PlayMakerFSM component = GetComponent<PlayMakerFSM>();
		if ((bool)component && component.FsmName == "Music Region")
		{
			FsmVariables fsmVariables = component.FsmVariables;
			dirtmouth = fsmVariables.GetFsmBool("Dirtmouth").Value;
			minesDelay = fsmVariables.GetFsmBool("Mines Delay").Value;
			enterMusicCue = fsmVariables.GetFsmObject("Enter Music Cue").Value as MusicCue;
			enterMusicSnapshot = fsmVariables.GetFsmObject("Enter Music Snapshot").Value as AudioMixerSnapshot;
			enterTrackEvent = fsmVariables.GetFsmString("Enter Track Event").Value;
			enterTransitionTime = fsmVariables.GetFsmFloat("Enter Transition Time").Value;
			exitMusicCue = fsmVariables.GetFsmObject("Exit Music Cue").Value as MusicCue;
			exitMusicSnapshot = fsmVariables.GetFsmObject("Exit Music Snapshot").Value as AudioMixerSnapshot;
			exitTrackEvent = fsmVariables.GetFsmString("Exit Track Event").Value;
			exitTransitionTime = fsmVariables.GetFsmFloat("Exit Transition Time").Value;
		}
	}

	private void OnTriggerEnter2D(Collider2D collision)
	{
		if (collision.gameObject.layer == 9)
		{
			if (fadeInRoutine != null)
			{
				StopCoroutine(fadeInRoutine);
			}
			fadeInRoutine = StartCoroutine(FadeIn());
		}
	}

	private void OnTriggerExit2D(Collider2D collision)
	{
		if (collision.gameObject.layer == 9)
		{
			if (fadeInRoutine != null)
			{
				StopCoroutine(fadeInRoutine);
			}
			FadeOut();
		}
	}

	private IEnumerator FadeIn()
	{
		if (minesDelay)
		{
			yield return new WaitForSeconds(2.35f);
		}
		float timeToReach = enterTransitionTime;
		if (dirtmouth)
		{
			MusicCue currentMusicCue = GameManager.instance.AudioManager.CurrentMusicCue;
			if ((currentMusicCue ? currentMusicCue.name : "") != "Dirtmouth")
			{
				timeToReach = 1f;
			}
		}
		if (enterMusicSnapshot != null)
		{
			enterMusicSnapshot.TransitionTo(timeToReach);
		}
		if ((bool)enterMusicCue)
		{
			GameManager.instance.AudioManager.ApplyMusicCue(enterMusicCue, 0f, 0f, applySnapshot: false);
		}
		fadeInRoutine = null;
	}

	private void FadeOut()
	{
		if (exitMusicSnapshot != null)
		{
			exitMusicSnapshot.TransitionTo(exitTransitionTime);
		}
		if ((bool)exitMusicCue)
		{
			GameManager.instance.AudioManager.ApplyMusicCue(exitMusicCue, 0f, 0f, applySnapshot: false);
		}
	}
}
public class MuteAudioChannel : MonoBehaviour
{
	public AudioMixer mixer;

	public string exposedProperty = "volActors";

	private float initialVolume;

	public float Volume
	{
		get
		{
			float value = 0f;
			if ((bool)mixer)
			{
				mixer.GetFloat(exposedProperty, out value);
			}
			return DecibelToLinear(value);
		}
		set
		{
			if ((bool)mixer)
			{
				mixer.SetFloat(exposedProperty, LinearToDecibel(value));
			}
		}
	}

	private void OnEnable()
	{
		if ((bool)mixer)
		{
			initialVolume = Volume;
			Volume = 0f;
		}
	}

	private void OnDisable()
	{
		if ((bool)mixer)
		{
			Volume = initialVolume;
		}
	}

	private float LinearToDecibel(float linear)
	{
		if (linear != 0f)
		{
			return 20f * Mathf.Log10(linear);
		}
		return -144f;
	}

	private float DecibelToLinear(float dB)
	{
		return Mathf.Pow(10f, dB / 20f);
	}
}
