public class CameraFade : MonoBehaviour
{
	public enum FadeTypes
	{
		NONE,
		BLACK_TO_CLEAR,
		CLEAR_TO_BLACK
	}

	private GUIStyle backgroundStyle = new GUIStyle();

	private Texture2D fadeTexture;

	private Color currentScreenOverlayColor = new Color(0f, 0f, 0f, 0f);

	private Color targetScreenOverlayColor = new Color(0f, 0f, 0f, 1f);

	private Color deltaColor = new Color(0f, 0f, 0f, 0f);

	private int fadeGUIDepth = -1000;

	[Header("Fade On Scene Start")]
	[Space(6f)]
	[UnityEngine.Tooltip("Type of fade to do on Start.")]
	public FadeTypes fadeOnStart;

	[UnityEngine.Tooltip("The time in seconds to wait after Start before performing the delay.")]
	public float startDelay;

	[UnityEngine.Tooltip("Time to perform fade in seconds on Start.")]
	public float fadeTime;

	private void Awake()
	{
		fadeTexture = new Texture2D(1, 1);
		backgroundStyle.normal.background = fadeTexture;
	}

	private IEnumerator Start()
	{
		if (fadeOnStart == FadeTypes.BLACK_TO_CLEAR)
		{
			SetScreenOverlayColor(new Color(0f, 0f, 0f, 1f));
		}
		else if (fadeOnStart == FadeTypes.CLEAR_TO_BLACK)
		{
			SetScreenOverlayColor(new Color(0f, 0f, 0f, 0f));
		}
		if (startDelay > 0f)
		{
			yield return new WaitForSeconds(startDelay);
		}
		else
		{
			yield return new WaitForEndOfFrame();
		}
		if (fadeOnStart == FadeTypes.BLACK_TO_CLEAR)
		{
			FadeToTransparent(fadeTime);
		}
		else if (fadeOnStart == FadeTypes.CLEAR_TO_BLACK)
		{
			FadeToBlack(fadeTime);
		}
	}

	private void OnGUI()
	{
		if (currentScreenOverlayColor != targetScreenOverlayColor)
		{
			if (Mathf.Abs(currentScreenOverlayColor.a - targetScreenOverlayColor.a) < Mathf.Abs(deltaColor.a) * Time.deltaTime)
			{
				currentScreenOverlayColor = targetScreenOverlayColor;
				SetScreenOverlayColor(currentScreenOverlayColor);
				deltaColor = new Color(0f, 0f, 0f, 0f);
			}
			else
			{
				SetScreenOverlayColor(currentScreenOverlayColor + deltaColor * Time.deltaTime);
			}
		}
		if (currentScreenOverlayColor.a > 0f)
		{
			GUI.depth = fadeGUIDepth;
			GUI.Label(new Rect(-10f, -10f, Screen.width + 10, Screen.height + 10), fadeTexture, backgroundStyle);
		}
	}

	public void SetScreenOverlayColor(Color newScreenOverlayColor)
	{
		currentScreenOverlayColor = newScreenOverlayColor;
		fadeTexture.SetPixel(0, 0, currentScreenOverlayColor);
		fadeTexture.Apply();
	}

	public void StartFade(Color newScreenOverlayColor, float fadeDuration)
	{
		if (fadeDuration <= 0f)
		{
			SetScreenOverlayColor(newScreenOverlayColor);
			return;
		}
		targetScreenOverlayColor = newScreenOverlayColor;
		deltaColor = (targetScreenOverlayColor - currentScreenOverlayColor) / (fadeDuration * 2f);
	}

	public void FadeToBlack(float duration)
	{
		SetScreenOverlayColor(new Color(0f, 0f, 0f, 0f));
		StartFade(new Color(0f, 0f, 0f, 1f), duration);
	}

	public void FadeToTransparent(float duration)
	{
		SetScreenOverlayColor(new Color(0f, 0f, 0f, 1f));
		StartFade(new Color(0f, 0f, 0f, 0f), duration);
	}
}
public class CameraLockArea : MonoBehaviour
{
	private bool verboseMode;

	public float cameraXMin;

	public float cameraYMin;

	public float cameraXMax;

	public float cameraYMax;

	private float leftSideX;

	private float rightSideX;

	private float topSideY;

	private float botSideY;

	private Vector3 heroPos;

	private bool enteredLeft;

	private bool enteredRight;

	private bool enteredTop;

	private bool enteredBot;

	private bool exitedLeft;

	private bool exitedRight;

	private bool exitedTop;

	private bool exitedBot;

	public bool preventLookUp;

	public bool preventLookDown;

	public bool maxPriority;

	private GameCameras gcams;

	private CameraController cameraCtrl;

	private CameraTarget camTarget;

	private Collider2D box2d;

	private void Awake()
	{
		box2d = GetComponent<Collider2D>();
	}

	private IEnumerator Start()
	{
		gcams = GameCameras.instance;
		if (gcams == null)
		{
			yield break;
		}
		cameraCtrl = gcams.cameraController;
		camTarget = gcams.cameraTarget;
		Scene scene = gameObject.scene;
		if (!(cameraCtrl == null))
		{
			while (cameraCtrl.tilemap == null || cameraCtrl.tilemap.gameObject.scene != scene)
			{
				yield return null;
			}
			if (!ValidateBounds())
			{
				UnityEngine.Debug.LogError("Camera bounds are unspecified for " + name + ", please specify lock area bounds for this Camera Lock Area.");
			}
			if (box2d != null)
			{
				leftSideX = box2d.bounds.min.x;
				rightSideX = box2d.bounds.max.x;
				botSideY = box2d.bounds.min.y;
				topSideY = box2d.bounds.max.y;
			}
		}
	}

	private bool IsInApplicableGameState()
	{
		GameManager unsafeInstance = GameManager.UnsafeInstance;
		if (unsafeInstance == null)
		{
			return false;
		}
		if (unsafeInstance.gameState != GameState.PLAYING)
		{
			return unsafeInstance.gameState == GameState.ENTERING_LEVEL;
		}
		return true;
	}

	public void OnTriggerEnter2D(Collider2D otherCollider)
	{
		if (!IsInApplicableGameState() || !otherCollider.CompareTag("Player"))
		{
			return;
		}
		heroPos = otherCollider.gameObject.transform.position;
		if (box2d != null)
		{
			if (heroPos.x > leftSideX - 1f && heroPos.x < leftSideX + 1f)
			{
				camTarget.enteredLeft = true;
			}
			else
			{
				camTarget.enteredLeft = false;
			}
			if (heroPos.x > rightSideX - 1f && heroPos.x < rightSideX + 1f)
			{
				camTarget.enteredRight = true;
			}
			else
			{
				camTarget.enteredRight = false;
			}
			if (heroPos.y > topSideY - 2f && heroPos.y < topSideY + 2f)
			{
				camTarget.enteredTop = true;
			}
			else
			{
				camTarget.enteredTop = false;
			}
			if (heroPos.y > botSideY - 1f && heroPos.y < botSideY + 1f)
			{
				camTarget.enteredBot = true;
			}
			else
			{
				camTarget.enteredBot = false;
			}
		}
		cameraCtrl.LockToArea(this);
		if (verboseMode)
		{
			UnityEngine.Debug.Log("Lockzone Enter Lock " + base.name);
		}
	}

	public void OnTriggerStay2D(Collider2D otherCollider)
	{
		if (!base.isActiveAndEnabled || !box2d.isActiveAndEnabled)
		{
			UnityEngine.Debug.LogWarning("Fix for Unity trigger event queue!");
		}
		else if (IsInApplicableGameState() && otherCollider.CompareTag("Player"))
		{
			if (verboseMode)
			{
				UnityEngine.Debug.Log("Lockzone Stay Lock " + base.name);
			}
			cameraCtrl.LockToArea(this);
		}
	}

	public void OnTriggerExit2D(Collider2D otherCollider)
	{
		if (!otherCollider.CompareTag("Player"))
		{
			return;
		}
		heroPos = otherCollider.gameObject.transform.position;
		if (box2d != null)
		{
			if (heroPos.x > leftSideX - 1f && heroPos.x < leftSideX + 1f)
			{
				camTarget.exitedLeft = true;
			}
			else
			{
				camTarget.exitedLeft = false;
			}
			if (heroPos.x > rightSideX - 1f && heroPos.x < rightSideX + 1f)
			{
				camTarget.exitedRight = true;
			}
			else
			{
				camTarget.exitedRight = false;
			}
			if (heroPos.y > topSideY - 2f && heroPos.y < topSideY + 2f)
			{
				camTarget.exitedTop = true;
			}
			else
			{
				camTarget.exitedTop = false;
			}
			if (heroPos.y > botSideY - 1f && heroPos.y < botSideY + 1f)
			{
				camTarget.exitedBot = true;
			}
			else
			{
				camTarget.exitedBot = false;
			}
		}
		cameraCtrl.ReleaseLock(this);
		if (verboseMode)
		{
			UnityEngine.Debug.Log("Lockzone Exit Lock " + base.name);
		}
	}

	public void OnDisable()
	{
		if (cameraCtrl != null)
		{
			cameraCtrl.ReleaseLock(this);
		}
	}

	private bool ValidateBounds()
	{
		if (cameraXMin == -1f)
		{
			cameraXMin = 14.6f;
		}
		if (cameraXMax == -1f)
		{
			cameraXMax = cameraCtrl.xLimit;
		}
		if (cameraYMin == -1f)
		{
			cameraYMin = 8.3f;
		}
		if (cameraYMax == -1f)
		{
			cameraYMax = cameraCtrl.yLimit;
		}
		if (cameraXMin == 0f && cameraXMax == 0f && cameraYMin == 0f && cameraYMax == 0f)
		{
			return false;
		}
		return true;
	}

	public void SetXMin(float xmin)
	{
		cameraXMin = xmin;
	}

	public void SetXMax(float xmax)
	{
		cameraXMax = xmax;
	}

	private IEnumerator orig_Start()
	{
		gcams = GameCameras.instance;
		cameraCtrl = gcams.cameraController;
		camTarget = gcams.cameraTarget;
		Scene scene = gameObject.scene;
		while (cameraCtrl.tilemap == null || cameraCtrl.tilemap.gameObject.scene != scene)
		{
			yield return null;
		}
		if (!ValidateBounds())
		{
			UnityEngine.Debug.LogError("Camera bounds are unspecified for " + name + ", please specify lock area bounds for this Camera Lock Area.");
		}
		if (box2d != null)
		{
			leftSideX = box2d.bounds.min.x;
			rightSideX = box2d.bounds.max.x;
			botSideY = box2d.bounds.min.y;
			topSideY = box2d.bounds.max.y;
		}
	}
}
public class CameraTarget : MonoBehaviour
{
	public enum TargetMode
	{
		FOLLOW_HERO,
		LOCK_ZONE,
		BOSS,
		FREE
	}

	private bool verboseMode;

	[HideInInspector]
	public GameManager gm;

	[HideInInspector]
	public HeroController hero_ctrl;

	private Transform heroTransform;

	public CameraController cameraCtrl;

	public TargetMode mode;

	public Vector3 destination;

	private Vector3 velocityX;

	private Vector3 velocityY;

	public float xOffset;

	public float dashOffset;

	public float fallOffset;

	public float fallOffset_multiplier;

	public float xLockMin;

	public float xLockMax;

	public float yLockMin;

	public float yLockMax;

	public bool enteredLeft;

	public bool enteredRight;

	public bool enteredTop;

	public bool enteredBot;

	public bool exitedLeft;

	public bool exitedRight;

	public bool exitedTop;

	public bool exitedBot;

	public bool superDashing;

	public bool quaking;

	public float slowTime = 0.5f;

	public float dampTimeNormal;

	public float dampTimeSlow;

	public float xLookAhead;

	public float dashLookAhead;

	public float superDashLookAhead;

	private Vector3 heroPrevPosition;

	private float dampTime;

	private float dampTimeX;

	private float dampTimeY;

	private float slowTimer;

	private float snapDistance = 0.15f;

	public float fallCatcher;

	public bool stickToHeroX;

	public bool stickToHeroY;

	public bool enteredFromLockZone;

	private float prevTarget_y;

	private float prevCam_y;

	public bool fallStick;

	private bool isGameplayScene;

	public void GameInit()
	{
		gm = GameManager.instance;
		if (cameraCtrl == null)
		{
			cameraCtrl = base.transform.parent.GetComponent<CameraController>();
		}
	}

	public void SceneInit()
	{
		if (gm == null)
		{
			gm = GameManager.instance;
		}
		if (gm.IsGameplayScene())
		{
			isGameplayScene = true;
			hero_ctrl = HeroController.instance;
			heroTransform = hero_ctrl.transform;
			mode = TargetMode.FOLLOW_HERO;
			stickToHeroX = true;
			stickToHeroY = true;
			fallCatcher = 0f;
			xLockMin = 0f;
			xLockMax = cameraCtrl.xLimit;
			yLockMin = 0f;
			yLockMax = cameraCtrl.yLimit;
		}
		else
		{
			isGameplayScene = false;
			mode = TargetMode.FREE;
		}
	}

	public void Update()
	{
		if (hero_ctrl == null || !isGameplayScene)
		{
			mode = TargetMode.FREE;
		}
		else
		{
			if (!isGameplayScene)
			{
				return;
			}
			float num = base.transform.position.x;
			float num2 = base.transform.position.y;
			float z = base.transform.position.z;
			float x = heroTransform.position.x;
			float y = heroTransform.position.y;
			_ = heroTransform.position;
			if (mode == TargetMode.FOLLOW_HERO)
			{
				SetDampTime();
				destination = heroTransform.position;
				if (!fallStick && fallCatcher <= 0f)
				{
					base.transform.position = new Vector3(Vector3.SmoothDamp(base.transform.position, new Vector3(destination.x, base.transform.position.y, z), ref velocityX, dampTimeX).x, Vector3.SmoothDamp(base.transform.position, new Vector3(base.transform.position.x, destination.y, z), ref velocityY, dampTimeY).y, z);
				}
				else
				{
					base.transform.position = new Vector3(Vector3.SmoothDamp(base.transform.position, new Vector3(destination.x, base.transform.position.y, z), ref velocityX, dampTimeX).x, base.transform.position.y, z);
				}
				num = base.transform.position.x;
				num2 = base.transform.position.y;
				z = base.transform.position.z;
				if ((heroPrevPosition.x < num && x > num) || (heroPrevPosition.x > num && x < num) || (num >= x - snapDistance && num <= x + snapDistance))
				{
					stickToHeroX = true;
				}
				if ((heroPrevPosition.y < num2 && y > num2) || (heroPrevPosition.y > num2 && y < num2) || (num2 >= y - snapDistance && num2 <= y + snapDistance))
				{
					stickToHeroY = true;
				}
				if (stickToHeroX)
				{
					base.transform.SetPositionX(x);
					num = x;
				}
				if (stickToHeroY)
				{
					base.transform.SetPositionY(y);
					num2 = y;
				}
			}
			if (mode == TargetMode.LOCK_ZONE)
			{
				SetDampTime();
				destination = heroTransform.position;
				if (destination.x < xLockMin)
				{
					destination.x = xLockMin;
				}
				if (destination.x > xLockMax)
				{
					destination.x = xLockMax;
				}
				if (destination.y < yLockMin)
				{
					destination.y = yLockMin;
				}
				if (destination.y > yLockMax)
				{
					destination.y = yLockMax;
				}
				if (!fallStick && fallCatcher <= 0f)
				{
					base.transform.position = new Vector3(Vector3.SmoothDamp(base.transform.position, new Vector3(destination.x, num2, z), ref velocityX, dampTimeX).x, Vector3.SmoothDamp(base.transform.position, new Vector3(num, destination.y, z), ref velocityY, dampTimeY).y, z);
				}
				else
				{
					base.transform.position = new Vector3(Vector3.SmoothDamp(base.transform.position, new Vector3(destination.x, num2, z), ref velocityX, dampTimeX).x, num2, z);
				}
				num = base.transform.position.x;
				num2 = base.transform.position.y;
				z = base.transform.position.z;
				if ((heroPrevPosition.x < num && x > num) || (heroPrevPosition.x > num && x < num) || (num >= x - snapDistance && num <= x + snapDistance))
				{
					stickToHeroX = true;
				}
				if ((heroPrevPosition.y < num2 && y > num2) || (heroPrevPosition.y > num2 && y < num2) || (num2 >= y - snapDistance && num2 <= y + snapDistance))
				{
					stickToHeroY = true;
				}
				if (stickToHeroX)
				{
					bool flag = false;
					if (x >= xLockMin && x <= xLockMax)
					{
						flag = true;
					}
					if (x <= xLockMax && x >= num)
					{
						flag = true;
					}
					if (x >= xLockMin && x <= num)
					{
						flag = true;
					}
					if (flag)
					{
						base.transform.SetPositionX(x);
						num = x;
					}
				}
				if (stickToHeroY)
				{
					bool flag2 = false;
					if (y >= yLockMin && y <= yLockMax)
					{
						flag2 = true;
					}
					if (y <= yLockMax && y >= num2)
					{
						flag2 = true;
					}
					if (y >= yLockMin && y <= num2)
					{
						flag2 = true;
					}
					if (flag2)
					{
						base.transform.SetPositionY(y);
						num2 = y;
					}
				}
			}
			if (hero_ctrl != null)
			{
				if (hero_ctrl.cState.facingRight)
				{
					if (xOffset < xLookAhead)
					{
						xOffset += Time.deltaTime * 6f;
					}
				}
				else if (xOffset > 0f - xLookAhead)
				{
					xOffset -= Time.deltaTime * 6f;
				}
				if (xOffset < 0f - xLookAhead)
				{
					xOffset = 0f - xLookAhead;
				}
				if (xOffset > xLookAhead)
				{
					xOffset = xLookAhead;
				}
				if (mode == TargetMode.LOCK_ZONE)
				{
					if (x < xLockMin && hero_ctrl.cState.facingRight)
					{
						xOffset = x - num + 1f;
					}
					if (x > xLockMax && !hero_ctrl.cState.facingRight)
					{
						xOffset = x - num - 1f;
					}
					if (num + xOffset > xLockMax)
					{
						xOffset = xLockMax - num;
					}
					if (num + xOffset < xLockMin)
					{
						xOffset = xLockMin - num;
					}
				}
				if (xOffset < 0f - xLookAhead)
				{
					xOffset = 0f - xLookAhead;
				}
				if (xOffset > xLookAhead)
				{
					xOffset = xLookAhead;
				}
				if (hero_ctrl.cState.dashing && (hero_ctrl.current_velocity.x > 5f || hero_ctrl.current_velocity.x < -5f))
				{
					if (hero_ctrl.cState.facingRight)
					{
						dashOffset = dashLookAhead;
					}
					else
					{
						dashOffset = 0f - dashLookAhead;
					}
					if (mode == TargetMode.LOCK_ZONE)
					{
						if (num + dashOffset > xLockMax)
						{
							dashOffset = 0f;
						}
						if (num + dashOffset < xLockMin)
						{
							dashOffset = 0f;
						}
						if (x > xLockMax || x < xLockMin)
						{
							dashOffset = 0f;
						}
					}
				}
				else if (superDashing)
				{
					if (hero_ctrl.cState.facingRight)
					{
						dashOffset = superDashLookAhead;
					}
					else
					{
						dashOffset = 0f - superDashLookAhead;
					}
					if (mode == TargetMode.LOCK_ZONE)
					{
						if (num + dashOffset > xLockMax)
						{
							dashOffset = 0f;
						}
						if (num + dashOffset < xLockMin)
						{
							dashOffset = 0f;
						}
						if (x > xLockMax || x < xLockMin)
						{
							dashOffset = 0f;
						}
					}
				}
				else
				{
					dashOffset = 0f;
				}
				heroPrevPosition = heroTransform.position;
			}
			if (hero_ctrl != null && !hero_ctrl.cState.falling)
			{
				fallCatcher = 0f;
				fallStick = false;
			}
			if (mode == TargetMode.FOLLOW_HERO || mode == TargetMode.LOCK_ZONE)
			{
				if (hero_ctrl.cState.falling && cameraCtrl.transform.position.y > y + 0.1f && !fallStick && !hero_ctrl.cState.transitioning && (cameraCtrl.transform.position.y - 0.1f >= yLockMin || mode != TargetMode.LOCK_ZONE))
				{
					cameraCtrl.transform.SetPositionY(cameraCtrl.transform.position.y - fallCatcher * Time.deltaTime);
					if (mode == TargetMode.LOCK_ZONE && cameraCtrl.transform.position.y < yLockMin)
					{
						cameraCtrl.transform.SetPositionY(yLockMin);
					}
					if (cameraCtrl.transform.position.y < 8.3f)
					{
						cameraCtrl.transform.SetPositionY(8.3f);
					}
					if (fallCatcher < 25f)
					{
						fallCatcher += 80f * Time.deltaTime;
					}
					if (cameraCtrl.transform.position.y < heroTransform.position.y + 0.1f)
					{
						fallStick = true;
					}
					base.transform.SetPositionY(cameraCtrl.transform.position.y);
					num2 = cameraCtrl.transform.position.y;
				}
				if (fallStick)
				{
					fallCatcher = 0f;
					if (heroTransform.position.y + 0.1f >= yLockMin || mode != TargetMode.LOCK_ZONE)
					{
						cameraCtrl.transform.SetPositionY(heroTransform.position.y + 0.1f);
						base.transform.SetPositionY(cameraCtrl.transform.position.y);
						num2 = cameraCtrl.transform.position.y;
					}
					if (mode == TargetMode.LOCK_ZONE && cameraCtrl.transform.position.y < yLockMin)
					{
						cameraCtrl.transform.SetPositionY(yLockMin);
					}
					if (cameraCtrl.transform.position.y < 8.3f)
					{
						cameraCtrl.transform.SetPositionY(8.3f);
					}
				}
			}
			if (quaking)
			{
				num2 = heroTransform.position.y;
				if (mode == TargetMode.LOCK_ZONE && num2 < yLockMin)
				{
					base.transform.SetPositionY(yLockMin);
					num2 = yLockMin;
				}
				base.transform.SetPositionY(num2);
			}
		}
	}

	public void EnterLockZone(float xLockMin_var, float xLockMax_var, float yLockMin_var, float yLockMax_var)
	{
		xLockMin = xLockMin_var;
		xLockMax = xLockMax_var;
		yLockMin = yLockMin_var;
		yLockMax = yLockMax_var;
		mode = TargetMode.LOCK_ZONE;
		float x = base.transform.position.x;
		float y = base.transform.position.y;
		_ = base.transform.position;
		float x2 = heroTransform.position.x;
		float y2 = heroTransform.position.y;
		_ = heroTransform.position;
		if ((!enteredLeft || xLockMin != 14.6f) && (!enteredRight || xLockMax != cameraCtrl.xLimit))
		{
			dampTimeX = dampTimeSlow;
		}
		if ((!enteredBot || yLockMin != 8.3f) && (!enteredTop || yLockMax != cameraCtrl.yLimit))
		{
			dampTimeY = dampTimeSlow;
		}
		slowTimer = slowTime;
		if (x >= x2 - snapDistance && x <= x2 + snapDistance)
		{
			stickToHeroX = true;
		}
		else
		{
			stickToHeroX = false;
		}
		if (y >= y2 - snapDistance && y <= y2 + snapDistance)
		{
			stickToHeroY = true;
		}
		else
		{
			stickToHeroY = false;
		}
	}

	public void EnterLockZoneInstant(float xLockMin_var, float xLockMax_var, float yLockMin_var, float yLockMax_var)
	{
		xLockMin = xLockMin_var;
		xLockMax = xLockMax_var;
		yLockMin = yLockMin_var;
		yLockMax = yLockMax_var;
		mode = TargetMode.LOCK_ZONE;
		if (base.transform.position.x < xLockMin)
		{
			base.transform.SetPositionX(xLockMin);
		}
		if (base.transform.position.x > xLockMax)
		{
			base.transform.SetPositionX(xLockMax);
		}
		if (base.transform.position.y < yLockMin)
		{
			base.transform.SetPositionY(yLockMin);
		}
		if (base.transform.position.y > yLockMax)
		{
			base.transform.SetPositionY(yLockMax);
		}
		stickToHeroX = true;
		stickToHeroY = true;
	}

	public void ExitLockZone()
	{
		if (mode == TargetMode.FREE)
		{
			return;
		}
		if (hero_ctrl.cState.hazardDeath || hero_ctrl.cState.dead || (hero_ctrl.transitionState != HeroTransitionState.WAITING_TO_TRANSITION && hero_ctrl.transitionState != HeroTransitionState.WAITING_TO_ENTER_LEVEL))
		{
			mode = TargetMode.FREE;
		}
		else
		{
			mode = TargetMode.FOLLOW_HERO;
		}
		if ((!exitedLeft || xLockMin != 14.6f) && (!exitedRight || xLockMax != cameraCtrl.xLimit))
		{
			dampTimeX = dampTimeSlow;
		}
		if ((!exitedBot || yLockMin != 8.3f) && (!exitedTop || yLockMax != cameraCtrl.yLimit))
		{
			dampTimeY = dampTimeSlow;
		}
		slowTimer = slowTime;
		stickToHeroX = false;
		stickToHeroY = false;
		fallStick = false;
		xLockMin = 0f;
		xLockMax = cameraCtrl.xLimit;
		yLockMin = 0f;
		yLockMax = cameraCtrl.yLimit;
		if (hero_ctrl != null)
		{
			if (base.transform.position.x >= heroTransform.position.x - snapDistance && base.transform.position.x <= heroTransform.position.x + snapDistance)
			{
				stickToHeroX = true;
			}
			else
			{
				stickToHeroX = false;
			}
			if (base.transform.position.y >= heroTransform.position.y - snapDistance && base.transform.position.y <= heroTransform.position.y + snapDistance)
			{
				stickToHeroY = true;
			}
			else
			{
				stickToHeroY = false;
			}
		}
	}

	private void SetDampTime()
	{
		if (slowTimer > 0f)
		{
			slowTimer -= Time.deltaTime;
			return;
		}
		if (dampTimeX > dampTimeNormal)
		{
			dampTimeX -= 0.007f;
		}
		else if (dampTimeX < dampTimeNormal)
		{
			dampTimeX = dampTimeNormal;
		}
		if (dampTimeY > dampTimeNormal)
		{
			dampTimeY -= 0.007f;
		}
		else if (dampTimeY < dampTimeNormal)
		{
			dampTimeY = dampTimeNormal;
		}
	}

	public void SetSuperDash(bool active)
	{
		superDashing = active;
	}

	public void SetQuake(bool quake)
	{
		quaking = quake;
	}

	public void FreezeInPlace()
	{
		mode = TargetMode.FREE;
	}

	public void PositionToStart()
	{
		float x = base.transform.position.x;
		_ = base.transform.position;
		float x2 = heroTransform.position.x;
		float y = heroTransform.position.y;
		velocityX = Vector3.zero;
		velocityY = Vector3.zero;
		destination = heroTransform.position;
		if (hero_ctrl.cState.facingRight)
		{
			xOffset = 1f;
		}
		else
		{
			xOffset = -1f;
		}
		if (mode == TargetMode.LOCK_ZONE)
		{
			if (x2 < xLockMin && hero_ctrl.cState.facingRight)
			{
				xOffset = x2 - x + 1f;
			}
			if (x2 > xLockMax && !hero_ctrl.cState.facingRight)
			{
				xOffset = x2 - x - 1f;
			}
			if (x + xOffset > xLockMax)
			{
				xOffset = xLockMax - x;
			}
			if (x + xOffset < xLockMin)
			{
				xOffset = xLockMin - x;
			}
		}
		if (xOffset < 0f - xLookAhead)
		{
			xOffset = 0f - xLookAhead;
		}
		if (xOffset > xLookAhead)
		{
			xOffset = xLookAhead;
		}
		if (verboseMode)
		{
			UnityEngine.Debug.LogFormat("CT PTS - xOffset: {0} HeroPos: {1}, {2}", xOffset, x2, y);
		}
		if (mode == TargetMode.FOLLOW_HERO)
		{
			if (verboseMode)
			{
				UnityEngine.Debug.LogFormat("CT PTS - Follow Hero - CT Pos: {0}", base.transform.position);
			}
			base.transform.position = cameraCtrl.KeepWithinSceneBounds(destination);
		}
		else if (mode == TargetMode.LOCK_ZONE)
		{
			if (destination.x < xLockMin)
			{
				destination.x = xLockMin;
			}
			if (destination.x > xLockMax)
			{
				destination.x = xLockMax;
			}
			if (destination.y < yLockMin)
			{
				destination.y = yLockMin;
			}
			if (destination.y > yLockMax)
			{
				destination.y = yLockMax;
			}
			base.transform.position = destination;
			if (verboseMode)
			{
				UnityEngine.Debug.LogFormat("CT PTS - Lock Zone - CT Pos: {0}", base.transform.position);
			}
		}
		if (verboseMode)
		{
			UnityEngine.Debug.LogFormat("CT - PTS: HeroPos: {0} Mode: {1} Dest: {2}", heroTransform.position, mode, destination);
		}
		heroPrevPosition = heroTransform.position;
	}
}
public class ForceCameraAspect : MonoBehaviour
{
	private tk2dCamera tk2dCam;

	private Camera hudCam;

	private int lastX;

	private int lastY;

	private float scaleAdjust;

	public static float CurrentViewportAspect { get; private set; }

	public static event Action<float> ViewportAspectChanged;

	private void Awake()
	{
		tk2dCam = GetComponent<tk2dCamera>();
		CurrentViewportAspect = 1.7777778f;
	}

	private void Start()
	{
		hudCam = GameCameras.instance.hudCamera;
		AutoScaleViewport();
	}

	private void Update()
	{
		if (lastX != Screen.width || lastY != Screen.height)
		{
			float num = AutoScaleViewport();
			lastX = Screen.width;
			lastY = Screen.height;
			if (ViewportAspectChanged != null)
			{
				ViewportAspectChanged(num);
			}
			CurrentViewportAspect = num;
		}
	}

	public void SetOverscanViewport(float adjustment)
	{
		scaleAdjust = adjustment;
		AutoScaleViewport();
	}

	private float AutoScaleViewport()
	{
		float num = (float)Screen.width / (float)Screen.height / 1.7777778f;
		float num2 = 1f + scaleAdjust;
		Rect rect = tk2dCam.CameraSettings.rect;
		if (num < 1f)
		{
			rect.width = 1f * num2;
			rect.height = num * num2;
			float x = (1f - rect.width) / 2f;
			rect.x = x;
			float y = (1f - rect.height) / 2f;
			rect.y = y;
		}
		else
		{
			float num3 = 1f / num;
			rect.width = num3 * num2;
			rect.height = 1f * num2;
			float x2 = (1f - rect.width) / 2f;
			rect.x = x2;
			float y2 = (1f - rect.height) / 2f;
			rect.y = y2;
		}
		tk2dCam.CameraSettings.rect = rect;
		hudCam.rect = rect;
		return 1.7777778f;
	}
}
public class ForceCameraAspectLite : MonoBehaviour
{
	public Camera sceneCamera;

	private bool viewportChanged;

	private int lastX;

	private int lastY;

	private float scaleAdjust;

	private void Start()
	{
		AutoScaleViewport();
	}

	private void Update()
	{
		viewportChanged = false;
		if (lastX != Screen.width)
		{
			viewportChanged = true;
		}
		if (lastY != Screen.height)
		{
			viewportChanged = true;
		}
		if (viewportChanged)
		{
			AutoScaleViewport();
		}
		lastX = Screen.width;
		lastY = Screen.height;
	}

	private void AutoScaleViewport()
	{
		float num = (float)Screen.width / (float)Screen.height / 1.7777778f;
		float num2 = 1f + scaleAdjust;
		Rect rect = sceneCamera.rect;
		if (num < 1f)
		{
			rect.width = 1f * num2;
			rect.height = num * num2;
			float x = (1f - rect.width) / 2f;
			rect.x = x;
			float y = (1f - rect.height) / 2f;
			rect.y = y;
		}
		else
		{
			float num3 = 1f / num;
			rect.width = num3 * num2;
			rect.height = 1f * num2;
			float x2 = (1f - rect.width) / 2f;
			rect.x = x2;
			float y2 = (1f - rect.height) / 2f;
			rect.y = y2;
		}
		sceneCamera.rect = rect;
	}
}
public class GameCameras : MonoBehaviour
{
	[Header("Cameras")]
	public Camera hudCamera;

	public Camera mainCamera;

	[Header("Controllers")]
	public CameraController cameraController;

	public CameraTarget cameraTarget;

	public ForceCameraAspect forceCameraAspect;

	[Header("FSMs")]
	public PlayMakerFSM cameraFadeFSM;

	public PlayMakerFSM cameraShakeFSM;

	public PlayMakerFSM soulOrbFSM;

	public PlayMakerFSM soulVesselFSM;

	public PlayMakerFSM openStagFSM;

	[Header("Camera Effects")]
	public ColorCorrectionCurves colorCorrectionCurves;

	public SceneColorManager sceneColorManager;

	public BrightnessEffect brightnessEffect;

	public SceneParticlesController sceneParticlesPrefab;

	[Header("Other")]
	public tk2dCamera tk2dCam;

	public GameObject hudCanvas;

	public Transform cameraParent;

	public GeoCounter geoCounter;

	private GameManager gm;

	private GameSettings gs;

	private CanvasScaler canvasScaler;

	private bool init;

	private static GameCameras _instance;

	public SceneParticlesController sceneParticles { get; private set; }

	public static GameCameras instance
	{
		get
		{
			if (_instance == null)
			{
				_instance = UnityEngine.Object.FindObjectOfType<GameCameras>();
				if (_instance == null)
				{
					UnityEngine.Debug.LogError("Couldn't find GameCameras, make sure one exists in the scene.");
				}
				else
				{
					UnityEngine.Object.DontDestroyOnLoad(_instance.gameObject);
				}
			}
			return _instance;
		}
	}

	private void Awake()
	{
		if (_instance == null)
		{
			_instance = this;
			UnityEngine.Object.DontDestroyOnLoad(this);
		}
		else if (this != _instance)
		{
			UnityEngine.Object.DestroyImmediate(base.gameObject);
		}
	}

	private void Start()
	{
		gs.LoadOverscanSettings();
		SetOverscan(gs.overScanAdjustment);
	}

	public void SceneInit()
	{
		if (this == _instance)
		{
			StartScene();
		}
	}

	private void OnDestroy()
	{
		UnityEngine.Object.DestroyImmediate(sceneParticles);
	}

	private void SetupGameRefs()
	{
		gm = GameManager.instance;
		gs = gm.gameSettings;
		canvasScaler = UIManager.instance.canvasScaler;
		if (cameraController != null)
		{
			cameraController.GameInit();
		}
		else
		{
			UnityEngine.Debug.LogError("CameraController not set in inspector.");
		}
		if (cameraTarget != null)
		{
			cameraTarget.GameInit();
		}
		else
		{
			UnityEngine.Debug.LogError("CameraTarget not set in inspector.");
		}
		if (sceneParticlesPrefab != null)
		{
			sceneParticles = UnityEngine.Object.Instantiate(sceneParticlesPrefab);
			sceneParticles.name = "SceneParticlesController";
			sceneParticles.transform.position = new Vector3(tk2dCam.transform.position.x, tk2dCam.transform.position.y, 0f);
			sceneParticles.transform.SetParent(tk2dCam.transform);
		}
		else
		{
			UnityEngine.Debug.LogError("Scene Particles Prefab not set in inspector.");
		}
		if (sceneColorManager != null)
		{
			sceneColorManager.GameInit();
		}
		else
		{
			UnityEngine.Debug.LogError("SceneColorManager not set in inspector.");
		}
		init = true;
	}

	private void StartScene()
	{
		if (!init)
		{
			SetupGameRefs();
		}
		if (gm.IsGameplayScene() || gm.ShouldKeepHUDCameraActive())
		{
			MoveMenuToHUDCamera();
			if (!hudCamera.gameObject.activeSelf)
			{
				hudCamera.gameObject.SetActive(value: true);
			}
		}
		else
		{
			DisableHUDCamIfAllowed();
		}
		if (gm.IsMenuScene())
		{
			cameraController.transform.SetPosition2D(14.6f, 8.5f);
		}
		else if (gm.IsCinematicScene())
		{
			cameraController.transform.SetPosition2D(14.6f, 8.5f);
		}
		else if (gm.IsNonGameplayScene())
		{
			if (gm.IsBossDoorScene())
			{
				cameraController.transform.SetPosition2D(17.5f, 17.5f);
			}
			else if (InGameCutsceneInfo.IsInCutscene)
			{
				cameraController.transform.SetPosition2D(InGameCutsceneInfo.CameraPosition);
			}
			else
			{
				cameraController.transform.SetPosition2D(14.6f, 8.5f);
			}
		}
		cameraController.SceneInit();
		cameraTarget.SceneInit();
		sceneColorManager.SceneInit();
		sceneParticles.SceneInit();
	}

	public void MoveMenuToHUDCamera()
	{
		int cullingMask = mainCamera.cullingMask;
		int cullingMask2 = hudCamera.cullingMask;
		UIManager.instance.UICanvas.worldCamera = hudCamera;
		UIManager.instance.UICanvas.renderMode = RenderMode.ScreenSpaceCamera;
		mainCamera.cullingMask = cullingMask ^ 0x8000000;
		hudCamera.cullingMask = cullingMask2 | 0x8000000;
	}

	public void DisableHUDCamIfAllowed()
	{
		if (gm.IsNonGameplayScene() && !gm.IsStagTravelScene() && !gm.IsBossDoorScene() && !gm.ShouldKeepHUDCameraActive())
		{
			hudCamera.gameObject.SetActive(value: false);
		}
	}

	public void StopCameraShake()
	{
		cameraShakeFSM.Fsm.Event("CANCEL SHAKE");
	}

	public void ResumeCameraShake()
	{
		cameraShakeFSM.Fsm.Event("RESUME SHAKE");
	}

	public void DisableImageEffects()
	{
		mainCamera.GetComponent<FastNoise>().enabled = false;
		mainCamera.GetComponent<BloomOptimized>().enabled = false;
		mainCamera.GetComponent<ColorCorrectionCurves>().enabled = false;
	}

	public void EnableImageEffects(bool isGameplayLevel, bool isBloomForced)
	{
		mainCamera.GetComponent<ColorCorrectionCurves>().enabled = true;
		cameraController.ApplyEffectConfiguration(isGameplayLevel, isBloomForced);
	}

	public void SetOverscan(float value)
	{
		if (!init)
		{
			SetupGameRefs();
		}
		Invoke("TestParentForPosition", 0.33f * Time.timeScale);
		float num = (float)Screen.width / (float)Screen.height;
		if (canvasScaler == null)
		{
			canvasScaler = UIManager.instance.canvasScaler;
		}
		canvasScaler.referenceResolution = new Vector2(1920f * (1f - value) + -220f * value, 1080f * (1f - value) + 1f / num * (-220f * value));
		forceCameraAspect.SetOverscanViewport(value);
		gs.overScanAdjustment = value;
	}

	public void TestParentForPosition()
	{
		if (cameraParent.transform.localPosition.z != 0f)
		{
			cameraParent.transform.localPosition = new Vector3(cameraParent.transform.localPosition.x, cameraParent.transform.localPosition.y, 0f);
		}
	}

	public static GameCameras orig_get_instance()
	{
		if (_instance == null)
		{
			_instance = UnityEngine.Object.FindObjectOfType<GameCameras>();
			if (_instance == null)
			{
				UnityEngine.Debug.LogError("Couldn't find GameCameras, make sure one exists in the scene.");
			}
			UnityEngine.Object.DontDestroyOnLoad(_instance.gameObject);
		}
		return _instance;
	}
}
public class HUDCamera : MonoBehaviour
{
	private GameCameras gc;

	private InputHandler ih;

	private bool shouldEnablePause;

	private void OnEnable()
	{
		if (!gc)
		{
			gc = GameCameras.instance;
		}
		if (!ih)
		{
			ih = GameManager.instance.inputHandler;
		}
		if (ih.pauseAllowed)
		{
			shouldEnablePause = true;
			ih.PreventPause();
		}
		else
		{
			shouldEnablePause = false;
		}
		Invoke("MoveMenuToHUDCamera", 0.5f);
	}

	private void MoveMenuToHUDCamera()
	{
		gc.MoveMenuToHUDCamera();
		if (shouldEnablePause)
		{
			ih.AllowPause();
			shouldEnablePause = false;
		}
	}
}
public class RequestFadeSceneIn : MonoBehaviour
{
	public float waitBeforeFade;

	public CameraFadeInType fadeInSpeed;

	private IEnumerator Start()
	{
		yield return new WaitForSeconds(waitBeforeFade);
		if (fadeInSpeed == CameraFadeInType.SLOW)
		{
			GameCameras.instance.cameraFadeFSM.Fsm.Event("FADE SCENE IN SLOWLY");
		}
		else if (fadeInSpeed == CameraFadeInType.NORMAL)
		{
			GameCameras.instance.cameraFadeFSM.Fsm.Event("FADE SCENE IN");
		}
		else if (fadeInSpeed == CameraFadeInType.INSTANT)
		{
			GameCameras.instance.cameraFadeFSM.Fsm.Event("FADE SCENE IN INSTANT");
		}
	}
}
