	protected bool CheatButton(ref int buttonIndex, string content)
	{
		bool flag = selectedButtonIndex == buttonIndex;
		Rect position = new Rect(25f, 25 + 22 * buttonIndex, 200f, 20f);
		GUI.color = new Color(0f, 0f, 0f, 0.5f);
		GUI.DrawTexture(position, Texture2D.whiteTexture);
		GUI.color = (flag ? Color.white : Color.grey);
		GUI.Label(position, (flag ? "> " : "") + content);
		buttonIndex++;
		if (flag)
		{
			if (Event.current.type != EventType.Repaint || !InputManager.ActiveDevice.Action1.WasPressed)
			{
				if (Event.current.type == EventType.KeyDown)
				{
					return Event.current.keyCode == KeyCode.Z;
				}
				return false;
			}
			return true;
		}
		return false;
	}

	protected bool SafetyCheatButton(ref int buttonIndex, string content)
	{
		int num = ((selectedButtonIndex == buttonIndex) ? safetyCounter : 0);
		if (CheatButton(ref buttonIndex, content + " [" + num + "/" + 10 + "]"))
		{
			if (safetyCounter < 10)
			{
				safetyCounter++;
			}
			return safetyCounter >= 10;
		}
		return false;
	}

	private void Restore()
	{
		GameManager unsafeInstance = GameManager.UnsafeInstance;
		if (unsafeInstance != null)
		{
			HeroController hero_ctrl = unsafeInstance.hero_ctrl;
			if (hero_ctrl != null)
			{
				hero_ctrl.AddHealth(unsafeInstance.playerData.GetInt("maxHealth") - unsafeInstance.playerData.GetInt("health"));
				hero_ctrl.AddMPCharge(unsafeInstance.playerData.GetInt("maxMP") - unsafeInstance.playerData.GetInt("MPCharge"));
			}
		}
	}

	private void Kill()
	{
		GameManager unsafeInstance = GameManager.UnsafeInstance;
		if (unsafeInstance != null)
		{
			HeroController hero_ctrl = unsafeInstance.hero_ctrl;
			if (hero_ctrl != null)
			{
				PlayerData.instance.SetBoolSwappedArgs(value: false, "isInvincible");
				hero_ctrl.TakeDamage(null, CollisionSide.other, 9999, 0);
			}
		}
	}

	private void GetGeo(int amount)
	{
		GameManager unsafeInstance = GameManager.UnsafeInstance;
		if (unsafeInstance != null)
		{
			unsafeInstance.playerData.AddGeo(amount);
		}
	}
}
public class CollisionEnterEvent : MonoBehaviour
{
	public delegate void CollisionEvent(Collision2D collision, GameObject sender);

	public enum Direction
	{
		Left,
		Right,
		Top,
		Bottom
	}

	public delegate void DirectionalCollisionEvent(Direction direction, Collision2D collision);

	public bool checkDirection;

	public bool ignoreTriggers;

	public int otherLayer = 9;

	[HideInInspector]
	public bool doCollisionStay;

	private Collider2D col2d;

	private const float RAYCAST_LENGTH = 0.08f;

	private List<Vector2> topRays;

	private List<Vector2> rightRays;

	private List<Vector2> bottomRays;

	private List<Vector2> leftRays;

	public event CollisionEvent OnCollisionEntered;

	public event DirectionalCollisionEvent OnCollisionEnteredDirectional;

	private void Awake()
	{
		col2d = GetComponent<Collider2D>();
	}

	private void OnCollisionEnter2D(Collision2D collision)
	{
		HandleCollision(collision);
	}

	private void OnCollisionStay2D(Collision2D collision)
	{
		if (doCollisionStay)
		{
			HandleCollision(collision);
		}
	}

	private void HandleCollision(Collision2D collision)
	{
		if (OnCollisionEntered != null)
		{
			OnCollisionEntered(collision, base.gameObject);
		}
		if (checkDirection)
		{
			CheckTouching(otherLayer, collision);
		}
	}

	private void CheckTouching(LayerMask layer, Collision2D collision)
	{
		topRays = new List<Vector2>();
		topRays.Add(new Vector2(col2d.bounds.min.x, col2d.bounds.max.y));
		topRays.Add(new Vector2(col2d.bounds.center.x, col2d.bounds.max.y));
		topRays.Add(col2d.bounds.max);
		rightRays = new List<Vector2>();
		rightRays.Add(col2d.bounds.max);
		rightRays.Add(new Vector2(col2d.bounds.max.x, col2d.bounds.center.y));
		rightRays.Add(new Vector2(col2d.bounds.max.x, col2d.bounds.min.y));
		bottomRays = new List<Vector2>();
		bottomRays.Add(new Vector2(col2d.bounds.max.x, col2d.bounds.min.y));
		bottomRays.Add(new Vector2(col2d.bounds.center.x, col2d.bounds.min.y));
		bottomRays.Add(col2d.bounds.min);
		leftRays = new List<Vector2>();
		leftRays.Add(col2d.bounds.min);
		leftRays.Add(new Vector2(col2d.bounds.min.x, col2d.bounds.center.y));
		leftRays.Add(new Vector2(col2d.bounds.min.x, col2d.bounds.max.y));
		foreach (Vector2 topRay in topRays)
		{
			RaycastHit2D raycastHit2D = Physics2D.Raycast((Vector3)topRay, Vector2.up, 0.08f, 1 << (int)layer);
			if (raycastHit2D.collider != null && (!ignoreTriggers || !raycastHit2D.collider.isTrigger))
			{
				if (OnCollisionEnteredDirectional != null)
				{
					OnCollisionEnteredDirectional(Direction.Top, collision);
				}
				break;
			}
		}
		foreach (Vector2 rightRay in rightRays)
		{
			RaycastHit2D raycastHit2D2 = Physics2D.Raycast((Vector3)rightRay, Vector2.right, 0.08f, 1 << (int)layer);
			if (raycastHit2D2.collider != null && (!ignoreTriggers || !raycastHit2D2.collider.isTrigger))
			{
				if (OnCollisionEnteredDirectional != null)
				{
					OnCollisionEnteredDirectional(Direction.Right, collision);
				}
				break;
			}
		}
		foreach (Vector2 bottomRay in bottomRays)
		{
			RaycastHit2D raycastHit2D3 = Physics2D.Raycast((Vector3)bottomRay, -Vector2.up, 0.08f, 1 << (int)layer);
			if (raycastHit2D3.collider != null && (!ignoreTriggers || !raycastHit2D3.collider.isTrigger))
			{
				if (OnCollisionEnteredDirectional != null)
				{
					OnCollisionEnteredDirectional(Direction.Bottom, collision);
				}
				break;
			}
		}
		foreach (Vector2 leftRay in leftRays)
		{
			RaycastHit2D raycastHit2D4 = Physics2D.Raycast((Vector3)leftRay, -Vector2.right, 0.08f, 1 << (int)layer);
			if (raycastHit2D4.collider != null && (!ignoreTriggers || !raycastHit2D4.collider.isTrigger))
			{
				if (OnCollisionEnteredDirectional != null)
				{
					OnCollisionEnteredDirectional(Direction.Left, collision);
				}
				break;
			}
		}
	}
}
public class ColorFader : MonoBehaviour
{
	public delegate void FadeEndEvent(bool up);

	public Color downColour = new Color(1f, 1f, 1f, 0f);

	public float downTime = 0.5f;

	public Color upColour = new Color(1f, 1f, 1f, 1f);

	public float upDelay;

	public float upTime = 0.4f;

	private Color initialColour;

	public bool useInitialColour = true;

	private SpriteRenderer spriteRenderer;

	private TextMeshPro textRenderer;

	private tk2dSprite tk2dSprite;

	private bool setup;

	private Coroutine fadeRoutine;

	public event FadeEndEvent OnFadeEnd;

	private void Reset()
	{
		PlayMakerFSM[] components = GetComponents<PlayMakerFSM>();
		foreach (PlayMakerFSM playMakerFSM in components)
		{
			if ((playMakerFSM.FsmTemplate ? playMakerFSM.FsmTemplate.name : playMakerFSM.FsmName) == "color_fader")
			{
				downColour = playMakerFSM.FsmVariables.GetFsmColor("Down Colour").Value;
				downTime = playMakerFSM.FsmVariables.GetFsmFloat("Down Time").Value;
				upColour = playMakerFSM.FsmVariables.GetFsmColor("Up Colour").Value;
				upDelay = playMakerFSM.FsmVariables.GetFsmFloat("Up Delay").Value;
				upTime = playMakerFSM.FsmVariables.GetFsmFloat("Up Time").Value;
				break;
			}
		}
	}

	private void Start()
	{
		Setup();
	}

	private void Setup()
	{
		if (setup)
		{
			return;
		}
		setup = true;
		if (!spriteRenderer)
		{
			spriteRenderer = GetComponent<SpriteRenderer>();
		}
		if ((bool)spriteRenderer)
		{
			initialColour = (useInitialColour ? spriteRenderer.color : Color.white);
			spriteRenderer.color = downColour * initialColour;
			return;
		}
		if (!textRenderer)
		{
			textRenderer = GetComponent<TextMeshPro>();
		}
		if ((bool)textRenderer)
		{
			initialColour = (useInitialColour ? textRenderer.color : Color.white);
			textRenderer.color = downColour * initialColour;
			return;
		}
		if (!tk2dSprite)
		{
			tk2dSprite = GetComponent<tk2dSprite>();
		}
		if ((bool)tk2dSprite)
		{
			initialColour = (useInitialColour ? tk2dSprite.color : Color.white);
			tk2dSprite.color = downColour * initialColour;
		}
	}

	public void Fade(bool up)
	{
		Setup();
		if (fadeRoutine != null)
		{
			StopCoroutine(fadeRoutine);
		}
		if (up)
		{
			fadeRoutine = StartCoroutine(Fade(upColour, upTime, upDelay));
		}
		else
		{
			fadeRoutine = StartCoroutine(Fade(downColour, downTime, 0f));
		}
	}

	private IEnumerator Fade(Color to, float time, float delay)
	{
		if (!spriteRenderer)
		{
			spriteRenderer = GetComponent<SpriteRenderer>();
		}
		Color from = (spriteRenderer ? spriteRenderer.color : (textRenderer ? textRenderer.color : (tk2dSprite ? tk2dSprite.color : Color.white)));
		if (delay > 0f)
		{
			yield return new WaitForSeconds(upDelay);
		}
		for (float elapsed = 0f; elapsed < time; elapsed += Time.deltaTime)
		{
			Color color = Color.Lerp(from, to, elapsed / time) * initialColour;
			if ((bool)spriteRenderer)
			{
				spriteRenderer.color = color;
			}
			else if ((bool)textRenderer)
			{
				textRenderer.color = color;
			}
			else if ((bool)tk2dSprite)
			{
				tk2dSprite.color = color;
			}
			yield return null;
		}
		if ((bool)spriteRenderer)
		{
			spriteRenderer.color = to * initialColour;
		}
		else if ((bool)textRenderer)
		{
			textRenderer.color = to * initialColour;
		}
		else if ((bool)tk2dSprite)
		{
			tk2dSprite.color = to * initialColour;
		}
		if (OnFadeEnd != null)
		{
			OnFadeEnd(to == upColour);
		}
	}
}
[ActionCategory("Hollow Knight")]
public class FadeColorFader : FsmStateAction
{
	public enum FadeType
	{
		UP,
		DOWN
	}

	public FsmOwnerDefault target;

	[ObjectType(typeof(FadeType))]
	public FsmEnum fadeType;

	public FsmBool useChildren;

	public override void Reset()
	{
		target = null;
		fadeType = null;
		useChildren = new FsmBool(true);
	}

	public override void OnEnter()
	{
		GameObject safe = target.GetSafe(this);
		if ((bool)safe)
		{
			ColorFader[] array = ((!useChildren.Value) ? new ColorFader[1] { safe.GetComponent<ColorFader>() } : safe.GetComponentsInChildren<ColorFader>());
			ColorFader[] array2 = array;
			for (int i = 0; i < array2.Length; i++)
			{
				array2[i].Fade((FadeType)(object)fadeType.Value == FadeType.UP);
			}
		}
		Finish();
	}
}
