	public void SoulGain()
	{
		int num;
		if (playerData.GetInt("MPCharge") < playerData.GetInt("maxMP"))
		{
			num = 11;
			if (playerData.GetBool("equippedCharm_20"))
			{
				num += 3;
			}
			if (playerData.GetBool("equippedCharm_21"))
			{
				num += 8;
			}
		}
		else
		{
			num = 6;
			if (playerData.GetBool("equippedCharm_20"))
			{
				num += 2;
			}
			if (playerData.GetBool("equippedCharm_21"))
			{
				num += 6;
			}
		}
		int num2 = playerData.GetInt("MPReserve");
		num = ModHooks.OnSoulGain(num);
		playerData.AddMPCharge(num);
		GameCameras.instance.soulOrbFSM.SendEvent("MP GAIN");
		if (playerData.GetInt("MPReserve") != num2)
		{
			gm.soulVessel_fsm.SendEvent("MP RESERVE UP");
		}
	}

