	public void SetDamageMode(int invincibilityType)
	{
		switch (invincibilityType)
		{
		case 0:
			damageMode = DamageMode.FULL_DAMAGE;
			break;
		case 1:
			damageMode = DamageMode.HAZARD_ONLY;
			break;
		case 2:
			damageMode = DamageMode.NO_DAMAGE;
			break;
		}
	}

