		scm.RedA = o_redChannel;
		scm.GreenA = o_greenChannel;
		scm.BlueA = o_blueChannel;
		scm.AmbientColorA = o_ambientColor;
		scm.AmbientIntensityA = o_ambientIntensity;
		SceneManager.SetLighting(o_ambientColor, o_ambientIntensity);
		if (GameManager.instance != null && GameManager.instance.IsGameplayScene())
		{
			scm.HeroLightColorA = o_heroLightColor;
		}
	}
}
[RequireComponent(typeof(PolygonCollider2D))]
public class GradeTrigger : MonoBehaviour
{
	public GradeMarker gradeMarker;

	public bool instantActivate;

	[Range(0.5f, 2f)]
	public float easeTime = 0.8f;

	private void Start()
	{
		if ((bool)gradeMarker)
		{
			gradeMarker.SetStartSizeForTrigger();
			gradeMarker.easeDuration = easeTime;
			gradeMarker.Deactivate();
		}
		else
		{
			UnityEngine.Debug.LogError("No grade marker set for this grade trigger: " + base.name);
		}
	}

	private void OnTriggerEnter2D(Collider2D triggerObject)
	{
		if (triggerObject.tag == "Player")
		{
			if (instantActivate)
			{
				gradeMarker.Activate();
			}
			else
			{
				gradeMarker.ActivateGradual();
			}
		}
	}

	private void OnTriggerExit2D(Collider2D triggerObject)
	{
		if (triggerObject.tag == "Player")
		{
			if (instantActivate)
			{
				gradeMarker.Deactivate();
			}
			else
			{
				gradeMarker.DeactivateGradual();
			}
		}
	}
}
