public class GrassBehaviour : MonoBehaviour
{
	[Header("Animation")]
	public float walkReactAmount = 1f;

	public AnimationCurve walkReactCurve;

	public float walkReactLength;

	[Space]
	public float attackReactAmount = 2f;

	public AnimationCurve attackReactCurve;

	public float attackReactLength;

	[Space]
	public string pushAnim = "Push";

	private Animator animator;

	[Header("Sound")]
	public AudioClip[] pushSounds;

	public AudioClip[] cutPushSounds;

	public AudioClip[] cutSounds;

	private AudioSource source;

	[Header("Extra")]
	public Color infectedColor = Color.white;

	public bool neverInfected;

	private static bool colorSet = false;

	private AnimationCurve curve;

	private float animLength = 2f;

	private float animElapsed;

	private float pushAmount = 1f;

	private float pushDirection;

	private bool returned = true;

	private bool cutFirstFrame;

	private bool isCut;

	private float pushAmountError;

	private Rigidbody2D player;

	private Vector3 oldPlayerPos;

	private SpriteRenderer[] renderers;

	private static Dictionary<string, Material> sharedMaterials = new Dictionary<string, Material>();

	private static int grassCount = 0;

	private Material sharedMaterial;

	private MaterialPropertyBlock propertyBlock;

	public Material SharedMaterial => sharedMaterial;

	private void Awake()
	{
		source = GetComponent<AudioSource>();
		animator = GetComponentInChildren<Animator>();
		propertyBlock = new MaterialPropertyBlock();
	}

	private void Start()
	{
		if (Mathf.Abs(base.transform.position.z - 0.004f) > 1.8f)
		{
			GrassCut component = GetComponent<GrassCut>();
			if ((bool)component)
			{
				UnityEngine.Object.Destroy(component);
			}
			Collider2D[] componentsInChildren = GetComponentsInChildren<Collider2D>();
			for (int i = 0; i < componentsInChildren.Length; i++)
			{
				UnityEngine.Object.Destroy(componentsInChildren[i]);
			}
		}
		renderers = GetComponentsInChildren<SpriteRenderer>(includeInactive: true);
		if (renderers.Length != 0)
		{
			string key = renderers[0].material.name + (neverInfected ? "_neverInfected" : "");
			if (sharedMaterials.ContainsKey(key))
			{
				sharedMaterial = sharedMaterials[key];
			}
			if (!sharedMaterial)
			{
				sharedMaterial = new Material(renderers[0].material);
				sharedMaterials[key] = sharedMaterial;
			}
		}
		SpriteRenderer[] array;
		if ((bool)sharedMaterial)
		{
			array = renderers;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].sharedMaterial = sharedMaterial;
			}
		}
		if (!colorSet && !neverInfected)
		{
			StartCoroutine(DelayedInfectedCheck());
		}
		pushAmountError = UnityEngine.Random.Range(-0.01f, 0.01f);
		array = renderers;
		foreach (Renderer rend in array)
		{
			SetPushAmount(rend, pushAmountError);
		}
		base.transform.SetPositionZ(base.transform.position.z + UnityEngine.Random.Range(-0.0001f, 0.0001f));
	}

	private void OnEnable()
	{
		grassCount++;
	}

	private void OnDisable()
	{
		grassCount--;
		if (colorSet)
		{
			colorSet = false;
			sharedMaterial = null;
		}
		if (grassCount <= 0)
		{
			sharedMaterials.Clear();
		}
	}

	private IEnumerator DelayedInfectedCheck()
	{
		yield return null;
		if ((bool)sharedMaterial && (bool)GameObject.FindWithTag("Infected Flag"))
		{
			colorSet = true;
			sharedMaterial.color = infectedColor;
			SpriteRenderer[] array = renderers;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].sharedMaterial = sharedMaterial;
			}
		}
	}

	private void LateUpdate()
	{
		if (returned)
		{
			return;
		}
		float value = curve.Evaluate(animElapsed / animLength) * pushAmount * pushDirection * Mathf.Sign(base.transform.localScale.x) + pushAmountError;
		SpriteRenderer[] array = renderers;
		foreach (SpriteRenderer rend in array)
		{
			SetPushAmount(rend, value);
		}
		if (animElapsed >= animLength)
		{
			returned = true;
			if ((bool)animator && animator.HasParameter(pushAnim, AnimatorControllerParameterType.Bool))
			{
				animator.SetBool(pushAnim, value: false);
			}
		}
		animElapsed += Time.deltaTime;
	}

	private void FixedUpdate()
	{
		if (!player || !returned || !(Mathf.Abs(player.velocity.x) >= 0.1f))
		{
			return;
		}
		pushDirection = Mathf.Sign(player.velocity.x);
		returned = false;
		animElapsed = 0f;
		pushAmount = walkReactAmount;
		curve = walkReactCurve;
		animLength = walkReactLength;
		PlayRandomSound(isCut ? cutPushSounds : pushSounds);
		if ((bool)animator)
		{
			if (animator.HasParameter(pushAnim, AnimatorControllerParameterType.Bool))
			{
				animator.SetBool(pushAnim, value: true);
			}
			else if (animator.HasParameter(pushAnim, AnimatorControllerParameterType.Trigger))
			{
				animator.SetTrigger(pushAnim);
			}
		}
	}

	private void OnTriggerEnter2D(Collider2D collision)
	{
		if (!returned)
		{
			return;
		}
		pushDirection = Mathf.Sign(base.transform.position.x - collision.transform.position.x);
		returned = false;
		animElapsed = 0f;
		if (GrassCut.ShouldCut(collision))
		{
			pushAmount = attackReactAmount;
			curve = attackReactCurve;
			animLength = attackReactLength;
			PlayRandomSound(isCut ? cutPushSounds : pushSounds);
		}
		else
		{
			pushAmount = walkReactAmount;
			curve = walkReactCurve;
			animLength = walkReactLength;
			if (collision.tag == "Player")
			{
				player = collision.GetComponent<Rigidbody2D>();
			}
			PlayRandomSound(isCut ? cutPushSounds : pushSounds);
		}
		if ((bool)animator && animator.HasParameter(pushAnim))
		{
			animator.SetBool(pushAnim, value: true);
		}
	}

	private void OnTriggerExit2D(Collider2D collision)
	{
		if (collision.tag == "Player")
		{
			player = null;
		}
	}

	public void CutReact(Collider2D collision)
	{
		if (!isCut)
		{
			pushDirection = Mathf.Sign(base.transform.position.x - collision.transform.position.x);
			returned = false;
			animElapsed = 0f;
			cutFirstFrame = true;
			pushAmount = attackReactAmount;
			curve = attackReactCurve;
			animLength = attackReactLength;
		}
		PlayRandomSound(cutSounds);
		isCut = true;
	}

	public void WindReact(Collider2D collision)
	{
		if (returned)
		{
			pushDirection = Mathf.Sign(base.transform.position.x - collision.transform.position.x);
			returned = false;
			animElapsed = 0f;
			pushAmount = walkReactAmount;
			curve = walkReactCurve;
			animLength = walkReactLength;
			PlayRandomSound(isCut ? cutPushSounds : pushSounds);
		}
	}

	private void PlayRandomSound(AudioClip[] clips)
	{
		if ((bool)source && clips.Length != 0)
		{
			AudioClip clip = clips[UnityEngine.Random.Range(0, clips.Length)];
			source.PlayOneShot(clip);
		}
	}

	private void SetPushAmount(Renderer rend, float value)
	{
		rend.GetPropertyBlock(propertyBlock);
		propertyBlock.SetFloat("_PushAmount", value);
		rend.SetPropertyBlock(propertyBlock);
	}
}
public class GrassCut : MonoBehaviour
{
	public SpriteRenderer[] disable;

	public SpriteRenderer[] enable;

	[Space]
	public Collider2D[] disableColliders;

	public Collider2D[] enableColliders;

	[Space]
	public GameObject particles;

	public GameObject cutEffectPrefab;

	private Collider2D col;

	private void Awake()
	{
		col = GetComponent<Collider2D>();
	}

	private void OnTriggerEnter2D(Collider2D collision)
	{
		if (!ShouldCut(collision))
		{
			return;
		}
		GrassBehaviour componentInParent = GetComponentInParent<GrassBehaviour>();
		SpriteRenderer[] array = disable;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].enabled = false;
		}
		array = enable;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].enabled = true;
		}
		Collider2D[] array2 = disableColliders;
		for (int i = 0; i < array2.Length; i++)
		{
			array2[i].enabled = false;
		}
		array2 = enableColliders;
		for (int i = 0; i < array2.Length; i++)
		{
			array2[i].enabled = true;
		}
		if ((bool)particles)
		{
			Renderer component = particles.GetComponent<Renderer>();
			if ((bool)component && (bool)componentInParent)
			{
				component.material.color = componentInParent.SharedMaterial.color;
			}
			particles.SetActive(value: true);
			particles.transform.position = new Vector3(particles.transform.position.x, particles.transform.position.y, particles.transform.position.z);
		}
		if ((bool)componentInParent)
		{
			componentInParent.CutReact(collision);
		}
		if ((bool)cutEffectPrefab)
		{
			Vector3 position = (collision.bounds.center + col.bounds.center) / 2f;
			float num = Mathf.Sign(base.transform.position.x - collision.transform.position.x);
			cutEffectPrefab.Spawn(position);
			cutEffectPrefab.transform.SetScaleX((0f - num) * 0.6f);
			cutEffectPrefab.transform.SetScaleY(1f);
		}
		UnityEngine.Object.Destroy(this);
	}

	public static bool ShouldCut(Collider2D collision)
	{
		if (!(collision.tag == "Nail Attack") && (!(collision.tag == "HeroBox") || !HeroController.instance.cState.superDashing))
		{
			return collision.tag == "Sharp Shadow";
		}
		return true;
	}
}
public class GrassSpriteBehaviour : MonoBehaviour
{
	[Header("Variables")]
	public bool isWindy;

	public bool noPushAnimation;

	[Space]
	public GameObject deathParticles;

	public GameObject deathParticlesWindy;

	public GameObject cutEffectPrefab;

	[Space]
	public AudioClip[] pushSounds;

	public AudioClip[] cutSounds;

	[Header("Animation State Names")]
	public string idleAnimation = "Idle";

	public string pushAnimation = "Push";

	public string cutAnimation = "Dead";

	[Space]
	public string idleWindyAnimation = "WindyIdle";

	public string pushWindyAnimation = "WindyPush";

	private bool isCut;

	private bool interaction = true;

	private bool visible;

	private Animator animator;

	private AudioSource source;

	private void Awake()
	{
		animator = GetComponent<Animator>();
		source = GetComponent<AudioSource>();
	}

	private void Start()
	{
		if (Mathf.Abs(base.transform.position.z - 0.004f) > 1.8f)
		{
			interaction = false;
		}
		Init();
	}

	private void OnBecameVisible()
	{
		visible = true;
	}

	private void OnBecameInvisible()
	{
		visible = false;
	}

	private void OnTriggerEnter2D(Collider2D collision)
	{
		if (isCut || !interaction || !visible)
		{
			return;
		}
		if (GrassCut.ShouldCut(collision))
		{
			animator.Play(cutAnimation);
			isCut = true;
			if (isWindy && (bool)deathParticlesWindy)
			{
				deathParticlesWindy.SetActive(value: true);
			}
			else if ((bool)deathParticles)
			{
				deathParticles.SetActive(value: true);
			}
			if ((bool)source && cutSounds.Length != 0)
			{
				source.PlayOneShot(cutSounds[UnityEngine.Random.Range(0, cutSounds.Length)]);
			}
			if ((bool)cutEffectPrefab)
			{
				int num = (int)Mathf.Sign(collision.transform.position.x - base.transform.position.x);
				Vector3 position = (collision.transform.position + base.transform.position) / 2f;
				GameObject obj = cutEffectPrefab.Spawn(position);
				Vector3 localScale = obj.transform.localScale;
				localScale.x = Mathf.Abs(localScale.x) * (float)(-num);
				obj.transform.localScale = localScale;
			}
		}
		else
		{
			if (!noPushAnimation)
			{
				animator.Play(isWindy ? pushWindyAnimation : pushAnimation);
			}
			if ((bool)source && pushSounds.Length != 0)
			{
				source.PlayOneShot(pushSounds[UnityEngine.Random.Range(0, pushSounds.Length)]);
			}
		}
	}

	private void Init()
	{
		animator.Play(isWindy ? idleWindyAnimation : idleAnimation);
	}

	public void SetWindy()
	{
		if (!isCut)
		{
			isWindy = true;
			noPushAnimation = true;
			Init();
		}
	}

	public void SetNotWindy()
	{
		if (!isCut)
		{
			isWindy = false;
			noPushAnimation = false;
			Init();
		}
	}
}
public class GrassWind : MonoBehaviour
{
	private Collider2D col;

	private void Awake()
	{
		col = GetComponent<Collider2D>();
	}

	private void OnTriggerEnter2D(Collider2D collision)
	{
		if (collision.tag == "Nail Attack")
		{
			GrassBehaviour componentInParent = GetComponentInParent<GrassBehaviour>();
			if ((bool)componentInParent)
			{
				StartCoroutine(DelayReact(componentInParent, collision));
			}
		}
	}

	private IEnumerator DelayReact(GrassBehaviour behaviour, Collider2D collision)
	{
		yield return null;
		behaviour.WindReact(collision);
	}
}
