public class SceneryTriggerCircle : MonoBehaviour
{
	private Animator animator;

	private CircleCollider2D[] col2ds;

	private int enterCount;

	public AudioSource audioSource;

	public AudioClip activateSound;

	public AudioClip deactivateSound;

	public bool active { get; private set; }

	private void Awake()
	{
		col2ds = GetComponentsInChildren<CircleCollider2D>();
		animator = GetComponentInChildren<Animator>();
		if (col2ds.Length > 2 || col2ds.Length < 2)
		{
			UnityEngine.Debug.LogError("Scenery Trigger requires exactly two Collider components attached to work correctly.");
			base.gameObject.SetActive(value: false);
		}
	}

	private void OnTriggerEnter2D(Collider2D other)
	{
		if (other.gameObject.layer != 9)
		{
			return;
		}
		if (enterCount == 0)
		{
			enterCount = 1;
		}
		else if (enterCount == 1)
		{
			active = true;
			animator.Play("Show");
			if (activateSound != null && audioSource != null)
			{
				RandomizePitch(audioSource, 0.85f, 1.15f);
				audioSource.PlayOneShot(activateSound);
			}
			enterCount = 2;
		}
	}

	private void OnTriggerStay2D(Collider2D other)
	{
		if (other.gameObject.layer == 9 && enterCount == 0)
		{
			enterCount = 1;
		}
	}

	private void OnTriggerExit2D(Collider2D other)
	{
		if (other.gameObject.layer != 9)
		{
			return;
		}
		if (enterCount == 1)
		{
			active = false;
			animator.Play("Hide");
			if (deactivateSound != null && audioSource != null)
			{
				RandomizePitch(audioSource, 0.85f, 1.15f);
				audioSource.PlayOneShot(deactivateSound);
			}
			enterCount = 0;
		}
		else if (enterCount == 2)
		{
			enterCount = 1;
		}
	}

	private void RandomizePitch(AudioSource src, float minPitch, float maxPitch)
	{
		float pitch = UnityEngine.Random.Range(minPitch, maxPitch);
		src.pitch = pitch;
	}

	private void ResetPitch(AudioSource src)
	{
		src.pitch = 1f;
	}
}
public class SoftLandEffect : MonoBehaviour
{
	public GameObject dustEffects;

	public GameObject grassEffects;

	public GameObject boneEffects;

	public GameObject splash;

	public AudioClip softLandClip;

	public AudioClip wetLandClip;

	private PlayerData pd;

	private GameObject heroObject;

	private AudioSource audioSource;

	private Rigidbody2D heroRigidBody;

	private tk2dSpriteAnimator jumpPuffAnimator;

	private float recycleTimer;

	private void OnEnable()
	{
		if (pd == null)
		{
			pd = GameManager.instance.playerData;
		}
		if (audioSource == null)
		{
			audioSource = base.gameObject.GetComponent<AudioSource>();
		}
		foreach (Transform item in base.transform)
		{
			item.gameObject.SetActive(value: false);
		}
		recycleTimer = 1f;
		HeroController instance = HeroController.instance;
		if (!(instance != null) || !instance.isHeroInPosition)
		{
			return;
		}
		switch (pd.GetInt("environmentType"))
		{
		case 1:
			grassEffects.SetActive(value: true);
			audioSource.PlayOneShot(softLandClip);
			break;
		case 2:
			boneEffects.SetActive(value: true);
			audioSource.PlayOneShot(softLandClip);
			break;
		case 3:
			audioSource.PlayOneShot(wetLandClip);
			break;
		case 6:
			audioSource.PlayOneShot(wetLandClip);
			splash.SetActive(value: true);
			if (UnityEngine.Random.Range(1, 100) > 50)
			{
				splash.transform.localScale = new Vector3(0f - splash.transform.localScale.x, splash.transform.localScale.y, splash.transform.localScale.z);
			}
			break;
		default:
			dustEffects.SetActive(value: true);
			audioSource.PlayOneShot(softLandClip);
			break;
		case 5:
			break;
		}
	}

	private void Update()
	{
		if (recycleTimer <= 0f)
		{
			base.gameObject.Recycle();
		}
		else
		{
			recycleTimer -= Time.deltaTime;
		}
	}
}
