		}
	}

	protected void Start()
	{
		direction = ((Vector2)base.transform.right).normalized;
		entryDust.transform.parent = null;
		if (entry != null)
		{
			entryPoint = entry.transform.position;
			entryDust.transform.SetPosition2D(entry.transform.position);
		}
		else
		{
			entryPoint = (Vector2)base.transform.position - direction * 12f;
		}
		exitDust.transform.parent = null;
		if (exit != null)
		{
			exitPoint = exit.transform.position;
			exitDust.transform.SetPosition2D(exit.transform.position);
		}
		else
		{
			exitPoint = (Vector2)base.transform.position + direction * 6f;
		}
		UnBurrow(changePosition: false);
	}

	private void UnBurrow(bool changePosition)
	{
		entryDust.Play();
		isBurrowing = false;
		if (changePosition)
		{
			base.transform.SetPosition2D(entryPoint - direction * 2.6f);
		}
		exitDust.Stop();
		meshRenderer.enabled = true;
		audioSource.volume = 0f;
		fadingAudio = true;
	}

	private void Burrow()
	{
		exitDust.Play();
		isBurrowing = true;
		burrowTimer = 0f;
		meshRenderer.enabled = false;
	}

	protected void FixedUpdate()
	{
		body.MovePosition(body.position + direction * moveSpeed * Time.fixedDeltaTime);
	}

	protected void Update()
	{
		Vector2 lhs = base.transform.position;
		if (!isBurrowing)
		{
			if (Vector2.Dot(lhs, direction) > Vector2.Dot(exitPoint, direction))
			{
				Burrow();
			}
		}
		else
		{
			burrowTimer += Time.deltaTime;
			if (burrowTimer > burrowTime)
			{
				UnBurrow(changePosition: true);
			}
		}
		if (fadingAudio)
		{
			audioSource.volume += Time.deltaTime * 1.5f;
			if (audioSource.volume > 1f)
			{
				audioSource.volume = 1f;
				fadingAudio = false;
			}
		}
	}
}
public class BigCentipedeSection : MonoBehaviour
{
	private BigCentipede parent;

	private MeshRenderer meshRenderer;

	private Collider2D bodyCollider;

	private bool hasLeft;

	protected void Awake()
	{
		parent = GetComponentInParent<BigCentipede>();
		meshRenderer = GetComponent<MeshRenderer>();
	}

	protected void Update()
	{
		Vector2 lhs = base.transform.position;
		if (!hasLeft)
		{
			if (Vector2.Dot(lhs, parent.Direction) > Vector2.Dot(parent.ExitPoint, parent.Direction))
			{
				meshRenderer.enabled = false;
				hasLeft = true;
			}
		}
		else if (Vector2.Dot(lhs, parent.Direction) > Vector2.Dot(parent.EntryPoint, parent.Direction) - 1.75f && Vector2.Dot(lhs, parent.Direction) < Vector2.Dot(parent.ExitPoint, parent.Direction))
		{
			meshRenderer.enabled = true;
			hasLeft = false;
		}
	}
}
public class BrokenVesselGlob : MonoBehaviour
{
	public ParticleSystem gasParticle;

	public Rigidbody2D rb;

	private float timer;

	private Vector2 force = new Vector2(0f, 25f);

	private float stretchFactor = 2f;

	private float stretchMinX = 1f;

	private float stretchMaxY = 2f;

	private float scaleModifier = 2f;

	private float scaleModifierMin = 2f;

	private float scaleModifierMax = 2f;

	private void OnEnable()
	{
		base.transform.localScale = new Vector3(2f, 2f, 2f);
		gasParticle.Play();
		rb.velocity = new Vector3(rb.velocity.x, -17.5f);
		timer = 5f;
	}

	private void Update()
	{
		FaceAngle();
		ProjectileSquash();
		if (timer >= 0f)
		{
			timer -= Time.deltaTime;
		}
		else
		{
			base.gameObject.Recycle();
		}
	}

	private void FixedUpdate()
	{
		rb.AddForce(force);
	}

	private void FaceAngle()
	{
		Vector2 velocity = rb.velocity;
		float z = Mathf.Atan2(velocity.y, velocity.x) * (180f / (float)Math.PI);
		base.transform.localEulerAngles = new Vector3(0f, 0f, z);
	}

	private void ProjectileSquash()
	{
		float num = 1f - rb.velocity.magnitude * stretchFactor * 0.01f;
		float num2 = 1f + rb.velocity.magnitude * stretchFactor * 0.01f;
		if (num2 < stretchMinX)
		{
			num2 = stretchMinX;
		}
		if (num > stretchMaxY)
		{
			num = stretchMaxY;
		}
		num *= scaleModifier;
		num2 *= scaleModifier;
		base.transform.localScale = new Vector3(num2, num, base.transform.localScale.z);
	}
}
public class Climber : MonoBehaviour
{
	private enum Direction
	{
		Right,
		Down,
		Left,
		Up
	}

	public bool startRight = true;

	private bool clockwise = true;

	public float speed = 2f;

	public float spinTime = 0.25f;

	[Space]
	public float wallRayPadding = 0.1f;

	[Space]
	public Vector2 constrain = new Vector2(0.1f, 0.1f);

	private Vector2 previousPos;

	public float minTurnDistance = 0.25f;

	private Vector2 previousTurnPos;

	private Direction currentDirection;

	private Coroutine turnRoutine;

	private Rigidbody2D body;

	private BoxCollider2D col;

	private tk2dSpriteAnimator anim;

	private void Awake()
	{
		body = GetComponent<Rigidbody2D>();
		col = GetComponent<BoxCollider2D>();
		anim = GetComponent<tk2dSpriteAnimator>();
	}

	private void Start()
	{
		StickToGround();
		float num = Mathf.Sign(base.transform.localScale.x);
		if (!startRight)
		{
			num *= -1f;
		}
		clockwise = num > 0f;
		float num2 = base.transform.eulerAngles.z % 360f;
		if (num2 >= 45f && num2 <= 135f)
		{
			currentDirection = ((!clockwise) ? Direction.Down : Direction.Up);
		}
		else if (num2 >= 135f && num2 <= 225f)
		{
			currentDirection = (clockwise ? Direction.Left : Direction.Right);
		}
		else if (num2 >= 225f && num2 <= 315f)
		{
			currentDirection = (clockwise ? Direction.Down : Direction.Up);
		}
		else
		{
			currentDirection = ((!clockwise) ? Direction.Left : Direction.Right);
		}
		Recoil component = GetComponent<Recoil>();
		if ((bool)component)
		{
			component.SkipFreezingByController = true;
			component.OnHandleFreeze += Stun;
		}
		previousPos = base.transform.position;
		StartCoroutine(Walk());
	}

	private IEnumerator Walk()
	{
		anim.Play("Walk");
		body.velocity = GetVelocity(currentDirection);
		while (true)
		{
			Vector2 vector = transform.position;
			bool flag = false;
			if (Mathf.Abs(vector.x - previousPos.x) > constrain.x)
			{
				vector.x = previousPos.x;
				flag = true;
			}
			if (Mathf.Abs(vector.y - previousPos.y) > constrain.y)
			{
				vector.y = previousPos.y;
				flag = true;
			}
			if (flag)
			{
				transform.position = vector;
			}
			else
			{
				previousPos = transform.position;
			}
			if (Vector3.Distance(previousTurnPos, transform.position) >= minTurnDistance)
			{
				if (!CheckGround())
				{
					turnRoutine = StartCoroutine(Turn(clockwise));
					yield return turnRoutine;
				}
				else if (CheckWall())
				{
					turnRoutine = StartCoroutine(Turn(!clockwise, tweenPos: true));
					yield return turnRoutine;
				}
			}
			yield return null;
		}
	}

	private IEnumerator Turn(bool turnClockwise, bool tweenPos = false)
	{
		body.velocity = Vector2.zero;
		float currentRotation = transform.eulerAngles.z;
		float targetRotation = currentRotation + (float)(turnClockwise ? (-90) : 90);
		Vector3 currentPos = transform.position;
		Vector3 targetPos = currentPos + (Vector3)GetTweenPos(currentDirection);
		for (float elapsed = 0f; elapsed < spinTime; elapsed += Time.deltaTime)
		{
			float t = elapsed / spinTime;
			transform.SetRotation2D(Mathf.Lerp(currentRotation, targetRotation, t));
			if (tweenPos)
			{
				transform.position = Vector3.Lerp(currentPos, targetPos, t);
			}
			yield return null;
		}
		transform.SetRotation2D(targetRotation);
		int num = (int)currentDirection;
		num += (turnClockwise ? 1 : (-1));
		int num2 = Enum.GetNames(typeof(Direction)).Length;
		if (num < 0)
		{
			num = num2 - 1;
		}
		else if (num >= num2)
		{
			num = 0;
		}
		currentDirection = (Direction)num;
		body.velocity = GetVelocity(currentDirection);
		previousPos = transform.position;
		previousTurnPos = previousPos;
		turnRoutine = null;
	}

	private Vector2 GetVelocity(Direction direction)
	{
		Vector2 result = Vector2.zero;
		switch (direction)
		{
		case Direction.Right:
			result = new Vector2(speed, 0f);
			break;
		case Direction.Down:
			result = new Vector2(0f, 0f - speed);
			break;
		case Direction.Left:
			result = new Vector2(0f - speed, 0f);
			break;
		case Direction.Up:
			result = new Vector2(0f, speed);
			break;
		}
		return result;
	}

	private bool CheckGround()
	{
		return FireRayLocal(Vector2.down, 1f).collider != null;
	}

	private bool CheckWall()
	{
		return FireRayLocal(clockwise ? Vector2.right : Vector2.left, col.size.x / 2f + wallRayPadding).collider != null;
	}

	public void Stun()
	{
		if (turnRoutine == null)
		{
			StopAllCoroutines();
			StartCoroutine(DoStun());
		}
	}

	private IEnumerator DoStun()
	{
		body.velocity = Vector2.zero;
		yield return StartCoroutine(anim.PlayAnimWait("Stun"));
		StartCoroutine(Walk());
	}

	private RaycastHit2D FireRayLocal(Vector2 direction, float length)
	{
		Vector2 vector = base.transform.TransformPoint(col.offset);
		Vector2 vector2 = base.transform.TransformDirection(direction);
		RaycastHit2D result = Physics2D.Raycast(vector, vector2, length, 256);
		UnityEngine.Debug.DrawRay(vector, vector2);
		return result;
	}

	private Vector2 GetTweenPos(Direction direction)
	{
		Vector2 result = Vector2.zero;
		switch (direction)
		{
		case Direction.Right:
			result = (clockwise ? new Vector2(col.size.x / 2f, col.size.y / 2f) : new Vector2(col.size.x / 2f, 0f - col.size.y / 2f));
			result.x += wallRayPadding;
			break;
		case Direction.Up:
			result = (clockwise ? new Vector2(0f - col.size.x / 2f, col.size.y / 2f) : new Vector2(col.size.x / 2f, col.size.y / 2f));
			result.y += wallRayPadding;
			break;
		case Direction.Down:
			result = (clockwise ? new Vector2(col.size.x / 2f, 0f - col.size.y / 2f) : new Vector2(0f - col.size.x / 2f, 0f - col.size.y / 2f));
			result.y -= wallRayPadding;
			break;
		case Direction.Left:
			result = (clockwise ? new Vector2(0f - col.size.x / 2f, 0f - col.size.y / 2f) : new Vector2(0f - col.size.x / 2f, col.size.y / 2f));
			result.x -= wallRayPadding;
			break;
		}
		return result;
	}

	private void StickToGround()
	{
		RaycastHit2D raycastHit2D = FireRayLocal(Vector2.down, 2f);
		if (raycastHit2D.collider != null)
		{
			base.transform.position = raycastHit2D.point;
		}
	}
}
public class ConstrainPosition : MonoBehaviour
{
	public bool constrainX;

	public float xMin;

	public float xMax;

	public bool constrainY;

	public float yMin;

	public float yMax;

	private void Update()
	{
		Vector3 position = base.transform.position;
		bool flag = false;
		if (constrainX)
		{
			if (position.x < xMin)
			{
				position.x = xMin;
				flag = true;
			}
			else if (position.x > xMax)
			{
				position.x = xMax;
				flag = true;
			}
		}
		if (constrainY)
		{
			if (position.y < yMin)
			{
				position.y = yMin;
				flag = true;
			}
			else if (position.y > yMax)
			{
				position.y = yMax;
				flag = true;
			}
		}
		if (flag)
		{
			base.transform.position = position;
		}
	}
}
public class Corpse : MonoBehaviour
{
	private enum States
	{
		NotStarted,
		InAir,
		DeathAnimation,
		Complete,
		PendingLandEffects
	}

	protected MeshRenderer meshRenderer;

	protected tk2dSprite sprite;

	protected tk2dSpriteAnimator spriteAnimator;

	protected SpriteFlash spriteFlash;

	protected Rigidbody2D body;

	protected Collider2D bodyCollider;

	[SerializeField]
	protected ParticleSystem corpseFlame;

	[SerializeField]
	protected ParticleSystem corpseSteam;

	[SerializeField]
	protected GameObject landEffects;

	[SerializeField]
	protected AudioSource audioPlayerPrefab;

	[SerializeField]
	protected GameObject deathWaveInfectedPrefab;

	[SerializeField]
	protected GameObject spatterOrangePrefab;

	[SerializeField]
	protected RandomAudioClipTable splatAudioClipTable;

	[SerializeField]
	private int smashBounces;

	[SerializeField]
	private bool breaker;

	[SerializeField]
	private bool bigBreaker;

	[SerializeField]
	private bool chunker;

	[SerializeField]
	private bool deathStun;

	[SerializeField]
	private bool fungusExplode;

	[SerializeField]
	private bool goopExplode;

	[SerializeField]
	private bool hatcher;

	[SerializeField]
	private bool instantChunker;

	[SerializeField]
	private bool massless;

	[SerializeField]
	private bool resetRotation;

	[SerializeField]
	private AudioEvent startAudio;

	[SerializeField]
	private bool spineBurst;

	[SerializeField]
	private bool zomHive;

	private bool noSteam;

	protected bool spellBurn;

	protected bool hitAcid;

	private States state;

	private bool bouncedThisFrame;

	private int bounceCount;

	private float landEffectsDelayRemaining;

	private void Awake()
	{
		meshRenderer = GetComponent<MeshRenderer>();
		sprite = GetComponent<tk2dSprite>();
		spriteAnimator = GetComponent<tk2dSpriteAnimator>();
		spriteFlash = GetComponent<SpriteFlash>();
		body = GetComponent<Rigidbody2D>();
		bodyCollider = GetComponent<Collider2D>();
	}

	public void Setup(bool noSteam, bool spellBurn)
	{
		this.noSteam = noSteam;
		this.spellBurn = spellBurn;
	}

	protected virtual void Start()
	{
		startAudio.SpawnAndPlayOneShot(audioPlayerPrefab, base.transform.position);
		if (resetRotation)
		{
			base.transform.SetRotation2D(0f);
		}
		if (noSteam && corpseSteam != null)
		{
			corpseSteam.gameObject.SetActive(value: false);
		}
		if (spellBurn)
		{
			if (sprite != null)
			{
				sprite.color = new Color(10f / 51f, 10f / 51f, 10f / 51f, 1f);
			}
			if (corpseFlame != null)
			{
				corpseFlame.Play();
			}
		}
		if (massless)
		{
			state = States.DeathAnimation;
		}
		else
		{
			state = States.InAir;
			if (spriteAnimator != null)
			{
				tk2dSpriteAnimationClip clipByName = spriteAnimator.GetClipByName("Death Air");
				if (clipByName != null)
				{
					spriteAnimator.Play(clipByName);
				}
			}
		}
		if (instantChunker && !breaker)
		{
			Land();
		}
		if (GameManager.instance.GetCurrentMapZone() == "COLOSSEUM")
		{
			StartCoroutine(DropThroughFloor());
		}
		StartCoroutine(DisableFlame());
	}

	protected void Update()
	{
		if (state == States.DeathAnimation)
		{
			if (spriteAnimator == null || !spriteAnimator.Playing)
			{
				Complete(detachChildren: true, destroyMe: true);
			}
		}
		else if (state == States.InAir)
		{
			bouncedThisFrame = false;
			if (base.transform.position.y < -10f)
			{
				Complete(detachChildren: true, destroyMe: true);
			}
		}
		else if (state == States.PendingLandEffects)
		{
			landEffectsDelayRemaining -= Time.deltaTime;
			if (landEffectsDelayRemaining <= 0f)
			{
				Complete(detachChildren: false, destroyMe: false);
			}
		}
	}

	private void Complete(bool detachChildren, bool destroyMe)
	{
		state = States.Complete;
		base.enabled = false;
		if (corpseSteam != null)
		{
			corpseSteam.Stop();
		}
		if (corpseFlame != null)
		{
			corpseFlame.Stop();
		}
		if (detachChildren)
		{
			base.transform.DetachChildren();
		}
		if (destroyMe)
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}
	}

	protected void OnCollisionEnter2D(Collision2D collision)
	{
		OnCollision(collision);
	}

	protected void OnCollisionStay2D(Collision2D collision)
	{
		OnCollision(collision);
	}

	private void OnCollision(Collision2D collision)
	{
		if (state == States.InAir && new Sweep(bodyCollider, 3, 3).Check(base.transform.position, 0.08f, 256, out var _))
		{
			Land();
		}
	}

	private void Land()
	{
		if (breaker)
		{
			if (!bouncedThisFrame)
			{
				bounceCount++;
				bouncedThisFrame = true;
				if (bounceCount >= smashBounces)
				{
					Smash();
				}
			}
			return;
		}
		if (spriteAnimator != null && !hitAcid)
		{
			tk2dSpriteAnimationClip clipByName = spriteAnimator.GetClipByName("Death Land");
			if (clipByName != null)
			{
				spriteAnimator.Play(clipByName);
			}
		}
		landEffectsDelayRemaining = 1f;
		if (landEffects != null)
		{
			landEffects.SetActive(value: true);
		}
		state = States.PendingLandEffects;
		if (!hitAcid)
		{
			LandEffects();
		}
	}

	protected virtual void LandEffects()
	{
	}

	protected virtual void Smash()
	{
		if (!hitAcid)
		{
			GlobalPrefabDefaults.Instance.SpawnBlood(base.transform.position, 6, 8, 10f, 20f, 75f, 105f);
		}
		splatAudioClipTable.SpawnAndPlayOneShot(audioPlayerPrefab, base.transform.position);
		if (corpseFlame != null)
		{
			corpseFlame.Stop();
		}
		if (corpseSteam != null)
		{
			corpseSteam.Stop();
		}
		if (spriteAnimator != null)
		{
			spriteAnimator.Play("Death Land");
		}
		body.velocity = Vector2.zero;
		state = States.DeathAnimation;
		if (bigBreaker)
		{
			if (!hitAcid)
			{
				GlobalPrefabDefaults.Instance.SpawnBlood(base.transform.position, 30, 30, 20f, 30f, 80f, 100f);
			}
			GameCameras instance = GameCameras.instance;
			if ((bool)instance)
			{
				instance.cameraShakeFSM.SendEvent("EnemyKillShake");
			}
		}
	}

	public void Acid()
	{
		hitAcid = true;
		if ((bool)corpseFlame)
		{
			corpseFlame.Stop();
		}
		if ((bool)corpseSteam)
		{
			corpseSteam.Stop();
		}
		Land();
	}

	private IEnumerator DropThroughFloor()
	{
		yield return new WaitForSeconds(UnityEngine.Random.Range(3f, 6f));
		Collider2D[] componentsInChildren = GetComponentsInChildren<Collider2D>();
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			componentsInChildren[i].enabled = false;
		}
		if ((bool)body)
		{
			body.isKinematic = false;
		}
		yield return new WaitForSeconds(1f);
		gameObject.SetActive(value: false);
	}

	private IEnumerator DisableFlame()
	{
		yield return new WaitForSeconds(5f);
		if ((bool)corpseFlame)
		{
			corpseFlame.Stop();
		}
	}
}
public class CorpseBitEnd : MonoBehaviour
{
	public float timer;

	private bool stopped;

	private void Update()
	{
		if (timer <= 0f && !stopped)
		{
			Rigidbody2D component = GetComponent<Rigidbody2D>();
			if ((bool)component)
			{
				component.isKinematic = true;
			}
			component.velocity = new Vector2(0f, 0f);
			component.angularVelocity = 0f;
			GetComponent<ObjectBounce>().StopBounce();
			GetComponent<PolygonCollider2D>().enabled = false;
			stopped = true;
		}
		else
		{
			timer -= Time.deltaTime;
		}
	}
}
public class CorpseChunker : Corpse
{
	[Header("Chunker Variables")]
	public GameObject effects;

	public GameObject chunks;

	protected override void LandEffects()
	{
		if ((bool)body)
		{
			body.velocity = Vector2.zero;
		}
		splatAudioClipTable.SpawnAndPlayOneShot(audioPlayerPrefab, base.transform.position);
		GlobalPrefabDefaults.Instance.SpawnBlood(base.transform.position, 30, 30, 5f, 30f, 60f, 120f);
		GameCameras gameCameras = UnityEngine.Object.FindObjectOfType<GameCameras>();
		if ((bool)gameCameras)
		{
			gameCameras.cameraShakeFSM.SendEvent("EnemyKillShake");
		}
		if ((bool)effects)
		{
			effects.SetActive(value: true);
		}
		if ((bool)chunks)
		{
			chunks.SetActive(value: true);
			chunks.transform.SetParent(null, worldPositionStays: true);
			FlingUtils.FlingChildren(new FlingUtils.ChildrenConfig
			{
				Parent = chunks,
				SpeedMin = 15f,
				SpeedMax = 20f,
				AngleMin = 60f,
				AngleMax = 120f,
				OriginVariationX = 0f,
				OriginVariationY = 0f
			}, base.transform, Vector3.zero);
		}
		meshRenderer.enabled = false;
	}
}
public class CorpseDeathStun : Corpse
{
	protected override void Start()
	{
		StartCoroutine(DeathStun());
	}

	private IEnumerator DeathStun()
	{
		SpriteFlash spriteFlash = GetComponent<SpriteFlash>();
		if ((bool)spriteFlash)
		{
			spriteFlash.flashInfectedLoop();
		}
		Vector2 velocity = body.velocity;
		body.isKinematic = true;
		body.velocity = Vector2.zero;
		yield return StartCoroutine(Jitter(0.75f));
		if ((bool)spriteFlash)
		{
			spriteFlash.CancelFlash();
