public class Crawler : MonoBehaviour
{
	private enum CrawlerType
	{
		Floor,
		Roof,
		Wall
	}

	public float speed = 2f;

	[Space]
	public Transform wallCheck;

	public Transform groundCheck;

	private Vector2 velocity;

	private CrawlerType type;

	private Rigidbody2D body;

	private Recoil recoil;

	private tk2dSpriteAnimator anim;

	private void Awake()
	{
		body = GetComponent<Rigidbody2D>();
		recoil = GetComponent<Recoil>();
		anim = GetComponent<tk2dSpriteAnimator>();
	}

	private void Start()
	{
		float z = base.transform.eulerAngles.z;
		if (z >= 45f && z <= 135f)
		{
			type = CrawlerType.Wall;
			velocity = new Vector2(0f, Mathf.Sign(0f - base.transform.localScale.x) * speed);
		}
		else if (z >= 135f && z <= 225f)
		{
			type = ((base.transform.localScale.y > 0f) ? CrawlerType.Roof : CrawlerType.Floor);
			velocity = new Vector2(Mathf.Sign(base.transform.localScale.x) * speed, 0f);
		}
		else if (z >= 225f && z <= 315f)
		{
			type = CrawlerType.Wall;
			velocity = new Vector2(0f, Mathf.Sign(base.transform.localScale.x) * speed);
		}
		else
		{
			type = ((!(base.transform.localScale.y > 0f)) ? CrawlerType.Roof : CrawlerType.Floor);
			velocity = new Vector2(Mathf.Sign(0f - base.transform.localScale.x) * speed, 0f);
		}
		recoil.SetRecoilSpeed(0f);
		recoil.OnCancelRecoil += delegate
		{
			body.velocity = velocity;
		};
		switch (type)
		{
		case CrawlerType.Floor:
			body.gravityScale = 1f;
			recoil.freezeInPlace = false;
			break;
		case CrawlerType.Roof:
		case CrawlerType.Wall:
			body.gravityScale = 0f;
			recoil.freezeInPlace = true;
			break;
		}
		StartCoroutine(Walk());
	}

	private IEnumerator Walk()
	{
		while (true)
		{
			anim.Play("Walk");
			body.velocity = velocity;
			bool hit = false;
			while (!hit && !CheckRayLocal(wallCheck.localPosition, (transform.localScale.x > 0f) ? Vector2.left : Vector2.right, 1f) && CheckRayLocal(groundCheck.localPosition, (transform.localScale.y > 0f) ? Vector2.down : Vector2.up, 1f))
			{
				yield return null;
			}
			yield return StartCoroutine(Turn());
			yield return null;
		}
	}

	private IEnumerator Turn()
	{
		body.velocity = Vector2.zero;
		yield return StartCoroutine(anim.PlayAnimWait("Turn"));
		transform.SetScaleX(transform.localScale.x * -1f);
		velocity.x *= -1f;
		velocity.y *= -1f;
	}

	public bool CheckRayLocal(Vector2 originLocal, Vector2 directionLocal, float length)
	{
		Vector2 vector = base.transform.TransformPoint(originLocal);
		Vector2 vector2 = base.transform.TransformDirection(directionLocal);
		RaycastHit2D raycastHit2D = Physics2D.Raycast(vector, vector2, length, 256);
		UnityEngine.Debug.DrawLine(vector, vector + vector2 * length);
		return raycastHit2D.collider != null;
	}
}
public class CycloneDust : MonoBehaviour
{
	public float dustY;

	public ParticleSystem particle;

	private Transform parent;

	private bool playing;

	private void Start()
	{
		parent = base.transform.parent;
	}

	private void OnEnable()
	{
		playing = false;
		particle.Stop();
	}

	private void Update()
	{
		if (parent.position.y < dustY)
		{
			if (!playing)
			{
				particle.Play();
				playing = true;
			}
		}
		else if (playing)
		{
			particle.Stop();
			playing = false;
		}
	}
}
public class DamageEnemies : MonoBehaviour
{
	public AttackTypes attackType = AttackTypes.Generic;

	public bool circleDirection;

	public int damageDealt;

	public float direction;

	public bool ignoreInvuln = true;

	public float magnitudeMult;

	public bool moveDirection;

	public SpecialTypes specialType;

	private List<Collider2D> enteredColliders = new List<Collider2D>();

	private void Reset()
	{
		PlayMakerFSM[] components = GetComponents<PlayMakerFSM>();
		foreach (PlayMakerFSM playMakerFSM in components)
		{
			if (playMakerFSM.FsmName == "damages_enemy")
			{
				attackType = (AttackTypes)playMakerFSM.FsmVariables.GetFsmInt("attackType").Value;
				circleDirection = playMakerFSM.FsmVariables.GetFsmBool("circleDirection").Value;
				damageDealt = playMakerFSM.FsmVariables.GetFsmInt("damageDealt").Value;
				direction = playMakerFSM.FsmVariables.GetFsmFloat("direction").Value;
				ignoreInvuln = playMakerFSM.FsmVariables.GetFsmBool("Ignore Invuln").Value;
				magnitudeMult = playMakerFSM.FsmVariables.GetFsmFloat("magnitudeMult").Value;
				moveDirection = playMakerFSM.FsmVariables.GetFsmBool("moveDirection").Value;
				specialType = (SpecialTypes)playMakerFSM.FsmVariables.GetFsmInt("Special Type").Value;
				break;
			}
		}
	}

	private void OnCollisionEnter2D(Collision2D collision)
	{
		DoDamage(collision.gameObject);
	}

	private void OnTriggerEnter2D(Collider2D collision)
	{
		if (base.enabled)
		{
			int layer = collision.gameObject.layer;
			if (layer != 20 && layer != 9 && layer != 26 && layer != 31 && !collision.CompareTag("Geo") && !enteredColliders.Contains(collision))
			{
				enteredColliders.Add(collision);
			}
		}
	}

	private void OnTriggerExit2D(Collider2D collision)
	{
		if (enteredColliders.Contains(collision))
		{
			enteredColliders.Remove(collision);
		}
	}

	private void OnDisable()
	{
		enteredColliders.Clear();
	}

	private void FixedUpdate()
	{
		for (int num = enteredColliders.Count - 1; num >= 0; num--)
		{
			Collider2D collider2D = enteredColliders[num];
			if (collider2D == null || !collider2D.isActiveAndEnabled)
			{
				enteredColliders.RemoveAt(num);
			}
			else
			{
				DoDamage(collider2D.gameObject);
			}
		}
	}

	private void DoDamage(GameObject target)
	{
		if (damageDealt > 0)
		{
			FSMUtility.SendEventToGameObject(target, "TAKE DAMAGE");
			HitTaker.Hit(target, new HitInstance
			{
				Source = base.gameObject,
				AttackType = attackType,
				CircleDirection = circleDirection,
				DamageDealt = damageDealt,
				Direction = direction,
				IgnoreInvulnerable = ignoreInvuln,
				MagnitudeMultiplier = magnitudeMult,
				MoveAngle = 0f,
				MoveDirection = moveDirection,
				Multiplier = 1f,
				SpecialType = specialType,
				IsExtraDamage = false
			});
		}
	}
}
