public enum ExtraDamageTypes
{
	Spore,
	Dung,
	Dung2
}
public interface IExtraDamageable
{
	void RecieveExtraDamage(ExtraDamageTypes extraDamageTypes);
}
public class ExtraDamageable : MonoBehaviour, IExtraDamageable
{
	private PlayMakerFSM healthManagerFsm;

	private FsmBool invincibleVar;

	private FsmInt hpVar;

	private SpriteFlash spriteFlash;

	private bool isSpellVulnerable;

	private HealthManager healthManager;

	[SerializeField]
	private RandomAudioClipTable impactClipTable;

	[SerializeField]
	private AudioSource audioPlayerPrefab;

	private bool damagedThisFrame;

	protected void Awake()
	{
		healthManagerFsm = FSMUtility.LocateFSM(base.gameObject, "health_manager_enemy");
		if (healthManagerFsm != null)
		{
			invincibleVar = healthManagerFsm.FsmVariables.GetFsmBool("Invincible");
			hpVar = healthManagerFsm.FsmVariables.GetFsmInt("HP");
		}
		healthManager = GetComponent<HealthManager>();
		spriteFlash = GetComponent<SpriteFlash>();
		isSpellVulnerable = base.gameObject.CompareTag("Spell Vulnerable");
	}

	private void LateUpdate()
	{
		damagedThisFrame = false;
	}

	public void RecieveExtraDamage(ExtraDamageTypes extraDamageType)
	{
		if (damagedThisFrame)
		{
			return;
		}
		damagedThisFrame = true;
		if (!isSpellVulnerable && ((invincibleVar != null && invincibleVar.Value) || (healthManager != null && healthManager.IsInvincible)))
		{
			return;
		}
		impactClipTable.SpawnAndPlayOneShot(audioPlayerPrefab, base.transform.position);
		if (spriteFlash != null)
		{
			switch (extraDamageType)
			{
			case ExtraDamageTypes.Spore:
				spriteFlash.flashSporeQuick();
				break;
			case ExtraDamageTypes.Dung:
			case ExtraDamageTypes.Dung2:
				spriteFlash.flashDungQuick();
				break;
			}
		}
		ApplyExtraDamageToHealthManager(GetDamageOfType(extraDamageType));
	}

	public static int GetDamageOfType(ExtraDamageTypes extraDamageTypes)
	{
		if ((uint)extraDamageTypes <= 1u || extraDamageTypes != ExtraDamageTypes.Dung2)
		{
			return 1;
		}
		return 2;
	}

	private void ApplyExtraDamageToHealthManager(int damageAmount)
	{
		if (healthManagerFsm != null && hpVar != null)
		{
			int num = hpVar.Value - damageAmount;
			hpVar.Value = num;
			if (num <= 0)
			{
				FSMUtility.SendEventToGameObject(base.gameObject, "EXTRA KILL");
			}
		}
		if (healthManager != null)
		{
			healthManager.ApplyExtraDamage(damageAmount);
		}
	}
}
[ActionCategory("Hollow Knight")]
public class SendExtraDamage : FsmStateAction
{
	[UIHint(UIHint.Variable)]
	public FsmOwnerDefault target;

	public FsmEnum extraDamageType;

	public override void Reset()
	{
		target = new FsmOwnerDefault();
		extraDamageType = new FsmEnum("Extra Damage Type", typeof(ExtraDamageTypes), 0);
	}

	public override void OnEnter()
	{
		GameObject gameObject = ((target.OwnerOption == OwnerDefaultOption.UseOwner) ? base.Owner : target.GameObject.Value);
		if (gameObject != null)
		{
			ExtraDamageable component = gameObject.GetComponent<ExtraDamageable>();
			if (component != null)
			{
				component.RecieveExtraDamage((ExtraDamageTypes)(object)extraDamageType.Value);
			}
		}
		Finish();
	}
}
[RequireComponent(typeof(Rigidbody2D))]
[RequireComponent(typeof(MeshRenderer))]
[RequireComponent(typeof(tk2dSpriteAnimator))]
public class FakeBat : MonoBehaviour
{
	private enum States
	{
		WaitingForBossAwake,
		Dormant,
		In,
		Out
	}

	private Rigidbody2D body;

	private MeshRenderer meshRenderer;

	private tk2dSpriteAnimator spriteAnimator;

	private States state;

	private float turnCooldown;

	[SerializeField]
	private Transform grimm;

	private const float Z = 0f;

	private static List<FakeBat> fakeBats;

	protected void Awake()
	{
		body = GetComponent<Rigidbody2D>();
		meshRenderer = GetComponent<MeshRenderer>();
		spriteAnimator = GetComponent<tk2dSpriteAnimator>();
		state = States.WaitingForBossAwake;
	}

	[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
	protected static void Init()
	{
		fakeBats = new List<FakeBat>();
	}

	protected void OnEnable()
	{
		fakeBats.Add(this);
	}

	protected void OnDisable()
	{
		fakeBats.Remove(this);
	}

	protected void Start()
	{
		float num = UnityEngine.Random.Range(0.7f, 0.9f);
		base.transform.SetScaleX(num);
		base.transform.SetScaleY(num);
		base.transform.SetPositionZ(0f);
	}

	protected void Update()
	{
		turnCooldown -= Time.deltaTime;
	}

	public static void NotifyAllBossAwake()
	{
		foreach (FakeBat fakeBat in fakeBats)
		{
			if (!(fakeBat == null))
			{
				fakeBat.NotifyBossAwake();
			}
		}
	}

	public void NotifyBossAwake()
	{
		state = States.Dormant;
	}

	public static void SendAllOut()
	{
		foreach (FakeBat fakeBat in fakeBats)
		{
			if (!(fakeBat == null))
			{
				fakeBat.SendOut();
			}
		}
	}

	public void SendOut()
	{
		if (state == States.Dormant)
		{
			StartCoroutine("SendOutRoutine");
			StopCoroutine("BringInRoutine");
		}
	}

	protected IEnumerator SendOutRoutine()
	{
		state = States.Out;
		transform.SetPosition2D(grimm.transform.position);
		transform.SetPositionZ(0f);
		meshRenderer.enabled = true;
		spriteAnimator.Play("Bat Fly");
		int? selectedDirection = null;
		while (true)
		{
			float minInclusive;
			float maxInclusive;
			float minInclusive2;
			float maxInclusive2;
			int num;
			float num2;
			switch (selectedDirection ?? UnityEngine.Random.Range(0, 4))
			{
			case 1:
				minInclusive = 1f;
				maxInclusive = 4f;
				minInclusive2 = 2f;
				maxInclusive2 = 3f;
				num = 1;
				num2 = 0.3f;
				break;
			case 3:
				minInclusive = 1f;
				maxInclusive = 4f;
				minInclusive2 = -3f;
				maxInclusive2 = -2f;
				num = 1;
				num2 = 0.3f;
				break;
			case 2:
				minInclusive = -5f;
				maxInclusive = -3f;
				minInclusive2 = 0.5f;
				maxInclusive2 = 2f;
				num = 0;
				num2 = 0.5f;
				break;
			default:
				minInclusive = 3f;
				maxInclusive = 5f;
				minInclusive2 = 0.5f;
				maxInclusive2 = 2f;
				num = 0;
				num2 = 0.5f;
				break;
			}
			int index = (num + 1) % 2;
			Vector2 accel = new Vector2(UnityEngine.Random.Range(minInclusive, maxInclusive), UnityEngine.Random.Range(minInclusive2, maxInclusive2));
			if (UnityEngine.Random.Range(0, 1) == 0)
			{
				accel[index] = 0f - accel[index];
			}
			Vector2 velocity = body.velocity;
			velocity[num] *= num2;
			body.velocity = velocity;
			accel *= 0.5f;
			Vector2 maxSpeed = accel * 10f;
			maxSpeed.x = Mathf.Abs(maxSpeed.x);
			maxSpeed.y = Mathf.Abs(maxSpeed.y);
			float timer;
			for (timer = 0.2f; timer > 0f; timer -= Time.deltaTime)
			{
				FaceDirection((body.velocity.x > 0f) ? 1 : (-1), snap: false);
				Accelerate(accel, new Vector2(15f, 10f));
				yield return null;
			}
			selectedDirection = null;
			timer = UnityEngine.Random.Range(0.5f, 1.5f);
			while (!selectedDirection.HasValue && timer > 0f)
			{
				FaceDirection((body.velocity.x > 0f) ? 1 : (-1), snap: false);
				Accelerate(accel, maxSpeed);
				Vector2 vector = transform.position;
				if (vector.x < 73f)
				{
					selectedDirection = 0;
					break;
				}
				if (vector.x > 99f)
				{
					selectedDirection = 2;
					break;
				}
				if (vector.y < 8f)
				{
					selectedDirection = 1;
					break;
				}
				if (vector.y > 15f)
				{
					selectedDirection = 3;
					break;
				}
				yield return null;
				timer -= Time.deltaTime;
			}
		}
	}

	public static void BringAllIn()
	{
		foreach (FakeBat fakeBat in fakeBats)
		{
			if (!(fakeBat == null))
			{
				fakeBat.BringIn();
			}
		}
	}

	public void BringIn()
	{
		StartCoroutine("BringInRoutine");
		StopCoroutine("SendOutRoutine");
	}

	protected IEnumerator BringInRoutine()
	{
		state = States.In;
		int sign = ((grimm.transform.position.x - body.velocity.x > 0f) ? 1 : (-1));
		FaceDirection(sign, snap: true);
		body.velocity = Vector2.zero;
		while (true)
		{
			Vector2 current = transform.position;
			Vector2 vector = grimm.transform.position;
			Vector2 vector2 = Vector2.MoveTowards(current, vector, 25f * Time.deltaTime);
			transform.SetPosition2D(vector2);
			if (Vector2.Distance(vector2, vector) < Mathf.Epsilon)
			{
				break;
			}
			yield return null;
		}
		spriteAnimator.Play("Bat End");
		while (spriteAnimator.ClipTimeSeconds < spriteAnimator.CurrentClip.Duration - Mathf.Epsilon)
		{
			yield return null;
		}
		meshRenderer.enabled = false;
		transform.SetPositionY(-50f);
		state = States.Dormant;
	}

	private void FaceDirection(int sign, bool snap)
	{
		float num = Mathf.Abs(base.transform.localScale.x) * (float)sign;
		if (!Mathf.Approximately(base.transform.localScale.x, num) && (snap || turnCooldown <= 0f))
		{
			if (!snap)
			{
				spriteAnimator.Play("Bat TurnToFly");
				spriteAnimator.PlayFromFrame(0);
				turnCooldown = 0.5f;
			}
			base.transform.SetScaleX(num);
		}
	}

	private void Accelerate(Vector2 fixedAcceleration, Vector2 speedLimit)
	{
		Vector2 vector = fixedAcceleration / Time.fixedDeltaTime;
		Vector2 velocity = body.velocity;
		velocity += vector * Time.deltaTime;
		velocity.x = Mathf.Clamp(velocity.x, 0f - speedLimit.x, speedLimit.x);
		velocity.y = Mathf.Clamp(velocity.y, 0f - speedLimit.y, speedLimit.y);
		body.velocity = velocity;
	}
}
public class HealthManager : MonoBehaviour, IHitResponder
{
	[Serializable]
	private struct HPScaleGG
	{
		public int level1;

		public int level2;

		public int level3;

		public int GetScaledHP(int originalHP)
		{
			if (BossSceneController.IsBossScene)
			{
				switch (BossSceneController.Instance.BossLevel)
				{
				case 0:
					if (level1 <= 0)
					{
						return originalHP;
					}
					return level1;
				case 1:
					if (level2 <= 0)
					{
						return originalHP;
					}
					return level2;
				case 2:
					if (level3 <= 0)
					{
						return originalHP;
					}
					return level3;
				}
			}
			return originalHP;
		}
	}

