public static class DirectionUtils
{
	public const int Right = 0;

	public const int Up = 1;

	public const int Left = 2;

	public const int Down = 3;

	public static int GetCardinalDirection(float degrees)
	{
		return NegSafeMod(Mathf.RoundToInt(degrees / 90f), 4);
	}

	public static int NegSafeMod(int val, int len)
	{
		return (val % len + len) % len;
	}

	public static int GetX(int cardinalDirection)
	{
		return (cardinalDirection % 4) switch
		{
			0 => 1, 
			2 => -1, 
			_ => 0, 
		};
	}

	public static int GetY(int cardinalDirection)
	{
		return (cardinalDirection % 4) switch
		{
			1 => 1, 
			3 => -1, 
			_ => 0, 
		};
	}
}
public class FSMActivator : MonoBehaviour
{
	[HideInInspector]
	public bool activateStaggered = true;

	private PlayMakerFSM[] fsms;

	private tk2dSpriteAnimator spriteAnim;

	private bool activated;

	private void Awake()
	{
		fsms = GetComponents<PlayMakerFSM>();
		spriteAnim = GetComponent<tk2dSpriteAnimator>();
	}

	public void Activate()
	{
		if (activateStaggered)
		{
			StartCoroutine(ActivateStaggered());
		}
		else
		{
			if (activated)
			{
				return;
			}
			if (fsms.Length != 0)
			{
				for (int i = 0; i < fsms.Length; i++)
				{
					fsms[i].enabled = true;
				}
			}
			if (spriteAnim != null)
			{
				spriteAnim.Play();
			}
			activated = true;
		}
	}

	public IEnumerator ActivateStaggered()
	{
		if (activated)
		{
			yield break;
		}
		if (fsms.Length != 0)
		{
			activated = true;
			for (int i = 0; i < fsms.Length; i++)
			{
				fsms[i].enabled = true;
				yield return null;
			}
		}
		if (spriteAnim != null)
		{
			activated = true;
			spriteAnim.Play();
		}
	}

	public void Deactivate()
	{
		if (activated && fsms.Length != 0)
		{
			for (int i = 0; i < fsms.Length; i++)
			{
				fsms[i].enabled = false;
			}
		}
	}

	public IEnumerator DeactivateStaggered()
	{
		if (activated && fsms.Length != 0)
		{
			for (int i = 0; i < fsms.Length; i++)
			{
				fsms[i].enabled = false;
				yield return null;
			}
		}
	}
}
