public class GlobalPrefabDefaults : MonoBehaviour
{
	public static GlobalPrefabDefaults Instance;

	public GameObject bloodSplatterParticle;

	public float speedMultiplier = 1.2f;

	public float amountMultiplier = 1.3f;

	private ParticleSystem.MinMaxGradient initialBloodColour;

	private void Awake()
	{
		Instance = this;
	}

	private void Start()
	{
		if ((bool)bloodSplatterParticle)
		{
			ParticleSystem component = bloodSplatterParticle.GetComponent<ParticleSystem>();
			if ((bool)component)
			{
				initialBloodColour = component.main.startColor;
			}
		}
	}

	public void SpawnBlood(Vector3 position, short minCount, short maxCount, float minSpeed, float maxSpeed, float angleMin = 0f, float angleMax = 360f, Color? colorOverride = null)
	{
		if (!bloodSplatterParticle)
		{
			return;
		}
		ParticleSystem component = bloodSplatterParticle.Spawn().GetComponent<ParticleSystem>();
		if ((bool)component)
		{
			component.Stop();
			component.emission.SetBursts(new ParticleSystem.Burst[1]
			{
				new ParticleSystem.Burst(0f, (short)Mathf.RoundToInt((float)minCount * amountMultiplier), (short)Mathf.RoundToInt((float)maxCount * amountMultiplier))
			});
			ParticleSystem.MainModule main = component.main;
			main.maxParticles = Mathf.RoundToInt((float)maxCount * amountMultiplier);
			main.startSpeed = new ParticleSystem.MinMaxCurve(minSpeed * speedMultiplier, maxSpeed * speedMultiplier);
			if (!colorOverride.HasValue)
			{
				main.startColor = initialBloodColour;
			}
			else
			{
				main.startColor = new ParticleSystem.MinMaxGradient(colorOverride.Value);
			}
			ParticleSystem.ShapeModule shape = component.shape;
			float num = (shape.arc = angleMax - angleMin);
			component.transform.SetRotation2D(angleMin);
			component.transform.position = position;
			component.Play();
		}
	}
}
public class SpawnBlood : FsmStateAction
{
	public FsmGameObject spawnPoint;

	public FsmVector3 position;

	public FsmInt spawnMin;

	public FsmInt spawnMax;

	public FsmFloat speedMin;

	public FsmFloat speedMax;

	public FsmFloat angleMin;

	public FsmFloat angleMax;

	public FsmColor colorOverride;

	public override void Reset()
	{
		spawnPoint = new FsmGameObject
		{
			UseVariable = true
		};
		position = new FsmVector3();
		spawnMin = null;
		spawnMax = null;
		speedMin = null;
		speedMax = null;
		angleMin = null;
		angleMax = null;
		colorOverride = new FsmColor
		{
			UseVariable = true
		};
	}

	public override void OnEnter()
	{
		Spawn();
		Finish();
	}

	protected void Spawn()
	{
		if ((bool)GlobalPrefabDefaults.Instance)
		{
			Vector3 value = position.Value;
			if ((bool)spawnPoint.Value)
			{
				value += spawnPoint.Value.transform.position;
			}
			GlobalPrefabDefaults.Instance.SpawnBlood(value, (short)spawnMin.Value, (short)spawnMax.Value, speedMin.Value, speedMax.Value, angleMin.Value, angleMax.Value, colorOverride.IsNone ? ((Color?)null) : new Color?(colorOverride.Value));
		}
	}
}
public class SpawnBloodTime : SpawnBlood
{
	public FsmFloat delay;

	private float nextSpawnTime;

	public override void Reset()
	{
		base.Reset();
		delay = new FsmFloat(0.1f);
	}

	public override void OnEnter()
	{
	}

	public override void OnUpdate()
	{
		base.OnUpdate();
		if (Time.time > nextSpawnTime)
		{
			nextSpawnTime = Time.time + delay.Value;
			Spawn();
		}
	}
}
[RequireComponent(typeof(Animator))]
public class BossDoorCage : MonoBehaviour
{
	public BossSequenceDoor[] requiredComplete;

	public TriggerEnterEvent unlockTrigger;

	public string playerData = "bossDoorCageUnlocked";

	private Animator animator;

	private CameraControlAnimationEvents cameraShake;

	private void Awake()
	{
		animator = GetComponent<Animator>();
		cameraShake = GetComponent<CameraControlAnimationEvents>();
	}

	private void Start()
	{
		if (GameManager.instance.GetPlayerDataBool(playerData))
		{
			base.gameObject.SetActive(value: false);
		}
		else if ((bool)unlockTrigger)
		{
			unlockTrigger.OnTriggerEntered += delegate
			{
				Unlock();
			};
		}
	}

	private void Unlock()
	{
		if (GameManager.instance.GetPlayerDataBool(playerData))
		{
			return;
		}
		BossSequenceDoor[] array = requiredComplete;
		for (int i = 0; i < array.Length; i++)
		{
			if (!array[i].CurrentCompletion.completed)
			{
				return;
			}
		}
		GameManager.instance.SetPlayerDataBool(playerData, value: true);
		StartCoroutine(UnlockRoutine());
	}

	private IEnumerator UnlockRoutine()
	{
		animator.Play("Unlock");
		yield return null;
		yield return new WaitForSeconds(animator.GetCurrentAnimatorStateInfo(0).length);
	}

	public void StartShakeLock()
	{
		if ((bool)cameraShake)
		{
			cameraShake.SmallRumble();
		}
		PlayMakerFSM playMakerFSM = PlayMakerFSM.FindFsmOnGameObject(HeroController.instance.gameObject, "Roar Lock");
		if ((bool)playMakerFSM)
		{
			playMakerFSM.FsmVariables.FindFsmGameObject("Roar Object").Value = base.gameObject;
		}
		FSMUtility.SendEventToGameObject(HeroController.instance.gameObject, "ROAR ENTER");
	}

	public void StopShakeLock()
	{
		if ((bool)cameraShake)
		{
			cameraShake.StopRumble();
		}
		FSMUtility.SendEventToGameObject(HeroController.instance.gameObject, "ROAR EXIT");
	}
}
public class BossDoorCompletionStates : MonoBehaviour
{
	[Serializable]
	public class CompletionState
	{
		public GameObject stateObject;

		public string sendEvent;
	}

	public CompletionState[] completionStates;

	[Space]
	[UnityEngine.Tooltip("OPTIONAL - using an int, will ensure each state is seen at least once. (Requires a 2D trigger on this GameObject)")]
	public string stateSeenPlayerData;

	private int completedIndex;

	private void Start()
	{
		completedIndex = 0;
		FieldInfo[] fields = typeof(PlayerData).GetFields();
		foreach (FieldInfo fieldInfo in fields)
		{
			if (fieldInfo.FieldType == typeof(BossSequenceDoor.Completion) && ((BossSequenceDoor.Completion)fieldInfo.GetValue(GameManager.instance.playerData)).completed)
			{
				completedIndex++;
			}
		}
		if (!string.IsNullOrEmpty(stateSeenPlayerData))
		{
			int num = GameManager.instance.GetPlayerDataInt(stateSeenPlayerData) + 1;
			if (completedIndex > num)
			{
				completedIndex = num;
			}
		}
		if (completedIndex >= completionStates.Length)
		{
			completedIndex = completionStates.Length - 1;
		}
		for (int j = 0; j < completionStates.Length; j++)
		{
			if ((bool)completionStates[j].stateObject)
			{
				completionStates[j].stateObject.SetActive(value: false);
			}
		}
		CompletionState completionState = completionStates[completedIndex];
		if ((bool)completionState.stateObject)
		{
			completionState.stateObject.SetActive(value: true);
			if (!string.IsNullOrEmpty(completionState.sendEvent))
			{
				FSMUtility.SendEventToGameObject(completionState.stateObject, completionState.sendEvent);
			}
		}
	}

	private void OnTriggerEnter2D(Collider2D collision)
	{
		if (!string.IsNullOrEmpty(stateSeenPlayerData))
		{
			GameManager.instance.SetPlayerDataInt(stateSeenPlayerData, completedIndex);
		}
	}
}
[DefaultExecutionOrder(1)]
public class BossDoorTargetLock : MonoBehaviour
{
	[Serializable]
	public class BossDoorTarget
	{
		public BossSequenceDoor door;

		public GameObject indicator;

		public bool Evaluate()
		{
			if ((bool)door && (bool)indicator)
			{
				bool completed = door.CurrentCompletion.completed;
				indicator.SetActive(completed);
				return completed;
			}
			return false;
		}
	}

	public BossDoorTarget[] targets;

	public string playerData = "finalBossDoorUnlocked";

	public TriggerEnterEvent unlockTrigger;

	public string unlockAnimation = "Unlock";

	public string unlockedAnimation = "Unlocked";

	private Animator animator;

	private bool IsUnlocked
	{
		get
		{
			if (string.IsNullOrEmpty(playerData))
			{
				return false;
			}
			return GameManager.instance.GetPlayerDataBool(playerData);
		}
		set
		{
			if (!string.IsNullOrEmpty(playerData))
			{
				GameManager.instance.SetPlayerDataBool(playerData, value);
			}
			else
			{
				UnityEngine.Debug.LogError("Can't save an empty PlayerData bool!", this);
			}
		}
	}

	private void Awake()
	{
		animator = GetComponent<Animator>();
	}

	private void Start()
	{
		bool flag = true;
		BossDoorTarget[] array = targets;
		for (int i = 0; i < array.Length; i++)
		{
			if (!array[i].Evaluate())
			{
				flag = false;
			}
		}
		if (IsUnlocked)
		{
			if ((bool)animator)
			{
				animator.Play(unlockedAnimation);
			}
		}
		else if (flag && (bool)unlockTrigger)
		{
			TriggerEnterEvent.CollisionEvent temp = null;
			temp = delegate
			{
				StartCoroutine(UnlockSequence());
				unlockTrigger.OnTriggerEntered -= temp;
			};
			unlockTrigger.OnTriggerEntered += temp;
		}
	}

	private IEnumerator UnlockSequence()
	{
		if ((bool)animator)
		{
			animator.Play(unlockAnimation);
			yield return null;
			yield return new WaitForSeconds(animator.GetCurrentAnimatorStateInfo(0).length);
		}
		IsUnlocked = true;
	}

	private void StartRoarLock()
	{
		PlayMakerFSM playMakerFSM = PlayMakerFSM.FindFsmOnGameObject(HeroController.instance.gameObject, "Roar Lock");
		if ((bool)playMakerFSM)
		{
			playMakerFSM.FsmVariables.FindFsmGameObject("Roar Object").Value = base.gameObject;
		}
		FSMUtility.SendEventToGameObject(HeroController.instance.gameObject, "ROAR ENTER");
	}

	private void StopRoarLock()
	{
		FSMUtility.SendEventToGameObject(HeroController.instance.gameObject, "ROAR EXIT");
	}
}
