	public string GetSceneAt(int index)
	{
		return GetBossScene(index).sceneName;
	}

	public string GetSceneObjectName(int index)
	{
		return GetBossScene(index).name;
	}

	public bool CanLoad(int index)
	{
		if (GetBossScene(index).isHidden)
		{
			return GetBossScene(index).IsUnlocked(BossSceneCheckSource.Sequence);
		}
		return true;
	}

	public BossScene GetBossScene(int index)
	{
		BossScene bossScene = bossScenes[index];
		if (!bossScene.IsUnlockedSelf(BossSceneCheckSource.Sequence) && (bool)bossScene.baseBoss && bossScene.substituteBoss)
		{
			bossScene = bossScene.baseBoss;
		}
		return bossScene;
	}

	public bool IsUnlocked()
	{
		if (useSceneUnlocks)
		{
			BossScene[] array = bossScenes;
			foreach (BossScene bossScene in array)
			{
				if (!bossScene.isHidden && !bossScene.IsUnlocked(BossSceneCheckSource.Sequence))
				{
					return false;
				}
			}
		}
		if (tests != null && tests.Length != 0)
		{
			BossScene.BossTest[] array2 = tests;
			for (int i = 0; i < array2.Length; i++)
			{
				if (array2[i].IsUnlocked())
				{
					return true;
				}
			}
			return false;
		}
		return true;
	}

	public bool IsSceneHidden(int index)
	{
		return GetBossScene(index).isHidden;
	}
}
public class BossSequenceBindingsDisplay : MonoBehaviour
{
	public GameObject[] bindingIcons;

	private void Start()
	{
		int num = CountCompletedBindings();
		for (int i = 0; i < bindingIcons.Length; i++)
		{
			bindingIcons[i].SetActive(i < num);
		}
	}

	public static void CountBindings(out int total, out int completed)
	{
		total = 0;
		completed = 0;
		FieldInfo[] fields = typeof(PlayerData).GetFields();
		foreach (FieldInfo fieldInfo in fields)
		{
			if (!(fieldInfo.FieldType == typeof(BossSequenceDoor.Completion)))
			{
				continue;
			}
			BossSequenceDoor.Completion completion = (BossSequenceDoor.Completion)fieldInfo.GetValue(GameManager.instance.playerData);
			if (completion.completed)
			{
				if (completion.boundNail)
				{
					completed++;
				}
				if (completion.boundShell)
				{
					completed++;
				}
				if (completion.boundCharms)
				{
					completed++;
				}
				if (completion.boundSoul)
				{
					completed++;
				}
			}
			total += 4;
		}
	}

	public static int CountCompletedBindings()
	{
		int total = 0;
		int completed = 0;
		CountBindings(out total, out completed);
		return completed;
	}

	public static int CountTotalBindings()
	{
		int total = 0;
		int completed = 0;
		CountBindings(out total, out completed);
		return total;
	}
}
