public class BossStatue : MonoBehaviour
{
	public delegate void StatueSwapEndEvent();

	public delegate void SeenNewStatueEvent();

	[Serializable]
	public struct Completion
	{
		public bool hasBeenSeen;

		public bool isUnlocked;

		public bool completedTier1;

		public bool completedTier2;

		public bool completedTier3;

		public bool seenTier3Unlock;

		public bool usingAltVersion;

		public static Completion None => new Completion
		{
			hasBeenSeen = false,
			isUnlocked = false,
			completedTier1 = false,
			completedTier2 = false,
			completedTier3 = false,
			seenTier3Unlock = false,
			usingAltVersion = false
		};
	}

	[Serializable]
	public struct BossUIDetails
	{
		public string nameKey;

		public string nameSheet;

		public string descriptionKey;

		public string descriptionSheet;
	}

	[Header("Boss Data")]
	public BossScene bossScene;

	public BossScene dreamBossScene;

	[Header("Statue Data")]
	[FormerlySerializedAs("statueStateInt")]
	public string statueStatePD;

	public BossUIDetails bossDetails;

	[Space]
	[FormerlySerializedAs("dreamStatueStateInt")]
	public string dreamStatueStatePD;

	public BossUIDetails dreamBossDetails;

	[Space]
	public bool hasNoTiers;

	public bool dontCountCompletion;

	public bool isAlwaysUnlocked;

	public bool isAlwaysUnlockedDream;

	public float inspectCameraHeight = 5.5f;

	public bool isHidden;

	[Header("Prefab Stuff")]
	public PlayMakerFSM bossUIControlFSM;

	[Space]
	public GameObject[] disableIfLocked;

	public GameObject[] enableIfLocked;

	public BossStatueTrophyPlaque regularPlaque;

	public BossStatueTrophyPlaque altPlaqueL;

	public BossStatueTrophyPlaque altPlaqueR;

	public SpriteRenderer lockedPlaque;

	[Space]
	public GameObject dreamReturnGate;

	public TriggerEnterEvent lightTrigger;

	public CameraLockArea cameraLock;

	[Header("Animation")]
	public GameObject statueDisplay;

	public GameObject statueDisplayAlt;

	public ParticleSystem statueShakeParticles;

	public ParticleSystem statueUpParticles;

	public AudioSource statueShakeLoop;

	public AudioSource audioSourcePrefab;

	public AudioEvent statueDownSound;

	public float statueDownSoundDelay;

	public AudioEvent statueUpSound;

	public float statueUpSoundDelay = 0.3f;

	public float swapWaitTime = 0.25f;

	public float shakeTime = 1f;

	public float holdTime = 0.5f;

	public float upParticleDelay = 0.25f;

	private IBossStatueToggle dreamToggle;

	private bool wasUsingDreamVersion;

	public bool UsingDreamVersion
	{
		get
		{
			return StatueState.usingAltVersion;
		}
		private set
		{
			Completion statueState = StatueState;
			statueState.usingAltVersion = value;
			StatueState = statueState;
		}
	}

	public Completion StatueState
	{
		get
		{
			if (string.IsNullOrEmpty(statueStatePD))
			{
				return Completion.None;
			}
			Completion playerDataVariable = GameManager.instance.GetPlayerDataVariable<Completion>(statueStatePD);
			if (!playerDataVariable.isUnlocked && (bool)bossScene && (bossScene.IsUnlocked(BossSceneCheckSource.Statue) || isAlwaysUnlocked))
			{
				playerDataVariable.isUnlocked = true;
			}
			return playerDataVariable;
		}
		set
		{
			if (!string.IsNullOrEmpty(statueStatePD))
			{
				GameManager.instance.SetPlayerDataVariable(statueStatePD, value);
			}
		}
	}

	public Completion DreamStatueState
	{
		get
		{
			if (string.IsNullOrEmpty(dreamStatueStatePD))
			{
				return Completion.None;
			}
			Completion playerDataVariable = GameManager.instance.GetPlayerDataVariable<Completion>(dreamStatueStatePD);
			if (!playerDataVariable.isUnlocked && (bool)dreamBossScene && (dreamBossScene.IsUnlocked(BossSceneCheckSource.Statue) || isAlwaysUnlockedDream))
			{
				playerDataVariable.isUnlocked = true;
			}
			return playerDataVariable;
		}
		set
		{
			if (!string.IsNullOrEmpty(dreamStatueStatePD))
			{
				GameManager.instance.SetPlayerDataVariable(dreamStatueStatePD, value);
			}
		}
	}

	public bool HasRegularVersion
	{
		get
		{
			if ((bool)bossScene)
			{
				return !string.IsNullOrEmpty(statueStatePD);
			}
			return false;
		}
	}

	public bool HasDreamVersion
	{
		get
		{
			if ((bool)dreamBossScene)
			{
				return !string.IsNullOrEmpty(dreamStatueStatePD);
			}
			return false;
		}
	}

	public event StatueSwapEndEvent OnStatueSwapFinished;

	public event SeenNewStatueEvent OnSeenNewStatue;

	private void Awake()
	{
		dreamToggle = GetComponentInChildren<IBossStatueToggle>(includeInactive: false);
		if ((bool)dreamReturnGate)
		{
			GameObject obj = dreamReturnGate;
			obj.name = obj.name + "_" + base.gameObject.name;
		}
		if ((bool)cameraLock)
		{
			cameraLock.cameraYMin = (cameraLock.cameraYMax = base.transform.position.y + inspectCameraHeight);
		}
	}

	private void Start()
	{
		UpdateDetails();
		if (StatueState.isUnlocked)
		{
			GameObject[] array = disableIfLocked;
			foreach (GameObject gameObject in array)
			{
				if ((bool)gameObject)
				{
					gameObject.SetActive(value: true);
				}
			}
			array = enableIfLocked;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].SetActive(value: false);
			}
			if ((bool)statueDisplay)
			{
				statueDisplay.SetActive(value: true);
			}
		}
		else
		{
			GameObject[] array = disableIfLocked;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].SetActive(value: false);
			}
			array = enableIfLocked;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].SetActive(value: true);
			}
			if ((bool)statueDisplay)
			{
				statueDisplay.SetActive(value: false);
			}
		}
		if ((bool)statueDisplayAlt)
		{
			statueDisplayAlt.SetActive(value: false);
		}
		if (dreamToggle != null)
		{
			dreamToggle.SetOwner(this);
		}
		if (DreamStatueState.isUnlocked)
		{
			if (dreamToggle != null)
			{
				dreamToggle.SetState(value: true);
			}
		}
		else if (dreamToggle != null)
		{
			dreamToggle.SetState(value: false);
		}
		Animator component = statueDisplay.GetComponent<Animator>();
		if ((bool)component)
		{
			component.enabled = false;
		}
		component = statueDisplayAlt.GetComponent<Animator>();
		if ((bool)component)
		{
			component.enabled = false;
		}
		if ((bool)lightTrigger)
		{
			lightTrigger.OnTriggerEntered += delegate
			{
				bool flag = false;
				Completion statueState = StatueState;
				if (statueState.isUnlocked && !statueState.hasBeenSeen && !isAlwaysUnlocked)
				{
					statueState.hasBeenSeen = true;
					StatueState = statueState;
					flag = true;
				}
				statueState = DreamStatueState;
				if (statueState.isUnlocked && !statueState.hasBeenSeen && !isAlwaysUnlockedDream)
				{
					statueState.hasBeenSeen = true;
					DreamStatueState = statueState;
					flag = true;
				}
				if (flag && OnSeenNewStatue != null)
				{
					OnSeenNewStatue();
				}
			};
		}
		SetPlaquesVisible((StatueState.isUnlocked && StatueState.hasBeenSeen) || isAlwaysUnlocked);
	}

	public void SetPlaquesVisible(bool isEnabled)
	{
		regularPlaque.gameObject.SetActive(value: false);
		altPlaqueL.gameObject.SetActive(value: false);
		altPlaqueR.gameObject.SetActive(value: false);
		if (isEnabled)
		{
			if ((bool)bossScene && !dreamBossScene)
			{
				regularPlaque.gameObject.SetActive(value: true);
				SetPlaqueState(StatueState, regularPlaque, statueStatePD);
			}
			else if ((bool)bossScene && (bool)dreamBossScene)
			{
				altPlaqueL.gameObject.SetActive(value: true);
				altPlaqueR.gameObject.SetActive(value: true);
				SetPlaqueState(StatueState, altPlaqueL, statueStatePD);
				SetPlaqueState(DreamStatueState, altPlaqueR, dreamStatueStatePD);
			}
		}
		lockedPlaque.enabled = !isEnabled;
	}

	public void SetPlaqueState(Completion statueState, BossStatueTrophyPlaque plaque, string playerDataKey)
	{
		PlayerData playerData = GameManager.instance.playerData;
		if (string.IsNullOrEmpty(playerData.GetString("currentBossStatueCompletionKey")) || playerData.GetString("currentBossStatueCompletionKey") != playerDataKey)
		{
			plaque.SetDisplay(BossStatueTrophyPlaque.GetDisplayType(statueState));
			return;
		}
		BossStatueTrophyPlaque.DisplayType displayType = BossStatueTrophyPlaque.GetDisplayType(statueState);
		plaque.SetDisplay(displayType);
		plaque.DoTierCompleteEffect((BossStatueTrophyPlaque.DisplayType)playerData.GetInt("bossStatueTargetLevel"));
		playerData.SetStringSwappedArgs("", "currentBossStatueCompletionKey");
		playerData.SetIntSwappedArgs(-1, "bossStatueTargetLevel");
	}

	public void SetDreamVersion(bool value, bool useAltStatue = false, bool doAnim = true)
	{
		UsingDreamVersion = value;
		if (useAltStatue && (bool)statueDisplayAlt && (bool)statueDisplay)
		{
			StartCoroutine(SwapStatues(doAnim));
		}
		else if (OnStatueSwapFinished != null)
		{
			OnStatueSwapFinished();
		}
		wasUsingDreamVersion = value;
		UpdateDetails();
	}

	private void UpdateDetails()
	{
		if ((bool)bossUIControlFSM)
		{
			BossUIDetails bossUIDetails = (UsingDreamVersion ? dreamBossDetails : bossDetails);
			bossUIControlFSM.FsmVariables.FindFsmString("Boss Name Key").Value = bossUIDetails.nameKey;
			bossUIControlFSM.FsmVariables.FindFsmString("Boss Name Sheet").Value = bossUIDetails.nameSheet;
			bossUIControlFSM.FsmVariables.FindFsmString("Description Key").Value = bossUIDetails.descriptionKey;
			bossUIControlFSM.FsmVariables.FindFsmString("Description Sheet").Value = bossUIDetails.descriptionSheet;
		}
	}

	private IEnumerator SwapStatues(bool doAnim)
	{
		GameObject current = (wasUsingDreamVersion ? statueDisplayAlt : statueDisplay);
		GameObject next = (wasUsingDreamVersion ? statueDisplay : statueDisplayAlt);
		if (doAnim)
		{
			if ((bool)bossUIControlFSM)
			{
				FSMUtility.SendEventToGameObject(bossUIControlFSM.gameObject, "NPC CONTROL OFF");
			}
			yield return new WaitForSeconds(swapWaitTime);
			if ((bool)statueShakeParticles)
			{
				statueShakeParticles.Play();
			}
			if ((bool)statueShakeLoop)
			{
				statueShakeLoop.Play();
			}
			yield return StartCoroutine(Jitter(shakeTime, 0.1f, current));
			if ((bool)statueShakeLoop)
			{
				statueShakeLoop.Stop();
			}
			StartCoroutine(PlayAudioEventDelayed(statueDownSound, statueDownSoundDelay));
			yield return StartCoroutine(PlayAnimWait(current.GetComponent<Animator>(), "Down", 0f));
		}
		current.SetActive(value: false);
		if (doAnim)
		{
			yield return new WaitForSeconds(holdTime);
			StartCoroutine(PlayParticlesDelay(statueUpParticles, upParticleDelay));
			StartCoroutine(PlayAudioEventDelayed(statueUpSound, statueUpSoundDelay));
		}
		next.transform.position = current.transform.position;
		next.SetActive(value: true);
		if (doAnim)
		{
			yield return StartCoroutine(PlayAnimWait(next.GetComponent<Animator>(), "Up", 0f));
			if ((bool)bossUIControlFSM)
			{
				FSMUtility.SendEventToGameObject(bossUIControlFSM.gameObject, "CONVO CANCEL");
			}
		}
		if (OnStatueSwapFinished != null)
		{
			OnStatueSwapFinished();
		}
	}

	private IEnumerator Jitter(float duration, float magnitude, GameObject obj)
	{
		Transform sprite = obj.transform;
		Vector3 initialPos = sprite.position;
		float elapsed = 0f;
		float half = magnitude / 2f;
		for (; elapsed < duration; elapsed += Time.deltaTime)
		{
			sprite.position = initialPos + new Vector3(UnityEngine.Random.Range(0f - half, half), UnityEngine.Random.Range(0f - half, half), 0f);
			yield return null;
		}
		sprite.position = initialPos;
	}

	private IEnumerator PlayAnimWait(Animator animator, string stateName, float normalizedTime)
	{
		if ((bool)animator)
		{
			animator.enabled = true;
			animator.Play(stateName, 0, normalizedTime);
			yield return null;
			yield return new WaitForSeconds(animator.GetCurrentAnimatorStateInfo(0).length);
			animator.enabled = false;
		}
	}

	private IEnumerator PlayParticlesDelay(ParticleSystem system, float delay)
	{
		if ((bool)system)
		{
			yield return new WaitForSeconds(delay);
			system.Play();
		}
	}

	private IEnumerator PlayAudioEventDelayed(AudioEvent audioEvent, float delay)
	{
		yield return new WaitForSeconds(delay);
		audioEvent.SpawnAndPlayOneShot(audioSourcePrefab, transform.position);
	}

	private void OnDrawGizmosSelected()
	{
		Gizmos.color = Color.green;
		Gizmos.DrawWireSphere(base.transform.position + new Vector3(0f, inspectCameraHeight, 0f), 0.25f);
	}
}
public class BossStatueCompletionStates : MonoBehaviour
{
	public enum Tiers
	{
		Tier1,
		Tier2,
		Tier3
	}

	[Serializable]
	public struct State
	{
		[SerializeField]
		private GameObject gameObject;

		[SerializeField]
		private string playmakerEvent;

		public void SetActive(bool value)
		{
			if ((bool)gameObject)
			{
				gameObject.SetActive(value);
				if (value && !string.IsNullOrEmpty(playmakerEvent))
				{
					FSMUtility.SendEventToGameObject(gameObject, playmakerEvent);
				}
			}
		}
	}

	public BossSummaryBoard bossListSource;

	public State defaultState;

	[ArrayForEnum(typeof(Tiers))]
	public State[] tierStates;

	public bool checkTiersAdditive = true;

	private void OnValidate()
	{
		ArrayForEnumAttribute.EnsureArraySize(ref tierStates, typeof(Tiers));
	}

	private void Start()
	{
		Tiers? highestCompletedTier = GetHighestCompletedTier();
		if (!highestCompletedTier.HasValue)
		{
			defaultState.SetActive(value: true);
			return;
		}
		for (int i = 0; i < tierStates.Length; i++)
		{
			tierStates[i].SetActive(value: false);
		}
		for (int j = 0; j < tierStates.Length; j++)
		{
			if (j == (int)highestCompletedTier.Value)
			{
				tierStates[j].SetActive(value: true);
			}
		}
	}

	public Tiers? GetHighestCompletedTier()
	{
		for (int num = Enum.GetNames(typeof(Tiers)).Length - 1; num >= 0; num--)
		{
			if (GetIsTierCompleted((Tiers)num))
			{
				return (Tiers)num;
			}
		}
		return null;
	}

	public bool GetIsTierCompleted(Tiers tier)
	{
		int completed = 0;
		int total = 0;
		CountCompletion(tier, out completed, out total);
		UnityEngine.Debug.Log($"Counted completion for {base.gameObject.name}, Total: {total}, Completed: {completed}, Tier: {tier.ToString()}");
		return completed >= total;
	}

	public void CountCompletion(Tiers tier, out int completed, out int total)
	{
		completed = 0;
		total = 0;
		BossStatue[] array = (bossListSource ? bossListSource.bossStatues.ToArray() : new BossStatue[0]);
		foreach (BossStatue bossStatue in array)
		{
			if (!bossStatue.gameObject.activeInHierarchy || bossStatue.hasNoTiers || bossStatue.dontCountCompletion)
			{
				continue;
			}
			if (bossStatue.HasRegularVersion)
			{
				total++;
				if (HasCompletedTier(bossStatue.StatueState, tier))
				{
					completed++;
				}
			}
			if (bossStatue.HasDreamVersion)
			{
				total++;
				if (HasCompletedTier(bossStatue.DreamStatueState, tier))
				{
					completed++;
				}
			}
		}
	}

	private bool HasCompletedTier(BossStatue.Completion completion, Tiers tier)
	{
		switch (tier)
		{
		case Tiers.Tier1:
			if (completion.completedTier1)
			{
				return true;
			}
			break;
		case Tiers.Tier2:
			if (completion.completedTier2)
			{
				return true;
			}
			break;
		case Tiers.Tier3:
			if (completion.completedTier3)
			{
				return true;
			}
			break;
		}
		if (checkTiersAdditive && (int)tier < Enum.GetNames(typeof(Tiers)).Length - 1)
		{
			return HasCompletedTier(completion, tier + 1);
		}
		return false;
	}
}
public interface IBossStatueToggle
{
	void SetOwner(BossStatue statue);

	void SetState(bool value);
}
public class BossStatueDreamToggle : MonoBehaviour, IBossStatueToggle
{
	public GameObject litPieces;

	public ParticleSystem[] particles;

	public GameObject dreamImpactPrefab;

	public Vector3 dreamImpactScale = new Vector3(4f, 4f, 1f);

	public Transform dreamImpactPoint;

	private bool canToggle = true;

	private ColorFader[] colorFaders;

	private int waitingForFade;

	public GameObject dreamBurstEffectPrefab;

	public GameObject dreamBurstEffectOffPrefab;

	public Transform dreamBurstSpawnPoint;

	private GameObject dreamBurstEffect;

	private GameObject dreamBurstEffectOff;

	private BossStatue bossStatue;

	private void OnEnable()
	{
		if ((bool)bossStatue && !bossStatue.UsingDreamVersion)
		{
			ParticleSystem[] array = particles;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].Stop(withChildren: true, ParticleSystemStopBehavior.StopEmitting);
			}
		}
	}

	private void Start()
	{
		if ((bool)litPieces)
		{
			litPieces.SetActive(value: true);
			if (!bossStatue || !bossStatue.UsingDreamVersion)
			{
				litPieces.SetActive(value: false);
			}
			colorFaders = litPieces.GetComponentsInChildren<ColorFader>(includeInactive: true);
			ColorFader[] array = colorFaders;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].OnFadeEnd += delegate(bool up)
				{
					if (!up)
					{
						waitingForFade--;
					}
				};
			}
		}
		if ((bool)dreamBurstEffectPrefab)
		{
			dreamBurstEffect = UnityEngine.Object.Instantiate(dreamBurstEffectPrefab, dreamBurstSpawnPoint);
			dreamBurstEffect.transform.localPosition = Vector3.zero;
			dreamBurstEffect.SetActive(value: false);
		}
		if ((bool)dreamBurstEffectOffPrefab)
		{
			dreamBurstEffectOff = UnityEngine.Object.Instantiate(dreamBurstEffectOffPrefab, dreamBurstSpawnPoint);
			dreamBurstEffectOff.transform.localPosition = Vector3.zero;
			dreamBurstEffectOff.SetActive(value: false);
		}
	}

	private void OnTriggerEnter2D(Collider2D collision)
	{
		if (base.gameObject.activeInHierarchy && canToggle && (bool)bossStatue && collision.tag == "Dream Attack")
		{
			bool flag = !bossStatue.UsingDreamVersion;
			bossStatue.SetDreamVersion(flag);
			if ((bool)dreamImpactPoint && (bool)dreamImpactPrefab)
			{
				dreamImpactPrefab.Spawn(dreamImpactPoint.position).transform.localScale = dreamImpactScale;
			}
			if ((bool)dreamBurstEffect)
			{
				dreamBurstEffect.SetActive(flag);
			}
			if ((bool)dreamBurstEffectOff)
			{
				dreamBurstEffectOff.SetActive(!flag);
			}
			StartCoroutine(Fade(bossStatue.UsingDreamVersion));
		}
	}

	private IEnumerator Fade(bool usingDreamVersion)
	{
		if (usingDreamVersion)
		{
			ParticleSystem[] array = particles;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].Play();
			}
		}
		else
		{
			ParticleSystem[] array = particles;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].Stop(withChildren: true, ParticleSystemStopBehavior.StopEmitting);
			}
		}
		if ((bool)litPieces)
		{
			litPieces.SetActive(value: true);
		}
		ColorFader[] array2 = colorFaders;
		foreach (ColorFader obj in array2)
		{
			if (!usingDreamVersion)
			{
				waitingForFade++;
			}
			obj.Fade(usingDreamVersion);
		}
		if (!usingDreamVersion)
		{
			while (waitingForFade > 0)
			{
				yield return null;
			}
			if ((bool)litPieces)
			{
				litPieces.SetActive(value: false);
			}
		}
	}

	public void SetOwner(BossStatue statue)
	{
		bossStatue = statue;
		if (!bossStatue.UsingDreamVersion)
		{
			ParticleSystem[] array = particles;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].Stop(withChildren: true, ParticleSystemStopBehavior.StopEmittingAndClear);
			}
			return;
		}
		if ((bool)litPieces)
		{
			litPieces.SetActive(value: true);
		}
		ColorFader[] array2 = colorFaders;
		for (int i = 0; i < array2.Length; i++)
		{
			array2[i].Fade(up: true);
		}
	}

	public void SetState(bool value)
	{
		canToggle = value;
		if (!value)
		{
			base.gameObject.SetActive(canToggle);
		}
	}
}
public class BossStatueExtraFlashEffect : MonoBehaviour
{
	public BossStatueFlashEffect mainEffect;

	public float flashSequenceDelay = 2f;

	public TriggerEnterEvent triggerUnlockEvent;

	public float toggleEnableTime = 1.35f;

	public GameObject toggle;

	private void Start()
	{
		BossStatue componentInParent = GetComponentInParent<BossStatue>();
		if ((bool)componentInParent && !componentInParent.DreamStatueState.hasBeenSeen && !componentInParent.isAlwaysUnlockedDream)
		{
			toggle.SetActive(value: false);
			if (componentInParent.DreamStatueState.isUnlocked)
			{
				if (componentInParent.StatueState.isUnlocked && !componentInParent.StatueState.hasBeenSeen && (bool)mainEffect)
				{
					mainEffect.OnFlashBegin += delegate
					{
						Invoke("DoAppear", flashSequenceDelay);
					};
				}
				else if ((bool)triggerUnlockEvent)
				{
					TriggerEnterEvent.CollisionEvent temp = null;
					temp = (TriggerEnterEvent.CollisionEvent)Delegate.Combine(temp, (TriggerEnterEvent.CollisionEvent)delegate
					{
						DoAppear();
						triggerUnlockEvent.OnTriggerEntered -= temp;
					});
					triggerUnlockEvent.OnTriggerEntered += temp;
				}
			}
		}
		base.gameObject.SetActive(value: false);
	}

	private void DoAppear()
	{
		base.gameObject.SetActive(value: true);
		StartCoroutine(AppearRoutine(toggle));
	}

	private IEnumerator AppearRoutine(GameObject toggle)
	{
		yield return new WaitForSeconds(toggleEnableTime);
		toggle.SetActive(value: true);
	}
}
public class BossStatueFlashEffect : MonoBehaviour
{
	public delegate void FlashCompleteDelegate();

	public SpriteRenderer templateSprite;

	public GameObject statueSpritesParent;

	private SpriteRenderer[] statueSprites;

	public GameObject inspect;

	public TriggerEnterEvent triggerEvent;

	private BossStatue parentStatue;

	private Animator animator;

	private Material mat;

	private MaterialPropertyBlock propBlock;

	public event FlashCompleteDelegate OnFlashBegin;

	private void Awake()
	{
		parentStatue = GetComponentInParent<BossStatue>();
		animator = GetComponent<Animator>();
	}

	private void Start()
	{
		if ((bool)templateSprite)
		{
			templateSprite.transform.localPosition += new Vector3(0f, -2000f, 0f);
			mat = new Material(templateSprite.sharedMaterial);
		}
		if (!parentStatue.StatueState.hasBeenSeen && !parentStatue.isAlwaysUnlocked)
		{
			if ((bool)statueSpritesParent)
			{
				statueSprites = statueSpritesParent.GetComponentsInChildren<SpriteRenderer>();
				SpriteRenderer[] array = statueSprites;
				foreach (SpriteRenderer obj in array)
				{
					obj.color = Color.clear;
					obj.sharedMaterial = mat;
				}
			}
			if ((bool)triggerEvent)
			{
				TriggerEnterEvent.CollisionEvent temp = null;
				temp = delegate
				{
					gameObject.SetActive(value: true);
					statueSpritesParent.SetActive(value: true);
					if ((bool)inspect)
					{
						inspect.SetActive(value: false);
					}
					StartCoroutine(FlashRoutine());
					triggerEvent.OnTriggerEntered -= temp;
				};
				triggerEvent.OnTriggerEntered += temp;
			}
		}
		propBlock = new MaterialPropertyBlock();
		base.gameObject.SetActive(value: false);
	}

	private IEnumerator FlashRoutine()
	{
		if (OnFlashBegin != null)
		{
			OnFlashBegin();
		}
		animator.cullingMode = AnimatorCullingMode.AlwaysAnimate;
		float duration = animator.GetCurrentAnimatorStateInfo(0).length;
		for (float elapsed = 0f; elapsed <= duration; elapsed += Time.deltaTime)
		{
			SpriteRenderer[] array = statueSprites;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].color = templateSprite.color;
			}
			templateSprite.GetPropertyBlock(propBlock);
			mat.SetFloat("_FlashAmount", propBlock.GetFloat("_FlashAmount"));
			yield return null;
		}
		yield return null;
		animator.enabled = false;
		SpriteFadeMaterial component = statueSpritesParent.GetComponent<SpriteFadeMaterial>();
		if ((bool)component)
		{
			component.FadeBack();
		}
	}

	public void FlashApex()
	{
		if ((bool)inspect)
		{
			inspect.SetActive(value: true);
		}
		parentStatue.SetPlaquesVisible(isEnabled: true);
	}
}
