public class BossStatueLoadManager : MonoBehaviour
{
	private static BossScene currentBossScene;

	private static BossScene previousBossScene;

	private static int activeCount;

	public static bool ShouldUnload
	{
		get
		{
			if (currentBossScene == null || previousBossScene == null || activeCount <= 0)
			{
				return false;
			}
			return currentBossScene != previousBossScene;
		}
	}

	private void OnEnable()
	{
		activeCount++;
		TransitionPoint component = GetComponent<TransitionPoint>();
		if ((bool)component)
		{
			component.OnBeforeTransition += Clear;
		}
	}

	private void OnDisable()
	{
		TransitionPoint component = GetComponent<TransitionPoint>();
		if ((bool)component)
		{
			component.OnBeforeTransition -= Clear;
		}
		activeCount--;
	}

	public static void Clear()
	{
		currentBossScene = null;
		previousBossScene = null;
	}

	public static void RecordBossScene(BossScene bossScene)
	{
		previousBossScene = currentBossScene;
		currentBossScene = bossScene;
		UnityEngine.Debug.Log(string.Format("Recorded statue boss scene. Current: {0}, Previous: {1}", currentBossScene ? currentBossScene.name : "null", previousBossScene ? previousBossScene.name : "null"));
	}
}
public class BossStatueSetUnlockIndicator : MonoBehaviour
{
	private int newStatueCount;

	private void Start()
	{
		BossStatue[] array = UnityEngine.Object.FindObjectsOfType<BossStatue>();
		foreach (BossStatue bossStatue in array)
		{
			if (!CheckIfNewBossStatue(bossStatue.StatueState) && !CheckIfNewBossStatue(bossStatue.DreamStatueState))
			{
				continue;
			}
			newStatueCount++;
			bossStatue.OnSeenNewStatue += delegate
			{
				newStatueCount--;
				if (newStatueCount == 0)
				{
					GameManager.instance.playerData.SetBoolSwappedArgs(value: false, "unlockedNewBossStatue");
				}
				else if (newStatueCount < 0)
				{
					UnityEngine.Debug.LogError("New statue count fell below zero. This means something has gone wrong!");
				}
			};
		}
	}

	private bool CheckIfNewBossStatue(BossStatue.Completion completion)
	{
		if (completion.isUnlocked)
		{
			return !completion.hasBeenSeen;
		}
		return false;
	}
}
public class BossStatueTrophyPlaque : MonoBehaviour
{
	public enum DisplayType
	{
		None = -1,
		Tier1,
		Tier2,
		Tier3
	}

	[ArrayForEnum(typeof(DisplayType))]
	public GameObject[] displayObjects;

	[Space]
	public Transform tierCompleteEffectPoint;

	public float tierCompleteEffectDelay = 1f;

	[ArrayForEnum(typeof(DisplayType))]
	public GameObject[] tierCompleteEffectPrefabs;

	private GameObject spawnedCompleteEffect;

	public void SetDisplay(DisplayType type)
	{
		SetDisplayObject(type);
	}

	public void DoTierCompleteEffect(DisplayType type)
	{
		if (type >= DisplayType.Tier1)
		{
			GameObject gameObject = tierCompleteEffectPrefabs[(int)type];
			if ((bool)gameObject)
			{
				spawnedCompleteEffect = UnityEngine.Object.Instantiate(gameObject, tierCompleteEffectPoint.position, gameObject.transform.rotation);
				spawnedCompleteEffect.SetActive(value: false);
				StartCoroutine(TierCompleteEffectDelayed());
			}
		}
	}

	private IEnumerator TierCompleteEffectDelayed()
	{
		yield return new WaitForSeconds(tierCompleteEffectDelay);
		spawnedCompleteEffect.SetActive(value: true);
	}

	private void SetDisplayObject(DisplayType type)
	{
		GameObject[] array = displayObjects;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].SetActive(value: false);
		}
		if (type >= DisplayType.Tier1)
		{
			displayObjects[(int)type].SetActive(value: true);
		}
	}

	public static DisplayType GetDisplayType(BossStatue.Completion completion)
	{
		DisplayType result = DisplayType.None;
		if (completion.completedTier3)
		{
			result = DisplayType.Tier3;
		}
		else if (completion.completedTier2)
		{
			result = DisplayType.Tier2;
		}
		else if (completion.completedTier1)
		{
			result = DisplayType.Tier1;
		}
		return result;
	}
}
