public class BossChallengeUI : MonoBehaviour
{
	public delegate void HideEvent();

	public delegate void LevelSelectedEvent();

	[Serializable]
	public class ButtonDisplay
	{
		public Image completeImage;

		public Image incompleteImage;

		public MenuSelectable button;

		public float enabledAlpha = 1f;

		public float disabledAlpha = 0.5f;

		public void SetupNavigation(bool isActive, ButtonDisplay selectOnUp, ButtonDisplay selectOnDown)
		{
			button.interactable = isActive;
			Navigation navigation = button.navigation;
			navigation.selectOnUp = selectOnUp.button;
			navigation.selectOnDown = selectOnDown.button;
			button.navigation = navigation;
			CanvasGroup component = button.GetComponent<CanvasGroup>();
			if ((bool)component)
			{
				component.alpha = (isActive ? enabledAlpha : disabledAlpha);
			}
		}

		public void SetState(bool isComplete)
		{
			if ((bool)completeImage)
			{
				completeImage.gameObject.SetActive(isComplete);
			}
			if ((bool)incompleteImage)
			{
				incompleteImage.gameObject.SetActive(!isComplete);
			}
		}
	}

	private BossStatue bossStatue;

	public Text bossNameText;

	public Text descriptionText;

	[Space]
	public MenuSelectable firstSelected;

	public string closeStateName = "GG_Challenge_Close";

	public ButtonDisplay tier1Button;

	public ButtonDisplay tier2Button;

	public ButtonDisplay tier3Button;

	public GameObject tier3UnlockEffect;

	public float tier3UnlockEffectDelay = 0.5f;

	private static int lastSelectedButton = -1;

	private Canvas canvas;

	private Animator animator;

	private CanvasGroup group;

	private bool started;

	public event HideEvent OnCancel;

	public event LevelSelectedEvent OnLevelSelected;

	private void Awake()
	{
		canvas = GetComponent<Canvas>();
		animator = GetComponent<Animator>();
		group = GetComponent<CanvasGroup>();
		if ((bool)group)
		{
			group.alpha = 0f;
		}
	}

	private void Start()
	{
		if ((bool)canvas && (bool)GameCameras.instance && (bool)GameCameras.instance.hudCamera)
		{
			canvas.worldCamera = GameCameras.instance.hudCamera;
		}
	}

	public void Setup(BossStatue bossStatue, string bossNameSheet, string bossNameKey, string descriptionSheet, string descriptionKey)
	{
		this.bossStatue = bossStatue;
		if ((bool)bossNameText)
		{
			bossNameText.text = global::Language.Language.Get(bossNameKey, bossNameSheet);
		}
		if ((bool)descriptionText)
		{
			descriptionText.text = global::Language.Language.Get(descriptionKey, descriptionSheet);
		}
		if (!bossStatue.hasNoTiers)
		{
			BossStatue.Completion completion = (bossStatue.UsingDreamVersion ? bossStatue.DreamStatueState : bossStatue.StatueState);
			tier1Button.SetState(completion.completedTier1);
			tier2Button.SetState(completion.completedTier2);
			tier3Button.SetState(completion.completedTier3);
			tier1Button.SetupNavigation(isActive: true, completion.completedTier2 ? tier3Button : tier2Button, tier2Button);
			tier2Button.SetupNavigation(isActive: true, tier1Button, completion.completedTier2 ? tier3Button : tier1Button);
			tier3Button.SetupNavigation(completion.completedTier2, tier2Button, tier1Button);
			if ((bool)tier3UnlockEffect && completion.completedTier2 && !completion.seenTier3Unlock)
			{
				StartCoroutine(ShowUnlockEffect());
			}
			StartCoroutine(SetFirstSelected());
		}
		else
		{
			LoadBoss(0, doHideAnim: false);
		}
	}

	private IEnumerator ShowUnlockEffect()
	{
		BossStatue.Completion state = (bossStatue.UsingDreamVersion ? bossStatue.DreamStatueState : bossStatue.StatueState);
		yield return new WaitForSeconds(tier3UnlockEffectDelay);
		tier3UnlockEffect.SetActive(value: true);
		state.seenTier3Unlock = true;
		if (bossStatue.UsingDreamVersion)
		{
			bossStatue.DreamStatueState = state;
		}
		else
		{
			bossStatue.StatueState = state;
		}
	}

	private IEnumerator SetFirstSelected()
	{
		MenuSelectable select = firstSelected;
		if (lastSelectedButton >= 0)
		{
			switch (lastSelectedButton)
			{
			case 0:
				if ((bool)tier1Button.button && tier1Button.button.interactable)
				{
					select = tier1Button.button;
				}
				break;
			case 1:
				if ((bool)tier2Button.button && tier2Button.button.interactable)
				{
					select = tier2Button.button;
				}
				break;
			case 2:
				if ((bool)tier3Button.button && tier3Button.button.interactable)
				{
					select = tier3Button.button;
				}
				break;
			}
		}
		if ((bool)select)
		{
			select.ForceDeselect();
			yield return null;
			select.DontPlaySelectSound = true;
			select.Select();
			InputHandler.Instance.StartUIInput();
		}
	}

	public void Hide()
	{
		Hide(doAnim: true);
	}

	public void Hide(bool doAnim)
	{
		if (doAnim)
		{
			StartCoroutine(HideAnim());
			return;
		}
		if (OnCancel != null)
		{
			OnCancel();
		}
		base.gameObject.SetActive(value: false);
	}

	private IEnumerator HideAnim()
	{
		if ((bool)animator)
		{
			animator.Play(closeStateName);
			AnimatorClipInfo[] currentAnimatorClipInfo = animator.GetCurrentAnimatorClipInfo(0);
			yield return new WaitForSeconds(currentAnimatorClipInfo[0].clip.length);
		}
		if ((bool)tier3UnlockEffect)
		{
			tier3UnlockEffect.SetActive(value: false);
		}
		if (OnCancel != null)
		{
			OnCancel();
		}
		gameObject.SetActive(value: false);
	}

	public void LoadBoss(int level)
	{
		LoadBoss(level, doHideAnim: true);
	}

	public void LoadBoss(int level, bool doHideAnim)
	{
		BossScene bossScene = (bossStatue.UsingDreamVersion ? bossStatue.dreamBossScene : bossStatue.bossScene);
		string text = bossScene.sceneName;
		switch (level)
		{
		case 0:
			text = bossScene.Tier1Scene;
			break;
		case 1:
			text = bossScene.Tier2Scene;
			break;
		case 2:
			text = bossScene.Tier3Scene;
			break;
		}
		if (!Application.CanStreamedLevelBeLoaded(text))
		{
			Hide(doHideAnim);
			UnityEngine.Debug.LogError($"Could not start boss scene. Scene: \"{text}\" does not exist!");
			return;
		}
		StaticVariableList.SetValue("bossSceneToLoad", text);
		BossStatueLoadManager.RecordBossScene(bossScene);
		OnCancel = null;
		Hide(doHideAnim);
		GameManager.instance.playerData.SetStringSwappedArgs(bossStatue.dreamReturnGate.name, "bossReturnEntryGate");
		BossSceneController.SetupEvent = delegate(BossSceneController self)
		{
			self.BossLevel = level;
			self.DreamReturnEvent = "DREAM RETURN";
			self.OnBossesDead += delegate
			{
				string fieldName = (bossStatue.UsingDreamVersion ? bossStatue.dreamStatueStatePD : bossStatue.statueStatePD);
				BossStatue.Completion playerDataVariable = GameManager.instance.GetPlayerDataVariable<BossStatue.Completion>(fieldName);
				switch (level)
				{
				case 0:
					playerDataVariable.completedTier1 = true;
					break;
				case 1:
					playerDataVariable.completedTier2 = true;
					break;
				case 2:
					playerDataVariable.completedTier3 = true;
					break;
				}
				GameManager.instance.SetPlayerDataVariable(fieldName, playerDataVariable);
				GameManager.instance.playerData.SetStringSwappedArgs(bossStatue.UsingDreamVersion ? bossStatue.dreamStatueStatePD : bossStatue.statueStatePD, "currentBossStatueCompletionKey");
				GameManager.instance.playerData.SetIntSwappedArgs(level, "bossStatueTargetLevel");
			};
			self.OnBossSceneComplete += delegate
			{
				self.DoDreamReturn();
			};
		};
		if (OnLevelSelected != null)
		{
			OnLevelSelected();
		}
	}

	public void RecordLastSelected(int index)
	{
		lastSelectedButton = index;
	}
}
[ActionCategory("Hollow Knight")]
public class ShowBossChallengeUI : FsmStateAction
{
	private static GameObject spawnedUI;

	public FsmGameObject prefab;

	public FsmString bossNameSheet;

	public FsmString bossNameKey;

	public FsmString descriptionSheet;

	public FsmString descriptionKey;

	public FsmEvent levelSelectedEvent;

	public override void Reset()
	{
		prefab = null;
		bossNameSheet = null;
		bossNameKey = null;
		descriptionSheet = null;
		descriptionKey = null;
		levelSelectedEvent = null;
	}

	public override void OnEnter()
	{
		if (spawnedUI == null && (bool)prefab.Value)
		{
			spawnedUI = UnityEngine.Object.Instantiate(prefab.Value);
			spawnedUI.SetActive(value: false);
		}
		if ((bool)spawnedUI)
		{
			GameObject gameObject = spawnedUI;
			gameObject.transform.position = prefab.Value.transform.position;
			gameObject.SetActive(value: true);
			BossChallengeUI ui = gameObject.GetComponent<BossChallengeUI>();
			if ((bool)ui)
			{
				BossStatue componentInParent = base.Owner.GetComponentInParent<BossStatue>();
				BossChallengeUI.HideEvent temp = null;
				temp = delegate
				{
					Finish();
					ui.OnCancel -= temp;
				};
				ui.OnCancel += temp;
				BossChallengeUI.LevelSelectedEvent temp2 = null;
				temp2 = delegate
				{
					Fsm.Event(levelSelectedEvent);
					ui.OnLevelSelected -= temp2;
				};
				ui.OnLevelSelected += temp2;
				ui.Setup(componentInParent, bossNameSheet.Value, bossNameKey.Value, descriptionSheet.Value, descriptionKey.Value);
				return;
			}
		}
		Finish();
	}
}
public class BossDoorChallengeCompleteUI : MonoBehaviour
{
	[Serializable]
	public class BindingIcon
	{
		public Image icon;

		public Sprite allUnlockedSprite;

		public GameObject[] flashEffects;

		private bool alreadyVisible;

		public void SetAlreadyVisible(bool value, bool allUnlocked)
		{
			GameObject[] array = flashEffects;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].SetActive(value: false);
			}
			if ((bool)icon)
			{
				icon.enabled = value;
			}
			alreadyVisible = value;
			if (allUnlocked)
			{
				SetAllUnlocked();
			}
		}

		public IEnumerator DoAppearAnim(float appearDelay)
		{
			if (!alreadyVisible && (bool)icon)
			{
				icon.enabled = false;
			}
			GameObject[] array = flashEffects;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].SetActive(value: true);
			}
			yield return new WaitForSeconds(appearDelay);
			if ((bool)icon)
			{
				icon.enabled = true;
			}
		}

		public IEnumerator DoAllAppearAnim(float appearDelay)
		{
			GameObject[] array = flashEffects;
			foreach (GameObject obj in array)
			{
				obj.SetActive(value: false);
				obj.SetActive(value: true);
			}
			yield return new WaitForSeconds(appearDelay);
			SetAllUnlocked();
		}

		private void SetAllUnlocked()
		{
			if ((bool)icon && (bool)allUnlockedSprite)
			{
				icon.sprite = allUnlockedSprite;
			}
		}
	}

	public float achievementShowDelay = 0.5f;

	public Animator animator;

	public float appearAnimDelay = 2f;

	public float appearEndWaitTime = 1f;

	public float bindingCapAnimDelay = 0.5f;

	public float bindingCapAppearDelay = 0.2f;

	public float completionCapAppearDelay = 0.75f;

	public float endAnimDelay = 2f;

	public AudioSource musicSource;

	public float musicDelay = 1f;

	[Space]
	public BindingIcon bindingCapNail;

	public BindingIcon bindingCapShell;

	public BindingIcon bindingCapCharm;

	public BindingIcon bindingCapSoul;

	public AudioSource audioSourcePrefab;

	public AudioEvent screenAppearSound;

	public AudioEvent bindingAppearSound;

	public float bindingAppearPitchIncrease = 0.05f;

	public AudioEvent bindingAllAppearSound;

	public AudioEvent coreAppearSound;

	[Space]
	public GameObject[] coreFlashEffects;

	public GameObject completeCore;

	public GameObject allBindingsCore;

	public GameObject noHitsCore;

	public GameObject allBindingsNoHitsCore;

	[Space]
	public CanvasGroup timerGroup;

	public float timerFadeDelay = 1f;

	public float timerFadeTime = 2f;

	public Text timerText;

	private bool waitingForInput;

	private void Start()
	{
		StartCoroutine(Sequence());
		StartCoroutine(ShowAchievements());
	}

	private void Update()
	{
		if (waitingForInput && (InputHandler.Instance.gameController.AnyButtonWasPressed || Input.anyKeyDown))
		{
			waitingForInput = false;
		}
	}

	private IEnumerator ShowAchievements()
	{
		yield return new WaitForSeconds(achievementShowDelay);
		GameManager.instance.AwardQueuedAchievements();
	}

	private IEnumerator Sequence()
	{
		GameObject[] array = coreFlashEffects;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].SetActive(value: false);
		}
		BossSequenceDoor.Completion completion = (BossSequenceController.IsInSequence ? BossSequenceController.PreviousCompletion : BossSequenceDoor.Completion.None);
		bool boundNail = !BossSequenceController.IsInSequence || BossSequenceController.BoundNail;
		bool boundShell = !BossSequenceController.IsInSequence || BossSequenceController.BoundShell;
		bool boundCharms = !BossSequenceController.IsInSequence || BossSequenceController.BoundCharms;
		bool boundSoul = !BossSequenceController.IsInSequence || BossSequenceController.BoundSoul;
		bool knightDamaged = !BossSequenceController.IsInSequence || BossSequenceController.KnightDamaged;
		if ((bool)completeCore)
		{
			completeCore.SetActive(value: false);
		}
		if ((bool)allBindingsCore)
		{
			allBindingsCore.SetActive(completion.allBindings);
		}
		if ((bool)noHitsCore)
		{
			noHitsCore.SetActive(completion.noHits && !completion.allBindings);
		}
		if ((bool)allBindingsNoHitsCore)
		{
			allBindingsNoHitsCore.SetActive(completion.noHits && completion.allBindings);
		}
		if ((bool)timerGroup)
		{
			timerGroup.alpha = 0f;
		}
		for (int j = 0; j < 4; j++)
		{
			BindingIcon bindingIcon = null;
			bool value = false;
			switch (j)
			{
			case 0:
				bindingIcon = bindingCapNail;
				value = completion.boundNail;
				break;
			case 1:
				bindingIcon = bindingCapShell;
				value = completion.boundShell;
				break;
			case 2:
				bindingIcon = bindingCapCharm;
				value = completion.boundCharms;
				break;
			case 3:
				bindingIcon = bindingCapSoul;
				value = completion.boundSoul;
				break;
			}
			bindingIcon?.SetAlreadyVisible(value, completion.allBindings);
		}
		yield return new WaitForSeconds(musicDelay);
		if ((bool)musicSource)
		{
			musicSource.Play();
		}
		yield return new WaitForSeconds(appearAnimDelay - musicDelay);
		if ((bool)animator)
		{
			animator.Play("Appear");
			yield return null;
			yield return new WaitForSeconds(animator.GetCurrentAnimatorStateInfo(0).length + appearEndWaitTime);
		}
		for (int k = 0; k < 4; k++)
		{
			BindingIcon bindingIcon2 = GetBindingIcon(k);
			if (bindingIcon2 != null)
			{
				StartCoroutine(bindingIcon2.DoAppearAnim(bindingCapAppearDelay));
				float num = (float)k * bindingAppearPitchIncrease;
				AudioEvent audioEvent = new AudioEvent
				{
					Clip = bindingAppearSound.Clip,
					PitchMin = bindingAppearSound.PitchMin + num,
					PitchMax = bindingAppearSound.PitchMax + num,
					Volume = bindingAppearSound.Volume
				};
				audioEvent.SpawnAndPlayOneShot(audioSourcePrefab, transform.position);
				yield return new WaitForSeconds(bindingCapAnimDelay);
			}
		}
		bool allBindings = boundNail & boundShell & boundCharms & boundSoul;
		if (allBindings)
		{
			for (int l = 0; l < 4; l++)
			{
				BindingIcon bindingIcon3 = GetBindingIcon(l);
				if (bindingIcon3 != null)
				{
					StartCoroutine(bindingIcon3.DoAllAppearAnim(bindingCapAppearDelay));
				}
			}
			bindingAllAppearSound.SpawnAndPlayOneShot(audioSourcePrefab, transform.position);
		}
		yield return new WaitForSeconds(completionCapAppearDelay);
		array = coreFlashEffects;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].SetActive(value: true);
		}
		coreAppearSound.SpawnAndPlayOneShot(audioSourcePrefab, transform.position);
		yield return new WaitForSeconds(bindingCapAppearDelay);
		if ((bool)completeCore)
		{
			completeCore.SetActive(!allBindings);
		}
		if ((bool)allBindingsCore & allBindings)
		{
			allBindingsCore.SetActive(value: true);
		}
		if ((bool)noHitsCore && !knightDamaged && !allBindings)
		{
			noHitsCore.SetActive(value: true);
		}
		if ((bool)allBindingsNoHitsCore && (!knightDamaged & allBindings))
		{
			allBindingsNoHitsCore.SetActive(value: true);
		}
		if ((bool)timerText)
		{
			int num2 = Mathf.RoundToInt(BossSequenceController.Timer);
			timerText.text = $"{num2 / 60:00}:{num2 % 60:00}";
			if ((bool)timerGroup)
			{
				yield return new WaitForSeconds(timerFadeDelay);
				for (float elapsed = 0f; elapsed <= timerFadeTime; elapsed += Time.deltaTime)
				{
					timerGroup.alpha = elapsed / timerFadeTime;
					yield return null;
				}
			}
		}
		yield return new WaitForSeconds(endAnimDelay);
		waitingForInput = true;
		while (waitingForInput)
		{
			yield return null;
		}
		if ((bool)animator)
		{
			animator.Play("Disappear");
			yield return null;
			yield return new WaitForSeconds(animator.GetCurrentAnimatorStateInfo(0).length);
		}
		HeroController.instance.EnterWithoutInput(flag: true);
		StaticVariableList.SetValue("finishedBossReturning", value: true);
		GameCameras.instance.cameraFadeFSM.SendEvent("FADE OUT INSTANT");
		yield return null;
		BossSequenceController.RestoreBindings();
		GameManager.instance.BeginSceneTransition(new GameManager.SceneLoadInfo
		{
			SceneName = (BossSequenceController.ShouldUnlockGGMode ? "GG_Unlock" : GameManager.instance.playerData.GetString("dreamReturnScene")),
			EntryGateName = GameManager.instance.playerData.GetString("bossReturnEntryGate"),
			EntryDelay = 0f,
			Visualization = GameManager.SceneLoadVisualizations.Dream,
			PreventCameraFadeOut = true,
			WaitForSceneTransitionCameraFade = false,
			AlwaysUnloadUnusedAssets = true
		});
	}

	private BindingIcon GetBindingIcon(int index)
	{
		BindingIcon result = null;
		switch (index)
		{
		case 0:
			if (BossSequenceController.BoundNail || !BossSequenceController.IsInSequence)
			{
				result = bindingCapNail;
			}
			break;
		case 1:
			if (BossSequenceController.BoundShell || !BossSequenceController.IsInSequence)
			{
				result = bindingCapShell;
			}
			break;
		case 2:
			if (BossSequenceController.BoundCharms || !BossSequenceController.IsInSequence)
			{
				result = bindingCapCharm;
			}
			break;
		case 3:
			if (BossSequenceController.BoundSoul || !BossSequenceController.IsInSequence)
			{
				result = bindingCapSoul;
			}
			break;
		}
		return result;
	}
}
public class BossDoorChallengeUI : MonoBehaviour
{
	public delegate void HideEvent();

	public delegate void BeginEvent();

	public Text titleTextSuper;

	public Text titleTextMain;

	public Text descriptionText;

	public BossDoorChallengeUIBindingButton boundNailButton;

	public BossDoorChallengeUIBindingButton boundHeartButton;

	public BossDoorChallengeUIBindingButton boundCharmsButton;

	public BossDoorChallengeUIBindingButton boundSoulButton;

	private BossDoorChallengeUIBindingButton[] buttons;

	private bool allPreviouslySelected;

	public AudioSource audioPlayerPrefab;

	public AudioEvent allSelectedSound;

	public GameObject allSelectedEffect;

	private BossSequenceDoor door;

	private Animator animator;

	private Canvas canvas;

	private CanvasGroup group;

	public event HideEvent OnHidden;

	public event BeginEvent OnBegin;

	private void Awake()
	{
		animator = GetComponent<Animator>();
		canvas = GetComponent<Canvas>();
		group = GetComponent<CanvasGroup>();
	}

	private void Start()
	{
		canvas.worldCamera = GameCameras.instance.hudCamera;
		buttons = new BossDoorChallengeUIBindingButton[4];
		buttons[0] = boundNailButton;
		buttons[1] = boundHeartButton;
		buttons[2] = boundCharmsButton;
		buttons[3] = boundSoulButton;
		BossDoorChallengeUIBindingButton[] array = buttons;
		foreach (BossDoorChallengeUIBindingButton obj in array)
		{
			obj.OnButtonSelected += UpdateAllButtons;
			obj.OnButtonCancelled += Hide;
			obj.Reset();
		}
		group.alpha = 0f;
	}

	private void OnEnable()
	{
		if (buttons != null)
		{
			BossDoorChallengeUIBindingButton[] array = buttons;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].Reset();
			}
			allPreviouslySelected = false;
		}
	}

	public void Setup(BossSequenceDoor door)
	{
		this.door = door;
		if ((bool)titleTextSuper)
		{
			titleTextSuper.text = global::Language.Language.Get(door.titleSuperKey, door.titleSuperSheet);
		}
		if ((bool)titleTextMain)
		{
			titleTextMain.text = global::Language.Language.Get(door.titleMainKey, door.titleMainSheet);
		}
		if ((bool)descriptionText)
		{
			descriptionText.text = global::Language.Language.Get(door.descriptionKey, door.descriptionSheet);
		}
	}

	private void UpdateAllButtons()
	{
		bool flag = true;
		BossDoorChallengeUIBindingButton[] array = buttons;
		for (int i = 0; i < array.Length; i++)
		{
			if (!array[i].Selected)
			{
				flag = false;
				break;
			}
		}
		if (flag || allPreviouslySelected)
		{
			array = buttons;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].SetAllSelected(flag);
			}
		}
		if (flag)
		{
			GameCameras.instance.cameraShakeFSM.SendEvent("AverageShake");
			allSelectedSound.SpawnAndPlayOneShot(audioPlayerPrefab, base.transform.position);
			if ((bool)allSelectedEffect)
			{
				allSelectedEffect.SetActive(value: false);
				allSelectedEffect.SetActive(value: true);
				allSelectedEffect.SetActiveChildren(value: true);
			}
		}
		allPreviouslySelected = flag;
	}

	public void Show()
	{
		base.gameObject.SetActive(value: true);
		StartCoroutine(ShowSequence());
		FSMUtility.SendEventToGameObject(GameCameras.instance.hudCanvas, "OUT");
	}

	private IEnumerator ShowSequence()
	{
		group.interactable = false;
		EventSystem.current.SetSelectedGameObject(null);
		yield return null;
		if ((bool)animator)
		{
			animator.Play("Open");
			yield return null;
			yield return new WaitForSeconds(animator.GetCurrentAnimatorStateInfo(0).length);
		}
		group.interactable = true;
		if (buttons.Length != 0)
		{
			EventSystem.current.SetSelectedGameObject(buttons[0].gameObject);
		}
		InputHandler.Instance.StartUIInput();
	}

	public void Hide()
	{
		StartCoroutine(HideSequence(sendEvent: true));
	}

	private IEnumerator HideSequence(bool sendEvent)
	{
		GameObject currentSelectedGameObject = EventSystem.current.currentSelectedGameObject;
		if ((bool)currentSelectedGameObject)
		{
			MenuButton component = currentSelectedGameObject.GetComponent<MenuButton>();
			if ((bool)component)
			{
				component.ForceDeselect();
			}
		}
		if ((bool)animator)
		{
			animator.Play("Close");
			yield return null;
			yield return new WaitForSeconds(animator.GetCurrentAnimatorStateInfo(0).length);
		}
		if (sendEvent && OnHidden != null)
		{
			OnHidden();
		}
		FSMUtility.SendEventToGameObject(GameCameras.instance.hudCanvas, "IN");
		if ((bool)allSelectedEffect)
		{
			allSelectedEffect.SetActive(value: false);
		}
		gameObject.SetActive(value: false);
	}

	public void Begin()
	{
		StartCoroutine(HideSequence(sendEvent: false));
		GameManager.instance.playerData.SetStringSwappedArgs(door.dreamReturnGate.name, "bossReturnEntryGate");
		BossSequenceController.ChallengeBindings challengeBindings = BossSequenceController.ChallengeBindings.None;
		if (boundNailButton.Selected)
		{
			challengeBindings |= BossSequenceController.ChallengeBindings.Nail;
		}
		if (boundHeartButton.Selected)
		{
			challengeBindings |= BossSequenceController.ChallengeBindings.Shell;
		}
		if (boundCharmsButton.Selected)
		{
			challengeBindings |= BossSequenceController.ChallengeBindings.Charms;
		}
		if (boundSoulButton.Selected)
		{
			challengeBindings |= BossSequenceController.ChallengeBindings.Soul;
		}
		BossSequenceController.SetupNewSequence(door.bossSequence, challengeBindings, door.playerDataString);
		if (OnBegin != null)
		{
			OnBegin();
		}
	}
}
[ActionCategory("Hollow Knight")]
public class ShowBossDoorChallengeUI : FsmStateAction
{
	private static BossDoorChallengeUI spawnedUI;

	public FsmOwnerDefault targetDoor;

	public FsmGameObject prefab;

	public FsmEvent cancelEvent;

	public FsmEvent challengeEvent;

	public override void Reset()
	{
