				Fsm.Event(challengeEvent);
				spawnedUI.OnBegin -= temp2;
			};
			spawnedUI.OnBegin += temp2;
		}
	}
}
public class BossDoorChallengeUIBindingButton : MonoBehaviour, ISubmitHandler, IEventSystemHandler, ICancelHandler, IPointerClickHandler
{
	public delegate void OnSelectionEvent();

	public delegate void OnCancelEvent();

	public Image iconImage;

	public Animator iconAnimator;

	private Sprite defaultSprite;

	public Sprite selectedSprite;

	public Sprite allSelectedSprite;

	public Animator chainAnimator;

	public GameObject bindAllEffect;

	public AudioSource audioSourcePrefab;

	public AudioEvent selectedSound;

	public AudioEvent deselectedSound;

	public float pitchShiftMin;

	public float pitchShiftMax = 0.5f;

	public int maxAmount = 4;

	private static int currentAmount;

	private bool isCounted;

	private bool selected;

	public bool Selected => selected;

	public event OnSelectionEvent OnButtonSelected;

	public event OnCancelEvent OnButtonCancelled;

	private void Awake()
	{
		if ((bool)iconImage)
		{
			defaultSprite = iconImage.sprite;
		}
	}

	public void Reset()
	{
		selected = false;
		if ((bool)chainAnimator)
		{
			chainAnimator.Play("Unbind", 0, 1f);
		}
		if ((bool)iconImage)
		{
			iconImage.sprite = defaultSprite;
			iconImage.SetNativeSize();
		}
		StartCoroutine(SetAnimSizeDelayed("Unbind", 1f));
		if ((bool)bindAllEffect)
		{
			bindAllEffect.SetActive(value: false);
		}
	}

	private void OnDisable()
	{
		if (isCounted)
		{
			currentAmount--;
			isCounted = false;
		}
	}

	public void OnSubmit(BaseEventData eventData)
	{
		selected = !selected;
		if ((bool)iconImage)
		{
			iconImage.sprite = (selected ? selectedSprite : defaultSprite);
			iconImage.SetNativeSize();
		}
		if ((bool)iconAnimator)
		{
			iconAnimator.Play("Select");
		}
		if ((bool)chainAnimator)
		{
			chainAnimator.Play(selected ? "Bind" : "Unbind");
		}
		if (selected && !isCounted)
		{
			isCounted = true;
			currentAmount++;
		}
		else if (!selected && isCounted)
		{
			currentAmount--;
			isCounted = false;
		}
		AudioEvent audioEvent = (selected ? selectedSound : deselectedSound);
		float num = Mathf.Lerp(pitchShiftMin, pitchShiftMax, (float)currentAmount / (float)maxAmount);
		audioEvent.PitchMin += num;
		audioEvent.PitchMax += num;
		audioEvent.SpawnAndPlayOneShot(audioSourcePrefab, base.transform.position);
		GameCameras.instance.cameraShakeFSM.SendEvent("EnemyKillShake");
		if (OnButtonSelected != null)
		{
			OnButtonSelected();
		}
	}

	public void SetAllSelected(bool value)
	{
		if ((bool)iconImage)
		{
			if (value)
			{
				iconImage.sprite = (allSelectedSprite ? allSelectedSprite : selectedSprite);
			}
			else
			{
				iconImage.sprite = (selected ? selectedSprite : defaultSprite);
			}
			iconImage.SetNativeSize();
		}
		if ((bool)iconAnimator)
		{
			iconAnimator.Play("Select");
		}
		StartCoroutine(SetAnimSizeDelayed(value ? "Bind All" : (selected ? "Bind" : "Unbind"), (!value && selected) ? 1 : 0));
		if ((bool)bindAllEffect)
		{
			bindAllEffect.SetActive(value);
		}
	}

	private IEnumerator SetAnimSizeDelayed(string anim, float normalizedTime)
	{
		if ((bool)chainAnimator)
		{
			chainAnimator.Play(anim, 0, normalizedTime);
		}
		float scale = chainAnimator.transform.localScale.x;
		chainAnimator.transform.SetScaleX(0f);
		yield return null;
		Image component = chainAnimator.GetComponent<Image>();
		if ((bool)component)
		{
			component.SetNativeSize();
		}
		chainAnimator.transform.SetScaleX(scale);
	}

	public void OnCancel(BaseEventData eventData)
	{
		if (OnButtonCancelled != null)
		{
			OnButtonCancelled();
		}
	}

	public void OnPointerClick(PointerEventData eventData)
	{
		OnSubmit(eventData);
	}
}
public class BossDoorLockUI : MonoBehaviour
{
	public GameObject iconParent;

	private BossDoorLockUIIcon[] bossIcons;

	public CanvasGroup buttonPrompts;

	public float buttonPromptFadeTime = 2f;

	private Coroutine fadeRoutine;

	private Coroutine fadeButtonRoutine;

	private CanvasGroup group;

	private Animator animator;

	private void Awake()
	{
		group = GetComponent<CanvasGroup>();
		animator = GetComponent<Animator>();
		bossIcons = (iconParent ? iconParent.GetComponentsInChildren<BossDoorLockUIIcon>() : new BossDoorLockUIIcon[0]);
	}

	public void Show(BossSequenceDoor door)
	{
		group.alpha = 0f;
		base.gameObject.SetActive(value: true);
		if ((bool)door && (bool)door.bossSequence)
		{
			BossSequenceDoor.Completion currentCompletion = door.CurrentCompletion;
			BossDoorLockUIIcon[] array = bossIcons;
			foreach (BossDoorLockUIIcon obj in array)
			{
				obj.bossIcon.enabled = false;
				obj.SetUnlocked(unlocked: false);
			}
			int count = door.bossSequence.Count;
			int num = 0;
			int num2 = 0;
			int num3 = 0;
			for (int j = 0; j < count; j++)
			{
				if (door.bossSequence.IsSceneHidden(j))
				{
					num--;
					continue;
				}
				BossScene bossScene = door.bossSequence.GetBossScene(j);
				string sceneObjectName = door.bossSequence.GetSceneObjectName(j);
				int num4 = j + num;
				num3 = num4;
				if (num4 >= bossIcons.Length || !bossIcons[num4])
				{
					continue;
				}
				bossIcons[num4].gameObject.SetActive(value: true);
				if ((bool)bossScene.DisplayIcon)
				{
					bossIcons[num4].bossIcon.enabled = true;
					bossIcons[num4].bossIcon.sprite = bossScene.DisplayIcon;
					bossIcons[num4].bossIcon.SetNativeSize();
				}
				if (bossScene.IsUnlocked(BossSceneCheckSource.Sequence))
				{
					if (currentCompletion.viewedBossSceneCompletions.Contains(sceneObjectName))
					{
						bossIcons[num4].SetUnlocked(unlocked: true);
						continue;
					}
					bossIcons[num4].SetUnlocked(unlocked: true, doUnlockAnim: true, num2);
					num2++;
					currentCompletion.viewedBossSceneCompletions.Add(sceneObjectName);
				}
			}
			for (int k = num3 + 1; k < bossIcons.Length; k++)
			{
				bossIcons[k].gameObject.SetActive(value: false);
			}
			door.CurrentCompletion = currentCompletion;
		}
		if (fadeRoutine != null)
		{
			StopCoroutine(fadeRoutine);
		}
		fadeRoutine = StartCoroutine(ShowRoutine());
		FSMUtility.SendEventToGameObject(GameCameras.instance.hudCanvas, "OUT");
	}

	public void Hide()
	{
		BossDoorLockUIIcon[] array = bossIcons;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].StopAllCoroutines();
		}
		if (fadeRoutine != null)
		{
			StopCoroutine(fadeRoutine);
		}
		fadeRoutine = StartCoroutine(HideRoutine());
	}

	private IEnumerator ShowRoutine()
	{
		if ((bool)buttonPrompts)
		{
			buttonPrompts.alpha = 0f;
		}
		if ((bool)animator)
		{
			animator.Play("Open");
			yield return null;
			yield return new WaitForSeconds(animator.GetCurrentAnimatorStateInfo(0).length);
		}
		group.alpha = 1f;
		if (fadeButtonRoutine != null)
		{
			StopCoroutine(fadeButtonRoutine);
		}
		fadeButtonRoutine = StartCoroutine(FadeButtonPrompts(1f, buttonPromptFadeTime));
		yield return fadeButtonRoutine;
		fadeRoutine = null;
	}

	private IEnumerator HideRoutine()
	{
		if ((bool)animator)
		{
			animator.Play("Close");
			yield return null;
			float length = animator.GetCurrentAnimatorStateInfo(0).length;
			if (fadeButtonRoutine != null)
			{
				StopCoroutine(fadeButtonRoutine);
			}
			fadeButtonRoutine = StartCoroutine(FadeButtonPrompts(0f, length));
			yield return new WaitForSeconds(length);
		}
		FSMUtility.SendEventToGameObject(GameCameras.instance.hudCanvas, "IN");
		gameObject.SetActive(value: false);
		fadeRoutine = null;
	}

	private IEnumerator FadeButtonPrompts(float toAlpha, float time)
	{
		if ((bool)buttonPrompts)
		{
			float startAlpha = buttonPrompts.alpha;
			for (float elapsed = 0f; elapsed < time; elapsed += Time.deltaTime)
			{
				buttonPrompts.alpha = Mathf.Lerp(startAlpha, toAlpha, elapsed / time);
				yield return null;
			}
			buttonPrompts.alpha = toAlpha;
		}
		fadeButtonRoutine = null;
	}
}
[RequireComponent(typeof(Animator))]
public class BossDoorLockUIIcon : MonoBehaviour
{
	public Image bossIcon;

	public float unlockAnimDelay = 1f;

	public float indexOffsetDelay = 0.25f;

	public AudioSource audioSourcePrefab;

	public AudioEvent unlockSound;

	private Animator animator;

	private void Awake()
	{
		animator = GetComponent<Animator>();
	}

	public void SetUnlocked(bool unlocked, bool doUnlockAnim = false, int indexAnimOffset = 0)
	{
		if (unlocked)
		{
			StartCoroutine(PlayAnimWithDelay("Unlock", doUnlockAnim, doUnlockAnim ? (unlockAnimDelay + indexOffsetDelay * (float)indexAnimOffset) : 0f));
		}
		else
		{
			animator.Play("Locked");
		}
	}

	private IEnumerator PlayAnimWithDelay(string anim, bool doAnim, float delay)
	{
		yield return new WaitForSeconds(delay);
		if (doAnim)
		{
			animator.Play(anim);
			unlockSound.SpawnAndPlayOneShot(audioSourcePrefab, transform.position);
		}
		else
		{
			animator.Play(anim, 0, 1f);
		}
	}
}
public class BossSummaryUI : MonoBehaviour
{
	public GameObject listItemTemplate;

	public Sprite[] stateSprites;

	public Sprite[] noTierStateSprites;

	public string defaultName = ".....";

	private Animator animator;

	private void Awake()
	{
		animator = GetComponent<Animator>();
	}

	private void Start()
	{
		CanvasGroup component = GetComponent<CanvasGroup>();
		if ((bool)component)
		{
			component.alpha = 0f;
		}
	}

	public void SetupUI(List<BossStatue> bossStatues)
	{
		listItemTemplate.SetActive(value: true);
		foreach (BossStatue bossStatue in bossStatues)
		{
			if (bossStatue.gameObject.activeInHierarchy)
			{
				CreateListItem(bossStatue);
				if ((bool)bossStatue && (bool)bossStatue.dreamBossScene)
				{
					CreateListItem(bossStatue, isAlt: true);
				}
			}
		}
		listItemTemplate.SetActive(value: false);
	}

	private void CreateListItem(BossStatue bossStatue, bool isAlt = false)
	{
		BossStatue.Completion completion = ((!(bossStatue != null)) ? BossStatue.Completion.None : (isAlt ? bossStatue.DreamStatueState : bossStatue.StatueState));
		if ((bool)listItemTemplate)
		{
			if (bossStatue.isHidden && !completion.completedTier1 && !completion.completedTier2 && !completion.completedTier3)
			{
				return;
			}
			GameObject obj = UnityEngine.Object.Instantiate(listItemTemplate, listItemTemplate.transform.parent);
			obj.name = string.Format("{0} ({1})", listItemTemplate.name, bossStatue ? bossStatue.gameObject.name : "null");
			int num = 0;
			if (completion.completedTier3)
			{
				num = 4;
			}
			else if (completion.completedTier2)
			{
				num = 3;
			}
			else if (completion.completedTier1)
			{
				num = 2;
			}
			else if (completion.isUnlocked)
			{
				num = 1;
			}
			Image componentInChildren = obj.GetComponentInChildren<Image>();
			if ((bool)componentInChildren)
			{
				if (bossStatue.hasNoTiers)
				{
					num = Mathf.Clamp(num, 0, 3);
					componentInChildren.sprite = noTierStateSprites[num];
					componentInChildren.SetNativeSize();
				}
				else if (num < stateSprites.Length && num >= 0)
				{
					componentInChildren.sprite = stateSprites[num];
					componentInChildren.SetNativeSize();
				}
			}
			Text componentInChildren2 = obj.GetComponentInChildren<Text>();
			if ((bool)componentInChildren2)
			{
				if (num > 0 && (bool)bossStatue)
				{
					componentInChildren2.text = global::Language.Language.Get(isAlt ? bossStatue.dreamBossDetails.nameKey : bossStatue.bossDetails.nameKey, isAlt ? bossStatue.dreamBossDetails.nameSheet : bossStatue.bossDetails.nameSheet).GetProcessed(LocalisationHelper.FontSource.Trajan).ToUpper();
				}
				else
				{
					componentInChildren2.text = defaultName;
				}
			}
		}
		else
		{
			UnityEngine.Debug.LogError("No List Item template assigned!", this);
		}
	}

	public void Show()
	{
		base.gameObject.SetActive(value: true);
		FSMUtility.SendEventToGameObject(GameCameras.instance.hudCanvas, "OUT");
	}

	public void Hide()
	{
		StartCoroutine(Close());
	}

	private IEnumerator Close()
	{
		if ((bool)animator)
		{
			animator.Play("Close");
			yield return null;
			yield return new WaitForSeconds(animator.GetCurrentAnimatorStateInfo(0).length);
		}
		FSMUtility.SendEventToGameObject(GameCameras.instance.hudCanvas, "IN");
		gameObject.SetActive(value: false);
	}
}
public class GodfinderGateIcon : MonoBehaviour
{
	public enum IconType
	{
		Bound,
		Unbound,
		Complete,
		CompleteRadiant
	}

	[ArrayForEnum(typeof(IconType))]
	public GameObject[] icons;

	public string completionPD;

	[UnityEngine.Tooltip("If assigned, icon will show unlocked when tier CAN be unlocked, rather than when the lock has been broken.")]
	public BossSequence unlockedSequence;

	public string requiredPDBool;

	private void Reset()
	{
		OnValidate();
	}

	private void OnValidate()
	{
		int num = Enum.GetNames(typeof(IconType)).Length;
		if (icons.Length != num)
		{
			GameObject[] array = icons;
			icons = new GameObject[num];
			for (int i = 0; i < array.Length; i++)
			{
				icons[i] = array[i];
			}
		}
	}

	private void SetIcon(IconType type)
	{
		for (int i = 0; i < icons.Length; i++)
		{
			if ((bool)icons[i])
			{
				icons[i].SetActive(i == (int)type);
			}
		}
	}

	public void Evaluate()
	{
		if (!string.IsNullOrEmpty(requiredPDBool) && !GameManager.instance.GetPlayerDataBool(requiredPDBool))
		{
			base.gameObject.SetActive(value: false);
			return;
		}
		BossSequenceDoor.Completion playerDataVariable = GameManager.instance.GetPlayerDataVariable<BossSequenceDoor.Completion>(completionPD);
		if (playerDataVariable.allBindings)
		{
			SetIcon(IconType.CompleteRadiant);
		}
		else if (playerDataVariable.completed)
		{
			SetIcon(IconType.Complete);
		}
		else if (playerDataVariable.unlocked || playerDataVariable.canUnlock || ((bool)unlockedSequence && unlockedSequence.IsUnlocked()))
		{
			SetIcon(IconType.Unbound);
		}
		else
		{
			SetIcon(IconType.Bound);
		}
		base.gameObject.SetActive(value: true);
	}
}
public class GodfinderGateIconManager : MonoBehaviour
{
	public GodfinderGateIcon[] gateIcons;

	public float offsetX = 8f;

	private void OnValidate()
	{
		DoLayout();
	}

	private void OnEnable()
	{
		GodfinderGateIcon[] array = gateIcons;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].Evaluate();
		}
		DoLayout();
	}

	private void DoLayout()
	{
		Vector3 vector = base.transform.position + new Vector3((0f - offsetX) / 2f, 0f);
		Vector3 vector2 = base.transform.position + new Vector3(offsetX / 2f, 0f);
		List<GodfinderGateIcon> list = new List<GodfinderGateIcon>();
		GodfinderGateIcon[] array = gateIcons;
		foreach (GodfinderGateIcon godfinderGateIcon in array)
		{
			if (godfinderGateIcon.gameObject.activeSelf)
			{
				list.Add(godfinderGateIcon);
			}
		}
		for (int j = 0; j < list.Count; j++)
		{
			if ((bool)list[j])
			{
				list[j].transform.position = Vector2.Lerp(vector, vector2, (float)j / (float)(list.Count - 1));
			}
		}
	}
}
public class GodfinderIcon : MonoBehaviour
{
	private static GodfinderIcon instance;

	public AudioSource audioPlayerPrefab;

	public AudioEvent showSound;

	private bool isVisible;

	private MeshRenderer renderer;

	private tk2dSpriteAnimator spriteAnimator;

	private void Awake()
	{
		instance = this;
		renderer = GetComponent<MeshRenderer>();
		spriteAnimator = GetComponent<tk2dSpriteAnimator>();
	}

	private void Start()
	{
		renderer.enabled = false;
	}

	private void Update()
	{
		if (isVisible && !spriteAnimator.Playing)
		{
			Hide();
		}
	}

	public static void ShowIcon(float delay, BossScene bossScene)
	{
		if (GameManager.instance.playerData.GetBool("bossRushMode") || !GameManager.instance.playerData.GetBool("hasGodfinder") || (bossScene != null && bossScene.IsUnlocked(BossSceneCheckSource.Godfinder)))
		{
			return;
		}
		GameManager.instance.playerData.SetBoolSwappedArgs(value: true, "unlockedNewBossStatue");
		if ((bool)instance)
		{
			if (GameManager.instance.GetCurrentMapZone() != "GODS_GLORY")
			{
				instance.StartCoroutine(instance.Show(delay));
			}
			else
			{
				GameManager.instance.playerData.SetBoolSwappedArgs(value: true, "queuedGodfinderIcon");
			}
		}
	}

	public static void ShowIconQueued(float delay)
	{
		if (!GameManager.instance.playerData.GetBool("bossRushMode") && (bool)instance && GameManager.instance.playerData.GetBool("queuedGodfinderIcon"))
		{
			instance.StartCoroutine(instance.Show(delay));
			GameManager.instance.playerData.SetBoolSwappedArgs(value: false, "queuedGodfinderIcon");
		}
	}

	private IEnumerator Show(float delay)
	{
		yield return new WaitForSeconds(delay);
		renderer.enabled = true;
		spriteAnimator.PlayFromFrame(0);
		showSound.SpawnAndPlayOneShot(audioPlayerPrefab, transform.position);
		isVisible = true;
	}

	private void Hide()
	{
		renderer.enabled = false;
		isVisible = false;
	}
}
