	public void IncreaseGameTimer(ref float timer)
	{
		if ((gameState == GameState.PLAYING || gameState == GameState.ENTERING_LEVEL || gameState == GameState.EXITING_LEVEL) && Time.unscaledDeltaTime < 1f)
		{
			timer += Time.unscaledDeltaTime;
		}
	}

	public void SaveGame(int saveSlot, Action<bool> callback)
	{
		if (saveSlot >= 0)
		{
			SaveLevelState();
			if (!gameConfig.disableSaveGame)
			{
				ShowSaveIcon();
				if (achievementHandler != null)
				{
					achievementHandler.FlushRecordsToDisk();
				}
				else
				{
					UnityEngine.Debug.LogError("Error saving achievements (PlayerAchievements is null)");
				}
				if (playerData != null)
				{
					playerData.SetFloat("playTime", playerData.GetFloat("playTime") + sessionPlayTimer);
					ResetGameTimer();
					playerData.SetString("version", "1.5.78.11833");
					playerData.SetInt("profileID", saveSlot);
					playerData.CountGameCompletion();
				}
				else
				{
					UnityEngine.Debug.LogError("Error updating PlayerData before save (PlayerData is null)");
				}
				try
				{
					SaveGameData saveGameData = new SaveGameData(playerData, sceneData);
					ModHooks.OnBeforeSaveGameSave(saveGameData);
					if (moddedData == null)
					{
						moddedData = new ModSavegameData();
					}
					ModHooks.OnSaveLocalSettings(moddedData);
					try
					{
						string text = ModdedSavePath(saveSlot);
						string value = JsonConvert.SerializeObject(moddedData, Newtonsoft.Json.Formatting.Indented, new JsonSerializerSettings
						{
							ContractResolver = ShouldSerializeContractResolver.Instance,
							TypeNameHandling = TypeNameHandling.Auto,
							Converters = JsonConverterTypes.ConverterTypes
						});
						if (File.Exists(text + ".bak"))
						{
							File.Delete(text + ".bak");
						}
						if (File.Exists(text))
						{
							File.Move(text, text + ".bak");
						}
						using FileStream stream = File.Create(text);
						using StreamWriter streamWriter = new StreamWriter(stream);
						streamWriter.Write(value);
					}
					catch (Exception message)
					{
						Modding.Logger.APILogger.LogError(message);
					}
					string text2 = null;
					try
					{
						text2 = JsonConvert.SerializeObject(saveGameData, Newtonsoft.Json.Formatting.Indented, new JsonSerializerSettings
						{
							ContractResolver = ShouldSerializeContractResolver.Instance,
							TypeNameHandling = TypeNameHandling.Auto,
							Converters = JsonConverterTypes.ConverterTypes
						});
					}
					catch (Exception message2)
					{
						Modding.Logger.LogError("Failed to serialize save using Json.NET, trying fallback.");
						Modding.Logger.APILogger.LogError(message2);
						text2 = JsonUtility.ToJson(saveGameData);
					}
					if (gameConfig.useSaveEncryption && !Platform.Current.IsFileSystemProtected)
					{
						string graph = Encryption.Encrypt(text2);
						BinaryFormatter binaryFormatter = new BinaryFormatter();
						MemoryStream memoryStream = new MemoryStream();
						binaryFormatter.Serialize(memoryStream, graph);
						byte[] binary = memoryStream.ToArray();
						memoryStream.Close();
						Platform.Current.WriteSaveSlot(saveSlot, binary, delegate(bool didSave)
						{
							HideSaveIcon();
							callback(didSave);
						});
					}
					else
					{
						Platform.Current.WriteSaveSlot(saveSlot, Encoding.UTF8.GetBytes(text2), delegate(bool didSave)
						{
							HideSaveIcon();
							if (callback != null)
							{
								callback(didSave);
							}
						});
					}
				}
				catch (Exception ex)
				{
					UnityEngine.Debug.LogError("GM Save - There was an error saving the game: " + ex);
					HideSaveIcon();
					if (callback != null)
					{
						CoreLoop.InvokeNext(delegate
						{
							callback(obj: false);
						});
					}
				}
				ModHooks.OnSavegameSave(saveSlot);
				return;
			}
			UnityEngine.Debug.Log("Saving game disabled. No save file written.");
			if (callback != null)
			{
				CoreLoop.InvokeNext(delegate
				{
					callback(obj: false);
				});
			}
			return;
		}
		UnityEngine.Debug.LogError("Save game slot not valid: " + saveSlot);
		if (callback != null)
		{
			CoreLoop.InvokeNext(delegate
			{
				callback(obj: false);
			});
		}
	}

	public void LoadGameFromUI(int saveSlot)
	{
		StartCoroutine(LoadGameFromUIRoutine(saveSlot));
	}

	private IEnumerator LoadGameFromUIRoutine(int saveSlot)
	{
		ui.ContinueGame();
		bool finishedLoading = false;
		bool successfullyLoaded = false;
		LoadGame(saveSlot, delegate(bool didLoad)
		{
			finishedLoading = true;
			successfullyLoaded = didLoad;
		});
		while (!finishedLoading)
		{
			yield return null;
		}
		if (successfullyLoaded)
		{
			ContinueGame();
		}
		else
		{
			ui.UIGoToMainMenu();
		}
	}

	public void LoadGame(int saveSlot, Action<bool> callback)
	{
		if (!Platform.IsSaveSlotIndexValid(saveSlot))
		{
			UnityEngine.Debug.LogErrorFormat("Cannot load from invalid save slot index {0}", saveSlot);
			if (callback != null)
			{
				CoreLoop.InvokeNext(delegate
				{
					callback(obj: false);
				});
			}
			return;
		}
		try
		{
			string path = ModdedSavePath(saveSlot);
			if (File.Exists(path))
			{
				using FileStream stream = File.OpenRead(path);
				using StreamReader streamReader = new StreamReader(stream);
				string text = streamReader.ReadToEnd();
				moddedData = JsonConvert.DeserializeObject<ModSavegameData>(text, new JsonSerializerSettings
				{
					ContractResolver = ShouldSerializeContractResolver.Instance,
					TypeNameHandling = TypeNameHandling.Auto,
					ObjectCreationHandling = ObjectCreationHandling.Replace,
					Converters = JsonConverterTypes.ConverterTypes
				});
				if (moddedData == null)
				{
					Modding.Logger.APILogger.LogError("Loaded mod savegame data deserialized to null: " + text);
					moddedData = new ModSavegameData();
				}
			}
			else
			{
				moddedData = new ModSavegameData();
			}
		}
		catch (Exception message)
		{
			Modding.Logger.APILogger.LogError(message);
			moddedData = new ModSavegameData();
		}
		ModHooks.OnLoadLocalSettings(moddedData);
		Platform.Current.ReadSaveSlot(saveSlot, delegate(byte[] fileBytes)
		{
			bool obj;
			try
			{
				string text2;
				if (gameConfig.useSaveEncryption && !Platform.Current.IsFileSystemProtected)
				{
					BinaryFormatter binaryFormatter = new BinaryFormatter();
					MemoryStream serializationStream = new MemoryStream(fileBytes);
					text2 = Encryption.Decrypt((string)binaryFormatter.Deserialize(serializationStream));
				}
				else
				{
					text2 = Encoding.UTF8.GetString(fileBytes);
				}
				SaveGameData saveGameData;
				try
				{
					saveGameData = JsonConvert.DeserializeObject<SaveGameData>(text2, new JsonSerializerSettings
					{
						ContractResolver = ShouldSerializeContractResolver.Instance,
						TypeNameHandling = TypeNameHandling.Auto,
						ObjectCreationHandling = ObjectCreationHandling.Replace,
						Converters = JsonConverterTypes.ConverterTypes
					});
				}
				catch (Exception message2)
				{
					Modding.Logger.APILogger.LogError("Failed to read save using Json.NET (GameManager::LoadGame), falling back.");
					Modding.Logger.APILogger.LogError(message2);
					saveGameData = JsonUtility.FromJson<SaveGameData>(text2);
				}
				PlayerData playerData = saveGameData.playerData;
				SceneData sceneData = saveGameData.sceneData;
				PlayerData.instance = playerData;
				this.playerData = playerData;
				SceneData.instance = sceneData;
				ModHooks.OnAfterSaveGameLoad(saveGameData);
				this.sceneData = sceneData;
				profileID = saveSlot;
				inputHandler.RefreshPlayerData();
				ModHooks.OnSavegameLoad(saveSlot);
				obj = true;
			}
			catch (Exception ex)
			{
				UnityEngine.Debug.LogFormat("Error loading save file for slot {0}: {1}", saveSlot, ex);
				obj = false;
			}
			if (callback != null)
			{
				callback(obj);
			}
		});
	}

	public void ClearSaveFile(int saveSlot, Action<bool> callback)
	{
		ModHooks.OnSavegameClear(saveSlot);
		orig_ClearSaveFile(saveSlot, callback);
		ModHooks.OnAfterSaveGameClear(saveSlot);
	}

	public void GetSaveStatsForSlot(int saveSlot, Action<SaveStats> callback)
	{
		if (!Platform.IsSaveSlotIndexValid(saveSlot))
		{
			UnityEngine.Debug.LogErrorFormat("Cannot get save stats for invalid slot {0}", saveSlot);
			if (callback != null)
			{
				CoreLoop.InvokeNext(delegate
				{
					callback(null);
				});
			}
			return;
		}
		Platform.Current.ReadSaveSlot(saveSlot, delegate(byte[] fileBytes)
		{
			if (fileBytes == null)
			{
				if (callback != null)
				{
					CoreLoop.InvokeNext(delegate
					{
						callback(null);
					});
				}
				return;
			}
			try
			{
				string text;
				if (gameConfig.useSaveEncryption && !Platform.Current.IsFileSystemProtected)
				{
					BinaryFormatter binaryFormatter = new BinaryFormatter();
					MemoryStream serializationStream = new MemoryStream(fileBytes);
					text = Encryption.Decrypt((string)binaryFormatter.Deserialize(serializationStream));
				}
				else
				{
					text = Encoding.UTF8.GetString(fileBytes);
				}
				SaveGameData saveGameData;
				try
				{
					saveGameData = JsonConvert.DeserializeObject<SaveGameData>(text, new JsonSerializerSettings
					{
						ContractResolver = ShouldSerializeContractResolver.Instance,
						TypeNameHandling = TypeNameHandling.Auto,
						ObjectCreationHandling = ObjectCreationHandling.Replace,
						Converters = JsonConverterTypes.ConverterTypes
					});
				}
				catch (Exception)
				{
					Modding.Logger.APILogger.LogWarn($"Failed to get save stats for slot {saveSlot} using Json.NET, falling back");
					saveGameData = JsonUtility.FromJson<SaveGameData>(text);
				}
				PlayerData playerData = saveGameData.playerData;
				SaveStats saveStats = new SaveStats(playerData.GetInt("maxHealthBase"), playerData.GetInt("geo"), playerData.GetVariable<MapZone>("mapZone"), playerData.GetFloat("playTime"), playerData.GetInt("MPReserveMax"), playerData.GetInt("permadeathMode"), playerData.GetBool("bossRushMode"), playerData.GetFloat("completionPercentage"), playerData.GetBool("unlockedCompletionRate"));
				if (callback != null)
				{
					CoreLoop.InvokeNext(delegate
					{
						callback(saveStats);
					});
				}
			}
			catch (Exception ex2)
			{
				UnityEngine.Debug.LogError("Error while loading save file for slot " + saveSlot + " Exception: " + ex2);
				if (callback != null)
				{
					CoreLoop.InvokeNext(delegate
					{
						callback(null);
					});
				}
			}
		});
	}

