			gameConfig.hideLanguageOption = true;
		}
	}

	public void orig_LoadScene(string destScene)
	{
		tilemapDirty = true;
		startedOnThisScene = false;
		nextSceneName = destScene;
		if (DestroyPersonalPools != null)
		{
			DestroyPersonalPools();
		}
		if (UnloadingLevel != null)
		{
			UnloadingLevel();
		}
		UnityEngine.SceneManagement.SceneManager.LoadScene(destScene);
	}

	public void orig_BeginSceneTransition(SceneLoadInfo info)
	{
		inventoryFSM.SendEvent("INVENTORY CANCEL");
		if (info.IsFirstLevelForPlayer)
		{
			ResetGameTimer();
		}
		if (BossSequenceController.IsInSequence)
		{
			if (BossSequenceController.ForceAssetUnload)
			{
				info.AlwaysUnloadUnusedAssets = true;
				UnityEngine.Debug.Log("Asset unload forced by next boss scene.");
			}
			else if (HeroController.instance.IsDreamReturning)
			{
				info.AlwaysUnloadUnusedAssets = true;
				UnityEngine.Debug.Log("Asset unload force by death in boss sequence.");
			}
		}
		else if (BossStatueLoadManager.ShouldUnload)
		{
			info.AlwaysUnloadUnusedAssets = true;
			UnityEngine.Debug.Log("Asset unload forced by challenging new boss statue");
		}
		StartCoroutine(BeginSceneTransitionRoutine(info));
	}

	public void orig_ClearSaveFile(int saveSlot, Action<bool> callback)
	{
		if (!Platform.IsSaveSlotIndexValid(saveSlot))
		{
			UnityEngine.Debug.LogErrorFormat("Cannot clear invalid save slot index {0}", saveSlot);
			if (callback != null)
			{
				CoreLoop.InvokeNext(delegate
				{
					callback(obj: false);
				});
			}
			return;
		}
		UnityEngine.Debug.LogFormat("Save file {0} {1}", saveSlot, "clearing...");
		Platform.Current.ClearSaveSlot(saveSlot, delegate(bool didClear)
		{
			UnityEngine.Debug.LogFormat("Save file {0} {1}", saveSlot, didClear ? "cleared" : "failed to clear");
			if (didClear)
			{
				playerData.Reset();
				sceneData.Reset();
			}
			if (callback != null)
			{
				callback(didClear);
			}
		});
	}

	public IEnumerator orig_PlayerDead(float waitTime)
	{
		cameraCtrl.FreezeInPlace(freezeTargetAlso: true);
		NoLongerFirstGame();
		ResetSemiPersistentItems();
		bool finishedSaving = false;
		SaveGame(profileID, delegate
		{
			finishedSaving = true;
		});
		yield return new WaitForSeconds(waitTime);
		cameraCtrl.FadeOut(CameraFadeType.HERO_DEATH);
		yield return new WaitForSeconds(0.8f);
		while (!finishedSaving)
		{
			yield return null;
		}
		if (playerData.GetInt("permadeathMode") == 0)
		{
			ReadyForRespawn(isFirstLevelForPlayer: false);
		}
		else if (playerData.GetInt("permadeathMode") == 2)
		{
			LoadScene("PermaDeath");
		}
	}

	private static string ModdedSavePath(int slot)
	{
		return Path.Combine(Application.persistentDataPath, $"user{slot}.modded.json");
	}

	public void orig_SetupSceneRefs(bool refreshTilemapInfo)
	{
		UpdateSceneName();
		if (ui == null)
		{
			ui = UIManager.instance;
		}
		GameObject gameObject = GameObject.FindGameObjectWithTag("SceneManager");
		if (gameObject != null)
		{
			sm = gameObject.GetComponent<SceneManager>();
		}
		else
		{
			UnityEngine.Debug.Log("Scene Manager missing from scene " + sceneName);
		}
		if (IsGameplayScene())
		{
			if (hero_ctrl == null)
			{
				SetupHeroRefs();
			}
			inputHandler.AttachHeroController(hero_ctrl);
			if (refreshTilemapInfo)
			{
				RefreshTilemapInfo(sceneName);
			}
			soulOrb_fsm = gameCams.soulOrbFSM;
			soulVessel_fsm = gameCams.soulVesselFSM;
		}
	}

	public void orig_OnWillActivateFirstLevel()
	{
		HeroController.instance.isEnteringFirstLevel = true;
		entryGateName = "top1";
		SetState(GameState.PLAYING);
		ui.ConfigureMenu();
	}

	public IEnumerator PauseToggleDynamicMenu(MenuScreen screen, bool allowUnpause = false)
	{
		if (TimeSlowed)
		{
			yield break;
		}
		if (!playerData.GetBool("disablePause") && gameState == GameState.PLAYING)
		{
			gameCams.StopCameraShake();
			inputHandler.PreventPause();
			inputHandler.StopUIInput();
			actorSnapshotPaused.TransitionTo(0f);
			isPaused = true;
			SetState(GameState.PAUSED);
			ui.AudioGoToPauseMenu(0.2f);
			ui.UIPauseToDynamicMenu(screen);
			if (HeroController.instance != null)
			{
				HeroController.instance.Pause();
			}
			gameCams.MoveMenuToHUDCamera();
			SetTimeScale(0f);
			yield return new WaitForSecondsRealtime(0.8f);
			inputHandler.AllowPause();
		}
		else if (allowUnpause && gameState == GameState.PAUSED)
		{
			gameCams.ResumeCameraShake();
			inputHandler.PreventPause();
			actorSnapshotUnpaused.TransitionTo(0f);
			isPaused = false;
			ui.AudioGoToGameplay(0.2f);
			ui.SetState(UIState.PLAYING);
			SetState(GameState.PLAYING);
			if (HeroController.instance != null)
			{
				HeroController.instance.UnPause();
			}
			MenuButtonList.ClearAllLastSelected();
			SetTimeScale(1f);
			yield return new WaitForSecondsRealtime(0.8f);
			inputHandler.AllowPause();
		}
	}
}
