[ActionCategory("Hollow Knight")]
public class CheckCanDreamWarpInScene : FSMUtility.CheckFsmStateAction
{
	private static Func<bool> bossRushCheck = () => !GameManager.instance.playerData.GetBool("bossRushMode");

	private Dictionary<string, Func<bool>> sceneCheckFunctions = new Dictionary<string, Func<bool>>
	{
		{ "GG_Atrium", bossRushCheck },
		{ "GG_Atrium_Roof", bossRushCheck },
		{ "GG_Workshop", bossRushCheck },
		{ "GG_Blue_Room", bossRushCheck },
		{
			"GG_Land_of_Storms",
			() => false
		},
		{
			"GG_Unlock_Wastes",
			() => false
		}
	};

	public override bool IsTrue
	{
		get
		{
			string sceneNameString = GameManager.instance.GetSceneNameString();
			if (sceneCheckFunctions.ContainsKey(sceneNameString))
			{
				return sceneCheckFunctions[sceneNameString]();
			}
			return true;
		}
	}
}
[Serializable]
public class SaveStats
{
	private PlayTime playTimeStruct;

	public int maxHealth { get; private set; }

	public int geo { get; private set; }

	public MapZone mapZone { get; private set; }

	public float playTime { get; private set; }

	public int maxMPReserve { get; private set; }

	public int permadeathMode { get; private set; }

	public bool bossRushMode { get; private set; }

	public float completionPercentage { get; private set; }

	public bool unlockedCompletionRate { get; private set; }

	public Dictionary<string, string> LoadedMods { get; set; }

	public string Name { get; set; }

	public SaveStats(int maxHealth, int geo, MapZone mapZone, float playTime, int maxMPReserve, int permadeathMode, bool bossRushMode, float completionPercentage, bool unlockedCompletionRate)
	{
		this.maxHealth = maxHealth;
		this.geo = geo;
		this.mapZone = mapZone;
		this.playTime = playTime;
		this.maxMPReserve = maxMPReserve;
		this.permadeathMode = permadeathMode;
		this.bossRushMode = bossRushMode;
		this.completionPercentage = completionPercentage;
		playTimeStruct.RawTime = playTime;
		this.unlockedCompletionRate = unlockedCompletionRate;
	}

	public string GetPlaytimeHHMM()
	{
		if (playTimeStruct.HasHours)
		{
			return $"{(int)playTimeStruct.Hours:0}h {(int)playTimeStruct.Minutes:00}m";
		}
		return $"{(int)playTimeStruct.Minutes:0}m";
	}

	public string GetPlaytimeHHMMSS()
	{
		if (!playTimeStruct.HasHours)
		{
			return $"{(int)playTimeStruct.Minutes:0}m {(int)playTimeStruct.Seconds:00}s";
		}
		if (!playTimeStruct.HasMinutes)
		{
			return $"{(int)playTimeStruct.Seconds:0}s";
		}
		return $"{(int)playTimeStruct.Hours:0}h {(int)playTimeStruct.Minutes:00}m {(int)playTimeStruct.Seconds:00}s";
	}

	public string GetCompletionPercentage()
	{
		return completionPercentage + "%";
	}

	public int GetMPSlotsVisible()
	{
		return (int)((float)maxMPReserve / 33f);
	}
}
public struct PlayTime
{
	public float RawTime;

	private TimeSpan time => TimeSpan.FromSeconds(RawTime);

	public float Hours => (float)Math.Floor(time.TotalHours);

	public float Minutes => time.Minutes;

	public float Seconds => time.Seconds;

	public bool HasHours => time.TotalHours >= 1.0;

	public bool HasMinutes => time.TotalMinutes >= 1.0;
}
[Serializable]
public class SceneManager : MonoBehaviour
{
	[Space(6f)]
	[UnityEngine.Tooltip("This denotes the type of this scene, mainly if it is a gameplay scene or not.")]
	public SceneType sceneType;

	[Header("Gameplay Scene Settings")]
	[UnityEngine.Tooltip("The area of the map this scene belongs to.")]
	[Space(6f)]
	public MapZone mapZone;

	[UnityEngine.Tooltip("Determines if this area is currently windy.")]
	public bool isWindy;

	[UnityEngine.Tooltip("Determines if this level experiences tremors.")]
	public bool isTremorZone;

	[UnityEngine.Tooltip("Set environment type on scene entry. 0 = Dust, 1 = Grass, 2 = Bone, 3 = Spa, 4 = Metal, 5 = No Effect, 6 = Wet")]
	public int environmentType;

	public int darknessLevel;

	public bool noLantern;

	[Header("Camera Color Correction Curves")]
	[Range(0f, 5f)]
	public float saturation;

	public bool ignorePlatformSaturationModifiers;

	public AnimationCurve redChannel;

	public AnimationCurve greenChannel;

	public AnimationCurve blueChannel;

	[Header("Ambient Light")]
	[UnityEngine.Tooltip("The default ambient light colour for this scene.")]
	[Space(6f)]
	public Color defaultColor;

	[UnityEngine.Tooltip("The intensity of the ambient light in this scene.")]
	[Range(0f, 1f)]
	public float defaultIntensity;

	[Header("Hero Light")]
	[UnityEngine.Tooltip("Color of the hero's light gradient (not point lights)")]
	[Space(6f)]
	public Color heroLightColor;

	[Header("Scene Particles")]
	public bool noParticles;

	public MapZone overrideParticlesWith;

	[Header("Audio Snapshots")]
	[Space(6f)]
	[SerializeField]
	private AtmosCue atmosCue;

	[SerializeField]
	private MusicCue musicCue;

	[SerializeField]
	private MusicCue infectedMusicCue;

	[SerializeField]
	private AudioMixerSnapshot musicSnapshot;

	[SerializeField]
	private float musicDelayTime;

	[SerializeField]
	private float musicTransitionTime;

	public AudioMixerSnapshot atmosSnapshot;

	public AudioMixerSnapshot enviroSnapshot;

	public AudioMixerSnapshot actorSnapshot;

	public AudioMixerSnapshot shadeSnapshot;

	public float transitionTime;

	[Header("Scene Border")]
	[Space(6f)]
	public GameObject borderPrefab;

	[Header("Mapping")]
	[Space(6f)]
	public bool manualMapTrigger;

	[Header("Object Spawns")]
	[Space(6f)]
	public GameObject hollowShadeObject;

	public GameObject dreamgateObject;

	private GameManager gm;

	private GameCameras gc;

	private HeroController heroCtrl;

	private PlayerData pd;

	private float enviroTimer;

	private bool enviroSent;

	private bool heroInfoSent;

	private bool setSaturation;

	private bool isGameplayScene;

	public static float AmbientIntesityMix = 0.5f;

	private const float SwitchConstant = 0.17f;

	private const float SwitchConstantGG = 0.1466f;

	private const float RegularConstant = 0.1466f;

	private bool gameplayScene;

	private void Start()
	{
		try
		{
			orig_Start();
		}
		catch (NullReferenceException) when (!ModLoader.LoadState.HasFlag(ModLoader.ModLoadState.Preloaded))
		{
		}
	}

	public static void SetLighting(Color ambientLightColor, float ambientLightIntensity)
	{
		float num = Mathf.Lerp(1f, ambientLightIntensity, AmbientIntesityMix);
		RenderSettings.ambientLight = new Color(ambientLightColor.r * num, ambientLightColor.g * num, ambientLightColor.b * num, 1f);
		RenderSettings.ambientIntensity = 1f;
	}

	private void Update()
	{
		if (gameplayScene && !heroInfoSent && heroCtrl != null && (heroCtrl.heroLight == null || heroCtrl.heroLight.material == null))
		{
			heroCtrl.SetDarkness(darknessLevel);
			heroInfoSent = true;
		}
		orig_Update();
	}

	public int GetDarknessLevel()
	{
		return darknessLevel;
	}

	public void SetWindy(bool setting)
	{
		isWindy = setting;
	}

	public float AdjustSaturation(float originalSaturation)
	{
		if (ignorePlatformSaturationModifiers)
		{
			return originalSaturation;
		}
		return AdjustSaturationForPlatform(originalSaturation, mapZone);
	}

	public static float AdjustSaturationForPlatform(float originalSaturation, MapZone? mapZone = null)
	{
		if (Application.platform == RuntimePlatform.Switch)
		{
			if (mapZone.HasValue && mapZone == MapZone.GODS_GLORY)
			{
				return originalSaturation + 0.1466f;
			}
			return originalSaturation + 0.17f;
		}
		return originalSaturation + 0.1466f;
	}

	private void PrintDebugInfo()
	{
		string text = "SM Setting Curves to ";
		text += "R: (";
		Keyframe[] keys = redChannel.keys;
		foreach (Keyframe keyframe in keys)
		{
			text = text + keyframe.value + ", ";
		}
		text += ") G: (";
		keys = greenChannel.keys;
		foreach (Keyframe keyframe2 in keys)
		{
			text = text + keyframe2.value + ", ";
		}
		text += " ) B: (";
		keys = blueChannel.keys;
		foreach (Keyframe keyframe3 in keys)
		{
			text = text + keyframe3.value + ", ";
		}
		text = text + ") S: " + saturation;
		UnityEngine.Debug.Log(text);
	}

	private void DrawBlackBorders()
	{
		List<GameObject> list = new List<GameObject>();
		GameObject gameObject = UnityEngine.Object.Instantiate(borderPrefab);
		gameObject.transform.SetPosition2D(gm.sceneWidth + 10f, gm.sceneHeight / 2f);
		gameObject.transform.localScale = new Vector2(20f, gm.sceneHeight + 40f);
		list.Add(gameObject);
		gameObject = UnityEngine.Object.Instantiate(borderPrefab);
		gameObject.transform.SetPosition2D(-10f, gm.sceneHeight / 2f);
		gameObject.transform.localScale = new Vector2(20f, gm.sceneHeight + 40f);
		list.Add(gameObject);
		gameObject = UnityEngine.Object.Instantiate(borderPrefab);
		gameObject.transform.SetPosition2D(gm.sceneWidth / 2f, gm.sceneHeight + 10f);
		gameObject.transform.localScale = new Vector2(40f + gm.sceneWidth, 20f);
		list.Add(gameObject);
		gameObject = UnityEngine.Object.Instantiate(borderPrefab);
		gameObject.transform.SetPosition2D(gm.sceneWidth / 2f, -10f);
		gameObject.transform.localScale = new Vector2(40f + gm.sceneWidth, 20f);
		list.Add(gameObject);
		ModHooks.OnDrawBlackBorders(list);
		foreach (GameObject item in list)
		{
			UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(item, base.gameObject.scene);
		}
	}

	private void AddSceneMapped()
	{
		if (!pd.GetVariable<List<string>>("scenesVisited").Contains(gm.GetSceneNameString()) && !manualMapTrigger && mapZone != MapZone.WHITE_PALACE && mapZone != MapZone.GODS_GLORY)
		{
			pd.GetVariable<List<string>>("scenesVisited").Add(gm.GetSceneNameString());
		}
	}

	public void UpdateSceneSettings(SceneManagerSettings sms)
	{
		mapZone = sms.mapZone;
		defaultColor = new Color(sms.defaultColor.r, sms.defaultColor.g, sms.defaultColor.b, sms.defaultColor.a);
		defaultIntensity = sms.defaultIntensity;
		saturation = sms.saturation;
		redChannel = new AnimationCurve(sms.redChannel.keys.Clone() as Keyframe[]);
		greenChannel = new AnimationCurve(sms.greenChannel.keys.Clone() as Keyframe[]);
		blueChannel = new AnimationCurve(sms.blueChannel.keys.Clone() as Keyframe[]);
		heroLightColor = new Color(sms.heroLightColor.r, sms.heroLightColor.g, sms.heroLightColor.b, sms.heroLightColor.a);
	}

	private void orig_Update()
	{
		if (!isGameplayScene)
		{
			return;
		}
		if (enviroTimer < 0.25f)
		{
			enviroTimer += Time.deltaTime;
		}
		else if (!enviroSent && heroCtrl != null)
		{
			heroCtrl.checkEnvironment();
			enviroSent = true;
		}
		if (!heroInfoSent && heroCtrl != null)
		{
			heroCtrl.heroLight.material.SetColor("_Color", Color.white);
			heroCtrl.SetDarkness(darknessLevel);
			heroInfoSent = true;
		}
		if (!setSaturation)
		{
			if (AdjustSaturation(saturation) != gc.colorCorrectionCurves.saturation)
			{
				gc.colorCorrectionCurves.saturation = AdjustSaturation(saturation);
			}
			setSaturation = true;
		}
	}

	private void orig_Start()
	{
		gm = GameManager.instance;
		gc = GameCameras.instance;
		pd = PlayerData.instance;
		if (gm.IsGameplayScene())
		{
			isGameplayScene = true;
			heroCtrl = HeroController.instance;
		}
		else
		{
			isGameplayScene = false;
		}
		gc.colorCorrectionCurves.saturation = AdjustSaturation(saturation);
		gc.colorCorrectionCurves.redChannel = redChannel;
		gc.colorCorrectionCurves.greenChannel = greenChannel;
		gc.colorCorrectionCurves.blueChannel = blueChannel;
		gc.colorCorrectionCurves.UpdateParameters();
		gc.sceneColorManager.SaturationA = AdjustSaturation(saturation);
		gc.sceneColorManager.RedA = redChannel;
		gc.sceneColorManager.GreenA = greenChannel;
		gc.sceneColorManager.BlueA = blueChannel;
		SetLighting(defaultColor, defaultIntensity);
		gc.sceneColorManager.AmbientColorA = defaultColor;
		gc.sceneColorManager.AmbientIntensityA = defaultIntensity;
		if (isGameplayScene)
		{
			if (heroCtrl != null)
			{
				heroCtrl.heroLight.color = heroLightColor;
			}
			gc.sceneColorManager.HeroLightColorA = heroLightColor;
		}
		pd.SetIntSwappedArgs(environmentType, "environmentType");
		pd.SetIntSwappedArgs(environmentType, "environmentTypeDefault");
		if ((bool)GameManager.instance)
		{
			GameManager.EnterSceneEvent temp = null;
			temp = delegate
			{
				AddSceneMapped();
				GameManager.instance.OnFinishedEnteringScene -= temp;
			};
			GameManager.instance.OnFinishedEnteringScene += temp;
		}
		else
		{
			AddSceneMapped();
		}
		if (atmosCue != null)
		{
			gm.AudioManager.ApplyAtmosCue(atmosCue, transitionTime);
		}
		MusicCue musicCue = this.musicCue;
		if (gm.playerData.GetBool("crossroadsInfected") && infectedMusicCue != null)
		{
			musicCue = infectedMusicCue;
		}
		if (musicCue != null)
		{
			gm.AudioManager.ApplyMusicCue(musicCue, musicDelayTime, musicTransitionTime, applySnapshot: false);
		}
		if (musicSnapshot != null)
		{
			gm.AudioManager.ApplyMusicSnapshot(musicSnapshot, musicDelayTime, musicTransitionTime);
		}
		if (enviroSnapshot != null)
		{
			enviroSnapshot.TransitionTo(transitionTime);
		}
		if (actorSnapshot != null)
		{
			actorSnapshot.TransitionTo(transitionTime);
		}
		if (shadeSnapshot != null)
		{
			shadeSnapshot.TransitionTo(transitionTime);
		}
		if (sceneType == SceneType.GAMEPLAY)
		{
			GameObject gameObject = GameObject.FindGameObjectWithTag("Vignette");
			if ((bool)gameObject)
			{
				PlayMakerFSM playMakerFSM = FSMUtility.LocateFSM(gameObject, "Darkness Control");
				if ((bool)playMakerFSM)
				{
					FSMUtility.SetInt(playMakerFSM, "Darkness Level", darknessLevel);
				}
				if (!noLantern)
				{
					FSMUtility.LocateFSM(gameObject, "Darkness Control").SendEvent("RESET");
				}
				else
				{
					FSMUtility.LocateFSM(gameObject, "Darkness Control").SendEvent("SCENE RESET NO LANTERN");
					if (heroCtrl != null)
					{
						heroCtrl.wieldingLantern = false;
					}
				}
			}
		}
		if (isGameplayScene)
		{
			DrawBlackBorders();
		}
		if (pd.GetBool("soulLimited") && isGameplayScene && pd.GetString("shadeScene") == base.gameObject.scene.name)
		{
			GameObject obj = UnityEngine.Object.Instantiate(hollowShadeObject, new Vector3(pd.GetFloat("shadePositionX"), pd.GetFloat("shadePositionY"), 0.006f), Quaternion.identity);
			obj.transform.SetParent(base.transform, worldPositionStays: true);
			obj.transform.SetParent(null);
		}
		if (isGameplayScene && pd.GetString("dreamGateScene") == base.gameObject.scene.name)
		{
			GameObject obj2 = UnityEngine.Object.Instantiate(dreamgateObject, new Vector3(pd.GetFloat("dreamGateX"), pd.GetFloat("dreamGateY") - 1.429361f, -0.002f), Quaternion.identity);
			obj2.transform.SetParent(base.transform, worldPositionStays: true);
			obj2.transform.SetParent(null);
		}
	}
}
public class StartManager : MonoBehaviour
{
	private bool verboseMode;

	public Animator startManagerAnimator;

	public Slider progressIndicator;

	[SerializeField]
	private StandaloneLoadingSpinner loadSpinnerPrefab;

	[Header("Controller Notice")]
	public SpriteRenderer controllerImage;

	[Space(5f)]
	public Sprite winController;

	public Sprite osxController;

	public SetTextMeshProGameText controllerNoticeText;

	[Header("Language Select")]
	public CanvasGroup languageSelect;

	public Animator languageAnimator;

	public PreselectOption preselector;

	public CanvasGroup languageConfirm;

	private string selectedLanguage;

	private string oldLanguage;

	[Header("Input")]
	public InControlInputModule inputModule;

	[Header("Audio")]
	public MenuAudioController uiAudioPlayer;

	[Header("Debug")]
	public bool showProgessIndicator;

	private AsyncOperation loadop;

	private RuntimePlatform platform;

	private string logoTrigger = "fadeLogo";

	private string controllerTrigger = "controllerNotice";

	private string loadingIconTrigger = "loading";

	private float fadeSpeed = 1.6f;

	private bool confirmedLanguage;

	private void Awake()
	{
		platform = Application.platform;
	}

	private IEnumerator Start()
	{
		controllerImage.sprite = GetControllerSpriteForPlatform(platform);
		AsyncOperation loadOperation = UnityEngine.SceneManagement.SceneManager.LoadSceneAsync("Menu_Title");
		loadOperation.allowSceneActivation = false;
		if (!CheckIsLanguageSet() && Platform.Current.ShowLanguageSelect)
		{
			yield return StartCoroutine(ShowLanguageSelect());
			while (!confirmedLanguage)
			{
				yield return null;
			}
			yield return StartCoroutine(LanguageSettingDone());
		}
		startManagerAnimator.SetBool("WillShowControllerNotice", value: false);
		startManagerAnimator.SetBool("WillShowQuote", value: true);
		UnityEngine.Object.Instantiate(loadSpinnerPrefab).Setup(null);
		loadOperation.allowSceneActivation = true;
		yield return loadOperation;
	}

	private Sprite GetControllerSpriteForPlatform(RuntimePlatform runtimePlatform)
	{
		switch (runtimePlatform)
		{
		case RuntimePlatform.WindowsPlayer:
		case RuntimePlatform.WindowsEditor:
		case RuntimePlatform.LinuxPlayer:
		case RuntimePlatform.LinuxEditor:
			return winController;
		case RuntimePlatform.OSXEditor:
		case RuntimePlatform.OSXPlayer:
			return osxController;
		default:
			return null;
		}
	}

	public void SwitchToMenuScene()
	{
		if (verboseMode)
		{
			UnityEngine.Debug.Log("Switching Scenes");
		}
		loadop.allowSceneActivation = true;
	}

	public void SetLanguage(string newLanguage)
	{
		oldLanguage = global::Language.Language.CurrentLanguage().ToString();
		selectedLanguage = newLanguage;
		global::Language.Language.SwitchLanguage(selectedLanguage);
		languageConfirm.gameObject.SetActive(value: true);
		StartCoroutine(FadeIn(languageConfirm, 0.25f));
		AutoLocalizeTextUI[] componentsInChildren = languageConfirm.GetComponentsInChildren<AutoLocalizeTextUI>();
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			componentsInChildren[i].RefreshTextFromLocalization();
		}
	}

	private IEnumerator FadeIn(CanvasGroup group, float duration)
	{
		group.alpha = 0f;
		for (float elapsed = 0f; elapsed < duration; elapsed += Time.deltaTime)
		{
			group.alpha = elapsed / duration;
			yield return new WaitForEndOfFrame();
		}
		group.alpha = 1f;
		PreselectOption component = group.GetComponent<PreselectOption>();
		if ((bool)component)
		{
			component.HighlightDefault(deselect: true);
		}
	}

	private IEnumerator FadeOut(CanvasGroup group, float duration)
	{
		group.alpha = 1f;
		for (float elapsed = 0f; elapsed < duration; elapsed += Time.deltaTime)
		{
			group.alpha = 1f - elapsed / duration;
			yield return new WaitForEndOfFrame();
		}
		group.alpha = 0f;
		group.gameObject.SetActive(value: false);
	}

	public bool CheckIsLanguageSet()
	{
		if (Platform.Current.IsPlayerPrefsLoaded)
		{
			return Platform.Current.SharedData.GetBool("GameLangSet", def: false);
		}
		return false;
	}

	public void ConfirmLanguage()
	{
		Platform.Current.SharedData.SetInt("GameLangSet", 1);
		Platform.Current.SharedData.Save();
		controllerNoticeText.UpdateText();
		StartCoroutine(FadeOut(languageConfirm, 0.25f));
		confirmedLanguage = true;
	}

	public void CancelLanguage()
	{
		global::Language.Language.SwitchLanguage(oldLanguage);
		StartCoroutine(FadeOut(languageConfirm, 0.25f));
		if ((bool)preselector)
		{
			preselector.HighlightDefault(deselect: true);
		}
	}

	private IEnumerator ShowLanguageSelect()
	{
		languageSelect.alpha = 0f;
		languageSelect.gameObject.SetActive(value: true);
		while ((double)languageSelect.alpha < 0.99)
		{
			languageSelect.alpha += Time.smoothDeltaTime * fadeSpeed;
			if ((double)languageSelect.alpha > 0.99)
			{
				languageSelect.alpha = 1f;
			}
			yield return null;
		}
		Cursor.lockState = CursorLockMode.None;
		preselector.HighlightDefault();
		yield return null;
	}

	private IEnumerator LanguageSettingDone()
	{
		Cursor.lockState = CursorLockMode.Locked;
		while ((double)languageSelect.alpha > 0.01)
		{
			languageSelect.alpha -= Time.smoothDeltaTime * fadeSpeed;
			if ((double)languageSelect.alpha < 0.01)
			{
				languageSelect.alpha = 0f;
			}
			yield return null;
		}
		languageSelect.gameObject.SetActive(value: false);
		ConfigManager.SaveConfig();
	}

	private IEnumerator orig_Start()
	{
		controllerImage.sprite = GetControllerSpriteForPlatform(platform);
		AsyncOperation loadOperation = UnityEngine.SceneManagement.SceneManager.LoadSceneAsync("Menu_Title");
		loadOperation.allowSceneActivation = false;
		if (!CheckIsLanguageSet() && Platform.Current.ShowLanguageSelect)
		{
			yield return StartCoroutine(ShowLanguageSelect());
			while (!confirmedLanguage)
			{
				yield return null;
			}
			yield return StartCoroutine(LanguageSettingDone());
		}
		startManagerAnimator.SetBool("WillShowControllerNotice", value: false);
		startManagerAnimator.SetBool("WillShowQuote", value: true);
		startManagerAnimator.SetTrigger("Start");
		int loadingIconNameHash = Animator.StringToHash("LoadingIcon");
		while (startManagerAnimator.GetCurrentAnimatorStateInfo(0).shortNameHash != loadingIconNameHash)
		{
			yield return null;
		}
		UnityEngine.Object.Instantiate(loadSpinnerPrefab).Setup(null);
		bool didWaitForPlayerPrefs = false;
		while (!Platform.Current.IsPlayerPrefsLoaded)
		{
			if (!didWaitForPlayerPrefs)
			{
				didWaitForPlayerPrefs = true;
				UnityEngine.Debug.LogFormat("Waiting for PlayerPrefs load...");
			}
			yield return null;
		}
		if (!didWaitForPlayerPrefs)
		{
			UnityEngine.Debug.LogFormat("Didn't need to wait for PlayerPrefs load.");
		}
		else
		{
			UnityEngine.Debug.LogFormat("Finished waiting for PlayerPrefs load.");
		}
		loadOperation.allowSceneActivation = true;
		yield return loadOperation;
	}
}
