			menu.topFleur.SetTrigger("hide");
		}
		if (menu.content != null)
		{
			HideCanvasGroup(menu.content);
		}
		if (menu.controls != null)
		{
			HideCanvasGroup(menu.controls);
		}
		HideCanvasGroup(menu.screenCanvasGroup);
		ih.StartUIInput();
	}

