public class ActionQueue
{
	public delegate void ActionQueueCallback(Action next);

	private readonly List<ActionQueueCallback> pendingActions;

	private bool isRunning;

	public ActionQueue()
	{
		pendingActions = new List<ActionQueueCallback>();
		isRunning = false;
	}

	public void Next()
	{
		while (pendingActions.Count > 0)
		{
			ActionQueueCallback actionQueueCallback = pendingActions[0];
			pendingActions.RemoveAt(0);
			try
			{
				actionQueueCallback(Next);
				return;
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}
		isRunning = false;
	}

	public void Enqueue(ActionQueueCallback action)
	{
		if (action != null)
		{
			pendingActions.Add(action);
			if (!isRunning)
			{
				isRunning = true;
				Next();
			}
		}
	}
}
public class CoreLoop : MonoBehaviour
{
	private class DelayedInvoke
	{
		public float TimeRemaining;

		public Action Action;
	}

	private static CoreLoop instance;

	private static List<Action> invokeNextActions;

	private static List<Action> invokeNextActionsBuffer;

	private static bool isFiringInvokeNext;

	private static List<DelayedInvoke> delayedInvokes;

	[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
	private static void Init()
	{
		GameObject obj = new GameObject("CoreLoop");
		instance = obj.AddComponent<CoreLoop>();
		UnityEngine.Object.DontDestroyOnLoad(obj);
		invokeNextActions = new List<Action>();
		invokeNextActionsBuffer = new List<Action>();
		isFiringInvokeNext = false;
		delayedInvokes = new List<DelayedInvoke>();
	}

	public static void InvokeNext(Action action)
	{
		invokeNextActions.Add(action);
		EnqueueInvokeNext();
	}

	private static void EnqueueInvokeNext()
	{
		if (!isFiringInvokeNext)
		{
			isFiringInvokeNext = true;
			instance.Invoke("FireInvokeNext", 0f);
		}
	}

	protected void FireInvokeNext()
	{
		isFiringInvokeNext = false;
		for (int i = 0; i < invokeNextActions.Count; i++)
		{
			invokeNextActionsBuffer.Add(invokeNextActions[i]);
		}
		invokeNextActions.Clear();
		for (int j = 0; j < invokeNextActionsBuffer.Count; j++)
		{
			Action action = invokeNextActionsBuffer[j];
			if (action != null)
			{
				try
				{
					action();
				}
				catch (Exception exception)
				{
					UnityEngine.Debug.LogException(exception);
				}
			}
		}
		invokeNextActionsBuffer.Clear();
	}

	protected void Update()
	{
		for (int i = 0; i < delayedInvokes.Count; i++)
		{
			DelayedInvoke delayedInvoke = delayedInvokes[i];
			delayedInvoke.TimeRemaining -= Time.unscaledDeltaTime;
			if (delayedInvoke.TimeRemaining <= 0f)
			{
				delayedInvokes.RemoveAt(i--);
				InvokeNext(delayedInvoke.Action);
			}
		}
	}
}
public class CoroutineQueue
{
	private readonly List<IEnumerator> pendingCoroutines;

	private readonly MonoBehaviour runner;

	private bool isRunning;

	public CoroutineQueue(MonoBehaviour runner)
	{
		this.runner = runner;
		pendingCoroutines = new List<IEnumerator>();
	}

	public void Enqueue(IEnumerator coroutine)
	{
		pendingCoroutines.Add(coroutine);
		if (!isRunning)
		{
			runner.StartCoroutine(Run());
		}
	}

	public IEnumerator Run()
	{
		isRunning = true;
		while (pendingCoroutines.Count > 0)
		{
			IEnumerator coroutine = pendingCoroutines[0];
			pendingCoroutines.RemoveAt(0);
			while (true)
			{
				bool flag;
				try
				{
					flag = coroutine.MoveNext();
				}
				catch (Exception exception)
				{
					UnityEngine.Debug.LogException(exception);
					break;
				}
				if (!flag)
				{
					break;
				}
				yield return coroutine.Current;
			}
		}
		isRunning = false;
	}
}
public abstract class CustomSharedData : Platform.ISharedData
{
	[Serializable]
	private class SharedDataSerializableBlob
	{
		[SerializeField]
		private SharedDataSerializablePair[] pairs;

		public static SharedDataSerializableBlob FromSharedData(Dictionary<string, string> sharedData)
		{
			List<SharedDataSerializablePair> list = new List<SharedDataSerializablePair>();
			foreach (KeyValuePair<string, string> sharedDatum in sharedData)
			{
				if (sharedDatum.Key == null)
				{
					UnityEngine.Debug.LogErrorFormat("Null key found in shared data");
					continue;
				}
				if (sharedDatum.Value == null)
				{
					UnityEngine.Debug.LogErrorFormat("Null value for key '{0}' found in shared data");
					continue;
				}
				list.Add(new SharedDataSerializablePair
				{
					Key = sharedDatum.Key,
					Value = sharedDatum.Value
				});
			}
			return new SharedDataSerializableBlob
			{
				pairs = list.ToArray()
			};
		}

		public void ToSharedData(Dictionary<string, string> sharedData)
		{
			sharedData.Clear();
			int num = 0;
			while (pairs != null && num < pairs.Length)
			{
				SharedDataSerializablePair sharedDataSerializablePair = pairs[num];
				if (sharedDataSerializablePair.Key == null)
				{
					UnityEngine.Debug.LogErrorFormat("Null key found in shared data");
				}
				else if (sharedDataSerializablePair.Value == null)
				{
					UnityEngine.Debug.LogErrorFormat("Null value for key '{0}' found in shared data", sharedDataSerializablePair.Key);
				}
				else if (sharedData.ContainsKey(sharedDataSerializablePair.Key))
				{
					UnityEngine.Debug.LogErrorFormat("Duplicate key '{0}' found in shared data", sharedDataSerializablePair.Key);
				}
				else
				{
					sharedData.Add(sharedDataSerializablePair.Key, sharedDataSerializablePair.Value);
				}
				num++;
			}
		}
	}

	[Serializable]
	private struct SharedDataSerializablePair
	{
		public string Key;

		public string Value;
	}

	public interface IResponder
	{
		void OnModified(CustomSharedData sharedData);
	}

	private Dictionary<string, string> sharedData;

	private IResponder responder;

	public Dictionary<string, string> SharedData => sharedData;

	public IResponder Responder
	{
		get
		{
			return responder;
		}
		set
		{
			responder = value;
		}
	}

	protected CustomSharedData()
	{
		sharedData = new Dictionary<string, string>();
	}

	public void LoadFromJSON(string str)
	{
		JsonUtility.FromJson<SharedDataSerializableBlob>(str).ToSharedData(sharedData);
	}

	public string SaveToJSON()
	{
		return JsonUtility.ToJson(SharedDataSerializableBlob.FromSharedData(sharedData));
	}

	public bool HasKey(string key)
	{
		return sharedData.ContainsKey(key);
	}

	public void DeleteKey(string key)
	{
		if (sharedData.Remove(key))
		{
			OnModified();
		}
	}

	public void DeleteAll()
	{
		if (sharedData.Count > 0)
		{
			sharedData.Clear();
			OnModified();
		}
	}

	public bool GetBool(string key, bool def)
	{
		return GetInt(key, def ? 1 : 0) > 0;
	}

	public void SetBool(string key, bool val)
	{
		SetInt(key, val ? 1 : 0);
	}

	public int GetInt(string key, int def)
	{
		if (!sharedData.TryGetValue(key, out var value))
		{
			return def;
		}
		if (!int.TryParse(value, out var result))
