	{
		DesktopOnlineSubsystem desktopOnlineSubsystem = onlineSubsystem;
		if (desktopOnlineSubsystem != null && desktopOnlineSubsystem.HandlesGameSaves)
		{
			onlineSubsystem.IsSaveSlotInUse(slotIndex, callback);
