		EncryptedSharedData.SetBool(achievementId, val: true);
	}

	public override void ResetAchievements()
	{
		if (onlineSubsystem != null)
		{
			onlineSubsystem.ResetAchievements();
		}
	}

	public bool IncludesPlugin(string pluginName)
	{
		string path = "Plugins";
