		if (!File.Exists(path2))
		{
			return Directory.Exists(path2);
		}
		return true;
	}

	public void OnOnlineSubsystemAchievementsFetched()
	{
		OnAchievementsFetched();
	}

	public VibrationMixer GetVibrationMixer()
