		SDK.XGameSaveSubmitUpdateAsync(updateHandle, delegate(int hresult)
		{
			if (Succeeded(hresult, "Game save submit update complete"))
			{
				callback?.Invoke(obj: true);
			}
			else
			{
				callback?.Invoke(obj: false);
			}
		});
	}

	public override void ClearSaveSlot(int slotIndex, Action<bool> callback)
	{
		if (!Succeeded(SDK.XGameSaveDeleteContainer(_gameSaveProviderHandle, GetSaveContainerName(slotIndex)), "Get container info"))
		{
			callback?.Invoke(obj: false);
		}
		else
		{
			callback?.Invoke(obj: true);
		}
	}

	private static bool Succeeded(int hresult, string operationFriendlyName)
	{
		bool result = false;
		if (hresult >= 0)
		{
			result = true;
		}
		else
		{
			string arg = hresult.ToString("X8");
			string arg2 = operationFriendlyName + " failed.";
			UnityEngine.Debug.LogError($"{arg2} Error code: hr=0x{arg}");
		}
		return result;
	}

	private void AddUserComplete(int hresult, XUserHandle userHandle)
	{
		if (Succeeded(hresult, "Sign in."))
		{
			UnityEngine.Debug.Log("Signed in!");
			_userHandle = userHandle;
			CompletePostSignInInitialization();
		}
	}

	private void CompletePostSignInInitialization()
	{
		if (Succeeded(SDK.XUserGetGamertag(_userHandle, XUserGamertagComponent.UniqueModern, out var gamertag), "Get gamertag."))
		{
			UnityEngine.Debug.Log("Got gamertag!");
			userDisplayName = gamertag;
			platform.NotifyEngagedDisplayInfoChanged();
		}
		SDK.XUserGetGamerPictureAsync(_userHandle, XUserGamerPictureSize.Small, delegate(int hresult, byte[] buffer)
		{
			if (Succeeded(hresult, "Get user display pic."))
			{
				userDisplayImage = new Texture2D(64, 64, TextureFormat.BGRA32, mipChain: false, linear: false);
				userDisplayImage.LoadImage(buffer);
				platform.NotifyEngagedDisplayInfoChanged();
			}
		});
		Succeeded(SDK.XBL.XblInitialize("00000000-0000-0000-0000-00007abd14db"), "Initialize Xbox Live");
		Succeeded(SDK.XBL.XblContextCreateHandle(_userHandle, out _xblContextHandle), "Create Xbox Live context");
		HashSet<int> hashSet = new HashSet<int>();
		awardedAchievements = hashSet;
		SDK.XGameSaveInitializeProviderAsync(_userHandle, "00000000-0000-0000-0000-00007abd14db", syncOnDemand: false, delegate(int hresult, XGameSaveProviderHandle handle)
		{
			if (Succeeded(hresult, "Init game save provider"))
			{
				_gameSaveProviderHandle = handle;
				UnityEngine.Debug.Log("Initialized game save provider!");
				MigrateLocalSaves();
			}
		});
	}

	private void MigrateLocalSaves()
	{
		for (int i = 1; i <= 4; i++)
		{
			int slotIndex = i;
			platform.LocalReadSaveSlot(slotIndex, delegate(byte[] localBytes)
			{
				if (localBytes != null)
				{
					platform.ReadSaveSlot(slotIndex, delegate(byte[] bytes)
					{
						if (bytes == null)
						{
							platform.WriteSaveSlot(slotIndex, localBytes, delegate
							{
								UnityEngine.Debug.Log($"Migrated local slot {slotIndex} to cloud.");
							});
						}
					});
				}
			});
		}
	}
}
public class GamepadVibrationMixer : VibrationMixer
{
	public class GamepadVibrationEmission : VibrationEmission
	{
		public struct Values
		{
			public float Small;

			public float Large;

			public bool IsNearlyZero
			{
				get
				{
					if (Small < Mathf.Epsilon)
					{
						return Large < Mathf.Epsilon;
					}
					return false;
				}
			}
		}

		private GamepadVibrationMixer mixer;

		private GamepadVibration gamepadVibration;

		private float duration;

		private bool isLooping;

		private bool isPlaying;

		private string tag;

		private VibrationTarget target;

		private float timer;

		public override bool IsLooping
		{
			get
			{
				return isLooping;
			}
			set
			{
				isLooping = value;
			}
		}

		public override bool IsPlaying => isPlaying;

		public override string Tag
		{
			get
			{
				return tag;
			}
			set
			{
				tag = value;
			}
		}

		public override VibrationTarget Target
		{
			get
			{
				return target;
			}
			set
			{
				target = value;
			}
		}

		public GamepadVibrationEmission(GamepadVibrationMixer mixer, GamepadVibration gamepadVibration, bool isLooping, string tag, VibrationTarget target)
		{
			this.mixer = mixer;
			this.gamepadVibration = gamepadVibration;
			duration = gamepadVibration.GetDuration();
			this.isLooping = isLooping;
			isPlaying = true;
			this.tag = tag;
			this.target = target;
		}

		public override void Stop()
		{
			isPlaying = false;
		}

		public Values GetCurrentValues()
		{
			return new Values
			{
				Small = ((target.Motors != VibrationMotors.None) ? gamepadVibration.SmallMotor.Evaluate(timer) : 0f),
				Large = ((target.Motors != VibrationMotors.None) ? gamepadVibration.LargeMotor.Evaluate(timer) : 0f)
			};
		}

		public void Advance(float deltaTime)
		{
			timer += deltaTime * gamepadVibration.PlaybackRate;
			if (timer >= duration)
			{
				if (isLooping)
				{
					timer = Mathf.Repeat(timer, duration);
				}
				else
				{
					isPlaying = false;
				}
			}
		}

		public override string ToString()
		{
			if (!(gamepadVibration != null))
			{
				return "null";
			}
			return gamepadVibration.name;
		}
	}

	public enum PlatformAdjustments
	{
		None,
		DualShock
	}

	private bool isPaused;

	private List<GamepadVibrationEmission> playingEmissions;

	private PlatformAdjustments platformAdjustment;

	private GamepadVibrationEmission.Values currentValues;

	public override bool IsPaused
	{
		get
		{
			return isPaused;
		}
		set
		{
			isPaused = value;
		}
	}

	public override int PlayingEmissionCount => playingEmissions.Count;

	public GamepadVibrationEmission.Values CurrentValues => currentValues;

	public override VibrationEmission GetPlayingEmission(int playingEmissionIndex)
	{
		return playingEmissions[playingEmissionIndex];
	}

	public GamepadVibrationMixer(PlatformAdjustments platformAdjustment = PlatformAdjustments.None)
	{
		this.platformAdjustment = platformAdjustment;
		playingEmissions = new List<GamepadVibrationEmission>();
	}

	public override VibrationEmission PlayEmission(VibrationData vibrationData, VibrationTarget vibrationTarget, bool isLooping, string tag)
	{
		if (vibrationData.GamepadVibration == null)
		{
			return new UnsupportedVibrationEmission(vibrationTarget, isLooping, tag);
		}
		GamepadVibrationEmission gamepadVibrationEmission = new GamepadVibrationEmission(this, vibrationData.GamepadVibration, isLooping, tag, vibrationTarget);
		playingEmissions.Add(gamepadVibrationEmission);
		return gamepadVibrationEmission;
	}

	public override void StopAllEmissions()
	{
		for (int i = 0; i < playingEmissions.Count; i++)
		{
			playingEmissions[i].Stop();
		}
	}

	public override void StopAllEmissionsWithTag(string tag)
	{
		for (int i = 0; i < playingEmissions.Count; i++)
		{
			GamepadVibrationEmission gamepadVibrationEmission = playingEmissions[i];
			if (gamepadVibrationEmission.Tag == tag)
			{
				gamepadVibrationEmission.Stop();
			}
		}
	}

	public void Update(float deltaTime)
	{
		GamepadVibrationEmission.Values values = new GamepadVibrationEmission.Values
		{
			Small = 0f,
			Large = 0f
		};
		bool flag = deltaTime < 1E-05f;
		if (!isPaused && !flag)
		{
			for (int i = 0; i < playingEmissions.Count; i++)
			{
				if (!playingEmissions[i].IsPlaying)
				{
					playingEmissions.RemoveAt(i--);
				}
			}
			for (int j = 0; j < playingEmissions.Count; j++)
			{
				GamepadVibrationEmission gamepadVibrationEmission = playingEmissions[j];
				GamepadVibrationEmission.Values values2 = gamepadVibrationEmission.GetCurrentValues();
				values.Small = AdjustForPlatform(Mathf.Max(values.Small, values2.Small));
				values.Large = AdjustForPlatform(Mathf.Max(values.Large, values2.Large));
				gamepadVibrationEmission.Advance(deltaTime);
			}
		}
		currentValues = values;
	}

	private float AdjustForPlatform(float val)
	{
		if (platformAdjustment == PlatformAdjustments.DualShock)
		{
			float b = Mathf.Clamp01(Mathf.Sin(val * (float)Math.PI * 0.5f));
			val = Mathf.Lerp(val, b, 1f);
		}
		return val * ConfigManager.ControllerRumbleMultiplier;
	}
}
