public class PlatformVibrationHelper
{
	private GamepadVibrationMixer vibrationMixer;

	private InputDevice lastVibratingInputDevice;

	private bool lastVibrationWasEmpty;

	public PlatformVibrationHelper()
	{
		vibrationMixer = new GamepadVibrationMixer();
	}

	public void Destroy()
	{
		if (lastVibratingInputDevice != null)
		{
			lastVibratingInputDevice.StopVibration();
			lastVibratingInputDevice = null;
		}
	}

	public void UpdateVibration()
	{
		vibrationMixer.Update(Time.deltaTime);
		GamepadVibrationMixer.GamepadVibrationEmission.Values currentValues = vibrationMixer.CurrentValues;
		InputDevice activeDevice = InputManager.ActiveDevice;
		if (lastVibratingInputDevice != activeDevice)
		{
			if (lastVibratingInputDevice != null)
			{
				lastVibratingInputDevice.StopVibration();
				lastVibratingInputDevice = null;
			}
			lastVibratingInputDevice = activeDevice;
			if (lastVibratingInputDevice != null)
			{
				lastVibratingInputDevice.StopVibration();
			}
			lastVibrationWasEmpty = false;
		}
		if (lastVibratingInputDevice != null)
		{
			if (!lastVibrationWasEmpty || !currentValues.IsNearlyZero)
			{
				lastVibratingInputDevice.Vibrate(currentValues.Small, currentValues.Large);
			}
			lastVibrationWasEmpty = currentValues.IsNearlyZero;
		}
	}

	public VibrationMixer GetMixer()
	{
		return vibrationMixer;
	}
}
public class PlayerPrefsSharedData : Platform.ISharedData
{
	private readonly RijndaelManaged cryptoSettings;

	public bool IsEncrypted => cryptoSettings != null;

	public PlayerPrefsSharedData(byte[] encryptionKey)
	{
		if (encryptionKey == null)
		{
			cryptoSettings = null;
			return;
		}
		cryptoSettings = new RijndaelManaged();
		cryptoSettings.Key = encryptionKey;
		cryptoSettings.Mode = CipherMode.ECB;
		cryptoSettings.Padding = PaddingMode.PKCS7;
	}

	private string ReadEncrypted(string key)
	{
		string text = PlayerPrefs.GetString(Encryption.Encrypt(key), "");
		if (string.IsNullOrEmpty(text))
		{
			return null;
		}
		return Encryption.Decrypt(text);
	}

	private void WriteEncrypted(string key, string val)
	{
		string key2 = Encryption.Encrypt(key);
		string value = Encryption.Encrypt(val);
		PlayerPrefs.SetString(key2, value);
	}

	public bool HasKey(string key)
	{
		return PlayerPrefs.HasKey(key);
	}

	public void DeleteKey(string key)
	{
		PlayerPrefs.DeleteKey(key);
	}

	public void DeleteAll()
	{
		PlayerPrefs.DeleteAll();
	}

	public bool GetBool(string key, bool def)
	{
		return GetInt(key, def ? 1 : 0) > 0;
	}

	public void SetBool(string key, bool val)
	{
		SetInt(key, val ? 1 : 0);
	}

	public int GetInt(string key, int def)
	{
		if (IsEncrypted)
		{
			string text = ReadEncrypted(key);
			if (text == null)
			{
				return def;
			}
			if (!int.TryParse(text, out var result))
			{
				return def;
			}
			return result;
		}
		return PlayerPrefs.GetInt(key, def);
	}

	public void SetInt(string key, int val)
	{
		if (IsEncrypted)
		{
			WriteEncrypted(key, val.ToString());
		}
		else
		{
			PlayerPrefs.SetInt(key, val);
		}
	}

	public float GetFloat(string key, float def)
	{
		if (IsEncrypted)
		{
			string text = ReadEncrypted(key);
			if (text == null)
			{
				return def;
			}
			if (!float.TryParse(text, out var result))
			{
				return def;
			}
			return result;
		}
		return PlayerPrefs.GetFloat(key, def);
	}

	public void SetFloat(string key, float val)
	{
		if (IsEncrypted)
		{
			WriteEncrypted(key, val.ToString());
		}
		else
		{
			PlayerPrefs.SetFloat(key, val);
		}
	}

	public string GetString(string key, string def)
	{
		if (IsEncrypted)
		{
			string text = ReadEncrypted(key);
			if (text == null)
			{
				return def;
			}
			return text;
		}
		return PlayerPrefs.GetString(key, def);
	}

	public void SetString(string key, string val)
	{
		if (IsEncrypted)
		{
			WriteEncrypted(key, val);
		}
		else
		{
			PlayerPrefs.SetString(key, val);
		}
	}

	public void Save()
	{
		PlayerPrefs.Save();
	}
}
public class SteamOnlineSubsystem : DesktopOnlineSubsystem
{
	private DesktopPlatform platform;

	private bool didInitialize;

	private bool statsReceived;

	private SteamAPIWarningMessageHook_t warningCallback;

	private Callback<GameOverlayActivated_t> gameOverlayCallback;

	private Callback<UserStatsReceived_t> statsReceivedCallback;

	private Callback<SteamShutdown_t> steamShutdownCallback;

	private Callback<UserAchievementStored_t> achievementStoredCallback;

	public override bool AreAchievementsFetched => statsReceived;

	public static bool IsPackaged(DesktopPlatform desktopPlatform)
	{
		return desktopPlatform.IncludesPlugin(Path.Combine("x86_64", "steam_api64.dll"));
	}

	public SteamOnlineSubsystem(DesktopPlatform platform)
	{
		this.platform = platform;
		if (!Packsize.Test())
		{
			UnityEngine.Debug.LogErrorFormat("Steamworks packsize incorrect.");
		}
		if (!DllCheck.Test())
		{
			UnityEngine.Debug.LogErrorFormat("Steamworks binaries out of date or missing.");
		}
		if (SteamAPI.RestartAppIfNecessary(new AppId_t(367520u)))
		{
			UnityEngine.Debug.LogError("Application was not launched through Steam! Shutting down...");
			Application.Quit();
		}
		UnityEngine.Debug.LogFormat("Steam initializing");
		if (didInitialize = SteamAPI.Init())
		{
			warningCallback = OnSteamLogMessage;
			SteamClient.SetWarningMessageHook(warningCallback);
			gameOverlayCallback = Callback<GameOverlayActivated_t>.Create(OnGameOverlayActivated);
			statsReceivedCallback = Callback<UserStatsReceived_t>.Create(OnStatsReceived);
			steamShutdownCallback = Callback<SteamShutdown_t>.Create(OnSteamShutdown);
			achievementStoredCallback = Callback<UserAchievementStored_t>.Create(OnAchievementStored);
			string personaName = SteamFriends.GetPersonaName();
			UnityEngine.Debug.LogFormat("Steam logged in as {0}", personaName);
			if (!SteamUserStats.RequestCurrentStats())
			{
				UnityEngine.Debug.LogErrorFormat("Steam unable to request current stats.");
			}
		}
		else
		{
			UnityEngine.Debug.LogErrorFormat("Steam failed to initialize");
		}
	}

	public override void Dispose()
	{
		if (didInitialize)
		{
			UnityEngine.Debug.LogFormat("Shutting down Steam API.");
			SteamAPI.Shutdown();
		}
		base.Dispose();
	}

	public override void Update()
	{
		base.Update();
		SteamAPI.RunCallbacks();
	}

	private void OnSteamLogMessage(int severity, StringBuilder content)
	{
		string format = "Steam: " + content.ToString();
		if (severity == 1)
		{
			UnityEngine.Debug.LogWarningFormat(format);
		}
		else
		{
			UnityEngine.Debug.LogFormat(format);
		}
	}

	private void OnGameOverlayActivated(GameOverlayActivated_t ev)
	{
		UnityEngine.Debug.LogFormat("Steam overlay became {0}.", (ev.m_bActive == 0) ? "closed" : "opened");
	}

	private void OnStatsReceived(UserStatsReceived_t ev)
	{
		if (ev.m_eResult == EResult.k_EResultOK)
		{
			statsReceived = true;
			UnityEngine.Debug.LogFormat("Steam stats received.");
			platform.OnOnlineSubsystemAchievementsFetched();
		}
		else
		{
			UnityEngine.Debug.LogErrorFormat("Steam failed to receive stats: {0}", ev.m_eResult);
		}
	}

	private void OnSteamShutdown(SteamShutdown_t ev)
	{
		UnityEngine.Debug.LogFormat("Steam shut down.");
		didInitialize = false;
	}

	private void OnAchievementStored(UserAchievementStored_t ev)
	{
		UnityEngine.Debug.LogFormat("Steam achievement {0} ({1}/{2}) upload complete", ev.m_rgchAchievementName, ev.m_nCurProgress, ev.m_nMaxProgress);
	}

	public override void PushAchievementUnlock(string achievementId)
	{
		if (didInitialize)
		{
			try
			{
				SteamUserStats.SetAchievement(achievementId);
				SteamUserStats.StoreStats();
				UnityEngine.Debug.LogFormat("Pushing achievement {0}", achievementId);
				return;
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
				return;
			}
		}
		UnityEngine.Debug.LogErrorFormat("Unable to unlock achievement {0}, because Steam is not initialized", achievementId);
	}

	public override bool? IsAchievementUnlocked(string achievementId)
	{
		if (didInitialize)
		{
			try
			{
				if (!SteamUserStats.GetAchievement(achievementId, out var pbAchieved))
				{
					UnityEngine.Debug.LogErrorFormat("Failed to retrieve achievement state for {0}", achievementId);
					return null;
				}
				return pbAchieved;
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
				return null;
			}
		}
		UnityEngine.Debug.LogErrorFormat("Unable to retrieve achievement state for {0}, because Steam is not initialized", achievementId);
		return null;
	}

	public override void ResetAchievements()
	{
		if (didInitialize)
		{
			try
			{
				SteamUserStats.ResetAllStats(bAchievementsToo: true);
				UnityEngine.Debug.LogFormat("Reset all stats");
				return;
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
				return;
			}
		}
		UnityEngine.Debug.LogErrorFormat("Unable to reset all stats, because Steam is not initialized");
	}
}
public static class TimeController
{
	private static float slowMotionTimeScale;

	private static float pauseTimeScale;

	private static float platformBackgroundTimeScale;

	private static float genericTimeScale;

	public static float SlowMotionTimeScale
	{
		get
		{
			return slowMotionTimeScale;
		}
		set
		{
			SetTimeScaleFactor(ref slowMotionTimeScale, value);
		}
	}

	public static float PauseTimeScale
	{
		get
		{
			return pauseTimeScale;
		}
		set
		{
			SetTimeScaleFactor(ref pauseTimeScale, value);
		}
	}

	public static float PlatformBackgroundTimeScale
	{
		get
		{
			return platformBackgroundTimeScale;
		}
		set
		{
			SetTimeScaleFactor(ref platformBackgroundTimeScale, value);
		}
	}

	public static float GenericTimeScale
	{
		get
		{
			return genericTimeScale;
		}
		set
		{
			SetTimeScaleFactor(ref genericTimeScale, value);
		}
	}

	static TimeController()
	{
		slowMotionTimeScale = 1f;
		pauseTimeScale = 1f;
		platformBackgroundTimeScale = 1f;
		genericTimeScale = 1f;
	}

	private static void SetTimeScaleFactor(ref float field, float val)
	{
		if (field != val)
		{
			field = val;
			float num = slowMotionTimeScale * pauseTimeScale * platformBackgroundTimeScale * genericTimeScale;
			if (num < 0.01f)
			{
				num = 0f;
			}
			Time.timeScale = num;
		}
	}
}
