	private bool HasMapForScene(string sceneName)
	{
		if (GetVariable<Dictionary<string, MapBools>>("mapZoneBools") == null)
		{
			SetVariableSwappedArgs(InitMapBools(), "mapZoneBools");
		}
		if (GetVariable<Dictionary<string, MapBools>>("mapZoneBools").ContainsKey(sceneName))
		{
			return GetVariable<Dictionary<string, MapBools>>("mapZoneBools")[sceneName] switch
			{
				MapBools.MapDirtmouth => GetBool("mapDirtmouth"), 
				MapBools.MapCrossroads => GetBool("mapCrossroads"), 
				MapBools.MapGreenpath => GetBool("mapGreenpath"), 
				MapBools.MapFogCanyon => GetBool("mapFogCanyon"), 
				MapBools.MapRoyalGardens => GetBool("mapRoyalGardens"), 
				MapBools.MapFungalWastes => GetBool("mapFungalWastes"), 
				MapBools.MapCity => GetBool("mapCity"), 
				MapBools.MapWaterways => GetBool("mapWaterways"), 
				MapBools.MapMines => GetBool("mapMines"), 
				MapBools.MapDeepnest => GetBool("mapDeepnest"), 
				MapBools.MapCliffs => GetBool("mapCliffs"), 
				MapBools.MapOutskirts => GetBool("mapOutskirts"), 
				MapBools.MapRestingGrounds => GetBool("mapRestingGrounds"), 
				MapBools.MapAbyss => GetBool("mapAbyss"), 
				_ => false, 
			};
		}
		return true;
	}

	protected PlayerData()
	{
		SetupNewPlayerData();
	}

	public void PrintStory()
	{
		UnityEngine.Debug.Log("combining player story");
		SetStringSwappedArgs(string.Join(",", GetVariable<List<string>>("playerStory").ToArray()), "playerStoryOutput");
	}

	public void Reset()
	{
		SetupNewPlayerData();
	}

	public bool UpdateGameMap()
	{
		bool result = false;
		if (GetBool("hasQuill"))
		{
			foreach (string item in GetVariable<List<string>>("scenesVisited"))
			{
				if (!GetVariable<List<string>>("scenesMapped").Contains(item) && HasMapForScene(item))
				{
					GetVariable<List<string>>("scenesMapped").Add(item);
					result = true;
				}
			}
		}
		return result;
	}

	public void CheckAllMaps()
	{
		if (GetBool("mapCrossroads") && GetBool("mapGreenpath") && GetBool("mapFogCanyon") && GetBool("mapRoyalGardens") && GetBool("mapFungalWastes") && GetBool("mapCity") && GetBool("mapWaterways") && GetBool("mapMines") && GetBool("mapDeepnest") && GetBool("mapCliffs") && GetBool("mapOutskirts") && GetBool("mapRestingGrounds") && GetBool("mapAbyss"))
		{
			SetBoolSwappedArgs(value: true, "corniferAtHome");
		}
	}

	public void SetBool(string boolName, bool value)
	{
		ModHooks.SetPlayerBool(boolName, value, this);
	}

	public void SetInt(string intName, int value)
	{
		ModHooks.SetPlayerInt(intName, value, this);
	}

	public void IncrementInt(string intName)
	{
		if (Modding.ReflectionHelper.GetFieldInfo(typeof(PlayerData), intName) != null)
		{
			ModHooks.SetPlayerInt(intName, GetIntInternal(intName) + 1, this);
		}
		else
		{
			UnityEngine.Debug.Log("PlayerData: Could not find field named " + intName + ", check variable name exists and FSM variable string is correct.");
		}
	}

	public void IntAdd(string intName, int amount)
	{
		if (Modding.ReflectionHelper.GetFieldInfo(typeof(PlayerData), intName) != null)
		{
			ModHooks.SetPlayerInt(intName, GetIntInternal(intName) + amount, this);
		}
		else
		{
			UnityEngine.Debug.Log("PlayerData: Could not find field named " + intName + ", check variable name exists and FSM variable string is correct.");
		}
	}

	public void SetFloat(string floatName, float value)
	{
		ModHooks.SetPlayerFloat(floatName, value, this);
	}

	public void DecrementInt(string intName)
	{
		if (Modding.ReflectionHelper.GetFieldInfo(typeof(PlayerData), intName) != null)
		{
			ModHooks.SetPlayerInt(intName, GetIntInternal(intName) - 1, this);
		}
	}

	public bool GetBool(string boolName)
	{
		return ModHooks.GetPlayerBool(boolName, this);
	}

	public int GetInt(string intName)
	{
		return ModHooks.GetPlayerInt(intName, this);
	}

	public float GetFloat(string floatName)
	{
		return ModHooks.GetPlayerFloat(floatName, this);
	}

	public string GetString(string stringName)
	{
		return ModHooks.GetPlayerString(stringName, this);
	}

	public void SetString(string stringName, string value)
	{
		ModHooks.SetPlayerString(stringName, value, this);
	}

	public void SetVector3(string vectorName, Vector3 value)
	{
		ModHooks.SetPlayerVector3(vectorName, value, this);
	}

	public Vector3 GetVector3(string vectorName)
	{
		return ModHooks.GetPlayerVector3(vectorName, this);
	}

	public void SetVariable<T>(string fieldName, T value)
	{
		ModHooks.SetPlayerVariable(fieldName, value, this);
	}

	public T GetVariable<T>(string fieldName)
	{
		return ModHooks.GetPlayerVariable<T>(fieldName, this);
	}

	public void AddHealth(int amount)
	{
		amount = ModHooks.BeforeAddHealth(amount);
		orig_AddHealth(amount);
	}

	public void TakeHealth(int amount)
	{
		amount = ModHooks.OnTakeHealth(amount);
		TakeHealthInternal(amount);
	}

	public void MaxHealth()
	{
		SetIntSwappedArgs(GetInt("health"), "prevHealth");
