	public void AddToMaxHealth(int amount)
	{
		SetIntSwappedArgs(GetInt("maxHealthBase") + amount, "maxHealthBase");
		if (!GetBool("equippedCharm_27"))
		{
			SetIntSwappedArgs(GetInt("maxHealth") + amount, "maxHealth");
		}
		SetIntSwappedArgs(GetInt("health"), "prevHealth");
		SetIntSwappedArgs(GetInt("maxHealth"), "health");
		if (GetInt("maxHealthBase") == GetInt("maxHealthCap"))
		{
			SetBoolSwappedArgs(value: true, "heartPieceMax");
		}
	}

	public void UpdateBlueHealth()
	{
		orig_UpdateBlueHealth();
		SetInt("healthBlue", GetInt("healthBlue") + ModHooks.OnBlueHealth());
	}

	public void AddGeo(int amount)
	{
		SetIntSwappedArgs(GetInt("geo") + amount, "geo");
		if (GetInt("geo") > 9999999)
		{
			SetIntSwappedArgs(9999999, "geo");
		}
	}

	public void TakeGeo(int amount)
	{
		SetIntSwappedArgs(GetInt("geo") - amount, "geo");
	}

	public bool WouldDie(int damage)
	{
		if (GetInt("health") - damage <= 0)
		{
			return true;
		}
		return false;
	}

	public bool AddMPCharge(int amount)
	{
		bool result = false;
		if (GetBool("soulLimited") && GetInt("maxMP") != 66)
		{
			SetIntSwappedArgs(66, "maxMP");
		}
		if (!GetBool("soulLimited") && GetInt("maxMP") != 99)
		{
			SetIntSwappedArgs(99, "maxMP");
		}
		if (BossSequenceController.BoundSoul && GetInt("maxMP") != 33)
		{
			SetIntSwappedArgs(33, "maxMP");
		}
		if (GetInt("MPCharge") + amount > GetInt("maxMP"))
		{
			if (GetInt("MPReserve") < GetInt("MPReserveMax") && !BossSequenceController.BoundSoul)
			{
				SetIntSwappedArgs(GetInt("MPReserve") + (amount - (GetInt("maxMP") - GetInt("MPCharge"))), "MPReserve");
				result = true;
				if (GetInt("MPReserve") > GetInt("MPReserveMax"))
				{
					SetIntSwappedArgs(GetInt("MPReserveMax"), "MPReserve");
				}
			}
			SetIntSwappedArgs(GetInt("maxMP"), "MPCharge");
		}
		else
		{
			SetIntSwappedArgs(GetInt("MPCharge") + amount, "MPCharge");
			result = true;
		}
		return result;
	}

	public void TakeMP(int amount)
	{
		if (amount <= GetInt("MPCharge"))
		{
			SetIntSwappedArgs(GetInt("MPCharge") - amount, "MPCharge");
			if (GetInt("MPCharge") < 0)
			{
				SetIntSwappedArgs(0, "MPCharge");
			}
		}
		else
		{
			SetIntSwappedArgs(0, "MPCharge");
		}
	}

	public void TakeReserveMP(int amount)
	{
		SetIntSwappedArgs(GetInt("MPReserve") - amount, "MPReserve");
		if (GetInt("MPReserve") < 0)
		{
			SetIntSwappedArgs(0, "MPReserve");
		}
	}

	public void ClearMP()
	{
		SetIntSwappedArgs(0, "MPCharge");
		SetIntSwappedArgs(0, "MPReserve");
	}

	public void AddToMaxMPReserve(int amount)
