	{
		SetVariable(name, value);
	}

	public void SetBoolInternal(string boolName, bool value)
	{
		Modding.ReflectionHelper.SetFieldSafe(this, boolName, value);
	}

	public bool GetBoolInternal(string boolName)
	{
		return Modding.ReflectionHelper.GetField<PlayerData, bool, bool?>(this, boolName) == true;
	}

	public void SetIntInternal(string intName, int value)
	{
		Modding.ReflectionHelper.SetFieldSafe(this, intName, value);
	}

	public int GetIntInternal(string intName)
	{
		return Modding.ReflectionHelper.GetField<PlayerData, int, int?>(this, intName) ?? (-9999);
	}

	public void SetFloatInternal(string floatName, float value)
	{
		Modding.ReflectionHelper.SetFieldSafe(this, floatName, value);
	}

	public float GetFloatInternal(string floatName)
	{
		return Modding.ReflectionHelper.GetField<PlayerData, float, float?>(this, floatName) ?? (-9999f);
	}

	public void SetStringInternal(string stringName, string value)
	{
		Modding.ReflectionHelper.SetFieldSafe(this, stringName, value);
	}

	public string GetStringInternal(string stringName)
	{
		return Modding.ReflectionHelper.GetField<PlayerData, string, string>(this, stringName) ?? " ";
	}

	public void SetVector3Internal(string vector3Name, Vector3 value)
	{
		Modding.ReflectionHelper.SetFieldSafe(this, vector3Name, value);
	}

	public Vector3 GetVector3Internal(string vector3Name)
	{
		return Modding.ReflectionHelper.GetField<PlayerData, Vector3, Vector3?>(this, vector3Name) ?? Vector3.zero;
	}

	public void SetVariableInternal<T>(string variableName, T value)
	{
		Modding.ReflectionHelper.SetFieldSafe(this, variableName, value);
	}

	public T GetVariableInternal<T>(string variableName)
	{
		try
		{
			return Modding.ReflectionHelper.GetField<PlayerData, T, T>(this, variableName);
		}
		catch
		{
			return default(T);
		}
	}

	private void TakeHealthInternal(int amount)
	{
		if (amount > 0 && GetInt("health") == GetInt("maxHealth") && GetInt("health") != CurrentMaxHealth)
		{
			SetInt("health", CurrentMaxHealth);
		}
		if (GetInt("healthBlue") > 0)
		{
			int num = amount - GetInt("healthBlue");
			SetBool("damagedBlue", value: true);
			SetInt("healthBlue", GetInt("healthBlue") - amount);
			if (GetInt("healthBlue") < 0)
			{
				SetInt("healthBlue", 0);
			}
			if (num > 0)
			{
				TakeHealthInternal(num);
			}
		}
		else
		{
			SetBool("damagedBlue", value: false);
			if (GetInt("health") - amount <= 0)
			{
				SetInt("health", 0);
			}
			else
			{
				SetInt("health", GetInt("health") - amount);
			}
		}
	}

	public void orig_UpdateBlueHealth()
	{
		SetIntSwappedArgs(0, "healthBlue");
		if (GetBool("equippedCharm_8"))
		{
			SetIntSwappedArgs(GetInt("healthBlue") + 2, "healthBlue");
		}
		if (GetBool("equippedCharm_9"))
		{
			SetIntSwappedArgs(GetInt("healthBlue") + 4, "healthBlue");
		}
	}

	public void orig_AddHealth(int amount)
	{
		if (GetInt("health") + amount >= GetInt("maxHealth"))
		{
			SetIntSwappedArgs(GetInt("maxHealth"), "health");
		}
		else
		{
			SetIntSwappedArgs(GetInt("health") + amount, "health");
		}
		if (GetInt("health") >= CurrentMaxHealth)
		{
			SetIntSwappedArgs(GetInt("maxHealth"), "health");
		}
	}
}
