public class Probability
{
	[Serializable]
	public class ProbabilityGameObject
	{
		public GameObject prefab;

		[UnityEngine.Tooltip("If probability = 0, it will be considered 1.")]
		public float probability;

		public ProbabilityGameObject()
		{
			probability = 1f;
		}
	}

	public static GameObject GetRandomGameObjectByProbability(ProbabilityGameObject[] array)
	{
		if (array.Length > 1)
		{
			List<ProbabilityGameObject> list = new List<ProbabilityGameObject>(array);
			ProbabilityGameObject probabilityGameObject = null;
			list.Sort((ProbabilityGameObject x, ProbabilityGameObject y) => x.probability.CompareTo(y.probability));
			float num = 0f;
			foreach (ProbabilityGameObject item in list)
			{
				num += ((item.probability != 0f) ? item.probability : 1f);
			}
			float num2 = UnityEngine.Random.Range(0f, num);
			float num3 = 0f;
			foreach (ProbabilityGameObject item2 in list)
			{
				if (num2 >= num3)
				{
					probabilityGameObject = item2;
				}
				num3 += item2.probability;
			}
			return probabilityGameObject.prefab;
		}
		if (array.Length == 1)
		{
			return array[0].prefab;
		}
		return null;
	}
}
public class PromptMarker : MonoBehaviour
{
	public GameObject labels;

	private FadeGroup fadeGroup;

	private tk2dSpriteAnimator anim;

	private GameObject owner;

	private bool isVisible;

	private void Awake()
	{
		anim = GetComponent<tk2dSpriteAnimator>();
		if ((bool)labels)
		{
			fadeGroup = labels.GetComponent<FadeGroup>();
		}
	}

	private void Start()
	{
		if ((bool)GameManager.instance)
		{
			GameManager.instance.UnloadingLevel += RecycleOnLevelLoad;
		}
	}

	private void OnDestroy()
	{
		if ((bool)GameManager.instance)
		{
			GameManager.instance.UnloadingLevel -= RecycleOnLevelLoad;
		}
	}

	private void RecycleOnLevelLoad()
	{
		if (base.gameObject.activeSelf)
		{
			base.gameObject.Recycle();
		}
	}

	private void OnEnable()
	{
		anim.Play("Blank");
	}

	private void Update()
	{
		if (isVisible && (!owner || !owner.activeInHierarchy))
		{
			Hide();
		}
	}

	public void SetLabel(string labelName)
	{
		if (!labels)
		{
			return;
		}
		foreach (Transform item in labels.transform)
		{
			item.gameObject.SetActive(item.name == labelName);
		}
	}

	public void Show()
	{
		anim.Play("Up");
		base.transform.SetPositionZ(0f);
		fadeGroup.FadeUp();
		isVisible = true;
	}

	public void Hide()
	{
		anim.Play("Down");
		fadeGroup.FadeDown();
		owner = null;
		StartCoroutine(RecycleDelayed(fadeGroup.fadeOutTime));
		isVisible = false;
	}

	private IEnumerator RecycleDelayed(float delay)
	{
		yield return new WaitForSeconds(delay);
		gameObject.Recycle();
	}

	public void SetOwner(GameObject obj)
	{
		owner = obj;
	}
}
public class ShowPromptMarker : FsmStateAction
{
	public FsmGameObject prefab;

	public FsmString labelName;

	[UIHint(UIHint.Variable)]
	public FsmGameObject spawnPoint;

	[UIHint(UIHint.Variable)]
	public FsmGameObject storeObject;

	public override void Reset()
	{
		prefab = new FsmGameObject();
		labelName = new FsmString();
		spawnPoint = new FsmGameObject();
		storeObject = new FsmGameObject();
	}

	public override void OnEnter()
	{
		if ((bool)prefab.Value && (bool)spawnPoint.Value)
		{
			GameObject gameObject = null;
			if ((bool)storeObject.Value)
			{
				gameObject = storeObject.Value;
			}
			else
			{
				gameObject = prefab.Value.Spawn();
				storeObject.Value = gameObject;
			}
			gameObject.transform.position = spawnPoint.Value.transform.position;
			PromptMarker component = gameObject.GetComponent<PromptMarker>();
			if ((bool)component)
			{
				component.SetLabel(labelName.Value);
				component.SetOwner(base.Owner);
				component.Show();
			}
		}
		Finish();
	}
}
public class HidePromptMarker : FsmStateAction
{
	[UIHint(UIHint.Variable)]
	public FsmGameObject storedObject;

	public override void Reset()
	{
		storedObject = new FsmGameObject();
	}

	public override void OnEnter()
	{
		if ((bool)storedObject.Value)
		{
			PromptMarker component = storedObject.Value.GetComponent<PromptMarker>();
			if ((bool)component)
			{
				component.Hide();
				storedObject.Value = null;
			}
		}
		Finish();
	}
}
public class Breakable : MonoBehaviour, IHitResponder
{
	[Serializable]
	public class FlingObject
	{
		public GameObject referenceObject;

		[Space]
		public int spawnMin;

		public int spawnMax;

		public float speedMin;

		public float speedMax;

		public float angleMin;

		public float angleMax;

		public Vector2 originVariation;

		public FlingObject()
		{
			spawnMin = 25;
			spawnMax = 30;
			speedMin = 9f;
			speedMax = 20f;
			angleMin = 20f;
			angleMax = 160f;
			originVariation = new Vector2(0.5f, 0.5f);
		}

		public void Fling(Vector3 origin)
		{
			if (!referenceObject)
			{
				return;
			}
			int num = UnityEngine.Random.Range(spawnMin, spawnMax + 1);
			for (int i = 0; i < num; i++)
			{
				GameObject gameObject = referenceObject.Spawn();
				if ((bool)gameObject)
				{
					gameObject.transform.position = origin + new Vector3(UnityEngine.Random.Range(0f - originVariation.x, originVariation.x), UnityEngine.Random.Range(0f - originVariation.y, originVariation.y), 0f);
					float num2 = UnityEngine.Random.Range(speedMin, speedMax);
					float num3 = UnityEngine.Random.Range(angleMin, angleMax);
					float x = num2 * Mathf.Cos(num3 * ((float)Math.PI / 180f));
					float y = num2 * Mathf.Sin(num3 * ((float)Math.PI / 180f));
					Vector2 force = new Vector2(x, y);
					Rigidbody2D component = gameObject.GetComponent<Rigidbody2D>();
					if ((bool)component)
					{
						component.AddForce(force, ForceMode2D.Impulse);
					}
				}
			}
		}
	}

	private Collider2D bodyCollider;

	[UnityEngine.Tooltip("Renderer which presents the undestroyed object.")]
	[SerializeField]
	private Renderer wholeRenderer;

	[UnityEngine.Tooltip("List of child game objects which also represent the whole object.")]
	[SerializeField]
	private GameObject[] wholeParts;

	[UnityEngine.Tooltip("List of child game objects which represent remnants that remain static after destruction.")]
	[SerializeField]
	private GameObject[] remnantParts;

	[SerializeField]
	private List<GameObject> debrisParts;

	[SerializeField]
	private float angleOffset = -60f;

	[UnityEngine.Tooltip("Breakables behind this threshold are inert.")]
	[SerializeField]
	private float inertBackgroundThreshold;

	[UnityEngine.Tooltip("Breakables in front of this threshold are inert.")]
	[SerializeField]
	private float inertForegroundThreshold;

	[UnityEngine.Tooltip("Breakable effects are spawned at this offset.")]
	[SerializeField]
	private Vector3 effectOffset;

	[UnityEngine.Tooltip("Prefab to spawn for audio.")]
	[SerializeField]
	private AudioSource audioSourcePrefab;

	[UnityEngine.Tooltip("Table of audio clips to play upon break.")]
	[SerializeField]
	private AudioEvent breakAudioEvent;

	[UnityEngine.Tooltip("Table of audio clips to play upon break.")]
	[SerializeField]
	private RandomAudioClipTable breakAudioClipTable;

	[UnityEngine.Tooltip("Prefab to spawn when hit from a non-down angle.")]
	[SerializeField]
	private Transform dustHitRegularPrefab;

	[UnityEngine.Tooltip("Prefab to spawn when hit from a down angle.")]
	[SerializeField]
	private Transform dustHitDownPrefab;

	[UnityEngine.Tooltip("Prefab to spawn when hit from a down angle.")]
	[SerializeField]
	private float flingSpeedMin;

	[UnityEngine.Tooltip("Prefab to spawn when hit from a down angle.")]
	[SerializeField]
	private float flingSpeedMax;

	[UnityEngine.Tooltip("Strike effect prefab to spawn.")]
	[SerializeField]
	private Transform strikeEffectPrefab;

	[UnityEngine.Tooltip("Nail hit prefab to spawn.")]
	[SerializeField]
	private Transform nailHitEffectPrefab;

	[UnityEngine.Tooltip("Spell hit effect prefab to spawn.")]
	[SerializeField]
	private Transform spellHitEffectPrefab;

	[UnityEngine.Tooltip("Legacy flag that was set but has always been broken but is no longer used?")]
	[SerializeField]
	private bool preventParticleRotation;

	[UnityEngine.Tooltip("Object to send HIT event to.")]
	[SerializeField]
	private GameObject hitEventReciever;

	[UnityEngine.Tooltip("Forward break effect to sibling FSMs.")]
	[SerializeField]
	private bool forwardBreakEvent;

	[Space]
	public Probability.ProbabilityGameObject[] containingParticles;

	public FlingObject[] flingObjectRegister;

	private bool isBroken;

	protected void Reset()
	{
		inertBackgroundThreshold = 1f;
		inertForegroundThreshold = -1f;
		effectOffset = new Vector3(0f, 0.5f, 0f);
		flingSpeedMin = 10f;
		flingSpeedMax = 17f;
	}

	protected void Awake()
	{
		bodyCollider = GetComponent<Collider2D>();
		PersistentBoolItem component = GetComponent<PersistentBoolItem>();
		if (!(component != null))
		{
			return;
		}
		component.OnGetSaveState += delegate(ref bool val)
		{
			val = isBroken;
		};
		component.OnSetSaveState += delegate(bool val)
		{
			isBroken = val;
			if (isBroken)
			{
				SetStaticPartsActivation(broken: true);
			}
		};
	}

	protected void Start()
	{
		CreateAdditionalDebrisParts(debrisParts);
		float z = base.transform.position.z;
		if (z > inertBackgroundThreshold || z < inertForegroundThreshold)
		{
			BoxCollider2D component = GetComponent<BoxCollider2D>();
			if (component != null)
			{
				component.enabled = false;
			}
			UnityEngine.Object.Destroy(this);
			return;
		}
		for (int i = 0; i < remnantParts.Length; i++)
		{
			GameObject gameObject = remnantParts[i];
			if (gameObject != null && gameObject.activeSelf)
			{
				gameObject.SetActive(value: false);
			}
		}
		angleOffset *= Mathf.Sign(base.transform.localScale.x);
	}

	protected virtual void CreateAdditionalDebrisParts(List<GameObject> debrisParts)
	{
	}

	public void BreakSelf()
	{
		if (!isBroken)
		{
			Break(70f, 110f, 1f);
		}
	}

	public void Hit(HitInstance damageInstance)
	{
		if (isBroken)
		{
			return;
		}
		float impactAngle = damageInstance.Direction;
		float num = damageInstance.MagnitudeMultiplier;
		if (damageInstance.AttackType == AttackTypes.Spell)
		{
			spellHitEffectPrefab.Spawn(base.transform.position).SetPositionZ(0.0031f);
		}
		else
		{
			if (damageInstance.AttackType != AttackTypes.Nail && damageInstance.AttackType != AttackTypes.Generic)
			{
				impactAngle = 90f;
				num = 1f;
			}
			strikeEffectPrefab.Spawn(base.transform.position);
			Vector3 position = (damageInstance.Source.transform.position + base.transform.position) * 0.5f;
			SpawnNailHitEffect(nailHitEffectPrefab, position, impactAngle);
		}
		int cardinalDirection = DirectionUtils.GetCardinalDirection(damageInstance.Direction);
		Transform transform = dustHitRegularPrefab;
		float flingAngleMin;
		float flingAngleMax;
		Vector3 euler;
		switch (cardinalDirection)
		{
		case 2:
			angleOffset *= -1f;
			flingAngleMin = 120f;
			flingAngleMax = 160f;
			euler = new Vector3(180f, 90f, 270f);
			break;
		case 0:
			flingAngleMin = 30f;
			flingAngleMax = 70f;
			euler = new Vector3(0f, 90f, 270f);
			break;
		case 1:
			angleOffset = 0f;
			flingAngleMin = 70f;
			flingAngleMax = 110f;
			num *= 1.5f;
			euler = new Vector3(270f, 90f, 270f);
			break;
		default:
			angleOffset = 0f;
			flingAngleMin = 160f;
			flingAngleMax = 380f;
			transform = dustHitDownPrefab;
			euler = new Vector3(-72.5f, -180f, -180f);
			break;
		}
		if (transform != null)
		{
			transform.Spawn(base.transform.position + effectOffset, Quaternion.Euler(euler));
		}
		Break(flingAngleMin, flingAngleMax, num);
	}

	private static Transform SpawnNailHitEffect(Transform nailHitEffectPrefab, Vector3 position, float impactAngle)
	{
		if (nailHitEffectPrefab == null)
		{
			return null;
		}
		int cardinalDirection = DirectionUtils.GetCardinalDirection(impactAngle);
		float y = 1.5f;
		float minInclusive;
		float maxInclusive;
		switch (cardinalDirection)
		{
		case 3:
			minInclusive = 250f;
			maxInclusive = 290f;
			break;
		case 1:
			minInclusive = 70f;
			maxInclusive = 110f;
			break;
		default:
			minInclusive = 340f;
			maxInclusive = 380f;
			break;
		}
		float x = ((cardinalDirection == 2) ? (-1.5f) : 1.5f);
		Transform obj = nailHitEffectPrefab.Spawn(position);
		Vector3 eulerAngles = obj.eulerAngles;
		eulerAngles.z = UnityEngine.Random.Range(minInclusive, maxInclusive);
		obj.eulerAngles = eulerAngles;
		Vector3 localScale = obj.localScale;
		localScale.x = x;
		localScale.y = y;
		obj.localScale = localScale;
		return obj;
	}

	private void SetStaticPartsActivation(bool broken)
	{
		if (wholeRenderer != null)
		{
			wholeRenderer.enabled = !broken;
		}
		for (int i = 0; i < wholeParts.Length; i++)
		{
			GameObject gameObject = wholeParts[i];
			if (gameObject == null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Unassigned whole part in {0}", this);
			}
			else
			{
				gameObject.SetActive(!broken);
			}
		}
		for (int j = 0; j < remnantParts.Length; j++)
		{
			GameObject gameObject2 = remnantParts[j];
			if (gameObject2 == null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Unassigned remnant part in {0}", this);
			}
			else
			{
				gameObject2.SetActive(broken);
			}
		}
		if (hitEventReciever != null)
		{
			FSMUtility.SendEventToGameObject(hitEventReciever, "HIT");
		}
		if ((bool)bodyCollider)
		{
			bodyCollider.enabled = !broken;
		}
	}

	public void Break(float flingAngleMin, float flingAngleMax, float impactMultiplier)
	{
		if (isBroken)
		{
			return;
		}
		SetStaticPartsActivation(broken: true);
		for (int i = 0; i < debrisParts.Count; i++)
		{
			GameObject gameObject = debrisParts[i];
			if (gameObject == null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Unassigned debris part in {0}", this);
				continue;
			}
			gameObject.SetActive(value: true);
			gameObject.transform.SetRotationZ(gameObject.transform.localEulerAngles.z + angleOffset);
			Rigidbody2D component = gameObject.GetComponent<Rigidbody2D>();
			if (component != null)
			{
				float num = UnityEngine.Random.Range(flingAngleMin, flingAngleMax);
				Vector2 vector = new Vector2(Mathf.Cos(num * ((float)Math.PI / 180f)), Mathf.Sin(num * ((float)Math.PI / 180f)));
				float num2 = UnityEngine.Random.Range(flingSpeedMin, flingSpeedMax) * impactMultiplier;
				component.velocity = vector * num2;
			}
		}
		if (containingParticles.Length != 0)
		{
			GameObject gameObject2 = Probability.GetRandomGameObjectByProbability(containingParticles);
			if ((bool)gameObject2)
			{
				if (gameObject2.transform.parent != base.transform)
				{
					FlingObject flingObject = null;
					FlingObject[] array = flingObjectRegister;
					foreach (FlingObject flingObject2 in array)
					{
						if (flingObject2.referenceObject == gameObject2)
						{
							flingObject = flingObject2;
							break;
						}
					}
					if (flingObject != null)
					{
						flingObject.Fling(base.transform.position);
					}
					else
					{
						gameObject2 = gameObject2.Spawn(base.transform.position);
					}
				}
				gameObject2.SetActive(value: true);
			}
		}
		breakAudioEvent.SpawnAndPlayOneShot(audioSourcePrefab, base.transform.position);
		breakAudioClipTable.SpawnAndPlayOneShot(audioSourcePrefab, base.transform.position);
		if (hitEventReciever != null)
		{
			FSMUtility.SendEventToGameObject(hitEventReciever, "HIT");
		}
		if (forwardBreakEvent)
		{
			FSMUtility.SendEventToGameObject(base.gameObject, "BREAK");
		}
		GameObject gameObject3 = GameObject.FindGameObjectWithTag("CameraParent");
		if (gameObject3 != null)
		{
			PlayMakerFSM playMakerFSM = PlayMakerFSM.FindFsmOnGameObject(gameObject3, "CameraShake");
			if (playMakerFSM != null)
			{
				playMakerFSM.SendEvent("EnemyKillShake");
			}
		}
		bodyCollider.enabled = false;
		isBroken = true;
	}
}
public class BreakableInfectedVine : MonoBehaviour
{
	public GameObject[] blobs;

	[Space]
	public GameObject[] effects;

	[Space]
	public int spatterAmount = 5;

	public float spatterSpeedMin = 10f;

	public float spatterSpeedMax = 20f;

	public float spatterAngleMin = 40f;

	public float spatterAngleMax = 140f;

	[Space]
	public float audioPitchMin = 0.8f;

	public float audioPitchMax = 1.1f;

	private bool activated;

	private AudioSource source;

	private VibrationPlayer vibration;

	private void Awake()
	{
		source = GetComponent<AudioSource>();
		vibration = GetComponent<VibrationPlayer>();
	}

	private void Start()
	{
		if (Mathf.Abs(base.transform.position.z - 0.004f) > 1f)
		{
			if ((bool)source)
			{
				source.enabled = false;
			}
			Collider2D component = GetComponent<Collider2D>();
			if ((bool)component)
			{
				component.enabled = false;
			}
			base.enabled = false;
		}
	}

	private void OnTriggerEnter2D(Collider2D collision)
	{
		if (activated)
		{
			return;
		}
		bool flag = false;
		if (collision.tag == "Nail Attack")
		{
			flag = true;
		}
		else if (collision.tag == "Hero Spell")
		{
			flag = true;
		}
		else if (collision.tag == "HeroBox" && HeroController.instance.cState.superDashing)
		{
			flag = true;
		}
		if (flag)
		{
			GameObject[] array = blobs;
			foreach (GameObject gameObject in array)
			{
				gameObject.SetActive(value: false);
				SpawnSpatters(gameObject.transform.position);
			}
			array = effects;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].SetActive(value: true);
			}
			if ((bool)source)
			{
				source.pitch = UnityEngine.Random.Range(audioPitchMin, audioPitchMax);
				source.Play();
			}
			if ((bool)vibration)
			{
				vibration.Play();
			}
			activated = true;
		}
	}

	private void SpawnSpatters(Vector3 position)
	{
		GlobalPrefabDefaults.Instance.SpawnBlood(position, (short)spatterAmount, (short)spatterAmount, spatterSpeedMin, spatterSpeedMax, spatterAngleMin, spatterAngleMax);
	}
}
public class BreakableObject : MonoBehaviour
{
	[Serializable]
	public class Direction
	{
		public GameObject effectPrefab;

		public Vector3 scale = Vector3.one;

		public Vector3 rotation;

		[Space]
		public float minFlingSpeed = 4f;

		public float maxFlingSpeed = 4f;

		public float minFlingAngle = 5f;

		public float maxFlingAngle = 5f;
	}

	[Serializable]
	public class FlingObject
	{
		public GameObject referenceObject;

		[Space]
		public int spawnMin = 25;

		public int spawnMax = 30;

		public float speedMin = 9f;

		public float speedMax = 20f;

		public float angleMin = 20f;

		public float angleMax = 160f;

		public Vector2 originVariation = new Vector2(0.5f, 0.5f);

		public void Fling(Vector3 origin)
		{
			if (!referenceObject)
			{
				return;
			}
			int num = UnityEngine.Random.Range(spawnMin, spawnMax + 1);
			for (int i = 0; i < num; i++)
			{
				GameObject gameObject = referenceObject.Spawn();
				if ((bool)gameObject)
				{
					gameObject.transform.position = origin + new Vector3(UnityEngine.Random.Range(0f - originVariation.x, originVariation.x), UnityEngine.Random.Range(0f - originVariation.y, originVariation.y), 0f);
					float num2 = UnityEngine.Random.Range(speedMin, speedMax);
					float num3 = UnityEngine.Random.Range(angleMin, angleMax);
					float x = num2 * Mathf.Cos(num3 * ((float)Math.PI / 180f));
					float y = num2 * Mathf.Sin(num3 * ((float)Math.PI / 180f));
					Vector2 force = new Vector2(x, y);
					Rigidbody2D component = gameObject.GetComponent<Rigidbody2D>();
					if ((bool)component)
					{
						component.AddForce(force, ForceMode2D.Impulse);
					}
				}
			}
		}
	}

	public GameObject[] flingDebris;

	public float attackMagnitude = 6f;

	[Space]
	public Direction right;

	public Direction left;

	public Direction up;

	public Direction down;

	[Space]
	public Probability.ProbabilityGameObject[] containingParticles;

	public FlingObject[] flingObjectRegister;

	[Space]
	public GameObject objectNailEffectPrefab;

	public GameObject midpointNailEffectPrefab;

	public GameObject spellHitEffectPrefab;

	[Space]
	public AudioClip[] cutSound;

	public float pitchMin = 0.9f;

	public float pitchMax = 1.1f;

	private AudioSource source;

	private bool activated;

	private void Awake()
	{
		source = GetComponent<AudioSource>();
	}

	private void Start()
	{
		if (Mathf.Abs(base.transform.position.z - 0.004f) > 1f)
		{
			if ((bool)source)
			{
				source.enabled = false;
			}
			Collider2D component = GetComponent<Collider2D>();
			if ((bool)component)
			{
				component.enabled = false;
			}
			base.enabled = false;
		}
	}

	private void OnTriggerEnter2D(Collider2D collision)
	{
		if (activated)
		{
			return;
		}
		bool flag = false;
		int num = (int)Mathf.Sign(base.transform.position.x - collision.transform.position.x);
		float num2 = 1f;
		Direction direction = null;
		if (collision.tag == "Nail Attack")
		{
			flag = true;
			num2 = attackMagnitude;
			if ((bool)objectNailEffectPrefab)
			{
				GameObject obj = objectNailEffectPrefab.Spawn(base.transform.position);
				Vector3 localScale = obj.transform.localScale;
				localScale.x = Mathf.Abs(localScale.x) * (float)num;
				obj.transform.localScale = localScale;
			}
			if ((bool)midpointNailEffectPrefab)
			{
				GameObject obj2 = midpointNailEffectPrefab.Spawn((collision.transform.position + base.transform.position) / 2f);
				Vector3 localScale2 = obj2.transform.localScale;
				localScale2.x = Mathf.Abs(localScale2.x) * (float)num;
				obj2.transform.localScale = localScale2;
			}
			float value = PlayMakerFSM.FindFsmOnGameObject(collision.gameObject, "damages_enemy").FsmVariables.FindFsmFloat("direction").Value;
			if (value < 45f)
			{
				direction = right;
			}
			else if (value < 135f)
			{
				direction = up;
			}
			else if (value < 225f)
			{
				direction = left;
			}
			else if (value < 360f)
			{
				direction = down;
			}
			if (direction != null && (bool)direction.effectPrefab)
			{
				GameObject gameObject = direction.effectPrefab.Spawn(base.transform.position);
				if ((bool)gameObject)
				{
					gameObject.transform.localScale = direction.scale;
					gameObject.transform.localEulerAngles = direction.rotation;
				}
			}
		}
		else if (collision.tag == "Hero Spell")
		{
			flag = true;
			if ((bool)spellHitEffectPrefab)
			{
				spellHitEffectPrefab.Spawn(base.transform.position);
			}
			else
			{
				UnityEngine.Debug.Log("No spell hit effect assigned to: " + base.gameObject.name);
			}
		}
		if (!flag)
		{
			return;
		}
		if (containingParticles.Length != 0)
		{
			GameObject gameObject2 = Probability.GetRandomGameObjectByProbability(containingParticles);
			if ((bool)gameObject2)
			{
				if (gameObject2.transform.parent != base.transform)
				{
					FlingObject flingObject = null;
					FlingObject[] array = flingObjectRegister;
					foreach (FlingObject flingObject2 in array)
					{
						if (flingObject2.referenceObject == gameObject2)
						{
							flingObject = flingObject2;
							break;
						}
					}
					if (flingObject != null)
					{
						flingObject.Fling(base.transform.position);
					}
					else
					{
						gameObject2 = gameObject2.Spawn(base.transform.position);
					}
				}
				gameObject2.SetActive(value: true);
			}
		}
		GameObject[] array2 = flingDebris;
		foreach (GameObject gameObject3 in array2)
		{
			if ((bool)gameObject3)
			{
				gameObject3.SetActive(value: true);
				float num3 = UnityEngine.Random.Range(direction.minFlingSpeed, direction.maxFlingSpeed) * num2;
				float num4 = UnityEngine.Random.Range(direction.minFlingAngle, direction.maxFlingAngle);
				float x = num3 * Mathf.Cos(num4 * ((float)Math.PI / 180f));
				float y = num3 * Mathf.Sin(num4 * ((float)Math.PI / 180f));
				Vector2 force = new Vector2(x, y);
				Rigidbody2D component = gameObject3.GetComponent<Rigidbody2D>();
				if ((bool)component)
				{
					component.AddForce(force, ForceMode2D.Impulse);
				}
			}
		}
		if ((bool)source && cutSound.Length != 0)
		{
			source.clip = cutSound[UnityEngine.Random.Range(0, cutSound.Length)];
			source.pitch = UnityEngine.Random.Range(pitchMin, pitchMax);
			source.Play();
		}
		GameCameras gameCameras = UnityEngine.Object.FindObjectOfType<GameCameras>();
		if ((bool)gameCameras)
		{
			gameCameras.cameraShakeFSM.SendEvent("EnemyKillShake");
		}
		SpriteRenderer component2 = GetComponent<SpriteRenderer>();
		if ((bool)component2)
		{
			component2.enabled = false;
		}
		activated = true;
	}
}
public class BreakablePole : MonoBehaviour, IHitResponder
{
	[SerializeField]
	private SpriteRenderer spriteRenderer;

	[SerializeField]
	private Sprite brokenSprite;

	[SerializeField]
	private float inertBackgroundThreshold;

	[SerializeField]
	private float inertForegroundThreshold;

	[SerializeField]
	private AudioSource audioSourcePrefab;

	[SerializeField]
	private RandomAudioClipTable hitClip;

	[SerializeField]
	private GameObject slashImpactPrefab;

	[SerializeField]
	private Rigidbody2D top;

	protected void Reset()
	{
		inertBackgroundThreshold = -1f;
		inertForegroundThreshold = 1f;
	}

	protected void Start()
	{
		float z = base.transform.position.z;
		if (z < inertBackgroundThreshold || z > inertForegroundThreshold)
		{
			base.enabled = false;
		}
	}

	public void Hit(HitInstance damageInstance)
	{
		int cardinalDirection = DirectionUtils.GetCardinalDirection(damageInstance.Direction);
		if (cardinalDirection == 2 || cardinalDirection == 0)
		{
			spriteRenderer.sprite = brokenSprite;
			Transform obj = slashImpactPrefab.Spawn().transform;
			obj.eulerAngles = new Vector3(0f, 0f, UnityEngine.Random.Range(340f, 380f));
			Vector3 localScale = obj.localScale;
			localScale.x = ((cardinalDirection == 2) ? (-1f) : 1f);
			localScale.y = 1f;
			hitClip.SpawnAndPlayOneShot(audioSourcePrefab, base.transform.position);
			top.gameObject.SetActive(value: true);
			float num = ((cardinalDirection == 2) ? UnityEngine.Random.Range(120, 140) : UnityEngine.Random.Range(40, 60));
			top.velocity = new Vector2(Mathf.Cos(num * ((float)Math.PI / 180f)), Mathf.Sin(num * ((float)Math.PI / 180f))) * 17f;
			base.enabled = false;
		}
	}
}
public class BreakablePoleSimple : MonoBehaviour
{
	public GameObject bottom;

	public GameObject top;

	public float speed = 17f;

	public float angleMin = 40f;

	public float angleMax = 60f;

	[Space]
	public GameObject slashEffectPrefab;

	public float slashAngleMin = 340f;

	public float slashAngleMax = 380f;

	[Space]
	public float audioPitchMin = 0.85f;

	public float audioPitchMax = 1.15f;

	private bool activated;

	private AudioSource source;

	private void Awake()
	{
		source = GetComponent<AudioSource>();
	}

	private void Start()
	{
		if (Mathf.Abs(base.transform.position.z - 0.004f) > 1f)
		{
			if ((bool)source)
			{
				source.enabled = false;
			}
			Collider2D component = GetComponent<Collider2D>();
			if ((bool)component)
			{
				component.enabled = false;
			}
			base.enabled = false;
		}
	}

	private void OnTriggerEnter2D(Collider2D collision)
	{
		if (activated)
		{
			return;
		}
		bool flag = false;
		float num = 1f;
		if (collision.tag == "Nail Attack")
		{
			float value = PlayMakerFSM.FindFsmOnGameObject(collision.gameObject, "damages_enemy").FsmVariables.FindFsmFloat("direction").Value;
			if (value < 45f)
			{
				flag = true;
				num = 1f;
			}
			else if (value < 135f)
			{
				flag = false;
			}
			else if (value < 225f)
			{
				flag = true;
				num = -1f;
			}
			else if (value < 360f)
			{
				flag = false;
			}
		}
		else if (collision.tag == "Hero Spell")
		{
			flag = true;
		}
		if (!flag)
		{
			return;
		}
		SpriteRenderer component = GetComponent<SpriteRenderer>();
		if ((bool)component)
		{
			component.enabled = false;
		}
		if ((bool)bottom)
		{
			bottom.SetActive(value: true);
		}
		if ((bool)top)
		{
			top.SetActive(value: true);
			float num2 = UnityEngine.Random.Range(angleMin, angleMax);
			Vector2 velocity = default(Vector2);
			velocity.x = speed * Mathf.Cos(num2 * ((float)Math.PI / 180f)) * num;
			velocity.y = speed * Mathf.Sin(num2 * ((float)Math.PI / 180f));
			Rigidbody2D component2 = top.GetComponent<Rigidbody2D>();
			if ((bool)component2)
			{
				component2.velocity = velocity;
			}
		}
		if ((bool)slashEffectPrefab)
		{
			GameObject obj = slashEffectPrefab.Spawn(base.transform.position);
			obj.transform.SetScaleX(num);
			obj.transform.SetRotationZ(UnityEngine.Random.Range(slashAngleMin, slashAngleMax));
		}
		if ((bool)source)
		{
			source.pitch = UnityEngine.Random.Range(audioPitchMin, audioPitchMax);
			source.Play();
		}
		activated = true;
	}
}
public class BreakablePoleTopLand : MonoBehaviour
{
	public float angleMin = 165f;

	public float angleMax = 195f;

	[Space]
	public GameObject[] effects;

	private void OnCollisionEnter2D(Collision2D collision)
	{
		Collider2D otherCollider = collision.otherCollider;
		if (collision.gameObject.layer != 8)
		{
			return;
		}
		Vector2 point = collision.GetSafeContact().Point;
		if (point.y > otherCollider.bounds.center.y)
		{
			return;
		}
		float z = base.transform.eulerAngles.z;
		if (z >= angleMin && z <= angleMax)
		{
			GameObject[] array = effects;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].Spawn(point);
			}
			Rigidbody2D component = GetComponent<Rigidbody2D>();
			if ((bool)component)
			{
				component.isKinematic = true;
				component.simulated = false;
				component.velocity = Vector2.zero;
				component.angularVelocity = 0f;
			}
		}
	}
}
public interface IExternalDebris
{
	void InitExternalDebris();
}
public class BreakableWithExternalDebris : Breakable
{
	[Serializable]
	public struct ExternalDebris
	{
		public GameObject Prefab;

		public int Count;
	}

	[Serializable]
	public class WeightedExternalDebrisItem : WeightedItem
	{
		public ExternalDebris Value;
	}

	[SerializeField]
	private float debrisPrefabPositionVariance;

	[SerializeField]
	private ExternalDebris[] externalDebris;

	[SerializeField]
	private WeightedExternalDebrisItem[] externalDebrisVariants;

	private static List<IExternalDebris> externalDebrisResponders = new List<IExternalDebris>();

	protected override void CreateAdditionalDebrisParts(List<GameObject> debrisParts)
	{
		base.CreateAdditionalDebrisParts(debrisParts);
		for (int i = 0; i < externalDebris.Length; i++)
		{
			Spawn(externalDebris[i], debrisParts);
		}
		WeightedExternalDebrisItem weightedExternalDebrisItem = externalDebrisVariants.SelectValue();
		if (weightedExternalDebrisItem != null)
		{
			Spawn(weightedExternalDebrisItem.Value, debrisParts);
		}
	}

	private void Spawn(ExternalDebris externalDebris, List<GameObject> debrisParts)
	{
		for (int i = 0; i < externalDebris.Count; i++)
		{
			if (!(externalDebris.Prefab == null))
			{
				GameObject gameObject = UnityEngine.Object.Instantiate(externalDebris.Prefab);
				gameObject.GetComponents(externalDebrisResponders);
				for (int j = 0; j < externalDebrisResponders.Count; j++)
				{
					externalDebrisResponders[j].InitExternalDebris();
				}
				externalDebrisResponders.Clear();
				gameObject.transform.position = base.transform.position + new Vector3(UnityEngine.Random.Range(0f - debrisPrefabPositionVariance, debrisPrefabPositionVariance), UnityEngine.Random.Range(0f - debrisPrefabPositionVariance, debrisPrefabPositionVariance), 0f);
				gameObject.SetActive(value: false);
				debrisParts.Add(gameObject);
			}
		}
	}
}
public class ConveyorBelt : MonoBehaviour
{
	public float speed;

	public bool vertical;

	private void OnCollisionEnter2D(Collision2D collision)
	{
		if ((bool)collision.gameObject.GetComponent<ConveyorMovement>())
		{
			collision.gameObject.GetComponent<ConveyorMovement>().StartConveyorMove(speed, 0f);
		}
		if ((bool)collision.gameObject.GetComponent<DropCrystal>())
		{
			collision.gameObject.GetComponent<DropCrystal>().StartConveyorMove(speed, 0f);
		}
		if ((bool)collision.gameObject.GetComponent<HeroController>())
		{
			if (vertical)
			{
				collision.gameObject.GetComponent<ConveyorMovementHero>().StartConveyorMove(0f, speed);
				collision.gameObject.GetComponent<HeroController>().cState.onConveyorV = true;
			}
			else
			{
				collision.gameObject.GetComponent<HeroController>().SetConveyorSpeed(speed);
				collision.gameObject.GetComponent<HeroController>().cState.onConveyor = true;
			}
		}
	}

	private void OnCollisionExit2D(Collision2D collision)
	{
		if ((bool)collision.gameObject.GetComponent<ConveyorMovement>())
		{
			collision.gameObject.GetComponent<ConveyorMovement>().StopConveyorMove();
		}
		if ((bool)collision.gameObject.GetComponent<DropCrystal>())
		{
			collision.gameObject.GetComponent<DropCrystal>().StopConveyorMove();
		}
		if ((bool)collision.gameObject.GetComponent<HeroController>())
		{
			collision.gameObject.GetComponent<ConveyorMovementHero>().StopConveyorMove();
			collision.gameObject.GetComponent<HeroController>().cState.onConveyor = false;
			collision.gameObject.GetComponent<HeroController>().cState.onConveyorV = false;
		}
	}
}
public class ConveyorMovement : MonoBehaviour
{
	private float xSpeed;

	private float ySpeed;

	public bool onConveyor;

	public void OnEnable()
	{
		onConveyor = false;
	}

	public void StartConveyorMove(float c_xSpeed, float c_ySpeed)
	{
		onConveyor = true;
		xSpeed = c_xSpeed;
		ySpeed = c_ySpeed;
	}

	public void StopConveyorMove()
	{
		onConveyor = false;
	}

	private void LateUpdate()
	{
		if (onConveyor && xSpeed != 0f)
		{
			base.transform.position = new Vector3(base.transform.position.x + xSpeed * Time.deltaTime, base.transform.position.y, base.transform.position.z);
		}
	}
}
public class ConveyorMovementHero : MonoBehaviour
{
	private float xSpeed;

	private float ySpeed;

	private bool onConveyor;

	public bool gravityOff;

	private HeroController heroCon;

	private void Start()
	{
		heroCon = GetComponent<HeroController>();
	}

	public void StartConveyorMove(float c_xSpeed, float c_ySpeed)
	{
		onConveyor = true;
		xSpeed = c_xSpeed;
		ySpeed = c_ySpeed;
	}

	public void StopConveyorMove()
	{
		onConveyor = false;
		if (gravityOff)
		{
			if (!heroCon.cState.superDashing)
			{
				heroCon.AffectedByGravity(gravityApplies: true);
			}
			gravityOff = false;
		}
	}

	private void LateUpdate()
	{
		if (!onConveyor)
		{
			return;
		}
		_ = xSpeed;
		_ = 0f;
		if (ySpeed != 0f && (heroCon.cState.wallSliding || heroCon.cState.superDashOnWall))
		{
			if (heroCon.cState.superDashOnWall)
			{
				GetComponent<Rigidbody2D>().velocity = new Vector3(0f, 0f);
			}
			GetComponent<Rigidbody2D>().velocity = new Vector2(GetComponent<Rigidbody2D>().velocity.x, ySpeed);
			if (!gravityOff)
			{
				heroCon.AffectedByGravity(gravityApplies: false);
				gravityOff = true;
			}
		}
		else if (gravityOff && !heroCon.cState.superDashing)
		{
			heroCon.AffectedByGravity(gravityApplies: true);
			gravityOff = false;
		}
	}
}
public class ConveyorSpeedZone : MonoBehaviour
{
	public float speed;

	private void OnTriggerEnter2D(Collider2D collision)
	{
		if ((bool)collision.gameObject.GetComponent<HeroController>())
		{
			collision.gameObject.GetComponent<HeroController>().SetConveyorSpeed(speed);
		}
	}
}
public class ConveyorZone : MonoBehaviour
{
	public float speed;

	public bool vertical;

	private bool activated = true;

	private void Start()
	{
		if ((bool)HeroController.instance)
		{
			activated = false;
			HeroController.HeroInPosition temp = null;
			temp = delegate
			{
				activated = true;
				HeroController.instance.heroInPosition -= temp;
			};
			HeroController.instance.heroInPosition += temp;
		}
	}

	private void OnTriggerEnter2D(Collider2D collision)
	{
		if (!activated)
		{
			return;
		}
		if ((bool)collision.gameObject.GetComponent<ConveyorMovement>())
		{
			collision.gameObject.GetComponent<ConveyorMovement>().StartConveyorMove(speed, 0f);
		}
		if ((bool)collision.gameObject.GetComponent<HeroController>())
		{
			if (vertical)
			{
				collision.gameObject.GetComponent<ConveyorMovementHero>().StartConveyorMove(0f, speed);
				collision.gameObject.GetComponent<HeroController>().cState.onConveyorV = true;
			}
			else
			{
				collision.gameObject.GetComponent<HeroController>().SetConveyorSpeed(speed);
				collision.gameObject.GetComponent<HeroController>().cState.inConveyorZone = true;
			}
		}
	}

	private void OnTriggerExit2D(Collider2D collision)
	{
		if (activated)
		{
			if ((bool)collision.gameObject.GetComponent<ConveyorMovement>())
			{
				collision.gameObject.GetComponent<ConveyorMovement>().StopConveyorMove();
			}
			if ((bool)collision.gameObject.GetComponent<HeroController>())
			{
				collision.gameObject.GetComponent<ConveyorMovementHero>().StopConveyorMove();
				collision.gameObject.GetComponent<HeroController>().cState.inConveyorZone = false;
				collision.gameObject.GetComponent<HeroController>().cState.onConveyorV = false;
			}
		}
	}
}
[RequireComponent(typeof(Rigidbody2D))]
public class DebrisPiece : MonoBehaviour
{
	[SerializeField]
	private bool resetOnDisable;

	private bool didLaunch;

	private bool didSpin;

	[Header("'set_z' Functionality")]
	[SerializeField]
	private bool forceZ;

	[SerializeField]
	private float forcedZ;

	[Header("'spin_self' Functionality")]
	[SerializeField]
	private bool randomStartRotation;

	[SerializeField]
	private float zRandomRadius;

	[SerializeField]
	private float spinFactor;

	private Rigidbody2D body;

	protected void Reset()
	{
		resetOnDisable = true;
		forceZ = true;
		forcedZ = 0.015f;
		randomStartRotation = false;
		zRandomRadius = 0.000999f;
		spinFactor = 10f;
	}

	protected void Awake()
	{
		body = GetComponent<Rigidbody2D>();
		if (body == null)
		{
			UnityEngine.Debug.LogErrorFormat(this, "Missing Rigidbody2D on {0}", base.name);
		}
	}

	protected void OnEnable()
	{
		if (!didLaunch)
		{
			Launch();
		}
	}

	protected void OnDisable()
	{
		if (resetOnDisable)
		{
			didLaunch = false;
			didSpin = false;
		}
	}

	private void Launch()
	{
		didLaunch = true;
		if (forceZ)
		{
			Vector3 position = base.transform.position;
			position.z = forcedZ;
			base.transform.position = position;
		}
		if (randomStartRotation)
		{
			Vector3 localEulerAngles = base.transform.localEulerAngles;
			localEulerAngles.z = UnityEngine.Random.Range(0f, 360f);
			base.transform.localEulerAngles = localEulerAngles;
		}
	}

	protected void FixedUpdate()
	{
		if (!didSpin)
		{
			Spin();
		}
	}

	private void Spin()
	{
		didSpin = true;
		if (spinFactor != 0f)
		{
			if (zRandomRadius != 0f)
			{
				Vector3 position = base.transform.position;
				position.z += UnityEngine.Random.Range(0f - zRandomRadius, zRandomRadius);
				base.transform.position = position;
			}
			body.AddTorque((0f - body.velocity.x) * spinFactor);
		}
	}
}
public class DestructibleProp : MonoBehaviour
{
}
public class DreamPlant : MonoBehaviour
{
	public HeroDetect heroDetector;

	public AudioClip glowSound;

	private AudioSource audioSource;

	public ParticleSystem wiltedParticles;

	[Space]
	public ColorFader glowFader;

	public ColorFader completeGlowFader;

	[Space]
	public AudioClip hitSound;

	public GameObject dreamImpact;

	public GameObject dreamAreaEffect;

	private GameObject spawnedDreamAreaEffect;

	public ParticleSystem activateParticles;

	public ParticleSystem activatedParticles;

	public GameObject whiteFlash;

	[Space]
	public AudioClip growChargeSound;

	public AudioClip growSound;

	public ParticleSystem completeChargeParticles;

	public ParticleSystem growParticles;

	public GameObject dreamDialogue;

	[Space]
	public string playerdataBool;

	private tk2dSpriteAnimator anim;

	private bool activated;

	private bool completed;

	private bool hasDreamNail;

	private bool seenDreamNailPrompt;

	private int spawnedOrbs;

	private Coroutine checkOrbRoutine;

	private DreamPlantOrb[] dreamOrbs;

	private SpriteFlash spriteFlash;

	private void Awake()
	{
		spriteFlash = GetComponent<SpriteFlash>();
		PersistentBoolItem component = GetComponent<PersistentBoolItem>();
		if ((bool)component)
		{
			component.OnGetSaveState += delegate(ref bool value)
			{
				value = completed;
			};
			component.OnSetSaveState += delegate(bool value)
			{
				completed = value;
				if (completed)
				{
					activated = true;
					if ((bool)anim)
					{
						anim.Play("Completed");
					}
					if ((bool)dreamDialogue)
					{
						dreamDialogue.SetActive(value: true);
					}
				}
			};
		}
		audioSource = GetComponent<AudioSource>();
		anim = GetComponent<tk2dSpriteAnimator>();
	}

	private void Start()
	{
		hasDreamNail = GameManager.instance.GetPlayerDataBool("hasDreamNail");
		seenDreamNailPrompt = GameManager.instance.GetPlayerDataBool("seenDreamNailPrompt");
		if ((bool)heroDetector && hasDreamNail)
		{
			heroDetector.OnEnter += delegate
			{
				ShowPrompt(show: true);
			};
			heroDetector.OnExit += delegate
			{
				ShowPrompt(show: false);
			};
		}
		if (completed && playerdataBool != "")
		{
			GameManager.instance.SetPlayerDataBool(playerdataBool, value: true);
		}
		if (hasDreamNail && !activated && (bool)dreamAreaEffect)
		{
			spawnedDreamAreaEffect = UnityEngine.Object.Instantiate(dreamAreaEffect);
			spawnedDreamAreaEffect.SetActive(value: false);
		}
		if ((bool)whiteFlash)
		{
			whiteFlash.SetActive(value: true);
			whiteFlash.SetActive(value: false);
		}
		dreamOrbs = UnityEngine.Object.FindObjectsOfType<DreamPlantOrb>();
		DreamPlantOrb.plant = this;
	}

	private void OnTriggerEnter2D(Collider2D collision)
	{
		if (activated || !(collision.tag == "Dream Attack"))
		{
			return;
		}
		activated = true;
		DreamPlantOrb[] array = dreamOrbs;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].Show();
		}
		if ((bool)spriteFlash)
		{
			spriteFlash.flashFocusHeal();
		}
		if ((bool)glowFader)
		{
			glowFader.Fade(up: false);
		}
		if ((bool)anim)
		{
			anim.Play("Activate");
		}
		if ((bool)audioSource && (bool)hitSound)
		{
			audioSource.PlayOneShot(hitSound);
		}
		if ((bool)spawnedDreamAreaEffect)
		{
			spawnedDreamAreaEffect.SetActive(value: true);
		}
		if ((bool)whiteFlash)
		{
			whiteFlash.SetActive(value: true);
		}
		if ((bool)activateParticles)
		{
			activateParticles.gameObject.SetActive(value: true);
		}
		if ((bool)activatedParticles)
		{
			activatedParticles.gameObject.SetActive(value: true);
		}
		if ((bool)dreamImpact)
		{
			Vector3 center = collision.bounds.center;
			Collider2D component = GetComponent<Collider2D>();
			if ((bool)component)
			{
				center += component.bounds.center;
				center /= 2f;
			}
			dreamImpact.Spawn(center);
		}
		GameCameras instance = GameCameras.instance;
		if ((bool)instance)
		{
			instance.cameraShakeFSM.SendEvent("AverageShake");
		}
		EventRegister.SendEvent("DREAM PLANT HIT");
	}

	public void AddOrbCount()
	{
		spawnedOrbs++;
		if (checkOrbRoutine == null)
		{
			checkOrbRoutine = StartCoroutine(CheckOrbs());
		}
	}

	public void RemoveOrbCount()
	{
		spawnedOrbs--;
	}

	private void ShowPrompt(bool show)
	{
		if (activated)
		{
			return;
		}
		if (show)
		{
			if (!seenDreamNailPrompt)
			{
				seenDreamNailPrompt = true;
				GameManager.instance.SetPlayerDataBool("seenDreamNailPrompt", value: true);
				PlayMakerFSM.BroadcastEvent("REMINDER DREAM NAIL");
			}
			if ((bool)audioSource && (bool)glowSound)
			{
				audioSource.PlayOneShot(glowSound);
			}
			if ((bool)wiltedParticles)
			{
				wiltedParticles.Play();
			}
			SendMessage("flashWhitePulse");
			if ((bool)glowFader)
			{
				glowFader.Fade(up: true);
			}
		}
		else if ((bool)glowFader)
		{
			glowFader.Fade(up: false);
		}
	}

	private IEnumerator CheckOrbs()
	{
		while (spawnedOrbs > 0)
		{
			yield return null;
		}
		completed = true;
		if (playerdataBool != "")
		{
			GameManager.instance.SetPlayerDataBool(playerdataBool, value: true);
		}
		GameManager.instance.SendMessage("AddToDreamPlantCList");
		yield return new WaitForSeconds(1f);
		PlayMakerFSM.BroadcastEvent("DREAM AREA DISABLE");
		if ((bool)activatedParticles)
		{
			activatedParticles.Stop(withChildren: true, ParticleSystemStopBehavior.StopEmitting);
		}
		if ((bool)completeGlowFader)
		{
			completeGlowFader.Fade(up: true);
		}
		if ((bool)audioSource && (bool)growChargeSound)
		{
			audioSource.PlayOneShot(growChargeSound);
		}
		if ((bool)completeChargeParticles)
		{
			completeChargeParticles.gameObject.SetActive(value: true);
		}
		yield return new WaitForSeconds(1f);
		if ((bool)completeChargeParticles)
		{
			completeChargeParticles.Stop(withChildren: true, ParticleSystemStopBehavior.StopEmitting);
		}
		if ((bool)audioSource && (bool)growSound)
		{
			audioSource.PlayOneShot(growSound);
		}
		if ((bool)anim)
		{
			anim.Play("Complete");
		}
		if ((bool)whiteFlash)
		{
			whiteFlash.SetActive(value: true);
		}
		if ((bool)completeGlowFader)
		{
			completeGlowFader.Fade(up: false);
		}
		if ((bool)growParticles)
		{
			growParticles.gameObject.SetActive(value: true);
		}
		GameCameras gameCameras = UnityEngine.Object.FindObjectOfType<GameCameras>();
		if ((bool)gameCameras)
		{
			gameCameras.cameraShakeFSM.SendEvent("AverageShake");
		}
		if ((bool)dreamDialogue)
		{
			dreamDialogue.SetActive(value: true);
		}
	}
}
public class DreamPlantOrb : MonoBehaviour
{
	public static DreamPlant plant;

	public BasicSpriteAnimator pickupAnim;

	private Renderer rend;

	private Vector3 initialScale;

	public AudioSource loopSource;

	[Space]
	public AudioSource soundSource;

	public AudioClip collectSound;

	public float basePitch = 0.85f;

	public float increasePitch = 0.025f;

	public float maxPitch = 1.25f;

	public float pitchReturnDelay = 3f;

	private static float currentPitch;

	private static float pitchReturnTime;

	[Space]
	public GameObject whiteFlash;

	[Space]
	public ParticleSystem pickupParticles;

	[Space]
	public ParticleSystem trailParticles;

	public ParticleSystem activateParticles;

	[Space]
	public AnimationCurve spread1Curve;

	public AnimationCurve spread2Curve;

	private bool pickedUp;

	private bool canPickup;

	private bool isActive;

	private bool didEverSetSaveState;

	private Coroutine spreadRoutine;

	private void Awake()
	{
		rend = GetComponent<Renderer>();
		PersistentBoolItem persist = GetComponent<PersistentBoolItem>();
		if (!persist)
		{
			return;
		}
		persist.OnGetSaveState += delegate(ref bool value)
		{
			value = pickedUp;
		};
		persist.OnSetSaveState += delegate(bool value)
		{
			if (!didEverSetSaveState)
			{
				pickedUp = value;
				didEverSetSaveState = true;
				persist.enabled = false;
			}
		};
		persist.PreSetup();
	}

	private void Start()
	{
		SetActive(value: false);
		initialScale = base.transform.localScale;
	}

	private void OnTriggerEnter2D(Collider2D collision)
	{
		if (!isActive || pickedUp || !canPickup || !(collision.tag == "Player"))
		{
			return;
		}
		GameManager.instance.IncrementPlayerDataInt("dreamOrbs");
		EventRegister.SendEvent("DREAM ORB COLLECT");
		if ((bool)soundSource && (bool)collectSound)
		{
			if (currentPitch <= 0f || Time.time >= pitchReturnTime)
			{
				currentPitch = basePitch;
			}
			if (currentPitch > maxPitch)
			{
				currentPitch = maxPitch;
			}
			soundSource.pitch = currentPitch;
			soundSource.PlayOneShot(collectSound);
			currentPitch += increasePitch;
			pitchReturnTime = Time.time + pitchReturnDelay;
		}
		if ((bool)pickupParticles)
		{
			pickupParticles.gameObject.SetActive(value: true);
		}
		if ((bool)whiteFlash)
		{
			whiteFlash.gameObject.SetActive(value: true);
		}
		if ((bool)pickupAnim)
		{
			pickupAnim.gameObject.SetActive(value: true);
			StartCoroutine(DisableAfterTime(pickupAnim.gameObject, pickupAnim.Length));
		}
		PersistentBoolItem component = GetComponent<PersistentBoolItem>();
		if ((bool)component)
		{
			component.enabled = true;
		}
		pickedUp = true;
		Disable();
	}

	public void Show()
	{
		if (!pickedUp)
		{
			SetActive(value: true);
			plant.AddOrbCount();
			spreadRoutine = StartCoroutine(Spread());
		}
	}

	private void SetActive(bool value)
	{
		isActive = value;
		if ((bool)rend)
		{
			rend.enabled = value;
		}
		if ((bool)loopSource)
		{
			loopSource.enabled = value;
		}
	}

	private IEnumerator Spread()
	{
		if ((bool)rend)
		{
			rend.enabled = false;
		}
		yield return null;
		transform.localScale = initialScale.MultiplyElements(new Vector3(0.5f, 0.5f, 1f));
		Vector3 position = plant.transform.position;
		position.z = UnityEngine.Random.Range(0.003f, 0.004f);
		position.x += UnityEngine.Random.Range(-1, 1);
		position.y += UnityEngine.Random.Range(-3, -2);
		Vector3 initialPos = transform.position;
		initialPos.z = 0.003f;
		transform.position = position;
		if ((bool)rend)
		{
			rend.enabled = true;
		}
		if ((bool)trailParticles)
		{
			trailParticles.gameObject.SetActive(value: true);
		}
		Vector3 vector = initialPos - transform.position;
		vector.z = 0f;
		vector.Normalize();
		vector *= UnityEngine.Random.Range(2f, 10f);
		Vector3 position2 = transform.position + vector;
		yield return StartCoroutine(TweenPosition(position2, 1f, spread1Curve));
		yield return new WaitForSeconds(UnityEngine.Random.Range(1f, 1.5f));
		yield return StartCoroutine(TweenPosition(initialPos, 1f, spread2Curve));
		transform.localScale = initialScale.MultiplyElements(new Vector3(1f, 1f, 1f));
		if ((bool)whiteFlash)
		{
			whiteFlash.gameObject.SetActive(value: true);
		}
		if ((bool)activateParticles)
		{
			activateParticles.gameObject.SetActive(value: true);
		}
		if ((bool)trailParticles)
		{
			trailParticles.Stop(withChildren: true, ParticleSystemStopBehavior.StopEmitting);
		}
		canPickup = true;
	}

	private void Disable()
	{
		pickedUp = true;
		if (plant != null)
		{
			plant.RemoveOrbCount();
		}
		SetActive(value: false);
		if (spreadRoutine != null)
		{
			StopCoroutine(spreadRoutine);
		}
	}

	private IEnumerator DisableAfterTime(GameObject obj, float time)
	{
		yield return new WaitForSeconds(time);
		obj.SetActive(value: false);
	}

	private IEnumerator TweenPosition(Vector3 position, float time, AnimationCurve curve)
	{
		Vector3 startPos = transform.position;
		for (float elapsed = 0f; elapsed <= time; elapsed += Time.deltaTime)
		{
			transform.position = Vector3.Lerp(startPos, position, curve.Evaluate(elapsed / time));
			yield return null;
		}
		transform.position = position;
	}
}
public class DreamPlatform : MonoBehaviour
{
	public TriggerEnterEvent outerCollider;

	public TriggerEnterEvent innerCollider;

	public Animator animator;

	public AudioClip activateSound;

	public AudioClip deactivateSound;

	private bool visible;

	public bool showOnEnable;

	private AudioSource audioSource;

	private void Awake()
	{
		audioSource = GetComponent<AudioSource>();
	}

	private void Start()
	{
		if (showOnEnable)
		{
			return;
		}
		if ((bool)outerCollider)
		{
			outerCollider.OnTriggerExited += delegate
			{
				Hide();
			};
		}
		if ((bool)innerCollider)
		{
			innerCollider.OnTriggerEntered += delegate
			{
				Show();
			};
		}
	}

	private void OnEnable()
	{
		if (showOnEnable)
		{
			Show();
		}
	}

	public void Show()
	{
		if (!visible)
		{
			PlayAnimation("Show");
			activateSound.PlayOnSource(audioSource, 0.85f, 1.15f);
			visible = true;
		}
	}

	public void Hide()
	{
		if (visible)
		{
			PlayAnimation("Hide");
			deactivateSound.PlayOnSource(audioSource, 0.85f, 1.15f);
			visible = false;
		}
	}

	private void PlayAnimation(string animationName)
	{
		if ((bool)animator)
		{
			animator.Play(animationName);
		}
	}
}
public class Drip : MonoBehaviour
{
	public float minWaitTime = 1f;

	public float maxWaitTime = 7f;

	public GameObject idleSprite;

	public GameObject dripSprite;

	private Animator dripAnimator;

	public Transform dripSpawnPoint;

	public float dripDelay = 0.6f;

	public GameObject dripPrefab;

	private void Awake()
	{
		dripAnimator = dripSprite.GetComponent<Animator>();
	}

	private void Start()
	{
		StartCoroutine(DripRoutine());
	}

	private IEnumerator DripRoutine()
	{
		while (true)
		{
			float seconds = UnityEngine.Random.Range(minWaitTime, maxWaitTime);
			yield return new WaitForSeconds(seconds);
			idleSprite.SetActive(value: false);
			dripSprite.SetActive(value: true);
			StartCoroutine(DropDrip());
			yield return new WaitForSeconds(dripAnimator.GetCurrentAnimatorStateInfo(0).length);
			idleSprite.SetActive(value: true);
			dripSprite.SetActive(value: false);
		}
	}

	private IEnumerator DropDrip()
	{
		yield return new WaitForSeconds(dripDelay);
		dripPrefab.Spawn(dripSpawnPoint.position).transform.SetPositionZ(0.003f);
	}
}
public class Dripper : MonoBehaviour
{
	public GameObject spatterPrefab;

	private Coroutine routine;

	private void OnEnable()
	{
		if ((bool)HeroController.instance && (bool)spatterPrefab)
		{
			routine = StartCoroutine(Behaviour());
		}
	}

	private void OnDisable()
	{
		if (routine != null)
		{
			StopCoroutine(routine);
		}
	}

	private IEnumerator Behaviour()
	{
		transform.SetParent(HeroController.instance.transform);
		transform.localPosition = new Vector3(0f, -0.5f, 0.01f);
		yield return new WaitForSeconds(0.04f);
		WaitForSeconds frequency = new WaitForSeconds(0.025f);
		float elapsed = 0f;
		while (elapsed <= 0.4f)
		{
			yield return frequency;
			elapsed += 0.025f;
			FlingUtils.SpawnAndFling(new FlingUtils.Config
			{
				Prefab = spatterPrefab,
				SpeedMin = 0f,
				SpeedMax = 1f,
				AmountMin = 1,
				AmountMax = 1,
				AngleMin = 90f,
				AngleMax = 90f,
				OriginVariationX = 0.5f,
				OriginVariationY = 0.8f
			}, transform, Vector3.zero);
		}
		routine = null;
		gameObject.Recycle();
	}
}
public class DropPlatform : MonoBehaviour
{
	public tk2dSpriteAnimator spriteAnimator;

	[Space]
	public string idleAnim = "Idle Small";

	public string dropAnim = "Drop Small";

	public string raiseAnim = "Raise Small";

	[Space]
	public AudioClip landSound;

	public AudioClip dropSound;

	public AudioClip flipUpSound;

	[Space]
	public GameObject strikeEffect;

	[Space]
	public Collider2D collider;

	private Coroutine flipRoutine;

	private AudioSource audioSource;

	private void Awake()
	{
		audioSource = GetComponent<AudioSource>();
	}

	private void Start()
	{
		Idle();
	}

	private void OnCollisionEnter2D(Collision2D collision)
	{
		if (flipRoutine == null && collision.gameObject.layer == 9 && collision.collider.bounds.min.y > collider.bounds.max.y)
		{
			flipRoutine = StartCoroutine(Flip());
		}
	}

	private void PlaySound(AudioClip clip)
	{
		if ((bool)audioSource && (bool)clip)
		{
			audioSource.PlayOneShot(clip);
		}
	}

	private void Idle()
	{
		base.transform.SetPositionZ(0.003f);
		spriteAnimator.Play(idleAnim);
		if ((bool)collider)
		{
			collider.enabled = true;
		}
	}

	private IEnumerator Flip()
	{
		PlaySound(landSound);
		if ((bool)strikeEffect)
		{
			strikeEffect.SetActive(value: true);
		}
		yield return new WaitForSeconds(0.7f);
		if ((bool)collider)
		{
			collider.enabled = false;
		}
		PlaySound(dropSound);
		yield return StartCoroutine(spriteAnimator.PlayAnimWait(dropAnim));
		transform.SetPositionZ(0.007f);
		yield return new WaitForSeconds(1.5f);
		PlaySound(flipUpSound);
		yield return StartCoroutine(spriteAnimator.PlayAnimWait(raiseAnim));
		flipRoutine = null;
		Idle();
	}

	private IEnumerator Jitter(float duration)
	{
		Transform sprite = spriteAnimator.transform;
		Vector3 initialPos = sprite.position;
		for (float elapsed = 0f; elapsed < duration; elapsed += Time.deltaTime)
		{
			sprite.position = initialPos + new Vector3(UnityEngine.Random.Range(-0.1f, 0.1f), 0f, 0f);
			yield return null;
		}
		sprite.position = initialPos;
	}
}
public class DustyPlatform : MonoBehaviour
{
	private BoxCollider2D bodyCollider;

	[SerializeField]
	private float inset;

	[SerializeField]
	private LayerMask dustIgnoredLayers;

	[SerializeField]
	private RandomAudioClipTable dustFallClips;

	[SerializeField]
	private AudioSource dustFallSourcePrefab;

	[SerializeField]
	private ParticleSystem dustPrefab;

	[SerializeField]
	private ParticleSystem rocksPrefab;

	[SerializeField]
	private float dustRateAreaFactor;

	[SerializeField]
	private float dustRateConstant;

	[SerializeField]
	private GameObject streamPrefab;

	[SerializeField]
	private Vector3 streamOffset;

	[SerializeField]
	private float streamEmissionMin;

	[SerializeField]
	private float streamEmissionMax;

	[SerializeField]
	private float rocksChance;

	[SerializeField]
	private float rocksDelay;

	[SerializeField]
	private Transform rockPrefab;

	[SerializeField]
	private int rockCountMin;

	[SerializeField]
	private int rockCountMax;

	private float rocksDelayTimer;

	[SerializeField]
	private float cooldownDuration;

	private float cooldownTimer;

	private bool isRunning;

	protected void Reset()
	{
		inset = 0.3f;
		dustIgnoredLayers.value = 327680;
		dustRateAreaFactor = 10f;
		dustRateConstant = 5f;
		streamOffset = new Vector3(0f, 0.1f, 0.01f);
		streamEmissionMin = 3f;
		streamEmissionMax = 10f;
		rocksChance = 0.5f;
		rocksDelay = 0.25f;
		rockCountMin = 1;
		rockCountMax = 3;
		cooldownDuration = 0.45f;
	}

	protected void Awake()
	{
		bodyCollider = GetComponent<BoxCollider2D>();
	}

	protected void Update()
	{
		if (!isRunning)
		{
			return;
		}
		bool flag = true;
		if (rocksDelayTimer > 0f)
		{
			rocksDelayTimer -= Time.deltaTime;
			if (rocksDelayTimer <= 0f)
			{
				SpawnRocks();
			}
			else
			{
				flag = false;
			}
		}
		if (cooldownTimer > 0f)
		{
			cooldownTimer -= Time.deltaTime;
			if (cooldownTimer > 0f)
			{
				flag = false;
			}
		}
		if (flag)
		{
			isRunning = false;
		}
	}

	protected void OnCollisionEnter2D(Collision2D collision)
	{
		if (isRunning)
		{
			return;
		}
		int layer = collision.collider.gameObject.layer;
		if ((dustIgnoredLayers.value & (1 << layer)) != 0)
		{
			return;
		}
		Vector2 vector = Vector2.zero;
		if (collision.contacts.Length != 0)
		{
			vector = collision.contacts[0].normal;
		}
		if (!(Mathf.Abs(vector.y - -1f) > 0.1f))
		{
			dustFallClips.SpawnAndPlayOneShot(dustFallSourcePrefab, base.transform.position);
			Vector2 vector2 = bodyCollider.size - new Vector2(inset, inset);
			Vector3 position = base.transform.position;
			position.z = -0.1f;
			if (dustPrefab != null)
			{
				ParticleSystem particleSystem = dustPrefab.Spawn(position);
				SetRateOverTime(particleSystem, vector2.x * vector2.y * dustRateAreaFactor + dustRateConstant);
				particleSystem.transform.localScale = new Vector3(vector2.x, vector2.y, particleSystem.transform.localScale.z);
			}
			if (streamPrefab != null)
			{
				GameObject obj = streamPrefab.Spawn(position + new Vector3(0f, (0f - bodyCollider.size.y) * 0.5f, 0.01f) + streamOffset);
				obj.GetComponentInChildren<ParticleSystem>();
				Vector3 localScale = obj.transform.localScale;
				localScale.x = vector2.x;
				obj.transform.localScale = localScale;
			}
			if (UnityEngine.Random.value < rocksChance && rocksPrefab != null)
			{
				ParticleSystem particleSystem2 = rocksPrefab.Spawn(position);
				particleSystem2.transform.position = new Vector3(particleSystem2.transform.position.x, particleSystem2.transform.position.y, 0.003f);
				particleSystem2.transform.localScale = new Vector3(vector2.x, vector2.y, particleSystem2.transform.localScale.z);
			}
			cooldownTimer = cooldownDuration;
			isRunning = true;
		}
	}

	private void SpawnRocks()
	{
	}

	private void SetRateOverTime(ParticleSystem ps, float rateOverTime)
	{
		ParticleSystem.EmissionModule emission = ps.emission;
		emission.rateOverTime = rateOverTime;
	}
}
