[RequireComponent(typeof(Collider2D))]
public class GlobControl : MonoBehaviour
{
	public Renderer rend;

	[Space]
	public float minScale = 0.6f;

	public float maxScale = 1.6f;

	[Space]
	public string landAnim = "Glob Land";

	public string wobbleAnim = "Glob Wobble";

	public string breakAnim = "Glob Break";

	[Space]
	public AudioSource audioPlayerPrefab;

	public AudioEvent breakSound;

	public Color bloodColorOverride = new Color(1f, 0.537f, 0.188f);

	[Space]
	public GameObject splatChild;

	[Space]
	public Collider2D groundCollider;

	private bool landed;

	private bool broken;

	private tk2dSpriteAnimator anim;

	private void Awake()
	{
		anim = GetComponent<tk2dSpriteAnimator>();
	}

	private void OnEnable()
	{
		float num = UnityEngine.Random.Range(minScale, maxScale);
		base.transform.localScale = new Vector3(num, num, 1f);
		if ((bool)splatChild)
		{
			splatChild.SetActive(value: false);
		}
		landed = false;
		broken = false;
	}

	private void Start()
	{
		CollisionEnterEvent collision = GetComponent<CollisionEnterEvent>();
		if ((bool)collision)
		{
			collision.OnCollisionEnteredDirectional += delegate(CollisionEnterEvent.Direction direction, Collision2D col)
			{
				if (!landed)
				{
					if (direction == CollisionEnterEvent.Direction.Bottom)
					{
						landed = true;
						collision.doCollisionStay = false;
						if (CheckForGround())
						{
							anim.Play(landAnim);
						}
						else
						{
							StartCoroutine(Break());
						}
					}
					else
					{
						collision.doCollisionStay = true;
					}
				}
			};
		}
		TriggerEnterEvent componentInChildren = GetComponentInChildren<TriggerEnterEvent>();
		if (!componentInChildren)
		{
			return;
		}
		componentInChildren.OnTriggerEntered += delegate(Collider2D col, GameObject sender)
		{
			if (landed && !broken && col.gameObject.layer == 11)
			{
				anim.Play(wobbleAnim);
			}
		};
	}

	private void OnTriggerEnter2D(Collider2D col)
	{
		if (landed && !broken)
		{
			if (col.tag == "Nail Attack")
			{
				StartCoroutine(Break());
			}
			else if (col.tag == "HeroBox")
			{
				anim.Play(wobbleAnim);
			}
		}
	}

	private IEnumerator Break()
	{
		broken = true;
		breakSound.SpawnAndPlayOneShot(audioPlayerPrefab, transform.position);
		GlobalPrefabDefaults.Instance.SpawnBlood(transform.position, 4, 5, 5f, 20f, 80f, 100f, bloodColorOverride);
		if ((bool)splatChild)
		{
			splatChild.SetActive(value: true);
		}
		yield return anim.PlayAnimWait(breakAnim);
		if ((bool)rend)
		{
			rend.enabled = false;
		}
	}

	private bool CheckForGround()
	{
		if (!groundCollider)
		{
			return true;
		}
		Vector2 origin = groundCollider.bounds.min;
		Vector2 origin2 = groundCollider.bounds.max;
		float num = origin2.y - origin.y;
		origin.y = origin2.y;
		origin.x += 0.1f;
		origin2.x -= 0.1f;
		RaycastHit2D raycastHit2D = Physics2D.Raycast(origin, Vector2.down, num + 0.25f, 256);
		RaycastHit2D raycastHit2D2 = Physics2D.Raycast(origin2, Vector2.down, num + 0.25f, 256);
		if (raycastHit2D.collider != null)
		{
			return raycastHit2D2.collider != null;
		}
		return false;
	}
}
public class GlowResponse : MonoBehaviour
{
	[HideInInspector]
	[SerializeField]
	private SpriteRenderer fadeSprite;

	public List<SpriteRenderer> FadeSprites = new List<SpriteRenderer>();

	public float fadeTime = 0.5f;

	public ParticleSystem particles;

	public Light light;

	private float lightStart;

	public AudioSource audioPlayerPrefab;

	public AudioEventRandom soundEffect;

	private Dictionary<SpriteRenderer, Coroutine> fadeRoutines = new Dictionary<SpriteRenderer, Coroutine>();

	private void OnValidate()
	{
		HandleUpgrade();
	}

	private void Awake()
	{
		HandleUpgrade();
	}

	private void HandleUpgrade()
	{
		if ((bool)fadeSprite)
		{
			FadeSprites.Add(fadeSprite);
			fadeSprite = null;
		}
	}

	private void Start()
	{
		foreach (SpriteRenderer fadeSprite in FadeSprites)
		{
			if ((bool)fadeSprite)
			{
				Color color = fadeSprite.color;
				color.a = 0f;
				fadeSprite.color = color;
			}
		}
		if ((bool)light)
		{
			lightStart = light.intensity;
			light.intensity = 0f;
			light.enabled = false;
		}
	}

	private void OnTriggerEnter2D(Collider2D collision)
	{
		if ((bool)particles)
		{
			particles.Play();
		}
		Vector3 position = base.transform.position;
		position.z = 0f;
		soundEffect.SpawnAndPlayOneShot(audioPlayerPrefab, position);
		FadeTo(1f);
	}

	private void OnTriggerExit2D(Collider2D collision)
	{
		if ((bool)particles)
		{
			particles.Stop(withChildren: true, ParticleSystemStopBehavior.StopEmitting);
		}
		FadeTo(0f);
	}

	private void FadeTo(float alpha)
	{
		foreach (SpriteRenderer fadeSprite in FadeSprites)
		{
			if (fadeRoutines.ContainsKey(fadeSprite) && fadeRoutines[fadeSprite] != null)
			{
				StopCoroutine(fadeRoutines[fadeSprite]);
			}
			if (base.gameObject.activeInHierarchy)
			{
				fadeRoutines[fadeSprite] = StartCoroutine(Fade(alpha, fadeSprite));
			}
		}
	}

	private IEnumerator Fade(float toAlpha, SpriteRenderer sprite)
	{
		float elapsed = 0f;
		Color initialColor = (sprite ? sprite.color : Color.white);
		Color currentColor = initialColor;
		bool fadeUp = toAlpha > 0.1f;
		float startIntensity = (light ? light.intensity : 0f);
		float toIntensity = (fadeUp ? lightStart : 0f);
		if ((bool)light & fadeUp)
		{
			light.enabled = true;
		}
		for (; elapsed < fadeTime; elapsed += Time.deltaTime)
		{
			if ((bool)sprite)
			{
				currentColor.a = Mathf.Lerp(initialColor.a, toAlpha, elapsed / fadeTime);
				sprite.color = currentColor;
			}
			if ((bool)light)
			{
				light.intensity = Mathf.Lerp(startIntensity, toIntensity, elapsed / fadeTime);
			}
			yield return null;
		}
		if ((bool)sprite)
		{
			currentColor.a = toAlpha;
			sprite.color = currentColor;
		}
		if ((bool)light && !fadeUp)
		{
			light.enabled = false;
		}
	}

	public void FadeEnd()
	{
		FadeTo(0f);
		if ((bool)particles)
		{
			particles.Stop(withChildren: true, ParticleSystemStopBehavior.StopEmitting);
		}
		CircleCollider2D component = GetComponent<CircleCollider2D>();
		if (component != null)
		{
			component.enabled = false;
		}
	}
}
[ActionCategory("Hollow Knight")]
public class GlowResponseEnd : FsmStateAction
{
	[UIHint(UIHint.Variable)]
	public FsmOwnerDefault target;

	public override void Reset()
	{
		target = new FsmOwnerDefault();
	}

	public override void OnEnter()
	{
		GameObject gameObject = ((target.OwnerOption == OwnerDefaultOption.UseOwner) ? base.Owner : target.GameObject.Value);
		if (gameObject != null)
		{
			GlowResponse component = gameObject.GetComponent<GlowResponse>();
			if (component != null)
			{
				component.FadeEnd();
			}
		}
		Finish();
	}
}
