	private RandomAudioClipTable cutAudioClipTable;

	private static readonly int IdleStateId = Animator.StringToHash("Idle");

	private static readonly int PushStateId = Animator.StringToHash("Push");

	private static readonly int DeadStateId = Animator.StringToHash("Dead");

	private bool isInfected;

	private bool isCut;

	private float childParticleSystemTimer;

	private static List<Grass> grasses;

	[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
	private static void Init()
	{
		grasses = new List<Grass>();
	}

	protected void Reset()
	{
		inertBackgroundThreshold = 1.8f;
		inertForegroundThreshold = -1.8f;
		infectedColor = new Color32(byte.MaxValue, 140, 54, byte.MaxValue);
		slashImpactRotationMin = 340f;
		slashImpactRotationMax = 380f;
		slashImpactScale = 0.6f;
		preventPushAnimation = false;
		childParticleSystemDuration = 5f;
	}

	protected void Awake()
	{
		animator = GetComponent<Animator>();
		bodyCollider = GetComponent<Collider2D>();
		audioSource = GetComponent<AudioSource>();
		grasses.Add(this);
	}

	protected void OnDestroy()
	{
		grasses.Remove(this);
	}

	protected void Start()
	{
		float z = base.transform.position.z;
		if (z > inertBackgroundThreshold || z < inertForegroundThreshold)
		{
			base.enabled = false;
			return;
		}
		isInfected = isInfectable && GameObject.FindGameObjectWithTag("Infected Flag") != null;
		if (isInfected)
		{
			FSMActionReplacements.SetMaterialColor(this, infectedColor);
		}
		animator.Play(IdleStateId, 0, UnityEngine.Random.Range(0f, 1f));
	}

	protected void OnTriggerEnter2D(Collider2D other)
	{
		if (!preventPushAnimation)
		{
			Push(isAllGrass: false);
		}
	}

	public void Push(bool isAllGrass)
	{
		if (!isCut)
		{
			if (!isAllGrass)
			{
				pushAudioClipTable.PlayOneShot(audioSource);
			}
			animator.Play(PushStateId, 0, 0f);
		}
	}

	public static void PushAll()
	{
		if (grasses != null)
		{
			for (int i = 0; i < grasses.Count; i++)
			{
				grasses[i].Push(isAllGrass: true);
			}
		}
	}

	public void Hit(HitInstance damageInstance)
	{
		if (damageInstance.DamageDealt <= 0 || isCut)
		{
			return;
		}
		isCut = true;
		bodyCollider.enabled = false;
		FSMActionReplacements.Directions directions = FSMActionReplacements.CheckDirectionWithBrokenBehaviour(0f);
		GameObject obj = slashImpactPrefab.Spawn(base.transform.position, Quaternion.Euler(0f, 0f, UnityEngine.Random.Range(slashImpactRotationMin, slashImpactRotationMax)));
		obj.transform.localScale = new Vector3((directions == FSMActionReplacements.Directions.Left) ? (0f - slashImpactScale) : slashImpactScale, slashImpactScale, 1f);
		Vector3 localPosition = obj.transform.localPosition;
		localPosition.z = 0f;
		obj.transform.localPosition = localPosition;
		Quaternion rotation = Quaternion.Euler(-90f, -90f, -0.01f);
		if (isInfected)
		{
			if (infectedCutPrefab0 != null)
			{
				infectedCutPrefab0.Spawn(base.transform.position, rotation);
			}
			if (infectedCutPrefab1 != null)
			{
				infectedCutPrefab1.Spawn(base.transform.position, rotation);
			}
		}
		else
		{
			if (cutPrefab0 != null)
			{
				cutPrefab0.Spawn(base.transform.position, rotation);
			}
			if (cutPrefab1 != null)
			{
				cutPrefab1.Spawn(base.transform.position, rotation);
			}
		}
		cutAudioClipTable.PlayOneShot(audioSource);
		animator.Play(DeadStateId, 0, 0f);
		if (!isInfected && childParticleSystem != null)
		{
			childParticleSystem.Play();
			childParticleSystemTimer = childParticleSystemDuration;
			base.enabled = true;
		}
		else
		{
			base.enabled = false;
		}
	}

	protected void Update()
	{
		childParticleSystemTimer -= Time.deltaTime;
		if (childParticleSystemTimer <= 0f)
		{
			if (childParticleSystem != null)
			{
				childParticleSystem.Stop();
			}
			base.enabled = false;
		}
	}
}
public static class FSMActionReplacements
{
	public enum Directions
	{
		Right,
		Up,
		Left,
		Down,
		Unknown
	}

	public static void SetMaterialColor(Component me, Color color)
	{
		Renderer component = me.GetComponent<Renderer>();
		if (component != null)
		{
			component.material.color = color;
		}
	}

	public static Directions CheckDirectionWithBrokenBehaviour(float angle)
	{
		if (angle < 45f)
		{
			return Directions.Right;
		}
		if (angle < 135f)
		{
			return Directions.Up;
		}
		if (angle < 225f)
		{
			return Directions.Left;
		}
		if (angle < 360f)
		{
			return Directions.Down;
		}
		return Directions.Unknown;
	}
}
public class GrubBGControl : MonoBehaviour
{
	public int grubNumber;

	[Space]
	public TriggerEnterEvent waveRegion;

	[Space]
	public AudioSource audioSourcePrefab;

	public AudioEventRandom idleSounds;

	public AudioEventRandom waveSounds;

	private Coroutine idleRoutine;

	private Coroutine waveRoutine;

	private tk2dSpriteAnimator anim;

	private void Awake()
	{
		anim = GetComponent<tk2dSpriteAnimator>();
	}

	private void Start()
	{
		int playerDataInt = GameManager.instance.GetPlayerDataInt("grubsCollected");
		if (grubNumber > playerDataInt)
		{
			base.gameObject.SetActive(value: false);
			return;
		}
		idleRoutine = StartCoroutine(Idle());
		if (!waveRegion)
		{
			return;
		}
		waveRegion.OnTriggerEntered += delegate
		{
			if (waveRoutine == null)
			{
				waveRoutine = StartCoroutine(Wave());
			}
		};
	}

	private IEnumerator Idle()
	{
		anim.Play("Home Bounce");
		while (true)
		{
			yield return new WaitForSeconds(UnityEngine.Random.Range(3f, 10f));
			idleSounds.SpawnAndPlayOneShot(audioSourcePrefab, transform.position);
		}
	}

	private IEnumerator Wave()
	{
		if (idleRoutine != null)
		{
			StopCoroutine(idleRoutine);
		}
		Vector3 position = transform.position;
		position.z = 0f;
		waveSounds.SpawnAndPlayOneShot(audioSourcePrefab, position);
		yield return StartCoroutine(anim.PlayAnimWait("Home Wave"));
		waveRoutine = null;
		idleRoutine = StartCoroutine(Idle());
	}
}
public class HealthCocoon : MonoBehaviour
{
	[Serializable]
	public class FlingPrefab
	{
		public GameObject prefab;

		private List<GameObject> pool = new List<GameObject>();

		public int minAmount;

		public int maxAmount;

		public Vector2 originVariation = new Vector2(0.5f, 0.5f);

		public float minSpeed;

		public float maxSpeed;

		public float minAngle;

		public float maxAngle;

		public void SetupPool(Transform parent)
		{
			if ((bool)prefab)
			{
				pool.Capacity = maxAmount;
				for (int i = pool.Count; i < maxAmount; i++)
				{
					GameObject gameObject = UnityEngine.Object.Instantiate(prefab, parent);
					gameObject.transform.localPosition = Vector3.zero;
					gameObject.SetActive(value: false);
					pool.Add(gameObject);
				}
			}
		}

		public GameObject Spawn()
		{
			foreach (GameObject item in pool)
			{
				if (!item.activeSelf)
				{
					item.SetActive(value: true);
					return item;
				}
			}
			return null;
		}
	}

	[Header("Behaviour")]
	public GameObject[] slashEffects;

	public GameObject[] spellEffects;

	public Vector3 effectOrigin = new Vector3(0f, 0.8f, 0f);

	[Space]
	public FlingPrefab[] flingPrefabs;

	[Space]
	public GameObject[] enableChildren;

	public GameObject[] disableChildren;

	public Collider2D[] disableColliders;

	[Space]
	public Rigidbody2D cap;

	public float capHitForce = 10f;

	[Space]
	public AudioClip deathSound;

	private bool activated;

	[Header("Animation")]
	public string idleAnimation = "Cocoon Idle";

	public string sweatAnimation = "Cocoon Sweat";

	public AudioClip moveSound;

	public float waitMin = 2f;

	public float waitMax = 6f;

	private Coroutine animRoutine;

	private AudioSource source;

	private tk2dSpriteAnimator animator;

	private void Awake()
	{
		source = GetComponent<AudioSource>();
		animator = GetComponent<tk2dSpriteAnimator>();
		PersistentBoolItem component = GetComponent<PersistentBoolItem>();
		if (!component)
		{
			return;
		}
		component.OnGetSaveState += delegate(ref bool value)
		{
			value = activated;
		};
		component.OnSetSaveState += delegate(bool value)
		{
			activated = value;
			if (activated)
			{
				SetBroken();
			}
		};
	}

	private void Start()
	{
		animRoutine = StartCoroutine(Animate());
		FlingPrefab[] array = flingPrefabs;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].SetupPool(base.transform);
		}
	}

	private void PlaySound(AudioClip clip)
	{
		if ((bool)source && (bool)clip)
		{
			source.PlayOneShot(clip);
		}
	}

	private IEnumerator Animate()
	{
		while (true)
		{
			yield return new WaitForSeconds(UnityEngine.Random.Range(waitMin, waitMax));
			PlaySound(moveSound);
			if ((bool)animator)
			{
				tk2dSpriteAnimationClip clipByName = animator.GetClipByName(sweatAnimation);
				animator.Play(clipByName);
				yield return new WaitForSeconds((float)clipByName.frames.Length / clipByName.fps);
				animator.Play(idleAnimation);
			}
		}
	}

	private void OnTriggerEnter2D(Collider2D collision)
	{
		if (activated)
		{
			return;
		}
		bool flag = false;
		if (collision.tag == "Nail Attack")
		{
			flag = true;
			float value = PlayMakerFSM.FindFsmOnGameObject(collision.gameObject, "damages_enemy").FsmVariables.FindFsmFloat("direction").Value;
			float z = 0f;
			Vector2 vector = new Vector2(1.5f, 1.5f);
			if (value < 45f)
			{
				z = UnityEngine.Random.Range(340, 380);
			}
			else if (value < 135f)
			{
				z = UnityEngine.Random.Range(340, 380);
			}
			else if (value < 225f)
			{
				vector.x *= -1f;
				z = UnityEngine.Random.Range(70, 110);
			}
			else if (value < 360f)
			{
				z = UnityEngine.Random.Range(250, 290);
			}
			GameObject[] array = slashEffects;
			for (int i = 0; i < array.Length; i++)
			{
				GameObject obj = array[i].Spawn(base.transform.position + effectOrigin);
				obj.transform.eulerAngles = new Vector3(0f, 0f, z);
				obj.transform.localScale = vector;
			}
		}
		if (collision.tag == "Hero Spell")
		{
			flag = true;
			GameObject[] array = spellEffects;
			for (int i = 0; i < array.Length; i++)
			{
				GameObject obj2 = array[i].Spawn(base.transform.position + effectOrigin);
				Vector3 position = obj2.transform.position;
				position.z = 0.0031f;
				obj2.transform.position = position;
			}
		}
		if (flag)
		{
			activated = true;
			GameObject[] array = enableChildren;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].SetActive(value: true);
			}
			if ((bool)cap)
			{
				cap.gameObject.SetActive(value: true);
				Vector3 vector2 = base.transform.position - collision.transform.position;
				vector2.Normalize();
				cap.AddForce(capHitForce * vector2, ForceMode2D.Impulse);
			}
			FlingPrefab[] array2 = flingPrefabs;
			foreach (FlingPrefab fling in array2)
			{
				FlingObjects(fling);
			}
			PlaySound(deathSound);
			SetBroken();
			GameManager.instance.AddToCocoonList();
			GameCameras gameCameras = UnityEngine.Object.FindObjectOfType<GameCameras>();
			if ((bool)gameCameras)
			{
				gameCameras.cameraShakeFSM.SendEvent("EnemyKillShake");
			}
		}
	}

	private void SetBroken()
	{
		StopCoroutine(animRoutine);
		GetComponent<MeshRenderer>().enabled = false;
		GameObject[] array = disableChildren;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].SetActive(value: false);
		}
		Collider2D[] array2 = disableColliders;
		for (int i = 0; i < array2.Length; i++)
		{
			array2[i].enabled = false;
		}
	}

	private void FlingObjects(FlingPrefab fling)
	{
		if (!fling.prefab)
		{
			return;
		}
		int num = UnityEngine.Random.Range(fling.minAmount, fling.maxAmount + 1);
		Vector2 velocity = default(Vector2);
		for (int i = 1; i <= num; i++)
		{
			GameObject obj = fling.Spawn();
			obj.transform.position += new Vector3(fling.originVariation.x * UnityEngine.Random.Range(-1f, 1f), fling.originVariation.y * UnityEngine.Random.Range(-1f, 1f));
			float num2 = UnityEngine.Random.Range(fling.minSpeed, fling.maxSpeed);
			float num3 = UnityEngine.Random.Range(fling.minAngle, fling.maxAngle);
			float x = num2 * Mathf.Cos(num3 * ((float)Math.PI / 180f));
			float y = num2 * Mathf.Sin(num3 * ((float)Math.PI / 180f));
			velocity.x = x;
			velocity.y = y;
			Rigidbody2D component = obj.GetComponent<Rigidbody2D>();
			if ((bool)component)
			{
				component.velocity = velocity;
			}
		}
	}

	public void SetScuttlerAmount(int amount)
	{
		FlingPrefab[] array = flingPrefabs;
		foreach (FlingPrefab flingPrefab in array)
		{
			if (flingPrefab.prefab.name == "Health Scuttler")
			{
				flingPrefab.minAmount = (flingPrefab.maxAmount = amount);
				flingPrefab.SetupPool(base.transform);
				break;
			}
		}
	}
}
[RequireComponent(typeof(Rigidbody2D))]
public class IdleBuzzing : MonoBehaviour
{
	private Rigidbody2D body;

	[SerializeField]
	private float waitMin;

	[SerializeField]
	private float waitMax;

	[SerializeField]
	private float speedMax;

	[SerializeField]
	private float accelerationMax;

	[SerializeField]
	private float roamingRange;

	[SerializeField]
	private float dampener;

	private Vector2 start2D;

	private Vector2 acceleration2D;

	private float waitTimer;

	private const float InspectorAccelerationConstant = 2000f;

	protected void Reset()
	{
		waitMin = 0.75f;
		waitMax = 1f;
		speedMax = 1.75f;
		accelerationMax = 15f;
		roamingRange = 1f;
		dampener = 1.125f;
	}

	protected void Awake()
	{
		body = GetComponent<Rigidbody2D>();
	}

	protected void Start()
	{
		start2D = body.position;
		acceleration2D = Vector2.zero;
		Buzz(0f);
	}

	protected void FixedUpdate()
	{
		float deltaTime = Time.deltaTime;
		Buzz(deltaTime);
	}

	private void Buzz(float deltaTime)
	{
		Vector2 position = body.position;
		Vector2 velocity = body.velocity;
		bool flag;
		if (waitTimer <= 0f)
		{
			flag = true;
			waitTimer = UnityEngine.Random.Range(waitMin, waitMax);
		}
		else
		{
			waitTimer -= deltaTime;
			flag = false;
		}
		for (int i = 0; i < 2; i++)
		{
			float num = velocity[i];
			float num2 = start2D[i];
			float num3 = position[i] - num2;
			float num4 = acceleration2D[i];
			if (flag)
			{
				num4 = ((!(Mathf.Abs(num3) > roamingRange)) ? UnityEngine.Random.Range(0f - accelerationMax, accelerationMax) : ((0f - Mathf.Sign(num3)) * accelerationMax));
				num4 /= 2000f;
			}
			else if (Mathf.Abs(num3) > roamingRange && num3 > 0f == num > 0f)
			{
				num4 = accelerationMax * (0f - Mathf.Sign(num3)) / 2000f;
				num /= dampener;
				waitTimer = UnityEngine.Random.Range(waitMin, waitMax);
			}
			num += num4;
			num = Mathf.Clamp(num, 0f - speedMax, speedMax);
			velocity[i] = num;
			acceleration2D[i] = num4;
		}
		body.velocity = velocity;
	}
}
[RequireComponent(typeof(Collider2D))]
public class IgnoreHeroCollision : MonoBehaviour
{
	private void Start()
	{
		if (!HeroController.instance)
		{
			return;
		}
		if (HeroController.instance.isHeroInPosition)
		{
			Ignore();
			return;
		}
		HeroController.HeroInPosition temp = null;
		temp = delegate
		{
			Ignore();
			HeroController.instance.heroInPosition -= temp;
			temp = null;
		};
		HeroController.instance.heroInPosition += temp;
	}

	private void Ignore()
	{
		Collider2D component = GetComponent<Collider2D>();
		Collider2D[] components = HeroController.instance.GetComponents<Collider2D>();
		foreach (Collider2D collider in components)
		{
			Physics2D.IgnoreCollision(component, collider);
		}
	}

	private void OnCollisionEnter2D(Collision2D collision)
	{
		if (collision.gameObject.tag == "Player")
		{
			Physics2D.IgnoreCollision(collision.collider, collision.otherCollider);
		}
	}
}
public class JellyEgg : MonoBehaviour
{
	public bool bomb;

	public GameObject explosionObject;

	public ParticleSystem popEffect;

	public GameObject strikeEffect;

	public MeshRenderer meshRenderer;

	public AudioSource audioSource;

	public VibrationData popVibration;

	public CircleCollider2D circleCollider;

	public GameObject falseShiny;

	public GameObject shinyItem;

	private void OnTriggerEnter2D(Collider2D otherCollider)
	{
		if (otherCollider.gameObject.tag == "Nail Attack" || otherCollider.gameObject.tag == "Hero Spell" || otherCollider.gameObject.tag == "HeroBox")
		{
			Burst();
		}
	}

	private void Burst()
	{
		meshRenderer.enabled = false;
		popEffect.Play();
		audioSource.Play();
		circleCollider.enabled = false;
		if (bomb)
		{
			explosionObject.Spawn(base.transform.position, base.transform.localRotation);
			return;
		}
		float num = UnityEngine.Random.Range(1f, 1.5f);
		strikeEffect.transform.localScale = new Vector3(num, num, num);
		strikeEffect.transform.localEulerAngles = new Vector3(strikeEffect.transform.localEulerAngles.x, strikeEffect.transform.localEulerAngles.y, UnityEngine.Random.Range(0f, 360f));
		strikeEffect.SetActive(value: true);
		if (falseShiny != null)
		{
			falseShiny.SetActive(value: false);
		}
		if (shinyItem != null)
		{
			shinyItem.SetActive(value: true);
		}
		VibrationManager.PlayVibrationClipOneShot(popVibration);
	}
}
public class LiftPlatform : MonoBehaviour
{
	public GameObject part1;

	public GameObject part2;

	public ParticleSystem dustParticle;

	public AudioSource audioSource;

	private float part1_start_y;

	private float part2_start_y;

	private int state;

	private float timer;

	private void Start()
	{
		part1_start_y = part1.transform.position.y;
		part2_start_y = part2.transform.position.y;
	}

	private void Update()
	{
		if (state == 1)
		{
			if (timer < 0.12f)
			{
				part1.transform.position = new Vector3(part1.transform.position.x, part1_start_y - timer * 0.75f, part1.transform.position.z);
				part2.transform.position = new Vector3(part2.transform.position.x, part2_start_y - timer * 0.75f, part2.transform.position.z);
				timer += Time.deltaTime;
			}
			else
			{
				part1.transform.position = new Vector3(part1.transform.position.x, part1_start_y - 0.09f, part1.transform.position.z);
				part2.transform.position = new Vector3(part2.transform.position.x, part2_start_y - 0.09f, part2.transform.position.z);
				state = 2;
				timer = 0.12f;
			}
		}
		if (state == 2)
		{
			if (timer > 0f)
			{
				part1.transform.position = new Vector3(part1.transform.position.x, part1_start_y - timer * 0.75f, part1.transform.position.z);
				part2.transform.position = new Vector3(part2.transform.position.x, part2_start_y - timer * 0.75f, part2.transform.position.z);
				timer -= Time.deltaTime;
			}
			else
			{
				part1.transform.position = new Vector3(part1.transform.position.x, part1_start_y, part1.transform.position.z);
				part2.transform.position = new Vector3(part2.transform.position.x, part2_start_y, part2.transform.position.z);
				state = 0;
			}
		}
	}

	private void OnCollisionEnter2D(Collision2D collision)
	{
		if (state == 0 && collision.collider.gameObject.layer != 16 && collision.collider.gameObject.layer != 18 && collision.GetSafeContact().Normal.y < 0.1f)
		{
			audioSource.pitch = UnityEngine.Random.Range(0.85f, 1.15f);
			audioSource.Play();
			dustParticle.Play();
			state = 1;
			timer = 0f;
		}
	}
}
public class LookAnimNPC : MonoBehaviour
{
	private enum AnimState
	{
		Left,
		TurningLeft,
		Right,
		TurningRight
	}

	public string leftAnim;

	public string rightAnim;

	public bool defaultLeft = true;

	public float centreOffset;

	[UnityEngine.Tooltip("Limit's behaviour if further than this from the hero's Z. Leave 0 for no limit.")]
	public float limitZ;

	public TriggerEnterEvent enterDetector;

	public TriggerEnterEvent exitDetector;

	private Transform target;

	private AnimState state;

	private float turnFinishTime;

	private bool isTurning;

	private tk2dSpriteAnimator anim;

	private void Awake()
	{
		anim = GetComponent<tk2dSpriteAnimator>();
		if (!anim)
		{
			UnityEngine.Debug.LogError($"LookAnimNPC on {base.gameObject.name} could not find a tk2dSpriteAnimator!", this);
		}
	}

	private void Start()
	{
		if (limitZ > 0f && Mathf.Abs(base.transform.position.z - 0.004f) > limitZ)
		{
			UnityEngine.Object.Destroy(this);
			return;
		}
		state = ((!defaultLeft) ? AnimState.Right : AnimState.Left);
		if ((bool)anim)
		{
			tk2dSpriteAnimationClip clipByName = anim.GetClipByName(defaultLeft ? leftAnim : rightAnim);
			anim.PlayFromFrame(clipByName, clipByName.frames.Length - 1);
		}
		if ((bool)enterDetector)
		{
			enterDetector.OnTriggerEntered += delegate(Collider2D collider, GameObject sender)
			{
				target = collider.transform;
			};
		}
		if ((bool)exitDetector)
		{
			exitDetector.OnTriggerExited += delegate
			{
				target = null;
			};
		}
	}

	private void OnDrawGizmosSelected()
	{
		Gizmos.DrawWireSphere(base.transform.position + new Vector3(centreOffset, 0f, 0f), 0.25f);
	}

	private void Update()
	{
		if (!anim)
		{
			return;
		}
		if (!isTurning)
		{
			bool flag = (target ? ((target.transform.position.x - (base.transform.position.x + centreOffset)) * base.transform.localScale.x < 0f) : defaultLeft);
			switch (state)
			{
			case AnimState.Left:
				if (!flag)
				{
					float num2 = anim.PlayAnimGetTime(rightAnim);
					state = AnimState.TurningRight;
					isTurning = true;
					turnFinishTime = Time.time + num2;
				}
				break;
			case AnimState.Right:
				if (flag)
				{
					float num = anim.PlayAnimGetTime(leftAnim);
					state = AnimState.TurningLeft;
					isTurning = true;
					turnFinishTime = Time.time + num;
				}
				break;
			}
		}
		if (isTurning && Time.time >= turnFinishTime)
		{
			isTurning = false;
			switch (state)
			{
			case AnimState.TurningLeft:
				state = AnimState.Left;
				break;
			case AnimState.TurningRight:
				state = AnimState.Right;
				break;
			}
		}
	}
}
public class MaskByYPos : MonoBehaviour
{
	public SpriteRenderer spriteRenderer;

	public float yPos;

	public bool maskIfAboveY;

	public bool maskIfBelowY;

	private void OnEnable()
	{
		if (spriteRenderer == null)
		{
			spriteRenderer = GetComponent<SpriteRenderer>();
		}
	}

	private void Update()
	{
		float y = base.transform.position.y;
		if (maskIfAboveY)
		{
			if (y < yPos)
			{
				if (!spriteRenderer.enabled)
				{
					spriteRenderer.enabled = true;
				}
			}
			else if (spriteRenderer.enabled)
			{
				spriteRenderer.enabled = false;
			}
		}
		if (!maskIfBelowY)
		{
			return;
		}
		if (y > yPos)
		{
			if (!spriteRenderer.enabled)
			{
				spriteRenderer.enabled = true;
			}
		}
		else if (spriteRenderer.enabled)
		{
			spriteRenderer.enabled = false;
		}
	}
}
