public class SpatterHoney : MonoBehaviour
{
	public Rigidbody2D rb2d;

	public CircleCollider2D circleCollider;

	public SpriteRenderer spriteRenderer;

	private float stretchFactor = 1.4f;

	private float stretchMinX = 0.7f;

	private float stretchMaxY = 1.75f;

	private float scaleModifier;

	public float scaleModifierMin = 0.7f;

	public float scaleModifierMax = 1.3f;

	private float state;

	private float idleTimer;

	private void Start()
	{
		scaleModifier = UnityEngine.Random.Range(scaleModifierMin, scaleModifierMax);
	}

	private void OnEnable()
	{
		rb2d.isKinematic = false;
		circleCollider.enabled = true;
		idleTimer = 0f;
	}

	private void Update()
	{
		FaceAngle();
		ProjectileSquash();
		idleTimer += Time.deltaTime;
		if (idleTimer > 3f)
		{
			Impact();
		}
	}

	private void Impact()
	{
		if (idleTimer > 0.1f)
		{
			base.gameObject.Recycle();
		}
	}

	private void FaceAngle()
	{
		Vector2 velocity = rb2d.velocity;
		float z = Mathf.Atan2(velocity.y, velocity.x) * (180f / (float)Math.PI);
		base.transform.localEulerAngles = new Vector3(0f, 0f, z);
	}

	private void ProjectileSquash()
	{
		float num = 1f - rb2d.velocity.magnitude * stretchFactor * 0.01f;
		float num2 = 1f + rb2d.velocity.magnitude * stretchFactor * 0.01f;
		if (num2 < stretchMinX)
		{
			num2 = stretchMinX;
		}
		if (num > stretchMaxY)
		{
			num = stretchMaxY;
		}
		num *= scaleModifier;
		num2 *= scaleModifier;
		base.transform.localScale = new Vector3(num2, num, base.transform.localScale.z);
	}

	private void OnCollisionEnter2D(Collision2D collision)
	{
		Impact();
	}
}
public class SpatterOrange : MonoBehaviour
{
	public Rigidbody2D rb2d;

	public CircleCollider2D circleCollider;

	public SpriteRenderer spriteRenderer;

	public Sprite[] sprites;

	private float stretchFactor = 1.4f;

	private float stretchMinX = 0.6f;

	private float stretchMaxY = 1.75f;

	private float scaleModifier;

	public float scaleModifierMin = 0.7f;

	public float scaleModifierMax = 1.3f;

	public float splashScaleMin = 1.5f;

	public float splashScaleMax = 2f;

	private float state;

	public float fps = 30f;

	private float idleTimer;

	private float animTimer;

	private int animFrame;

	private void Start()
	{
		scaleModifier = UnityEngine.Random.Range(scaleModifierMin, scaleModifierMax);
	}

	private void OnEnable()
	{
		rb2d.isKinematic = false;
		circleCollider.enabled = true;
		idleTimer = 0f;
		animTimer = 0f;
		spriteRenderer.sprite = sprites[0];
		animFrame = 1;
		state = 0f;
	}

	private void Update()
	{
		if (state == 0f)
		{
			FaceAngle();
			ProjectileSquash();
			idleTimer += Time.deltaTime;
			if (idleTimer > 3f)
			{
				Impact();
			}
		}
		if (state != 1f)
		{
			return;
		}
		animTimer += Time.deltaTime;
		if (animTimer >= 1f / fps)
		{
			animTimer = 0f;
			animFrame++;
			if (animFrame > 6)
			{
				base.gameObject.Recycle();
			}
			else
			{
				spriteRenderer.sprite = sprites[animFrame];
			}
		}
	}

	private void Impact()
	{
		float num = UnityEngine.Random.Range(splashScaleMin, splashScaleMax);
		base.transform.localScale = new Vector2(num, num);
		circleCollider.enabled = false;
		rb2d.isKinematic = true;
		rb2d.velocity = new Vector2(0f, 0f);
		spriteRenderer.sprite = sprites[1];
		state = 1f;
	}

	private void FaceAngle()
	{
		Vector2 velocity = rb2d.velocity;
		float z = Mathf.Atan2(velocity.y, velocity.x) * (180f / (float)Math.PI);
		base.transform.localEulerAngles = new Vector3(0f, 0f, z);
	}

	private void ProjectileSquash()
	{
		float num = 1f - rb2d.velocity.magnitude * stretchFactor * 0.01f;
		float num2 = 1f + rb2d.velocity.magnitude * stretchFactor * 0.01f;
		if (num2 < stretchMinX)
		{
			num2 = stretchMinX;
		}
		if (num > stretchMaxY)
		{
			num = stretchMaxY;
		}
		num *= scaleModifier;
		num2 *= scaleModifier;
		base.transform.localScale = new Vector3(num2, num, base.transform.localScale.z);
	}

	private void OnCollisionEnter2D(Collision2D collision)
	{
		Collision2DUtils.Collision2DSafeContact safeContact = collision.GetSafeContact();
		float x = safeContact.Normal.x;
		float y = safeContact.Normal.y;
		if (y == -1f)
		{
			base.transform.localEulerAngles = new Vector3(base.transform.localEulerAngles.x, base.transform.localEulerAngles.y, 180f);
		}
		else if (y == 1f)
		{
			base.transform.localEulerAngles = new Vector3(base.transform.localEulerAngles.x, base.transform.localEulerAngles.y, 0f);
		}
		else if (x == 1f)
		{
			base.transform.localEulerAngles = new Vector3(base.transform.localEulerAngles.x, base.transform.localEulerAngles.y, 270f);
		}
		else if (x == -1f)
		{
			base.transform.localEulerAngles = new Vector3(base.transform.localEulerAngles.x, base.transform.localEulerAngles.y, 90f);
		}
		else
		{
			base.transform.localEulerAngles = new Vector3(base.transform.localEulerAngles.x, base.transform.localEulerAngles.y, base.transform.localEulerAngles.z + 90f);
		}
		Impact();
	}

	private void OnTriggerEnter2D()
	{
		base.transform.localEulerAngles = new Vector3(base.transform.localEulerAngles.x, base.transform.localEulerAngles.y, 0f);
		base.transform.position = new Vector3(base.transform.position.x, base.transform.position.y + 0.65f, base.transform.position.z);
		Impact();
	}
}
public class StalactiteControl : MonoBehaviour
{
	public GameObject top;

	[Space]
	public float startFallOffset = 0.1f;

	public GameObject startFallEffect;

	public AudioClip startFallSound;

	public float fallDelay = 0.25f;

	[Space]
	public GameObject fallEffect;

	public GameObject trailEffect;

	public GameObject nailStrikePrefab;

	[Space]
	public GameObject embeddedVersion;

	public GameObject[] landEffectPrefabs;

	[Space]
	public float hitVelocity = 40f;

	[Space]
	public GameObject[] hitUpEffectPrefabs;

	public AudioClip hitSound;

	public GameObject hitUpRockPrefabs;

	public int spawnMin = 10;

	public int spawnMax = 12;

	public int speedMin = 15;

	public int speedMax = 20;

	public AudioClip breakSound;

	private TriggerEnterEvent trigger;

	private DamageHero heroDamage;

	private Rigidbody2D body;

	private AudioSource source;

	private DamageEnemies damageEnemies;

	private bool fallen;

	private void Awake()
	{
		body = GetComponent<Rigidbody2D>();
		source = GetComponent<AudioSource>();
		heroDamage = GetComponent<DamageHero>();
		damageEnemies = GetComponent<DamageEnemies>();
	}

	private void Start()
	{
		trigger = GetComponentInChildren<TriggerEnterEvent>();
		if ((bool)trigger)
		{
			trigger.OnTriggerEntered += HandleTriggerEnter;
		}
		if ((bool)heroDamage)
		{
			heroDamage.damageDealt = 0;
		}
		body.isKinematic = true;
		if ((bool)damageEnemies)
		{
			damageEnemies.enabled = false;
		}
	}

	private void HandleTriggerEnter(Collider2D collider, GameObject sender)
	{
		if (collider.tag == "Player" && Physics2D.Linecast(base.transform.position, collider.transform.position, 256).collider == null)
		{
			StartCoroutine(Fall(fallDelay));
			trigger.OnTriggerEntered -= HandleTriggerEnter;
			sender.SetActive(value: false);
		}
	}

	private IEnumerator Fall(float delay)
	{
		if ((bool)top)
		{
			top.transform.SetParent(transform.parent);
		}
		transform.position += Vector3.down * startFallOffset;
		if ((bool)startFallEffect)
		{
			startFallEffect.SetActive(value: true);
			startFallEffect.transform.SetParent(transform.parent);
		}
		if ((bool)source && (bool)startFallSound)
		{
			source.PlayOneShot(startFallSound);
		}
		yield return new WaitForSeconds(delay);
		if ((bool)fallEffect)
		{
			fallEffect.SetActive(value: true);
			fallEffect.transform.SetParent(transform.parent);
		}
		if ((bool)trailEffect)
		{
			trailEffect.SetActive(value: true);
		}
		if ((bool)heroDamage)
		{
			heroDamage.damageDealt = 1;
		}
		if ((bool)damageEnemies)
		{
			damageEnemies.enabled = true;
		}
		body.isKinematic = false;
		fallen = true;
	}

	private void OnTriggerEnter2D(Collider2D collision)
	{
		if (fallen && collision.gameObject.layer == 8)
		{
			body.isKinematic = true;
			if ((bool)trailEffect)
			{
				trailEffect.transform.parent = null;
			}
			trailEffect.GetComponent<ParticleSystem>().Stop();
			if ((bool)embeddedVersion)
			{
				embeddedVersion.SetActive(value: true);
				embeddedVersion.transform.SetParent(base.transform.parent, worldPositionStays: true);
			}
			RaycastHit2D raycastHit2D = Physics2D.Raycast(base.transform.position, Vector2.down, 10f, 256);
			GameObject[] array = landEffectPrefabs;
			foreach (GameObject gameObject in array)
			{
				Vector3 vector = new Vector3(raycastHit2D.point.x, raycastHit2D.point.y, gameObject.transform.position.z);
				gameObject.Spawn((raycastHit2D.collider != null) ? vector : base.transform.position);
			}
			base.gameObject.SetActive(value: false);
		}
		else
		{
			if (!(collision.tag == "Nail Attack"))
			{
				return;
			}
			if (!fallen)
			{
				StartCoroutine(Fall(0f));
			}
			if ((bool)heroDamage)
			{
				heroDamage.damageDealt = 0;
				heroDamage = null;
			}
			float value = PlayMakerFSM.FindFsmOnGameObject(collision.gameObject, "damages_enemy").FsmVariables.FindFsmFloat("direction").Value;
			float num = 0f;
			if (value < 45f)
			{
				num = 45f;
			}
			else
			{
				if (value < 135f)
				{
					GameObject[] array = hitUpEffectPrefabs;
					for (int i = 0; i < array.Length; i++)
					{
						array[i].Spawn(base.transform.position);
					}
					FlingObjects();
					if ((bool)source && (bool)breakSound)
					{
						AudioSource audioSource = new GameObject("StalactiteBreakEffect").AddComponent<AudioSource>();
						audioSource.outputAudioMixerGroup = source.outputAudioMixerGroup;
						audioSource.loop = false;
						audioSource.playOnAwake = false;
						audioSource.rolloffMode = source.rolloffMode;
						audioSource.minDistance = source.minDistance;
						audioSource.maxDistance = source.maxDistance;
						audioSource.clip = breakSound;
						audioSource.volume = source.volume;
						audioSource.Play();
					}
					base.gameObject.SetActive(value: false);
					return;
				}
				if (value < 225f)
				{
					num = -45f;
				}
				else if (value < 360f)
				{
					num = 0f;
				}
			}
			_ = (Vector3)body.velocity;
			Vector3 vector2 = Quaternion.Euler(0f, 0f, num) * Vector3.down * hitVelocity;
			body.rotation = num;
			body.gravityScale = 0f;
			body.velocity = vector2;
			nailStrikePrefab.Spawn(base.transform.position);
			if ((bool)source && (bool)hitSound)
			{
				source.PlayOneShot(hitSound);
			}
		}
	}

	private void FlingObjects()
	{
		int num = UnityEngine.Random.Range(spawnMin, spawnMax + 1);
		Vector2 velocity = default(Vector2);
		for (int i = 1; i <= num; i++)
		{
			GameObject obj = hitUpRockPrefabs.Spawn(base.transform.position, base.transform.rotation);
			_ = obj.transform.position;
			_ = obj.transform.position;
			_ = obj.transform.position;
			float num2 = UnityEngine.Random.Range(speedMin, speedMax);
			float num3 = UnityEngine.Random.Range(0f, 360f);
			float x = num2 * Mathf.Cos(num3 * ((float)Math.PI / 180f));
			float y = num2 * Mathf.Sin(num3 * ((float)Math.PI / 180f));
			velocity.x = x;
			velocity.y = y;
			Rigidbody2D component = obj.GetComponent<Rigidbody2D>();
			if ((bool)component)
			{
				component.velocity = velocity;
			}
		}
	}
}
public class SteepSlope : MonoBehaviour
{
	public bool slideLeft;

	public bool slideRight;

	private HeroController hc;

	private void Start()
	{
		hc = HeroController.instance;
	}

	private void OnCollisionStay2D(Collision2D collision)
	{
		GameObject obj = collision.gameObject;
		Rigidbody2D component = obj.GetComponent<Rigidbody2D>();
		component.velocity = new Vector2(component.velocity.x, -20f);
		if (obj.CompareTag("Player"))
		{
			hc.ResetHardLandingTimer();
			hc.CancelSuperDash();
		}
	}

	private void OnCollisionEnter2D(Collision2D collision)
	{
		if (collision.gameObject.CompareTag("Player"))
		{
			if (slideLeft)
			{
				hc.cState.slidingLeft = true;
			}
			if (slideRight)
			{
				hc.cState.slidingRight = true;
			}
		}
	}

	private void OnCollisionExit2D(Collision2D collision)
	{
		if (collision.gameObject.CompareTag("Player"))
		{
			if (slideLeft)
			{
				hc.cState.slidingLeft = false;
			}
			if (slideRight)
			{
				hc.cState.slidingRight = false;
			}
		}
	}
}
public class TouchShake : MonoBehaviour
{
	[Header("If using SpriteRenderer")]
	public SpriteRenderer spriteRenderer;

	public BasicSpriteAnimator anim;

	[Header("If using tk2D")]
	public tk2dSpriteAnimator tk2dAnim;

	private Coroutine animateRoutine;

	[Header("General")]
	public ParticleSystem particles;

	public int emitParticles = 20;

	public AudioSource audioSourcePrefab;

	public RandomAudioClipTable audioTable;

	private void Start()
	{
		if ((bool)anim)
		{
			anim.enabled = false;
		}
	}

	private void OnTriggerEnter2D(Collider2D collision)
	{
		if (!(collision.tag == "HeroBox") && !(collision.tag == "Player"))
		{
			return;
		}
		if ((bool)anim)
		{
			if (anim.gameObject.activeInHierarchy && (bool)anim && animateRoutine == null)
			{
				animateRoutine = StartCoroutine(DoAnimation());
			}
		}
		else if ((bool)tk2dAnim && tk2dAnim.gameObject.activeInHierarchy && (bool)tk2dAnim && animateRoutine == null)
		{
			animateRoutine = StartCoroutine(DoAnimation());
		}
	}

	private IEnumerator DoAnimation()
	{
		if ((bool)particles)
		{
			particles.Emit(emitParticles);
		}
		if ((bool)audioTable)
		{
			audioTable.SpawnAndPlayOneShot(audioSourcePrefab, transform.position);
		}
		if ((bool)spriteRenderer && (bool)anim)
		{
			yield return StartCoroutine(SpriteAnimation());
		}
		else if ((bool)tk2dAnim)
		{
			yield return StartCoroutine(tk2dAnimation());
		}
		animateRoutine = null;
	}

	private IEnumerator SpriteAnimation()
	{
		Sprite sprite = spriteRenderer.sprite;
		anim.enabled = true;
		yield return null;
		yield return new WaitForSeconds(anim.Length);
		anim.enabled = false;
		spriteRenderer.sprite = sprite;
	}

	private IEnumerator tk2dAnimation()
	{
		tk2dAnim.PlayFromFrame(0);
		yield return new WaitForSeconds(tk2dAnim.CurrentClip.Duration);
	}
}
public class TownGrass : MonoBehaviour
{
	public GameObject[] debris;

	public GameObject nailEffectPrefab;

	public AudioClip[] cutSound;

	public AudioSource source;

	private void OnTriggerEnter2D(Collider2D collision)
	{
		if (!GrassCut.ShouldCut(collision))
		{
			return;
		}
		int num = (int)Mathf.Sign(collision.transform.position.x - base.transform.position.x);
		Vector3 position = (collision.transform.position + base.transform.position) / 2f;
		if ((bool)nailEffectPrefab)
		{
			GameObject obj = nailEffectPrefab.Spawn(position);
			Vector3 localScale = obj.transform.localScale;
			localScale.x = Mathf.Abs(localScale.x) * (float)(-num);
			obj.transform.localScale = localScale;
		}
		else
		{
			UnityEngine.Debug.Log("No nail effect assigned to " + base.gameObject.name);
		}
		if (debris.Length != 0)
		{
			GameObject[] array = debris;
			foreach (GameObject obj2 in array)
			{
				obj2.SetActive(value: true);
				obj2.transform.SetParent(null, worldPositionStays: true);
			}
		}
		else
		{
			UnityEngine.Debug.Log("No debris assigned to " + base.gameObject.name);
		}
		if ((bool)source && cutSound.Length != 0)
		{
			source.transform.SetParent(null, worldPositionStays: true);
			source.PlayOneShot(cutSound[UnityEngine.Random.Range(0, cutSound.Length)]);
		}
		base.gameObject.SetActive(value: false);
	}
}
public class VinePlatform : MonoBehaviour
{
	public GameObject platformSprite;

	public GameObject activatedSprite;

	public Collider2D collider;

	[Space]
	public AudioClip playerLandSound;

	public ParticleSystem playerLandParticles;

	public AnimationCurve playerLandAnimCurve = new AnimationCurve(new Keyframe(0f, 0f), new Keyframe(0.5f, 1f), new Keyframe(1f, 0f));

	public float playerLandAnimLength = 0.5f;

	[HideInInspector]
	public Coroutine landRoutine;

	[HideInInspector]
	public bool respondOnLand = true;

	private Action landReturnAction;

	[Space]
	public TriggerEnterEvent landingDetector;

	public AudioClip landSound;

	public ParticleSystem[] landParticles;

	public GameObject slamEffect;

	[Space]
	public TriggerEnterEvent enemyDetector;

	[Space]
	public bool acidLander;

	public float acidTargetY;

	public AudioClip acidSplashSound;

	public GameObject acidSplashPrefab;

	private AudioSource audioSource;

	private Rigidbody2D body;

	private bool activated;

	private void Awake()
	{
		audioSource = GetComponent<AudioSource>();
		body = GetComponent<Rigidbody2D>();
	}

	private void Start()
	{
		PersistentBoolItem component = GetComponent<PersistentBoolItem>();
		if ((bool)component)
		{
			component.OnGetSaveState += delegate(ref bool value)
			{
				value = activated;
			};
			component.OnSetSaveState += delegate(bool value)
			{
				activated = value;
				if (activated)
				{
					platformSprite.SetActive(value: false);
					activatedSprite.SetActive(value: true);
					if ((bool)landingDetector)
					{
						landingDetector.gameObject.SetActive(value: false);
					}
					if ((bool)collider)
					{
						collider.enabled = false;
					}
				}
			};
		}
		if ((bool)landingDetector && !acidLander)
		{
			landingDetector.OnTriggerEntered += delegate
			{
				Land();
			};
		}
		if (!enemyDetector)
		{
			return;
		}
		enemyDetector.OnTriggerEntered += delegate(Collider2D collider, GameObject sender)
		{
			HealthManager component2 = collider.GetComponent<HealthManager>();
			if ((bool)component2)
			{
				component2.Die(0f, AttackTypes.Splatter, ignoreEvasion: false);
			}
		};
		enemyDetector.gameObject.SetActive(value: false);
	}

	private void Update()
	{
		if (acidLander && !activated && collider.bounds.min.y <= acidTargetY)
		{
			Land();
		}
	}

	private void Land()
	{
		PlaySound(landSound);
		if (!acidLander)
		{
			GameCameras gameCameras = UnityEngine.Object.FindObjectOfType<GameCameras>();
			if ((bool)gameCameras)
			{
				gameCameras.cameraShakeFSM.SendEvent("AverageShake");
			}
			ParticleSystem[] array = landParticles;
			foreach (ParticleSystem particleSystem in array)
			{
				if (particleSystem.gameObject.activeInHierarchy)
				{
					particleSystem.Play();
				}
			}
			if ((bool)slamEffect)
			{
				slamEffect.SetActive(value: true);
			}
		}
		else
		{
			PlaySound(acidSplashSound);
			if ((bool)acidSplashPrefab)
			{
				UnityEngine.Object.Instantiate(acidSplashPrefab, new Vector3(base.transform.position.x, collider.bounds.min.y, base.transform.position.z), Quaternion.identity);
			}
			float num = base.transform.position.y - collider.bounds.min.y;
			base.transform.SetPositionY(acidTargetY + num);
		}
		if ((bool)body)
		{
			body.isKinematic = true;
			body.velocity = Vector2.zero;
		}
		if ((bool)enemyDetector)
		{
			enemyDetector.gameObject.SetActive(value: false);
		}
		activated = true;
	}

	private void OnCollisionEnter2D(Collision2D collision)
	{
		if (respondOnLand && collision.gameObject.layer == 9 && collision.collider.bounds.min.y >= collider.bounds.max.y)
		{
			if (landRoutine != null)
			{
				StopCoroutine(landRoutine);
			}
			if (landReturnAction != null)
			{
				landReturnAction();
			}
			landRoutine = StartCoroutine(PlayerLand());
		}
		else if (!body.isKinematic && collision.gameObject.layer != 8 && collision.gameObject.layer != 9)
		{
			Physics2D.IgnoreCollision(collision.collider, collision.otherCollider);
		}
	}

	private void PlaySound(AudioClip clip)
	{
		if ((bool)audioSource && (bool)clip)
		{
			audioSource.PlayOneShot(clip);
		}
	}

	private IEnumerator PlayerLand()
	{
		PlaySound(playerLandSound);
		if ((bool)playerLandParticles)
		{
			playerLandParticles.Play();
		}
		if ((bool)platformSprite)
		{
			Vector3 initialPos = platformSprite.transform.position;
			landReturnAction = delegate
			{
				platformSprite.transform.position = initialPos;
			};
			for (float elapsed = 0f; elapsed < playerLandAnimLength; elapsed += Time.deltaTime)
			{
				Vector3 position = initialPos;
				position.y += playerLandAnimCurve.Evaluate(elapsed / playerLandAnimLength);
				platformSprite.transform.position = position;
				yield return null;
			}
		}
		if (landReturnAction != null)
		{
			landReturnAction();
		}
		landRoutine = null;
	}

	private void OnDrawGizmosSelected()
	{
		if (acidLander)
		{
			Vector3 position = base.transform.position;
			position.y = acidTargetY;
			Gizmos.DrawWireSphere(position, 0.5f);
		}
	}
}
public class VinePlatformCut : MonoBehaviour
{
	public Rigidbody2D body;

	[Space]
	public GameObject sprites;

	[Space]
	public GameObject cutParticles;

	public GameObject cutPointParticles;

	public GameObject cutEffectPrefab;

	[Space]
	public AudioClip cutSound;

	private bool activated;

	private VinePlatform platform;

	private AudioSource audioSource;

	private Collider2D col;

	private void Awake()
	{
		platform = GetComponentInParent<VinePlatform>();
		audioSource = GetComponentInParent<AudioSource>();
		col = GetComponent<Collider2D>();
	}

	private void OnTriggerEnter2D(Collider2D collision)
	{
		if (activated || !(collision.tag == "Nail Attack") || collision.transform.position.y < col.bounds.min.y || collision.transform.position.y > col.bounds.max.y)
		{
			return;
		}
		float value = PlayMakerFSM.FindFsmOnGameObject(collision.gameObject, "damages_enemy").FsmVariables.FindFsmFloat("direction").Value;
		if (value < 45f || (!(value < 135f) && (value < 225f || !(value < 360f))))
		{
			Vector3 position = cutPointParticles.transform.position;
			position.y = collision.transform.position.y;
			if ((bool)cutEffectPrefab)
			{
				cutEffectPrefab.Spawn(position);
			}
			if ((bool)cutPointParticles)
			{
				cutPointParticles.transform.position = position;
				cutPointParticles.SetActive(value: true);
			}
			Cut();
		}
	}

	public void Cut()
	{
		activated = true;
		if ((bool)body)
		{
			body.isKinematic = false;
		}
		if ((bool)cutParticles)
		{
			cutParticles.SetActive(value: true);
		}
		if ((bool)platform.enemyDetector)
		{
			platform.enemyDetector.gameObject.SetActive(value: true);
		}
		platform.respondOnLand = false;
		if (platform.landRoutine != null)
		{
			StopCoroutine(platform.landRoutine);
		}
		if ((bool)audioSource && (bool)cutSound)
		{
			audioSource.PlayOneShot(cutSound);
		}
		Disable();
	}

	public void Disable(bool disableAll = false)
	{
		if (disableAll)
		{
			base.gameObject.SetActive(value: false);
		}
		else if ((bool)sprites)
		{
			sprites.SetActive(value: false);
		}
	}
}
public class WalkSlope : MonoBehaviour
{
	private void Start()
	{
		UnityEngine.Debug.LogError(base.name + " has a WalkSlope script attached. This script is now DEPRECATED. Please remove it from the prefab.");
	}
}
[RequireComponent(typeof(Collider2D))]
[RequireComponent(typeof(Rigidbody2D))]
[RequireComponent(typeof(tk2dSpriteAnimator))]
[RequireComponent(typeof(AudioSource))]
public class WaterDrip : MonoBehaviour
{
	public float idleTimeMin = 2f;

	public float idleTimeMax = 8f;

	public float fallVelocity = -7f;

	public RandomAudioClipTable impactAudioClipTable;

	public float impactTranslation = -0.5f;

	private bool impacted;

	private Vector2 startPos;

	private Collider2D col;

	private Rigidbody2D body;

	private tk2dSpriteAnimator anim;

	private AudioSource source;

	private void Awake()
	{
		col = GetComponent<Collider2D>();
		body = GetComponent<Rigidbody2D>();
		anim = GetComponent<tk2dSpriteAnimator>();
		source = GetComponent<AudioSource>();
	}

	private void Start()
	{
		startPos = base.transform.position;
		StartCoroutine(Drip());
	}

	private IEnumerator Drip()
	{
		while (true)
		{
			anim.Play("Idle");
			body.gravityScale = 0f;
			body.velocity = Vector2.zero;
			col.enabled = false;
			yield return new WaitForSeconds(UnityEngine.Random.Range(idleTimeMin, idleTimeMax));
			col.enabled = true;
			yield return StartCoroutine(anim.PlayAnimWait("Drip"));
			anim.Play("Fall");
			body.gravityScale = 1f;
			body.velocity = new Vector2(0f, fallVelocity);
			impacted = false;
			while (!impacted)
			{
				yield return null;
			}
			body.gravityScale = 0f;
			body.velocity = Vector2.zero;
			col.enabled = false;
			impactAudioClipTable.PlayOneShot(source);
			transform.position += new Vector3(0f, impactTranslation, 0f);
			yield return StartCoroutine(anim.PlayAnimWait("Impact"));
			transform.position = startPos;
		}
	}

	private void OnCollisionEnter2D(Collision2D collision)
	{
		impacted = true;
	}
}
