public class CodeProfiler : MonoBehaviour
{
	private float startTime;

	private float nextOutputTime = 5f;

	private int numFrames;

	private static Dictionary<string, ProfilerRecording> recordings = new Dictionary<string, ProfilerRecording>();

	private string displayText;

	private Rect displayRect = new Rect(10f, 10f, 460f, 300f);

	private void Awake()
	{
		startTime = Time.time;
		displayText = "\n\nTaking initial readings...";
	}

	private void OnGUI()
	{
		GUI.Box(displayRect, "Code Profiler");
		GUI.Label(displayRect, displayText);
	}

	public static void Begin(string id)
	{
		if (!recordings.ContainsKey(id))
		{
			recordings[id] = new ProfilerRecording(id);
		}
		recordings[id].Start();
	}

	public static void End(string id)
	{
		recordings[id].Stop();
	}

	private void Update()
	{
		numFrames++;
		if (!(Time.time > nextOutputTime))
		{
			return;
		}
		int totalWidth = 10;
		displayText = "\n\n";
		float num = (Time.time - startTime) * 1000f;
		float num2 = num / (float)numFrames;
		float num3 = 1000f / (num / (float)numFrames);
		displayText += "Avg frame time: ";
		displayText = displayText + num2.ToString("0.#") + "ms, ";
		displayText = displayText + num3.ToString("0.#") + " fps \n";
		displayText += "Total".PadRight(totalWidth);
		displayText += "MS/frame".PadRight(totalWidth);
		displayText += "Calls/fra".PadRight(totalWidth);
		displayText += "MS/call".PadRight(totalWidth);
		displayText += "Label";
		displayText += "\n";
		foreach (KeyValuePair<string, ProfilerRecording> recording in recordings)
		{
			ProfilerRecording value = recording.Value;
			float num4 = value.Seconds * 1000f;
			float num5 = num4 * 100f / num;
			float num6 = num4 / (float)numFrames;
			float num7 = num4 / (float)value.Count;
			float num8 = (float)value.Count / (float)numFrames;
			displayText += (num5.ToString("0.000") + "%").PadRight(totalWidth);
			displayText += (num6.ToString("0.000") + "ms").PadRight(totalWidth);
			displayText += num8.ToString("0.000").PadRight(totalWidth);
			displayText += (num7.ToString("0.0000") + "ms").PadRight(totalWidth);
			displayText += value.id;
			displayText += "\n";
			value.Reset();
		}
		UnityEngine.Debug.Log(displayText);
		numFrames = 0;
		startTime = Time.time;
		nextOutputTime = Time.time + 5f;
	}
}
internal class ProfilerRecording
{
	private int count;

	private float startTime;

	private float accumulatedTime;

	private bool started;

	public string id;

	public float Seconds => accumulatedTime;

	public int Count => count;

	public ProfilerRecording(string id)
	{
		this.id = id;
	}

	public void Start()
	{
		if (started)
		{
			BalanceError();
		}
		count++;
		started = true;
		startTime = Time.realtimeSinceStartup;
	}

	public void Stop()
	{
		float realtimeSinceStartup = Time.realtimeSinceStartup;
		if (!started)
		{
			BalanceError();
		}
		started = false;
		float num = realtimeSinceStartup - startTime;
		accumulatedTime += num;
	}

	public void Reset()
	{
		accumulatedTime = 0f;
		count = 0;
		started = false;
	}

	private void BalanceError()
	{
		UnityEngine.Debug.LogError("ProfilerRecording start/stops not balanced for '" + id + "'");
	}
}
[ExecuteInEditMode]
public class GateSnap : MonoBehaviour
{
	private float snapX = 0.5f;

	private float snapY = 0.5f;

	private void Update()
	{
		Vector2 vector = base.transform.position;
		vector.x = Mathf.Round(vector.x / snapX) * snapX;
		vector.y = Mathf.Round(vector.y / snapY) * snapY;
		base.transform.position = vector;
	}
}
public class OnScreenDebugInfo : MonoBehaviour
{
	private GameManager gm;

	private InputHandler ih;

	private float unloadTime;

	private float loadTime;

	private float frameRate;

	private string fps;

	private string infoString;

	private string versionNumber;

	private const float textWidth = 100f;

	private Rect loadProfilerRect;

	private Rect fpsRect;

	private Rect infoRect;

	private Rect inputRect;

	private Rect tfrRect;

	private bool showFPS;

	private bool showInfo;

	private bool showInput;

	private bool showLoadingTime;

	private bool showTFR;

	private void Awake()
	{
		if (ModLoader.LoadState == ModLoader.ModLoadState.NotStarted)
		{
			Modding.Logger.APILogger.Log("Main menu loading");
			ModLoader.LoadState = ModLoader.ModLoadState.Started;
			GameObject gameObject = new GameObject();
			UnityEngine.Object.DontDestroyOnLoad(gameObject);
			new Thread(Modding.ReflectionHelper.PreloadCommonTypes).Start();
			gameObject.AddComponent<NonBouncer>().StartCoroutine(ModLoader.LoadModsInit(gameObject));
		}
		else
		{
			Modding.Logger.APILogger.LogDebug($"OnScreenDebugInfo: Already begun mod loading (state {ModLoader.LoadState})");
		}
		orig_Awake();
	}

	private IEnumerator Start()
	{
		gm = GameManager.instance;
		gm.UnloadingLevel += OnLevelUnload;
		ih = gm.inputHandler;
		RetrieveInfo();
		GUI.depth = 2;
		while (showFPS)
		{
			if (Time.timeScale == 1f)
			{
				yield return new WaitForSeconds(0.1f);
				frameRate = 1f / Time.deltaTime;
				fps = "FPS :" + Mathf.Round(frameRate);
			}
			else
			{
				fps = "Pause";
			}
			yield return new WaitForSeconds(0.5f);
		}
	}

	private void LevelActivated(Scene sceneFrom, Scene sceneTo)
	{
		RetrieveInfo();
		if (showLoadingTime)
		{
			loadTime = (float)Math.Round(Time.realtimeSinceStartup - unloadTime, 2);
		}
	}

	private void OnEnable()
	{
		UnityEngine.SceneManagement.SceneManager.activeSceneChanged += LevelActivated;
	}

	private void OnDisable()
	{
		UnityEngine.SceneManagement.SceneManager.activeSceneChanged -= LevelActivated;
		if (gm != null)
		{
			gm.UnloadingLevel -= OnLevelUnload;
		}
	}

	private void OnGUI()
	{
		if (showInfo)
		{
			if (showFPS)
			{
				GUI.Label(fpsRect, fps);
			}
			if (showInfo)
			{
				GUI.Label(infoRect, infoString);
			}
			if (showInput)
			{
				GUI.Label(inputRect, ReadInput());
			}
			if (showLoadingTime)
			{
				GUI.Label(loadProfilerRect, loadTime + "s");
			}
			if (showTFR)
			{
				GUI.Label(tfrRect, "TFR: " + Application.targetFrameRate);
			}
		}
	}

	public void ShowFPS()
	{
		showFPS = !showFPS;
	}

	public void ShowGameInfo()
	{
		showInfo = !showInfo;
	}

	public void ShowInput()
	{
		showInput = !showInput;
	}

	public void ShowLoadingTime()
	{
		showLoadingTime = !showLoadingTime;
	}

	public void ShowTargetFrameRate()
	{
		showTFR = !showTFR;
	}

	private void OnLevelUnload()
	{
		unloadTime = Time.realtimeSinceStartup;
	}

	private void RetrieveInfo()
	{
		if (gm == null)
		{
			gm = GameManager.instance;
		}
		versionNumber = "1.5.78.11833";
		infoString = global::Language.Language.Get("GAME_TITLE") + "\r\n" + versionNumber + " " + global::Language.Language.CurrentLanguage().ToString() + "\r\n" + gm.GetSceneNameString();
	}

	private string ReadInput()
	{
		return string.Concat(string.Concat(string.Concat(string.Concat("" + $"Move Vector: {ih.inputActions.moveVector.Vector.x.ToString()}, {ih.inputActions.moveVector.Vector.y.ToString()}", $"\nMove Pressed: {ih.inputActions.left.IsPressed || ih.inputActions.right.IsPressed}"), $"\nMove Raw L: {ih.inputActions.left.RawValue} R: {ih.inputActions.right.RawValue}"), string.Format("\nInputX: " + ih.inputX)), $"\nAny Key Down: {InputManager.AnyKeyIsPressed}");
	}

	private void orig_Awake()
	{
		fpsRect = new Rect(7f, 5f, 100f, 25f);
		infoRect = new Rect(Screen.width - 105, 5f, 100f, 70f);
		inputRect = new Rect(7f, 65f, 300f, 120f);
		loadProfilerRect = new Rect((float)(Screen.width / 2) - 50f, 5f, 100f, 25f);
		tfrRect = new Rect(7f, 20f, 100f, 25f);
	}
}
