public class TrackTriggerObjects : MonoBehaviour
{
	[SerializeField]
	private LayerMask ignoreLayers;

	private List<GameObject> insideGameObjects = new List<GameObject>();

	private int layerMask = -1;

	private bool gottenOverlappedColliders;

	private bool subscribed;

	private static readonly Collider2D[] _tempResults = new Collider2D[10];

	private static readonly List<GameObject> _refreshTemp = new List<GameObject>();

	public int InsideCount
	{
		get
		{
			int num = 0;
			foreach (GameObject insideGameObject in insideGameObjects)
			{
				if ((bool)insideGameObject)
				{
					num++;
				}
			}
			return num;
		}
	}

	private void OnDisable()
	{
		insideGameObjects.Clear();
		gottenOverlappedColliders = false;
		if (subscribed)
		{
			HeroController silentInstance = HeroController.SilentInstance;
			if ((bool)silentInstance)
			{
				silentInstance.heroInPosition -= OnHeroInPosition;
			}
			subscribed = false;
		}
	}

	private void OnEnable()
	{
		if (layerMask < 0)
		{
			layerMask = Helper.GetCollidingLayerMaskForLayer(base.gameObject.layer);
		}
		HeroController instance = HeroController.instance;
		if ((bool)instance && !instance.isHeroInPosition)
		{
			HeroController.instance.heroInPosition += OnHeroInPosition;
			subscribed = true;
		}
		else
		{
			GetOverlappedColliders();
		}
	}

	private void FixedUpdate()
	{
		for (int num = insideGameObjects.Count - 1; num >= 0; num--)
		{
			GameObject gameObject = insideGameObjects[num];
			if (!gameObject || !gameObject.activeInHierarchy)
			{
				insideGameObjects.RemoveAt(num);
			}
		}
	}

	private void OnHeroInPosition(bool forceDirect)
	{
		if (subscribed)
		{
			HeroController.instance.heroInPosition -= OnHeroInPosition;
			subscribed = false;
		}
		if (!this)
		{
			UnityEngine.Debug.LogError("TrackTriggerObjects native Object was destroyed! This should not happen...", this);
		}
		else
		{
			GetOverlappedColliders();
		}
	}

	private void GetOverlappedColliders(bool isRefresh = false)
	{
		if (!base.enabled || !base.gameObject.activeInHierarchy || (gottenOverlappedColliders && !isRefresh))
		{
			return;
		}
		gottenOverlappedColliders = true;
		Collider2D[] components = GetComponents<Collider2D>();
		Collider2D[] array = components;
		for (int i = 0; i < array.Length; i++)
		{
			if (array[i].OverlapCollider(new ContactFilter2D
			{
				useTriggers = true,
				useLayerMask = true,
				layerMask = layerMask
			}, _tempResults) <= 0)
			{
				continue;
			}
			Collider2D[] tempResults = _tempResults;
			foreach (Collider2D collider2D in tempResults)
			{
				if ((bool)collider2D)
				{
					OnTriggerEnter2D(collider2D);
				}
			}
		}
		for (int k = 0; k < _tempResults.Length; k++)
		{
			_tempResults[k] = null;
		}
		if (!isRefresh)
		{
			return;
		}
		_refreshTemp.AddRange(insideGameObjects);
		foreach (GameObject item in _refreshTemp)
		{
			bool flag = false;
			array = components;
			for (int i = 0; i < array.Length; i++)
			{
				if (array[i].gameObject == item)
				{
					flag = true;
					break;
				}
			}
			if (!flag)
			{
				OnExit(item);
			}
		}
		_refreshTemp.Clear();
	}

	private void OnTriggerEnter2D(Collider2D collision)
	{
		if (gottenOverlappedColliders)
		{
			GameObject gameObject = collision.gameObject;
			if (!IsIgnored(gameObject) && !insideGameObjects.Contains(gameObject))
			{
				insideGameObjects.Add(gameObject);
			}
		}
	}

	private void OnTriggerExit2D(Collider2D collision)
	{
		GameObject obj = collision.gameObject;
		OnExit(obj);
	}

	private void OnExit(GameObject obj)
	{
		insideGameObjects.Remove(obj);
	}

	private bool IsIgnored(GameObject obj)
	{
		int layer = obj.layer;
		int num = 1 << layer;
		return (ignoreLayers.value & num) == num;
	}
}
[ActionCategory("Hollow Knight")]
public class AddTrackTrigger : FsmStateAction
{
	public FsmOwnerDefault target;

	public FsmBool skipIfPresent;

	public override void Reset()
	{
		target = null;
		skipIfPresent = true;
	}

	public override void OnEnter()
	{
		GameObject safe = target.GetSafe(this);
		if ((bool)safe && !safe.GetComponent<TrackTriggerObjects>())
		{
			safe.AddComponent<TrackTriggerObjects>();
		}
		Finish();
	}
}
[ActionCategory("Hollow Knight")]
[HutongGames.PlayMaker.Tooltip("Check and respond to the amount of objects in a Trigger that has TrackTriggerObjects attached to the same object.")]
public class CheckTrackTriggerCount : FsmStateAction
{
	public enum IntTest
	{
		Equal,
		LessThan,
		MoreThan,
		LessThanOrEqual,
		MoreThanOrEqual
	}

	public FsmOwnerDefault target;

	public FsmInt count;

	[ObjectType(typeof(IntTest))]
	public FsmEnum test;

	public bool everyFrame;

	[Space]
	public FsmEvent successEvent;

	private TrackTriggerObjects track;

	public override void Reset()
	{
		target = null;
		count = null;
		test = null;
		everyFrame = true;
		successEvent = null;
	}

	public override void OnPreprocess()
	{
		base.Fsm.HandleFixedUpdate = true;
	}

	public override void OnEnter()
	{
		GameObject safe = target.GetSafe(this);
		if ((bool)safe)
		{
			track = safe.GetComponent<TrackTriggerObjects>();
			if ((bool)track)
			{
				if (!CheckCount())
				{
					if (everyFrame)
					{
						return;
					}
				}
				else
				{
					base.Fsm.Event(successEvent);
				}
			}
			else
			{
				UnityEngine.Debug.LogError("Target GameObject does not have a TrackTriggerObjects component attached!", base.Owner);
			}
		}
		Finish();
	}

	public override void OnFixedUpdate()
	{
		if (everyFrame && CheckCount())
		{
			base.Fsm.Event(successEvent);
		}
	}

	public bool CheckCount()
	{
		if ((bool)track)
		{
			switch ((IntTest)(object)test.Value)
			{
			case IntTest.Equal:
				return track.InsideCount == count.Value;
			case IntTest.LessThan:
				return track.InsideCount < count.Value;
			case IntTest.LessThanOrEqual:
				return track.InsideCount <= count.Value;
			case IntTest.MoreThan:
				return track.InsideCount > count.Value;
			case IntTest.MoreThanOrEqual:
				return track.InsideCount >= count.Value;
			}
			UnityEngine.Debug.LogError($"IntTest type {((IntTest)(object)test.Value/*cast due to constrained. prefix*/).ToString()} not implemented!", base.Owner);
		}
		return false;
	}
}
public class TransitionPoint : MonoBehaviour
{
	public delegate void BeforeTransitionEvent();

	private GameManager gm;

	private PlayerData playerData;

	private bool activated;

	[Header("Door Type Gate Settings")]
	[Space(5f)]
	public bool isADoor;

	public bool dontWalkOutOfDoor;

	[Header("Gate Entry")]
	[UnityEngine.Tooltip("The wait time before entering from this gate (not the target gate).")]
	public float entryDelay;

	public bool alwaysEnterRight;

	public bool alwaysEnterLeft;

	[Header("Force Hard Land (Top Gates Only)")]
	[Space(5f)]
	public bool hardLandOnExit;

	[Header("Destination Scene")]
	[Space(5f)]
	public string targetScene;

	public string entryPoint;

	public Vector2 entryOffset;

	[SerializeField]
	private bool alwaysUnloadUnusedAssets;

	public PlayMakerFSM customFadeFSM;

	[Header("Hazard Respawn")]
	[Space(5f)]
	public bool nonHazardGate;

	public HazardRespawnMarker respawnMarker;

	[Header("Set Audio Snapshots")]
	[Space(5f)]
	public AudioMixerSnapshot atmosSnapshot;

	public AudioMixerSnapshot enviroSnapshot;

	public AudioMixerSnapshot actorSnapshot;

	public AudioMixerSnapshot musicSnapshot;

	private Color myGreen = new Color(0f, 0.8f, 0f, 0.5f);

	[Header("Cosmetics")]
	public GameManager.SceneLoadVisualizations sceneLoadVisualization;

	public bool customFade;

	public bool forceWaitFetch;

	private static List<TransitionPoint> transitionPoints;

	public static string lastEntered = "";

	public static List<TransitionPoint> TransitionPoints => transitionPoints;

	public event BeforeTransitionEvent OnBeforeTransition;

	[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
	private static void Init()
	{
		transitionPoints = new List<TransitionPoint>();
	}

	protected void Awake()
	{
		transitionPoints.Add(this);
	}

	protected void OnDestroy()
	{
		transitionPoints.Remove(this);
	}

	private void Start()
	{
		gm = GameManager.instance;
		playerData = PlayerData.instance;
		if (!nonHazardGate && respawnMarker == null)
		{
			UnityEngine.Debug.LogError("Transition Gate " + base.name + " in " + gm.sceneName + " does not have its respawn marker set in inspector.");
		}
	}

	private void OnTriggerEnter2D(Collider2D movingObj)
	{
		if (isADoor || movingObj.gameObject.layer != 9 || gm.gameState != GameState.PLAYING)
		{
			return;
		}
		if (!string.IsNullOrEmpty(targetScene) && !string.IsNullOrEmpty(entryPoint))
		{
			if ((bool)customFadeFSM)
			{
				customFadeFSM.SendEvent("FADE");
			}
			if (atmosSnapshot != null)
			{
				atmosSnapshot.TransitionTo(1.5f);
			}
			if (enviroSnapshot != null)
			{
				enviroSnapshot.TransitionTo(1.5f);
			}
			if (actorSnapshot != null)
			{
				actorSnapshot.TransitionTo(1.5f);
			}
			if (musicSnapshot != null)
			{
				musicSnapshot.TransitionTo(1.5f);
			}
			activated = true;
			lastEntered = base.gameObject.name;
			if (OnBeforeTransition != null)
			{
				OnBeforeTransition();
			}
			gm.BeginSceneTransition(new GameManager.SceneLoadInfo
			{
				SceneName = targetScene,
				EntryGateName = entryPoint,
				HeroLeaveDirection = GetGatePosition(),
				EntryDelay = entryDelay,
				WaitForSceneTransitionCameraFade = true,
				PreventCameraFadeOut = (customFadeFSM != null),
				Visualization = sceneLoadVisualization,
				AlwaysUnloadUnusedAssets = alwaysUnloadUnusedAssets,
				forceWaitFetch = forceWaitFetch
			});
		}
		else
		{
			UnityEngine.Debug.LogError(gm.sceneName + " " + base.name + " no target scene has been set on this gate.");
		}
	}

	private void OnTriggerStay2D(Collider2D movingObj)
	{
		if (!activated)
		{
			OnTriggerEnter2D(movingObj);
		}
	}

	private void OnDrawGizmos()
	{
		if (base.transform != null)
		{
			Vector3 position = (Vector3)(Vector2)base.transform.position + new Vector3(0f, GetComponent<BoxCollider2D>().bounds.extents.y + 1.5f, 0f);
			GizmoUtility.DrawText(GUI.skin, targetScene, position, myGreen, 10);
		}
	}

	public GatePosition GetGatePosition()
	{
		string text = base.name;
		if (text.Contains("top"))
		{
			return GatePosition.top;
		}
		if (text.Contains("right"))
		{
			return GatePosition.right;
		}
		if (text.Contains("left"))
		{
			return GatePosition.left;
		}
		if (text.Contains("bot"))
		{
			return GatePosition.bottom;
		}
		if (text.Contains("door") || isADoor)
		{
			return GatePosition.door;
		}
		UnityEngine.Debug.LogError("Gate name " + text + "does not conform to a valid gate position type. Make sure gate name has the form 'left1'");
		return GatePosition.unknown;
	}

	public void SetTargetScene(string newScene)
	{
		targetScene = newScene;
	}
}
public class TriggerEnterEvent : MonoBehaviour
{
	public delegate void CollisionEvent(Collider2D collider, GameObject sender);

	public bool waitForHeroInPosition;

	private bool active;

	public event CollisionEvent OnTriggerEntered;

	public event CollisionEvent OnTriggerExited;

	public event CollisionEvent OnTriggerStayed;

	private void Start()
	{
		active = false;
		if (waitForHeroInPosition)
		{
			if (HeroController.instance.isHeroInPosition)
			{
				active = true;
				return;
			}
			HeroController.HeroInPosition temp = null;
			temp = delegate
			{
				active = true;
				HeroController.instance.heroInPosition -= temp;
			};
			HeroController.instance.heroInPosition += temp;
		}
		else
		{
			active = true;
		}
	}

	private void OnTriggerEnter2D(Collider2D collision)
	{
		if (active && OnTriggerEntered != null)
		{
			OnTriggerEntered(collision, base.gameObject);
		}
	}

	private void OnTriggerExit2D(Collider2D collision)
	{
		if (active && OnTriggerExited != null)
		{
			OnTriggerExited(collision, base.gameObject);
		}
	}

	private void OnTriggerStay2D(Collider2D collision)
	{
		if (active && OnTriggerStayed != null)
		{
			OnTriggerStayed(collision, base.gameObject);
		}
	}
}
[ActionCategory("Hollow Knight")]
public class TriggerEnterEventSubscribe : FsmStateAction
{
	[ObjectType(typeof(TriggerEnterEvent))]
	public FsmObject trigger;

	public FsmEvent triggerEnteredEvent;

	public FsmEvent triggerExitedEvent;

	public FsmEvent triggerStayedEvent;

	public override void Reset()
	{
		triggerEnteredEvent = null;
		triggerExitedEvent = null;
		triggerStayedEvent = null;
	}

	public override void OnEnter()
	{
		if (!trigger.IsNone)
		{
			TriggerEnterEvent obj = (TriggerEnterEvent)trigger.Value;
			obj.OnTriggerEntered += SendEnteredEvent;
			obj.OnTriggerExited += SendExitedEvent;
			obj.OnTriggerStayed += SendStayedEvent;
		}
		Finish();
	}

	public override void OnExit()
	{
		if (!trigger.IsNone)
		{
			TriggerEnterEvent obj = (TriggerEnterEvent)trigger.Value;
			obj.OnTriggerEntered -= SendEnteredEvent;
			obj.OnTriggerExited -= SendExitedEvent;
			obj.OnTriggerStayed -= SendStayedEvent;
		}
	}

	private void SendEnteredEvent(Collider2D collider, GameObject sender)
	{
		base.Fsm.Event(triggerEnteredEvent);
	}

	private void SendExitedEvent(Collider2D collider, GameObject sender)
	{
		base.Fsm.Event(triggerExitedEvent);
	}

	private void SendStayedEvent(Collider2D collider, GameObject sender)
	{
		base.Fsm.Event(triggerStayedEvent);
	}
}
public class TriggerEnterSendMessage : MonoBehaviour
{
	public string message = "Acid";

	public SendMessageOptions options = SendMessageOptions.DontRequireReceiver;

