		collision.gameObject.SendMessage(message, options);
	}
}
public class AchievementPopup : MonoBehaviour
{
	public delegate void SelfEvent(AchievementPopup sender);

	private enum FadeState
	{
		None,
		FadeUp,
		Wait,
		FadeDown,
		Finish
	}

	public Image image;

	public Text nameText;

	public Text descriptionText;

	private CanvasGroup group;

	[Space]
	public float fadeInTime = 0.25f;

	public float holdTime = 3f;

	public float fadeOutTime = 0.5f;

	[Space]
	public AudioSource audioPlayerPrefab;

	public AudioEvent sound;

	[Space]
	public Animator fluerAnimator;

	public string fluerCloseName = "Close";

	private FadeState currentState;

	private FadeState previousState;

	private float elapsed;

	public event SelfEvent OnFinish;

	private void Awake()
	{
		group = GetComponent<CanvasGroup>();
	}

	public void Setup(Sprite icon, string name, string description)
	{
		if ((bool)image)
		{
			image.sprite = icon;
		}
		if ((bool)nameText)
		{
			nameText.text = name;
		}
		if ((bool)descriptionText)
		{
			descriptionText.text = description;
		}
		sound.SpawnAndPlayOneShot(audioPlayerPrefab, Vector3.zero);
		currentState = FadeState.FadeUp;
	}

	private void Update()
	{
		switch (currentState)
		{
		case FadeState.FadeUp:
			if (currentState != previousState)
			{
				elapsed = 0f;
				previousState = currentState;
			}
			group.alpha = Mathf.Lerp(0f, 1f, elapsed / fadeInTime);
			elapsed += Time.unscaledDeltaTime;
			if (elapsed >= fadeInTime)
			{
				group.alpha = 1f;
				currentState = FadeState.Wait;
			}
			break;
		case FadeState.Wait:
			if (currentState != previousState)
			{
				elapsed = 0f;
				previousState = currentState;
			}
			elapsed += Time.unscaledDeltaTime;
			if (elapsed >= holdTime)
			{
				currentState = FadeState.FadeDown;
			}
			break;
		case FadeState.FadeDown:
			if (currentState != previousState)
			{
				elapsed = 0f;
				previousState = currentState;
				if ((bool)fluerAnimator)
				{
					fluerAnimator.Play(fluerCloseName);
				}
			}
			group.alpha = Mathf.Lerp(1f, 0f, elapsed / fadeInTime);
			elapsed += Time.unscaledDeltaTime;
			if (elapsed >= fadeInTime)
			{
				group.alpha = 0f;
				currentState = FadeState.Finish;
			}
			break;
		case FadeState.Finish:
			if (currentState != previousState)
			{
				previousState = currentState;
				if (OnFinish != null)
				{
					OnFinish(this);
				}
				else
				{
					base.gameObject.SetActive(value: false);
				}
			}
			break;
		}
	}
}
public class AchievementPopupHandler : MonoBehaviour
{
	public static AchievementPopupHandler Instance;

	public AchievementPopup template;

	private List<AchievementPopup> popups = new List<AchievementPopup>();

	public bool reverseOrder;

	private AchievementHandler achievements;

	private AchievementPopup lastPopup;

	private void Awake()
	{
		Instance = this;
		if ((bool)template)
		{
			popups.Add(template);
			template.gameObject.SetActive(value: false);
		}
	}

	private void Start()
	{
		achievements = GameManager.instance.achievementHandler;
	}

	public void Setup(AchievementHandler handler)
	{
		achievements = handler;
		if (!Platform.Current.HasNativeAchievementsDialog)
		{
			achievements.AwardAchievementEvent += HandleAchievementEvent;
		}
	}

	private void HandleAchievementEvent(string key)
	{
		Achievement achievement = achievements.achievementsList.FindAchievement(key);
		Sprite earnedIcon = achievement.earnedIcon;
		string text = global::Language.Language.Get(achievement.localizedTitle, "Achievements");
		string description = global::Language.Language.Get(achievement.localizedText, "Achievements");
		AchievementPopup pooledPopup = GetPooledPopup();
		if ((bool)pooledPopup)
		{
			pooledPopup.Setup(earnedIcon, text, description);
			lastPopup = pooledPopup;
			pooledPopup.OnFinish += DisableAll;
		}
		else
		{
			UnityEngine.Debug.LogError("Could not get achievement popup!");
		}
	}

	private AchievementPopup GetPooledPopup()
	{
		AchievementPopup achievementPopup = null;
		foreach (AchievementPopup popup in popups)
		{
			if (!popup.gameObject.activeSelf)
			{
				achievementPopup = popup;
				break;
			}
		}
		if (achievementPopup == null && (bool)template)
		{
			achievementPopup = UnityEngine.Object.Instantiate(template.gameObject, template.transform.parent).GetComponent<AchievementPopup>();
			popups.Add(achievementPopup);
		}
		if (reverseOrder)
		{
			achievementPopup.transform.SetAsFirstSibling();
		}
		else
		{
			achievementPopup.transform.SetAsLastSibling();
		}
		achievementPopup.gameObject.SetActive(value: true);
		return achievementPopup;
	}

	private void DisableAll(AchievementPopup sender)
	{
		sender.OnFinish -= DisableAll;
		if (!(sender == lastPopup))
		{
			return;
		}
		foreach (AchievementPopup popup in popups)
		{
			popup.gameObject.SetActive(value: false);
		}
	}
}
[RequireComponent(typeof(SpriteRenderer))]
public class ActionButtonIcon : ActionButtonIconBase
{
	public HeroActionButton action;

	public bool showForControllerOnly;

	private Vector3? initialScale;

	public override HeroActionButton Action => action;

	protected override void OnEnable()
	{
		base.OnIconUpdate += CheckHideIcon;
		base.OnEnable();
	}

	protected override void OnDisable()
	{
		base.OnIconUpdate -= CheckHideIcon;
		base.OnDisable();
	}

	private void CheckHideIcon()
	{
		if (showForControllerOnly && (bool)sr)
		{
			if (!initialScale.HasValue)
			{
				initialScale = base.transform.localScale;
			}
			InputHandler instance = InputHandler.Instance;
			if (instance.lastActiveController == BindingSourceType.KeyBindingSource || instance.lastActiveController == BindingSourceType.None)
			{
				base.transform.localScale = Vector3.zero;
			}
			else if (instance.lastActiveController == BindingSourceType.DeviceBindingSource)
			{
				base.transform.localScale = initialScale.Value;
			}
		}
	}

	public void SetAction(HeroActionButton action)
	{
		this.action = action;
		GetButtonIcon(action);
	}

	public void SetActionString(string action)
	{
		object obj = Enum.Parse(typeof(HeroActionButton), action);
		if (obj != null)
		{
			this.action = (HeroActionButton)obj;
			GetButtonIcon((HeroActionButton)obj);
		}
		else
		{
			UnityEngine.Debug.LogError("SetAction couldn't convert " + action);
		}
	}
}
[RequireComponent(typeof(SpriteRenderer))]
public abstract class ActionButtonIconBase : MonoBehaviour
{
	public delegate void IconUpdateEvent();

	[Header("Optional")]
	[UnityEngine.Tooltip("This will update the button skin to reflect the currently active controller at all times.")]
	public bool liveUpdate;

	public TextMeshPro label;

	public TextContainer textContainer;

	protected SpriteRenderer sr;

	private UIButtonSkins uibs;

	private InputHandler ih;

	private float blnkWidth = 1.685f;

	private float blnkHeight = 0.6f;

	private float blnkFontMax = 9.5f;

	private float blnkFontMin = 4f;

	private float sqrWidth = 0.7f;

	private float sqrHeight = 0.8f;

	private float sqrFontMax = 9.5f;

	private float sqrFontMin = 3.35f;

	private float wideWidth = 1.685f;

	private float wideHeight = 0.7f;

	private float wideFontMax = 9.5f;

	private float wideFontMin = 4f;

	public abstract HeroActionButton Action { get; }

	public event IconUpdateEvent OnIconUpdate;

	private void Awake()
	{
		sr = GetComponent<SpriteRenderer>();
		uibs = UIManager.instance.uiButtonSkins;
	}

	protected virtual void OnEnable()
	{
		if (ih == null)
		{
			ih = GameManager.instance.inputHandler;
		}
		if (ih != null)
		{
			ih.RefreshActiveControllerEvent += RefreshController;
		}
		RefreshButtonIcon();
	}

	protected virtual void OnDisable()
	{
		if (ih != null)
		{
			ih.RefreshActiveControllerEvent -= RefreshController;
		}
	}

	protected void GetButtonIcon(HeroActionButton actionButton)
	{
		ButtonSkin buttonSkinFor = uibs.GetButtonSkinFor(actionButton);
		if (buttonSkinFor == null)
		{
			UnityEngine.Debug.LogError("Couldn't get button skin for " + actionButton, this);
			return;
		}
		sr.sprite = buttonSkinFor.sprite;
		if (textContainer != null)
		{
			if (buttonSkinFor.skinType == ButtonSkinType.BLANK)
			{
				textContainer.width = blnkWidth;
				textContainer.height = blnkHeight;
			}
			else if (buttonSkinFor.skinType == ButtonSkinType.SQUARE)
			{
				textContainer.width = sqrWidth;
				textContainer.height = sqrHeight;
			}
			else if (buttonSkinFor.skinType == ButtonSkinType.WIDE)
			{
				textContainer.width = wideWidth;
				textContainer.height = wideHeight;
			}
		}
		if (label != null)
		{
			if (buttonSkinFor.skinType == ButtonSkinType.BLANK)
			{
				label.fontSizeMin = blnkFontMin;
				label.fontSizeMax = blnkFontMax;
			}
			else if (buttonSkinFor.skinType == ButtonSkinType.SQUARE)
			{
				label.fontSizeMin = sqrFontMin;
				label.fontSizeMax = sqrFontMax;
			}
			else if (buttonSkinFor.skinType == ButtonSkinType.WIDE)
			{
				label.fontSizeMin = wideFontMin;
				label.fontSizeMax = wideFontMax;
			}
			label.text = buttonSkinFor.symbol;
		}
		if (OnIconUpdate != null)
		{
			OnIconUpdate();
		}
	}

	public void RefreshController()
	{
		if (liveUpdate)
		{
			RefreshButtonIcon();
		}
	}

	public void RefreshButtonIcon()
	{
		GetButtonIcon(Action);
	}
}
