public class CursorHighlight : MonoBehaviour
{
	private RectTransform myRect;

	private Vector2 startPos;

	private Vector2 targetPos;

	[UnityEngine.Tooltip("The time it takes for the cursor to move from one option to another.")]
	public float lerpTime = 1f;

	[UnityEngine.Tooltip("The wait period between the cursor moving from one option to another.")]
	public float cursorCooldown = 0.1f;

	private float lerpTimer;

	private float cooldownTimer;

	private bool coolingDown;

	public void Awake()
	{
		myRect = GetComponent<RectTransform>();
	}

	private void Start()
	{
		lerpTimer = lerpTime;
		cooldownTimer = 0f;
		startPos = myRect.anchoredPosition;
		targetPos = startPos;
		coolingDown = false;
	}

	private void Update()
	{
		if (coolingDown)
		{
			if (cooldownTimer > cursorCooldown)
			{
				coolingDown = false;
				cooldownTimer = 0f;
			}
			else
			{
				cooldownTimer += Time.deltaTime;
			}
			return;
		}
		if (lerpTimer > lerpTime)
		{
			lerpTimer = lerpTime;
			coolingDown = true;
		}
		else if (lerpTimer < lerpTime)
		{
			lerpTimer += Time.deltaTime;
		}
		float num = lerpTimer / lerpTime;
		num = num * num * (3f - 2f * num);
		myRect.anchoredPosition = Vector2.Lerp(startPos, targetPos, num);
	}

	public void MoveCursor(RectTransform buttonRect)
	{
		if (!coolingDown)
		{
			startPos = myRect.anchoredPosition;
			targetPos = buttonRect.anchoredPosition;
			lerpTimer = 0f;
		}
	}
}
public class DialogueBox : MonoBehaviour
{
	[Header("Conversation Info")]
	public string currentConversation;

	public int currentPage;

	[Header("Typewriter")]
	[UnityEngine.Tooltip("Enables the typewriter effect.")]
	public bool useTypeWriter;

	[Range(1f, 100f)]
	public float revealSpeed = 20f;

	private float normalRevealSpeed;

	private TextMeshPro textMesh;

	private PlayMakerFSM proxyFSM;

	private bool typing;

	private bool fastTyping;

	private bool hidden;

	private TMP_PageInfo[] pageInfo;

	private void Start()
	{
		textMesh = base.gameObject.GetComponent<TextMeshPro>();
		normalRevealSpeed = revealSpeed;
		HideText();
		proxyFSM = FSMUtility.LocateFSM(base.gameObject, "Dialogue Page Control");
		if (proxyFSM == null)
		{
			UnityEngine.Debug.LogWarning("DialogueBox: Couldn't find an FSM on this GameObject to use as a proxy, events will not be fired from this dialogue box.");
		}
	}

	public void SetConversation(string convName, string sheetName)
	{
		currentConversation = convName;
		currentPage = 1;
		textMesh.text = global::Language.Language.Get(convName, sheetName);
		textMesh.ForceMeshUpdate();
	}

	public void ShowPage(int pageNum)
	{
		if (pageNum < 1 || pageNum > textMesh.textInfo.pageCount)
		{
			SendConvEndEvent();
			return;
		}
		if (hidden)
		{
			hidden = false;
		}
		if (useTypeWriter)
		{
			if (typing)
			{
				StopTypewriter();
			}
			textMesh.pageToDisplay = pageNum;
			currentPage = pageNum;
			textMesh.maxVisibleCharacters = GetFirstCharIndexOnPage() - 1;
			string text = textMesh.text;
			text = text.Replace("<br>", "\n");
			textMesh.text = text;
			StartCoroutine("TypewriteCurrentPage");
		}
		else
		{
			textMesh.pageToDisplay = pageNum;
			currentPage = pageNum;
			textMesh.maxVisibleCharacters = GetLastCharIndexOnPage();
			SendEndEvent();
		}
	}

	public void ShowNextPage()
	{
		if (textMesh.pageToDisplay < textMesh.textInfo.pageCount)
		{
			ShowPage(currentPage + 1);
		}
	}

	public void ShowPrevPage()
	{
		if (textMesh.pageToDisplay > 1)
		{
			ShowPage(currentPage - 1);
		}
	}

	public void HideText()
	{
		if (typing)
		{
			StopTypewriter();
		}
		textMesh.maxVisibleCharacters = 0;
		hidden = true;
	}

	public void StartConversation(string convName, string sheetName)
	{
		SetConversation(convName, sheetName);
		ShowPage(1);
	}

	private IEnumerator TypewriteCurrentPage()
	{
		if (!typing)
		{
			InvokeRepeating("ShowNextChar", 0f, 1f / revealSpeed);
			typing = true;
		}
		while (typing)
		{
			if (textMesh.maxVisibleCharacters >= GetLastCharIndexOnPage())
			{
				StopTypewriter();
				SendEndEvent();
			}
			else
			{
				yield return null;
			}
		}
	}

	private void ShowNextChar()
	{
		textMesh.maxVisibleCharacters++;
	}

	private void StopTypewriter()
	{
		CancelInvoke("ShowNextChar");
		typing = false;
		fastTyping = false;
		revealSpeed = normalRevealSpeed;
	}

	public void SpeedupTypewriter()
	{
		if (typing && !fastTyping)
		{
			StopTypewriter();
			normalRevealSpeed = revealSpeed;
			revealSpeed = 200f;
			fastTyping = true;
			StartCoroutine(TypewriteCurrentPage());
		}
	}

	private void RestoreTypewriter()
	{
		revealSpeed = normalRevealSpeed;
	}

	private void SendEndEvent()
	{
		if (currentPage == textMesh.textInfo.pageCount)
		{
			SendConvEndEvent();
		}
		else
		{
			SendPageEndEvent();
		}
	}

	private void SendPageEndEvent()
	{
		if (proxyFSM != null)
		{
			proxyFSM.SendEvent("PAGE_END");
		}
	}

	private void SendConvEndEvent()
	{
		if (proxyFSM != null)
		{
			proxyFSM.SendEvent("CONVERSATION_END");
		}
	}

	private int GetFirstCharIndexOnPage()
	{
		return textMesh.textInfo.pageInfo[currentPage - 1].firstCharacterIndex + 1;
	}

	private int GetLastCharIndexOnPage()
	{
		return textMesh.textInfo.pageInfo[currentPage - 1].lastCharacterIndex + 1;
	}

	public void PrintPageInfo()
	{
		UnityEngine.Debug.LogFormat("PageInfo: Current Page: {0} Start: {1} End {2}", currentPage, GetFirstCharIndexOnPage(), GetLastCharIndexOnPage());
	}

	public void PrintPageInfoAll()
	{
		UnityEngine.Debug.LogFormat("PageInfo: Current conversation {0} contains {1} pages.\n", currentConversation, textMesh.textInfo.pageCount);
		for (int i = 0; i < textMesh.textInfo.pageCount; i++)
		{
			UnityEngine.Debug.LogFormat("[Page {0}] Start/End: {1}/{2}\n", i + 1, textMesh.textInfo.pageInfo[i].firstCharacterIndex, textMesh.textInfo.pageInfo[i].lastCharacterIndex);
		}
	}

	public void PrintCurrentConversation()
	{
		UnityEngine.Debug.LogFormat("Current conversation set to {0}\nClick this message to see the dialogue for this conversation.\n{1}", currentConversation, textMesh.text);
	}
}
