public class InvAnimateUpAndDown : MonoBehaviour
{
	public string upAnimation;

	public string downAnimation;

	public float upDelay;

	public int randomStartFrameSpriteMax;

	private tk2dSpriteAnimator spriteAnimator;

	private MeshRenderer meshRenderer;

	private float timer;

	private bool animatingDown;

	private bool readyingAnimUp;

	private void Awake()
	{
		spriteAnimator = GetComponent<tk2dSpriteAnimator>();
		meshRenderer = GetComponent<MeshRenderer>();
	}

	private void Update()
	{
		if (animatingDown && !spriteAnimator.Playing)
		{
			meshRenderer.enabled = false;
			animatingDown = false;
		}
		if (timer > 0f)
		{
			timer -= Time.deltaTime;
		}
		if (readyingAnimUp && timer <= 0f)
		{
			animatingDown = false;
			meshRenderer.enabled = true;
			if (randomStartFrameSpriteMax > 0)
			{
				int frame = UnityEngine.Random.Range(0, randomStartFrameSpriteMax);
				spriteAnimator.PlayFromFrame(upAnimation, frame);
			}
			else
			{
				spriteAnimator.Play(upAnimation);
			}
			readyingAnimUp = false;
		}
	}

	public void AnimateUp()
	{
		readyingAnimUp = true;
		timer = upDelay;
	}

	public void AnimateDown()
	{
		spriteAnimator.Play(downAnimation);
		animatingDown = true;
	}

	public void ReplayUpAnim()
	{
		meshRenderer.enabled = true;
		spriteAnimator.PlayFromFrame(0);
	}
}
public class InvCharmBackboard : MonoBehaviour
{
	public GameObject charmObject;

	public GameObject newOrb;

	public int charmNum;

	public string charmNumString;

	public string gotCharmString;

	public string newCharmString;

	public Sprite blankSprite;

	public Sprite activeSprite;

	private bool positionedCharm;

	private PlayerData playerData;

	private GameObject orb;

	private SpriteRenderer spriteRenderer;

	private bool blanked;

	private void Awake()
	{
		spriteRenderer = GetComponent<SpriteRenderer>();
	}

	private void OnEnable()
	{
		if (!positionedCharm)
		{
			charmObject.transform.localPosition = new Vector3(base.transform.localPosition.x, base.transform.localPosition.y, base.transform.localPosition.z - 0.001f);
			positionedCharm = true;
		}
		if (playerData == null)
		{
			playerData = PlayerData.instance;
		}
		if (playerData.GetBool(gotCharmString) && playerData.GetBool(newCharmString))
		{
			newOrb.SetActive(value: true);
		}
		if (playerData.GetBool(gotCharmString) && !blanked)
		{
			spriteRenderer.sprite = blankSprite;
			blanked = true;
		}
		if (!playerData.GetBool(gotCharmString) && blanked)
		{
			spriteRenderer.sprite = activeSprite;
			blanked = false;
		}
	}

	public void SelectCharm()
	{
		if (playerData.GetBool(newCharmString))
		{
			playerData.SetBool(newCharmString, value: false);
			newOrb.GetComponent<SimpleFadeOut>().FadeOut();
		}
	}

	public int GetCharmNum()
	{
		return charmNum;
	}

	public string GetCharmString()
	{
		return gotCharmString;
	}

	public string GetCharmNumString()
	{
		return charmNumString;
	}
