	[SerializeField]
	private float labelRightInset;

	protected void Start()
	{
		Setup();
		InputHandler.Instance.RefreshActiveControllerEvent += Setup;
	}

	private void OnDestroy()
	{
		InputHandler.Instance.RefreshActiveControllerEvent -= Setup;
