public class LoadingCanvas : MonoBehaviour
{
	[SerializeField]
	[ArrayForEnum(typeof(GameManager.SceneLoadVisualizations))]
	private GameObject[] visualizationContainers;

	private bool isLoading;

	private GameManager.SceneLoadVisualizations loadingVisualization;

	[SerializeField]
	private LoadingSpinner defaultLoadingSpinner;

	[SerializeField]
	private float continueFromSaveDelayAdjustment;

	protected void Start()
	{
		for (int i = 0; i < visualizationContainers.Length; i++)
		{
			GameObject gameObject = visualizationContainers[i];
			if (!(gameObject == null))
			{
				gameObject.SetActive(value: false);
			}
		}
	}

	protected void Update()
	{
		GameManager unsafeInstance = GameManager.UnsafeInstance;
		if (!(unsafeInstance != null) || isLoading == unsafeInstance.IsLoadingSceneTransition)
		{
			return;
		}
		isLoading = unsafeInstance.IsLoadingSceneTransition;
		if (!isLoading)
		{
			return;
		}
		defaultLoadingSpinner.DisplayDelayAdjustment = ((unsafeInstance.LoadVisualization == GameManager.SceneLoadVisualizations.ContinueFromSave) ? continueFromSaveDelayAdjustment : 0f);
		GameObject gameObject = null;
		if (unsafeInstance.LoadVisualization >= GameManager.SceneLoadVisualizations.Default && (int)unsafeInstance.LoadVisualization < visualizationContainers.Length)
		{
			gameObject = visualizationContainers[(int)unsafeInstance.LoadVisualization];
		}
		for (int i = 0; i < visualizationContainers.Length; i++)
		{
			GameObject gameObject2 = visualizationContainers[i];
			if (!(gameObject2 == null))
			{
				gameObject2.SetActive(gameObject2 == gameObject);
			}
		}
	}
}
public class LoadingPulse : MonoBehaviour
{
	public Color pulseColor;

	public float pulseDuration;

	private Image sprite;

	private Color normalColor;

	private bool pulsing;

	private bool reverse;

	private float currentLerpTime;

	private void Start()
	{
		sprite = GetComponent<Image>();
		normalColor = sprite.color;
		pulsing = true;
		currentLerpTime = 0f;
	}

	private void Update()
	{
		if (!pulsing)
		{
			return;
		}
		if (!reverse)
		{
			currentLerpTime += Time.deltaTime;
			if (currentLerpTime > pulseDuration)
			{
				currentLerpTime = pulseDuration;
				reverse = true;
			}
		}
		else
		{
			currentLerpTime -= Time.deltaTime;
			if (currentLerpTime < 0f)
			{
				currentLerpTime = 0f;
				reverse = false;
			}
		}
		float t = currentLerpTime / pulseDuration;
		sprite.color = Color.Lerp(normalColor, pulseColor, t);
	}
}
public class LoadingSpinner : MonoBehaviour
{
	[SerializeField]
	private Image image;

	[SerializeField]
	private float displayDelay;

	[SerializeField]
	private float fadeDuration;

	[SerializeField]
	private float fadeAmount;

	[SerializeField]
	private float fadeVariance;

	[SerializeField]
	private float fadePulseDuration;

	[SerializeField]
	private Sprite[] sprites;

	[SerializeField]
	private float frameRate;

	private float fadeFactor;

	private float frameTimer;

	private int frameIndex;

	private float displayDelayAdjustment;

	public float DisplayDelayAdjustment
	{
		get
		{
			return displayDelayAdjustment;
		}
		set
		{
			displayDelayAdjustment = value;
		}
	}

	public float DisplayDelay => displayDelay + displayDelayAdjustment;

	protected void OnEnable()
	{
		fadeFactor = 0f;
	}

	protected void Start()
	{
		image.color = new Color(1f, 1f, 1f, 0f);
		image.enabled = false;
		fadeFactor = 0f;
	}

	protected void Update()
	{
		float num = Mathf.Max(1f / 60f, Time.unscaledDeltaTime);
		GameManager unsafeInstance = GameManager.UnsafeInstance;
		if (unsafeInstance != null)
		{
			float target = ((unsafeInstance.CurrentLoadDuration > DisplayDelay && !unsafeInstance.IsUsingCustomLoadAnimation) ? 1f : 0f);
			fadeFactor = Mathf.MoveTowards(fadeFactor, target, num / fadeDuration);
			if (fadeFactor < Mathf.Epsilon)
			{
				if (image.enabled)
				{
					image.enabled = false;
				}
			}
			else
			{
				if (!image.enabled)
				{
					image.enabled = true;
				}
				image.color = new Color(1f, 1f, 1f, fadeFactor * (fadeAmount + fadeVariance * Mathf.Sin(unsafeInstance.CurrentLoadDuration * (float)Math.PI * 2f / fadePulseDuration)));
			}
		}
		if (sprites.Length != 0)
		{
			frameTimer += num * frameRate;
			int num2 = (int)frameTimer;
			if (num2 > 0)
			{
				frameTimer -= num2;
				frameIndex = (frameIndex + num2) % sprites.Length;
				image.sprite = sprites[frameIndex];
			}
		}
	}
}
