	private long buildTime;

	private static bool didLoad;

	private static BuildMetadata embedded;

	public const string EmbeddedFileName = "BuildMetadata.json";

	public string BranchName => branchName;

	public string Revision => revision;

	public DateTime CommitTime => DateTime.FromBinary(commitTime);

	public string MachineName => machineName;

	public DateTime BuildTime => DateTime.FromBinary(buildTime);

	public static BuildMetadata Embedded
	{
		get
		{
			if (!didLoad)
			{
				didLoad = true;
				try
				{
					BuildMetadata objectToOverwrite = new BuildMetadata();
					JsonUtility.FromJsonOverwrite(File.ReadAllText(Path.Combine(Application.streamingAssetsPath, "BuildMetadata.json")), objectToOverwrite);
					embedded = objectToOverwrite;
				}
				catch (FileNotFoundException)
				{
				}
				catch (Exception exception)
				{
					UnityEngine.Debug.LogException(exception);
				}
			}
			return embedded;
		}
	}

	public static BuildMetadata Create(string branchName, string revision, DateTime commitTime, string machineName, DateTime buildTime)
	{
		return new BuildMetadata
		{
			branchName = branchName,
			revision = revision,
			commitTime = commitTime.ToBinary(),
			machineName = machineName,
			buildTime = buildTime.ToBinary()
		};
	}
}
public static class Collision2DUtils
{
	public struct Collision2DSafeContact
	{
		public Vector2 Point;

		public Vector2 Normal;

		public bool IsLegitimate;
	}

	private static ContactPoint2D[] contactsBuffer = new ContactPoint2D[1];

	public static Collision2DSafeContact GetSafeContact(this Collision2D collision)
	{
		if (collision.GetContacts(contactsBuffer) >= 1)
		{
			ContactPoint2D contactPoint2D = contactsBuffer[0];
			return new Collision2DSafeContact
			{
				Point = contactPoint2D.point,
				Normal = contactPoint2D.normal,
				IsLegitimate = true
			};
		}
		Vector2 vector = collision.collider.transform.TransformPoint(collision.collider.offset);
		Vector2 vector2 = collision.otherCollider.transform.TransformPoint(collision.otherCollider.offset);
		return new Collision2DSafeContact
		{
			Point = (vector2 + vector) * 0.5f,
			Normal = (vector2 - vector).normalized,
			IsLegitimate = false
		};
	}
}
public static class CommandLineArguments
{
	private const StringComparison ArgumentComparison = StringComparison.OrdinalIgnoreCase;

	private const string ShowPerformanceHUDFlag = "--show-performance-hud";

	private const string RemoteSaveDirectoryPrefix = "--remote-save-directory=";

	private const string EnableDeveloperCheatsFlag = "--enable-developer-cheats";

	public static bool ShowPerformanceHUD { get; private set; }

	public static string RemoteSaveDirectory { get; private set; }

	public static bool EnableDeveloperCheats { get; private set; }

	static CommandLineArguments()
	{
		if (Application.isEditor)
		{
			return;
		}
		string[] commandLineArgs = Environment.GetCommandLineArgs();
		if (commandLineArgs == null)
		{
			return;
		}
		foreach (string text in commandLineArgs)
		{
			if (text.Equals("--show-performance-hud", StringComparison.OrdinalIgnoreCase))
			{
				ShowPerformanceHUD = true;
			}
			else if (text.Equals("--enable-developer-cheats", StringComparison.OrdinalIgnoreCase))
			{
				EnableDeveloperCheats = true;
			}
			else if (text.StartsWith("--remote-save-directory=", StringComparison.OrdinalIgnoreCase))
			{
				RemoteSaveDirectory = text.Substring("--remote-save-directory=".Length);
			}
		}
	}
}
