public static class StaticVariableList
{
	public static Dictionary<string, object> variables;

	public static void Clear()
	{
		if (variables != null)
		{
			variables.Clear();
		}
	}

	public static void SetValue<T>(string variableName, T value)
	{
		if (variables == null)
		{
			variables = new Dictionary<string, object>();
		}
		variables[variableName] = value;
	}

	public static T GetValue<T>(string variableName)
	{
		if (variables == null || !variables.ContainsKey(variableName))
		{
			UnityEngine.Debug.LogError($"Attempt to get {variableName} from static variable list failed!");
			return default(T);
		}
		return (T)variables[variableName];
	}

	public static bool Exists(string variableName)
	{
		if (variables == null)
		{
			return false;
		}
		return variables.ContainsKey(variableName);
	}
}
public class SetStaticVariable : FsmStateAction
{
	public FsmString variableName;

	public FsmVar setValue;

	public override void Reset()
	{
		variableName = null;
		setValue = null;
	}

	public override void OnEnter()
	{
		if (!variableName.IsNone && !setValue.IsNone)
		{
			_ = setValue.RealType;
			object valueFromFsmVar = PlayMakerUtils.GetValueFromFsmVar(base.Fsm, setValue);
			switch (setValue.Type)
			{
			case VariableType.Bool:
				StaticVariableList.SetValue(variableName.Value, (bool)valueFromFsmVar);
				break;
			case VariableType.Int:
				StaticVariableList.SetValue(variableName.Value, (int)valueFromFsmVar);
				break;
			case VariableType.Float:
				StaticVariableList.SetValue(variableName.Value, (float)valueFromFsmVar);
				break;
			case VariableType.String:
				StaticVariableList.SetValue(variableName.Value, (string)valueFromFsmVar);
				break;
			default:
				UnityEngine.Debug.LogWarning($"Couldn't set static variable: {variableName.Value}, Variable type \"{setValue.Type.ToString()}\" not implemented!");
				break;
			}
		}
		else
		{
			UnityEngine.Debug.LogWarning($"Couldn't set static variable: {variableName.Value}");
		}
		Finish();
	}
}
