public class StringEncrypt
{
	private static byte[] keyArray = Encoding.UTF8.GetBytes("UKu52ePUBwetZ9wNX88o54dnfKRu0T1l");

	public static string EncryptData(string toEncrypt)
	{
		byte[] bytes = Encoding.UTF8.GetBytes(toEncrypt);
		byte[] array = new RijndaelManaged
		{
			Key = keyArray,
			Mode = CipherMode.ECB,
			Padding = PaddingMode.PKCS7
		}.CreateEncryptor().TransformFinalBlock(bytes, 0, bytes.Length);
		return Convert.ToBase64String(array, 0, array.Length);
	}

	public static string DecryptData(string toDecrypt)
	{
		byte[] array = Convert.FromBase64String(toDecrypt);
		byte[] bytes = new RijndaelManaged
		{
			Key = keyArray,
			Mode = CipherMode.ECB,
			Padding = PaddingMode.PKCS7
		}.CreateDecryptor().TransformFinalBlock(array, 0, array.Length);
		return Encoding.UTF8.GetString(bytes);
	}
}
public class TimeScaleIndependentUpdate : MonoBehaviour
{
	private float previousTimeSinceStartup;

	public float deltaTime { get; private set; }

	protected virtual void Awake()
	{
		previousTimeSinceStartup = Time.realtimeSinceStartup;
	}

	protected virtual void Update()
	{
		float realtimeSinceStartup = Time.realtimeSinceStartup;
		deltaTime = realtimeSinceStartup - previousTimeSinceStartup;
		previousTimeSinceStartup = realtimeSinceStartup;
		if (deltaTime < 0f)
		{
			deltaTime = 0f;
		}
	}

	public IEnumerator TimeScaleIndependentWaitForSeconds(float seconds)
	{
		for (float elapsedTime = 0f; elapsedTime < seconds; elapsedTime += deltaTime)
		{
			yield return null;
		}
	}
}
public static class TimeUtility
{
	public static IEnumerator Wait(float duration)
	{
		for (float timer = 0f; timer < duration; timer += Time.deltaTime)
		{
			yield return null;
		}
	}

	public static IEnumerator WaitForRealSeconds(float time)
	{
		float start = Time.realtimeSinceStartup;
		while (Time.realtimeSinceStartup < start + time)
		{
			yield return null;
		}
	}
}
