[ActionCategory("Hollow Knight")]
public class PlayVibration : FsmStateAction
{
	[ObjectType(typeof(LowFidelityVibrations))]
	public FsmEnum lowFidelityVibration;

	[ObjectType(typeof(TextAsset))]
	public FsmObject highFidelityVibration;

	[ObjectType(typeof(VibrationMotors))]
	public FsmEnum motors;

	public FsmFloat loopTime;

	public FsmBool isLooping;

	public FsmString tag;

	[ObjectType(typeof(GamepadVibration))]
	public FsmObject gamepadVibration;

	private float cooldownTimer;

	public override void Reset()
	{
		base.Reset();
		lowFidelityVibration = new FsmEnum
		{
			UseVariable = false
		};
		highFidelityVibration = new FsmObject
		{
			UseVariable = false
		};
		motors = new FsmEnum
		{
			UseVariable = false,
			Value = VibrationMotors.All
		};
		loopTime = new FsmFloat
		{
			UseVariable = true
		};
	}

	public override void OnEnter()
	{
		base.OnEnter();
		Play(loop: false);
		EnqueueNextLoop();
	}

	private void Play(bool loop)
	{
		VibrationMotors vibrationMotors = VibrationMotors.All;
		if (!motors.IsNone)
		{
			vibrationMotors = (VibrationMotors)(object)motors.Value;
		}
		VibrationManager.PlayVibrationClipOneShot(VibrationData.Create((LowFidelityVibrations)(object)lowFidelityVibration.Value, highFidelityVibration.Value as TextAsset, gamepadVibration.Value as GamepadVibration), new VibrationTarget(vibrationMotors), loop, tag.Value ?? "");
	}

	public override void OnUpdate()
	{
		base.OnUpdate();
		cooldownTimer -= Time.deltaTime;
		if (cooldownTimer <= 0f)
		{
			Play(loop: false);
			EnqueueNextLoop();
		}
	}

	private void EnqueueNextLoop()
	{
		float num = 0f;
		if (!loopTime.IsNone)
		{
			num = loopTime.Value;
		}
		if (num < Mathf.Epsilon)
		{
			Finish();
		}
		else
		{
			cooldownTimer = num;
		}
	}
}
[ActionCategory("Hollow Knight")]
public class StopVibration : FsmStateAction
{
	private FsmString fsmTag;

	public override void Reset()
	{
		base.Reset();
		fsmTag = new FsmString
		{
			UseVariable = true
		};
	}

	public override void OnEnter()
	{
		base.OnEnter();
		if (fsmTag == null || fsmTag.IsNone || string.IsNullOrEmpty(fsmTag.Value))
		{
			VibrationManager.StopAllVibration();
		}
		else
		{
			VibrationManager.GetMixer()?.StopAllEmissionsWithTag(fsmTag.Value);
		}
		Finish();
	}
}
public static class VibrationManager
{
	public interface IVibrationMixerProvider
	{
		VibrationMixer GetVibrationMixer();
	}

	private static bool isMuted;

	public static bool IsMuted
	{
		get
		{
			return isMuted;
		}
		set
		{
			if (isMuted != value)
			{
				isMuted = value;
				if (isMuted)
				{
					StopAllVibration();
				}
			}
		}
	}

	public static VibrationMixer GetMixer()
	{
		Platform current = Platform.Current;
		if (current != null && current is IVibrationMixerProvider vibrationMixerProvider)
		{
			VibrationMixer vibrationMixer = vibrationMixerProvider.GetVibrationMixer();
			if (vibrationMixer != null)
			{
				return vibrationMixer;
			}
		}
		InputDevice activeDevice = InputManager.ActiveDevice;
		if (activeDevice != null && activeDevice.IsAttached && activeDevice is IVibrationMixerProvider vibrationMixerProvider2)
		{
			VibrationMixer vibrationMixer2 = vibrationMixerProvider2.GetVibrationMixer();
			if (vibrationMixer2 != null)
			{
				return vibrationMixer2;
			}
		}
		return null;
	}

	public static VibrationEmission PlayVibrationClipOneShot(VibrationData vibrationData, VibrationTarget? vibrationTarget = null, bool isLooping = false, string tag = "")
	{
		if (isMuted)
		{
			return null;
		}
		return GetMixer()?.PlayEmission(vibrationData, vibrationTarget ?? new VibrationTarget(VibrationMotors.All), isLooping, tag);
	}

	public static void StopAllVibration()
	{
		if (!isMuted)
		{
			GetMixer()?.StopAllEmissions();
		}
	}

	public static void StopAllVibrationsWithTag(string tag)
	{
		if (!isMuted)
		{
			GetMixer()?.StopAllEmissionsWithTag(tag);
		}
	}
}
