[DisallowMultipleComponent]
public class LiftChain : MonoBehaviour
{
	private tk2dSpriteAnimator[] spriteAnimators;

	private int currentDirection;

	protected void Awake()
	{
		spriteAnimators = GetComponentsInChildren<tk2dSpriteAnimator>();
		currentDirection = 0;
	}

	public void GoDown()
	{
		UnityEngine.Debug.LogFormat(this, "Chain {0} going down.", base.name);
		for (int i = 0; i < spriteAnimators.Length; i++)
		{
			tk2dSpriteAnimator tk2dSpriteAnimator2 = spriteAnimators[i];
			tk2dSpriteAnimator2.Resume();
			if (currentDirection != -1)
			{
				tk2dSpriteAnimator2.Play("Chain Down");
			}
		}
		currentDirection = -1;
	}

	public void GoUp()
	{
		UnityEngine.Debug.LogFormat(this, "Chain {0} going up.", base.name);
		for (int i = 0; i < spriteAnimators.Length; i++)
		{
			tk2dSpriteAnimator tk2dSpriteAnimator2 = spriteAnimators[i];
			tk2dSpriteAnimator2.Resume();
			if (currentDirection != 1)
			{
				tk2dSpriteAnimator2.Play("Chain Up");
			}
		}
		currentDirection = 1;
	}

	public void Stop()
	{
		UnityEngine.Debug.LogFormat(this, "Chain {0} stopping.", base.name);
		for (int i = 0; i < spriteAnimators.Length; i++)
		{
			spriteAnimators[i].Pause();
		}
	}
}
[ActionCategory("Hollow Knight")]
public abstract class LiftChainAction : FsmStateAction
{
	public FsmOwnerDefault target;

	public bool everyFrame;

	private LiftChain liftChain;

	public override void Reset()
	{
		base.Reset();
		target = new FsmOwnerDefault();
		everyFrame = false;
	}

	public override void OnEnter()
	{
		base.OnEnter();
		GameObject safe = target.GetSafe(this);
		if (safe != null)
		{
			liftChain = safe.GetComponent<LiftChain>();
			if (liftChain != null)
			{
				Apply(liftChain);
			}
		}
		else
		{
			liftChain = null;
		}
		if (!everyFrame)
		{
			Finish();
		}
	}

	public override void OnUpdate()
