					if (num3 > 0f)
					{
						num3 = 0f;
						num2 = 0f;
						stringBuilder.Remove(num4 + 1, stringBuilder.Length - num4 - 1);
						stringBuilder.Append('\n');
						i = num5;
						continue;
					}
					stringBuilder.Append('\n');
					num2 = (tk2dFontChar2.advance + data.spacing) * data.scale.x;
				}
				else
				{
					num2 += (tk2dFontChar2.advance + data.spacing) * data.scale.x;
				}
				break;
			}
			stringBuilder.Append(c);
		}
		_targetString = stringBuilder.ToString();
	}

	private void SetNeedUpdate(UpdateFlags uf)
	{
		if (updateFlags == UpdateFlags.UpdateNone)
		{
			updateFlags |= uf;
			tk2dUpdateManager.QueueCommit(this);
		}
		else
		{
			updateFlags |= uf;
		}
	}

	private void InitInstance()
	{
		if (data != null && data.font != null)
		{
			_fontInst = data.font.inst;
			_fontInst.InitDictionary();
		}
	}

	private void Awake()
	{
		UpgradeData();
		if (data.font != null)
		{
			_fontInst = data.font.inst;
		}
		updateFlags = UpdateFlags.UpdateBuffers;
		if (data.font != null)
		{
			Init();
			UpdateMaterial();
		}
		updateFlags = UpdateFlags.UpdateNone;
	}

	protected void OnDestroy()
	{
		if (meshFilter == null)
		{
			meshFilter = GetComponent<MeshFilter>();
		}
		if (meshFilter != null)
		{
			mesh = meshFilter.sharedMesh;
		}
		if ((bool)mesh)
		{
			UnityEngine.Object.DestroyImmediate(mesh, allowDestroyingAssets: true);
			meshFilter.mesh = null;
		}
	}

	public int NumDrawnCharacters()
	{
		int num = NumTotalCharacters();
		if (num > data.maxChars)
		{
			num = data.maxChars;
		}
		return num;
	}

	public int NumTotalCharacters()
	{
		InitInstance();
		if ((updateFlags & (UpdateFlags.UpdateText | UpdateFlags.UpdateBuffers)) != UpdateFlags.UpdateNone)
		{
			FormatText();
		}
		int num = 0;
		for (int i = 0; i < _formattedText.Length; i++)
		{
			int num2 = _formattedText[i];
			bool num3 = num2 == 94;
			if (_fontInst.useDictionary)
			{
				if (!_fontInst.charDict.ContainsKey(num2))
				{
					num2 = 0;
				}
			}
			else if (num2 >= _fontInst.chars.Length)
			{
				num2 = 0;
			}
			if (num3)
			{
				num2 = 94;
			}
			if (num2 == 10)
			{
				continue;
			}
			if (data.inlineStyling && num2 == 94 && i + 1 < _formattedText.Length)
			{
				if (_formattedText[i + 1] != '^')
				{
					i += GetInlineStyleCommandLength(_formattedText[i + 1]);
					continue;
				}
				i++;
			}
			num++;
		}
		return num;
	}

	[Obsolete("Use GetEstimatedMeshBoundsForString().size instead")]
	public Vector2 GetMeshDimensionsForString(string str)
	{
		return tk2dTextGeomGen.GetMeshDimensionsForString(str, tk2dTextGeomGen.Data(data, _fontInst, _formattedText));
	}

	public UnityEngine.Bounds GetEstimatedMeshBoundsForString(string str)
	{
		InitInstance();
		tk2dTextGeomGen.GeomData geomData = tk2dTextGeomGen.Data(data, _fontInst, _formattedText);
		Vector2 meshDimensionsForString = tk2dTextGeomGen.GetMeshDimensionsForString(FormatText(str), geomData);
		float yAnchorForHeight = tk2dTextGeomGen.GetYAnchorForHeight(meshDimensionsForString.y, geomData);
		float xAnchorForWidth = tk2dTextGeomGen.GetXAnchorForWidth(meshDimensionsForString.x, geomData);
		float num = (_fontInst.lineHeight + data.lineSpacing) * data.scale.y;
		return new UnityEngine.Bounds(new Vector3(xAnchorForWidth + meshDimensionsForString.x * 0.5f, yAnchorForHeight + meshDimensionsForString.y * 0.5f + num, 0f), Vector3.Scale(meshDimensionsForString, new Vector3(1f, -1f, 1f)));
	}

	public void Init(bool force)
	{
		if (force)
		{
			SetNeedUpdate(UpdateFlags.UpdateBuffers);
		}
		Init();
	}

	public void Init()
	{
		if (!_fontInst || ((updateFlags & UpdateFlags.UpdateBuffers) == 0 && !(mesh == null)))
		{
			return;
		}
		_fontInst.InitDictionary();
		FormatText();
		tk2dTextGeomGen.GeomData geomData = tk2dTextGeomGen.Data(data, _fontInst, _formattedText);
		tk2dTextGeomGen.GetTextMeshGeomDesc(out var numVertices, out var numIndices, geomData);
		vertices = new Vector3[numVertices];
		uvs = new Vector2[numVertices];
		colors = new Color32[numVertices];
		untintedColors = new Color32[numVertices];
		if (_fontInst.textureGradients)
		{
			uv2 = new Vector2[numVertices];
		}
		int[] array = new int[numIndices];
		int target = tk2dTextGeomGen.SetTextMeshGeom(vertices, uvs, uv2, untintedColors, 0, geomData);
		if (!_fontInst.isPacked)
		{
			Color32 color = data.color;
			Color32 color2 = (data.useGradient ? data.color2 : data.color);
			for (int i = 0; i < numVertices; i++)
			{
				Color32 color3 = ((i % 4 < 2) ? color : color2);
				byte b = (byte)(untintedColors[i].r * color3.r / 255);
				byte b2 = (byte)(untintedColors[i].g * color3.g / 255);
				byte b3 = (byte)(untintedColors[i].b * color3.b / 255);
				byte b4 = (byte)(untintedColors[i].a * color3.a / 255);
				if (_fontInst.premultipliedAlpha)
				{
					b = (byte)(b * b4 / 255);
					b2 = (byte)(b2 * b4 / 255);
					b3 = (byte)(b3 * b4 / 255);
				}
				colors[i] = new Color32(b, b2, b3, b4);
			}
		}
		else
		{
			colors = untintedColors;
		}
		tk2dTextGeomGen.SetTextMeshIndices(array, 0, 0, geomData, target);
		if (mesh == null)
		{
			if (meshFilter == null)
			{
				meshFilter = GetComponent<MeshFilter>();
			}
			mesh = new Mesh();
			mesh.MarkDynamic();
			mesh.hideFlags = HideFlags.DontSave;
			meshFilter.mesh = mesh;
		}
		else
		{
			mesh.Clear();
		}
		mesh.vertices = vertices;
		mesh.uv = uvs;
		if (font.textureGradients)
		{
			mesh.uv2 = uv2;
		}
		mesh.triangles = array;
		mesh.colors32 = colors;
		mesh.RecalculateBounds();
		mesh.bounds = tk2dBaseSprite.AdjustedMeshBounds(mesh.bounds, data.renderLayer);
		updateFlags = UpdateFlags.UpdateNone;
	}

	public void Commit()
	{
		tk2dUpdateManager.FlushQueues();
	}

	public void DoNotUse__CommitInternal()
	{
		InitInstance();
		if (_fontInst == null)
		{
			return;
		}
		_fontInst.InitDictionary();
		if ((updateFlags & UpdateFlags.UpdateBuffers) != UpdateFlags.UpdateNone || mesh == null)
		{
			Init();
		}
		else
		{
			if ((updateFlags & UpdateFlags.UpdateText) != UpdateFlags.UpdateNone)
			{
				FormatText();
				tk2dTextGeomGen.GeomData geomData = tk2dTextGeomGen.Data(data, _fontInst, _formattedText);
				for (int i = tk2dTextGeomGen.SetTextMeshGeom(vertices, uvs, uv2, untintedColors, 0, geomData); i < data.maxChars; i++)
				{
					vertices[i * 4] = (vertices[i * 4 + 1] = (vertices[i * 4 + 2] = (vertices[i * 4 + 3] = Vector3.zero)));
				}
				mesh.vertices = vertices;
				mesh.uv = uvs;
				if (_fontInst.textureGradients)
				{
					mesh.uv2 = uv2;
				}
				if (_fontInst.isPacked)
				{
					colors = untintedColors;
					mesh.colors32 = colors;
				}
				if (data.inlineStyling)
				{
					SetNeedUpdate(UpdateFlags.UpdateColors);
				}
				mesh.RecalculateBounds();
				mesh.bounds = tk2dBaseSprite.AdjustedMeshBounds(mesh.bounds, data.renderLayer);
			}
			if (!font.isPacked && (updateFlags & UpdateFlags.UpdateColors) != UpdateFlags.UpdateNone)
			{
				Color32 color = data.color;
				Color32 color2 = (data.useGradient ? data.color2 : data.color);
				for (int j = 0; j < colors.Length; j++)
				{
					Color32 color3 = ((j % 4 < 2) ? color : color2);
					byte b = (byte)(untintedColors[j].r * color3.r / 255);
					byte b2 = (byte)(untintedColors[j].g * color3.g / 255);
					byte b3 = (byte)(untintedColors[j].b * color3.b / 255);
					byte b4 = (byte)(untintedColors[j].a * color3.a / 255);
					if (_fontInst.premultipliedAlpha)
					{
						b = (byte)(b * b4 / 255);
						b2 = (byte)(b2 * b4 / 255);
						b3 = (byte)(b3 * b4 / 255);
					}
					colors[j] = new Color32(b, b2, b3, b4);
				}
				mesh.colors32 = colors;
			}
		}
		updateFlags = UpdateFlags.UpdateNone;
	}

	public void MakePixelPerfect()
	{
		float num = 1f;
		tk2dCamera tk2dCamera2 = tk2dCamera.CameraForLayer(base.gameObject.layer);
		if (tk2dCamera2 != null)
		{
			if (_fontInst.version < 1)
			{
				UnityEngine.Debug.LogError("Need to rebuild font.");
			}
			float distance = base.transform.position.z - tk2dCamera2.transform.position.z;
			float num2 = _fontInst.invOrthoSize * _fontInst.halfTargetHeight;
			num = tk2dCamera2.GetSizeAtDistance(distance) * num2;
		}
		else if ((bool)Camera.main)
		{
			if (Camera.main.orthographic)
			{
				num = Camera.main.orthographicSize;
			}
			else
			{
				float zdist = base.transform.position.z - Camera.main.transform.position.z;
				num = tk2dPixelPerfectHelper.CalculateScaleForPerspectiveCamera(Camera.main.fieldOfView, zdist);
			}
			num *= _fontInst.invOrthoSize;
		}
		scale = new Vector3(Mathf.Sign(scale.x) * num, Mathf.Sign(scale.y) * num, Mathf.Sign(scale.z) * num);
	}

	public bool UsesSpriteCollection(tk2dSpriteCollectionData spriteCollection)
	{
		if (data.font != null && data.font.spriteCollection != null)
		{
			return data.font.spriteCollection == spriteCollection;
		}
		return true;
	}

	private void UpdateMaterial()
	{
		if (GetComponent<Renderer>().sharedMaterial != _fontInst.materialInst)
		{
			GetComponent<Renderer>().material = _fontInst.materialInst;
		}
	}

	public void ForceBuild()
	{
		if (data.font != null)
		{
			_fontInst = data.font.inst;
			UpdateMaterial();
		}
		Init(force: true);
	}
}
[AddComponentMenu("2D Toolkit/Deprecated/GUI/tk2dButton")]
public class tk2dButton : MonoBehaviour
{
	public delegate void ButtonHandlerDelegate(tk2dButton source);

	public Camera viewCamera;

	public string buttonDownSprite = "button_down";

	public string buttonUpSprite = "button_up";

	public string buttonPressedSprite = "button_up";

	private int buttonDownSpriteId = -1;

	private int buttonUpSpriteId = -1;

	private int buttonPressedSpriteId = -1;

	public AudioClip buttonDownSound;

	public AudioClip buttonUpSound;

	public AudioClip buttonPressedSound;

	public GameObject targetObject;

	public string messageName = "";

	private tk2dBaseSprite sprite;

	private bool buttonDown;

	public float targetScale = 1.1f;

	public float scaleTime = 0.05f;

	public float pressedWaitTime = 0.3f;

	public event ButtonHandlerDelegate ButtonPressedEvent;

	public event ButtonHandlerDelegate ButtonAutoFireEvent;

	public event ButtonHandlerDelegate ButtonDownEvent;

	public event ButtonHandlerDelegate ButtonUpEvent;

	private void OnEnable()
	{
		buttonDown = false;
	}

	private void Start()
	{
		if (viewCamera == null)
		{
			Transform parent = base.transform;
			while ((bool)parent && parent.GetComponent<Camera>() == null)
			{
				parent = parent.parent;
			}
			if ((bool)parent && parent.GetComponent<Camera>() != null)
			{
				viewCamera = parent.GetComponent<Camera>();
			}
			if (viewCamera == null && (bool)tk2dCamera.Instance)
			{
				viewCamera = tk2dCamera.Instance.GetComponent<Camera>();
			}
			if (viewCamera == null)
			{
				viewCamera = Camera.main;
			}
		}
		sprite = GetComponent<tk2dBaseSprite>();
		if ((bool)sprite)
		{
			UpdateSpriteIds();
		}
		if (GetComponent<Collider>() == null)
		{
			BoxCollider boxCollider = base.gameObject.AddComponent<BoxCollider>();
			Vector3 size = boxCollider.size;
			size.z = 0.2f;
			boxCollider.size = size;
		}
		if ((buttonDownSound != null || buttonPressedSound != null || buttonUpSound != null) && GetComponent<AudioSource>() == null)
		{
			base.gameObject.AddComponent<AudioSource>().playOnAwake = false;
		}
	}

	public void UpdateSpriteIds()
	{
		buttonDownSpriteId = ((buttonDownSprite.Length > 0) ? sprite.GetSpriteIdByName(buttonDownSprite) : (-1));
		buttonUpSpriteId = ((buttonUpSprite.Length > 0) ? sprite.GetSpriteIdByName(buttonUpSprite) : (-1));
		buttonPressedSpriteId = ((buttonPressedSprite.Length > 0) ? sprite.GetSpriteIdByName(buttonPressedSprite) : (-1));
	}

	private void PlaySound(AudioClip source)
	{
		if ((bool)GetComponent<AudioSource>() && (bool)source)
		{
			GetComponent<AudioSource>().PlayOneShot(source);
		}
	}

	private IEnumerator coScale(Vector3 defaultScale, float startScale, float endScale)
	{
		float t0 = Time.realtimeSinceStartup;
		for (float num = 0f; num < scaleTime; num = Time.realtimeSinceStartup - t0)
		{
			float t1 = Mathf.Clamp01(num / scaleTime);
			float num2 = Mathf.Lerp(startScale, endScale, t1);
			Vector3 localScale = defaultScale * num2;
			transform.localScale = localScale;
			yield return 0;
		}
		transform.localScale = defaultScale * endScale;
	}

	private IEnumerator LocalWaitForSeconds(float seconds)
	{
		float t0 = Time.realtimeSinceStartup;
		for (float num = 0f; num < seconds; num = Time.realtimeSinceStartup - t0)
		{
			yield return 0;
		}
	}

	private IEnumerator coHandleButtonPress(int fingerId)
	{
		buttonDown = true;
		bool buttonPressed = true;
		Vector3 defaultScale = transform.localScale;
		if (targetScale != 1f)
		{
			yield return StartCoroutine(coScale(defaultScale, 1f, targetScale));
		}
		PlaySound(buttonDownSound);
		if (buttonDownSpriteId != -1)
		{
			sprite.spriteId = buttonDownSpriteId;
		}
		if (ButtonDownEvent != null)
		{
			ButtonDownEvent(this);
		}
		while (true)
		{
			Vector3 pos = Vector3.zero;
			bool flag = true;
			if (fingerId != -1)
			{
				bool flag2 = false;
				for (int i = 0; i < Input.touchCount; i++)
				{
					UnityEngine.Touch touch = Input.GetTouch(i);
					if (touch.fingerId == fingerId)
					{
						if (touch.phase == TouchPhase.Ended || touch.phase == TouchPhase.Canceled)
						{
							break;
						}
						pos = touch.position;
						flag2 = true;
					}
				}
				if (!flag2)
				{
					flag = false;
				}
			}
			else
			{
				if (!Input.GetMouseButton(0))
				{
					flag = false;
				}
				pos = Input.mousePosition;
			}
			if (!flag)
			{
				break;
			}
			Ray ray = viewCamera.ScreenPointToRay(pos);
			bool flag3 = GetComponent<Collider>().Raycast(ray, out var _, float.PositiveInfinity);
			if (buttonPressed && !flag3)
			{
				if (targetScale != 1f)
				{
					yield return StartCoroutine(coScale(defaultScale, targetScale, 1f));
				}
				PlaySound(buttonUpSound);
				if (buttonUpSpriteId != -1)
				{
					sprite.spriteId = buttonUpSpriteId;
				}
				if (ButtonUpEvent != null)
				{
					ButtonUpEvent(this);
				}
				buttonPressed = false;
			}
			else if (!buttonPressed & flag3)
			{
				if (targetScale != 1f)
				{
					yield return StartCoroutine(coScale(defaultScale, 1f, targetScale));
				}
				PlaySound(buttonDownSound);
				if (buttonDownSpriteId != -1)
				{
					sprite.spriteId = buttonDownSpriteId;
				}
				if (ButtonDownEvent != null)
				{
					ButtonDownEvent(this);
				}
				buttonPressed = true;
			}
			if (buttonPressed && ButtonAutoFireEvent != null)
			{
				ButtonAutoFireEvent(this);
			}
			yield return 0;
		}
		if (buttonPressed)
		{
			if (targetScale != 1f)
			{
				yield return StartCoroutine(coScale(defaultScale, targetScale, 1f));
			}
			PlaySound(buttonPressedSound);
			if (buttonPressedSpriteId != -1)
			{
				sprite.spriteId = buttonPressedSpriteId;
			}
			if ((bool)targetObject)
			{
				targetObject.SendMessage(messageName);
			}
			if (ButtonUpEvent != null)
			{
				ButtonUpEvent(this);
			}
			if (ButtonPressedEvent != null)
			{
				ButtonPressedEvent(this);
			}
			if (gameObject.activeInHierarchy)
			{
				yield return StartCoroutine(LocalWaitForSeconds(pressedWaitTime));
			}
			if (buttonUpSpriteId != -1)
			{
				sprite.spriteId = buttonUpSpriteId;
			}
		}
		buttonDown = false;
	}

	private void Update()
	{
		if (buttonDown)
		{
			return;
		}
		bool flag = false;
		if (Input.multiTouchEnabled)
		{
			for (int i = 0; i < Input.touchCount; i++)
			{
				UnityEngine.Touch touch = Input.GetTouch(i);
				if (touch.phase == TouchPhase.Began)
				{
					Ray ray = viewCamera.ScreenPointToRay(touch.position);
					if (GetComponent<Collider>().Raycast(ray, out var hitInfo, 100000000f) && !Physics.Raycast(ray, hitInfo.distance - 0.01f))
					{
						StartCoroutine(coHandleButtonPress(touch.fingerId));
						flag = true;
						break;
					}
				}
			}
		}
		if (!flag && Input.GetMouseButtonDown(0))
		{
			Ray ray2 = viewCamera.ScreenPointToRay(Input.mousePosition);
			if (GetComponent<Collider>().Raycast(ray2, out var hitInfo2, 100000000f) && !Physics.Raycast(ray2, hitInfo2.distance - 0.01f))
			{
				StartCoroutine(coHandleButtonPress(-1));
			}
		}
	}
}
