	}

	public void Pause()
	{
		Animator.Pause();
	}

	public void Resume()
	{
		Animator.Resume();
	}

	public void SetFrame(int currFrame)
	{
		Animator.SetFrame(currFrame);
	}

	public void SetFrame(int currFrame, bool triggerEvent)
