		tk2dSpriteDefinition currentSprite = base.CurrentSprite;
		float colliderOffsetZ = ((boxCollider != null) ? boxCollider.center.z : 0f);
		float colliderExtentZ = ((boxCollider != null) ? (boxCollider.size.z * 0.5f) : 0.5f);
		tk2dSpriteGeomGen.SetSlicedSpriteGeom(meshVertices, meshUvs, 0, out boundsCenter, out boundsExtents, currentSprite, _scale, dimensions, new Vector2(borderLeft, borderBottom), new Vector2(borderRight, borderTop), anchor, colliderOffsetZ, colliderExtentZ);
		if (meshNormals.Length != 0 || meshTangents.Length != 0)
		{
			tk2dSpriteGeomGen.SetSpriteVertexNormals(meshVertices, meshVertices[0], meshVertices[15], currentSprite.normals, currentSprite.tangents, meshNormals, meshTangents);
		}
		if (currentSprite.positions.Length != 4 || currentSprite.complexGeometry)
		{
			for (int i = 0; i < vertices.Length; i++)
			{
				vertices[i] = Vector3.zero;
			}
		}
	}

	private void SetIndices()
	{
		int num = (_borderOnly ? 48 : 54);
		meshIndices = new int[num];
		tk2dSpriteGeomGen.SetSlicedSpriteIndices(meshIndices, 0, 0, base.CurrentSprite, _borderOnly);
	}

	private bool NearEnough(float value, float compValue, float scale)
	{
		return Mathf.Abs(Mathf.Abs(value - compValue) / scale) < 0.01f;
	}

	private void PermanentUpgradeLegacyMode()
	{
		tk2dSpriteDefinition currentSprite = base.CurrentSprite;
		float x = currentSprite.untrimmedBoundsData[0].x;
		float y = currentSprite.untrimmedBoundsData[0].y;
		float x2 = currentSprite.untrimmedBoundsData[1].x;
		float y2 = currentSprite.untrimmedBoundsData[1].y;
		if (NearEnough(x, 0f, x2) && NearEnough(y, (0f - y2) / 2f, y2))
		{
			_anchor = Anchor.UpperCenter;
		}
		else if (NearEnough(x, 0f, x2) && NearEnough(y, 0f, y2))
		{
			_anchor = Anchor.MiddleCenter;
		}
		else if (NearEnough(x, 0f, x2) && NearEnough(y, y2 / 2f, y2))
		{
			_anchor = Anchor.LowerCenter;
		}
		else if (NearEnough(x, (0f - x2) / 2f, x2) && NearEnough(y, (0f - y2) / 2f, y2))
		{
			_anchor = Anchor.UpperRight;
		}
		else if (NearEnough(x, (0f - x2) / 2f, x2) && NearEnough(y, 0f, y2))
		{
			_anchor = Anchor.MiddleRight;
		}
		else if (NearEnough(x, (0f - x2) / 2f, x2) && NearEnough(y, y2 / 2f, y2))
		{
			_anchor = Anchor.LowerRight;
		}
		else if (NearEnough(x, x2 / 2f, x2) && NearEnough(y, (0f - y2) / 2f, y2))
		{
			_anchor = Anchor.UpperLeft;
		}
		else if (NearEnough(x, x2 / 2f, x2) && NearEnough(y, 0f, y2))
		{
			_anchor = Anchor.MiddleLeft;
		}
		else if (NearEnough(x, x2 / 2f, x2) && NearEnough(y, y2 / 2f, y2))
		{
			_anchor = Anchor.LowerLeft;
		}
		else
		{
			UnityEngine.Debug.LogError("tk2dSlicedSprite (" + base.name + ") error - Unable to determine anchor upgrading from legacy mode. Please fix this manually.");
			_anchor = Anchor.MiddleCenter;
		}
		float num = x2 / currentSprite.texelSize.x;
		float num2 = y2 / currentSprite.texelSize.y;
		_dimensions.x = _scale.x * num;
		_dimensions.y = _scale.y * num2;
		_scale.Set(1f, 1f, 1f);
		legacyMode = false;
	}

	public override void Build()
	{
		if (legacyMode)
		{
			PermanentUpgradeLegacyMode();
		}
		tk2dSpriteDefinition currentSprite = base.CurrentSprite;
		meshUvs = new Vector2[16];
		meshVertices = new Vector3[16];
		meshColors = new Color32[16];
		meshNormals = new Vector3[0];
		meshTangents = new Vector4[0];
		if (currentSprite.normals != null && currentSprite.normals.Length != 0)
		{
			meshNormals = new Vector3[16];
		}
		if (currentSprite.tangents != null && currentSprite.tangents.Length != 0)
		{
			meshTangents = new Vector4[16];
		}
		SetIndices();
		SetGeometry(meshVertices, meshUvs);
		SetColors(meshColors);
		if (mesh == null)
		{
			mesh = new Mesh();
			mesh.MarkDynamic();
			mesh.hideFlags = HideFlags.DontSave;
		}
		else
		{
			mesh.Clear();
		}
		mesh.vertices = meshVertices;
		mesh.colors32 = meshColors;
		mesh.uv = meshUvs;
		mesh.normals = meshNormals;
		mesh.tangents = meshTangents;
		mesh.triangles = meshIndices;
		mesh.RecalculateBounds();
		mesh.bounds = tk2dBaseSprite.AdjustedMeshBounds(mesh.bounds, renderLayer);
		GetComponent<MeshFilter>().mesh = mesh;
		UpdateCollider();
		UpdateMaterial();
	}

	protected override void UpdateGeometry()
	{
		UpdateGeometryImpl();
	}

	protected override void UpdateColors()
	{
		UpdateColorsImpl();
	}

	protected override void UpdateVertices()
	{
		UpdateGeometryImpl();
	}

	private void UpdateIndices()
	{
		if (mesh != null)
		{
			SetIndices();
			mesh.triangles = meshIndices;
		}
	}

	protected void UpdateColorsImpl()
	{
		if (meshColors == null || meshColors.Length == 0)
		{
			Build();
			return;
		}
		SetColors(meshColors);
		mesh.colors32 = meshColors;
	}

	protected void UpdateGeometryImpl()
	{
		if (meshVertices == null || meshVertices.Length == 0)
		{
			Build();
			return;
		}
		SetGeometry(meshVertices, meshUvs);
		mesh.vertices = meshVertices;
		mesh.uv = meshUvs;
		mesh.normals = meshNormals;
		mesh.tangents = meshTangents;
		mesh.RecalculateBounds();
		mesh.bounds = tk2dBaseSprite.AdjustedMeshBounds(mesh.bounds, renderLayer);
		UpdateCollider();
	}

	protected override void UpdateCollider()
	{
		if (!CreateBoxCollider)
		{
			return;
		}
		if (base.CurrentSprite.physicsEngine == tk2dSpriteDefinition.PhysicsEngine.Physics3D)
		{
			if (boxCollider != null)
			{
				boxCollider.size = 2f * boundsExtents;
				boxCollider.center = boundsCenter;
			}
		}
		else if (base.CurrentSprite.physicsEngine == tk2dSpriteDefinition.PhysicsEngine.Physics2D && boxCollider2D != null)
		{
			boxCollider2D.size = 2f * boundsExtents;
			boxCollider2D.offset = boundsCenter;
		}
	}

	protected override void CreateCollider()
	{
		UpdateCollider();
	}

	protected override void UpdateMaterial()
	{
		Renderer component = GetComponent<Renderer>();
		if (component.sharedMaterial != collectionInst.spriteDefinitions[base.spriteId].materialInst)
		{
			component.material = collectionInst.spriteDefinitions[base.spriteId].materialInst;
		}
	}

	protected override int GetCurrentVertexCount()
	{
		return 16;
	}

	public override void ReshapeBounds(Vector3 dMin, Vector3 dMax)
	{
		float num = 0.1f;
		tk2dSpriteDefinition currentSprite = base.CurrentSprite;
		Vector2 vector = new Vector2(_dimensions.x * currentSprite.texelSize.x, _dimensions.y * currentSprite.texelSize.y);
		Vector3 vector2 = new Vector3(vector.x * _scale.x, vector.y * _scale.y);
		Vector3 zero = Vector3.zero;
		switch (_anchor)
		{
		case Anchor.LowerLeft:
			zero.Set(0f, 0f, 0f);
			break;
		case Anchor.LowerCenter:
			zero.Set(0.5f, 0f, 0f);
			break;
		case Anchor.LowerRight:
			zero.Set(1f, 0f, 0f);
			break;
		case Anchor.MiddleLeft:
			zero.Set(0f, 0.5f, 0f);
			break;
		case Anchor.MiddleCenter:
			zero.Set(0.5f, 0.5f, 0f);
			break;
		case Anchor.MiddleRight:
			zero.Set(1f, 0.5f, 0f);
			break;
		case Anchor.UpperLeft:
			zero.Set(0f, 1f, 0f);
			break;
		case Anchor.UpperCenter:
			zero.Set(0.5f, 1f, 0f);
			break;
		case Anchor.UpperRight:
			zero.Set(1f, 1f, 0f);
			break;
		}
		zero = Vector3.Scale(zero, vector2) * -1f;
		Vector3 vector3 = vector2 + dMax - dMin;
		vector3.x /= vector.x;
		vector3.y /= vector.y;
		if (Mathf.Abs(vector.x * vector3.x) < currentSprite.texelSize.x * num && Mathf.Abs(vector3.x) < Mathf.Abs(_scale.x))
		{
			dMin.x = 0f;
			vector3.x = _scale.x;
		}
		if (Mathf.Abs(vector.y * vector3.y) < currentSprite.texelSize.y * num && Mathf.Abs(vector3.y) < Mathf.Abs(_scale.y))
		{
			dMin.y = 0f;
			vector3.y = _scale.y;
		}
		Vector2 vector4 = new Vector3(Mathf.Approximately(_scale.x, 0f) ? 0f : (vector3.x / _scale.x), Mathf.Approximately(_scale.y, 0f) ? 0f : (vector3.y / _scale.y));
		Vector3 vector5 = new Vector3(zero.x * vector4.x, zero.y * vector4.y);
		Vector3 position = dMin + zero - vector5;
		position.z = 0f;
		base.transform.position = base.transform.TransformPoint(position);
		dimensions = new Vector2(_dimensions.x * vector4.x, _dimensions.y * vector4.y);
	}
}
[AddComponentMenu("2D Toolkit/Sprite/tk2dSprite")]
[RequireComponent(typeof(MeshRenderer))]
[RequireComponent(typeof(MeshFilter))]
[ExecuteInEditMode]
public class tk2dSprite : tk2dBaseSprite
{
	private Mesh mesh;

	private Vector3[] meshVertices;

	private Vector3[] meshNormals;

	private Vector4[] meshTangents;

	private Color32[] meshColors;

	private new void Awake()
	{
		base.Awake();
		mesh = new Mesh();
		mesh.MarkDynamic();
		mesh.hideFlags = HideFlags.DontSave;
		GetComponent<MeshFilter>().mesh = mesh;
		if ((bool)base.Collection)
		{
			if (_spriteId < 0 || _spriteId >= base.Collection.Count)
			{
				_spriteId = 0;
			}
			Build();
		}
	}

	protected void OnDestroy()
	{
		if ((bool)mesh)
		{
			UnityEngine.Object.Destroy(mesh);
		}
		if ((bool)meshColliderMesh)
		{
			UnityEngine.Object.Destroy(meshColliderMesh);
		}
	}

	public override void Build()
	{
		tk2dSpriteDefinition tk2dSpriteDefinition2 = collectionInst.spriteDefinitions[base.spriteId];
		meshVertices = new Vector3[tk2dSpriteDefinition2.positions.Length];
		meshColors = new Color32[tk2dSpriteDefinition2.positions.Length];
		meshNormals = new Vector3[0];
		meshTangents = new Vector4[0];
		if (tk2dSpriteDefinition2.normals != null && tk2dSpriteDefinition2.normals.Length != 0)
		{
			meshNormals = new Vector3[tk2dSpriteDefinition2.normals.Length];
		}
		if (tk2dSpriteDefinition2.tangents != null && tk2dSpriteDefinition2.tangents.Length != 0)
		{
			meshTangents = new Vector4[tk2dSpriteDefinition2.tangents.Length];
		}
		SetPositions(meshVertices, meshNormals, meshTangents);
		SetColors(meshColors);
		if (mesh == null)
		{
			mesh = new Mesh();
			mesh.MarkDynamic();
			mesh.hideFlags = HideFlags.DontSave;
			GetComponent<MeshFilter>().mesh = mesh;
		}
		mesh.Clear();
		mesh.vertices = meshVertices;
		mesh.normals = meshNormals;
		mesh.tangents = meshTangents;
		mesh.colors32 = meshColors;
		mesh.uv = tk2dSpriteDefinition2.uvs;
		mesh.triangles = tk2dSpriteDefinition2.indices;
		mesh.bounds = tk2dBaseSprite.AdjustedMeshBounds(GetBounds(), renderLayer);
		UpdateMaterial();
		CreateCollider();
	}

	public static tk2dSprite AddComponent(GameObject go, tk2dSpriteCollectionData spriteCollection, int spriteId)
	{
		return tk2dBaseSprite.AddComponent<tk2dSprite>(go, spriteCollection, spriteId);
	}

	public static tk2dSprite AddComponent(GameObject go, tk2dSpriteCollectionData spriteCollection, string spriteName)
	{
		return tk2dBaseSprite.AddComponent<tk2dSprite>(go, spriteCollection, spriteName);
	}

	public static GameObject CreateFromTexture(Texture texture, tk2dSpriteCollectionSize size, Rect region, Vector2 anchor)
	{
		return tk2dBaseSprite.CreateFromTexture<tk2dSprite>(texture, size, region, anchor);
	}

	protected override void UpdateGeometry()
	{
		UpdateGeometryImpl();
	}

	protected override void UpdateColors()
	{
		UpdateColorsImpl();
	}

	protected override void UpdateVertices()
	{
		UpdateVerticesImpl();
	}

	protected void UpdateColorsImpl()
	{
		if (!(mesh == null) && meshColors != null && meshColors.Length != 0)
		{
			SetColors(meshColors);
			mesh.colors32 = meshColors;
		}
	}

	protected void UpdateVerticesImpl()
	{
		tk2dSpriteDefinition tk2dSpriteDefinition2 = collectionInst.spriteDefinitions[base.spriteId];
		if (!(mesh == null) && meshVertices != null && meshVertices.Length != 0)
		{
			if (tk2dSpriteDefinition2.normals.Length != meshNormals.Length)
			{
				meshNormals = ((tk2dSpriteDefinition2.normals != null && tk2dSpriteDefinition2.normals.Length != 0) ? new Vector3[tk2dSpriteDefinition2.normals.Length] : new Vector3[0]);
			}
			if (tk2dSpriteDefinition2.tangents.Length != meshTangents.Length)
			{
				meshTangents = ((tk2dSpriteDefinition2.tangents != null && tk2dSpriteDefinition2.tangents.Length != 0) ? new Vector4[tk2dSpriteDefinition2.tangents.Length] : new Vector4[0]);
			}
			SetPositions(meshVertices, meshNormals, meshTangents);
			mesh.vertices = meshVertices;
			mesh.normals = meshNormals;
			mesh.tangents = meshTangents;
			mesh.uv = tk2dSpriteDefinition2.uvs;
			mesh.bounds = tk2dBaseSprite.AdjustedMeshBounds(GetBounds(), renderLayer);
		}
	}

	protected void UpdateGeometryImpl()
	{
		if (!(mesh == null))
		{
			tk2dSpriteDefinition tk2dSpriteDefinition2 = collectionInst.spriteDefinitions[base.spriteId];
			if (meshVertices == null || meshVertices.Length != tk2dSpriteDefinition2.positions.Length)
			{
				meshVertices = new Vector3[tk2dSpriteDefinition2.positions.Length];
				meshColors = new Color32[tk2dSpriteDefinition2.positions.Length];
			}
			if (meshNormals == null || (tk2dSpriteDefinition2.normals != null && meshNormals.Length != tk2dSpriteDefinition2.normals.Length))
			{
				meshNormals = new Vector3[tk2dSpriteDefinition2.normals.Length];
			}
			else if (tk2dSpriteDefinition2.normals == null)
			{
				meshNormals = new Vector3[0];
			}
			if (meshTangents == null || (tk2dSpriteDefinition2.tangents != null && meshTangents.Length != tk2dSpriteDefinition2.tangents.Length))
			{
				meshTangents = new Vector4[tk2dSpriteDefinition2.tangents.Length];
			}
			else if (tk2dSpriteDefinition2.tangents == null)
			{
				meshTangents = new Vector4[0];
			}
			SetPositions(meshVertices, meshNormals, meshTangents);
			SetColors(meshColors);
			mesh.Clear();
			mesh.vertices = meshVertices;
			mesh.normals = meshNormals;
			mesh.tangents = meshTangents;
			mesh.colors32 = meshColors;
			mesh.uv = tk2dSpriteDefinition2.uvs;
			mesh.bounds = tk2dBaseSprite.AdjustedMeshBounds(GetBounds(), renderLayer);
			mesh.triangles = tk2dSpriteDefinition2.indices;
		}
	}

	protected override void UpdateMaterial()
	{
		Renderer component = GetComponent<Renderer>();
		if (component.sharedMaterial != collectionInst.spriteDefinitions[base.spriteId].materialInst)
		{
			component.material = collectionInst.spriteDefinitions[base.spriteId].materialInst;
		}
	}

	protected override int GetCurrentVertexCount()
	{
		if (meshVertices == null)
		{
			return 0;
		}
		return meshVertices.Length;
	}

	public override void ForceBuild()
	{
		base.ForceBuild();
		GetComponent<MeshFilter>().mesh = mesh;
	}

	public override void ReshapeBounds(Vector3 dMin, Vector3 dMax)
	{
		float num = 0.1f;
		tk2dSpriteDefinition currentSprite = base.CurrentSprite;
		Vector3 b = new Vector3(Mathf.Abs(_scale.x), Mathf.Abs(_scale.y), Mathf.Abs(_scale.z));
		Vector3 vector = Vector3.Scale(currentSprite.untrimmedBoundsData[0], _scale) - 0.5f * Vector3.Scale(currentSprite.untrimmedBoundsData[1], b);
		Vector3 vector2 = Vector3.Scale(currentSprite.untrimmedBoundsData[1], b) + dMax - dMin;
		vector2.x /= currentSprite.untrimmedBoundsData[1].x;
		vector2.y /= currentSprite.untrimmedBoundsData[1].y;
		if (currentSprite.untrimmedBoundsData[1].x * vector2.x < currentSprite.texelSize.x * num && vector2.x < b.x)
		{
			dMin.x = 0f;
			vector2.x = b.x;
		}
		if (currentSprite.untrimmedBoundsData[1].y * vector2.y < currentSprite.texelSize.y * num && vector2.y < b.y)
		{
			dMin.y = 0f;
			vector2.y = b.y;
		}
		Vector2 vector3 = new Vector3(Mathf.Approximately(b.x, 0f) ? 0f : (vector2.x / b.x), Mathf.Approximately(b.y, 0f) ? 0f : (vector2.y / b.y));
		Vector3 vector4 = new Vector3(vector.x * vector3.x, vector.y * vector3.y);
		Vector3 position = dMin + vector - vector4;
		position.z = 0f;
		base.transform.position = base.transform.TransformPoint(position);
		base.scale = new Vector3(_scale.x * vector3.x, _scale.y * vector3.y, _scale.z);
	}
}
[Serializable]
public class tk2dSpriteAnimationFrame
{
	public tk2dSpriteCollectionData spriteCollection;

	public int spriteId;

	public bool triggerEvent;

	public string eventInfo = "";

	public int eventInt;

	public float eventFloat;

	public void CopyFrom(tk2dSpriteAnimationFrame source)
	{
		CopyFrom(source, full: true);
	}

	public void CopyTriggerFrom(tk2dSpriteAnimationFrame source)
	{
		triggerEvent = source.triggerEvent;
		eventInfo = source.eventInfo;
		eventInt = source.eventInt;
		eventFloat = source.eventFloat;
	}

	public void ClearTrigger()
	{
		triggerEvent = false;
		eventInt = 0;
		eventFloat = 0f;
		eventInfo = "";
	}

	public void CopyFrom(tk2dSpriteAnimationFrame source, bool full)
	{
		spriteCollection = source.spriteCollection;
		spriteId = source.spriteId;
		if (full)
		{
			CopyTriggerFrom(source);
		}
	}
}
[Serializable]
public class tk2dSpriteAnimationClip
{
	public enum WrapMode
	{
		Loop,
		LoopSection,
		Once,
		PingPong,
		RandomFrame,
		RandomLoop,
		Single
	}

	public string name = "Default";

	public tk2dSpriteAnimationFrame[] frames = new tk2dSpriteAnimationFrame[0];

	public float fps = 30f;

	public int loopStart;

	public WrapMode wrapMode;

	public float Duration => (float)frames.Length / fps;

	public bool Empty
	{
		get
		{
			if (name.Length != 0 && frames != null)
			{
				return frames.Length == 0;
			}
			return true;
		}
	}

	public tk2dSpriteAnimationClip()
	{
	}

	public tk2dSpriteAnimationClip(tk2dSpriteAnimationClip source)
	{
		CopyFrom(source);
	}

	public void CopyFrom(tk2dSpriteAnimationClip source)
	{
		name = source.name;
		if (source.frames == null)
		{
			frames = null;
		}
		else
		{
			frames = new tk2dSpriteAnimationFrame[source.frames.Length];
			for (int i = 0; i < frames.Length; i++)
			{
				if (source.frames[i] == null)
				{
					frames[i] = null;
					continue;
				}
				frames[i] = new tk2dSpriteAnimationFrame();
				frames[i].CopyFrom(source.frames[i]);
			}
		}
		fps = source.fps;
		loopStart = source.loopStart;
		wrapMode = source.wrapMode;
		if (wrapMode == WrapMode.Single && frames.Length > 1)
		{
			frames = new tk2dSpriteAnimationFrame[1] { frames[0] };
			UnityEngine.Debug.LogError($"Clip: '{name}' Fixed up frames for WrapMode.Single");
		}
	}

	public void Clear()
	{
		name = "";
		frames = new tk2dSpriteAnimationFrame[0];
		fps = 30f;
		loopStart = 0;
		wrapMode = WrapMode.Loop;
	}

	public tk2dSpriteAnimationFrame GetFrame(int frame)
	{
		return frames[frame];
	}
}
[AddComponentMenu("2D Toolkit/Backend/tk2dSpriteAnimation")]
public class tk2dSpriteAnimation : MonoBehaviour
{
	public tk2dSpriteAnimationClip[] clips;

	public tk2dSpriteAnimationClip FirstValidClip
	{
		get
		{
			for (int i = 0; i < clips.Length; i++)
			{
				if (!clips[i].Empty && clips[i].frames[0].spriteCollection != null && clips[i].frames[0].spriteId != -1)
				{
					return clips[i];
				}
			}
			return null;
		}
	}

	public tk2dSpriteAnimationClip GetClipByName(string name)
	{
		for (int i = 0; i < clips.Length; i++)
		{
			if (clips[i].name == name)
			{
				return clips[i];
			}
		}
		return null;
	}

	public tk2dSpriteAnimationClip GetClipById(int id)
	{
		if (id < 0 || id >= clips.Length || clips[id].Empty)
		{
			return null;
		}
		return clips[id];
	}

	public int GetClipIdByName(string name)
	{
		for (int i = 0; i < clips.Length; i++)
		{
			if (clips[i].name == name)
			{
				return i;
			}
		}
		return -1;
	}

	public int GetClipIdByName(tk2dSpriteAnimationClip clip)
	{
		for (int i = 0; i < clips.Length; i++)
		{
			if (clips[i] == clip)
			{
				return i;
			}
		}
		return -1;
	}
}
[AddComponentMenu("2D Toolkit/Sprite/tk2dSpriteAnimator")]
public class tk2dSpriteAnimator : MonoBehaviour
{
	private enum State
	{
		Init,
		Playing,
		Paused
	}

	[SerializeField]
	private tk2dSpriteAnimation library;

	[SerializeField]
	private int defaultClipId;

	public bool playAutomatically;

	private static State globalState;

	private tk2dSpriteAnimationClip currentClip;

	private float clipTime;

	private float clipFps = -1f;

	private int previousFrame = -1;

	public Action<tk2dSpriteAnimator, tk2dSpriteAnimationClip> AnimationCompleted;

	public Action<tk2dSpriteAnimator, tk2dSpriteAnimationClip, int> AnimationEventTriggered;

	private State state;

	protected tk2dBaseSprite _sprite;

	public static bool g_Paused
	{
		get
		{
			return (globalState & State.Paused) != 0;
		}
		set
		{
			globalState = (value ? State.Paused : State.Init);
		}
	}

	public bool Paused
	{
		get
		{
			return (state & State.Paused) != 0;
		}
		set
		{
			if (value)
			{
				state |= State.Paused;
			}
			else
			{
				state &= (State)(-3);
			}
		}
	}

	public tk2dSpriteAnimation Library
	{
		get
		{
			return library;
		}
		set
		{
			library = value;
		}
	}

	public int DefaultClipId
	{
		get
		{
			return defaultClipId;
		}
		set
		{
			defaultClipId = value;
		}
	}

	public tk2dSpriteAnimationClip DefaultClip => GetClipById(defaultClipId);

	public virtual tk2dBaseSprite Sprite
	{
		get
		{
			if (_sprite == null)
			{
				_sprite = GetComponent<tk2dBaseSprite>();
				if (_sprite == null)
				{
					UnityEngine.Debug.LogError("Sprite not found attached to tk2dSpriteAnimator.");
				}
			}
			return _sprite;
		}
	}

	public bool Playing => (state & State.Playing) != 0;

	public tk2dSpriteAnimationClip CurrentClip => currentClip;

	public float ClipTimeSeconds
	{
		get
		{
			if (!(clipFps > 0f))
			{
				return clipTime / currentClip.fps;
			}
			return clipTime / clipFps;
		}
	}

	public float ClipFps
	{
		get
		{
			return clipFps;
		}
		set
		{
			if (currentClip != null)
			{
				clipFps = ((value > 0f) ? value : currentClip.fps);
			}
		}
	}

	public static float DefaultFps => 0f;

	public int CurrentFrame
	{
		get
		{
			switch (currentClip.wrapMode)
			{
			case tk2dSpriteAnimationClip.WrapMode.Once:
				return Mathf.Min((int)clipTime, currentClip.frames.Length);
			case tk2dSpriteAnimationClip.WrapMode.Loop:
			case tk2dSpriteAnimationClip.WrapMode.RandomLoop:
				return (int)clipTime % currentClip.frames.Length;
			case tk2dSpriteAnimationClip.WrapMode.LoopSection:
			{
				int num2 = (int)clipTime;
				int result = currentClip.loopStart + (num2 - currentClip.loopStart) % (currentClip.frames.Length - currentClip.loopStart);
				if (num2 >= currentClip.loopStart)
				{
					return result;
				}
				return num2;
			}
			case tk2dSpriteAnimationClip.WrapMode.PingPong:
			{
				int num = ((currentClip.frames.Length > 1) ? ((int)clipTime % (currentClip.frames.Length + currentClip.frames.Length - 2)) : 0);
				if (num >= currentClip.frames.Length)
				{
					num = 2 * currentClip.frames.Length - 2 - num;
				}
				return num;
			}
			case tk2dSpriteAnimationClip.WrapMode.Single:
				return 0;
			default:
				UnityEngine.Debug.LogError("Unhandled clip wrap mode");
				goto case tk2dSpriteAnimationClip.WrapMode.Loop;
			}
		}
	}

	private void OnEnable()
	{
		if (Sprite == null)
		{
			base.enabled = false;
		}
	}

	private void Start()
	{
		if (playAutomatically)
		{
			Play(DefaultClip);
		}
	}

	public static tk2dSpriteAnimator AddComponent(GameObject go, tk2dSpriteAnimation anim, int clipId)
	{
		tk2dSpriteAnimationClip tk2dSpriteAnimationClip2 = anim.clips[clipId];
		tk2dSpriteAnimator obj = go.AddComponent<tk2dSpriteAnimator>();
		obj.Library = anim;
		obj.SetSprite(tk2dSpriteAnimationClip2.frames[0].spriteCollection, tk2dSpriteAnimationClip2.frames[0].spriteId);
		return obj;
	}

	private tk2dSpriteAnimationClip GetClipByNameVerbose(string name)
	{
		if (library == null)
		{
			UnityEngine.Debug.LogError("Library not set");
			return null;
		}
		tk2dSpriteAnimationClip clipByName = library.GetClipByName(name);
		if (clipByName == null)
		{
			UnityEngine.Debug.LogError("Unable to find clip '" + name + "' in library");
			return null;
		}
		return clipByName;
	}

	public void Play()
	{
		if (currentClip == null)
		{
			currentClip = DefaultClip;
		}
		Play(currentClip);
	}

	public void Play(string name)
	{
		Play(GetClipByNameVerbose(name));
	}

	public void Play(tk2dSpriteAnimationClip clip)
	{
		Play(clip, 0f, DefaultFps);
	}

	public void PlayFromFrame(int frame)
	{
		if (currentClip == null)
		{
			currentClip = DefaultClip;
		}
		PlayFromFrame(currentClip, frame);
	}

	public void PlayFromFrame(string name, int frame)
	{
		PlayFromFrame(GetClipByNameVerbose(name), frame);
	}

	public void PlayFromFrame(tk2dSpriteAnimationClip clip, int frame)
	{
		PlayFrom(clip, ((float)frame + 0.001f) / clip.fps);
	}

	public void PlayFrom(float clipStartTime)
	{
		if (currentClip == null)
		{
			currentClip = DefaultClip;
		}
		PlayFrom(currentClip, clipStartTime);
	}

	public void PlayFrom(string name, float clipStartTime)
	{
		tk2dSpriteAnimationClip tk2dSpriteAnimationClip2 = (library ? library.GetClipByName(name) : null);
		if (tk2dSpriteAnimationClip2 == null)
		{
			ClipNameError(name);
		}
		else
		{
			PlayFrom(tk2dSpriteAnimationClip2, clipStartTime);
		}
	}

	public void PlayFrom(tk2dSpriteAnimationClip clip, float clipStartTime)
	{
		Play(clip, clipStartTime, DefaultFps);
	}

	public void Play(tk2dSpriteAnimationClip clip, float clipStartTime, float overrideFps)
	{
		if (clip != null)
		{
			float num = ((overrideFps > 0f) ? overrideFps : clip.fps);
			if (clipStartTime == 0f && IsPlaying(clip))
			{
				clipFps = num;
				return;
			}
			state |= State.Playing;
			currentClip = clip;
			clipFps = num;
			if (currentClip.wrapMode == tk2dSpriteAnimationClip.WrapMode.Single || currentClip.frames == null)
			{
				WarpClipToLocalTime(currentClip, 0f);
				state &= (State)(-2);
			}
			else if (currentClip.wrapMode == tk2dSpriteAnimationClip.WrapMode.RandomFrame || currentClip.wrapMode == tk2dSpriteAnimationClip.WrapMode.RandomLoop)
			{
				int num2 = UnityEngine.Random.Range(0, currentClip.frames.Length);
				WarpClipToLocalTime(currentClip, num2);
				if (currentClip.wrapMode == tk2dSpriteAnimationClip.WrapMode.RandomFrame)
				{
					previousFrame = -1;
					state &= (State)(-2);
				}
			}
			else
			{
				float num3 = clipStartTime * clipFps;
				if (currentClip.wrapMode == tk2dSpriteAnimationClip.WrapMode.Once && num3 >= clipFps * (float)currentClip.frames.Length)
				{
					WarpClipToLocalTime(currentClip, currentClip.frames.Length - 1);
					state &= (State)(-2);
				}
				else
				{
					WarpClipToLocalTime(currentClip, num3);
					clipTime = num3;
				}
			}
		}
		else
		{
			UnityEngine.Debug.LogError("Calling clip.Play() with a null clip");
			OnAnimationCompleted();
			state &= (State)(-2);
		}
	}

	public void Stop()
	{
		state &= (State)(-2);
	}

	public void StopAndResetFrame()
	{
		if (currentClip != null)
		{
			SetSprite(currentClip.frames[0].spriteCollection, currentClip.frames[0].spriteId);
		}
		Stop();
	}

	public bool IsPlaying(string name)
	{
		if (Playing && CurrentClip != null)
		{
			return CurrentClip.name == name;
		}
		return false;
	}

	public bool IsPlaying(tk2dSpriteAnimationClip clip)
	{
		if (Playing && CurrentClip != null)
		{
			return CurrentClip == clip;
		}
		return false;
	}

	public tk2dSpriteAnimationClip GetClipById(int id)
	{
		if (library == null)
		{
			return null;
		}
		return library.GetClipById(id);
	}

	public int GetClipIdByName(string name)
	{
		if (!library)
		{
			return -1;
		}
		return library.GetClipIdByName(name);
	}

	public tk2dSpriteAnimationClip GetClipByName(string name)
	{
		if (!library)
		{
			return null;
		}
		return library.GetClipByName(name);
	}

	public void Pause()
	{
		state |= State.Paused;
	}

	public void Resume()
	{
		state &= (State)(-3);
	}

	public void SetFrame(int currFrame)
	{
		SetFrame(currFrame, triggerEvent: true);
	}

	public void SetFrame(int currFrame, bool triggerEvent)
	{
		if (currentClip == null)
		{
			currentClip = DefaultClip;
		}
		if (currentClip != null)
		{
			int num = currFrame % currentClip.frames.Length;
			SetFrameInternal(num);
			if (triggerEvent && currentClip.frames.Length != 0 && currFrame >= 0)
			{
				ProcessEvents(num - 1, num, 1);
			}
		}
	}

	public void UpdateAnimation(float deltaTime)
	{
		if ((state | globalState) != State.Playing)
		{
			return;
		}
		clipTime += deltaTime * clipFps;
		int num = previousFrame;
		switch (currentClip.wrapMode)
		{
		case tk2dSpriteAnimationClip.WrapMode.Loop:
		case tk2dSpriteAnimationClip.WrapMode.RandomLoop:
		{
			int num5 = (int)clipTime % currentClip.frames.Length;
			SetFrameInternal(num5);
			if (num5 < num)
			{
				ProcessEvents(num, currentClip.frames.Length - 1, 1);
				ProcessEvents(-1, num5, 1);
			}
			else
			{
				ProcessEvents(num, num5, 1);
			}
			break;
		}
		case tk2dSpriteAnimationClip.WrapMode.LoopSection:
		{
			int num3 = (int)clipTime;
			int num4 = currentClip.loopStart + (num3 - currentClip.loopStart) % (currentClip.frames.Length - currentClip.loopStart);
			if (num3 >= currentClip.loopStart)
			{
				SetFrameInternal(num4);
				num3 = num4;
				if (num < currentClip.loopStart)
				{
					ProcessEvents(num, currentClip.loopStart - 1, 1);
					ProcessEvents(currentClip.loopStart - 1, num3, 1);
				}
				else if (num3 < num)
				{
					ProcessEvents(num, currentClip.frames.Length - 1, 1);
					ProcessEvents(currentClip.loopStart - 1, num3, 1);
				}
				else
				{
					ProcessEvents(num, num3, 1);
				}
			}
			else
			{
				SetFrameInternal(num3);
				ProcessEvents(num, num3, 1);
			}
			break;
		}
		case tk2dSpriteAnimationClip.WrapMode.PingPong:
		{
			int num6 = ((currentClip.frames.Length > 1) ? ((int)clipTime % (currentClip.frames.Length + currentClip.frames.Length - 2)) : 0);
			int direction = 1;
			if (num6 >= currentClip.frames.Length)
			{
				num6 = 2 * currentClip.frames.Length - 2 - num6;
				direction = -1;
			}
			if (num6 < num)
			{
				direction = -1;
			}
			SetFrameInternal(num6);
			ProcessEvents(num, num6, direction);
			break;
		}
		case tk2dSpriteAnimationClip.WrapMode.Once:
		{
			int num2 = (int)clipTime;
			if (num2 >= currentClip.frames.Length)
			{
				SetFrameInternal(currentClip.frames.Length - 1);
				state &= (State)(-2);
				ProcessEvents(num, currentClip.frames.Length - 1, 1);
				OnAnimationCompleted();
			}
			else
			{
				SetFrameInternal(num2);
				ProcessEvents(num, num2, 1);
			}
			break;
		}
		case tk2dSpriteAnimationClip.WrapMode.RandomFrame:
			break;
		}
	}

	private void ClipNameError(string name)
	{
		UnityEngine.Debug.LogError("Unable to find clip named '" + name + "' in library");
	}

	private void ClipIdError(int id)
	{
		UnityEngine.Debug.LogError("Play - Invalid clip id '" + id + "' in library");
	}

	private void WarpClipToLocalTime(tk2dSpriteAnimationClip clip, float time)
	{
		clipTime = time;
		int num = (int)clipTime % clip.frames.Length;
		tk2dSpriteAnimationFrame tk2dSpriteAnimationFrame2 = clip.frames[num];
		SetSprite(tk2dSpriteAnimationFrame2.spriteCollection, tk2dSpriteAnimationFrame2.spriteId);
		if (tk2dSpriteAnimationFrame2.triggerEvent && AnimationEventTriggered != null)
		{
			AnimationEventTriggered(this, clip, num);
		}
		previousFrame = num;
	}

	private void SetFrameInternal(int currFrame)
	{
		if (previousFrame != currFrame)
		{
			SetSprite(currentClip.frames[currFrame].spriteCollection, currentClip.frames[currFrame].spriteId);
			previousFrame = currFrame;
		}
	}

	private void ProcessEvents(int start, int last, int direction)
	{
		if (AnimationEventTriggered == null || start == last || Mathf.Sign(last - start) != Mathf.Sign(direction))
		{
			return;
		}
		int num = last + direction;
		tk2dSpriteAnimationFrame[] frames = currentClip.frames;
		for (int i = start + direction; i != num; i += direction)
		{
			if (frames[i].triggerEvent && AnimationEventTriggered != null)
			{
				AnimationEventTriggered(this, currentClip, i);
			}
		}
	}

	private void OnAnimationCompleted()
	{
		previousFrame = -1;
		if (AnimationCompleted != null)
		{
			AnimationCompleted(this, currentClip);
		}
	}

	public virtual void LateUpdate()
	{
		UpdateAnimation(Time.deltaTime);
	}

	public virtual void SetSprite(tk2dSpriteCollectionData spriteCollection, int spriteId)
	{
		Sprite.SetSprite(spriteCollection, spriteId);
	}
}
[ExecuteInEditMode]
[AddComponentMenu("2D Toolkit/Sprite/tk2dSpriteAttachPoint")]
public class tk2dSpriteAttachPoint : MonoBehaviour
{
	private tk2dBaseSprite sprite;

	public List<Transform> attachPoints = new List<Transform>();

	private static bool[] attachPointUpdated = new bool[32];

	public bool deactivateUnusedAttachPoints;

	private Dictionary<Transform, string> cachedInstanceNames = new Dictionary<Transform, string>();

	private void Awake()
	{
		if (sprite == null)
		{
			sprite = GetComponent<tk2dBaseSprite>();
			if (sprite != null)
			{
				HandleSpriteChanged(sprite);
			}
		}
	}

	private void OnEnable()
	{
		if (sprite != null)
		{
			sprite.SpriteChanged += HandleSpriteChanged;
		}
	}

	private void OnDisable()
	{
		if (sprite != null)
		{
			sprite.SpriteChanged -= HandleSpriteChanged;
		}
	}

	private void UpdateAttachPointTransform(tk2dSpriteDefinition.AttachPoint attachPoint, Transform t)
	{
		t.localPosition = Vector3.Scale(attachPoint.position, sprite.scale);
		t.localScale = sprite.scale;
		float num = Mathf.Sign(sprite.scale.x) * Mathf.Sign(sprite.scale.y);
		t.localEulerAngles = new Vector3(0f, 0f, attachPoint.angle * num);
	}

	private string GetInstanceName(Transform t)
	{
		string value = "";
		if (cachedInstanceNames.TryGetValue(t, out value))
		{
			return value;
		}
		cachedInstanceNames[t] = t.name;
		return t.name;
	}

	private void HandleSpriteChanged(tk2dBaseSprite spr)
	{
		tk2dSpriteDefinition currentSprite = spr.CurrentSprite;
		int num = Mathf.Max(currentSprite.attachPoints.Length, attachPoints.Count);
		if (num > attachPointUpdated.Length)
		{
			attachPointUpdated = new bool[num];
		}
		tk2dSpriteDefinition.AttachPoint[] array = currentSprite.attachPoints;
		foreach (tk2dSpriteDefinition.AttachPoint attachPoint in array)
		{
			bool flag = false;
			int num2 = 0;
			for (int j = 0; j < attachPoints.Count; j++)
			{
				Transform transform = attachPoints[j];
				if (transform != null && GetInstanceName(transform) == attachPoint.name)
				{
					attachPointUpdated[num2] = true;
					UpdateAttachPointTransform(attachPoint, transform);
					flag = true;
				}
				num2++;
			}
			if (!flag)
			{
				Transform transform2 = new GameObject(attachPoint.name).transform;
				transform2.parent = base.transform;
				UpdateAttachPointTransform(attachPoint, transform2);
				attachPointUpdated[attachPoints.Count] = true;
				attachPoints.Add(transform2);
			}
		}
		if (!deactivateUnusedAttachPoints)
		{
			return;
		}
		for (int k = 0; k < attachPoints.Count; k++)
		{
			if (attachPoints[k] != null)
			{
				GameObject gameObject = attachPoints[k].gameObject;
				if (attachPointUpdated[k] && !gameObject.activeSelf)
				{
					gameObject.SetActive(value: true);
				}
				else if (!attachPointUpdated[k] && gameObject.activeSelf)
				{
					gameObject.SetActive(value: false);
				}
			}
			attachPointUpdated[k] = false;
		}
	}
}
[Serializable]
public class tk2dSpriteColliderIsland
{
	public bool connected = true;

	public Vector2[] points;

	public bool IsValid()
	{
		if (connected)
		{
			return points.Length >= 3;
		}
		return points.Length >= 2;
	}

	public void CopyFrom(tk2dSpriteColliderIsland src)
	{
		connected = src.connected;
		points = new Vector2[src.points.Length];
		for (int i = 0; i < points.Length; i++)
		{
			points[i] = src.points[i];
		}
	}

	public bool CompareTo(tk2dSpriteColliderIsland src)
	{
		if (connected != src.connected)
		{
			return false;
		}
		if (points.Length != src.points.Length)
		{
			return false;
		}
		for (int i = 0; i < points.Length; i++)
		{
			if (points[i] != src.points[i])
			{
				return false;
			}
		}
		return true;
	}
}
