	[Serializable]
	public class ColliderData
	{
		public enum Type
		{
			Box,
			Circle
		}

		public string name = "";

		public Type type;

		public Vector2 origin = Vector3.zero;

		public Vector2 size = Vector3.zero;

		public float angle;

		public void CopyFrom(ColliderData src)
		{
			name = src.name;
			type = src.type;
			origin = src.origin;
			size = src.size;
			angle = src.angle;
		}

		public bool CompareTo(ColliderData src)
		{
			if (name == src.name && type == src.type && origin == src.origin && size == src.size)
			{
				return angle == src.angle;
			}
			return false;
		}
	}

	public string name = "";

	public bool disableTrimming;

	public bool additive;

	public Vector3 scale = new Vector3(1f, 1f, 1f);

	public Texture2D texture;

	[NonSerialized]
	public Texture2D thumbnailTexture;

	public int materialId;

