	public int FirstValidDefinitionIndex
	{
		get
		{
			tk2dSpriteCollectionData tk2dSpriteCollectionData2 = inst;
			for (int i = 0; i < tk2dSpriteCollectionData2.spriteDefinitions.Length; i++)
			{
				if (tk2dSpriteCollectionData2.spriteDefinitions[i].Valid)
				{
					return i;
				}
			}
			return -1;
		}
	}

	public tk2dSpriteCollectionData inst
	{
		get
		{
			if (platformSpecificData == null)
			{
				if (hasPlatformData)
				{
					string currentPlatform = tk2dSystem.CurrentPlatform;
					string text = "";
					for (int i = 0; i < spriteCollectionPlatforms.Length; i++)
					{
						if (spriteCollectionPlatforms[i] == currentPlatform)
						{
							text = spriteCollectionPlatformGUIDs[i];
							break;
						}
					}
					if (text.Length == 0)
					{
						text = spriteCollectionPlatformGUIDs[0];
					}
					platformSpecificData = tk2dSystem.LoadResourceByGUID<tk2dSpriteCollectionData>(text);
				}
				else
				{
					platformSpecificData = this;
				}
			}
			platformSpecificData.Init();
			return platformSpecificData;
		}
	}

	public int GetSpriteIdByName(string name)
	{
		return GetSpriteIdByName(name, 0);
	}

	public int GetSpriteIdByName(string name, int defaultValue)
	{
		inst.InitDictionary();
		int value = defaultValue;
		if (!inst.spriteNameLookupDict.TryGetValue(name, out value))
		{
			return defaultValue;
		}
		return value;
	}

	public void ClearDictionary()
	{
		spriteNameLookupDict = null;
	}

	public tk2dSpriteDefinition GetSpriteDefinition(string name)
	{
		int spriteIdByName = GetSpriteIdByName(name, -1);
		if (spriteIdByName == -1)
		{
			return null;
		}
		return spriteDefinitions[spriteIdByName];
	}

	public void InitDictionary()
	{
		if (spriteNameLookupDict == null)
		{
			spriteNameLookupDict = new Dictionary<string, int>(spriteDefinitions.Length);
			for (int i = 0; i < spriteDefinitions.Length; i++)
			{
				spriteNameLookupDict[spriteDefinitions[i].name] = i;
			}
		}
	}

	public bool IsValidSpriteId(int id)
	{
		if (id < 0 || id >= inst.spriteDefinitions.Length)
		{
			return false;
		}
		return inst.spriteDefinitions[id].Valid;
	}

	public void InitMaterialIds()
	{
		if (inst.materialIdsValid)
		{
			return;
		}
		int num = -1;
		Dictionary<Material, int> dictionary = new Dictionary<Material, int>();
		for (int i = 0; i < inst.materials.Length; i++)
		{
			if (num == -1 && inst.materials[i] != null)
			{
				num = i;
			}
			dictionary[materials[i]] = i;
		}
		if (num == -1)
		{
			UnityEngine.Debug.LogError("Init material ids failed.");
			return;
		}
		tk2dSpriteDefinition[] array = inst.spriteDefinitions;
		foreach (tk2dSpriteDefinition tk2dSpriteDefinition2 in array)
		{
			if (!dictionary.TryGetValue(tk2dSpriteDefinition2.material, out tk2dSpriteDefinition2.materialId))
			{
				tk2dSpriteDefinition2.materialId = num;
			}
		}
		inst.materialIdsValid = true;
	}

	private void Init()
	{
		if (materialInsts != null)
		{
			return;
		}
		if (spriteDefinitions == null)
		{
			spriteDefinitions = new tk2dSpriteDefinition[0];
		}
		if (materials == null)
		{
			materials = new Material[0];
		}
		materialInsts = new Material[materials.Length];
		if (needMaterialInstance)
		{
			if (tk2dSystem.OverrideBuildMaterial)
			{
				for (int i = 0; i < materials.Length; i++)
				{
					materialInsts[i] = new Material(Shader.Find("tk2d/BlendVertexColor"));
				}
			}
			else
			{
				bool flag = false;
				if (pngTextures.Length != 0)
				{
					flag = true;
					textureInsts = new Texture2D[pngTextures.Length];
					for (int j = 0; j < pngTextures.Length; j++)
					{
						Texture2D texture2D = new Texture2D(4, 4, TextureFormat.ARGB32, textureMipMaps);
						texture2D.LoadImage(pngTextures[j].bytes);
						textureInsts[j] = texture2D;
						texture2D.filterMode = textureFilterMode;
						texture2D.Apply(textureMipMaps, makeNoLongerReadable: true);
					}
				}
				for (int k = 0; k < materials.Length; k++)
				{
					materialInsts[k] = UnityEngine.Object.Instantiate(materials[k]);
					if (flag)
					{
						int num = ((materialPngTextureId.Length != 0) ? materialPngTextureId[k] : 0);
						materialInsts[k].mainTexture = textureInsts[num];
					}
				}
			}
			for (int l = 0; l < spriteDefinitions.Length; l++)
			{
				tk2dSpriteDefinition tk2dSpriteDefinition2 = spriteDefinitions[l];
				tk2dSpriteDefinition2.materialInst = materialInsts[tk2dSpriteDefinition2.materialId];
			}
		}
		else
		{
			for (int m = 0; m < materials.Length; m++)
			{
				materialInsts[m] = materials[m];
			}
			for (int n = 0; n < spriteDefinitions.Length; n++)
			{
				tk2dSpriteDefinition obj = spriteDefinitions[n];
				obj.materialInst = obj.material;
			}
		}
		tk2dEditorSpriteDataUnloader.Register(this);
	}

	public static tk2dSpriteCollectionData CreateFromTexture(Texture texture, tk2dSpriteCollectionSize size, string[] names, Rect[] regions, Vector2[] anchors)
	{
		return SpriteCollectionGenerator.CreateFromTexture(texture, size, names, regions, anchors);
	}

	public static tk2dSpriteCollectionData CreateFromTexturePacker(tk2dSpriteCollectionSize size, string texturePackerData, Texture texture)
	{
		return SpriteCollectionGenerator.CreateFromTexturePacker(size, texturePackerData, texture);
	}

	public void ResetPlatformData()
	{
		tk2dEditorSpriteDataUnloader.Unregister(this);
		if (platformSpecificData != null)
		{
			platformSpecificData.DestroyTextureInsts();
		}
		DestroyTextureInsts();
		if ((bool)platformSpecificData)
		{
			platformSpecificData = null;
		}
		materialInsts = null;
	}

	private void DestroyTextureInsts()
	{
		Texture2D[] array = textureInsts;
		for (int i = 0; i < array.Length; i++)
		{
			UnityEngine.Object.DestroyImmediate(array[i]);
		}
		textureInsts = new Texture2D[0];
	}

	public void UnloadTextures()
	{
		tk2dSpriteCollectionData tk2dSpriteCollectionData2 = inst;
		Texture[] array = tk2dSpriteCollectionData2.textures;
		for (int i = 0; i < array.Length; i++)
		{
			Resources.UnloadAsset((Texture2D)array[i]);
		}
		tk2dSpriteCollectionData2.DestroyMaterialInsts();
		tk2dSpriteCollectionData2.DestroyTextureInsts();
	}

	private void DestroyMaterialInsts()
	{
		if (needMaterialInstance)
		{
			Material[] array = materialInsts;
			for (int i = 0; i < array.Length; i++)
			{
				UnityEngine.Object.DestroyImmediate(array[i]);
			}
		}
		materialInsts = null;
	}

	private void OnDestroy()
	{
		if (Transient)
		{
			Material[] array = materials;
			for (int i = 0; i < array.Length; i++)
			{
				UnityEngine.Object.DestroyImmediate(array[i]);
			}
		}
		else if (needMaterialInstance)
		{
			Material[] array = materialInsts;
			for (int i = 0; i < array.Length; i++)
			{
				UnityEngine.Object.DestroyImmediate(array[i]);
			}
			materialInsts = new Material[0];
			Texture2D[] array2 = textureInsts;
			for (int i = 0; i < array2.Length; i++)
			{
				UnityEngine.Object.DestroyImmediate(array2[i]);
			}
			textureInsts = new Texture2D[0];
		}
		ResetPlatformData();
	}
}
[Serializable]
public class tk2dSpriteCollectionSize
{
	public enum Type
	{
		Explicit,
		PixelsPerMeter
	}

	public Type type = Type.PixelsPerMeter;

	public float orthoSize = 10f;

	public float pixelsPerMeter = 100f;

	public float width = 960f;

	public float height = 640f;

	public float OrthoSize => type switch
	{
		Type.Explicit => orthoSize, 
		Type.PixelsPerMeter => 0.5f, 
		_ => orthoSize, 
	};

	public float TargetHeight => type switch
	{
		Type.Explicit => height, 
		Type.PixelsPerMeter => pixelsPerMeter, 
		_ => height, 
	};

	public static tk2dSpriteCollectionSize Explicit(float orthoSize, float targetHeight)
	{
		return ForResolution(orthoSize, targetHeight, targetHeight);
	}

	public static tk2dSpriteCollectionSize PixelsPerMeter(float pixelsPerMeter)
	{
		return new tk2dSpriteCollectionSize
		{
			type = Type.PixelsPerMeter,
			pixelsPerMeter = pixelsPerMeter
		};
	}

	public static tk2dSpriteCollectionSize ForResolution(float orthoSize, float width, float height)
	{
		return new tk2dSpriteCollectionSize
		{
			type = Type.Explicit,
			orthoSize = orthoSize,
			width = width,
			height = height
		};
	}

	public static tk2dSpriteCollectionSize ForTk2dCamera()
	{
		return new tk2dSpriteCollectionSize
		{
			type = Type.PixelsPerMeter,
			pixelsPerMeter = 1f
		};
	}

	public static tk2dSpriteCollectionSize ForTk2dCamera(tk2dCamera camera)
	{
		tk2dSpriteCollectionSize tk2dSpriteCollectionSize2 = new tk2dSpriteCollectionSize();
		tk2dCameraSettings cameraSettings = camera.SettingsRoot.CameraSettings;
		if (cameraSettings.projection == tk2dCameraSettings.ProjectionType.Orthographic)
		{
			switch (cameraSettings.orthographicType)
			{
			case tk2dCameraSettings.OrthographicType.PixelsPerMeter:
				tk2dSpriteCollectionSize2.type = Type.PixelsPerMeter;
				tk2dSpriteCollectionSize2.pixelsPerMeter = cameraSettings.orthographicPixelsPerMeter;
				break;
			case tk2dCameraSettings.OrthographicType.OrthographicSize:
				tk2dSpriteCollectionSize2.type = Type.Explicit;
				tk2dSpriteCollectionSize2.height = camera.nativeResolutionHeight;
				tk2dSpriteCollectionSize2.orthoSize = cameraSettings.orthographicSize;
				break;
			}
		}
		else if (cameraSettings.projection == tk2dCameraSettings.ProjectionType.Perspective)
		{
			tk2dSpriteCollectionSize2.type = Type.PixelsPerMeter;
			tk2dSpriteCollectionSize2.pixelsPerMeter = 100f;
		}
		return tk2dSpriteCollectionSize2;
	}

	public static tk2dSpriteCollectionSize Default()
	{
		return PixelsPerMeter(100f);
	}

	public void CopyFromLegacy(bool useTk2dCamera, float orthoSize, float targetHeight)
	{
		if (useTk2dCamera)
		{
			type = Type.PixelsPerMeter;
			pixelsPerMeter = 1f;
		}
		else
		{
			type = Type.Explicit;
			height = targetHeight;
			this.orthoSize = orthoSize;
		}
	}

	public void CopyFrom(tk2dSpriteCollectionSize source)
	{
		type = source.type;
		width = source.width;
		height = source.height;
		orthoSize = source.orthoSize;
		pixelsPerMeter = source.pixelsPerMeter;
	}
}
[AddComponentMenu("2D Toolkit/Sprite/tk2dSpriteFromTexture")]
[ExecuteInEditMode]
public class tk2dSpriteFromTexture : MonoBehaviour
{
	public Texture texture;

	public tk2dSpriteCollectionSize spriteCollectionSize = new tk2dSpriteCollectionSize();

	public tk2dBaseSprite.Anchor anchor = tk2dBaseSprite.Anchor.MiddleCenter;

	private tk2dSpriteCollectionData spriteCollection;

	private tk2dBaseSprite _sprite;

	private tk2dBaseSprite Sprite
	{
		get
		{
			if (_sprite == null)
			{
				_sprite = GetComponent<tk2dBaseSprite>();
				if (_sprite == null)
				{
					UnityEngine.Debug.Log("tk2dSpriteFromTexture - Missing sprite object. Creating.");
					_sprite = base.gameObject.AddComponent<tk2dSprite>();
				}
			}
			return _sprite;
		}
	}

	public bool HasSpriteCollection => spriteCollection != null;

	private void Awake()
	{
		Create(spriteCollectionSize, texture, anchor);
	}

	private void OnDestroy()
	{
		DestroyInternal();
		Renderer component = GetComponent<Renderer>();
		if (component != null)
		{
			component.material = null;
		}
	}

	public void Create(tk2dSpriteCollectionSize spriteCollectionSize, Texture texture, tk2dBaseSprite.Anchor anchor)
	{
		DestroyInternal();
		if (texture != null)
		{
			this.spriteCollectionSize.CopyFrom(spriteCollectionSize);
			this.texture = texture;
			this.anchor = anchor;
			GameObject gameObject = new GameObject("tk2dSpriteFromTexture - " + texture.name);
			gameObject.transform.localPosition = Vector3.zero;
			gameObject.transform.localRotation = Quaternion.identity;
			gameObject.transform.localScale = Vector3.one;
			gameObject.hideFlags = HideFlags.DontSave;
			Vector2 anchorOffset = tk2dSpriteGeomGen.GetAnchorOffset(anchor, texture.width, texture.height);
			spriteCollection = SpriteCollectionGenerator.CreateFromTexture(gameObject, texture, spriteCollectionSize, new Vector2(texture.width, texture.height), new string[1] { "unnamed" }, new Rect[1]
			{
				new Rect(0f, 0f, texture.width, texture.height)
			}, null, new Vector2[1] { anchorOffset }, new bool[1]);
			string spriteCollectionName = "SpriteFromTexture " + texture.name;
			spriteCollection.spriteCollectionName = spriteCollectionName;
			spriteCollection.spriteDefinitions[0].material.name = spriteCollectionName;
			spriteCollection.spriteDefinitions[0].material.hideFlags = HideFlags.DontSave | HideFlags.HideInInspector;
			Sprite.SetSprite(spriteCollection, 0);
		}
	}

	public void Clear()
	{
		DestroyInternal();
	}

	public void ForceBuild()
	{
		DestroyInternal();
		Create(spriteCollectionSize, texture, anchor);
	}

	private void DestroyInternal()
	{
		if (spriteCollection != null)
		{
			if (spriteCollection.spriteDefinitions[0].material != null)
			{
				UnityEngine.Object.DestroyImmediate(spriteCollection.spriteDefinitions[0].material);
			}
			UnityEngine.Object.DestroyImmediate(spriteCollection.gameObject);
			spriteCollection = null;
		}
	}
}
public static class tk2dSpriteGeomGen
{
	private static readonly int[] boxIndicesBack = new int[36]
	{
		0, 1, 2, 2, 1, 3, 6, 5, 4, 7,
		5, 6, 3, 7, 6, 2, 3, 6, 4, 5,
		1, 4, 1, 0, 6, 4, 0, 6, 0, 2,
		1, 7, 3, 5, 7, 1
	};

	private static readonly int[] boxIndicesFwd = new int[36]
	{
		2, 1, 0, 3, 1, 2, 4, 5, 6, 6,
		5, 7, 6, 7, 3, 6, 3, 2, 1, 5,
		4, 0, 1, 4, 0, 4, 6, 2, 0, 6,
		3, 7, 1, 1, 7, 5
	};

	private static readonly Vector3[] boxUnitVertices = new Vector3[8]
	{
		new Vector3(-1f, -1f, -1f),
		new Vector3(-1f, -1f, 1f),
		new Vector3(1f, -1f, -1f),
		new Vector3(1f, -1f, 1f),
		new Vector3(-1f, 1f, -1f),
		new Vector3(-1f, 1f, 1f),
		new Vector3(1f, 1f, -1f),
		new Vector3(1f, 1f, 1f)
	};

	private static Matrix4x4 boxScaleMatrix = Matrix4x4.identity;

	public static void SetSpriteColors(Color32[] dest, int offset, int numVertices, Color c, bool premulAlpha)
	{
		if (premulAlpha)
		{
			c.r *= c.a;
			c.g *= c.a;
			c.b *= c.a;
		}
		Color32 color = c;
		for (int i = 0; i < numVertices; i++)
		{
			dest[offset + i] = color;
		}
	}

	public static Vector2 GetAnchorOffset(tk2dBaseSprite.Anchor anchor, float width, float height)
	{
		Vector2 zero = Vector2.zero;
		switch (anchor)
		{
		case tk2dBaseSprite.Anchor.LowerCenter:
		case tk2dBaseSprite.Anchor.MiddleCenter:
		case tk2dBaseSprite.Anchor.UpperCenter:
			zero.x = (int)(width / 2f);
			break;
		case tk2dBaseSprite.Anchor.LowerRight:
		case tk2dBaseSprite.Anchor.MiddleRight:
		case tk2dBaseSprite.Anchor.UpperRight:
			zero.x = (int)width;
			break;
		}
		switch (anchor)
		{
		case tk2dBaseSprite.Anchor.MiddleLeft:
		case tk2dBaseSprite.Anchor.MiddleCenter:
		case tk2dBaseSprite.Anchor.MiddleRight:
			zero.y = (int)(height / 2f);
			break;
		case tk2dBaseSprite.Anchor.LowerLeft:
		case tk2dBaseSprite.Anchor.LowerCenter:
		case tk2dBaseSprite.Anchor.LowerRight:
			zero.y = (int)height;
			break;
		}
		return zero;
	}

	public static void GetSpriteGeomDesc(out int numVertices, out int numIndices, tk2dSpriteDefinition spriteDef)
	{
		numVertices = spriteDef.positions.Length;
		numIndices = spriteDef.indices.Length;
	}

	public static void SetSpriteGeom(Vector3[] pos, Vector2[] uv, Vector3[] norm, Vector4[] tang, int offset, tk2dSpriteDefinition spriteDef, Vector3 scale)
	{
		for (int i = 0; i < spriteDef.positions.Length; i++)
		{
			pos[offset + i] = Vector3.Scale(spriteDef.positions[i], scale);
		}
		for (int j = 0; j < spriteDef.uvs.Length; j++)
		{
			uv[offset + j] = spriteDef.uvs[j];
		}
		if (norm != null && spriteDef.normals != null)
		{
			for (int k = 0; k < spriteDef.normals.Length; k++)
			{
				norm[offset + k] = spriteDef.normals[k];
			}
		}
		if (tang != null && spriteDef.tangents != null)
		{
			for (int l = 0; l < spriteDef.tangents.Length; l++)
			{
				tang[offset + l] = spriteDef.tangents[l];
			}
		}
	}

	public static void SetSpriteIndices(int[] indices, int offset, int vStart, tk2dSpriteDefinition spriteDef)
	{
		for (int i = 0; i < spriteDef.indices.Length; i++)
		{
			indices[offset + i] = vStart + spriteDef.indices[i];
		}
	}

	public static void GetClippedSpriteGeomDesc(out int numVertices, out int numIndices, tk2dSpriteDefinition spriteDef)
	{
		if (spriteDef.positions.Length == 4)
		{
			numVertices = 4;
			numIndices = 6;
		}
		else
		{
			numVertices = 0;
			numIndices = 0;
		}
	}

	public static void SetClippedSpriteGeom(Vector3[] pos, Vector2[] uv, int offset, out Vector3 boundsCenter, out Vector3 boundsExtents, tk2dSpriteDefinition spriteDef, Vector3 scale, Vector2 clipBottomLeft, Vector2 clipTopRight, float colliderOffsetZ, float colliderExtentZ)
	{
		boundsCenter = Vector3.zero;
		boundsExtents = Vector3.zero;
		if (spriteDef.positions.Length == 4)
		{
			Vector3 vector = spriteDef.untrimmedBoundsData[0] - spriteDef.untrimmedBoundsData[1] * 0.5f;
			Vector3 vector2 = spriteDef.untrimmedBoundsData[0] + spriteDef.untrimmedBoundsData[1] * 0.5f;
			float num = Mathf.Lerp(vector.x, vector2.x, clipBottomLeft.x);
			float num2 = Mathf.Lerp(vector.x, vector2.x, clipTopRight.x);
			float num3 = Mathf.Lerp(vector.y, vector2.y, clipBottomLeft.y);
			float num4 = Mathf.Lerp(vector.y, vector2.y, clipTopRight.y);
			Vector3 vector3 = spriteDef.boundsData[1];
			Vector3 vector4 = spriteDef.boundsData[0] - vector3 * 0.5f;
			float value = (num - vector4.x) / vector3.x;
			float value2 = (num2 - vector4.x) / vector3.x;
			float value3 = (num3 - vector4.y) / vector3.y;
			float value4 = (num4 - vector4.y) / vector3.y;
			Vector2 vector5 = new Vector2(Mathf.Clamp01(value), Mathf.Clamp01(value3));
			Vector2 vector6 = new Vector2(Mathf.Clamp01(value2), Mathf.Clamp01(value4));
			Vector3 vector7 = spriteDef.positions[0];
			Vector3 vector8 = spriteDef.positions[3];
			Vector3 vector9 = new Vector3(Mathf.Lerp(vector7.x, vector8.x, vector5.x) * scale.x, Mathf.Lerp(vector7.y, vector8.y, vector5.y) * scale.y, vector7.z * scale.z);
			Vector3 vector10 = new Vector3(Mathf.Lerp(vector7.x, vector8.x, vector6.x) * scale.x, Mathf.Lerp(vector7.y, vector8.y, vector6.y) * scale.y, vector7.z * scale.z);
			boundsCenter.Set(vector9.x + (vector10.x - vector9.x) * 0.5f, vector9.y + (vector10.y - vector9.y) * 0.5f, colliderOffsetZ);
			boundsExtents.Set((vector10.x - vector9.x) * 0.5f, (vector10.y - vector9.y) * 0.5f, colliderExtentZ);
			pos[offset] = new Vector3(vector9.x, vector9.y, vector9.z);
			pos[offset + 1] = new Vector3(vector10.x, vector9.y, vector9.z);
			pos[offset + 2] = new Vector3(vector9.x, vector10.y, vector9.z);
			pos[offset + 3] = new Vector3(vector10.x, vector10.y, vector9.z);
			if (spriteDef.flipped == tk2dSpriteDefinition.FlipMode.Tk2d)
			{
				Vector2 vector11 = new Vector2(Mathf.Lerp(spriteDef.uvs[0].x, spriteDef.uvs[3].x, vector5.y), Mathf.Lerp(spriteDef.uvs[0].y, spriteDef.uvs[3].y, vector5.x));
				Vector2 vector12 = new Vector2(Mathf.Lerp(spriteDef.uvs[0].x, spriteDef.uvs[3].x, vector6.y), Mathf.Lerp(spriteDef.uvs[0].y, spriteDef.uvs[3].y, vector6.x));
				uv[offset] = new Vector2(vector11.x, vector11.y);
				uv[offset + 1] = new Vector2(vector11.x, vector12.y);
				uv[offset + 2] = new Vector2(vector12.x, vector11.y);
				uv[offset + 3] = new Vector2(vector12.x, vector12.y);
			}
			else if (spriteDef.flipped == tk2dSpriteDefinition.FlipMode.TPackerCW)
			{
				Vector2 vector13 = new Vector2(Mathf.Lerp(spriteDef.uvs[0].x, spriteDef.uvs[3].x, vector5.y), Mathf.Lerp(spriteDef.uvs[0].y, spriteDef.uvs[3].y, vector5.x));
				Vector2 vector14 = new Vector2(Mathf.Lerp(spriteDef.uvs[0].x, spriteDef.uvs[3].x, vector6.y), Mathf.Lerp(spriteDef.uvs[0].y, spriteDef.uvs[3].y, vector6.x));
				uv[offset] = new Vector2(vector13.x, vector13.y);
				uv[offset + 2] = new Vector2(vector14.x, vector13.y);
				uv[offset + 1] = new Vector2(vector13.x, vector14.y);
				uv[offset + 3] = new Vector2(vector14.x, vector14.y);
			}
			else
			{
				Vector2 vector15 = new Vector2(Mathf.Lerp(spriteDef.uvs[0].x, spriteDef.uvs[3].x, vector5.x), Mathf.Lerp(spriteDef.uvs[0].y, spriteDef.uvs[3].y, vector5.y));
				Vector2 vector16 = new Vector2(Mathf.Lerp(spriteDef.uvs[0].x, spriteDef.uvs[3].x, vector6.x), Mathf.Lerp(spriteDef.uvs[0].y, spriteDef.uvs[3].y, vector6.y));
				uv[offset] = new Vector2(vector15.x, vector15.y);
				uv[offset + 1] = new Vector2(vector16.x, vector15.y);
				uv[offset + 2] = new Vector2(vector15.x, vector16.y);
				uv[offset + 3] = new Vector2(vector16.x, vector16.y);
			}
		}
	}

	public static void SetClippedSpriteIndices(int[] indices, int offset, int vStart, tk2dSpriteDefinition spriteDef)
	{
		if (spriteDef.positions.Length == 4)
		{
			indices[offset] = vStart;
			indices[offset + 1] = vStart + 3;
			indices[offset + 2] = vStart + 1;
			indices[offset + 3] = vStart + 2;
			indices[offset + 4] = vStart + 3;
			indices[offset + 5] = vStart;
		}
	}

	public static void GetSlicedSpriteGeomDesc(out int numVertices, out int numIndices, tk2dSpriteDefinition spriteDef, bool borderOnly)
	{
		if (spriteDef.positions.Length == 4)
		{
			numVertices = 16;
			numIndices = (borderOnly ? 48 : 54);
		}
		else
		{
			numVertices = 0;
			numIndices = 0;
		}
	}

	public static void SetSlicedSpriteGeom(Vector3[] pos, Vector2[] uv, int offset, out Vector3 boundsCenter, out Vector3 boundsExtents, tk2dSpriteDefinition spriteDef, Vector3 scale, Vector2 dimensions, Vector2 borderBottomLeft, Vector2 borderTopRight, tk2dBaseSprite.Anchor anchor, float colliderOffsetZ, float colliderExtentZ)
	{
		boundsCenter = Vector3.zero;
		boundsExtents = Vector3.zero;
		if (spriteDef.positions.Length != 4)
		{
			return;
		}
		float x = spriteDef.texelSize.x;
		float y = spriteDef.texelSize.y;
		Vector3[] positions = spriteDef.positions;
		float num = positions[1].x - positions[0].x;
		float num2 = positions[2].y - positions[0].y;
		float num3 = borderTopRight.y * num2;
		float y2 = borderBottomLeft.y * num2;
		float num4 = borderTopRight.x * num;
		float x2 = borderBottomLeft.x * num;
		float num5 = dimensions.x * x;
		float num6 = dimensions.y * y;
		float num7 = 0f;
		float num8 = 0f;
		switch (anchor)
		{
		case tk2dBaseSprite.Anchor.LowerCenter:
		case tk2dBaseSprite.Anchor.MiddleCenter:
		case tk2dBaseSprite.Anchor.UpperCenter:
			num7 = -(int)(dimensions.x / 2f);
			break;
		case tk2dBaseSprite.Anchor.LowerRight:
		case tk2dBaseSprite.Anchor.MiddleRight:
		case tk2dBaseSprite.Anchor.UpperRight:
			num7 = -(int)dimensions.x;
			break;
		}
		switch (anchor)
		{
		case tk2dBaseSprite.Anchor.MiddleLeft:
		case tk2dBaseSprite.Anchor.MiddleCenter:
		case tk2dBaseSprite.Anchor.MiddleRight:
			num8 = -(int)(dimensions.y / 2f);
			break;
		case tk2dBaseSprite.Anchor.UpperLeft:
		case tk2dBaseSprite.Anchor.UpperCenter:
		case tk2dBaseSprite.Anchor.UpperRight:
			num8 = -(int)dimensions.y;
			break;
		}
		num7 *= x;
		num8 *= y;
		boundsCenter.Set(scale.x * (num5 * 0.5f + num7), scale.y * (num6 * 0.5f + num8), colliderOffsetZ);
		boundsExtents.Set(scale.x * (num5 * 0.5f), scale.y * (num6 * 0.5f), colliderExtentZ);
		Vector2[] uvs = spriteDef.uvs;
		Vector2 vector = uvs[1] - uvs[0];
		Vector2 vector2 = uvs[2] - uvs[0];
		Vector3 vector3 = new Vector3(num7, num8, 0f);
		Vector3[] array = new Vector3[4]
		{
			vector3,
			vector3 + new Vector3(0f, y2, 0f),
			vector3 + new Vector3(0f, num6 - num3, 0f),
			vector3 + new Vector3(0f, num6, 0f)
		};
		Vector2[] array2 = new Vector2[4]
		{
			uvs[0],
			uvs[0] + vector2 * borderBottomLeft.y,
			uvs[0] + vector2 * (1f - borderTopRight.y),
			uvs[0] + vector2
		};
		for (int i = 0; i < 4; i++)
		{
			pos[offset + i * 4] = array[i];
			pos[offset + i * 4 + 1] = array[i] + new Vector3(x2, 0f, 0f);
			pos[offset + i * 4 + 2] = array[i] + new Vector3(num5 - num4, 0f, 0f);
			pos[offset + i * 4 + 3] = array[i] + new Vector3(num5, 0f, 0f);
			for (int j = 0; j < 4; j++)
			{
				pos[offset + i * 4 + j] = Vector3.Scale(pos[offset + i * 4 + j], scale);
			}
			uv[offset + i * 4] = array2[i];
			uv[offset + i * 4 + 1] = array2[i] + vector * borderBottomLeft.x;
			uv[offset + i * 4 + 2] = array2[i] + vector * (1f - borderTopRight.x);
			uv[offset + i * 4 + 3] = array2[i] + vector;
		}
	}

	public static void SetSlicedSpriteIndices(int[] indices, int offset, int vStart, tk2dSpriteDefinition spriteDef, bool borderOnly)
	{
		if (spriteDef.positions.Length == 4)
		{
			int[] array = new int[54]
			{
				0, 4, 1, 1, 4, 5, 1, 5, 2, 2,
				5, 6, 2, 6, 3, 3, 6, 7, 4, 8,
				5, 5, 8, 9, 6, 10, 7, 7, 10, 11,
				8, 12, 9, 9, 12, 13, 9, 13, 10, 10,
				13, 14, 10, 14, 11, 11, 14, 15, 5, 9,
				6, 6, 9, 10
			};
			int num = array.Length;
			if (borderOnly)
			{
				num -= 6;
			}
			for (int i = 0; i < num; i++)
			{
				indices[offset + i] = vStart + array[i];
			}
		}
	}

	public static void GetTiledSpriteGeomDesc(out int numVertices, out int numIndices, tk2dSpriteDefinition spriteDef, Vector2 dimensions)
	{
		int num = (int)Mathf.Ceil(dimensions.x * spriteDef.texelSize.x / spriteDef.untrimmedBoundsData[1].x);
		int num2 = (int)Mathf.Ceil(dimensions.y * spriteDef.texelSize.y / spriteDef.untrimmedBoundsData[1].y);
		numVertices = num * num2 * 4;
		numIndices = num * num2 * 6;
	}

	public static void SetTiledSpriteGeom(Vector3[] pos, Vector2[] uv, int offset, out Vector3 boundsCenter, out Vector3 boundsExtents, tk2dSpriteDefinition spriteDef, Vector3 scale, Vector2 dimensions, tk2dBaseSprite.Anchor anchor, float colliderOffsetZ, float colliderExtentZ)
	{
		boundsCenter = Vector3.zero;
		boundsExtents = Vector3.zero;
		int num = (int)Mathf.Ceil(dimensions.x * spriteDef.texelSize.x / spriteDef.untrimmedBoundsData[1].x);
		int num2 = (int)Mathf.Ceil(dimensions.y * spriteDef.texelSize.y / spriteDef.untrimmedBoundsData[1].y);
		Vector2 vector = new Vector2(dimensions.x * spriteDef.texelSize.x * scale.x, dimensions.y * spriteDef.texelSize.y * scale.y);
		Vector2 vector2 = Vector2.Scale(spriteDef.texelSize, scale) * 0.1f;
		Vector3 zero = Vector3.zero;
		switch (anchor)
		{
		case tk2dBaseSprite.Anchor.LowerCenter:
		case tk2dBaseSprite.Anchor.MiddleCenter:
		case tk2dBaseSprite.Anchor.UpperCenter:
			zero.x = 0f - vector.x / 2f;
			break;
		case tk2dBaseSprite.Anchor.LowerRight:
		case tk2dBaseSprite.Anchor.MiddleRight:
		case tk2dBaseSprite.Anchor.UpperRight:
			zero.x = 0f - vector.x;
			break;
		}
		switch (anchor)
		{
		case tk2dBaseSprite.Anchor.MiddleLeft:
		case tk2dBaseSprite.Anchor.MiddleCenter:
		case tk2dBaseSprite.Anchor.MiddleRight:
			zero.y = 0f - vector.y / 2f;
			break;
		case tk2dBaseSprite.Anchor.UpperLeft:
		case tk2dBaseSprite.Anchor.UpperCenter:
		case tk2dBaseSprite.Anchor.UpperRight:
			zero.y = 0f - vector.y;
			break;
		}
		Vector3 vector3 = zero;
		zero -= Vector3.Scale(spriteDef.positions[0], scale);
		boundsCenter.Set(vector.x * 0.5f + vector3.x, vector.y * 0.5f + vector3.y, colliderOffsetZ);
		boundsExtents.Set(vector.x * 0.5f, vector.y * 0.5f, colliderExtentZ);
		int num3 = 0;
		Vector3 vector4 = Vector3.Scale(spriteDef.untrimmedBoundsData[1], scale);
		Vector3 zero2 = Vector3.zero;
		Vector3 vector5 = zero2;
		for (int i = 0; i < num2; i++)
		{
			vector5.x = zero2.x;
			for (int j = 0; j < num; j++)
			{
				float num4 = 1f;
				float num5 = 1f;
				if (Mathf.Abs(vector5.x + vector4.x) > Mathf.Abs(vector.x) + vector2.x)
				{
					num4 = vector.x % vector4.x / vector4.x;
				}
				if (Mathf.Abs(vector5.y + vector4.y) > Mathf.Abs(vector.y) + vector2.y)
				{
					num5 = vector.y % vector4.y / vector4.y;
				}
				Vector3 vector6 = vector5 + zero;
				if (num4 != 1f || num5 != 1f)
				{
					Vector2 zero3 = Vector2.zero;
					Vector2 vector7 = new Vector2(num4, num5);
					Vector3 vector8 = new Vector3(Mathf.Lerp(spriteDef.positions[0].x, spriteDef.positions[3].x, zero3.x) * scale.x, Mathf.Lerp(spriteDef.positions[0].y, spriteDef.positions[3].y, zero3.y) * scale.y, spriteDef.positions[0].z * scale.z);
					Vector3 vector9 = new Vector3(Mathf.Lerp(spriteDef.positions[0].x, spriteDef.positions[3].x, vector7.x) * scale.x, Mathf.Lerp(spriteDef.positions[0].y, spriteDef.positions[3].y, vector7.y) * scale.y, spriteDef.positions[0].z * scale.z);
					pos[offset + num3] = vector6 + new Vector3(vector8.x, vector8.y, vector8.z);
					pos[offset + num3 + 1] = vector6 + new Vector3(vector9.x, vector8.y, vector8.z);
					pos[offset + num3 + 2] = vector6 + new Vector3(vector8.x, vector9.y, vector8.z);
					pos[offset + num3 + 3] = vector6 + new Vector3(vector9.x, vector9.y, vector8.z);
					if (spriteDef.flipped == tk2dSpriteDefinition.FlipMode.Tk2d)
					{
						Vector2 vector10 = new Vector2(Mathf.Lerp(spriteDef.uvs[0].x, spriteDef.uvs[3].x, zero3.y), Mathf.Lerp(spriteDef.uvs[0].y, spriteDef.uvs[3].y, zero3.x));
						Vector2 vector11 = new Vector2(Mathf.Lerp(spriteDef.uvs[0].x, spriteDef.uvs[3].x, vector7.y), Mathf.Lerp(spriteDef.uvs[0].y, spriteDef.uvs[3].y, vector7.x));
						uv[offset + num3] = new Vector2(vector10.x, vector10.y);
						uv[offset + num3 + 1] = new Vector2(vector10.x, vector11.y);
						uv[offset + num3 + 2] = new Vector2(vector11.x, vector10.y);
						uv[offset + num3 + 3] = new Vector2(vector11.x, vector11.y);
					}
					else if (spriteDef.flipped == tk2dSpriteDefinition.FlipMode.TPackerCW)
					{
						Vector2 vector12 = new Vector2(Mathf.Lerp(spriteDef.uvs[0].x, spriteDef.uvs[3].x, zero3.y), Mathf.Lerp(spriteDef.uvs[0].y, spriteDef.uvs[3].y, zero3.x));
						Vector2 vector13 = new Vector2(Mathf.Lerp(spriteDef.uvs[0].x, spriteDef.uvs[3].x, vector7.y), Mathf.Lerp(spriteDef.uvs[0].y, spriteDef.uvs[3].y, vector7.x));
						uv[offset + num3] = new Vector2(vector12.x, vector12.y);
						uv[offset + num3 + 2] = new Vector2(vector13.x, vector12.y);
						uv[offset + num3 + 1] = new Vector2(vector12.x, vector13.y);
						uv[offset + num3 + 3] = new Vector2(vector13.x, vector13.y);
					}
					else
					{
						Vector2 vector14 = new Vector2(Mathf.Lerp(spriteDef.uvs[0].x, spriteDef.uvs[3].x, zero3.x), Mathf.Lerp(spriteDef.uvs[0].y, spriteDef.uvs[3].y, zero3.y));
						Vector2 vector15 = new Vector2(Mathf.Lerp(spriteDef.uvs[0].x, spriteDef.uvs[3].x, vector7.x), Mathf.Lerp(spriteDef.uvs[0].y, spriteDef.uvs[3].y, vector7.y));
						uv[offset + num3] = new Vector2(vector14.x, vector14.y);
						uv[offset + num3 + 1] = new Vector2(vector15.x, vector14.y);
						uv[offset + num3 + 2] = new Vector2(vector14.x, vector15.y);
						uv[offset + num3 + 3] = new Vector2(vector15.x, vector15.y);
					}
				}
				else
				{
					pos[offset + num3] = vector6 + Vector3.Scale(spriteDef.positions[0], scale);
					pos[offset + num3 + 1] = vector6 + Vector3.Scale(spriteDef.positions[1], scale);
					pos[offset + num3 + 2] = vector6 + Vector3.Scale(spriteDef.positions[2], scale);
					pos[offset + num3 + 3] = vector6 + Vector3.Scale(spriteDef.positions[3], scale);
					uv[offset + num3] = spriteDef.uvs[0];
					uv[offset + num3 + 1] = spriteDef.uvs[1];
					uv[offset + num3 + 2] = spriteDef.uvs[2];
					uv[offset + num3 + 3] = spriteDef.uvs[3];
				}
				num3 += 4;
				vector5.x += vector4.x;
			}
			vector5.y += vector4.y;
		}
	}

	public static void SetTiledSpriteIndices(int[] indices, int offset, int vStart, tk2dSpriteDefinition spriteDef, Vector2 dimensions)
	{
		GetTiledSpriteGeomDesc(out var _, out var numIndices, spriteDef, dimensions);
		int num = 0;
		for (int i = 0; i < numIndices; i += 6)
		{
			indices[offset + i] = vStart + spriteDef.indices[0] + num;
			indices[offset + i + 1] = vStart + spriteDef.indices[1] + num;
			indices[offset + i + 2] = vStart + spriteDef.indices[2] + num;
			indices[offset + i + 3] = vStart + spriteDef.indices[3] + num;
			indices[offset + i + 4] = vStart + spriteDef.indices[4] + num;
			indices[offset + i + 5] = vStart + spriteDef.indices[5] + num;
			num += 4;
		}
	}

	public static void SetBoxMeshData(Vector3[] pos, int[] indices, int posOffset, int indicesOffset, int vStart, Vector3 origin, Vector3 extents, Matrix4x4 mat, Vector3 baseScale)
	{
		boxScaleMatrix.m03 = origin.x * baseScale.x;
		boxScaleMatrix.m13 = origin.y * baseScale.y;
		boxScaleMatrix.m23 = origin.z * baseScale.z;
		boxScaleMatrix.m00 = extents.x * baseScale.x;
		boxScaleMatrix.m11 = extents.y * baseScale.y;
		boxScaleMatrix.m22 = extents.z * baseScale.z;
		Matrix4x4 matrix4x = mat * boxScaleMatrix;
		for (int i = 0; i < 8; i++)
		{
			pos[posOffset + i] = matrix4x.MultiplyPoint(boxUnitVertices[i]);
		}
		int[] array = ((mat.m00 * mat.m11 * mat.m22 * baseScale.x * baseScale.y * baseScale.z >= 0f) ? boxIndicesFwd : boxIndicesBack);
		for (int j = 0; j < array.Length; j++)
		{
			indices[indicesOffset + j] = vStart + array[j];
		}
	}

	public static void SetSpriteDefinitionMeshData(Vector3[] pos, int[] indices, int posOffset, int indicesOffset, int vStart, tk2dSpriteDefinition spriteDef, Matrix4x4 mat, Vector3 baseScale)
	{
		for (int i = 0; i < spriteDef.colliderVertices.Length; i++)
		{
			Vector3 point = Vector3.Scale(spriteDef.colliderVertices[i], baseScale);
			point = mat.MultiplyPoint(point);
			pos[posOffset + i] = point;
		}
		int[] array = ((mat.m00 * mat.m11 * mat.m22 >= 0f) ? spriteDef.colliderIndicesFwd : spriteDef.colliderIndicesBack);
		for (int j = 0; j < array.Length; j++)
		{
			indices[indicesOffset + j] = vStart + array[j];
		}
	}

	public static void SetSpriteVertexNormals(Vector3[] pos, Vector3 pMin, Vector3 pMax, Vector3[] spriteDefNormals, Vector4[] spriteDefTangents, Vector3[] normals, Vector4[] tangents)
	{
		Vector3 vector = pMax - pMin;
		int num = pos.Length;
		for (int i = 0; i < num; i++)
		{
			Vector3 vector2 = pos[i];
			float num2 = (vector2.x - pMin.x) / vector.x;
			float num3 = (vector2.y - pMin.y) / vector.y;
			float num4 = (1f - num2) * (1f - num3);
			float num5 = num2 * (1f - num3);
			float num6 = (1f - num2) * num3;
			float num7 = num2 * num3;
			if (spriteDefNormals != null && spriteDefNormals.Length == 4 && i < normals.Length)
			{
				normals[i] = spriteDefNormals[0] * num4 + spriteDefNormals[1] * num5 + spriteDefNormals[2] * num6 + spriteDefNormals[3] * num7;
			}
			if (spriteDefTangents != null && spriteDefTangents.Length == 4 && i < tangents.Length)
			{
				tangents[i] = spriteDefTangents[0] * num4 + spriteDefTangents[1] * num5 + spriteDefTangents[2] * num6 + spriteDefTangents[3] * num7;
			}
		}
	}
}
[Serializable]
public class tk2dBatchedSprite
{
	public enum Type
	{
		EmptyGameObject,
		Sprite,
		TiledSprite,
		SlicedSprite,
		ClippedSprite,
		TextMesh
	}

	[Flags]
	public enum Flags
	{
		None = 0,
		Sprite_CreateBoxCollider = 1,
		SlicedSprite_BorderOnly = 2
	}

	public Type type = Type.Sprite;

	public string name = "";

	public int parentId = -1;

	public int spriteId;

	public int xRefId = -1;

	public tk2dSpriteCollectionData spriteCollection;

	public Quaternion rotation = Quaternion.identity;

	public Vector3 position = Vector3.zero;

	public Vector3 localScale = Vector3.one;

	public Color color = Color.white;

	public Vector3 baseScale = Vector3.one;

	public int renderLayer;

	[SerializeField]
	private Vector2 internalData0;

	[SerializeField]
	private Vector2 internalData1;

	[SerializeField]
	private Vector2 internalData2;

	[SerializeField]
	private Vector2 colliderData = new Vector2(0f, 1f);

	[SerializeField]
	private string formattedText = "";

	[SerializeField]
	private Flags flags;

	public tk2dBaseSprite.Anchor anchor;

	public Matrix4x4 relativeMatrix = Matrix4x4.identity;

	private Vector3 cachedBoundsCenter = Vector3.zero;

	private Vector3 cachedBoundsExtents = Vector3.zero;

	public float BoxColliderOffsetZ
	{
		get
		{
			return colliderData.x;
		}
		set
		{
			colliderData.x = value;
		}
	}

	public float BoxColliderExtentZ
	{
		get
		{
			return colliderData.y;
		}
		set
		{
			colliderData.y = value;
		}
	}

	public string FormattedText
	{
		get
		{
			return formattedText;
		}
		set
		{
			formattedText = value;
		}
	}

	public Vector2 ClippedSpriteRegionBottomLeft
	{
		get
		{
			return internalData0;
		}
		set
		{
			internalData0 = value;
		}
	}

	public Vector2 ClippedSpriteRegionTopRight
	{
		get
		{
			return internalData1;
		}
		set
		{
			internalData1 = value;
		}
	}

	public Vector2 SlicedSpriteBorderBottomLeft
	{
		get
		{
			return internalData0;
		}
		set
		{
			internalData0 = value;
		}
	}

	public Vector2 SlicedSpriteBorderTopRight
	{
		get
		{
			return internalData1;
		}
		set
		{
			internalData1 = value;
		}
	}

	public Vector2 Dimensions
	{
		get
		{
			return internalData2;
		}
		set
		{
			internalData2 = value;
		}
	}

	public bool IsDrawn => type != Type.EmptyGameObject;

	public Vector3 CachedBoundsCenter
	{
		get
		{
			return cachedBoundsCenter;
		}
		set
		{
			cachedBoundsCenter = value;
		}
	}

	public Vector3 CachedBoundsExtents
	{
		get
		{
			return cachedBoundsExtents;
		}
		set
		{
			cachedBoundsExtents = value;
		}
	}

	public bool CheckFlag(Flags mask)
	{
		return (flags & mask) != 0;
	}

	public void SetFlag(Flags mask, bool value)
	{
		if (value)
		{
			flags |= mask;
		}
		else
		{
			flags &= ~mask;
		}
	}

	public tk2dSpriteDefinition GetSpriteDefinition()
	{
		if (spriteCollection != null && spriteId != -1)
		{
			return spriteCollection.inst.spriteDefinitions[spriteId];
		}
		return null;
	}

	public tk2dBatchedSprite()
	{
		parentId = -1;
	}
}
[AddComponentMenu("2D Toolkit/Sprite/tk2dStaticSpriteBatcher")]
[RequireComponent(typeof(MeshRenderer))]
[RequireComponent(typeof(MeshFilter))]
[ExecuteInEditMode]
public class tk2dStaticSpriteBatcher : MonoBehaviour, ISpriteCollectionForceBuild
{
	public enum Flags
	{
		None = 0,
		GenerateCollider = 1,
		FlattenDepth = 2,
		SortToCamera = 4
	}

	public static int CURRENT_VERSION = 3;

	public int version;

	public tk2dBatchedSprite[] batchedSprites;

	public tk2dTextMeshData[] allTextMeshData;

	public tk2dSpriteCollectionData spriteCollection;

	[SerializeField]
	private Flags flags = Flags.GenerateCollider;

	private Mesh mesh;

	private Mesh colliderMesh;

	[SerializeField]
	private Vector3 _scale = new Vector3(1f, 1f, 1f);

	public bool CheckFlag(Flags mask)
	{
		return (flags & mask) != 0;
	}

	public void SetFlag(Flags mask, bool value)
	{
		if (CheckFlag(mask) != value)
		{
			if (value)
			{
				flags |= mask;
			}
			else
			{
				flags &= ~mask;
			}
			Build();
		}
	}

	private void Awake()
	{
		Build();
	}

	private bool UpgradeData()
	{
		if (version == CURRENT_VERSION)
		{
			return false;
		}
		if (_scale == Vector3.zero)
		{
			_scale = Vector3.one;
		}
		if (version < 2 && batchedSprites != null)
		{
			tk2dBatchedSprite[] array = batchedSprites;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].parentId = -1;
			}
		}
		if (version < 3)
		{
			if (batchedSprites != null)
			{
				tk2dBatchedSprite[] array = batchedSprites;
				foreach (tk2dBatchedSprite tk2dBatchedSprite2 in array)
				{
					if (tk2dBatchedSprite2.spriteId == -1)
					{
						tk2dBatchedSprite2.type = tk2dBatchedSprite.Type.EmptyGameObject;
						continue;
					}
					tk2dBatchedSprite2.type = tk2dBatchedSprite.Type.Sprite;
					if (tk2dBatchedSprite2.spriteCollection == null)
					{
						tk2dBatchedSprite2.spriteCollection = spriteCollection;
					}
				}
				UpdateMatrices();
			}
			spriteCollection = null;
		}
		version = CURRENT_VERSION;
		return true;
	}

	protected void OnDestroy()
	{
		if ((bool)mesh)
		{
			UnityEngine.Object.Destroy(mesh);
		}
		if ((bool)colliderMesh)
		{
			UnityEngine.Object.Destroy(colliderMesh);
		}
	}

	public void UpdateMatrices()
	{
		bool flag = false;
		tk2dBatchedSprite[] array = batchedSprites;
		for (int i = 0; i < array.Length; i++)
		{
			if (array[i].parentId != -1)
			{
				flag = true;
				break;
			}
		}
		if (flag)
		{
			Matrix4x4 matrix4x = default(Matrix4x4);
			List<tk2dBatchedSprite> list = new List<tk2dBatchedSprite>(batchedSprites);
			list.Sort((tk2dBatchedSprite a, tk2dBatchedSprite b) => a.parentId.CompareTo(b.parentId));
			{
				foreach (tk2dBatchedSprite item in list)
				{
					matrix4x.SetTRS(item.position, item.rotation, item.localScale);
					item.relativeMatrix = ((item.parentId == -1) ? Matrix4x4.identity : batchedSprites[item.parentId].relativeMatrix) * matrix4x;
				}
				return;
			}
		}
		array = batchedSprites;
		foreach (tk2dBatchedSprite tk2dBatchedSprite2 in array)
		{
			tk2dBatchedSprite2.relativeMatrix.SetTRS(tk2dBatchedSprite2.position, tk2dBatchedSprite2.rotation, tk2dBatchedSprite2.localScale);
		}
	}

	public void Build()
	{
		UpgradeData();
		if (mesh == null)
		{
			mesh = new Mesh();
			mesh.hideFlags = HideFlags.DontSave;
			GetComponent<MeshFilter>().mesh = mesh;
		}
		else
		{
			mesh.Clear();
		}
		if ((bool)colliderMesh)
		{
			UnityEngine.Object.Destroy(colliderMesh);
			colliderMesh = null;
		}
		if (batchedSprites != null && batchedSprites.Length != 0)
		{
			SortBatchedSprites();
			BuildRenderMesh();
			BuildPhysicsMesh();
		}
	}

	private void SortBatchedSprites()
	{
		List<tk2dBatchedSprite> list = new List<tk2dBatchedSprite>();
		List<tk2dBatchedSprite> list2 = new List<tk2dBatchedSprite>();
		List<tk2dBatchedSprite> list3 = new List<tk2dBatchedSprite>();
		tk2dBatchedSprite[] array = batchedSprites;
		foreach (tk2dBatchedSprite tk2dBatchedSprite2 in array)
		{
			if (!tk2dBatchedSprite2.IsDrawn)
			{
				list3.Add(tk2dBatchedSprite2);
				continue;
			}
			Material material = GetMaterial(tk2dBatchedSprite2);
			if (material != null)
			{
				if (material.renderQueue == 2000)
				{
					list.Add(tk2dBatchedSprite2);
				}
				else
				{
					list2.Add(tk2dBatchedSprite2);
				}
			}
			else
			{
				list.Add(tk2dBatchedSprite2);
			}
		}
		List<tk2dBatchedSprite> list4 = new List<tk2dBatchedSprite>(list.Count + list2.Count + list3.Count);
		list4.AddRange(list);
		list4.AddRange(list2);
		list4.AddRange(list3);
		Dictionary<tk2dBatchedSprite, int> dictionary = new Dictionary<tk2dBatchedSprite, int>();
		int num = 0;
		foreach (tk2dBatchedSprite item in list4)
		{
			dictionary[item] = num++;
		}
		foreach (tk2dBatchedSprite item2 in list4)
		{
			if (item2.parentId != -1)
			{
				item2.parentId = dictionary[batchedSprites[item2.parentId]];
			}
		}
		batchedSprites = list4.ToArray();
	}

	private Material GetMaterial(tk2dBatchedSprite bs)
	{
		return bs.type switch
		{
			tk2dBatchedSprite.Type.EmptyGameObject => null, 
			tk2dBatchedSprite.Type.TextMesh => allTextMeshData[bs.xRefId].font.materialInst, 
			_ => bs.GetSpriteDefinition().materialInst, 
		};
	}

