[AddComponentMenu("2D Toolkit/UI/tk2dUIDropDownMenu")]
public class tk2dUIDropDownMenu : MonoBehaviour
{
	public tk2dUIItem dropDownButton;

	public tk2dTextMesh selectedTextMesh;

	[HideInInspector]
	public float height;

	public tk2dUIDropDownItem dropDownItemTemplate;

	[SerializeField]
	private string[] startingItemList;

	[SerializeField]
	private int startingIndex;

	private List<string> itemList = new List<string>();

	public string SendMessageOnSelectedItemChangeMethodName = "";

	private int index;

	private List<tk2dUIDropDownItem> dropDownItems = new List<tk2dUIDropDownItem>();

	private bool isExpanded;

	[SerializeField]
	[HideInInspector]
	private tk2dUILayout menuLayoutItem;

	[SerializeField]
	[HideInInspector]
	private tk2dUILayout templateLayoutItem;

	public List<string> ItemList
	{
		get
		{
			return itemList;
		}
		set
		{
			itemList = value;
		}
	}

	public int Index
	{
		get
		{
			return index;
		}
		set
		{
			index = Mathf.Clamp(value, 0, ItemList.Count - 1);
			SetSelectedItem();
		}
	}

	public string SelectedItem
	{
		get
		{
			if (index >= 0 && index < itemList.Count)
			{
				return itemList[index];
			}
			return "";
		}
	}

	public GameObject SendMessageTarget
	{
		get
		{
			if (dropDownButton != null)
			{
				return dropDownButton.sendMessageTarget;
			}
			return null;
		}
		set
		{
			if (dropDownButton != null && dropDownButton.sendMessageTarget != value)
			{
				dropDownButton.sendMessageTarget = value;
			}
		}
	}

	public tk2dUILayout MenuLayoutItem
	{
		get
		{
			return menuLayoutItem;
		}
		set
		{
			menuLayoutItem = value;
		}
	}

	public tk2dUILayout TemplateLayoutItem
	{
		get
		{
			return templateLayoutItem;
		}
		set
		{
			templateLayoutItem = value;
		}
	}

	public event Action OnSelectedItemChange;

	private void Awake()
	{
		string[] array = startingItemList;
		foreach (string item in array)
		{
			itemList.Add(item);
		}
		index = startingIndex;
		dropDownItemTemplate.gameObject.SetActive(value: false);
		UpdateList();
	}

	private void OnEnable()
	{
		dropDownButton.OnDown += ExpandButtonPressed;
	}

	private void OnDisable()
	{
		dropDownButton.OnDown -= ExpandButtonPressed;
	}

	public void UpdateList()
	{
		if (dropDownItems.Count > ItemList.Count)
		{
			for (int i = ItemList.Count; i < dropDownItems.Count; i++)
			{
				dropDownItems[i].gameObject.SetActive(value: false);
			}
		}
		while (dropDownItems.Count < ItemList.Count)
		{
			dropDownItems.Add(CreateAnotherDropDownItem());
		}
		for (int j = 0; j < ItemList.Count; j++)
		{
			tk2dUIDropDownItem tk2dUIDropDownItem2 = dropDownItems[j];
			Vector3 localPosition = tk2dUIDropDownItem2.transform.localPosition;
			if (menuLayoutItem != null && templateLayoutItem != null)
			{
				localPosition.y = menuLayoutItem.bMin.y - (float)j * (templateLayoutItem.bMax.y - templateLayoutItem.bMin.y);
			}
			else
			{
				localPosition.y = 0f - height - (float)j * tk2dUIDropDownItem2.height;
			}
			tk2dUIDropDownItem2.transform.localPosition = localPosition;
			if (tk2dUIDropDownItem2.label != null)
			{
				tk2dUIDropDownItem2.LabelText = itemList[j];
			}
			tk2dUIDropDownItem2.Index = j;
		}
		SetSelectedItem();
	}

	public void SetSelectedItem()
	{
		if (index < 0 || index >= ItemList.Count)
		{
			index = 0;
		}
		if (index >= 0 && index < ItemList.Count)
		{
			selectedTextMesh.text = ItemList[index];
			selectedTextMesh.Commit();
		}
		else
		{
			selectedTextMesh.text = "";
			selectedTextMesh.Commit();
		}
		if (OnSelectedItemChange != null)
		{
			OnSelectedItemChange();
		}
		if (SendMessageTarget != null && SendMessageOnSelectedItemChangeMethodName.Length > 0)
		{
			SendMessageTarget.SendMessage(SendMessageOnSelectedItemChangeMethodName, this, SendMessageOptions.RequireReceiver);
		}
	}

	private tk2dUIDropDownItem CreateAnotherDropDownItem()
	{
		GameObject obj = UnityEngine.Object.Instantiate(dropDownItemTemplate.gameObject);
		obj.name = "DropDownItem";
		obj.transform.parent = base.transform;
		obj.transform.localPosition = dropDownItemTemplate.transform.localPosition;
		obj.transform.localRotation = dropDownItemTemplate.transform.localRotation;
		obj.transform.localScale = dropDownItemTemplate.transform.localScale;
		tk2dUIDropDownItem component = obj.GetComponent<tk2dUIDropDownItem>();
		component.OnItemSelected += ItemSelected;
		(component.upDownHoverBtn = obj.GetComponent<tk2dUIUpDownHoverButton>()).OnToggleOver += DropDownItemHoverBtnToggle;
		return component;
	}

	private void ItemSelected(tk2dUIDropDownItem item)
	{
		if (isExpanded)
		{
			CollapseList();
		}
		Index = item.Index;
	}

	private void ExpandButtonPressed()
	{
		if (isExpanded)
		{
			CollapseList();
		}
		else
		{
			ExpandList();
		}
	}

	private void ExpandList()
	{
		isExpanded = true;
		int num = Mathf.Min(ItemList.Count, dropDownItems.Count);
		for (int i = 0; i < num; i++)
		{
			dropDownItems[i].gameObject.SetActive(value: true);
		}
		tk2dUIDropDownItem tk2dUIDropDownItem2 = dropDownItems[index];
		if (tk2dUIDropDownItem2.upDownHoverBtn != null)
		{
			tk2dUIDropDownItem2.upDownHoverBtn.IsOver = true;
		}
	}

	private void CollapseList()
	{
		isExpanded = false;
		foreach (tk2dUIDropDownItem dropDownItem in dropDownItems)
		{
			dropDownItem.gameObject.SetActive(value: false);
		}
	}

	private void DropDownItemHoverBtnToggle(tk2dUIUpDownHoverButton upDownHoverButton)
	{
		if (!upDownHoverButton.IsOver)
		{
			return;
		}
		foreach (tk2dUIDropDownItem dropDownItem in dropDownItems)
		{
			if (dropDownItem.upDownHoverBtn != upDownHoverButton && dropDownItem.upDownHoverBtn != null)
			{
				dropDownItem.upDownHoverBtn.IsOver = false;
			}
		}
	}

	private void OnDestroy()
	{
		foreach (tk2dUIDropDownItem dropDownItem in dropDownItems)
		{
			dropDownItem.OnItemSelected -= ItemSelected;
			if (dropDownItem.upDownHoverBtn != null)
			{
				dropDownItem.upDownHoverBtn.OnToggleOver -= DropDownItemHoverBtnToggle;
			}
		}
	}
}
[AddComponentMenu("2D Toolkit/UI/tk2dUIHoverItem")]
public class tk2dUIHoverItem : tk2dUIBaseItemControl
{
	public GameObject outStateGO;

	public GameObject overStateGO;

	private bool isOver;

	public string SendMessageOnToggleHoverMethodName = "";

	public bool IsOver
	{
		get
		{
			return isOver;
		}
		set
		{
			if (isOver != value)
			{
				isOver = value;
				SetState();
				if (OnToggleHover != null)
				{
					OnToggleHover(this);
				}
				DoSendMessage(SendMessageOnToggleHoverMethodName, this);
			}
		}
	}

	public event Action<tk2dUIHoverItem> OnToggleHover;

	private void Start()
	{
		SetState();
	}

	private void OnEnable()
	{
		if ((bool)uiItem)
		{
			uiItem.OnHoverOver += HoverOver;
			uiItem.OnHoverOut += HoverOut;
		}
	}

	private void OnDisable()
	{
		if ((bool)uiItem)
		{
			uiItem.OnHoverOver -= HoverOver;
			uiItem.OnHoverOut -= HoverOut;
		}
	}

	private void HoverOver()
	{
		IsOver = true;
	}

	private void HoverOut()
	{
		IsOver = false;
	}

	public void SetState()
	{
		tk2dUIBaseItemControl.ChangeGameObjectActiveStateWithNullCheck(overStateGO, isOver);
		tk2dUIBaseItemControl.ChangeGameObjectActiveStateWithNullCheck(outStateGO, !isOver);
	}
}
[AddComponentMenu("2D Toolkit/UI/tk2dUIMultiStateToggleButton")]
public class tk2dUIMultiStateToggleButton : tk2dUIBaseItemControl
{
	public GameObject[] states;

	public bool activateOnPress;

	private int index;

	public string SendMessageOnStateToggleMethodName = "";

	public int Index
	{
		get
		{
			return index;
		}
		set
		{
			if (value >= states.Length)
			{
				value = states.Length;
			}
			if (value < 0)
			{
				value = 0;
			}
			if (index != value)
			{
				index = value;
				SetState();
				if (OnStateToggle != null)
				{
					OnStateToggle(this);
				}
				DoSendMessage(SendMessageOnStateToggleMethodName, this);
			}
		}
	}

	public event Action<tk2dUIMultiStateToggleButton> OnStateToggle;

	private void Start()
	{
		SetState();
	}

	private void OnEnable()
	{
		if ((bool)uiItem)
		{
			uiItem.OnClick += ButtonClick;
			uiItem.OnDown += ButtonDown;
		}
	}

	private void OnDisable()
	{
		if ((bool)uiItem)
		{
			uiItem.OnClick -= ButtonClick;
			uiItem.OnDown -= ButtonDown;
		}
	}

	private void ButtonClick()
	{
		if (!activateOnPress)
		{
			ButtonToggle();
		}
	}

	private void ButtonDown()
	{
		if (activateOnPress)
		{
			ButtonToggle();
		}
	}

	private void ButtonToggle()
	{
		if (Index + 1 >= states.Length)
		{
			Index = 0;
		}
		else
		{
			Index++;
		}
	}

	private void SetState()
	{
		for (int i = 0; i < states.Length; i++)
		{
			if (!(states[i] != null))
			{
				continue;
			}
			if (i != index)
			{
				if (states[i].activeInHierarchy)
				{
					states[i].SetActive(value: false);
				}
			}
			else if (!states[i].activeInHierarchy)
			{
				states[i].SetActive(value: true);
			}
		}
	}
}
[AddComponentMenu("2D Toolkit/UI/tk2dUIProgressBar")]
public class tk2dUIProgressBar : MonoBehaviour
{
	public Transform scalableBar;

	public tk2dClippedSprite clippedSpriteBar;

	public tk2dSlicedSprite slicedSpriteBar;

	private bool initializedSlicedSpriteDimensions;

	private Vector2 emptySlicedSpriteDimensions = Vector2.zero;

	private Vector2 fullSlicedSpriteDimensions = Vector2.zero;

	private Vector2 currentDimensions = Vector2.zero;

	[SerializeField]
	private float percent;

	private bool isProgressComplete;

	public GameObject sendMessageTarget;

	public string SendMessageOnProgressCompleteMethodName = "";

	public float Value
	{
		get
		{
			return percent;
		}
		set
		{
			percent = Mathf.Clamp(value, 0f, 1f);
			if (!Application.isPlaying)
			{
				return;
			}
			if (clippedSpriteBar != null)
			{
				clippedSpriteBar.clipTopRight = new Vector2(Value, 1f);
			}
			else if (scalableBar != null)
			{
				scalableBar.localScale = new Vector3(Value, scalableBar.localScale.y, scalableBar.localScale.z);
			}
			else if (slicedSpriteBar != null)
			{
				InitializeSlicedSpriteDimensions();
				float newX = Mathf.Lerp(emptySlicedSpriteDimensions.x, fullSlicedSpriteDimensions.x, Value);
				currentDimensions.Set(newX, fullSlicedSpriteDimensions.y);
				slicedSpriteBar.dimensions = currentDimensions;
			}
			if (!isProgressComplete && Value == 1f)
			{
				isProgressComplete = true;
				if (OnProgressComplete != null)
				{
					OnProgressComplete();
				}
				if (sendMessageTarget != null && SendMessageOnProgressCompleteMethodName.Length > 0)
				{
					sendMessageTarget.SendMessage(SendMessageOnProgressCompleteMethodName, this, SendMessageOptions.RequireReceiver);
				}
			}
			else if (isProgressComplete && Value < 1f)
			{
				isProgressComplete = false;
			}
		}
	}

	public event Action OnProgressComplete;

	private void Start()
	{
		InitializeSlicedSpriteDimensions();
		Value = percent;
	}

	private void InitializeSlicedSpriteDimensions()
	{
		if (!initializedSlicedSpriteDimensions)
		{
			if (slicedSpriteBar != null)
			{
				tk2dSpriteDefinition currentSprite = slicedSpriteBar.CurrentSprite;
				Vector3 vector = currentSprite.boundsData[1];
				fullSlicedSpriteDimensions = slicedSpriteBar.dimensions;
				emptySlicedSpriteDimensions.Set((slicedSpriteBar.borderLeft + slicedSpriteBar.borderRight) * vector.x / currentSprite.texelSize.x, fullSlicedSpriteDimensions.y);
			}
			initializedSlicedSpriteDimensions = true;
		}
	}
}
[ExecuteInEditMode]
[AddComponentMenu("2D Toolkit/UI/tk2dUIScrollableArea")]
public class tk2dUIScrollableArea : MonoBehaviour
{
	public enum Axes
	{
		XAxis,
		YAxis
	}

	[SerializeField]
	private float contentLength = 1f;

	[SerializeField]
	private float visibleAreaLength = 1f;

	public GameObject contentContainer;

	public tk2dUIScrollbar scrollBar;

	public tk2dUIItem backgroundUIItem;

	public Axes scrollAxes = Axes.YAxis;

	public bool allowSwipeScrolling = true;

	public bool allowScrollWheel = true;

	[SerializeField]
	[HideInInspector]
	private tk2dUILayout backgroundLayoutItem;

	[SerializeField]
	[HideInInspector]
	private tk2dUILayoutContainer contentLayoutContainer;

	private bool isBackgroundButtonDown;

	private bool isBackgroundButtonOver;

	private Vector3 swipeScrollingPressDownStartLocalPos = Vector3.zero;

	private Vector3 swipeScrollingContentStartLocalPos = Vector3.zero;

	private Vector3 swipeScrollingContentDestLocalPos = Vector3.zero;

	private bool isSwipeScrollingInProgress;

	private const float SWIPE_SCROLLING_FIRST_SCROLL_THRESHOLD = 0.02f;

	private const float WITHOUT_SCROLLBAR_FIXED_SCROLL_WHEEL_PERCENT = 0.1f;

	private Vector3 swipePrevScrollingContentPressLocalPos = Vector3.zero;

	private float swipeCurrVelocity;

	private float snapBackVelocity;

	public string SendMessageOnScrollMethodName = "";

	private float percent;

	private static readonly Vector3[] boxExtents = new Vector3[8]
	{
		new Vector3(-1f, -1f, -1f),
		new Vector3(1f, -1f, -1f),
		new Vector3(-1f, 1f, -1f),
		new Vector3(1f, 1f, -1f),
		new Vector3(-1f, -1f, 1f),
		new Vector3(1f, -1f, 1f),
		new Vector3(-1f, 1f, 1f),
		new Vector3(1f, 1f, 1f)
	};

	public float ContentLength
	{
		get
		{
			return contentLength;
		}
		set
		{
			ContentLengthVisibleAreaLengthChange(contentLength, value, visibleAreaLength, visibleAreaLength);
		}
	}

	public float VisibleAreaLength
	{
		get
		{
			return visibleAreaLength;
		}
		set
		{
			ContentLengthVisibleAreaLengthChange(contentLength, contentLength, visibleAreaLength, value);
		}
	}

	public tk2dUILayout BackgroundLayoutItem
	{
		get
		{
			return backgroundLayoutItem;
		}
		set
		{
			if (backgroundLayoutItem != value)
			{
				if (backgroundLayoutItem != null)
				{
					backgroundLayoutItem.OnReshape -= LayoutReshaped;
				}
				backgroundLayoutItem = value;
				if (backgroundLayoutItem != null)
				{
					backgroundLayoutItem.OnReshape += LayoutReshaped;
				}
			}
		}
	}

	public tk2dUILayoutContainer ContentLayoutContainer
	{
		get
		{
			return contentLayoutContainer;
		}
		set
		{
			if (contentLayoutContainer != value)
			{
				if (contentLayoutContainer != null)
				{
					contentLayoutContainer.OnChangeContent -= ContentLayoutChangeCallback;
				}
				contentLayoutContainer = value;
				if (contentLayoutContainer != null)
				{
					contentLayoutContainer.OnChangeContent += ContentLayoutChangeCallback;
				}
			}
		}
	}

	public GameObject SendMessageTarget
	{
		get
		{
			if (backgroundUIItem != null)
			{
				return backgroundUIItem.sendMessageTarget;
			}
			return null;
		}
		set
		{
			if (backgroundUIItem != null && backgroundUIItem.sendMessageTarget != value)
			{
				backgroundUIItem.sendMessageTarget = value;
			}
		}
	}

	public float Value
	{
		get
		{
			return Mathf.Clamp01(percent);
		}
		set
		{
			value = Mathf.Clamp(value, 0f, 1f);
			if (value != percent)
			{
				UnpressAllUIItemChildren();
				percent = value;
				if (OnScroll != null)
				{
					OnScroll(this);
				}
				if (isBackgroundButtonDown || isSwipeScrollingInProgress)
				{
					if (tk2dUIManager.Instance__NoCreate != null)
					{
						tk2dUIManager.Instance.OnInputUpdate -= BackgroundOverUpdate;
					}
					isBackgroundButtonDown = false;
					isSwipeScrollingInProgress = false;
				}
				TargetOnScrollCallback();
			}
			if (scrollBar != null)
			{
				scrollBar.SetScrollPercentWithoutEvent(percent);
			}
			SetContentPosition();
		}
	}

	private Vector3 ContentContainerOffset
	{
		get
		{
			return Vector3.Scale(new Vector3(-1f, 1f, 1f), contentContainer.transform.localPosition);
		}
		set
		{
			contentContainer.transform.localPosition = Vector3.Scale(new Vector3(-1f, 1f, 1f), value);
		}
	}

	public event Action<tk2dUIScrollableArea> OnScroll;

	public void SetScrollPercentWithoutEvent(float newScrollPercent)
	{
		percent = Mathf.Clamp(newScrollPercent, 0f, 1f);
		UnpressAllUIItemChildren();
		if (scrollBar != null)
		{
			scrollBar.SetScrollPercentWithoutEvent(percent);
		}
		SetContentPosition();
	}

	public float MeasureContentLength()
	{
		Vector3 vector = new Vector3(float.MinValue, float.MinValue, float.MinValue);
		Vector3 vector2 = new Vector3(float.MaxValue, float.MaxValue, float.MaxValue);
		Vector3[] array = new Vector3[2] { vector2, vector };
		Transform transform = contentContainer.transform;
		GetRendererBoundsInChildren(transform.worldToLocalMatrix, array, transform);
		if (array[0] != vector2 && array[1] != vector)
		{
			array[0] = Vector3.Min(array[0], Vector3.zero);
			array[1] = Vector3.Max(array[1], Vector3.zero);
			if (scrollAxes != Axes.YAxis)
			{
				return array[1].x - array[0].x;
			}
			return array[1].y - array[0].y;
		}
		UnityEngine.Debug.LogError("Unable to measure content length");
		return VisibleAreaLength * 0.9f;
	}

	private void OnEnable()
	{
		if (scrollBar != null)
		{
			scrollBar.OnScroll += ScrollBarMove;
		}
		if (backgroundUIItem != null)
		{
			backgroundUIItem.OnDown += BackgroundButtonDown;
			backgroundUIItem.OnRelease += BackgroundButtonRelease;
			backgroundUIItem.OnHoverOver += BackgroundButtonHoverOver;
			backgroundUIItem.OnHoverOut += BackgroundButtonHoverOut;
		}
		if (backgroundLayoutItem != null)
		{
			backgroundLayoutItem.OnReshape += LayoutReshaped;
		}
		if (contentLayoutContainer != null)
		{
			contentLayoutContainer.OnChangeContent += ContentLayoutChangeCallback;
		}
	}

	private void OnDisable()
	{
		if (scrollBar != null)
		{
			scrollBar.OnScroll -= ScrollBarMove;
		}
		if (backgroundUIItem != null)
		{
			backgroundUIItem.OnDown -= BackgroundButtonDown;
			backgroundUIItem.OnRelease -= BackgroundButtonRelease;
			backgroundUIItem.OnHoverOver -= BackgroundButtonHoverOver;
			backgroundUIItem.OnHoverOut -= BackgroundButtonHoverOut;
		}
		if (isBackgroundButtonOver)
		{
			if (tk2dUIManager.Instance__NoCreate != null)
			{
				tk2dUIManager.Instance.OnScrollWheelChange -= BackgroundHoverOverScrollWheelChange;
			}
			isBackgroundButtonOver = false;
		}
		if (isBackgroundButtonDown || isSwipeScrollingInProgress)
		{
			if (tk2dUIManager.Instance__NoCreate != null)
			{
				tk2dUIManager.Instance.OnInputUpdate -= BackgroundOverUpdate;
			}
			isBackgroundButtonDown = false;
			isSwipeScrollingInProgress = false;
		}
		if (backgroundLayoutItem != null)
		{
			backgroundLayoutItem.OnReshape -= LayoutReshaped;
		}
		if (contentLayoutContainer != null)
		{
			contentLayoutContainer.OnChangeContent -= ContentLayoutChangeCallback;
		}
		swipeCurrVelocity = 0f;
	}

	private void Start()
	{
		UpdateScrollbarActiveState();
	}

	private void BackgroundHoverOverScrollWheelChange(float mouseWheelChange)
	{
		if (mouseWheelChange > 0f)
		{
			if ((bool)scrollBar)
			{
				scrollBar.ScrollUpFixed();
			}
			else
			{
				Value -= 0.1f;
			}
		}
		else if (mouseWheelChange < 0f)
		{
			if ((bool)scrollBar)
			{
				scrollBar.ScrollDownFixed();
			}
			else
			{
				Value += 0.1f;
			}
		}
	}

	private void ScrollBarMove(tk2dUIScrollbar scrollBar)
	{
		Value = scrollBar.Value;
		isSwipeScrollingInProgress = false;
		if (isBackgroundButtonDown)
		{
			BackgroundButtonRelease();
		}
	}

	private void SetContentPosition()
	{
		Vector3 contentContainerOffset = ContentContainerOffset;
		float num = (contentLength - visibleAreaLength) * Value;
		if (num < 0f)
		{
			num = 0f;
		}
		if (scrollAxes == Axes.XAxis)
		{
			contentContainerOffset.x = num;
		}
		else if (scrollAxes == Axes.YAxis)
		{
			contentContainerOffset.y = num;
		}
		ContentContainerOffset = contentContainerOffset;
	}

	private void BackgroundButtonDown()
	{
		if (allowSwipeScrolling && contentLength > visibleAreaLength)
		{
			if (!isBackgroundButtonDown && !isSwipeScrollingInProgress)
			{
				tk2dUIManager.Instance.OnInputUpdate += BackgroundOverUpdate;
			}
			swipeScrollingPressDownStartLocalPos = base.transform.InverseTransformPoint(CalculateClickWorldPos(backgroundUIItem));
			swipePrevScrollingContentPressLocalPos = swipeScrollingPressDownStartLocalPos;
			swipeScrollingContentStartLocalPos = ContentContainerOffset;
			swipeScrollingContentDestLocalPos = swipeScrollingContentStartLocalPos;
			isBackgroundButtonDown = true;
			swipeCurrVelocity = 0f;
		}
	}

	private void BackgroundOverUpdate()
	{
		if (isBackgroundButtonDown)
		{
			UpdateSwipeScrollDestintationPosition();
		}
		if (!isSwipeScrollingInProgress)
		{
			return;
		}
		float num = percent;
		float num2 = 0f;
		if (scrollAxes == Axes.XAxis)
		{
			num2 = swipeScrollingContentDestLocalPos.x;
		}
		else if (scrollAxes == Axes.YAxis)
		{
			num2 = swipeScrollingContentDestLocalPos.y;
		}
		float num3 = 0f;
		float num4 = contentLength - visibleAreaLength;
		if (isBackgroundButtonDown)
		{
			if (num2 < num3)
			{
				num2 += (0f - num2) / visibleAreaLength / 2f;
				if (num2 > num3)
				{
					num2 = num3;
				}
			}
			else if (num2 > num4)
			{
				num2 -= (num2 - num4) / visibleAreaLength / 2f;
				if (num2 < num4)
				{
					num2 = num4;
				}
			}
			if (scrollAxes == Axes.XAxis)
			{
				swipeScrollingContentDestLocalPos.x = num2;
			}
			else if (scrollAxes == Axes.YAxis)
			{
				swipeScrollingContentDestLocalPos.y = num2;
			}
			num = ((!(contentLength - visibleAreaLength > Mathf.Epsilon)) ? 0f : (num2 / (contentLength - visibleAreaLength)));
		}
		else
		{
			float num5 = visibleAreaLength * 0.001f;
			if (num2 < num3 || num2 > num4)
			{
				float num6 = ((num2 < num3) ? num3 : num4);
				num2 = Mathf.SmoothDamp(num2, num6, ref snapBackVelocity, 0.05f, float.PositiveInfinity, tk2dUITime.deltaTime);
				if (Mathf.Abs(snapBackVelocity) < num5)
				{
					num2 = num6;
					snapBackVelocity = 0f;
				}
				swipeCurrVelocity = 0f;
			}
			else if (swipeCurrVelocity != 0f)
			{
				num2 += swipeCurrVelocity * tk2dUITime.deltaTime * 20f;
				if (swipeCurrVelocity > num5 || swipeCurrVelocity < 0f - num5)
				{
					swipeCurrVelocity = Mathf.Lerp(swipeCurrVelocity, 0f, tk2dUITime.deltaTime * 2.5f);
				}
				else
				{
					swipeCurrVelocity = 0f;
				}
			}
			else
			{
				isSwipeScrollingInProgress = false;
				tk2dUIManager.Instance.OnInputUpdate -= BackgroundOverUpdate;
			}
			if (scrollAxes == Axes.XAxis)
			{
				swipeScrollingContentDestLocalPos.x = num2;
			}
			else if (scrollAxes == Axes.YAxis)
			{
				swipeScrollingContentDestLocalPos.y = num2;
			}
			num = num2 / (contentLength - visibleAreaLength);
		}
		if (num != percent)
		{
			percent = num;
			ContentContainerOffset = swipeScrollingContentDestLocalPos;
			if (OnScroll != null)
			{
				OnScroll(this);
			}
			TargetOnScrollCallback();
		}
		if (scrollBar != null)
		{
			float scrollPercentWithoutEvent = percent;
			if (scrollAxes == Axes.XAxis)
			{
				scrollPercentWithoutEvent = ContentContainerOffset.x / (contentLength - visibleAreaLength);
			}
			else if (scrollAxes == Axes.YAxis)
			{
				scrollPercentWithoutEvent = ContentContainerOffset.y / (contentLength - visibleAreaLength);
			}
			scrollBar.SetScrollPercentWithoutEvent(scrollPercentWithoutEvent);
		}
	}

	private void UpdateSwipeScrollDestintationPosition()
	{
		Vector3 vector = base.transform.InverseTransformPoint(CalculateClickWorldPos(backgroundUIItem));
		Vector3 vector2 = vector - swipeScrollingPressDownStartLocalPos;
		vector2.x *= -1f;
		float f = 0f;
		if (scrollAxes == Axes.XAxis)
		{
			f = vector2.x;
			swipeCurrVelocity = 0f - (vector.x - swipePrevScrollingContentPressLocalPos.x);
		}
		else if (scrollAxes == Axes.YAxis)
		{
			f = vector2.y;
			swipeCurrVelocity = vector.y - swipePrevScrollingContentPressLocalPos.y;
		}
		if (!isSwipeScrollingInProgress && Mathf.Abs(f) > 0.02f)
		{
			isSwipeScrollingInProgress = true;
			tk2dUIManager.Instance.OverrideClearAllChildrenPresses(backgroundUIItem);
		}
		if (isSwipeScrollingInProgress)
		{
			Vector3 vector3 = swipeScrollingContentStartLocalPos + vector2;
			vector3.z = ContentContainerOffset.z;
			if (scrollAxes == Axes.XAxis)
			{
				vector3.y = ContentContainerOffset.y;
			}
			else if (scrollAxes == Axes.YAxis)
			{
				vector3.x = ContentContainerOffset.x;
			}
			vector3.z = ContentContainerOffset.z;
			swipeScrollingContentDestLocalPos = vector3;
			swipePrevScrollingContentPressLocalPos = vector;
		}
	}

	private void BackgroundButtonRelease()
	{
		if (allowSwipeScrolling)
		{
			if (isBackgroundButtonDown && !isSwipeScrollingInProgress)
			{
				tk2dUIManager.Instance.OnInputUpdate -= BackgroundOverUpdate;
			}
			isBackgroundButtonDown = false;
		}
	}

	private void BackgroundButtonHoverOver()
	{
		if (allowScrollWheel)
		{
			if (!isBackgroundButtonOver)
			{
				tk2dUIManager.Instance.OnScrollWheelChange += BackgroundHoverOverScrollWheelChange;
			}
			isBackgroundButtonOver = true;
		}
	}

	private void BackgroundButtonHoverOut()
	{
		if (isBackgroundButtonOver)
		{
			tk2dUIManager.Instance.OnScrollWheelChange -= BackgroundHoverOverScrollWheelChange;
		}
		isBackgroundButtonOver = false;
	}

	private Vector3 CalculateClickWorldPos(tk2dUIItem btn)
	{
		Vector2 position = btn.Touch.position;
		Camera uICameraForControl = tk2dUIManager.Instance.GetUICameraForControl(base.gameObject);
		Vector3 result = uICameraForControl.ScreenToWorldPoint(new Vector3(position.x, position.y, btn.transform.position.z - uICameraForControl.transform.position.z));
		result.z = btn.transform.position.z;
		return result;
	}

	private void UpdateScrollbarActiveState()
	{
		bool flag = contentLength > visibleAreaLength;
		if (scrollBar != null && scrollBar.gameObject.activeSelf != flag)
		{
			tk2dUIBaseItemControl.ChangeGameObjectActiveState(scrollBar.gameObject, flag);
		}
	}

	private void ContentLengthVisibleAreaLengthChange(float prevContentLength, float newContentLength, float prevVisibleAreaLength, float newVisibleAreaLength)
	{
		float value = ((newContentLength - visibleAreaLength == 0f) ? 0f : ((prevContentLength - prevVisibleAreaLength) * Value / (newContentLength - newVisibleAreaLength)));
		contentLength = newContentLength;
		visibleAreaLength = newVisibleAreaLength;
		UpdateScrollbarActiveState();
		Value = value;
	}

	private void UnpressAllUIItemChildren()
	{
	}

	private void TargetOnScrollCallback()
	{
		if (SendMessageTarget != null && SendMessageOnScrollMethodName.Length > 0)
		{
			SendMessageTarget.SendMessage(SendMessageOnScrollMethodName, this, SendMessageOptions.RequireReceiver);
		}
	}

	private static void GetRendererBoundsInChildren(Matrix4x4 rootWorldToLocal, Vector3[] minMax, Transform t)
	{
		MeshFilter component = t.GetComponent<MeshFilter>();
		if (component != null && component.sharedMesh != null)
		{
			UnityEngine.Bounds bounds = component.sharedMesh.bounds;
			Matrix4x4 matrix4x = rootWorldToLocal * t.localToWorldMatrix;
			for (int i = 0; i < 8; i++)
			{
				Vector3 point = bounds.center + Vector3.Scale(bounds.extents, boxExtents[i]);
				Vector3 rhs = matrix4x.MultiplyPoint(point);
				minMax[0] = Vector3.Min(minMax[0], rhs);
				minMax[1] = Vector3.Max(minMax[1], rhs);
			}
		}
		int childCount = t.childCount;
		for (int j = 0; j < childCount; j++)
		{
			Transform child = t.GetChild(j);
			if (t.gameObject.activeSelf)
			{
				GetRendererBoundsInChildren(rootWorldToLocal, minMax, child);
			}
		}
	}

	private void LayoutReshaped(Vector3 dMin, Vector3 dMax)
	{
		VisibleAreaLength += ((scrollAxes == Axes.XAxis) ? (dMax.x - dMin.x) : (dMax.y - dMin.y));
	}

	private void ContentLayoutChangeCallback()
	{
		if (contentLayoutContainer != null)
		{
			Vector2 innerSize = contentLayoutContainer.GetInnerSize();
			ContentLength = ((scrollAxes == Axes.XAxis) ? innerSize.x : innerSize.y);
		}
	}
}
[ExecuteInEditMode]
[AddComponentMenu("2D Toolkit/UI/tk2dUIScrollbar")]
public class tk2dUIScrollbar : MonoBehaviour
{
	public enum Axes
	{
		XAxis,
		YAxis
	}

	public tk2dUIItem barUIItem;

	public float scrollBarLength;

	public tk2dUIItem thumbBtn;

	public Transform thumbTransform;

	public float thumbLength;

	public tk2dUIItem upButton;

	private tk2dUIHoverItem hoverUpButton;

	public tk2dUIItem downButton;

	private tk2dUIHoverItem hoverDownButton;

	public float buttonUpDownScrollDistance = 1f;

	public bool allowScrollWheel = true;

	public Axes scrollAxes = Axes.YAxis;

	public tk2dUIProgressBar highlightProgressBar;

	[SerializeField]
	[HideInInspector]
	private tk2dUILayout barLayoutItem;

	private bool isScrollThumbButtonDown;

	private bool isTrackHoverOver;

	private float percent;

	private Vector3 moveThumbBtnOffset = Vector3.zero;

	private int scrollUpDownButtonState;

	private float timeOfUpDownButtonPressStart;

	private float repeatUpDownButtonHoldCounter;

	private const float WITHOUT_SCROLLBAR_FIXED_SCROLL_WHEEL_PERCENT = 0.1f;

	private const float INITIAL_TIME_TO_REPEAT_UP_DOWN_SCROLL_BUTTON_SCROLLING_ON_HOLD = 0.55f;

	private const float TIME_TO_REPEAT_UP_DOWN_SCROLL_BUTTON_SCROLLING_ON_HOLD = 0.45f;

	public string SendMessageOnScrollMethodName = "";

	public tk2dUILayout BarLayoutItem
	{
		get
		{
			return barLayoutItem;
		}
		set
		{
			if (barLayoutItem != value)
			{
				if (barLayoutItem != null)
				{
					barLayoutItem.OnReshape -= LayoutReshaped;
				}
				barLayoutItem = value;
				if (barLayoutItem != null)
				{
					barLayoutItem.OnReshape += LayoutReshaped;
				}
			}
		}
	}

	public GameObject SendMessageTarget
	{
		get
		{
			if (barUIItem != null)
			{
				return barUIItem.sendMessageTarget;
			}
			return null;
		}
		set
		{
			if (barUIItem != null && barUIItem.sendMessageTarget != value)
			{
				barUIItem.sendMessageTarget = value;
			}
		}
	}

	public float Value
	{
		get
		{
			return percent;
		}
		set
		{
			percent = Mathf.Clamp(value, 0f, 1f);
			if (OnScroll != null)
			{
				OnScroll(this);
			}
			SetScrollThumbPosition();
			if (SendMessageTarget != null && SendMessageOnScrollMethodName.Length > 0)
			{
				SendMessageTarget.SendMessage(SendMessageOnScrollMethodName, this, SendMessageOptions.RequireReceiver);
			}
		}
	}

	public event Action<tk2dUIScrollbar> OnScroll;

	public void SetScrollPercentWithoutEvent(float newScrollPercent)
	{
		percent = Mathf.Clamp(newScrollPercent, 0f, 1f);
		SetScrollThumbPosition();
	}

	private void OnEnable()
	{
		if (barUIItem != null)
		{
			barUIItem.OnDown += ScrollTrackButtonDown;
			barUIItem.OnHoverOver += ScrollTrackButtonHoverOver;
			barUIItem.OnHoverOut += ScrollTrackButtonHoverOut;
		}
		if (thumbBtn != null)
		{
			thumbBtn.OnDown += ScrollThumbButtonDown;
			thumbBtn.OnRelease += ScrollThumbButtonRelease;
		}
		if (upButton != null)
		{
			upButton.OnDown += ScrollUpButtonDown;
			upButton.OnUp += ScrollUpButtonUp;
		}
		if (downButton != null)
		{
			downButton.OnDown += ScrollDownButtonDown;
			downButton.OnUp += ScrollDownButtonUp;
		}
		if (barLayoutItem != null)
		{
			barLayoutItem.OnReshape += LayoutReshaped;
		}
	}

	private void OnDisable()
	{
		if (barUIItem != null)
		{
			barUIItem.OnDown -= ScrollTrackButtonDown;
			barUIItem.OnHoverOver -= ScrollTrackButtonHoverOver;
			barUIItem.OnHoverOut -= ScrollTrackButtonHoverOut;
		}
		if (thumbBtn != null)
		{
			thumbBtn.OnDown -= ScrollThumbButtonDown;
			thumbBtn.OnRelease -= ScrollThumbButtonRelease;
		}
		if (upButton != null)
		{
			upButton.OnDown -= ScrollUpButtonDown;
			upButton.OnUp -= ScrollUpButtonUp;
		}
		if (downButton != null)
		{
			downButton.OnDown -= ScrollDownButtonDown;
			downButton.OnUp -= ScrollDownButtonUp;
		}
		if (isScrollThumbButtonDown)
		{
			if (tk2dUIManager.Instance__NoCreate != null)
			{
				tk2dUIManager.Instance.OnInputUpdate -= MoveScrollThumbButton;
			}
			isScrollThumbButtonDown = false;
		}
		if (isTrackHoverOver)
		{
			if (tk2dUIManager.Instance__NoCreate != null)
			{
				tk2dUIManager.Instance.OnScrollWheelChange -= TrackHoverScrollWheelChange;
			}
			isTrackHoverOver = false;
		}
		if (scrollUpDownButtonState != 0)
		{
			tk2dUIManager.Instance.OnInputUpdate -= CheckRepeatScrollUpDownButton;
			scrollUpDownButtonState = 0;
		}
		if (barLayoutItem != null)
		{
			barLayoutItem.OnReshape -= LayoutReshaped;
		}
	}

	private void Awake()
	{
		if (upButton != null)
		{
			hoverUpButton = upButton.GetComponent<tk2dUIHoverItem>();
		}
		if (downButton != null)
		{
			hoverDownButton = downButton.GetComponent<tk2dUIHoverItem>();
		}
	}

	private void Start()
	{
		SetScrollThumbPosition();
	}

	private void TrackHoverScrollWheelChange(float mouseWheelChange)
	{
		if (mouseWheelChange > 0f)
		{
			ScrollUpFixed();
		}
		else if (mouseWheelChange < 0f)
		{
			ScrollDownFixed();
		}
	}

	private void SetScrollThumbPosition()
	{
		if (thumbTransform != null)
		{
			float num = 0f - (scrollBarLength - thumbLength) * Value;
			Vector3 localPosition = thumbTransform.localPosition;
			if (scrollAxes == Axes.XAxis)
			{
				localPosition.x = 0f - num;
			}
			else if (scrollAxes == Axes.YAxis)
			{
				localPosition.y = num;
			}
			thumbTransform.localPosition = localPosition;
		}
		if (highlightProgressBar != null)
		{
			highlightProgressBar.Value = Value;
		}
	}

	private void MoveScrollThumbButton()
	{
		ScrollToPosition(CalculateClickWorldPos(thumbBtn) + moveThumbBtnOffset);
	}

	private Vector3 CalculateClickWorldPos(tk2dUIItem btn)
	{
		Camera uICameraForControl = tk2dUIManager.Instance.GetUICameraForControl(base.gameObject);
		Vector2 position = btn.Touch.position;
		Vector3 result = uICameraForControl.ScreenToWorldPoint(new Vector3(position.x, position.y, btn.transform.position.z - uICameraForControl.transform.position.z));
		result.z = btn.transform.position.z;
		return result;
	}

	private void ScrollToPosition(Vector3 worldPos)
	{
		Vector3 vector = thumbTransform.parent.InverseTransformPoint(worldPos);
		float num = 0f;
		if (scrollAxes == Axes.XAxis)
		{
			num = vector.x;
		}
		else if (scrollAxes == Axes.YAxis)
		{
			num = 0f - vector.y;
		}
		Value = num / (scrollBarLength - thumbLength);
	}

	private void ScrollTrackButtonDown()
	{
		ScrollToPosition(CalculateClickWorldPos(barUIItem));
	}

	private void ScrollTrackButtonHoverOver()
	{
		if (allowScrollWheel)
		{
			if (!isTrackHoverOver)
			{
				tk2dUIManager.Instance.OnScrollWheelChange += TrackHoverScrollWheelChange;
			}
			isTrackHoverOver = true;
		}
	}

	private void ScrollTrackButtonHoverOut()
	{
		if (isTrackHoverOver)
		{
			tk2dUIManager.Instance.OnScrollWheelChange -= TrackHoverScrollWheelChange;
		}
		isTrackHoverOver = false;
	}

	private void ScrollThumbButtonDown()
	{
		if (!isScrollThumbButtonDown)
		{
			tk2dUIManager.Instance.OnInputUpdate += MoveScrollThumbButton;
		}
		isScrollThumbButtonDown = true;
		Vector3 vector = CalculateClickWorldPos(thumbBtn);
		moveThumbBtnOffset = thumbBtn.transform.position - vector;
		moveThumbBtnOffset.z = 0f;
		if (hoverUpButton != null)
		{
			hoverUpButton.IsOver = true;
		}
		if (hoverDownButton != null)
		{
			hoverDownButton.IsOver = true;
		}
	}

	private void ScrollThumbButtonRelease()
	{
		if (isScrollThumbButtonDown)
		{
			tk2dUIManager.Instance.OnInputUpdate -= MoveScrollThumbButton;
		}
		isScrollThumbButtonDown = false;
		if (hoverUpButton != null)
		{
			hoverUpButton.IsOver = false;
		}
		if (hoverDownButton != null)
		{
			hoverDownButton.IsOver = false;
		}
	}

	private void ScrollUpButtonDown()
	{
		timeOfUpDownButtonPressStart = Time.realtimeSinceStartup;
		repeatUpDownButtonHoldCounter = 0f;
		if (scrollUpDownButtonState == 0)
		{
			tk2dUIManager.Instance.OnInputUpdate += CheckRepeatScrollUpDownButton;
		}
		scrollUpDownButtonState = -1;
		ScrollUpFixed();
	}

	private void ScrollUpButtonUp()
	{
		if (scrollUpDownButtonState != 0)
		{
			tk2dUIManager.Instance.OnInputUpdate -= CheckRepeatScrollUpDownButton;
		}
		scrollUpDownButtonState = 0;
	}

	private void ScrollDownButtonDown()
	{
		timeOfUpDownButtonPressStart = Time.realtimeSinceStartup;
		repeatUpDownButtonHoldCounter = 0f;
		if (scrollUpDownButtonState == 0)
		{
			tk2dUIManager.Instance.OnInputUpdate += CheckRepeatScrollUpDownButton;
		}
		scrollUpDownButtonState = 1;
		ScrollDownFixed();
	}

	private void ScrollDownButtonUp()
	{
		if (scrollUpDownButtonState != 0)
		{
			tk2dUIManager.Instance.OnInputUpdate -= CheckRepeatScrollUpDownButton;
		}
		scrollUpDownButtonState = 0;
	}

	public void ScrollUpFixed()
	{
		ScrollDirection(-1);
	}

	public void ScrollDownFixed()
	{
		ScrollDirection(1);
	}

	private void CheckRepeatScrollUpDownButton()
	{
		if (scrollUpDownButtonState == 0)
		{
			return;
		}
		float num = Time.realtimeSinceStartup - timeOfUpDownButtonPressStart;
		if (repeatUpDownButtonHoldCounter == 0f)
		{
			if (num > 0.55f)
			{
				repeatUpDownButtonHoldCounter++;
				num -= 0.55f;
				ScrollDirection(scrollUpDownButtonState);
			}
		}
		else if (num > 0.45f)
		{
			repeatUpDownButtonHoldCounter++;
			num -= 0.45f;
			ScrollDirection(scrollUpDownButtonState);
		}
	}

	public void ScrollDirection(int dir)
	{
		if (scrollAxes == Axes.XAxis)
		{
			Value -= CalcScrollPercentOffsetButtonScrollDistance() * (float)dir * buttonUpDownScrollDistance;
		}
		else
		{
			Value += CalcScrollPercentOffsetButtonScrollDistance() * (float)dir * buttonUpDownScrollDistance;
		}
	}

	private float CalcScrollPercentOffsetButtonScrollDistance()
	{
		return 0.1f;
	}

	private void LayoutReshaped(Vector3 dMin, Vector3 dMax)
	{
		scrollBarLength += ((scrollAxes == Axes.XAxis) ? (dMax.x - dMin.x) : (dMax.y - dMin.y));
	}
}
