	public static tk2dUIAudioManager Instance
	{
		get
		{
			if (instance == null)
			{
				instance = UnityEngine.Object.FindObjectOfType(typeof(tk2dUIAudioManager)) as tk2dUIAudioManager;
				if (instance == null)
				{
					instance = new GameObject("tk2dUIAudioManager").AddComponent<tk2dUIAudioManager>();
				}
			}
			return instance;
		}
	}

	private void Awake()
	{
		if (instance == null)
		{
			instance = this;
		}
		else if (instance != this)
		{
			UnityEngine.Object.Destroy(this);
			return;
		}
		Setup();
	}

	private void Setup()
	{
		if (audioSrc == null)
		{
			audioSrc = base.gameObject.GetComponent<AudioSource>();
		}
		if (audioSrc == null)
		{
			audioSrc = base.gameObject.AddComponent<AudioSource>();
			audioSrc.playOnAwake = false;
		}
	}

	public void Play(AudioClip clip)
	{
		audioSrc.PlayOneShot(clip, AudioListener.volume);
	}
}
[AddComponentMenu("2D Toolkit/UI/Core/tk2dUICamera")]
public class tk2dUICamera : MonoBehaviour
{
	public enum tk2dRaycastType
	{
		Physics3D,
		Physics2D
	}

	[SerializeField]
	private LayerMask raycastLayerMask = -1;

	[SerializeField]
	private tk2dRaycastType raycastType;

	public tk2dRaycastType RaycastType => raycastType;

	public LayerMask FilteredMask => (int)raycastLayerMask & GetComponent<Camera>().cullingMask;

	public Camera HostCamera => GetComponent<Camera>();

	public void AssignRaycastLayerMask(LayerMask mask)
	{
		raycastLayerMask = mask;
	}

	private void OnEnable()
	{
		if (GetComponent<Camera>() == null)
		{
			UnityEngine.Debug.LogError("tk2dUICamera should only be attached to a camera.");
			base.enabled = false;
		}
		else if (!GetComponent<Camera>().orthographic && raycastType == tk2dRaycastType.Physics2D)
		{
			UnityEngine.Debug.LogError("tk2dUICamera - Physics2D raycast only works with orthographic cameras.");
			base.enabled = false;
		}
		else
		{
			tk2dUIManager.RegisterCamera(this);
		}
	}

	private void OnDisable()
	{
		tk2dUIManager.UnregisterCamera(this);
	}
}
[AddComponentMenu("2D Toolkit/UI/Core/tk2dUIItem")]
public class tk2dUIItem : MonoBehaviour
{
	public GameObject sendMessageTarget;

	public string SendMessageOnDownMethodName = "";

	public string SendMessageOnUpMethodName = "";

	public string SendMessageOnClickMethodName = "";

	public string SendMessageOnReleaseMethodName = "";

	[SerializeField]
	private bool isChildOfAnotherUIItem;

	public bool registerPressFromChildren;

	public bool isHoverEnabled;

	public Transform[] editorExtraBounds = new Transform[0];

	public Transform[] editorIgnoreBounds = new Transform[0];

	private bool isPressed;

	private bool isHoverOver;

	private tk2dUITouch touch;

	private tk2dUIItem parentUIItem;

	public bool IsPressed => isPressed;

	public tk2dUITouch Touch => touch;

	public tk2dUIItem ParentUIItem => parentUIItem;

	public event Action OnDown;

	public event Action OnUp;

	public event Action OnClick;

	public event Action OnRelease;

	public event Action OnHoverOver;

	public event Action OnHoverOut;

	public event Action<tk2dUIItem> OnDownUIItem;

	public event Action<tk2dUIItem> OnUpUIItem;

	public event Action<tk2dUIItem> OnClickUIItem;

	public event Action<tk2dUIItem> OnReleaseUIItem;

	public event Action<tk2dUIItem> OnHoverOverUIItem;

	public event Action<tk2dUIItem> OnHoverOutUIItem;

	private void Awake()
	{
		if (isChildOfAnotherUIItem)
		{
			UpdateParent();
		}
	}

	private void Start()
	{
		if (tk2dUIManager.Instance == null)
		{
			UnityEngine.Debug.LogError("Unable to find tk2dUIManager. Please create a tk2dUIManager in the scene before proceeding.");
		}
		if (isChildOfAnotherUIItem && parentUIItem == null)
		{
			UpdateParent();
		}
	}

	public void UpdateParent()
	{
		parentUIItem = GetParentUIItem();
	}

	public void ManuallySetParent(tk2dUIItem newParentUIItem)
	{
		parentUIItem = newParentUIItem;
	}

	public void RemoveParent()
	{
		parentUIItem = null;
	}

	public bool Press(tk2dUITouch touch)
	{
		return Press(touch, null);
	}

	public bool Press(tk2dUITouch touch, tk2dUIItem sentFromChild)
	{
		if (isPressed)
		{
			return false;
		}
		if (!isPressed)
		{
			this.touch = touch;
			if ((registerPressFromChildren || sentFromChild == null) && base.enabled)
			{
				isPressed = true;
				if (OnDown != null)
				{
					OnDown();
				}
				if (OnDownUIItem != null)
				{
					OnDownUIItem(this);
				}
				DoSendMessage(SendMessageOnDownMethodName);
			}
			if (parentUIItem != null)
			{
				parentUIItem.Press(touch, this);
			}
		}
		return true;
	}

	public void UpdateTouch(tk2dUITouch touch)
	{
		this.touch = touch;
		if (parentUIItem != null)
		{
			parentUIItem.UpdateTouch(touch);
		}
	}

	private void DoSendMessage(string methodName)
	{
		if (sendMessageTarget != null && methodName.Length > 0)
		{
			sendMessageTarget.SendMessage(methodName, this, SendMessageOptions.RequireReceiver);
		}
	}

	public void Release()
	{
		if (isPressed)
		{
			isPressed = false;
			if (OnUp != null)
			{
				OnUp();
			}
			if (OnUpUIItem != null)
			{
				OnUpUIItem(this);
			}
			DoSendMessage(SendMessageOnUpMethodName);
			if (OnClick != null)
			{
				OnClick();
			}
			if (OnClickUIItem != null)
			{
				OnClickUIItem(this);
			}
			DoSendMessage(SendMessageOnClickMethodName);
		}
		if (OnRelease != null)
		{
			OnRelease();
		}
		if (OnReleaseUIItem != null)
		{
			OnReleaseUIItem(this);
		}
		DoSendMessage(SendMessageOnReleaseMethodName);
		if (parentUIItem != null)
		{
			parentUIItem.Release();
		}
	}

	public void CurrentOverUIItem(tk2dUIItem overUIItem)
	{
		if (!(overUIItem != this))
		{
			return;
		}
		if (isPressed)
		{
			if (!CheckIsUIItemChildOfMe(overUIItem))
			{
				Exit();
				if (parentUIItem != null)
				{
					parentUIItem.CurrentOverUIItem(overUIItem);
				}
			}
		}
		else if (parentUIItem != null)
		{
			parentUIItem.CurrentOverUIItem(overUIItem);
		}
	}

	public bool CheckIsUIItemChildOfMe(tk2dUIItem uiItem)
	{
		tk2dUIItem tk2dUIItem2 = null;
		bool result = false;
		if (uiItem != null)
		{
			tk2dUIItem2 = uiItem.parentUIItem;
		}
		while (tk2dUIItem2 != null)
		{
			if (tk2dUIItem2 == this)
			{
				result = true;
				break;
			}
			tk2dUIItem2 = tk2dUIItem2.parentUIItem;
		}
		return result;
	}

	public void Exit()
	{
		if (isPressed)
		{
			isPressed = false;
			if (OnUp != null)
			{
				OnUp();
			}
			if (OnUpUIItem != null)
			{
				OnUpUIItem(this);
			}
			DoSendMessage(SendMessageOnUpMethodName);
		}
	}

	public bool HoverOver(tk2dUIItem prevHover)
	{
		bool flag = false;
		tk2dUIItem tk2dUIItem2 = null;
		if (!isHoverOver)
		{
			if (OnHoverOver != null)
			{
				OnHoverOver();
			}
			if (OnHoverOverUIItem != null)
			{
				OnHoverOverUIItem(this);
			}
			isHoverOver = true;
		}
		if (prevHover == this)
		{
			flag = true;
		}
		if (parentUIItem != null && parentUIItem.isHoverEnabled)
		{
			tk2dUIItem2 = parentUIItem;
		}
		if (tk2dUIItem2 == null)
		{
			return flag;
		}
		return tk2dUIItem2.HoverOver(prevHover) | flag;
	}

	public void HoverOut(tk2dUIItem currHoverButton)
	{
		if (isHoverOver)
		{
			if (OnHoverOut != null)
			{
				OnHoverOut();
			}
			if (OnHoverOutUIItem != null)
			{
				OnHoverOutUIItem(this);
			}
			isHoverOver = false;
		}
		if (parentUIItem != null && parentUIItem.isHoverEnabled)
		{
			if (currHoverButton == null)
			{
				parentUIItem.HoverOut(currHoverButton);
			}
			else if (!parentUIItem.CheckIsUIItemChildOfMe(currHoverButton) && currHoverButton != parentUIItem)
			{
				parentUIItem.HoverOut(currHoverButton);
			}
		}
	}

	private tk2dUIItem GetParentUIItem()
	{
		Transform parent = base.transform.parent;
		while (parent != null)
		{
			tk2dUIItem component = parent.GetComponent<tk2dUIItem>();
			if (component != null)
			{
				return component;
			}
			parent = parent.parent;
		}
		return null;
	}

	public void SimulateClick()
	{
		if (OnDown != null)
		{
			OnDown();
		}
		if (OnDownUIItem != null)
		{
			OnDownUIItem(this);
		}
		DoSendMessage(SendMessageOnDownMethodName);
		if (OnUp != null)
		{
			OnUp();
		}
		if (OnUpUIItem != null)
		{
			OnUpUIItem(this);
		}
		DoSendMessage(SendMessageOnUpMethodName);
		if (OnClick != null)
		{
			OnClick();
		}
		if (OnClickUIItem != null)
		{
			OnClickUIItem(this);
		}
		DoSendMessage(SendMessageOnClickMethodName);
		if (OnRelease != null)
		{
			OnRelease();
		}
		if (OnReleaseUIItem != null)
		{
			OnReleaseUIItem(this);
		}
		DoSendMessage(SendMessageOnReleaseMethodName);
	}

	public void InternalSetIsChildOfAnotherUIItem(bool state)
	{
		isChildOfAnotherUIItem = state;
	}

	public bool InternalGetIsChildOfAnotherUIItem()
	{
		return isChildOfAnotherUIItem;
	}
}
