[AddComponentMenu("2D Toolkit/UI/Core/tk2dUILayout")]
public class tk2dUILayout : MonoBehaviour
{
	public Vector3 bMin = new Vector3(0f, -1f, 0f);

	public Vector3 bMax = new Vector3(1f, 0f, 0f);

	public List<tk2dUILayoutItem> layoutItems = new List<tk2dUILayoutItem>();

	public bool autoResizeCollider;

	public int ItemCount => layoutItems.Count;

	public event Action<Vector3, Vector3> OnReshape;

	private void Reset()
	{
		if (!(GetComponent<Collider>() != null))
		{
			return;
		}
		BoxCollider boxCollider = GetComponent<Collider>() as BoxCollider;
		if (boxCollider != null)
		{
			UnityEngine.Bounds bounds = boxCollider.bounds;
			Matrix4x4 worldToLocalMatrix = base.transform.worldToLocalMatrix;
			Vector3 position = base.transform.position;
			Reshape(worldToLocalMatrix.MultiplyPoint(bounds.min) - bMin, worldToLocalMatrix.MultiplyPoint(bounds.max) - bMax, updateChildren: true);
			Vector3 vector = worldToLocalMatrix.MultiplyVector(base.transform.position - position);
			Transform transform = base.transform;
			for (int i = 0; i < transform.childCount; i++)
			{
				Transform child = transform.GetChild(i);
				Vector3 localPosition = child.localPosition - vector;
				child.localPosition = localPosition;
			}
			boxCollider.center -= vector;
			autoResizeCollider = true;
		}
	}

	public virtual void Reshape(Vector3 dMin, Vector3 dMax, bool updateChildren)
	{
		foreach (tk2dUILayoutItem layoutItem in layoutItems)
		{
			layoutItem.oldPos = layoutItem.gameObj.transform.position;
		}
		bMin += dMin;
		bMax += dMax;
		Vector3 vector = new Vector3(bMin.x, bMax.y);
		base.transform.position += base.transform.localToWorldMatrix.MultiplyVector(vector);
		bMin -= vector;
		bMax -= vector;
		if (autoResizeCollider)
		{
			BoxCollider component = GetComponent<BoxCollider>();
			if (component != null)
			{
				component.center += (dMin + dMax) / 2f - vector;
				component.size += dMax - dMin;
			}
		}
		foreach (tk2dUILayoutItem layoutItem2 in layoutItems)
		{
			Vector3 vector2 = base.transform.worldToLocalMatrix.MultiplyVector(layoutItem2.gameObj.transform.position - layoutItem2.oldPos);
			Vector3 vector3 = -vector2;
			Vector3 vector4 = -vector2;
			if (updateChildren)
			{
				vector3.x += (layoutItem2.snapLeft ? dMin.x : (layoutItem2.snapRight ? dMax.x : 0f));
				vector3.y += (layoutItem2.snapBottom ? dMin.y : (layoutItem2.snapTop ? dMax.y : 0f));
				vector4.x += (layoutItem2.snapRight ? dMax.x : (layoutItem2.snapLeft ? dMin.x : 0f));
				vector4.y += (layoutItem2.snapTop ? dMax.y : (layoutItem2.snapBottom ? dMin.y : 0f));
			}
			if (layoutItem2.sprite != null || layoutItem2.UIMask != null || layoutItem2.layout != null)
			{
				Matrix4x4 matrix4x = base.transform.localToWorldMatrix * layoutItem2.gameObj.transform.worldToLocalMatrix;
				vector3 = matrix4x.MultiplyVector(vector3);
				vector4 = matrix4x.MultiplyVector(vector4);
			}
			if (layoutItem2.sprite != null)
			{
				layoutItem2.sprite.ReshapeBounds(vector3, vector4);
				continue;
			}
			if (layoutItem2.UIMask != null)
			{
				layoutItem2.UIMask.ReshapeBounds(vector3, vector4);
				continue;
			}
			if (layoutItem2.layout != null)
			{
				layoutItem2.layout.Reshape(vector3, vector4, updateChildren: true);
				continue;
			}
			Vector3 vector5 = vector3;
			if (layoutItem2.snapLeft && layoutItem2.snapRight)
			{
				vector5.x = 0.5f * (vector3.x + vector4.x);
			}
			if (layoutItem2.snapTop && layoutItem2.snapBottom)
			{
				vector5.y = 0.5f * (vector3.y + vector4.y);
			}
			layoutItem2.gameObj.transform.position += vector5;
		}
		if (OnReshape != null)
		{
			OnReshape(dMin, dMax);
		}
	}

	public void SetBounds(Vector3 pMin, Vector3 pMax)
	{
		Matrix4x4 worldToLocalMatrix = base.transform.worldToLocalMatrix;
		Reshape(worldToLocalMatrix.MultiplyPoint(pMin) - bMin, worldToLocalMatrix.MultiplyPoint(pMax) - bMax, updateChildren: true);
	}

	public Vector3 GetMinBounds()
	{
		return base.transform.localToWorldMatrix.MultiplyPoint(bMin);
	}

	public Vector3 GetMaxBounds()
	{
		return base.transform.localToWorldMatrix.MultiplyPoint(bMax);
	}

	public void Refresh()
	{
		Reshape(Vector3.zero, Vector3.zero, updateChildren: true);
	}
}
public abstract class tk2dUILayoutContainer : tk2dUILayout
{
	protected Vector2 innerSize = Vector2.zero;

	public event Action OnChangeContent;

	public Vector2 GetInnerSize()
	{
		return innerSize;
	}

	protected abstract void DoChildLayout();

	public override void Reshape(Vector3 dMin, Vector3 dMax, bool updateChildren)
	{
		bMin += dMin;
		bMax += dMax;
		Vector3 vector = new Vector3(bMin.x, bMax.y);
		base.transform.position += vector;
		bMin -= vector;
		bMax -= vector;
		DoChildLayout();
		if (OnChangeContent != null)
		{
			OnChangeContent();
		}
	}

	public void AddLayout(tk2dUILayout layout, tk2dUILayoutItem item)
	{
		item.gameObj = layout.gameObject;
		item.layout = layout;
		layoutItems.Add(item);
		layout.gameObject.transform.parent = base.transform;
		Refresh();
	}

	public void AddLayoutAtIndex(tk2dUILayout layout, tk2dUILayoutItem item, int index)
	{
		item.gameObj = layout.gameObject;
		item.layout = layout;
		layoutItems.Insert(index, item);
		layout.gameObject.transform.parent = base.transform;
		Refresh();
	}

	public void RemoveLayout(tk2dUILayout layout)
	{
		foreach (tk2dUILayoutItem layoutItem in layoutItems)
		{
			if (layoutItem.layout == layout)
			{
				layoutItems.Remove(layoutItem);
				layout.gameObject.transform.parent = null;
				break;
			}
		}
		Refresh();
	}
}
[AddComponentMenu("2D Toolkit/UI/Core/tk2dUILayoutContainerSizer")]
public class tk2dUILayoutContainerSizer : tk2dUILayoutContainer
{
	public bool horizontal;

	public bool expand = true;

	public Vector2 margin = Vector2.zero;

	public float spacing;

	protected override void DoChildLayout()
	{
		int count = layoutItems.Count;
		if (count == 0)
		{
			return;
		}
		float num = bMax.x - bMin.x - 2f * margin.x;
		float num2 = bMax.y - bMin.y - 2f * margin.y;
		float num3 = (horizontal ? num : num2) - spacing * (float)(count - 1);
		float num4 = 1f;
		float num5 = num3;
		float num6 = 0f;
		float[] array = new float[count];
		for (int i = 0; i < count; i++)
		{
			tk2dUILayoutItem tk2dUILayoutItem2 = layoutItems[i];
			if (tk2dUILayoutItem2.fixedSize)
			{
				array[i] = (horizontal ? (tk2dUILayoutItem2.layout.bMax.x - tk2dUILayoutItem2.layout.bMin.x) : (tk2dUILayoutItem2.layout.bMax.y - tk2dUILayoutItem2.layout.bMin.y));
				num5 -= array[i];
			}
			else if (tk2dUILayoutItem2.fillPercentage > 0f)
			{
				float num7 = num4 * tk2dUILayoutItem2.fillPercentage / 100f;
				array[i] = num3 * num7;
				num5 -= array[i];
				num4 -= num7;
			}
			else
			{
				num6 += tk2dUILayoutItem2.sizeProportion;
			}
		}
		for (int j = 0; j < count; j++)
		{
			tk2dUILayoutItem tk2dUILayoutItem3 = layoutItems[j];
			if (!tk2dUILayoutItem3.fixedSize && tk2dUILayoutItem3.fillPercentage <= 0f)
			{
				array[j] = num5 * tk2dUILayoutItem3.sizeProportion / num6;
			}
		}
		Vector3 zero = Vector3.zero;
		Vector3 zero2 = Vector3.zero;
		float num8 = 0f;
		Matrix4x4 localToWorldMatrix = base.transform.localToWorldMatrix;
		if (horizontal)
		{
			innerSize = new Vector2(2f * margin.x + spacing * (float)(count - 1), bMax.y - bMin.y);
		}
		else
		{
			innerSize = new Vector2(bMax.x - bMin.x, 2f * margin.y + spacing * (float)(count - 1));
		}
		for (int k = 0; k < count; k++)
		{
			tk2dUILayoutItem tk2dUILayoutItem4 = layoutItems[k];
			Matrix4x4 matrix4x = tk2dUILayoutItem4.gameObj.transform.localToWorldMatrix * base.transform.worldToLocalMatrix;
			if (horizontal)
			{
				if (expand)
				{
					zero.y = bMin.y + margin.y;
					zero2.y = bMax.y - margin.y;
				}
				else
				{
					zero.y = matrix4x.MultiplyPoint(tk2dUILayoutItem4.layout.bMin).y;
					zero2.y = matrix4x.MultiplyPoint(tk2dUILayoutItem4.layout.bMax).y;
				}
				zero.x = bMin.x + margin.x + num8;
				zero2.x = zero.x + array[k];
			}
			else
			{
				if (expand)
				{
					zero.x = bMin.x + margin.x;
					zero2.x = bMax.x - margin.x;
				}
				else
				{
					zero.x = matrix4x.MultiplyPoint(tk2dUILayoutItem4.layout.bMin).x;
					zero2.x = matrix4x.MultiplyPoint(tk2dUILayoutItem4.layout.bMax).x;
				}
				zero2.y = bMax.y - margin.y - num8;
				zero.y = zero2.y - array[k];
			}
			tk2dUILayoutItem4.layout.SetBounds(localToWorldMatrix.MultiplyPoint(zero), localToWorldMatrix.MultiplyPoint(zero2));
			num8 += array[k] + spacing;
			if (horizontal)
			{
				innerSize.x += array[k];
			}
			else
			{
				innerSize.y += array[k];
			}
		}
	}
}
[AddComponentMenu("2D Toolkit/UI/Core/tk2dUIManager")]
public class tk2dUIManager : MonoBehaviour
{
	public static double version = 1.0;

	public static int releaseId = 0;

	private static tk2dUIManager instance;

	[SerializeField]
	private Camera uiCamera;

	private static List<tk2dUICamera> allCameras = new List<tk2dUICamera>();

	private List<tk2dUICamera> sortedCameras = new List<tk2dUICamera>();

	public LayerMask raycastLayerMask = -1;

	private bool inputEnabled = true;

	public bool areHoverEventsTracked = true;

	private tk2dUIItem pressedUIItem;

	private tk2dUIItem overUIItem;

	private tk2dUITouch firstPressedUIItemTouch;

	private bool checkForHovers = true;

	[SerializeField]
	private bool useMultiTouch;

	private const int MAX_MULTI_TOUCH_COUNT = 5;

	private tk2dUITouch[] allTouches = new tk2dUITouch[5];

	private List<tk2dUIItem> prevPressedUIItemList = new List<tk2dUIItem>();

	private tk2dUIItem[] pressedUIItems = new tk2dUIItem[5];

	private int touchCounter;

	private Vector2 mouseDownFirstPos = Vector2.zero;

	private const string MOUSE_WHEEL_AXES_NAME = "Mouse ScrollWheel";

	private tk2dUITouch primaryTouch;

	private tk2dUITouch secondaryTouch;

	private tk2dUITouch resultTouch;

	private tk2dUIItem hitUIItem;

	private RaycastHit hit;

	private Ray ray;

	private tk2dUITouch currTouch;

	private tk2dUIItem currPressedItem;

	private tk2dUIItem prevPressedItem;

	public static tk2dUIManager Instance
	{
		get
		{
			if (instance == null)
			{
				instance = UnityEngine.Object.FindObjectOfType(typeof(tk2dUIManager)) as tk2dUIManager;
				if (instance == null)
				{
					instance = new GameObject("tk2dUIManager").AddComponent<tk2dUIManager>();
				}
			}
			return instance;
		}
	}

	public static tk2dUIManager Instance__NoCreate => instance;

	public Camera UICamera
	{
		get
		{
			return uiCamera;
		}
		set
		{
			uiCamera = value;
		}
	}

	public bool InputEnabled
	{
		get
		{
			return inputEnabled;
		}
		set
		{
			if (inputEnabled && !value)
			{
				SortCameras();
				inputEnabled = value;
				if (useMultiTouch)
				{
					CheckMultiTouchInputs();
				}
				else
				{
					CheckInputs();
				}
			}
			else
			{
				inputEnabled = value;
			}
		}
	}

	public tk2dUIItem PressedUIItem
	{
		get
		{
			if (useMultiTouch)
			{
				if (pressedUIItems.Length != 0)
				{
					return pressedUIItems[pressedUIItems.Length - 1];
				}
				return null;
			}
			return pressedUIItem;
		}
	}

	public tk2dUIItem[] PressedUIItems => pressedUIItems;

	public bool UseMultiTouch
	{
		get
		{
			return useMultiTouch;
		}
		set
		{
			if (useMultiTouch != value && inputEnabled)
			{
				InputEnabled = false;
				useMultiTouch = value;
				InputEnabled = true;
			}
			else
			{
				useMultiTouch = value;
			}
		}
	}

	public event Action OnAnyPress;

	public event Action OnInputUpdate;

	public event Action<float> OnScrollWheelChange;

	public Camera GetUICameraForControl(GameObject go)
	{
		int num = 1 << go.layer;
		int count = allCameras.Count;
		for (int i = 0; i < count; i++)
		{
			tk2dUICamera tk2dUICamera2 = allCameras[i];
			if (((int)tk2dUICamera2.FilteredMask & num) != 0)
			{
				return tk2dUICamera2.HostCamera;
			}
		}
		UnityEngine.Debug.LogError("Unable to find UI camera for " + go.name);
		return null;
	}

	public static void RegisterCamera(tk2dUICamera cam)
	{
		allCameras.Add(cam);
	}

	public static void UnregisterCamera(tk2dUICamera cam)
	{
		allCameras.Remove(cam);
	}

	private void SortCameras()
	{
		sortedCameras.Clear();
		int count = allCameras.Count;
		for (int i = 0; i < count; i++)
		{
			tk2dUICamera tk2dUICamera2 = allCameras[i];
			if (tk2dUICamera2 != null)
			{
				sortedCameras.Add(tk2dUICamera2);
			}
		}
		sortedCameras.Sort((tk2dUICamera a, tk2dUICamera b) => b.GetComponent<Camera>().depth.CompareTo(a.GetComponent<Camera>().depth));
	}

	private void Awake()
	{
		if (instance == null)
		{
			instance = this;
			if (instance.transform.childCount != 0)
			{
				UnityEngine.Debug.LogError("You should not attach anything to the tk2dUIManager object. The tk2dUIManager will not get destroyed between scene switches and any children will persist as well.");
			}
			if (Application.isPlaying)
			{
				UnityEngine.Object.DontDestroyOnLoad(base.gameObject);
			}
		}
		else if (instance != this)
		{
			UnityEngine.Debug.Log("Discarding unnecessary tk2dUIManager instance.");
			if (uiCamera != null)
			{
				HookUpLegacyCamera(uiCamera);
				uiCamera = null;
			}
			UnityEngine.Object.Destroy(this);
			return;
		}
		tk2dUITime.Init();
		Setup();
	}

	private void HookUpLegacyCamera(Camera cam)
	{
		if (cam.GetComponent<tk2dUICamera>() == null)
		{
			cam.gameObject.AddComponent<tk2dUICamera>().AssignRaycastLayerMask(raycastLayerMask);
		}
	}

	private void Start()
	{
		if (uiCamera != null)
		{
			UnityEngine.Debug.Log("It is no longer necessary to hook up a camera to the tk2dUIManager. You can simply attach a tk2dUICamera script to the cameras that interact with UI.");
			HookUpLegacyCamera(uiCamera);
			uiCamera = null;
		}
		if (allCameras.Count == 0)
		{
			UnityEngine.Debug.LogError("Unable to find any tk2dUICameras, and no cameras are connected to the tk2dUIManager. You will not be able to interact with the UI.");
		}
	}

	private void Setup()
	{
		if (!areHoverEventsTracked)
		{
			checkForHovers = false;
		}
	}

	private void Update()
	{
		tk2dUITime.Update();
		if (!inputEnabled)
		{
			return;
		}
		SortCameras();
		if (useMultiTouch)
		{
			CheckMultiTouchInputs();
		}
		else
		{
			CheckInputs();
		}
		if (OnInputUpdate != null)
		{
			OnInputUpdate();
		}
		if (OnScrollWheelChange != null)
		{
			float axis = Input.GetAxis("Mouse ScrollWheel");
			if (axis != 0f)
			{
				OnScrollWheelChange(axis);
			}
		}
	}

	private void CheckInputs()
	{
		bool flag = false;
		bool flag2 = false;
		bool flag3 = false;
		primaryTouch = default(tk2dUITouch);
		secondaryTouch = default(tk2dUITouch);
		resultTouch = default(tk2dUITouch);
		hitUIItem = null;
		if (inputEnabled)
		{
			int touchCount = Input.touchCount;
			if (Input.touchCount > 0)
			{
				for (int i = 0; i < touchCount; i++)
				{
					UnityEngine.Touch touch = Input.GetTouch(i);
					if (touch.phase == TouchPhase.Began)
					{
						primaryTouch = new tk2dUITouch(touch);
						flag = true;
						flag3 = true;
					}
					else if (pressedUIItem != null && touch.fingerId == firstPressedUIItemTouch.fingerId)
					{
						secondaryTouch = new tk2dUITouch(touch);
						flag2 = true;
					}
				}
				checkForHovers = false;
			}
			else if (Input.GetMouseButtonDown(0))
			{
				primaryTouch = new tk2dUITouch(TouchPhase.Began, 9999, Input.mousePosition, Vector2.zero, 0f);
				flag = true;
				flag3 = true;
			}
			else if (Input.GetMouseButton(0) || Input.GetMouseButtonUp(0))
			{
				Vector2 vector = Vector2.zero;
				TouchPhase phase = TouchPhase.Moved;
				if (pressedUIItem != null)
				{
					vector = firstPressedUIItemTouch.position - new Vector2(Input.mousePosition.x, Input.mousePosition.y);
				}
				if (Input.GetMouseButtonUp(0))
				{
					phase = TouchPhase.Ended;
				}
				else if (vector == Vector2.zero)
				{
					phase = TouchPhase.Stationary;
				}
				secondaryTouch = new tk2dUITouch(phase, 9999, Input.mousePosition, vector, tk2dUITime.deltaTime);
				flag2 = true;
			}
		}
		if (flag)
		{
			resultTouch = primaryTouch;
		}
		else if (flag2)
		{
			resultTouch = secondaryTouch;
		}
		if (flag | flag2)
		{
			hitUIItem = RaycastForUIItem(resultTouch.position);
			if (resultTouch.phase == TouchPhase.Began)
			{
				if (pressedUIItem != null)
				{
					pressedUIItem.CurrentOverUIItem(hitUIItem);
					if (pressedUIItem != hitUIItem)
					{
						pressedUIItem.Release();
						pressedUIItem = null;
					}
					else
					{
						firstPressedUIItemTouch = resultTouch;
					}
				}
				if (hitUIItem != null)
				{
					hitUIItem.Press(resultTouch);
				}
				pressedUIItem = hitUIItem;
				firstPressedUIItemTouch = resultTouch;
			}
			else if (resultTouch.phase == TouchPhase.Ended)
			{
				if (pressedUIItem != null)
				{
					pressedUIItem.CurrentOverUIItem(hitUIItem);
					pressedUIItem.UpdateTouch(resultTouch);
					pressedUIItem.Release();
					pressedUIItem = null;
				}
			}
			else if (pressedUIItem != null)
			{
				pressedUIItem.CurrentOverUIItem(hitUIItem);
				pressedUIItem.UpdateTouch(resultTouch);
			}
		}
		else if (pressedUIItem != null)
		{
			pressedUIItem.CurrentOverUIItem(null);
			pressedUIItem.Release();
			pressedUIItem = null;
		}
		if (checkForHovers)
		{
			if (inputEnabled)
			{
				if (!flag && !flag2 && hitUIItem == null && !Input.GetMouseButton(0))
				{
					hitUIItem = RaycastForUIItem(Input.mousePosition);
				}
				else if (Input.GetMouseButton(0))
				{
					hitUIItem = null;
				}
			}
			if (hitUIItem != null)
			{
				if (hitUIItem.isHoverEnabled)
				{
					if (!hitUIItem.HoverOver(overUIItem) && overUIItem != null)
					{
						overUIItem.HoverOut(hitUIItem);
					}
					overUIItem = hitUIItem;
				}
				else if (overUIItem != null)
				{
					overUIItem.HoverOut(null);
				}
			}
			else if (overUIItem != null)
			{
				overUIItem.HoverOut(null);
			}
		}
		if (flag3 && OnAnyPress != null)
		{
			OnAnyPress();
		}
	}

	private void CheckMultiTouchInputs()
	{
		bool flag = false;
		int num = -1;
		bool flag2 = false;
		touchCounter = 0;
		if (inputEnabled)
		{
			if (Input.touchCount > 0)
			{
				UnityEngine.Touch[] touches = Input.touches;
				foreach (UnityEngine.Touch touch in touches)
				{
					if (touchCounter >= 5)
					{
						break;
					}
					allTouches[touchCounter] = new tk2dUITouch(touch);
					touchCounter++;
				}
			}
			else if (Input.GetMouseButtonDown(0))
			{
				allTouches[touchCounter] = new tk2dUITouch(TouchPhase.Began, 9999, Input.mousePosition, Vector2.zero, 0f);
				mouseDownFirstPos = Input.mousePosition;
				touchCounter++;
			}
			else if (Input.GetMouseButton(0) || Input.GetMouseButtonUp(0))
			{
				Vector2 vector = mouseDownFirstPos - new Vector2(Input.mousePosition.x, Input.mousePosition.y);
				TouchPhase phase = TouchPhase.Moved;
				if (Input.GetMouseButtonUp(0))
				{
					phase = TouchPhase.Ended;
				}
				else if (vector == Vector2.zero)
				{
					phase = TouchPhase.Stationary;
				}
				allTouches[touchCounter] = new tk2dUITouch(phase, 9999, Input.mousePosition, vector, tk2dUITime.deltaTime);
				touchCounter++;
			}
		}
		for (int j = 0; j < touchCounter; j++)
		{
			pressedUIItems[j] = RaycastForUIItem(allTouches[j].position);
		}
		for (int k = 0; k < prevPressedUIItemList.Count; k++)
		{
			prevPressedItem = prevPressedUIItemList[k];
			if (!(prevPressedItem != null))
			{
				continue;
			}
			num = prevPressedItem.Touch.fingerId;
			flag2 = false;
			for (int l = 0; l < touchCounter; l++)
			{
				currTouch = allTouches[l];
				if (currTouch.fingerId != num)
				{
					continue;
				}
				flag2 = true;
				currPressedItem = pressedUIItems[l];
				if (currTouch.phase == TouchPhase.Began)
				{
					prevPressedItem.CurrentOverUIItem(currPressedItem);
					if (prevPressedItem != currPressedItem)
					{
						prevPressedItem.Release();
						prevPressedUIItemList.RemoveAt(k);
						k--;
					}
				}
				else if (currTouch.phase == TouchPhase.Ended)
				{
					prevPressedItem.CurrentOverUIItem(currPressedItem);
					prevPressedItem.UpdateTouch(currTouch);
					prevPressedItem.Release();
					prevPressedUIItemList.RemoveAt(k);
					k--;
				}
				else
				{
					prevPressedItem.CurrentOverUIItem(currPressedItem);
					prevPressedItem.UpdateTouch(currTouch);
				}
				break;
			}
			if (!flag2)
			{
				prevPressedItem.CurrentOverUIItem(null);
				prevPressedItem.Release();
				prevPressedUIItemList.RemoveAt(k);
				k--;
			}
		}
		for (int m = 0; m < touchCounter; m++)
		{
			currPressedItem = pressedUIItems[m];
			currTouch = allTouches[m];
			if (currTouch.phase == TouchPhase.Began)
			{
				if (currPressedItem != null && currPressedItem.Press(currTouch))
				{
					prevPressedUIItemList.Add(currPressedItem);
				}
				flag = true;
			}
		}
		if (flag && OnAnyPress != null)
		{
			OnAnyPress();
		}
	}

	private tk2dUIItem RaycastForUIItem(Vector2 screenPos)
	{
		int count = sortedCameras.Count;
		for (int i = 0; i < count; i++)
		{
			tk2dUICamera tk2dUICamera2 = sortedCameras[i];
			if (tk2dUICamera2.RaycastType == tk2dUICamera.tk2dRaycastType.Physics3D)
			{
				ray = tk2dUICamera2.HostCamera.ScreenPointToRay(screenPos);
				if (Physics.Raycast(ray, out hit, tk2dUICamera2.HostCamera.farClipPlane - tk2dUICamera2.HostCamera.nearClipPlane, tk2dUICamera2.FilteredMask))
				{
					return hit.collider.GetComponent<tk2dUIItem>();
				}
			}
			else if (tk2dUICamera2.RaycastType == tk2dUICamera.tk2dRaycastType.Physics2D)
			{
				Collider2D collider2D = Physics2D.OverlapPoint(tk2dUICamera2.HostCamera.ScreenToWorldPoint(screenPos), tk2dUICamera2.FilteredMask);
				if (collider2D != null)
				{
					return collider2D.GetComponent<tk2dUIItem>();
				}
			}
		}
		return null;
	}

	public void OverrideClearAllChildrenPresses(tk2dUIItem item)
	{
		if (useMultiTouch)
		{
			for (int i = 0; i < pressedUIItems.Length; i++)
			{
				tk2dUIItem tk2dUIItem2 = pressedUIItems[i];
				if (tk2dUIItem2 != null && item.CheckIsUIItemChildOfMe(tk2dUIItem2))
				{
					tk2dUIItem2.CurrentOverUIItem(item);
				}
			}
		}
		else if (pressedUIItem != null && item.CheckIsUIItemChildOfMe(pressedUIItem))
		{
			pressedUIItem.CurrentOverUIItem(item);
		}
	}
}
[AddComponentMenu("2D Toolkit/UI/Core/tk2dUIMask")]
[RequireComponent(typeof(MeshRenderer))]
[RequireComponent(typeof(MeshFilter))]
[ExecuteInEditMode]
public class tk2dUIMask : MonoBehaviour
{
	public tk2dBaseSprite.Anchor anchor = tk2dBaseSprite.Anchor.MiddleCenter;

	public Vector2 size = new Vector2(1f, 1f);

	public float depth = 1f;

	public bool createBoxCollider = true;

	private MeshFilter _thisMeshFilter;

	private BoxCollider _thisBoxCollider;

	private static readonly Vector2[] uv = new Vector2[4]
	{
		new Vector2(0f, 0f),
		new Vector2(1f, 0f),
		new Vector2(0f, 1f),
		new Vector2(1f, 1f)
	};

	private static readonly int[] indices = new int[6] { 0, 3, 1, 2, 3, 0 };

	private MeshFilter ThisMeshFilter
	{
		get
		{
			if (_thisMeshFilter == null)
			{
				_thisMeshFilter = GetComponent<MeshFilter>();
			}
			return _thisMeshFilter;
		}
	}

	private BoxCollider ThisBoxCollider
	{
		get
		{
			if (_thisBoxCollider == null)
			{
				_thisBoxCollider = GetComponent<BoxCollider>();
			}
			return _thisBoxCollider;
		}
	}

	private void Awake()
	{
		Build();
	}

	private void OnDestroy()
	{
		if (ThisMeshFilter.sharedMesh != null)
		{
			UnityEngine.Object.Destroy(ThisMeshFilter.sharedMesh);
		}
	}

	private Mesh FillMesh(Mesh mesh)
	{
		Vector3 vector = Vector3.zero;
		switch (anchor)
		{
		case tk2dBaseSprite.Anchor.UpperLeft:
			vector = new Vector3(0f, 0f - size.y, 0f);
			break;
		case tk2dBaseSprite.Anchor.UpperCenter:
			vector = new Vector3((0f - size.x) / 2f, 0f - size.y, 0f);
			break;
		case tk2dBaseSprite.Anchor.UpperRight:
			vector = new Vector3(0f - size.x, 0f - size.y, 0f);
			break;
		case tk2dBaseSprite.Anchor.MiddleLeft:
			vector = new Vector3(0f, (0f - size.y) / 2f, 0f);
			break;
		case tk2dBaseSprite.Anchor.MiddleCenter:
			vector = new Vector3((0f - size.x) / 2f, (0f - size.y) / 2f, 0f);
			break;
		case tk2dBaseSprite.Anchor.MiddleRight:
			vector = new Vector3(0f - size.x, (0f - size.y) / 2f, 0f);
			break;
		case tk2dBaseSprite.Anchor.LowerLeft:
			vector = new Vector3(0f, 0f, 0f);
			break;
		case tk2dBaseSprite.Anchor.LowerCenter:
			vector = new Vector3((0f - size.x) / 2f, 0f, 0f);
			break;
		case tk2dBaseSprite.Anchor.LowerRight:
			vector = new Vector3(0f - size.x, 0f, 0f);
			break;
		}
		Vector3[] vertices = new Vector3[4]
		{
			vector + new Vector3(0f, 0f, 0f - depth),
			vector + new Vector3(size.x, 0f, 0f - depth),
			vector + new Vector3(0f, size.y, 0f - depth),
			vector + new Vector3(size.x, size.y, 0f - depth)
		};
		mesh.vertices = vertices;
		mesh.uv = uv;
		mesh.triangles = indices;
		UnityEngine.Bounds bounds = default(UnityEngine.Bounds);
		bounds.SetMinMax(vector, vector + new Vector3(size.x, size.y, 0f));
		mesh.bounds = bounds;
		return mesh;
	}

	private void OnDrawGizmosSelected()
	{
		Mesh sharedMesh = ThisMeshFilter.sharedMesh;
		if (sharedMesh != null)
		{
			Gizmos.matrix = base.transform.localToWorldMatrix;
			UnityEngine.Bounds bounds = sharedMesh.bounds;
			Gizmos.color = new Color32(56, 146, 227, 96);
			float num = (0f - depth) * 1.001f;
			Vector3 center = new Vector3(bounds.center.x, bounds.center.y, num * 0.5f);
			Vector3 vector = new Vector3(bounds.extents.x * 2f, bounds.extents.y * 2f, Mathf.Abs(num));
			Gizmos.DrawCube(center, vector);
			Gizmos.color = new Color32(22, 145, byte.MaxValue, byte.MaxValue);
			Gizmos.DrawWireCube(center, vector);
		}
	}

	public void Build()
	{
		if (ThisMeshFilter.sharedMesh == null)
		{
			Mesh mesh = new Mesh();
			mesh.MarkDynamic();
			mesh.hideFlags = HideFlags.DontSave;
			ThisMeshFilter.mesh = FillMesh(mesh);
		}
		else
		{
			FillMesh(ThisMeshFilter.sharedMesh);
		}
		if (createBoxCollider)
		{
			if (ThisBoxCollider == null)
			{
				_thisBoxCollider = base.gameObject.AddComponent<BoxCollider>();
			}
			UnityEngine.Bounds bounds = ThisMeshFilter.sharedMesh.bounds;
			ThisBoxCollider.center = new Vector3(bounds.center.x, bounds.center.y, 0f - depth);
			ThisBoxCollider.size = new Vector3(bounds.size.x, bounds.size.y, 0.0002f);
		}
		else if (ThisBoxCollider != null)
		{
			UnityEngine.Object.Destroy(ThisBoxCollider);
		}
	}

	public void ReshapeBounds(Vector3 dMin, Vector3 dMax)
	{
		Vector3 vector = new Vector3(size.x, size.y);
		Vector3 zero = Vector3.zero;
		switch (anchor)
		{
		case tk2dBaseSprite.Anchor.LowerLeft:
			zero.Set(0f, 0f, 0f);
			break;
		case tk2dBaseSprite.Anchor.LowerCenter:
			zero.Set(0.5f, 0f, 0f);
			break;
		case tk2dBaseSprite.Anchor.LowerRight:
			zero.Set(1f, 0f, 0f);
			break;
		case tk2dBaseSprite.Anchor.MiddleLeft:
			zero.Set(0f, 0.5f, 0f);
			break;
		case tk2dBaseSprite.Anchor.MiddleCenter:
			zero.Set(0.5f, 0.5f, 0f);
			break;
		case tk2dBaseSprite.Anchor.MiddleRight:
			zero.Set(1f, 0.5f, 0f);
			break;
		case tk2dBaseSprite.Anchor.UpperLeft:
			zero.Set(0f, 1f, 0f);
			break;
		case tk2dBaseSprite.Anchor.UpperCenter:
			zero.Set(0.5f, 1f, 0f);
			break;
		case tk2dBaseSprite.Anchor.UpperRight:
			zero.Set(1f, 1f, 0f);
			break;
		}
		zero = Vector3.Scale(zero, vector) * -1f;
		Vector3 vector2 = vector + dMax - dMin;
		Vector3 vector3 = new Vector3(Mathf.Approximately(vector.x, 0f) ? 0f : (zero.x * vector2.x / vector.x), Mathf.Approximately(vector.y, 0f) ? 0f : (zero.y * vector2.y / vector.y));
		Vector3 position = zero + dMin - vector3;
		position.z = 0f;
		base.transform.position = base.transform.TransformPoint(position);
		size = new Vector2(vector2.x, vector2.y);
		Build();
	}
}
