public static class tk2dUITime
{
	private static double lastRealTime = 0.0;

	private static float _deltaTime = 1f / 60f;

	public static float deltaTime => _deltaTime;

	public static void Init()
	{
		lastRealTime = Time.realtimeSinceStartup;
		_deltaTime = Time.maximumDeltaTime;
	}

	public static void Update()
	{
		float realtimeSinceStartup = Time.realtimeSinceStartup;
		if (Time.timeScale < 0.001f)
		{
			_deltaTime = Mathf.Min(1f / 15f, (float)((double)realtimeSinceStartup - lastRealTime));
		}
		else
		{
			_deltaTime = Time.deltaTime / Time.timeScale;
		}
		lastRealTime = realtimeSinceStartup;
	}
}
public struct tk2dUITouch
{
	public const int MOUSE_POINTER_FINGER_ID = 9999;

	public TouchPhase phase { get; private set; }

	public int fingerId { get; private set; }

	public Vector2 position { get; private set; }

	public Vector2 deltaPosition { get; private set; }

	public float deltaTime { get; private set; }

	public tk2dUITouch(TouchPhase _phase, int _fingerId, Vector2 _position, Vector2 _deltaPosition, float _deltaTime)
	{
		this = default(tk2dUITouch);
		phase = _phase;
		fingerId = _fingerId;
		position = _position;
		deltaPosition = _deltaPosition;
		deltaTime = _deltaTime;
	}

	public tk2dUITouch(UnityEngine.Touch touch)
	{
		this = default(tk2dUITouch);
		phase = touch.phase;
		fingerId = touch.fingerId;
		position = touch.position;
		deltaPosition = deltaPosition;
		deltaTime = deltaTime;
	}

	public override string ToString()
	{
		return phase.ToString() + "," + fingerId + "," + position.ToString() + "," + deltaPosition.ToString() + "," + deltaTime;
	}
}
public class TextMeshSharpener : MonoBehaviour
{
	private float lastPixelHeight = -1f;

	private TextMesh textMesh;

	private void Start()
	{
		textMesh = GetComponent<TextMesh>();
		resize();
	}

	private void Update()
	{
		if ((float)Camera.main.pixelHeight != lastPixelHeight || (Application.isEditor && !Application.isPlaying))
		{
			resize();
		}
	}

	private void resize()
	{
		float num = Camera.main.pixelHeight;
		float num2 = Camera.main.orthographicSize * 2f / num;
		float num3 = 128f;
		textMesh.characterSize = num2 * Camera.main.orthographicSize / Math.Max(base.transform.localScale.x, base.transform.localScale.y);
		textMesh.fontSize = (int)Math.Round(num3 / textMesh.characterSize);
		lastPixelHeight = num;
	}
}
public class WaveEffectControl : MonoBehaviour
{
	private float timer;

	public Color colour;

	public SpriteRenderer spriteRenderer;

	public float accel;

	public float accelStart = 5f;

	public bool doNotRecycle;

	public bool doNotPositionZ;

	public bool blackWave;

	public bool otherColour;

	public float scaleMultiplier = 1f;

	private void Start()
	{
		spriteRenderer = GetComponent<SpriteRenderer>();
	}

	private void OnEnable()
	{
		timer = 0f;
		if (blackWave)
		{
			colour = new Color(0f, 0f, 0f, 1f);
		}
		else if (!otherColour)
		{
			colour = new Color(1f, 1f, 1f, 1f);
		}
		accel = accelStart;
		if (!doNotPositionZ)
		{
			base.transform.position = new Vector3(base.transform.position.x, base.transform.position.y, 0.1f);
		}
	}

	private void Update()
	{
		timer += Time.deltaTime * accel;
		float num = (1f + timer * 4f) * scaleMultiplier;
		base.transform.localScale = new Vector3(num, num, num);
		Color color = spriteRenderer.color;
		color.a = 1f - timer;
		spriteRenderer.color = color;
		if (timer > 1f)
		{
			if (!doNotRecycle)
			{
				base.gameObject.Recycle();
			}
			else
			{
				base.gameObject.SetActive(value: false);
			}
		}
	}

	private void FixedUpdate()
	{
		accel *= 0.95f;
		if (accel < 0.5f)
		{
			accel = 0.5f;
		}
	}
}
