		protected override void AdjustLineOffset(int startIndex, int endIndex, float offset)
		{
			Vector3 vector = new Vector3(0f, offset, 0f);
			for (int i = startIndex; i <= endIndex; i++)
			{
				m_textInfo.characterInfo[i].bottomLeft -= vector;
				m_textInfo.characterInfo[i].topLeft -= vector;
				m_textInfo.characterInfo[i].topRight -= vector;
				m_textInfo.characterInfo[i].bottomRight -= vector;
				m_textInfo.characterInfo[i].ascender -= vector.y;
				m_textInfo.characterInfo[i].baseLine -= vector.y;
				m_textInfo.characterInfo[i].descender -= vector.y;
				if (m_textInfo.characterInfo[i].isVisible)
				{
					m_textInfo.characterInfo[i].vertex_BL.position -= vector;
					m_textInfo.characterInfo[i].vertex_TL.position -= vector;
					m_textInfo.characterInfo[i].vertex_TR.position -= vector;
					m_textInfo.characterInfo[i].vertex_BR.position -= vector;
				}
			}
		}

		public void CalculateLayoutInputHorizontal()
		{
			if (base.gameObject.activeInHierarchy && (m_isCalculateSizeRequired || m_rectTransform.hasChanged))
			{
				m_preferredWidth = GetPreferredWidth();
				ComputeMarginSize();
				m_isLayoutDirty = true;
			}
		}

		public void CalculateLayoutInputVertical()
		{
			if (base.gameObject.activeInHierarchy)
			{
				if (m_isCalculateSizeRequired || m_rectTransform.hasChanged)
				{
					m_preferredHeight = GetPreferredHeight();
					ComputeMarginSize();
					m_isLayoutDirty = true;
				}
				m_isCalculateSizeRequired = false;
			}
		}

		public override void SetVerticesDirty()
		{
			if (!m_verticesAlreadyDirty && !(this == null) && IsActive() && !CanvasUpdateRegistry.IsRebuildingGraphics())
			{
				m_verticesAlreadyDirty = true;
				CanvasUpdateRegistry.RegisterCanvasElementForGraphicRebuild(this);
			}
		}

		public override void SetLayoutDirty()
		{
			if (!m_layoutAlreadyDirty && !(this == null) && IsActive())
			{
				m_layoutAlreadyDirty = true;
				LayoutRebuilder.MarkLayoutForRebuild(base.rectTransform);
				m_isLayoutDirty = true;
			}
		}

		public override void SetMaterialDirty()
		{
			if (!(this == null) && IsActive() && !CanvasUpdateRegistry.IsRebuildingGraphics())
			{
				m_isMaterialDirty = true;
				CanvasUpdateRegistry.RegisterCanvasElementForGraphicRebuild(this);
			}
		}

		public override void SetAllDirty()
		{
			SetLayoutDirty();
			SetVerticesDirty();
			SetMaterialDirty();
		}

		public override void Rebuild(CanvasUpdate update)
		{
			if (!(this == null) && update == CanvasUpdate.PreRender)
			{
				OnPreRenderCanvas();
				m_verticesAlreadyDirty = false;
				m_layoutAlreadyDirty = false;
				if (m_isMaterialDirty)
				{
					UpdateMaterial();
					m_isMaterialDirty = false;
				}
			}
		}

		private void UpdateSubObjectPivot()
		{
			if (m_textInfo != null)
			{
				for (int i = 1; i < m_subTextObjects.Length && m_subTextObjects[i] != null; i++)
				{
					m_subTextObjects[i].SetPivotDirty();
				}
			}
		}

		public override Material GetModifiedMaterial(Material baseMaterial)
		{
			Material material = baseMaterial;
			if (m_ShouldRecalculateStencil)
			{
				m_stencilID = TMP_MaterialManager.GetStencilID(base.gameObject);
				m_ShouldRecalculateStencil = false;
			}
			if (m_stencilID > 0)
			{
				material = TMP_MaterialManager.GetStencilMaterial(baseMaterial, m_stencilID);
				if (m_MaskMaterial != null)
				{
					TMP_MaterialManager.ReleaseStencilMaterial(m_MaskMaterial);
				}
				m_MaskMaterial = material;
			}
			return material;
		}

		protected override void UpdateMaterial()
		{
			if (m_canvasRenderer == null)
			{
				m_canvasRenderer = canvasRenderer;
			}
			m_canvasRenderer.materialCount = 1;
			m_canvasRenderer.SetMaterial(materialForRendering, m_sharedMaterial.mainTexture);
		}

		public override void RecalculateClipping()
		{
			base.RecalculateClipping();
		}

		public override void RecalculateMasking()
		{
			m_ShouldRecalculateStencil = true;
			SetMaterialDirty();
		}

		public override void UpdateMeshPadding()
		{
			m_padding = ShaderUtilities.GetPadding(m_sharedMaterial, m_enableExtraPadding, m_isUsingBold);
			m_isMaskingEnabled = ShaderUtilities.IsMaskingEnabled(m_sharedMaterial);
			m_havePropertiesChanged = true;
			checkPaddingRequired = false;
			for (int i = 1; i < m_textInfo.materialCount; i++)
			{
				m_subTextObjects[i].UpdateMeshPadding(m_enableExtraPadding, m_isUsingBold);
			}
		}

		protected override void InternalCrossFadeColor(Color targetColor, float duration, bool ignoreTimeScale, bool useAlpha)
		{
			int materialCount = m_textInfo.materialCount;
			for (int i = 1; i < materialCount; i++)
			{
				m_subTextObjects[i].CrossFadeColor(targetColor, duration, ignoreTimeScale, useAlpha);
			}
		}

		protected override void InternalCrossFadeAlpha(float alpha, float duration, bool ignoreTimeScale)
		{
			int materialCount = m_textInfo.materialCount;
			for (int i = 1; i < materialCount; i++)
			{
				m_subTextObjects[i].CrossFadeAlpha(alpha, duration, ignoreTimeScale);
			}
		}

		public override void ForceMeshUpdate()
		{
			m_havePropertiesChanged = true;
			OnPreRenderCanvas();
		}

		public override void ForceMeshUpdate(bool ignoreInactive)
		{
			m_havePropertiesChanged = true;
			m_ignoreActiveState = true;
			OnPreRenderCanvas();
		}

		public override TMP_TextInfo GetTextInfo(string text)
		{
			StringToCharArray(text, ref m_char_buffer);
			SetArraySizes(m_char_buffer);
			m_renderMode = TextRenderFlags.DontRender;
			ComputeMarginSize();
			if (m_canvas == null)
			{
				m_canvas = base.canvas;
			}
			GenerateTextMesh();
			m_renderMode = TextRenderFlags.Render;
			return base.textInfo;
		}

		public override void UpdateGeometry(Mesh mesh, int index)
		{
			mesh.RecalculateBounds();
			if (index == 0)
			{
				m_canvasRenderer.SetMesh(mesh);
			}
			else
			{
				m_subTextObjects[index].canvasRenderer.SetMesh(mesh);
			}
		}

		public override void UpdateVertexData(TMP_VertexDataUpdateFlags flags)
		{
			int materialCount = m_textInfo.materialCount;
			for (int i = 0; i < materialCount; i++)
			{
				Mesh mesh = ((i != 0) ? m_subTextObjects[i].mesh : m_mesh);
				if ((flags & TMP_VertexDataUpdateFlags.Vertices) == TMP_VertexDataUpdateFlags.Vertices)
				{
					mesh.vertices = m_textInfo.meshInfo[i].vertices;
				}
				if ((flags & TMP_VertexDataUpdateFlags.Uv0) == TMP_VertexDataUpdateFlags.Uv0)
				{
					mesh.uv = m_textInfo.meshInfo[i].uvs0;
				}
				if ((flags & TMP_VertexDataUpdateFlags.Uv2) == TMP_VertexDataUpdateFlags.Uv2)
				{
					mesh.uv2 = m_textInfo.meshInfo[i].uvs2;
				}
				if ((flags & TMP_VertexDataUpdateFlags.Colors32) == TMP_VertexDataUpdateFlags.Colors32)
				{
					mesh.colors32 = m_textInfo.meshInfo[i].colors32;
				}
				mesh.RecalculateBounds();
				if (i == 0)
				{
					m_canvasRenderer.SetMesh(mesh);
				}
				else
				{
					m_subTextObjects[i].canvasRenderer.SetMesh(mesh);
				}
			}
		}

		public override void UpdateVertexData()
		{
			int materialCount = m_textInfo.materialCount;
			for (int i = 0; i < materialCount; i++)
			{
				Mesh mesh = ((i != 0) ? m_subTextObjects[i].mesh : m_mesh);
				mesh.vertices = m_textInfo.meshInfo[i].vertices;
				mesh.uv = m_textInfo.meshInfo[i].uvs0;
				mesh.uv2 = m_textInfo.meshInfo[i].uvs2;
				mesh.colors32 = m_textInfo.meshInfo[i].colors32;
				mesh.RecalculateBounds();
				if (i == 0)
				{
					m_canvasRenderer.SetMesh(mesh);
				}
				else
				{
					m_subTextObjects[i].canvasRenderer.SetMesh(mesh);
				}
			}
		}

		public void UpdateFontAsset()
		{
			LoadFontAsset();
		}
	}
	public enum TextContainerAnchors
	{
		TopLeft,
		Top,
		TopRight,
		Left,
		Middle,
		Right,
		BottomLeft,
		Bottom,
		BottomRight,
		Custom
	}
	[ExecuteInEditMode]
	[RequireComponent(typeof(RectTransform))]
	[AddComponentMenu("Layout/Text Container")]
	public class TextContainer : UIBehaviour
	{
		private bool m_hasChanged;

		[SerializeField]
		private Vector2 m_pivot;

		[SerializeField]
		private TextContainerAnchors m_anchorPosition = TextContainerAnchors.Middle;

		[SerializeField]
		private Rect m_rect;

		private bool m_isDefaultWidth;

		private bool m_isDefaultHeight;

		private bool m_isAutoFitting;

		private Vector3[] m_corners = new Vector3[4];

		private Vector3[] m_worldCorners = new Vector3[4];

		[SerializeField]
		private Vector4 m_margins;

		private RectTransform m_rectTransform;

		private static Vector2 k_defaultSize = new Vector2(100f, 100f);

		private TextMeshPro m_textMeshPro;

		public bool hasChanged
		{
			get
			{
				return m_hasChanged;
			}
			set
			{
				m_hasChanged = value;
			}
		}

		public Vector2 pivot
		{
			get
			{
				return m_pivot;
			}
			set
			{
				if (m_pivot != value)
				{
					m_pivot = value;
					m_anchorPosition = GetAnchorPosition(m_pivot);
					m_hasChanged = true;
					OnContainerChanged();
				}
			}
		}

		public TextContainerAnchors anchorPosition
		{
			get
			{
				return m_anchorPosition;
			}
			set
			{
				if (m_anchorPosition != value)
				{
					m_anchorPosition = value;
					m_pivot = GetPivot(m_anchorPosition);
					m_hasChanged = true;
					OnContainerChanged();
				}
			}
		}

		public Rect rect
		{
			get
			{
				return m_rect;
			}
			set
			{
				if (m_rect != value)
				{
					m_rect = value;
					m_hasChanged = true;
					OnContainerChanged();
				}
			}
		}

		public Vector2 size
		{
			get
			{
				return new Vector2(m_rect.width, m_rect.height);
			}
			set
			{
				if (new Vector2(m_rect.width, m_rect.height) != value)
				{
					SetRect(value);
					m_hasChanged = true;
					m_isDefaultWidth = false;
					m_isDefaultHeight = false;
					OnContainerChanged();
				}
			}
		}

		public float width
		{
			get
			{
				return m_rect.width;
			}
			set
			{
				SetRect(new Vector2(value, m_rect.height));
				m_hasChanged = true;
				m_isDefaultWidth = false;
				OnContainerChanged();
			}
		}

		public float height
		{
			get
			{
				return m_rect.height;
			}
			set
			{
				SetRect(new Vector2(m_rect.width, value));
				m_hasChanged = true;
				m_isDefaultHeight = false;
				OnContainerChanged();
			}
		}

		public bool isDefaultWidth => m_isDefaultWidth;

		public bool isDefaultHeight => m_isDefaultHeight;

		public bool isAutoFitting
		{
			get
			{
				return m_isAutoFitting;
			}
			set
			{
				m_isAutoFitting = value;
			}
		}

		public Vector3[] corners => m_corners;

		public Vector3[] worldCorners => m_worldCorners;

		public Vector4 margins
		{
			get
			{
				return m_margins;
			}
			set
			{
				if (m_margins != value)
				{
					m_margins = value;
					m_hasChanged = true;
					OnContainerChanged();
				}
			}
		}

		public RectTransform rectTransform
		{
			get
			{
				if (m_rectTransform == null)
				{
					m_rectTransform = GetComponent<RectTransform>();
				}
				return m_rectTransform;
			}
		}

		public TextMeshPro textMeshPro
		{
			get
			{
				if (m_textMeshPro == null)
				{
					m_textMeshPro = GetComponent<TextMeshPro>();
				}
				return m_textMeshPro;
			}
		}

		protected override void Awake()
		{
			m_rectTransform = rectTransform;
			if (m_rectTransform == null)
			{
				Vector2 vector = m_pivot;
				m_rectTransform = base.gameObject.AddComponent<RectTransform>();
				m_pivot = vector;
			}
			m_textMeshPro = GetComponent(typeof(TextMeshPro)) as TextMeshPro;
			if (m_rect.width != 0f && m_rect.height != 0f)
			{
				return;
			}
			if (m_textMeshPro != null && m_textMeshPro.anchor != TMP_Compatibility.AnchorPositions.None)
			{
				UnityEngine.Debug.LogWarning("Converting from using anchor and lineLength properties to Text Container.", this);
				m_isDefaultHeight = true;
				int num = (int)m_textMeshPro.anchor;
				m_textMeshPro.anchor = TMP_Compatibility.AnchorPositions.None;
				if (num == 9)
				{
					switch (m_textMeshPro.alignment)
					{
					case TextAlignmentOptions.TopLeft:
						m_textMeshPro.alignment = TextAlignmentOptions.BaselineLeft;
						break;
					case TextAlignmentOptions.Top:
						m_textMeshPro.alignment = TextAlignmentOptions.Baseline;
						break;
					case TextAlignmentOptions.TopRight:
						m_textMeshPro.alignment = TextAlignmentOptions.BaselineRight;
						break;
					case TextAlignmentOptions.TopJustified:
						m_textMeshPro.alignment = TextAlignmentOptions.BaselineJustified;
						break;
					}
					num = 3;
				}
				m_anchorPosition = (TextContainerAnchors)num;
				m_pivot = GetPivot(m_anchorPosition);
				if (m_textMeshPro.lineLength == 72f)
				{
					m_rect.size = m_textMeshPro.GetPreferredValues(m_textMeshPro.text);
				}
				else
				{
					m_rect.width = m_textMeshPro.lineLength;
					m_rect.height = m_textMeshPro.GetPreferredValues(m_rect.width, float.PositiveInfinity).y;
				}
			}
			else
			{
				m_isDefaultWidth = true;
				m_isDefaultHeight = true;
				m_pivot = GetPivot(m_anchorPosition);
				m_rect.width = 20f;
				m_rect.height = 5f;
				m_rectTransform.sizeDelta = size;
			}
			m_margins = new Vector4(0f, 0f, 0f, 0f);
			UpdateCorners();
		}

		protected override void OnEnable()
		{
			OnContainerChanged();
		}

		protected override void OnDisable()
		{
		}

		private void OnContainerChanged()
		{
			UpdateCorners();
			if (m_rectTransform != null)
			{
				m_rectTransform.sizeDelta = size;
				m_rectTransform.hasChanged = true;
			}
			if (textMeshPro != null)
			{
				m_textMeshPro.SetVerticesDirty();
				m_textMeshPro.margin = m_margins;
			}
		}

		protected override void OnRectTransformDimensionsChange()
		{
			if (rectTransform == null)
			{
				m_rectTransform = base.gameObject.AddComponent<RectTransform>();
			}
			if (m_rectTransform.sizeDelta != k_defaultSize)
			{
				size = m_rectTransform.sizeDelta;
			}
			pivot = m_rectTransform.pivot;
			m_hasChanged = true;
			OnContainerChanged();
		}

		private void SetRect(Vector2 size)
		{
			m_rect = new Rect(m_rect.x, m_rect.y, size.x, size.y);
		}

		private void UpdateCorners()
		{
			m_corners[0] = new Vector3((0f - m_pivot.x) * m_rect.width, (0f - m_pivot.y) * m_rect.height);
			m_corners[1] = new Vector3((0f - m_pivot.x) * m_rect.width, (1f - m_pivot.y) * m_rect.height);
			m_corners[2] = new Vector3((1f - m_pivot.x) * m_rect.width, (1f - m_pivot.y) * m_rect.height);
			m_corners[3] = new Vector3((1f - m_pivot.x) * m_rect.width, (0f - m_pivot.y) * m_rect.height);
			if (m_rectTransform != null)
			{
				m_rectTransform.pivot = m_pivot;
			}
		}

		private Vector2 GetPivot(TextContainerAnchors anchor)
		{
			Vector2 result = Vector2.zero;
			switch (anchor)
			{
			case TextContainerAnchors.TopLeft:
				result = new Vector2(0f, 1f);
				break;
			case TextContainerAnchors.Top:
				result = new Vector2(0.5f, 1f);
				break;
			case TextContainerAnchors.TopRight:
				result = new Vector2(1f, 1f);
				break;
			case TextContainerAnchors.Left:
				result = new Vector2(0f, 0.5f);
				break;
			case TextContainerAnchors.Middle:
				result = new Vector2(0.5f, 0.5f);
				break;
			case TextContainerAnchors.Right:
				result = new Vector2(1f, 0.5f);
				break;
			case TextContainerAnchors.BottomLeft:
				result = new Vector2(0f, 0f);
				break;
			case TextContainerAnchors.Bottom:
				result = new Vector2(0.5f, 0f);
				break;
			case TextContainerAnchors.BottomRight:
				result = new Vector2(1f, 0f);
				break;
			}
			return result;
		}

		private TextContainerAnchors GetAnchorPosition(Vector2 pivot)
		{
			if (pivot == new Vector2(0f, 1f))
			{
				return TextContainerAnchors.TopLeft;
			}
			if (pivot == new Vector2(0.5f, 1f))
			{
				return TextContainerAnchors.Top;
			}
			if (pivot == new Vector2(1f, 1f))
			{
				return TextContainerAnchors.TopRight;
			}
			if (pivot == new Vector2(0f, 0.5f))
			{
				return TextContainerAnchors.Left;
			}
			if (pivot == new Vector2(0.5f, 0.5f))
			{
				return TextContainerAnchors.Middle;
			}
			if (pivot == new Vector2(1f, 0.5f))
			{
				return TextContainerAnchors.Right;
			}
			if (pivot == new Vector2(0f, 0f))
			{
				return TextContainerAnchors.BottomLeft;
			}
			if (pivot == new Vector2(0.5f, 0f))
			{
				return TextContainerAnchors.Bottom;
			}
			if (pivot == new Vector2(1f, 0f))
			{
				return TextContainerAnchors.BottomRight;
			}
			return TextContainerAnchors.Custom;
		}
	}
}
namespace tk2dRuntime
{
	internal static class SpriteCollectionGenerator
	{
		public static tk2dSpriteCollectionData CreateFromTexture(Texture texture, tk2dSpriteCollectionSize size, Rect region, Vector2 anchor)
		{
			return CreateFromTexture(texture, size, new string[1] { "Unnamed" }, new Rect[1] { region }, new Vector2[1] { anchor });
		}

		public static tk2dSpriteCollectionData CreateFromTexture(Texture texture, tk2dSpriteCollectionSize size, string[] names, Rect[] regions, Vector2[] anchors)
		{
			Vector2 textureDimensions = new Vector2(texture.width, texture.height);
			return CreateFromTexture(texture, size, textureDimensions, names, regions, null, anchors, null);
		}

		public static tk2dSpriteCollectionData CreateFromTexture(Texture texture, tk2dSpriteCollectionSize size, Vector2 textureDimensions, string[] names, Rect[] regions, Rect[] trimRects, Vector2[] anchors, bool[] rotated)
		{
			return CreateFromTexture(null, texture, size, textureDimensions, names, regions, trimRects, anchors, rotated);
		}

		public static tk2dSpriteCollectionData CreateFromTexture(GameObject parentObject, Texture texture, tk2dSpriteCollectionSize size, Vector2 textureDimensions, string[] names, Rect[] regions, Rect[] trimRects, Vector2[] anchors, bool[] rotated)
		{
			tk2dSpriteCollectionData tk2dSpriteCollectionData2 = ((parentObject != null) ? parentObject : new GameObject("SpriteCollection")).AddComponent<tk2dSpriteCollectionData>();
			tk2dSpriteCollectionData2.Transient = true;
			tk2dSpriteCollectionData2.version = 3;
			tk2dSpriteCollectionData2.invOrthoSize = 1f / size.OrthoSize;
			tk2dSpriteCollectionData2.halfTargetHeight = size.TargetHeight * 0.5f;
			tk2dSpriteCollectionData2.premultipliedAlpha = false;
			string name = "tk2d/BlendVertexColor";
			tk2dSpriteCollectionData2.material = new Material(Shader.Find(name));
			tk2dSpriteCollectionData2.material.mainTexture = texture;
			tk2dSpriteCollectionData2.materials = new Material[1] { tk2dSpriteCollectionData2.material };
			tk2dSpriteCollectionData2.textures = new Texture[1] { texture };
			tk2dSpriteCollectionData2.buildKey = UnityEngine.Random.Range(0, int.MaxValue);
			float scale = 2f * size.OrthoSize / size.TargetHeight;
			Rect trimRect = new Rect(0f, 0f, 0f, 0f);
			tk2dSpriteCollectionData2.spriteDefinitions = new tk2dSpriteDefinition[regions.Length];
			for (int i = 0; i < regions.Length; i++)
			{
				bool flag = rotated != null && rotated[i];
				if (trimRects != null)
				{
					trimRect = trimRects[i];
				}
				else if (flag)
				{
					trimRect.Set(0f, 0f, regions[i].height, regions[i].width);
				}
				else
				{
					trimRect.Set(0f, 0f, regions[i].width, regions[i].height);
				}
				tk2dSpriteCollectionData2.spriteDefinitions[i] = CreateDefinitionForRegionInTexture(names[i], textureDimensions, scale, regions[i], trimRect, anchors[i], flag);
			}
			tk2dSpriteDefinition[] spriteDefinitions = tk2dSpriteCollectionData2.spriteDefinitions;
			for (int j = 0; j < spriteDefinitions.Length; j++)
			{
				spriteDefinitions[j].material = tk2dSpriteCollectionData2.material;
			}
			return tk2dSpriteCollectionData2;
		}

		private static tk2dSpriteDefinition CreateDefinitionForRegionInTexture(string name, Vector2 textureDimensions, float scale, Rect uvRegion, Rect trimRect, Vector2 anchor, bool rotated)
		{
			float height = uvRegion.height;
			float width = uvRegion.width;
			float x = textureDimensions.x;
			float y = textureDimensions.y;
			tk2dSpriteDefinition tk2dSpriteDefinition2 = new tk2dSpriteDefinition();
			tk2dSpriteDefinition2.flipped = (rotated ? tk2dSpriteDefinition.FlipMode.TPackerCW : tk2dSpriteDefinition.FlipMode.None);
			tk2dSpriteDefinition2.extractRegion = false;
			tk2dSpriteDefinition2.name = name;
			tk2dSpriteDefinition2.colliderType = tk2dSpriteDefinition.ColliderType.Unset;
			Vector2 vector = new Vector2(0.001f, 0.001f);
			Vector2 vector2 = new Vector2((uvRegion.x + vector.x) / x, 1f - (uvRegion.y + uvRegion.height + vector.y) / y);
			Vector2 vector3 = new Vector2((uvRegion.x + uvRegion.width - vector.x) / x, 1f - (uvRegion.y - vector.y) / y);
			Vector2 vector4 = new Vector2(trimRect.x - anchor.x, 0f - trimRect.y + anchor.y);
			if (rotated)
			{
				vector4.y -= width;
			}
			vector4 *= scale;
			Vector3 vector5 = new Vector3((0f - anchor.x) * scale, anchor.y * scale, 0f);
			Vector3 vector6 = vector5 + new Vector3(trimRect.width * scale, (0f - trimRect.height) * scale, 0f);
			Vector3 vector7 = new Vector3(0f, (0f - height) * scale, 0f);
			Vector3 vector8 = vector7 + new Vector3(width * scale, height * scale, 0f);
			if (rotated)
			{
				tk2dSpriteDefinition2.positions = new Vector3[4]
				{
					new Vector3(0f - vector8.y + vector4.x, vector7.x + vector4.y, 0f),
					new Vector3(0f - vector7.y + vector4.x, vector7.x + vector4.y, 0f),
					new Vector3(0f - vector8.y + vector4.x, vector8.x + vector4.y, 0f),
					new Vector3(0f - vector7.y + vector4.x, vector8.x + vector4.y, 0f)
				};
				tk2dSpriteDefinition2.uvs = new Vector2[4]
				{
					new Vector2(vector2.x, vector3.y),
					new Vector2(vector2.x, vector2.y),
					new Vector2(vector3.x, vector3.y),
					new Vector2(vector3.x, vector2.y)
				};
			}
			else
			{
				tk2dSpriteDefinition2.positions = new Vector3[4]
				{
					new Vector3(vector7.x + vector4.x, vector7.y + vector4.y, 0f),
					new Vector3(vector8.x + vector4.x, vector7.y + vector4.y, 0f),
					new Vector3(vector7.x + vector4.x, vector8.y + vector4.y, 0f),
					new Vector3(vector8.x + vector4.x, vector8.y + vector4.y, 0f)
				};
				tk2dSpriteDefinition2.uvs = new Vector2[4]
				{
					new Vector2(vector2.x, vector2.y),
					new Vector2(vector3.x, vector2.y),
					new Vector2(vector2.x, vector3.y),
					new Vector2(vector3.x, vector3.y)
				};
			}
			tk2dSpriteDefinition2.normals = new Vector3[0];
			tk2dSpriteDefinition2.tangents = new Vector4[0];
			tk2dSpriteDefinition2.indices = new int[6] { 0, 3, 1, 2, 3, 0 };
			Vector3 vector9 = new Vector3(vector5.x, vector6.y, 0f);
			Vector3 vector10 = new Vector3(vector6.x, vector5.y, 0f);
			tk2dSpriteDefinition2.boundsData = new Vector3[2]
			{
				(vector10 + vector9) / 2f,
				vector10 - vector9
			};
			tk2dSpriteDefinition2.untrimmedBoundsData = new Vector3[2]
			{
				(vector10 + vector9) / 2f,
				vector10 - vector9
			};
			tk2dSpriteDefinition2.texelSize = new Vector2(scale, scale);
			return tk2dSpriteDefinition2;
		}

		public static tk2dSpriteCollectionData CreateFromTexturePacker(tk2dSpriteCollectionSize spriteCollectionSize, string texturePackerFileContents, Texture texture)
		{
			List<string> list = new List<string>();
			List<Rect> list2 = new List<Rect>();
			List<Rect> list3 = new List<Rect>();
			List<Vector2> list4 = new List<Vector2>();
			List<bool> list5 = new List<bool>();
			int num = 0;
			TextReader textReader = new StringReader(texturePackerFileContents);
			bool flag = false;
			bool flag2 = false;
			string item = "";
			Rect item2 = default(Rect);
			Rect item3 = default(Rect);
			Vector2 zero = Vector2.zero;
			Vector2 zero2 = Vector2.zero;
			for (string text = textReader.ReadLine(); text != null; text = textReader.ReadLine())
			{
				if (text.Length > 0)
				{
					char c = text[0];
					switch (num)
					{
					case 0:
						switch (c)
						{
						case 'w':
							zero.x = int.Parse(text.Substring(2));
							break;
						case 'h':
							zero.y = int.Parse(text.Substring(2));
							break;
						case '~':
							num++;
							break;
						}
						break;
					case 1:
						switch (c)
						{
						case 'n':
							item = text.Substring(2);
							break;
						case 'r':
							flag = int.Parse(text.Substring(2)) == 1;
							break;
						case 's':
						{
							string[] array = text.Split();
							item2.Set(int.Parse(array[1]), int.Parse(array[2]), int.Parse(array[3]), int.Parse(array[4]));
							break;
						}
						case 'o':
						{
							string[] array2 = text.Split();
							item3.Set(int.Parse(array2[1]), int.Parse(array2[2]), int.Parse(array2[3]), int.Parse(array2[4]));
							flag2 = true;
							break;
						}
						case '~':
							list.Add(item);
							list5.Add(flag);
							list2.Add(item2);
							if (!flag2)
							{
								if (flag)
								{
									item3.Set(0f, 0f, item2.height, item2.width);
								}
								else
								{
									item3.Set(0f, 0f, item2.width, item2.height);
								}
							}
							list3.Add(item3);
							zero2.Set((int)(item3.width / 2f), (int)(item3.height / 2f));
							list4.Add(zero2);
							item = "";
							flag2 = false;
							flag = false;
							break;
						}
						break;
					}
				}
			}
			return CreateFromTexture(texture, spriteCollectionSize, zero, list.ToArray(), list2.ToArray(), list3.ToArray(), list4.ToArray(), list5.ToArray());
		}
	}
