		public void ClearDirtyFlag()
		{
			ColorChunk[] array = chunks;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].Dirty = false;
			}
		}

		public void Clear(Color color)
		{
			clearColor = color;
			ColorChunk[] array = chunks;
			foreach (ColorChunk chunk in array)
			{
				ClearChunk(chunk);
			}
			Optimize();
		}

		public void Delete()
		{
			chunks = new ColorChunk[0];
		}

		public void Create()
		{
			chunks = new ColorChunk[numColumns * numRows];
			for (int i = 0; i < chunks.Length; i++)
			{
				chunks[i] = new ColorChunk();
			}
		}

		private void Optimize(ColorChunk chunk)
		{
			bool flag = true;
			Color32 color = clearColor;
			Color32[] colors = chunk.colors;
			for (int i = 0; i < colors.Length; i++)
			{
				Color32 color2 = colors[i];
				if (color2.r != color.r || color2.g != color.g || color2.b != color.b || color2.a != color.a)
				{
					flag = false;
					break;
				}
			}
			if (flag)
			{
				chunk.colors = new Color32[0];
			}
		}

		public void Optimize()
		{
			ColorChunk[] array = chunks;
			foreach (ColorChunk chunk in array)
			{
				Optimize(chunk);
			}
		}
	}
	[Serializable]
	public class Layer
	{
		public int hash;

		public SpriteChannel spriteChannel;

		private const int tileMask = 16777215;

		private const int flagMask = -16777216;

		public int width;

		public int height;

		public int numColumns;

		public int numRows;

		public int divX;

		public int divY;

		public GameObject gameObject;

		public bool IsEmpty => spriteChannel.chunks.Length == 0;

		public int NumActiveChunks
		{
			get
			{
				int num = 0;
				SpriteChunk[] chunks = spriteChannel.chunks;
				for (int i = 0; i < chunks.Length; i++)
				{
					if (!chunks[i].IsEmpty)
					{
						num++;
					}
				}
				return num;
			}
		}

		public Layer(int hash, int width, int height, int divX, int divY)
		{
			spriteChannel = new SpriteChannel();
			Init(hash, width, height, divX, divY);
		}

		public void Init(int hash, int width, int height, int divX, int divY)
		{
			this.divX = divX;
			this.divY = divY;
			this.hash = hash;
			numColumns = (width + divX - 1) / divX;
			numRows = (height + divY - 1) / divY;
			this.width = width;
			this.height = height;
			spriteChannel.chunks = new SpriteChunk[numColumns * numRows];
			for (int i = 0; i < numColumns * numRows; i++)
			{
				spriteChannel.chunks[i] = new SpriteChunk();
			}
		}

		public void Create()
		{
			spriteChannel.chunks = new SpriteChunk[numColumns * numRows];
		}

		public int[] GetChunkData(int x, int y)
		{
			return GetChunk(x, y).spriteIds;
		}

		public SpriteChunk GetChunk(int x, int y)
		{
			return spriteChannel.chunks[y * numColumns + x];
		}

		private SpriteChunk FindChunkAndCoordinate(int x, int y, out int offset)
		{
			int num = x / divX;
			int num2 = y / divY;
			SpriteChunk result = spriteChannel.chunks[num2 * numColumns + num];
			int num3 = x - num * divX;
			int num4 = y - num2 * divY;
			offset = num4 * divX + num3;
			return result;
		}

		private bool GetRawTileValue(int x, int y, ref int value)
		{
			SpriteChunk spriteChunk = FindChunkAndCoordinate(x, y, out var offset);
			if (spriteChunk.spriteIds == null || spriteChunk.spriteIds.Length == 0)
			{
				return false;
			}
			value = spriteChunk.spriteIds[offset];
			return true;
		}

		private void SetRawTileValue(int x, int y, int value)
		{
			SpriteChunk spriteChunk = FindChunkAndCoordinate(x, y, out var offset);
			if (spriteChunk != null)
			{
				CreateChunk(spriteChunk);
				spriteChunk.spriteIds[offset] = value;
				spriteChunk.Dirty = true;
			}
		}

		public void DestroyGameData(tk2dTileMap tilemap)
		{
			SpriteChunk[] chunks = spriteChannel.chunks;
			foreach (SpriteChunk spriteChunk in chunks)
			{
				if (spriteChunk.HasGameData)
				{
					spriteChunk.DestroyColliderData(tilemap);
					spriteChunk.DestroyGameData(tilemap);
				}
			}
		}

		public int GetTile(int x, int y)
		{
			int value = 0;
			if (GetRawTileValue(x, y, ref value) && value != -1)
			{
				return value & 0xFFFFFF;
			}
			return -1;
		}

		public tk2dTileFlags GetTileFlags(int x, int y)
		{
			int value = 0;
			if (GetRawTileValue(x, y, ref value) && value != -1)
			{
				return (tk2dTileFlags)(value & -16777216);
			}
			return tk2dTileFlags.None;
		}

		public int GetRawTile(int x, int y)
		{
			int value = 0;
			if (GetRawTileValue(x, y, ref value))
			{
				return value;
			}
			return -1;
		}

		public void SetTile(int x, int y, int tile)
		{
			tk2dTileFlags tileFlags = GetTileFlags(x, y);
			int value = ((tile == -1) ? (-1) : (tile | (int)tileFlags));
			SetRawTileValue(x, y, value);
		}

		public void SetTileFlags(int x, int y, tk2dTileFlags flags)
		{
			int tile = GetTile(x, y);
			if (tile != -1)
			{
				int value = tile | (int)flags;
				SetRawTileValue(x, y, value);
			}
		}

		public void ClearTile(int x, int y)
		{
			SetTile(x, y, -1);
		}

		public void SetRawTile(int x, int y, int rawTile)
		{
			SetRawTileValue(x, y, rawTile);
		}

		private void CreateChunk(SpriteChunk chunk)
		{
			if (chunk.spriteIds == null || chunk.spriteIds.Length == 0)
			{
				chunk.spriteIds = new int[divX * divY];
				for (int i = 0; i < divX * divY; i++)
				{
					chunk.spriteIds[i] = -1;
				}
			}
		}

		private void Optimize(SpriteChunk chunk)
		{
			bool flag = true;
			int[] spriteIds = chunk.spriteIds;
			for (int i = 0; i < spriteIds.Length; i++)
			{
				if (spriteIds[i] != -1)
				{
					flag = false;
					break;
				}
			}
			if (flag)
			{
				chunk.spriteIds = new int[0];
			}
		}

		public void Optimize()
		{
			SpriteChunk[] chunks = spriteChannel.chunks;
			foreach (SpriteChunk chunk in chunks)
			{
				Optimize(chunk);
			}
		}

		public void OptimizeIncremental()
		{
			SpriteChunk[] chunks = spriteChannel.chunks;
			foreach (SpriteChunk spriteChunk in chunks)
			{
				if (spriteChunk.Dirty)
				{
					Optimize(spriteChunk);
				}
			}
		}

		public void ClearDirtyFlag()
		{
			SpriteChunk[] chunks = spriteChannel.chunks;
			for (int i = 0; i < chunks.Length; i++)
			{
				chunks[i].Dirty = false;
			}
		}
	}
	public static class ColliderBuilder3D
	{
		public static void Build(tk2dTileMap tileMap, bool forceBuild)
		{
			bool flag = !forceBuild;
			int num = tileMap.Layers.Length;
			for (int i = 0; i < num; i++)
			{
				Layer layer = tileMap.Layers[i];
				if (layer.IsEmpty || !tileMap.data.Layers[i].generateCollider)
				{
					continue;
				}
				for (int j = 0; j < layer.numRows; j++)
				{
					int baseY = j * layer.divY;
					for (int k = 0; k < layer.numColumns; k++)
					{
						int baseX = k * layer.divX;
						SpriteChunk chunk = layer.GetChunk(k, j);
						if ((!flag || chunk.Dirty) && !chunk.IsEmpty)
						{
							BuildForChunk(tileMap, chunk, baseX, baseY);
							PhysicMaterial physicMaterial = tileMap.data.Layers[i].physicMaterial;
							if (chunk.meshCollider != null)
							{
								chunk.meshCollider.sharedMaterial = physicMaterial;
							}
						}
					}
				}
			}
		}

		public static void BuildForChunk(tk2dTileMap tileMap, SpriteChunk chunk, int baseX, int baseY)
		{
			Vector3[] vertices = new Vector3[0];
			int[] indices = new int[0];
			BuildLocalMeshForChunk(tileMap, chunk, baseX, baseY, ref vertices, ref indices);
			if (indices.Length > 6)
			{
				vertices = WeldVertices(vertices, ref indices);
				indices = RemoveDuplicateFaces(indices);
			}
			foreach (EdgeCollider2D edgeCollider in chunk.edgeColliders)
			{
				if (edgeCollider != null)
				{
					tk2dUtil.DestroyImmediate(edgeCollider);
				}
			}
			chunk.edgeColliders.Clear();
			if (vertices.Length != 0)
			{
				if (chunk.colliderMesh != null)
				{
					tk2dUtil.DestroyImmediate(chunk.colliderMesh);
					chunk.colliderMesh = null;
				}
				if (chunk.meshCollider == null)
				{
					chunk.meshCollider = chunk.gameObject.GetComponent<MeshCollider>();
					if (chunk.meshCollider == null)
					{
						chunk.meshCollider = tk2dUtil.AddComponent<MeshCollider>(chunk.gameObject);
					}
				}
				chunk.colliderMesh = tk2dUtil.CreateMesh();
				chunk.colliderMesh.vertices = vertices;
				chunk.colliderMesh.triangles = indices;
				chunk.colliderMesh.RecalculateBounds();
				chunk.meshCollider.sharedMesh = chunk.colliderMesh;
			}
			else
			{
				chunk.DestroyColliderData(tileMap);
			}
		}

		private static void BuildLocalMeshForChunk(tk2dTileMap tileMap, SpriteChunk chunk, int baseX, int baseY, ref Vector3[] vertices, ref int[] indices)
		{
			List<Vector3> list = new List<Vector3>();
			List<int> list2 = new List<int>();
			int num = tileMap.SpriteCollectionInst.spriteDefinitions.Length;
			Vector3 tileSize = tileMap.data.tileSize;
			GameObject[] tilePrefabs = tileMap.data.tilePrefabs;
			float x = 0f;
			float y = 0f;
			tileMap.data.GetTileOffset(out x, out y);
			int[] spriteIds = chunk.spriteIds;
			for (int i = 0; i < tileMap.partitionSizeY; i++)
			{
				float num2 = (float)((baseY + i) & 1) * x;
				for (int j = 0; j < tileMap.partitionSizeX; j++)
				{
					int rawTile = spriteIds[i * tileMap.partitionSizeX + j];
					int tileFromRawTile = BuilderUtil.GetTileFromRawTile(rawTile);
					Vector3 vector = new Vector3(tileSize.x * ((float)j + num2), tileSize.y * (float)i, 0f);
					if (tileFromRawTile < 0 || tileFromRawTile >= num || (bool)tilePrefabs[tileFromRawTile])
					{
						continue;
					}
					bool flag = BuilderUtil.IsRawTileFlagSet(rawTile, tk2dTileFlags.FlipX);
					bool flag2 = BuilderUtil.IsRawTileFlagSet(rawTile, tk2dTileFlags.FlipY);
					bool rot = BuilderUtil.IsRawTileFlagSet(rawTile, tk2dTileFlags.Rot90);
					bool flag3 = false;
					if (flag)
					{
						flag3 = !flag3;
					}
					if (flag2)
					{
						flag3 = !flag3;
					}
					tk2dSpriteDefinition tk2dSpriteDefinition2 = tileMap.SpriteCollectionInst.spriteDefinitions[tileFromRawTile];
					int count = list.Count;
					if (tk2dSpriteDefinition2.colliderType == tk2dSpriteDefinition.ColliderType.Box)
					{
						Vector3 vector2 = tk2dSpriteDefinition2.colliderVertices[0];
						Vector3 vector3 = tk2dSpriteDefinition2.colliderVertices[1];
						Vector3 vector4 = vector2 - vector3;
						Vector3 vector5 = vector2 + vector3;
						Vector3[] array = new Vector3[8]
						{
							new Vector3(vector4.x, vector4.y, vector4.z),
							new Vector3(vector4.x, vector4.y, vector5.z),
							new Vector3(vector5.x, vector4.y, vector4.z),
							new Vector3(vector5.x, vector4.y, vector5.z),
							new Vector3(vector4.x, vector5.y, vector4.z),
							new Vector3(vector4.x, vector5.y, vector5.z),
							new Vector3(vector5.x, vector5.y, vector4.z),
							new Vector3(vector5.x, vector5.y, vector5.z)
						};
						for (int k = 0; k < 8; k++)
						{
							Vector3 vector6 = BuilderUtil.ApplySpriteVertexTileFlags(tileMap, tk2dSpriteDefinition2, array[k], flag, flag2, rot);
							list.Add(vector6 + vector);
						}
						int[] array2 = new int[24]
						{
							2, 1, 0, 3, 1, 2, 4, 5, 6, 6,
							5, 7, 6, 7, 3, 6, 3, 2, 1, 5,
							4, 0, 1, 4
						};
						for (int l = 0; l < array2.Length; l++)
						{
							int num3 = (flag3 ? (array2.Length - 1 - l) : l);
							list2.Add(count + array2[num3]);
						}
					}
					else if (tk2dSpriteDefinition2.colliderType == tk2dSpriteDefinition.ColliderType.Mesh)
					{
						for (int m = 0; m < tk2dSpriteDefinition2.colliderVertices.Length; m++)
						{
							Vector3 vector7 = BuilderUtil.ApplySpriteVertexTileFlags(tileMap, tk2dSpriteDefinition2, tk2dSpriteDefinition2.colliderVertices[m], flag, flag2, rot);
							list.Add(vector7 + vector);
						}
						int[] colliderIndicesFwd = tk2dSpriteDefinition2.colliderIndicesFwd;
						for (int n = 0; n < colliderIndicesFwd.Length; n++)
						{
							int num4 = (flag3 ? (colliderIndicesFwd.Length - 1 - n) : n);
							list2.Add(count + colliderIndicesFwd[num4]);
						}
					}
				}
			}
			vertices = list.ToArray();
			indices = list2.ToArray();
		}

		private static int CompareWeldVertices(Vector3 a, Vector3 b)
		{
			float num = 0.01f;
			float f = a.x - b.x;
			if (Mathf.Abs(f) > num)
			{
				return (int)Mathf.Sign(f);
			}
			float f2 = a.y - b.y;
			if (Mathf.Abs(f2) > num)
			{
				return (int)Mathf.Sign(f2);
			}
			float f3 = a.z - b.z;
			if (Mathf.Abs(f3) > num)
			{
				return (int)Mathf.Sign(f3);
			}
			return 0;
		}

		private static Vector3[] WeldVertices(Vector3[] vertices, ref int[] indices)
		{
			int[] array = new int[vertices.Length];
			for (int i = 0; i < vertices.Length; i++)
			{
				array[i] = i;
			}
			Array.Sort(array, (int a, int b) => CompareWeldVertices(vertices[a], vertices[b]));
			List<Vector3> list = new List<Vector3>();
			int[] array2 = new int[vertices.Length];
			Vector3 vector = vertices[array[0]];
			list.Add(vector);
			array2[array[0]] = list.Count - 1;
			for (int num = 1; num < array.Length; num++)
			{
				Vector3 vector2 = vertices[array[num]];
				if (CompareWeldVertices(vector2, vector) != 0)
				{
					vector = vector2;
					list.Add(vector);
					array2[array[num]] = list.Count - 1;
				}
				array2[array[num]] = list.Count - 1;
			}
			for (int num2 = 0; num2 < indices.Length; num2++)
			{
				indices[num2] = array2[indices[num2]];
			}
			return list.ToArray();
		}

		private static int CompareDuplicateFaces(int[] indices, int face0index, int face1index)
		{
			for (int i = 0; i < 3; i++)
			{
				int num = indices[face0index + i] - indices[face1index + i];
				if (num != 0)
				{
					return num;
				}
			}
			return 0;
		}

		private static int[] RemoveDuplicateFaces(int[] indices)
		{
			int[] sortedFaceIndices = new int[indices.Length];
			for (int i = 0; i < indices.Length; i += 3)
			{
				int[] array = new int[3]
				{
					indices[i],
					indices[i + 1],
					indices[i + 2]
				};
				Array.Sort(array);
				sortedFaceIndices[i] = array[0];
				sortedFaceIndices[i + 1] = array[1];
				sortedFaceIndices[i + 2] = array[2];
			}
			int[] array2 = new int[indices.Length / 3];
			for (int j = 0; j < indices.Length; j += 3)
			{
				array2[j / 3] = j;
			}
			Array.Sort(array2, (int a, int b) => CompareDuplicateFaces(sortedFaceIndices, a, b));
			List<int> list = new List<int>();
			for (int num = 0; num < array2.Length; num++)
			{
				if (num != array2.Length - 1 && CompareDuplicateFaces(sortedFaceIndices, array2[num], array2[num + 1]) == 0)
				{
					num++;
					continue;
				}
				for (int num2 = 0; num2 < 3; num2++)
				{
					list.Add(indices[array2[num] + num2]);
				}
			}
			return list.ToArray();
		}
	}
	public static class ColliderBuilder2D
	{
		public static void Build(tk2dTileMap tileMap, bool forceBuild)
		{
			bool flag = !forceBuild;
			int num = tileMap.Layers.Length;
			for (int i = 0; i < num; i++)
			{
				Layer layer = tileMap.Layers[i];
				if (layer.IsEmpty || !tileMap.data.Layers[i].generateCollider)
				{
					continue;
				}
				for (int j = 0; j < layer.numRows; j++)
				{
					int baseY = j * layer.divY;
					for (int k = 0; k < layer.numColumns; k++)
					{
						int baseX = k * layer.divX;
						SpriteChunk chunk = layer.GetChunk(k, j);
						if ((flag && !chunk.Dirty) || chunk.IsEmpty)
						{
							continue;
						}
						BuildForChunk(tileMap, chunk, baseX, baseY);
						PhysicsMaterial2D physicsMaterial2D = tileMap.data.Layers[i].physicsMaterial2D;
						foreach (EdgeCollider2D edgeCollider in chunk.edgeColliders)
						{
							if (edgeCollider != null)
							{
								edgeCollider.sharedMaterial = physicsMaterial2D;
							}
						}
					}
				}
			}
		}

		public static void BuildForChunk(tk2dTileMap tileMap, SpriteChunk chunk, int baseX, int baseY)
		{
			Vector2[] vertices = new Vector2[0];
			int[] indices = new int[0];
			List<Vector2[]> list = new List<Vector2[]>();
			BuildLocalMeshForChunk(tileMap, chunk, baseX, baseY, ref vertices, ref indices);
			if (indices.Length > 4)
			{
				vertices = WeldVertices(vertices, ref indices);
				indices = RemoveDuplicateEdges(indices);
			}
			list = MergeEdges(vertices, indices);
			if (chunk.meshCollider != null)
			{
				tk2dUtil.DestroyImmediate(chunk.meshCollider);
				chunk.meshCollider = null;
			}
			if (list.Count == 0)
			{
				for (int i = 0; i < chunk.edgeColliders.Count; i++)
				{
					if (chunk.edgeColliders[i] != null)
					{
						tk2dUtil.DestroyImmediate(chunk.edgeColliders[i]);
					}
				}
				chunk.edgeColliders.Clear();
				return;
			}
			int count = list.Count;
			for (int j = count; j < chunk.edgeColliders.Count; j++)
			{
				if (chunk.edgeColliders[j] != null)
				{
					tk2dUtil.DestroyImmediate(chunk.edgeColliders[j]);
				}
			}
			int num = chunk.edgeColliders.Count - count;
			if (num > 0)
			{
				chunk.edgeColliders.RemoveRange(chunk.edgeColliders.Count - num, num);
			}
			for (int k = 0; k < chunk.edgeColliders.Count; k++)
			{
				if (chunk.edgeColliders[k] == null)
				{
					chunk.edgeColliders[k] = tk2dUtil.AddComponent<EdgeCollider2D>(chunk.gameObject);
				}
			}
			while (chunk.edgeColliders.Count < count)
			{
				chunk.edgeColliders.Add(tk2dUtil.AddComponent<EdgeCollider2D>(chunk.gameObject));
			}
			for (int l = 0; l < count; l++)
			{
				chunk.edgeColliders[l].points = list[l];
			}
		}

		private static void BuildLocalMeshForChunk(tk2dTileMap tileMap, SpriteChunk chunk, int baseX, int baseY, ref Vector2[] vertices, ref int[] indices)
		{
			List<Vector2> list = new List<Vector2>();
			List<int> list2 = new List<int>();
			Vector2[] array = new Vector2[4];
			int[] array2 = new int[8] { 0, 1, 1, 2, 2, 3, 3, 0 };
			int[] array3 = new int[8] { 0, 3, 3, 2, 2, 1, 1, 0 };
			int num = tileMap.SpriteCollectionInst.spriteDefinitions.Length;
			Vector2 vector = new Vector3(tileMap.data.tileSize.x, tileMap.data.tileSize.y);
			GameObject[] tilePrefabs = tileMap.data.tilePrefabs;
			float x = 0f;
			float y = 0f;
			tileMap.data.GetTileOffset(out x, out y);
			int[] spriteIds = chunk.spriteIds;
			for (int i = 0; i < tileMap.partitionSizeY; i++)
			{
				float num2 = (float)((baseY + i) & 1) * x;
				for (int j = 0; j < tileMap.partitionSizeX; j++)
				{
					int rawTile = spriteIds[i * tileMap.partitionSizeX + j];
					int tileFromRawTile = BuilderUtil.GetTileFromRawTile(rawTile);
					Vector2 vector2 = new Vector2(vector.x * ((float)j + num2), vector.y * (float)i);
					if (tileFromRawTile < 0 || tileFromRawTile >= num || (bool)tilePrefabs[tileFromRawTile])
					{
						continue;
					}
					bool flag = BuilderUtil.IsRawTileFlagSet(rawTile, tk2dTileFlags.FlipX);
					bool flag2 = BuilderUtil.IsRawTileFlagSet(rawTile, tk2dTileFlags.FlipY);
					bool rot = BuilderUtil.IsRawTileFlagSet(rawTile, tk2dTileFlags.Rot90);
					bool flag3 = false;
					if (flag)
					{
						flag3 = !flag3;
					}
					if (flag2)
					{
						flag3 = !flag3;
					}
					tk2dSpriteDefinition tk2dSpriteDefinition2 = tileMap.SpriteCollectionInst.spriteDefinitions[tileFromRawTile];
					int count = list.Count;
					if (tk2dSpriteDefinition2.colliderType == tk2dSpriteDefinition.ColliderType.Box)
					{
						Vector3 vector3 = tk2dSpriteDefinition2.colliderVertices[0];
						Vector3 vector4 = tk2dSpriteDefinition2.colliderVertices[1];
						Vector3 vector5 = vector3 - vector4;
						Vector3 vector6 = vector3 + vector4;
						array[0] = new Vector2(vector5.x, vector5.y);
						array[1] = new Vector2(vector6.x, vector5.y);
						array[2] = new Vector2(vector6.x, vector6.y);
						array[3] = new Vector2(vector5.x, vector6.y);
						for (int k = 0; k < 4; k++)
						{
							list.Add(BuilderUtil.ApplySpriteVertexTileFlags(tileMap, tk2dSpriteDefinition2, array[k], flag, flag2, rot) + vector2);
						}
						int[] array4 = (flag3 ? array3 : array2);
						for (int l = 0; l < 8; l++)
						{
							list2.Add(count + array4[l]);
						}
					}
					else
					{
						if (tk2dSpriteDefinition2.colliderType != tk2dSpriteDefinition.ColliderType.Mesh)
						{
							continue;
						}
						tk2dCollider2DData[] edgeCollider2D = tk2dSpriteDefinition2.edgeCollider2D;
						foreach (tk2dCollider2DData tk2dCollider2DData2 in edgeCollider2D)
						{
							count = list.Count;
							Vector2[] points = tk2dCollider2DData2.points;
							foreach (Vector2 pos in points)
							{
								list.Add(BuilderUtil.ApplySpriteVertexTileFlags(tileMap, tk2dSpriteDefinition2, pos, flag, flag2, rot) + vector2);
							}
							int num3 = tk2dCollider2DData2.points.Length;
							if (flag3)
							{
								for (int num4 = num3 - 1; num4 > 0; num4--)
								{
									list2.Add(count + num4);
									list2.Add(count + num4 - 1);
								}
							}
							else
							{
								for (int num5 = 0; num5 < num3 - 1; num5++)
								{
									list2.Add(count + num5);
									list2.Add(count + num5 + 1);
								}
							}
						}
						edgeCollider2D = tk2dSpriteDefinition2.polygonCollider2D;
						foreach (tk2dCollider2DData tk2dCollider2DData3 in edgeCollider2D)
						{
							count = list.Count;
							Vector2[] points = tk2dCollider2DData3.points;
							foreach (Vector2 pos2 in points)
							{
								list.Add(BuilderUtil.ApplySpriteVertexTileFlags(tileMap, tk2dSpriteDefinition2, pos2, flag, flag2, rot) + vector2);
							}
							int num6 = tk2dCollider2DData3.points.Length;
							if (flag3)
							{
								for (int num7 = num6; num7 > 0; num7--)
								{
									list2.Add(count + num7 % num6);
									list2.Add(count + num7 - 1);
								}
							}
							else
							{
								for (int num8 = 0; num8 < num6; num8++)
								{
									list2.Add(count + num8);
									list2.Add(count + (num8 + 1) % num6);
								}
							}
						}
					}
				}
			}
			vertices = list.ToArray();
			indices = list2.ToArray();
		}

		private static int CompareWeldVertices(Vector2 a, Vector2 b)
		{
			float num = 0.01f;
			float f = a.x - b.x;
			if (Mathf.Abs(f) > num)
			{
				return (int)Mathf.Sign(f);
			}
			float f2 = a.y - b.y;
			if (Mathf.Abs(f2) > num)
			{
				return (int)Mathf.Sign(f2);
			}
			return 0;
		}

		private static Vector2[] WeldVertices(Vector2[] vertices, ref int[] indices)
		{
			int[] array = new int[vertices.Length];
			for (int i = 0; i < vertices.Length; i++)
			{
				array[i] = i;
			}
			Array.Sort(array, (int a, int b) => CompareWeldVertices(vertices[a], vertices[b]));
			List<Vector2> list = new List<Vector2>();
			int[] array2 = new int[vertices.Length];
			Vector2 vector = vertices[array[0]];
			list.Add(vector);
			array2[array[0]] = list.Count - 1;
			for (int num = 1; num < array.Length; num++)
			{
				Vector2 vector2 = vertices[array[num]];
				if (CompareWeldVertices(vector2, vector) != 0)
				{
					vector = vector2;
					list.Add(vector);
					array2[array[num]] = list.Count - 1;
				}
				array2[array[num]] = list.Count - 1;
			}
			for (int num2 = 0; num2 < indices.Length; num2++)
			{
				indices[num2] = array2[indices[num2]];
			}
			return list.ToArray();
		}

		private static int CompareDuplicateFaces(int[] indices, int face0index, int face1index)
		{
			for (int i = 0; i < 2; i++)
			{
				int num = indices[face0index + i] - indices[face1index + i];
				if (num != 0)
				{
					return num;
				}
			}
			return 0;
		}

		private static int[] RemoveDuplicateEdges(int[] indices)
		{
			int[] sortedFaceIndices = new int[indices.Length];
			for (int i = 0; i < indices.Length; i += 2)
			{
				if (indices[i] > indices[i + 1])
				{
					sortedFaceIndices[i] = indices[i + 1];
					sortedFaceIndices[i + 1] = indices[i];
				}
				else
				{
					sortedFaceIndices[i] = indices[i];
					sortedFaceIndices[i + 1] = indices[i + 1];
				}
			}
			int[] array = new int[indices.Length / 2];
			for (int j = 0; j < indices.Length; j += 2)
			{
				array[j / 2] = j;
			}
			Array.Sort(array, (int a, int b) => CompareDuplicateFaces(sortedFaceIndices, a, b));
			List<int> list = new List<int>();
			for (int num = 0; num < array.Length; num++)
			{
				if (num != array.Length - 1 && CompareDuplicateFaces(sortedFaceIndices, array[num], array[num + 1]) == 0)
				{
					num++;
					continue;
				}
				for (int num2 = 0; num2 < 2; num2++)
				{
					list.Add(indices[array[num] + num2]);
				}
			}
			return list.ToArray();
		}

		private static List<Vector2[]> MergeEdges(Vector2[] verts, int[] indices)
		{
			List<Vector2[]> list = new List<Vector2[]>();
			List<Vector2> list2 = new List<Vector2>();
			List<int> list3 = new List<int>();
			Vector2 zero = Vector2.zero;
			_ = Vector2.zero;
			bool[] array = new bool[indices.Length / 2];
			bool flag = true;
			while (flag)
			{
				flag = false;
				for (int i = 0; i < array.Length; i++)
				{
					if (array[i])
					{
						continue;
					}
					array[i] = true;
					int num = indices[i * 2];
					int num2 = indices[i * 2 + 1];
					zero = (verts[num2] - verts[num]).normalized;
					list3.Add(num);
					list3.Add(num2);
					for (int j = i + 1; j < array.Length; j++)
					{
						if (array[j])
						{
							continue;
						}
						int num3 = indices[j * 2];
						if (num3 == num2)
						{
							int num4 = indices[j * 2 + 1];
							Vector2 normalized = (verts[num4] - verts[num3]).normalized;
							if (Vector2.Dot(normalized, zero) > 0.999f)
							{
								list3.RemoveAt(list3.Count - 1);
							}
							list3.Add(num4);
							array[j] = true;
							zero = normalized;
							j = i;
							num2 = num4;
						}
					}
					flag = true;
					break;
				}
				if (flag)
				{
					list2.Clear();
					list2.Capacity = Mathf.Max(list2.Capacity, list3.Count);
					for (int k = 0; k < list3.Count; k++)
					{
						list2.Add(verts[list3[k]]);
					}
					list.Add(list2.ToArray());
					list3.Clear();
				}
			}
			return list;
		}
	}
