namespace SecPlayerPrefs
{
	public class SecureDataManager<T> where T : new()
	{
		private T stats;

		private string key;

		public SecureDataManager(string filename)
		{
			key = filename;
			stats = Load();
		}

		public T Get()
		{
			return stats;
		}

		private T Load()
		{
			if (!SecurePlayerPrefs.HasKey(key))
			{
				return new T();
			}
			string pXmlizedString = SecurePlayerPrefs.GetString(key);
			return DeserializeObject(pXmlizedString);
		}

		public void Save(T stats)
		{
			string value = SerializeObject(stats);
			SecurePlayerPrefs.SetString(key, value);
			SecurePlayerPrefs.Save();
		}

		private string SerializeObject(T pObject)
		{
			MemoryStream w = new MemoryStream();
			XmlSerializer xmlSerializer = new XmlSerializer(typeof(T));
			XmlTextWriter xmlTextWriter = new XmlTextWriter(w, Encoding.UTF8);
			xmlSerializer.Serialize(xmlTextWriter, pObject);
			return UTF8ByteArrayToString(((MemoryStream)xmlTextWriter.BaseStream).ToArray());
		}

		private T DeserializeObject(string pXmlizedString)
		{
			XmlSerializer xmlSerializer = new XmlSerializer(typeof(T));
			MemoryStream memoryStream = new MemoryStream(StringToUTF8ByteArray(pXmlizedString));
			new XmlTextWriter(memoryStream, Encoding.UTF8);
			return (T)xmlSerializer.Deserialize(memoryStream);
		}

		private static string UTF8ByteArrayToString(byte[] characters)
		{
			return new UTF8Encoding().GetString(characters);
		}

		private static byte[] StringToUTF8ByteArray(string pXmlString)
		{
			return new UTF8Encoding().GetBytes(pXmlString);
		}
	}
	public class SecurePlayerPrefs : ScriptableObject
	{
		private static readonly byte[] Salt = new byte[17]
		{
			10, 20, 30, 40, 50, 60, 70, 80, 90, 12,
			13, 14, 15, 16, 17, 18, 19
		};

		private static byte[] keyArray = Encoding.UTF8.GetBytes("UKu52ePUBwetZ9wNX88o54dnfKRu0T1l");

		private static string Encrypt(string toEncrypt)
		{
			byte[] bytes = Encoding.UTF8.GetBytes(toEncrypt);
			byte[] array = new RijndaelManaged
			{
				Key = keyArray,
				Mode = CipherMode.ECB,
				Padding = PaddingMode.PKCS7
			}.CreateEncryptor().TransformFinalBlock(bytes, 0, bytes.Length);
			return Convert.ToBase64String(array, 0, array.Length);
		}

		private static string Decrypt(string toDecrypt)
		{
			byte[] array = Convert.FromBase64String(toDecrypt);
			byte[] bytes = new RijndaelManaged
			{
				Key = keyArray,
				Mode = CipherMode.ECB,
				Padding = PaddingMode.PKCS7
			}.CreateDecryptor().TransformFinalBlock(array, 0, array.Length);
			return Encoding.UTF8.GetString(bytes);
		}

		private static string UTF8ByteArrayToString(byte[] characters)
		{
			return new UTF8Encoding().GetString(characters);
		}

		private static byte[] StringToUTF8ByteArray(string pXmlString)
		{
			return new UTF8Encoding().GetBytes(pXmlString);
		}

		public static void SetInt(string Key, int Value)
		{
			PlayerPrefs.SetString(Encrypt(Key), Encrypt(Value.ToString()));
		}

		public static void SetString(string Key, string Value)
		{
			PlayerPrefs.SetString(Encrypt(Key), Encrypt(Value));
		}

		public static void SetFloat(string Key, float Value)
		{
			PlayerPrefs.SetString(Encrypt(Key), Encrypt(Value.ToString()));
		}

		public static void SetBool(string Key, bool Value)
		{
			PlayerPrefs.SetString(Encrypt(Key), Encrypt(Value.ToString()));
		}

		public static string GetString(string Key)
		{
			string text = PlayerPrefs.GetString(Encrypt(Key));
			if (text == "")
			{
				return "";
			}
			return Decrypt(text);
		}

		public static int GetInt(string Key)
		{
			string text = PlayerPrefs.GetString(Encrypt(Key));
			if (text == "")
			{
				return 0;
			}
			return int.Parse(Decrypt(text));
		}

		public static float GetFloat(string Key)
		{
			string text = PlayerPrefs.GetString(Encrypt(Key));
			if (text == "")
			{
				return 0f;
			}
			return float.Parse(Decrypt(text));
		}

		public static bool GetBool(string Key)
		{
			string text = PlayerPrefs.GetString(Encrypt(Key));
			if (text == "")
			{
				return false;
			}
			return bool.Parse(Decrypt(text));
		}

		public static void DeleteKey(string Key)
		{
			PlayerPrefs.DeleteKey(Encrypt(Key));
		}

		public static void DeleteAll()
		{
			PlayerPrefs.DeleteAll();
		}

		public static void Save()
		{
			PlayerPrefs.Save();
		}

		public static bool HasKey(string Key)
		{
			return PlayerPrefs.HasKey(Encrypt(Key));
		}
	}
}
