	public class ClearSaveButton : MenuButton, ISubmitHandler, IEventSystemHandler, IPointerClickHandler, ISelectHandler
	{
		public SaveSlotButton saveSlotButton;

		public new void OnSubmit(BaseEventData eventData)
		{
			ForceDeselect();
			saveSlotButton.ClearSavePrompt();
		}

		public new void OnPointerClick(PointerEventData eventData)
		{
			OnSubmit(eventData);
		}

		public new void OnSelect(BaseEventData eventData)
		{
			base.OnSelect(eventData);
			if (!GetComponent<CanvasGroup>().interactable)
			{
				StartCoroutine(SelectAfterFrame(base.navigation.selectOnLeft.gameObject));
			}
		}

		private IEnumerator SelectAfterFrame(GameObject gameObject)
		{
			yield return new WaitForEndOfFrame();
			EventSystem.current.SetSelectedGameObject(gameObject);
		}
	}
	public class ControllerProfileButton : MonoBehaviour, ISelectHandler, IEventSystemHandler, IDeselectHandler, ISubmitHandler, IPointerClickHandler
	{
		public Animator leftCursor;

		public Animator rightCursor;

		public Image highlightCursor;

		public MenuAudioController uiAudioPlayer;

		private GameObject prevSelectedObject;

		private bool dontPlaySelectSound;

		public void OnSelect(BaseEventData eventData)
		{
			leftCursor.ResetTrigger("hide");
			rightCursor.ResetTrigger("hide");
			leftCursor.SetTrigger("show");
			rightCursor.SetTrigger("show");
			if (!dontPlaySelectSound)
			{
				uiAudioPlayer.PlaySelect();
			}
			else
			{
				dontPlaySelectSound = false;
			}
		}

		public void OnDeselect(BaseEventData eventData)
		{
			StartCoroutine(ValidateDeselect());
		}

		public void OnSubmit(BaseEventData eventData)
		{
			highlightCursor.gameObject.SetActive(value: true);
		}

		public void OnPointerClick(PointerEventData eventData)
		{
			OnSubmit(eventData);
		}

		private IEnumerator ValidateDeselect()
		{
			prevSelectedObject = EventSystem.current.currentSelectedGameObject;
			yield return new WaitForEndOfFrame();
			if (EventSystem.current.currentSelectedGameObject != null)
			{
				leftCursor.ResetTrigger("show");
				rightCursor.ResetTrigger("show");
				leftCursor.SetTrigger("hide");
				rightCursor.SetTrigger("hide");
			}
			else
			{
				dontPlaySelectSound = true;
				EventSystem.current.SetSelectedGameObject(prevSelectedObject);
			}
		}
	}
	public class ControllerProfileButtons : MonoBehaviour
	{
		public Image profileHighlight1;

		public Image profileHighlight2;

		public Image profileHighlight3;

		public Image profileHighlight4;

		public void SelectItem(int num)
		{
			switch (num)
			{
			case 1:
				profileHighlight1.gameObject.SetActive(value: true);
				profileHighlight2.gameObject.SetActive(value: false);
				profileHighlight3.gameObject.SetActive(value: false);
				profileHighlight4.gameObject.SetActive(value: false);
				break;
			case 2:
				profileHighlight1.gameObject.SetActive(value: false);
				profileHighlight2.gameObject.SetActive(value: true);
				profileHighlight3.gameObject.SetActive(value: false);
				profileHighlight4.gameObject.SetActive(value: false);
				break;
			case 3:
				profileHighlight1.gameObject.SetActive(value: false);
				profileHighlight2.gameObject.SetActive(value: false);
				profileHighlight3.gameObject.SetActive(value: true);
				profileHighlight4.gameObject.SetActive(value: false);
				break;
			case 4:
				profileHighlight1.gameObject.SetActive(value: false);
				profileHighlight2.gameObject.SetActive(value: false);
				profileHighlight3.gameObject.SetActive(value: false);
				profileHighlight4.gameObject.SetActive(value: true);
				break;
			default:
				Debug.LogError("Invalid profile button ID");
				break;
			}
		}
	}
	public class MenuButton : MenuSelectable, ISubmitHandler, IEventSystemHandler, IPointerClickHandler
	{
		public enum MenuButtonType
		{
			Proceed,
			Activate,
			CustomSubmit
		}

		public MenuButtonType buttonType;

		public Animator flashEffect;

		public Action<MenuButton> submitAction { get; set; }

		public bool proceed { get; set; }

		private new void Start()
		{
			HookUpAudioPlayer();
		}

		public void OnSubmit(BaseEventData eventData)
		{
			if (buttonType == MenuButtonType.CustomSubmit)
			{
				if ((bool)flashEffect)
				{
					flashEffect.ResetTrigger("Flash");
					flashEffect.SetTrigger("Flash");
				}
				if (proceed)
				{
					ForceDeselect();
				}
				submitAction?.Invoke(this);
			}
			orig_OnSubmit(eventData);
		}

		public void OnPointerClick(PointerEventData eventData)
		{
			OnSubmit(eventData);
		}

		public void orig_OnSubmit(BaseEventData eventData)
		{
			if (buttonType == MenuButtonType.Proceed)
			{
				try
				{
					flashEffect.ResetTrigger("Flash");
					flashEffect.SetTrigger("Flash");
				}
				catch
				{
				}
				ForceDeselect();
			}
			else if (buttonType == MenuButtonType.Activate)
			{
				try
				{
					flashEffect.ResetTrigger("Flash");
					flashEffect.SetTrigger("Flash");
				}
				catch
				{
				}
			}
			PlaySubmitSound();
		}
	}
	public class MenuDisplaySetting : MenuOptionHorizontal, IMoveHandler, IEventSystemHandler, IMenuOptionListSetting, IPointerClickHandler
	{
		private bool verboseMode;

		private Display[] availableDisplays;

		private bool dontMove;

		public new void OnEnable()
		{
			RefreshControls();
		}

		public new void OnMove(AxisEventData move)
		{
			if (MoveOption(move.moveDir))
			{
				UpdateMonitorSetting();
			}
			else
			{
				base.OnMove(move);
			}
		}

		public new void OnPointerClick(PointerEventData eventData)
		{
			PointerClickCheckArrows(eventData);
			UpdateMonitorSetting();
		}

		public void RefreshControls()
		{
			RefreshCurrentIndex();
			PushUpdateOptionList();
			UpdateText();
		}

		public void DisableMonitorSelectSetting()
		{
			SetOptionTo(0);
			UpdateMonitorSetting();
		}

		private void UpdateMonitorSetting()
		{
			Debug.Log("UpdateMonitorSetting...");
			StartCoroutine(TargetDisplayHack(selectedOptionIndex));
		}

		public void RefreshCurrentIndex()
		{
			availableDisplays = Display.displays;
			if (verboseMode)
			{
				Debug.LogFormat("Monitor Select: There are {0} displays available.", availableDisplays.Length);
			}
			bool flag = false;
			for (int i = 0; i < availableDisplays.Length; i++)
			{
				if (Display.main == availableDisplays[i])
				{
					selectedOptionIndex = i;
					flag = true;
				}
			}
			if (!flag)
			{
				Debug.LogError("Could not find currently active display");
			}
		}

		public void PushUpdateOptionList()
		{
			string[] array = new string[availableDisplays.Length];
			for (int i = 0; i < availableDisplays.Length; i++)
			{
				array[i] = (i + 1).ToString();
			}
			SetOptionList(array);
		}

		private IEnumerator TargetDisplayHack(int targetDisplay)
		{
			dontMove = true;
			int screenWidth = Screen.width;
			int screenHeight = Screen.height;
			PlayerPrefs.SetInt("UnitySelectMonitor", targetDisplay);
			Screen.SetResolution(800, 600, Screen.fullScreen);
			yield return null;
			Screen.SetResolution(screenWidth, screenHeight, Screen.fullScreen);
			dontMove = false;
		}
	}
	public class MenuFrameCapSetting : MenuOptionHorizontal, IMoveHandler, IEventSystemHandler, IMenuOptionListSetting, IPointerClickHandler
	{
		private int[] frameCapValues = new int[8] { -1, 30, 50, 60, 72, 100, 120, 144 };

		private int tfrOff = -1;

		private GameSettings gs;

		public FixVerticalAlign textAligner;

		public new void OnEnable()
		{
			RefreshControls();
		}

		public new void OnMove(AxisEventData move)
		{
			if (MoveOption(move.moveDir))
			{
				UpdateFrameCapSetting();
			}
			else
			{
				base.OnMove(move);
			}
		}

		public new void OnPointerClick(PointerEventData eventData)
		{
			PointerClickCheckArrows(eventData);
			UpdateFrameCapSetting();
		}

		public void RefreshControls()
		{
			RefreshCurrentIndex();
			PushUpdateOptionList();
			if (selectedOptionIndex == 0)
			{
				optionText.text = global::Language.Language.Get("MOH_OFF", "MainMenu");
				textAligner.AlignText();
			}
			else
			{
				UpdateText();
			}
		}

		public void DisableFrameCapSetting()
		{
			SetOptionTo(0);
			UpdateFrameCapSetting();
		}

		public void ApplyValueFromGameSettings()
		{
			Application.targetFrameRate = GameManager.instance.gameSettings.targetFrameRate;
			RefreshControls();
		}

		private void UpdateFrameCapSetting()
		{
			if (selectedOptionIndex == 0)
			{
				optionText.text = global::Language.Language.Get("MOH_OFF", "MainMenu");
				textAligner.AlignText();
			}
			else
			{
				UIManager.instance.DisableVsyncSetting();
			}
			GameManager.instance.gameSettings.targetFrameRate = frameCapValues[selectedOptionIndex];
			Application.targetFrameRate = frameCapValues[selectedOptionIndex];
		}

		public void RefreshCurrentIndex()
		{
			bool flag = false;
			for (int i = 0; i < frameCapValues.Length; i++)
			{
				if (Application.targetFrameRate == frameCapValues[i])
				{
					selectedOptionIndex = i;
					flag = true;
				}
			}
			if (!flag)
			{
				Debug.LogError("Couldn't match current Target Frame Rate setting - " + Application.targetFrameRate);
			}
		}

		public void PushUpdateOptionList()
		{
			string[] array = new string[frameCapValues.Length];
			for (int i = 0; i < frameCapValues.Length; i++)
			{
				array[i] = frameCapValues[i].ToString();
			}
			SetOptionList(array);
		}
	}
	public class MenuLanguageSetting : MenuOptionHorizontal, IMoveHandler, IEventSystemHandler, IMenuOptionListSetting, IPointerClickHandler
	{
		private SupportedLanguages[] langs;

		private GameSettings gs;

		public FixVerticalAlign textAligner;

		private new void OnEnable()
		{
			RefreshControls();
			UpdateAlpha();
		}

		public void UpdateAlpha()
		{
			CanvasGroup component = GetComponent<CanvasGroup>();
			if ((bool)component)
			{
				if (!base.interactable)
				{
					component.alpha = 0.5f;
				}
				else
				{
					component.alpha = 1f;
				}
			}
		}

		public new void OnMove(AxisEventData move)
		{
			if (base.interactable)
			{
				if (MoveOption(move.moveDir))
				{
					UpdateLanguageSetting();
				}
				else
				{
					base.OnMove(move);
				}
			}
		}

		public new void OnPointerClick(PointerEventData eventData)
		{
			if (base.interactable)
			{
				PointerClickCheckArrows(eventData);
				UpdateLanguageSetting();
			}
		}

		public static Rect RectTransformToScreenSpace(RectTransform transform)
		{
			Vector2 vector = Vector2.Scale(transform.rect.size, transform.lossyScale);
			return new Rect(transform.position.x, (float)Screen.height - transform.position.y, vector.x, vector.y);
		}

		public void RefreshControls()
		{
			RefreshAvailableLanguages();
			RefreshCurrentIndex();
			PushUpdateOptionList();
			UpdateText();
		}

		private void UpdateLanguageSetting()
		{
			GameManager.instance.gameSettings.gameLanguage = langs[selectedOptionIndex];
			global::Language.Language.SwitchLanguage((LanguageCode)langs[selectedOptionIndex]);
			gm.RefreshLocalization();
			UIManager.instance.RefreshAchievementsList();
			UpdateText();
		}

		private void RefreshAvailableLanguages()
		{
			if (GameManager.instance.gameConfig.hideLanguageOption)
			{
				langs = Enum.GetValues(typeof(TestingLanguages)) as SupportedLanguages[];
			}
			else
			{
				langs = Enum.GetValues(typeof(SupportedLanguages)) as SupportedLanguages[];
			}
		}

		public void RefreshCurrentIndex()
		{
			bool flag = false;
			string text = global::Language.Language.CurrentLanguage().ToString();
			for (int i = 0; i < langs.Length; i++)
			{
				if (text == langs[i].ToString())
				{
					selectedOptionIndex = i;
					flag = true;
				}
			}
			if (!flag)
			{
				Debug.LogError("Couldn't find currently active language");
			}
		}

		public void PushUpdateOptionList()
		{
			string[] array = new string[langs.Length];
			for (int i = 0; i < langs.Length; i++)
			{
				array[i] = langs[i].ToString();
			}
			SetOptionList(array);
		}

		protected override void UpdateText()
		{
			if (optionList != null && optionText != null)
			{
				try
				{
					optionText.text = global::Language.Language.Get("LANG_" + optionList[selectedOptionIndex].ToString(), sheetTitle);
				}
				catch (Exception ex)
				{
					Debug.LogError(optionText.text + " : " + optionList?.ToString() + " : " + selectedOptionIndex + " " + ex);
				}
				optionText.GetComponent<FixVerticalAlign>().AlignText();
			}
		}
	}
	public class MenuOptionHorizontal : MenuSelectable, IMoveHandler, IEventSystemHandler, IPointerEnterHandler, IPointerClickHandler
	{
		public enum ApplyOnType
		{
			Scroll,
			Submit
		}

		[Header("Option List Settings")]
		public Text optionText;

		public string[] optionList;

		public int selectedOptionIndex;

		public MenuSetting menuSetting;

		[Header("Interaction")]
		public ApplyOnType applySettingOn;

		[Header("Localization")]
		public bool localizeText;

		public string sheetTitle;

		protected GameManager gm;

		private new void Awake()
		{
			gm = GameManager.instance;
		}

		private new void OnEnable()
		{
			gm.RefreshLanguageText += UpdateText;
			UpdateText();
		}

		private new void OnDisable()
		{
			gm.RefreshLanguageText -= UpdateText;
		}

		public new void OnMove(AxisEventData move)
		{
			if (base.interactable && !MoveOption(move.moveDir))
			{
				base.OnMove(move);
			}
		}

		public void OnPointerClick(PointerEventData eventData)
		{
			if (base.interactable)
			{
				PointerClickCheckArrows(eventData);
			}
		}

		protected bool MoveOption(MoveDirection dir)
		{
			switch (dir)
			{
			case MoveDirection.Right:
				IncrementOption();
				break;
			case MoveDirection.Left:
				DecrementOption();
				break;
			default:
				return false;
			}
			if ((bool)uiAudioPlayer)
			{
				uiAudioPlayer.PlaySlider();
			}
			return true;
		}

		protected void PointerClickCheckArrows(PointerEventData eventData)
		{
			if ((bool)leftCursor && IsInside(leftCursor.gameObject, eventData))
			{
				MoveOption(MoveDirection.Left);
			}
			else if ((bool)rightCursor && IsInside(rightCursor.gameObject, eventData))
			{
				MoveOption(MoveDirection.Right);
			}
			else
			{
				MoveOption(MoveDirection.Right);
			}
		}

		private bool IsInside(GameObject obj, PointerEventData eventData)
		{
			RectTransform component = obj.GetComponent<RectTransform>();
			if ((bool)component && RectTransformUtility.RectangleContainsScreenPoint(component, eventData.position, Camera.main))
			{
				return true;
			}
			return false;
		}

		public void SetOptionList(string[] optionList)
		{
			this.optionList = optionList;
		}

		public string GetSelectedOptionText()
		{
			if (localizeText)
			{
				return global::Language.Language.Get(optionList[selectedOptionIndex].ToString(), sheetTitle);
			}
			return optionList[selectedOptionIndex].ToString();
		}

		public string GetSelectedOptionTextRaw()
		{
			return optionList[selectedOptionIndex].ToString();
		}

		public virtual void SetOptionTo(int optionNumber)
		{
			if (optionNumber >= 0 && optionNumber < optionList.Length)
			{
				selectedOptionIndex = optionNumber;
				UpdateText();
				return;
			}
			Debug.LogErrorFormat("{0} - Trying to select an option outside the list size (index: {1} listsize: {2})", base.name, optionNumber, optionList.Length);
		}

		protected virtual void UpdateText()
		{
			if (optionList == null || !(optionText != null))
			{
				return;
			}
			try
			{
				if (localizeText)
				{
					optionText.text = global::Language.Language.Get(optionList[selectedOptionIndex].ToString(), sheetTitle);
				}
				else
				{
					optionText.text = optionList[selectedOptionIndex].ToString();
				}
			}
			catch (Exception ex)
			{
				Debug.LogError(optionText.text + " : " + optionList?.ToString() + " : " + selectedOptionIndex + " " + ex);
			}
			optionText.GetComponent<FixVerticalAlign>().AlignText();
		}

		protected void UpdateSetting()
		{
			if ((bool)menuSetting)
			{
				menuSetting.UpdateSetting(selectedOptionIndex);
			}
		}

		protected void DecrementOption()
		{
			if (selectedOptionIndex > 0)
			{
				selectedOptionIndex--;
				if (applySettingOn == ApplyOnType.Scroll)
				{
					UpdateSetting();
				}
				UpdateText();
			}
			else if (selectedOptionIndex == 0)
			{
				selectedOptionIndex = optionList.Length - 1;
				if (applySettingOn == ApplyOnType.Scroll)
				{
					UpdateSetting();
				}
				UpdateText();
			}
		}

		protected void IncrementOption()
		{
			if (selectedOptionIndex >= 0 && selectedOptionIndex < optionList.Length - 1)
			{
				selectedOptionIndex++;
				if (applySettingOn == ApplyOnType.Scroll)
				{
					UpdateSetting();
				}
				UpdateText();
			}
			else if (selectedOptionIndex == optionList.Length - 1)
			{
				selectedOptionIndex = 0;
				if (applySettingOn == ApplyOnType.Scroll)
				{
					UpdateSetting();
				}
				UpdateText();
			}
		}
	}
	public class MenuPreventDeselect : MonoBehaviour, ISelectHandler, IEventSystemHandler, IDeselectHandler, ICancelHandler
	{
		[Header("On Cancel")]
		public CancelAction cancelAction;

		[Header("Fleurs")]
		public Animator leftCursor;

		public Animator rightCursor;

		private MenuAudioController uiAudioPlayer;

		private GameObject prevSelectedObject;

		private bool dontPlaySelectSound;

		private bool deselectWasForced;

		public Action<MenuPreventDeselect> customCancelAction { get; set; }

		private void Start()
		{
			HookUpAudioPlayer();
		}

		public void OnSelect(BaseEventData eventData)
		{
			if (leftCursor != null)
			{
				leftCursor.SetTrigger("show");
				leftCursor.ResetTrigger("hide");
			}
			if (rightCursor != null)
			{
				rightCursor.SetTrigger("show");
				rightCursor.ResetTrigger("hide");
			}
			if (!dontPlaySelectSound)
			{
				uiAudioPlayer.PlaySelect();
			}
			else
			{
				dontPlaySelectSound = false;
			}
		}

		public void OnDeselect(BaseEventData eventData)
		{
			StartCoroutine(ValidateDeselect());
		}

		public void OnCancel(BaseEventData eventData)
		{
			if (cancelAction == CancelAction.GoToExtrasMenu && customCancelAction != null)
			{
				ForceDeselect();
				customCancelAction(this);
				uiAudioPlayer.PlayCancel();
			}
			else
			{
				orig_OnCancel(eventData);
			}
		}

		private IEnumerator ValidateDeselect()
		{
			prevSelectedObject = EventSystem.current.currentSelectedGameObject;
			yield return new WaitForEndOfFrame();
			if (EventSystem.current.currentSelectedGameObject != null)
			{
				if (leftCursor != null)
				{
					leftCursor.ResetTrigger("show");
					leftCursor.SetTrigger("hide");
				}
				if (rightCursor != null)
				{
					rightCursor.ResetTrigger("show");
					rightCursor.SetTrigger("hide");
				}
				deselectWasForced = false;
			}
			else if (deselectWasForced)
			{
				if (leftCursor != null)
				{
					leftCursor.ResetTrigger("show");
					leftCursor.SetTrigger("hide");
				}
				if (rightCursor != null)
				{
					rightCursor.ResetTrigger("show");
					rightCursor.SetTrigger("hide");
				}
				deselectWasForced = false;
			}
			else
			{
				deselectWasForced = false;
				dontPlaySelectSound = true;
				EventSystem.current.SetSelectedGameObject(prevSelectedObject);
			}
		}

		protected void HookUpAudioPlayer()
		{
			uiAudioPlayer = UIManager.instance.uiAudioPlayer;
		}

		public void ForceDeselect()
		{
			if (EventSystem.current.currentSelectedGameObject != null)
			{
				deselectWasForced = true;
				EventSystem.current.SetSelectedGameObject(null);
			}
		}

		public void SimulateSubmit()
		{
			ForceDeselect();
			UIManager.instance.uiAudioPlayer.PlaySubmit();
		}

		public void orig_OnCancel(BaseEventData eventData)
		{
			bool flag = true;
			if (cancelAction != CancelAction.DoNothing)
			{
				ForceDeselect();
			}
			if (cancelAction == CancelAction.DoNothing)
			{
				flag = false;
			}
			else if (cancelAction == CancelAction.GoToMainMenu)
			{
				UIManager.instance.UIGoToMainMenu();
			}
			else if (cancelAction == CancelAction.GoToOptionsMenu)
			{
				UIManager.instance.UIGoToOptionsMenu();
			}
			else if (cancelAction == CancelAction.GoToVideoMenu)
			{
				UIManager.instance.UIGoToVideoMenu();
			}
			else if (cancelAction == CancelAction.GoToPauseMenu)
			{
				UIManager.instance.UIGoToPauseMenu();
			}
			else if (cancelAction == CancelAction.LeaveOptionsMenu)
			{
				UIManager.instance.UILeaveOptionsMenu();
			}
			else if (cancelAction == CancelAction.GoToExitPrompt)
			{
				UIManager.instance.UIShowQuitGamePrompt();
			}
			else if (cancelAction == CancelAction.GoToProfileMenu)
			{
				UIManager.instance.UIGoToProfileMenu();
			}
			else if (cancelAction == CancelAction.GoToControllerMenu)
			{
				UIManager.instance.UIGoToControllerMenu();
			}
			else if (cancelAction == CancelAction.ApplyRemapGamepadSettings)
			{
				UIManager.instance.ApplyRemapGamepadMenuSettings();
			}
			else if (cancelAction == CancelAction.ApplyAudioSettings)
			{
				UIManager.instance.ApplyAudioMenuSettings();
			}
			else if (cancelAction == CancelAction.ApplyVideoSettings)
			{
				UIManager.instance.ApplyVideoMenuSettings();
			}
			else if (cancelAction == CancelAction.ApplyGameSettings)
			{
				UIManager.instance.ApplyGameMenuSettings();
			}
			else if (cancelAction == CancelAction.ApplyKeyboardSettings)
			{
				UIManager.instance.ApplyKeyboardMenuSettings();
			}
			else if (cancelAction == CancelAction.ApplyControllerSettings)
			{
				UIManager.instance.ApplyControllerMenuSettings();
			}
			else if (cancelAction == CancelAction.GoToExplicitSwitchUser)
			{
				UIManager.instance.UIGoToEngageMenu();
			}
			else if (cancelAction == CancelAction.ReturnToProfileMenu)
			{
				UIManager.instance.UIReturnToProfileMenu();
			}
			else
			{
				Debug.LogError("CancelAction not implemented for this control");
				flag = false;
			}
			if (flag)
			{
				uiAudioPlayer.PlayCancel();
			}
		}
	}
	public class MenuResolutionSetting : MenuOptionHorizontal, ISubmitHandler, IEventSystemHandler, IMoveHandler, IPointerClickHandler, IMenuOptionListSetting
	{
		private Resolution[] availableResolutions;

		private Resolution previousRes;

		private bool foundResolutionInList;

		private int currentlyActiveResIndex = -1;

		private int previousResIndex;

		[Header("Resolution Setting Specific")]
		public CanvasGroup applyButton;

		public Resolution currentRes { get; private set; }

		public Resolution screenRes { get; private set; }

		public new void OnEnable()
		{
			RefreshControls();
			UpdateApplyButton();
		}

		public void OnSubmit(BaseEventData eventData)
		{
			if (currentlyActiveResIndex != selectedOptionIndex)
			{
				ForceDeselect();
				uiAudioPlayer.PlaySubmit();
				ApplySettings();
			}
		}

		public new void OnMove(AxisEventData move)
		{
			if (MoveOption(move.moveDir))
			{
				UpdateApplyButton();
			}
			else
			{
				base.OnMove(move);
			}
		}

		public new void OnPointerClick(PointerEventData eventData)
		{
			base.OnPointerClick(eventData);
			if (eventData.button == PointerEventData.InputButton.Left || eventData.button == PointerEventData.InputButton.Right)
			{
				UpdateApplyButton();
			}
		}

		public void ApplySettings()
		{
			if (selectedOptionIndex >= 0)
			{
				previousRes = currentRes;
				previousResIndex = currentlyActiveResIndex;
				Resolution resolution = availableResolutions[selectedOptionIndex];
				Screen.SetResolution(resolution.width, resolution.height, Screen.fullScreen, resolution.refreshRate);
				currentRes = resolution;
				currentlyActiveResIndex = selectedOptionIndex;
				HideApplyButton();
				UIManager.instance.UIShowResolutionPrompt(startTimer: true);
			}
		}

		public void UpdateApplyButton()
		{
			if (currentlyActiveResIndex == selectedOptionIndex)
			{
				HideApplyButton();
			}
			else
			{
				ShowApplyButton();
			}
		}

		public void ResetToDefaultResolution()
		{
			Screen.SetResolution(1920, 1080, Screen.fullScreen);
			currentRes = Screen.currentResolution;
			StartCoroutine(RefreshOnNextFrame());
		}

		public void RefreshControls()
		{
			RefreshAvailableResolutions();
			RefreshCurrentIndex();
			PushUpdateOptionList();
			UpdateText();
		}

		public void RollbackResolution()
		{
			Screen.SetResolution(previousRes.width, previousRes.height, Screen.fullScreen);
			currentRes = Screen.currentResolution;
			StartCoroutine(RefreshOnNextFrame());
		}

		public void RefreshCurrentIndex()
		{
			foundResolutionInList = false;
			for (int i = 0; i < availableResolutions.Length; i++)
			{
				if (currentRes.Equals(availableResolutions[i]))
				{
					selectedOptionIndex = i;
					currentlyActiveResIndex = i;
					foundResolutionInList = true;
					break;
				}
			}
			if (!foundResolutionInList)
			{
				Resolution[] array = new Resolution[availableResolutions.Length + 1];
				array[0] = currentRes;
				for (int j = 0; j < availableResolutions.Length; j++)
				{
					array[j + 1] = availableResolutions[j];
				}
				availableResolutions = array;
				selectedOptionIndex = 0;
				currentlyActiveResIndex = 0;
			}
		}

		public void PushUpdateOptionList()
		{
			string[] array = new string[availableResolutions.Length];
			for (int i = 0; i < availableResolutions.Length; i++)
			{
				array[i] = availableResolutions[i].ToString();
			}
			SetOptionList(array);
		}

		private void HideApplyButton()
		{
			applyButton.alpha = 0f;
			applyButton.interactable = false;
			applyButton.blocksRaycasts = false;
		}

		private void ShowApplyButton()
		{
			applyButton.alpha = 1f;
			applyButton.interactable = true;
			applyButton.blocksRaycasts = true;
		}

		private void RefreshAvailableResolutions()
		{
			screenRes = Screen.currentResolution;
			if (!Screen.fullScreen)
			{
				currentRes = new Resolution
				{
					width = Screen.width,
					height = Screen.height,
					refreshRate = screenRes.refreshRate
				};
			}
			else
			{
				currentRes = screenRes;
			}
			availableResolutions = Screen.resolutions;
		}

		private IEnumerator RefreshOnNextFrame()
		{
			yield return null;
			RefreshAvailableResolutions();
			RefreshCurrentIndex();
			PushUpdateOptionList();
			UpdateApplyButton();
			UpdateText();
		}
	}
	public class MenuScroller : UIBehaviour, IMoveHandler, IEventSystemHandler, ISelectHandler, IDeselectHandler, ISubmitHandler, IPointerClickHandler, ICancelHandler
	{
		public ScrollRect scrollRect;

		public Scrollbar scrollbar;

		public HollowKnightInputModule inputModule;

		public float scrollRate = 0.1f;

		public float scrollRepeatRate = 0.02f;

		public float scrollFirstDelay = 0.4f;

		private EventSystem eventSystem;

		private float prevRepeatRate;

		private float prevInitialDelay;

		public void OnSelect(BaseEventData eventData)
		{
			prevRepeatRate = inputModule.moveRepeatDelayDuration;
			prevInitialDelay = inputModule.moveRepeatFirstDuration;
			inputModule.moveRepeatDelayDuration = scrollRepeatRate;
			inputModule.moveRepeatFirstDuration = scrollFirstDelay;
		}

		public void OnDeselect(BaseEventData eventData)
		{
			inputModule.moveRepeatDelayDuration = prevRepeatRate;
			inputModule.moveRepeatFirstDuration = prevInitialDelay;
		}

		public void OnSubmit(BaseEventData eventData)
		{
			OnDeselect(eventData);
		}

		public void OnPointerClick(PointerEventData eventData)
		{
			OnDeselect(eventData);
		}

		public void OnCancel(BaseEventData eventData)
		{
			OnDeselect(eventData);
		}

		public void OnMove(AxisEventData move)
		{
			if (move.moveDir == MoveDirection.Up)
			{
				scrollbar.value += scrollRate;
			}
			else if (move.moveDir == MoveDirection.Down)
			{
				scrollbar.value -= scrollRate;
			}
		}
	}
	public class MenuSelectable : Selectable, ISelectHandler, IEventSystemHandler, IDeselectHandler, ICancelHandler, IPointerExitHandler
	{
		public delegate void OnSelectedEvent(MenuSelectable self);

		[Header("On Cancel")]
		public CancelAction cancelAction;

		[Header("Fleurs")]
		public Animator leftCursor;

		public Animator rightCursor;

		[Header("Highlight")]
		public Animator selectHighlight;

		public bool playSubmitSound = true;

		[Header("Description Text")]
		public Animator descriptionText;

		protected MenuAudioController uiAudioPlayer;

		protected GameObject prevSelectedObject;

		protected bool dontPlaySelectSound;

		protected bool deselectWasForced;

		private MenuButtonList parentList;

		public bool DontPlaySelectSound
		{
			get
			{
				return dontPlaySelectSound;
			}
			set
			{
				dontPlaySelectSound = value;
			}
		}

		public Action<MenuSelectable> customCancelAction { get; set; }

		public event OnSelectedEvent OnSelected;

		private new void Awake()
		{
			base.transition = Transition.None;
			if (base.navigation.mode != Navigation.Mode.Explicit)
			{
				base.navigation = new Navigation
				{
					mode = Navigation.Mode.Explicit
				};
			}
		}

		private new void Start()
		{
			HookUpAudioPlayer();
		}

		public new void OnSelect(BaseEventData eventData)
		{
			if (!base.interactable)
			{
				return;
			}
			if (OnSelected != null)
			{
				OnSelected(this);
			}
			if (leftCursor != null)
			{
				leftCursor.ResetTrigger("hide");
				leftCursor.SetTrigger("show");
			}
			if (rightCursor != null)
			{
				rightCursor.ResetTrigger("hide");
				rightCursor.SetTrigger("show");
			}
			if (selectHighlight != null)
			{
				selectHighlight.ResetTrigger("hide");
				selectHighlight.SetTrigger("show");
			}
			if (descriptionText != null)
			{
				descriptionText.ResetTrigger("hide");
				descriptionText.SetTrigger("show");
			}
			if (!DontPlaySelectSound)
			{
				try
				{
					uiAudioPlayer.PlaySelect();
					return;
				}
				catch (Exception ex)
				{
					Debug.LogError(base.name + " doesn't have a select sound specified. " + ex);
					return;
				}
			}
			dontPlaySelectSound = false;
		}

		public new void OnDeselect(BaseEventData eventData)
		{
			StartCoroutine(ValidateDeselect());
		}

		public void ForceDeselect()
		{
			if (EventSystem.current.currentSelectedGameObject != null)
			{
				deselectWasForced = true;
				EventSystem.current.SetSelectedGameObject(null);
			}
		}

		public void OnCancel(BaseEventData eventData)
		{
			if (cancelAction == CancelAction.GoToExtrasMenu && customCancelAction != null)
			{
				ForceDeselect();
				customCancelAction(this);
				PlayCancelSound();
			}
			else
			{
				orig_OnCancel(eventData);
			}
		}

		private IEnumerator ValidateDeselect()
		{
			prevSelectedObject = EventSystem.current.currentSelectedGameObject;
			yield return new WaitForEndOfFrame();
			if (EventSystem.current.currentSelectedGameObject != null)
			{
				if (leftCursor != null)
				{
					leftCursor.ResetTrigger("show");
					leftCursor.SetTrigger("hide");
				}
				if (rightCursor != null)
				{
					rightCursor.ResetTrigger("show");
					rightCursor.SetTrigger("hide");
				}
				if (selectHighlight != null)
				{
					selectHighlight.ResetTrigger("show");
					selectHighlight.SetTrigger("hide");
				}
				if (descriptionText != null)
				{
					descriptionText.ResetTrigger("show");
					descriptionText.SetTrigger("hide");
				}
				deselectWasForced = false;
			}
			else if (deselectWasForced)
			{
				if (leftCursor != null)
				{
					leftCursor.ResetTrigger("show");
					leftCursor.SetTrigger("hide");
				}
				if (rightCursor != null)
				{
					rightCursor.ResetTrigger("show");
					rightCursor.SetTrigger("hide");
				}
				if (selectHighlight != null)
				{
					selectHighlight.ResetTrigger("show");
					selectHighlight.SetTrigger("hide");
				}
				if (descriptionText != null)
				{
					descriptionText.ResetTrigger("show");
					descriptionText.SetTrigger("hide");
				}
				deselectWasForced = false;
			}
			else
			{
				deselectWasForced = false;
				dontPlaySelectSound = true;
				EventSystem.current.SetSelectedGameObject(prevSelectedObject);
			}
		}

		protected void HookUpAudioPlayer()
		{
			if (UnityEngine.SceneManagement.SceneManager.GetActiveScene().name == "Pre_Menu_Intro")
			{
				uiAudioPlayer = Object.FindObjectOfType<MenuAudioController>();
			}
			else
			{
				uiAudioPlayer = UIManager.instance.uiAudioPlayer;
			}
		}

		protected void PlaySubmitSound()
		{
			if (playSubmitSound)
			{
				uiAudioPlayer.PlaySubmit();
			}
		}

		protected void PlayCancelSound()
		{
			uiAudioPlayer.PlayCancel();
		}

		protected void PlaySelectSound()
		{
			uiAudioPlayer.PlaySelect();
		}

		public void orig_OnCancel(BaseEventData eventData)
		{
			if (cancelAction != CancelAction.DoNothing)
			{
				ForceDeselect();
			}
			if (!parentList)
			{
				parentList = GetComponentInParent<MenuButtonList>();
			}
			if ((bool)parentList)
			{
				parentList.ClearLastSelected();
			}
			if (cancelAction != CancelAction.DoNothing)
			{
				if (cancelAction == CancelAction.GoToMainMenu)
				{
					UIManager.instance.UIGoToMainMenu();
				}
				else if (cancelAction == CancelAction.GoToOptionsMenu)
				{
					UIManager.instance.UIGoToOptionsMenu();
				}
				else if (cancelAction == CancelAction.GoToVideoMenu)
				{
					UIManager.instance.UIGoToVideoMenu();
				}
				else if (cancelAction == CancelAction.GoToPauseMenu)
				{
					UIManager.instance.UIGoToPauseMenu();
				}
				else if (cancelAction == CancelAction.LeaveOptionsMenu)
				{
					UIManager.instance.UILeaveOptionsMenu();
				}
				else if (cancelAction == CancelAction.GoToExitPrompt)
				{
					UIManager.instance.UIShowQuitGamePrompt();
				}
				else if (cancelAction == CancelAction.GoToProfileMenu)
				{
					UIManager.instance.UIGoToProfileMenu();
				}
				else if (cancelAction == CancelAction.GoToControllerMenu)
				{
					UIManager.instance.UIGoToControllerMenu();
				}
				else if (cancelAction == CancelAction.ApplyRemapGamepadSettings)
				{
					UIManager.instance.ApplyRemapGamepadMenuSettings();
				}
				else if (cancelAction == CancelAction.ApplyAudioSettings)
				{
					UIManager.instance.ApplyAudioMenuSettings();
				}
				else if (cancelAction == CancelAction.ApplyVideoSettings)
				{
					UIManager.instance.ApplyVideoMenuSettings();
				}
				else if (cancelAction == CancelAction.ApplyGameSettings)
				{
					UIManager.instance.ApplyGameMenuSettings();
				}
				else if (cancelAction == CancelAction.ApplyKeyboardSettings)
				{
					UIManager.instance.ApplyKeyboardMenuSettings();
				}
				else if (cancelAction == CancelAction.ApplyControllerSettings)
				{
					UIManager.instance.ApplyControllerMenuSettings();
				}
				else if (cancelAction == CancelAction.GoToExtrasMenu)
				{
					if ((bool)ContentPackDetailsUI.Instance)
					{
						ContentPackDetailsUI.Instance.UndoMenuStyle();
					}
					UIManager.instance.UIGoToExtrasMenu();
				}
				else if (cancelAction == CancelAction.GoToExplicitSwitchUser)
				{
					UIManager.instance.UIGoToEngageMenu();
				}
				else if (cancelAction == CancelAction.ReturnToProfileMenu)
				{
					UIManager.instance.UIReturnToProfileMenu();
				}
				else
				{
					Debug.LogError("CancelAction not implemented for this control");
				}
			}
			if (cancelAction != CancelAction.DoNothing)
			{
				PlayCancelSound();
			}
		}
	}
	public class MenuStyleSetting : MenuOptionHorizontal, IMoveHandler, IEventSystemHandler, IPointerClickHandler
	{
		private MenuStyles styles;

		private List<int> indexList = new List<int>();

		private new void OnEnable()
		{
			styles = MenuStyles.Instance;
			if (!styles || styles.styles.Length == 0)
			{
				return;
			}
			List<string> list = new List<string>();
			for (int i = 0; i < styles.styles.Length; i++)
			{
				MenuStyles.MenuStyle menuStyle = styles.styles[i];
				if (menuStyle.IsAvailable)
				{
					list.Add(menuStyle.displayName);
					indexList.Add(i);
				}
			}
			optionList = list.ToArray();
			selectedOptionIndex = indexList.IndexOf(styles.CurrentStyle);
			UpdateText();
		}

		public new void OnMove(AxisEventData move)
		{
			if (base.interactable)
			{
				if (MoveOption(move.moveDir))
				{
					UpdateStyle();
				}
				else
				{
					base.OnMove(move);
				}
			}
		}

		public new void OnPointerClick(PointerEventData eventData)
		{
			if (base.interactable)
			{
				PointerClickCheckArrows(eventData);
				UpdateStyle();
			}
		}

		private void UpdateStyle()
		{
			if ((bool)styles)
			{
				styles.SetStyle(indexList[selectedOptionIndex], fade: true);
			}
		}
	}
	public class PauseMenuButton : MenuSelectable, ISubmitHandler, IEventSystemHandler, IPointerClickHandler, ICancelHandler
	{
		public enum PauseButtonType
		{
			Continue,
			Options,
			Quit
		}

		public Animator flashEffect;

		private GameManager gm;

		private UIManager ui;

		private InputHandler ih;

		public PauseButtonType pauseButtonType;

		public new CancelAction cancelAction { get; private set; }

		private new void Start()
		{
			gm = GameManager.instance;
			ih = gm.inputHandler;
			ui = UIManager.instance;
			HookUpAudioPlayer();
		}

		public void OnSubmit(BaseEventData eventData)
		{
			if (pauseButtonType == PauseButtonType.Continue)
			{
				if (ih.pauseAllowed)
				{
					ui.TogglePauseGame();
					flashEffect.ResetTrigger("Flash");
					flashEffect.SetTrigger("Flash");
					ForceDeselect();
					PlaySubmitSound();
				}
			}
			else if (pauseButtonType == PauseButtonType.Options)
			{
				ui.UIGoToOptionsMenu();
				flashEffect.ResetTrigger("Flash");
				flashEffect.SetTrigger("Flash");
				ForceDeselect();
				PlaySubmitSound();
			}
			else if (pauseButtonType == PauseButtonType.Quit)
			{
				ui.UIShowReturnMenuPrompt();
				flashEffect.ResetTrigger("Flash");
				flashEffect.SetTrigger("Flash");
				ForceDeselect();
				PlaySubmitSound();
			}
		}

		public new void OnCancel(BaseEventData eventData)
		{
			if (ih.pauseAllowed)
			{
				ui.TogglePauseGame();
				flashEffect.ResetTrigger("Flash");
				flashEffect.SetTrigger("Flash");
				ForceDeselect();
				PlaySubmitSound();
			}
		}

		public void OnPointerClick(PointerEventData eventData)
		{
			OnSubmit(eventData);
		}
	}
	[Serializable]
	public class SaveSlotButton : MenuButton, ISelectHandler, IEventSystemHandler, IDeselectHandler, ISubmitHandler, IPointerClickHandler
	{
		public enum SaveFileStates
		{
			NotStarted,
			OperationInProgress,
			Empty,
			LoadedStats,
			Corrupted
		}

		public enum SaveSlot
		{
			SLOT_1,
			SLOT_2,
			SLOT_3,
			SLOT_4
		}

		public enum SlotState
		{
			HIDDEN,
			OPERATION_IN_PROGRESS,
			EMPTY_SLOT,
			SAVE_PRESENT,
			CORRUPTED,
			CLEAR_PROMPT,
			DEFEATED
		}

		private bool verboseMode;

		[Header("Slot Number")]
		public SaveSlot saveSlot;

		[Header("Animation")]
		public Animator topFleur;

		public Animator highlight;

		[Header("Canvas Groups")]
		public CanvasGroup newGameText;

		public CanvasGroup saveCorruptedText;

		public CanvasGroup loadingText;

		public CanvasGroup activeSaveSlot;

		public CanvasGroup clearSaveButton;

		public CanvasGroup clearSavePrompt;

		public CanvasGroup backgroundCg;

		public CanvasGroup slotNumberText;

		public CanvasGroup myCanvasGroup;

		public CanvasGroup defeatedText;

		public CanvasGroup defeatedBackground;

		public CanvasGroup brokenSteelOrb;

		[Header("Text Elements")]
		public Text geoText;

		public Text locationText;

		public Text playTimeText;

		public Text completionText;

		[Header("Soul Orbs")]
		public CanvasGroup normalSoulOrbCg;

		public CanvasGroup hardcoreSoulOrbCg;

		public CanvasGroup ggSoulOrbCg;

		[Header("Visual Elements")]
		public Image background;

		public Image soulOrbIcon;

		public SaveProfileHealthBar healthSlots;

		public Image geoIcon;

		public SaveProfileMPSlots mpSlots;

		public SaveSlotBackgrounds saveSlots;

		[Header("Raycast Blocker")]
		public GameObject clearSaveBlocker;

		private GameManager gm;

		private UIManager ui;

		private InputHandler ih;

		public SaveFileStates saveFileState;

		private PreselectOption clearSavePromptHighlight;

		[SerializeField]
		private SaveStats saveStats;

		private Navigation noNav;

		private Navigation fullSlotNav;

		private Navigation emptySlotNav;

		private IEnumerator currentLoadingTextFadeIn;

		private bool didLoadSaveStats;

		private CoroutineQueue coroutineQueue;

		public SlotState state { get; private set; }

		private int SaveSlotIndex => saveSlot switch
		{
			SaveSlot.SLOT_1 => 1, 
			SaveSlot.SLOT_2 => 2, 
			SaveSlot.SLOT_3 => 3, 
			SaveSlot.SLOT_4 => 4, 
			_ => 0, 
		};

		private new void Awake()
		{
			gm = GameManager.instance;
			clearSavePromptHighlight = clearSavePrompt.GetComponent<PreselectOption>();
			coroutineQueue = new CoroutineQueue(gm);
			SetupNavs();
		}

		private new void OnEnable()
		{
			if (saveStats != null && saveFileState == SaveFileStates.LoadedStats)
			{
				PresentSaveSlot(saveStats);
			}
		}

		private new void Start()
		{
			if (Application.isPlaying)
			{
				ui = UIManager.instance;
				ih = gm.inputHandler;
				HookUpAudioPlayer();
			}
		}

		public void Prepare(GameManager gameManager, bool isReload = false)
		{
			if (saveFileState != SaveFileStates.NotStarted && (!isReload || saveFileState != SaveFileStates.Corrupted))
			{
				return;
			}
			ChangeSaveFileState(SaveFileStates.OperationInProgress);
			Platform.Current.IsSaveSlotInUse(SaveSlotIndex, delegate(bool fileExists)
			{
				if (!fileExists)
				{
					ChangeSaveFileState(SaveFileStates.Empty);
				}
				else
				{
					gameManager.GetSaveStatsForSlot(SaveSlotIndex, delegate(SaveStats saveStats)
					{
						if (saveStats == null)
						{
							ChangeSaveFileState(SaveFileStates.Corrupted);
						}
						else
						{
							this.saveStats = saveStats;
							ChangeSaveFileState(SaveFileStates.LoadedStats);
						}
					});
				}
			});
		}

		public void ClearCache()
		{
			saveFileState = SaveFileStates.NotStarted;
			saveStats = null;
		}

		private void ChangeSaveFileState(SaveFileStates nextSaveFileState)
		{
			saveFileState = nextSaveFileState;
			if (base.isActiveAndEnabled)
			{
				ShowRelevantModeForSaveFileState();
			}
		}

		public new void OnSubmit(BaseEventData eventData)
		{
			if (saveFileState == SaveFileStates.LoadedStats)
			{
				if (saveStats.permadeathMode == 2)
				{
					ForceDeselect();
					ClearSavePrompt();
				}
				else
				{
					gm.LoadGameFromUI(SaveSlotIndex);
				}
				base.OnSubmit(eventData);
			}
			else if (saveFileState == SaveFileStates.Empty)
			{
				gm.profileID = SaveSlotIndex;
				if (gm.GetStatusRecordInt("RecPermadeathMode") == 1 || gm.GetStatusRecordInt("RecBossRushMode") == 1)
				{
					ui.UIGoToPlayModeMenu();
				}
				else
				{
					ui.StartNewGame();
				}
				base.OnSubmit(eventData);
			}
			else if (saveFileState == SaveFileStates.Corrupted)
			{
				StartCoroutine(ReloadCorrupted());
			}
		}

		protected IEnumerator ReloadCorrupted()
		{
			ih.StopUIInput();
			Prepare(gm, isReload: true);
			while (saveFileState == SaveFileStates.OperationInProgress)
			{
				yield return null;
			}
			ih.StartUIInput();
		}

		public new void OnPointerClick(PointerEventData eventData)
		{
			OnSubmit(eventData);
		}

		public new void OnSelect(BaseEventData eventData)
		{
			highlight.ResetTrigger("hide");
			highlight.SetTrigger("show");
			if (leftCursor != null)
			{
				leftCursor.ResetTrigger("hide");
				leftCursor.SetTrigger("show");
			}
			if (rightCursor != null)
			{
				rightCursor.ResetTrigger("hide");
				rightCursor.SetTrigger("show");
			}
			base.OnSelect(eventData);
			if (!base.interactable)
			{
				try
				{
					uiAudioPlayer.PlaySelect();
				}
				catch (Exception ex)
				{
					Debug.LogError(base.name + " doesn't have a select sound specified. " + ex);
				}
			}
		}

		public new void OnDeselect(BaseEventData eventData)
		{
			StartCoroutine(ValidateDeselect());
		}

		public void ShowRelevantModeForSaveFileState()
		{
			switch (saveFileState)
			{
			case SaveFileStates.Empty:
				coroutineQueue.Enqueue(AnimateToSlotState(SlotState.EMPTY_SLOT));
				break;
			default:
				coroutineQueue.Enqueue(AnimateToSlotState(SlotState.OPERATION_IN_PROGRESS));
				break;
			case SaveFileStates.Corrupted:
				coroutineQueue.Enqueue(AnimateToSlotState(SlotState.CORRUPTED));
				break;
			case SaveFileStates.LoadedStats:
				if (saveStats.permadeathMode == 2)
				{
					coroutineQueue.Enqueue(AnimateToSlotState(SlotState.DEFEATED));
				}
				else
				{
					coroutineQueue.Enqueue(AnimateToSlotState(SlotState.SAVE_PRESENT));
				}
				break;
			}
		}

		public void HideSaveSlot()
		{
			coroutineQueue.Enqueue(AnimateToSlotState(SlotState.HIDDEN));
		}

		public void ClearSavePrompt()
		{
			coroutineQueue.Enqueue(AnimateToSlotState(SlotState.CLEAR_PROMPT));
		}

		public void CancelClearSave()
		{
			if (state == SlotState.CLEAR_PROMPT)
			{
				ShowRelevantModeForSaveFileState();
			}
		}

		public void ClearSaveFile()
		{
			gm.ClearSaveFile(SaveSlotIndex, delegate
			{
			});
			saveStats = null;
			ChangeSaveFileState(SaveFileStates.Empty);
		}

		private IEnumerator FadeInCanvasGroupAfterDelay(float delay, CanvasGroup cg)
		{
			for (float timer = 0f; timer < delay; timer += Time.unscaledDeltaTime)
			{
				yield return null;
			}
			yield return ui.FadeInCanvasGroup(cg);
		}

		private IEnumerator AnimateToSlotState(SlotState nextState)
		{
			SlotState slotState = state;
			if (slotState == nextState)
			{
				yield break;
			}
			if (currentLoadingTextFadeIn != null)
			{
				StopCoroutine(currentLoadingTextFadeIn);
				currentLoadingTextFadeIn = null;
			}
			if (verboseMode)
			{
				Debug.LogFormat("{0} SetState: {1} -> {2}", name, state, nextState);
			}
			state = nextState;
			switch (nextState)
			{
			case SlotState.HIDDEN:
			case SlotState.OPERATION_IN_PROGRESS:
				navigation = noNav;
				break;
			case SlotState.EMPTY_SLOT:
				navigation = emptySlotNav;
				break;
			case SlotState.SAVE_PRESENT:
			case SlotState.CORRUPTED:
			case SlotState.DEFEATED:
				navigation = fullSlotNav;
				break;
			}
			switch (slotState)
			{
			case SlotState.HIDDEN:
				switch (nextState)
				{
				case SlotState.OPERATION_IN_PROGRESS:
					topFleur.ResetTrigger("hide");
					topFleur.SetTrigger("show");
					yield return new WaitForSeconds(0.2f);
					StartCoroutine(currentLoadingTextFadeIn = FadeInCanvasGroupAfterDelay(5f, loadingText));
					break;
				case SlotState.EMPTY_SLOT:
					topFleur.ResetTrigger("hide");
					topFleur.SetTrigger("show");
					yield return new WaitForSeconds(0.2f);
					StartCoroutine(ui.FadeInCanvasGroup(slotNumberText));
					StartCoroutine(ui.FadeInCanvasGroup(newGameText));
					break;
				case SlotState.SAVE_PRESENT:
					topFleur.ResetTrigger("hide");
					topFleur.SetTrigger("show");
					yield return new WaitForSeconds(0.2f);
					StartCoroutine(ui.FadeInCanvasGroup(slotNumberText));
					StartCoroutine(ui.FadeInCanvasGroup(backgroundCg));
					StartCoroutine(ui.FadeInCanvasGroup(activeSaveSlot));
					StartCoroutine(ui.FadeInCanvasGroup(clearSaveButton));
					clearSaveButton.blocksRaycasts = true;
					break;
				case SlotState.DEFEATED:
					topFleur.ResetTrigger("hide");
					topFleur.SetTrigger("show");
					yield return new WaitForSeconds(0.2f);
					StartCoroutine(ui.FadeInCanvasGroup(defeatedBackground));
					StartCoroutine(ui.FadeInCanvasGroup(defeatedText));
					StartCoroutine(ui.FadeInCanvasGroup(brokenSteelOrb));
					StartCoroutine(ui.FadeInCanvasGroup(clearSaveButton));
					clearSaveButton.blocksRaycasts = true;
					myCanvasGroup.blocksRaycasts = true;
					break;
				case SlotState.CORRUPTED:
					topFleur.ResetTrigger("hide");
					topFleur.SetTrigger("show");
					yield return new WaitForSeconds(0.2f);
					StartCoroutine(ui.FadeInCanvasGroup(slotNumberText));
					StartCoroutine(ui.FadeInCanvasGroup(saveCorruptedText));
					StartCoroutine(ui.FadeInCanvasGroup(clearSaveButton));
					clearSaveButton.blocksRaycasts = true;
					myCanvasGroup.blocksRaycasts = true;
					break;
				}
				break;
			case SlotState.OPERATION_IN_PROGRESS:
				switch (nextState)
				{
				case SlotState.EMPTY_SLOT:
					yield return StartCoroutine(ui.FadeOutCanvasGroup(loadingText));
					StartCoroutine(ui.FadeInCanvasGroup(slotNumberText));
					StartCoroutine(ui.FadeInCanvasGroup(newGameText));
					break;
				case SlotState.SAVE_PRESENT:
					yield return StartCoroutine(ui.FadeOutCanvasGroup(loadingText));
					if (saveStats != null)
					{
						PresentSaveSlot(saveStats);
					}
					StartCoroutine(ui.FadeInCanvasGroup(slotNumberText));
					StartCoroutine(ui.FadeInCanvasGroup(backgroundCg));
					StartCoroutine(ui.FadeInCanvasGroup(activeSaveSlot));
					StartCoroutine(ui.FadeInCanvasGroup(clearSaveButton));
					clearSaveButton.blocksRaycasts = true;
					break;
				case SlotState.DEFEATED:
					yield return StartCoroutine(ui.FadeOutCanvasGroup(loadingText));
					StartCoroutine(ui.FadeInCanvasGroup(defeatedBackground));
					StartCoroutine(ui.FadeInCanvasGroup(defeatedText));
					StartCoroutine(ui.FadeInCanvasGroup(brokenSteelOrb));
					StartCoroutine(ui.FadeInCanvasGroup(clearSaveButton));
					clearSaveButton.blocksRaycasts = true;
					myCanvasGroup.blocksRaycasts = true;
					break;
				case SlotState.CORRUPTED:
					yield return StartCoroutine(ui.FadeOutCanvasGroup(loadingText));
					StartCoroutine(ui.FadeInCanvasGroup(slotNumberText));
					StartCoroutine(ui.FadeInCanvasGroup(saveCorruptedText));
					StartCoroutine(ui.FadeInCanvasGroup(clearSaveButton));
					clearSaveButton.blocksRaycasts = true;
					myCanvasGroup.blocksRaycasts = true;
					break;
				}
				break;
			case SlotState.SAVE_PRESENT:
				switch (nextState)
				{
				case SlotState.CLEAR_PROMPT:
					ih.StopUIInput();
					interactable = false;
					myCanvasGroup.blocksRaycasts = false;
					StartCoroutine(ui.FadeOutCanvasGroup(slotNumberText));
					StartCoroutine(ui.FadeOutCanvasGroup(activeSaveSlot));
					StartCoroutine(ui.FadeOutCanvasGroup(backgroundCg));
					yield return StartCoroutine(ui.FadeOutCanvasGroup(clearSaveButton));
					clearSaveButton.blocksRaycasts = false;
					clearSaveBlocker.SetActive(value: true);
					yield return StartCoroutine(ui.FadeInCanvasGroup(clearSavePrompt));
					clearSavePrompt.interactable = true;
					clearSavePrompt.blocksRaycasts = true;
					clearSavePromptHighlight.HighlightDefault();
					ih.StartUIInput();
					break;
				case SlotState.HIDDEN:
					topFleur.ResetTrigger("show");
					topFleur.SetTrigger("hide");
					yield return new WaitForSeconds(0.2f);
					StartCoroutine(ui.FadeOutCanvasGroup(slotNumberText));
					StartCoroutine(ui.FadeOutCanvasGroup(backgroundCg));
					StartCoroutine(ui.FadeOutCanvasGroup(activeSaveSlot));
					StartCoroutine(ui.FadeOutCanvasGroup(clearSaveButton));
					clearSaveButton.blocksRaycasts = false;
					break;
				}
				break;
			case SlotState.CLEAR_PROMPT:
				switch (nextState)
				{
				case SlotState.SAVE_PRESENT:
					ih.StopUIInput();
					yield return StartCoroutine(ui.FadeOutCanvasGroup(clearSavePrompt));
					clearSaveBlocker.SetActive(value: false);
					clearSavePrompt.interactable = false;
					clearSavePrompt.blocksRaycasts = false;
					if (saveStats != null)
					{
						PresentSaveSlot(saveStats);
					}
					StartCoroutine(ui.FadeInCanvasGroup(slotNumberText));
					StartCoroutine(ui.FadeInCanvasGroup(activeSaveSlot));
					StartCoroutine(ui.FadeInCanvasGroup(backgroundCg));
					yield return StartCoroutine(ui.FadeInCanvasGroup(clearSaveButton));
					clearSaveButton.blocksRaycasts = true;
					interactable = true;
					myCanvasGroup.blocksRaycasts = true;
					Select();
					ih.StartUIInput();
					break;
				case SlotState.EMPTY_SLOT:
					ih.StopUIInput();
					StartCoroutine(ui.FadeOutCanvasGroup(backgroundCg));
					yield return StartCoroutine(ui.FadeOutCanvasGroup(clearSavePrompt));
					clearSavePrompt.interactable = false;
					clearSavePrompt.blocksRaycasts = false;
					clearSaveBlocker.SetActive(value: false);
					StartCoroutine(ui.FadeInCanvasGroup(slotNumberText));
					yield return StartCoroutine(ui.FadeInCanvasGroup(newGameText));
					myCanvasGroup.blocksRaycasts = true;
					Select();
					ih.StartUIInput();
					break;
				case SlotState.DEFEATED:
					ih.StopUIInput();
					StartCoroutine(ui.FadeOutCanvasGroup(backgroundCg));
					yield return StartCoroutine(ui.FadeOutCanvasGroup(clearSavePrompt));
					clearSavePrompt.interactable = false;
					clearSavePrompt.blocksRaycasts = false;
					clearSaveBlocker.SetActive(value: false);
					StartCoroutine(ui.FadeInCanvasGroup(defeatedBackground));
					StartCoroutine(ui.FadeInCanvasGroup(defeatedText));
					StartCoroutine(ui.FadeInCanvasGroup(brokenSteelOrb));
					yield return StartCoroutine(ui.FadeInCanvasGroup(clearSaveButton));
					clearSaveButton.blocksRaycasts = true;
					myCanvasGroup.blocksRaycasts = true;
					Select();
					ih.StartUIInput();
					break;
				case SlotState.HIDDEN:
					yield return StartCoroutine(ui.FadeOutCanvasGroup(clearSavePrompt));
					break;
				case SlotState.CORRUPTED:
					ih.StopUIInput();
					yield return StartCoroutine(ui.FadeOutCanvasGroup(clearSavePrompt));
					clearSavePrompt.interactable = false;
					clearSavePrompt.blocksRaycasts = false;
					clearSaveBlocker.SetActive(value: false);
					StartCoroutine(ui.FadeInCanvasGroup(slotNumberText));
					StartCoroutine(ui.FadeInCanvasGroup(saveCorruptedText));
					yield return StartCoroutine(ui.FadeInCanvasGroup(clearSaveButton));
					clearSaveButton.blocksRaycasts = true;
					myCanvasGroup.blocksRaycasts = true;
					Select();
					ih.StartUIInput();
					break;
				}
				break;
			case SlotState.EMPTY_SLOT:
				if (nextState == SlotState.HIDDEN)
				{
					topFleur.ResetTrigger("show");
					topFleur.SetTrigger("hide");
					yield return new WaitForSeconds(0.2f);
					StartCoroutine(ui.FadeOutCanvasGroup(slotNumberText));
					StartCoroutine(ui.FadeOutCanvasGroup(backgroundCg));
					StartCoroutine(ui.FadeOutCanvasGroup(newGameText));
				}
				break;
			case SlotState.DEFEATED:
				switch (nextState)
				{
				case SlotState.CLEAR_PROMPT:
					ih.StopUIInput();
					interactable = false;
					myCanvasGroup.blocksRaycasts = false;
					StartCoroutine(ui.FadeOutCanvasGroup(defeatedBackground));
					StartCoroutine(ui.FadeOutCanvasGroup(defeatedText));
					StartCoroutine(ui.FadeOutCanvasGroup(brokenSteelOrb));
					yield return StartCoroutine(ui.FadeOutCanvasGroup(clearSaveButton));
					clearSaveButton.blocksRaycasts = false;
					clearSaveBlocker.SetActive(value: true);
					yield return StartCoroutine(ui.FadeInCanvasGroup(clearSavePrompt));
					clearSavePrompt.interactable = true;
					clearSavePrompt.blocksRaycasts = true;
					clearSavePromptHighlight.HighlightDefault();
					interactable = false;
					myCanvasGroup.blocksRaycasts = false;
					ih.StartUIInput();
					break;
				case SlotState.HIDDEN:
					topFleur.ResetTrigger("show");
					topFleur.SetTrigger("hide");
					yield return new WaitForSeconds(0.2f);
					StartCoroutine(ui.FadeOutCanvasGroup(slotNumberText));
					StartCoroutine(ui.FadeOutCanvasGroup(backgroundCg));
					StartCoroutine(ui.FadeOutCanvasGroup(activeSaveSlot));
					StartCoroutine(ui.FadeOutCanvasGroup(defeatedBackground));
					StartCoroutine(ui.FadeOutCanvasGroup(defeatedText));
					StartCoroutine(ui.FadeOutCanvasGroup(brokenSteelOrb));
					StartCoroutine(ui.FadeOutCanvasGroup(clearSaveButton));
					clearSaveButton.blocksRaycasts = false;
					break;
				}
				break;
			case SlotState.CORRUPTED:
				switch (nextState)
				{
				case SlotState.CLEAR_PROMPT:
					ih.StopUIInput();
					interactable = false;
					myCanvasGroup.blocksRaycasts = false;
					StartCoroutine(ui.FadeOutCanvasGroup(slotNumberText));
					StartCoroutine(ui.FadeOutCanvasGroup(saveCorruptedText));
					yield return StartCoroutine(ui.FadeOutCanvasGroup(clearSaveButton));
					clearSaveButton.blocksRaycasts = false;
					clearSaveBlocker.SetActive(value: true);
					yield return StartCoroutine(ui.FadeInCanvasGroup(clearSavePrompt));
					clearSavePrompt.interactable = true;
					clearSavePrompt.blocksRaycasts = true;
					clearSavePromptHighlight.HighlightDefault();
					interactable = false;
					myCanvasGroup.blocksRaycasts = false;
					ih.StartUIInput();
					break;
				case SlotState.HIDDEN:
					topFleur.ResetTrigger("show");
					topFleur.SetTrigger("hide");
					yield return new WaitForSeconds(0.2f);
					StartCoroutine(ui.FadeOutCanvasGroup(slotNumberText));
					StartCoroutine(ui.FadeOutCanvasGroup(saveCorruptedText));
					StartCoroutine(ui.FadeOutCanvasGroup(clearSaveButton));
					clearSaveButton.blocksRaycasts = false;
					break;
				case SlotState.OPERATION_IN_PROGRESS:
					StartCoroutine(ui.FadeOutCanvasGroup(slotNumberText));
					StartCoroutine(ui.FadeOutCanvasGroup(saveCorruptedText));
					yield return StartCoroutine(ui.FadeOutCanvasGroup(clearSaveButton));
					StartCoroutine(currentLoadingTextFadeIn = FadeInCanvasGroupAfterDelay(5f, loadingText));
					break;
				}
				break;
			default:
				if (slotState == SlotState.OPERATION_IN_PROGRESS && nextState == SlotState.HIDDEN)
				{
					topFleur.ResetTrigger("show");
					topFleur.SetTrigger("hide");
					yield return new WaitForSeconds(0.2f);
					StartCoroutine(ui.FadeOutCanvasGroup(loadingText));
				}
				break;
			}
		}

		private void PresentSaveSlot(SaveStats saveStats)
		{
			geoIcon.enabled = true;
			geoText.enabled = true;
			completionText.enabled = true;
			if (saveStats.bossRushMode)
			{
				normalSoulOrbCg.alpha = 0f;
				hardcoreSoulOrbCg.alpha = 0f;
				ggSoulOrbCg.alpha = 1f;
				healthSlots.showHealth(saveStats.maxHealth, steelsoulMode: false);
				playTimeText.text = saveStats.GetPlaytimeHHMM();
				mpSlots.showMPSlots(saveStats.GetMPSlotsVisible(), steelsoulMode: false);
				geoIcon.enabled = false;
				geoText.enabled = false;
				completionText.enabled = false;
				AreaBackground areaBackground = saveSlots.GetBackground(MapZone.GODS_GLORY);
				if (areaBackground != null)
				{
					background.sprite = areaBackground.backgroundImage;
				}
			}
			else if (saveStats.permadeathMode == 0)
			{
				normalSoulOrbCg.alpha = 1f;
				hardcoreSoulOrbCg.alpha = 0f;
				ggSoulOrbCg.alpha = 0f;
				healthSlots.showHealth(saveStats.maxHealth, steelsoulMode: false);
				geoText.text = saveStats.geo.ToString();
				if (saveStats.unlockedCompletionRate)
				{
					completionText.text = saveStats.completionPercentage + "%";
				}
				else
				{
					completionText.text = "";
				}
				playTimeText.text = saveStats.GetPlaytimeHHMM();
				mpSlots.showMPSlots(saveStats.GetMPSlotsVisible(), steelsoulMode: false);
				AreaBackground areaBackground2 = saveSlots.GetBackground(saveStats.mapZone);
				if (areaBackground2 != null)
				{
					background.sprite = areaBackground2.backgroundImage;
				}
			}
			else if (saveStats.permadeathMode == 1)
			{
				normalSoulOrbCg.alpha = 0f;
				hardcoreSoulOrbCg.alpha = 1f;
				ggSoulOrbCg.alpha = 0f;
				healthSlots.showHealth(saveStats.maxHealth, steelsoulMode: true);
				geoText.text = saveStats.geo.ToString();
				if (saveStats.unlockedCompletionRate)
				{
					completionText.text = saveStats.completionPercentage + "%";
				}
				else
				{
					completionText.text = "";
				}
				playTimeText.text = saveStats.GetPlaytimeHHMM();
				mpSlots.showMPSlots(saveStats.GetMPSlotsVisible(), steelsoulMode: true);
				AreaBackground areaBackground3 = saveSlots.GetBackground(saveStats.mapZone);
				if (areaBackground3 != null)
				{
					background.sprite = areaBackground3.backgroundImage;
				}
			}
			else if (saveStats.permadeathMode == 2)
			{
				normalSoulOrbCg.alpha = 0f;
				hardcoreSoulOrbCg.alpha = 0f;
				ggSoulOrbCg.alpha = 0f;
			}
			locationText.text = gm.GetFormattedMapZoneString(saveStats.mapZone).Replace("<br>", Environment.NewLine);
		}

		private void SetupNavs()
		{
			noNav = new Navigation
			{
				mode = Navigation.Mode.Explicit,
				selectOnLeft = null,
				selectOnRight = null,
				selectOnUp = base.navigation.selectOnUp,
				selectOnDown = base.navigation.selectOnDown
			};
			emptySlotNav = new Navigation
			{
				mode = Navigation.Mode.Explicit,
				selectOnRight = null,
				selectOnUp = base.navigation.selectOnUp,
				selectOnDown = base.navigation.selectOnDown
			};
			fullSlotNav = new Navigation
			{
				mode = Navigation.Mode.Explicit,
				selectOnRight = clearSaveButton.GetComponent<ClearSaveButton>(),
				selectOnUp = base.navigation.selectOnUp,
				selectOnDown = base.navigation.selectOnDown
			};
		}

		private IEnumerator ValidateDeselect()
		{
			prevSelectedObject = EventSystem.current.currentSelectedGameObject;
			yield return new WaitForEndOfFrame();
			if (EventSystem.current.currentSelectedGameObject != null)
			{
				leftCursor.ResetTrigger("show");
				rightCursor.ResetTrigger("show");
				highlight.ResetTrigger("show");
				leftCursor.SetTrigger("hide");
				rightCursor.SetTrigger("hide");
				highlight.SetTrigger("hide");
				deselectWasForced = false;
			}
			else if (deselectWasForced)
			{
				leftCursor.ResetTrigger("show");
				rightCursor.ResetTrigger("show");
				highlight.ResetTrigger("show");
				leftCursor.SetTrigger("hide");
				rightCursor.SetTrigger("hide");
				highlight.SetTrigger("hide");
				deselectWasForced = false;
			}
			else
			{
				deselectWasForced = false;
				dontPlaySelectSound = true;
				EventSystem.current.SetSelectedGameObject(prevSelectedObject);
			}
		}
	}
}
namespace UnityEngine.UI.Extensions
{
	[ExecuteInEditMode]
	[AddComponentMenu("UI/Effects/Extensions/SoftMaskScript")]
	public class SoftMaskScript : MonoBehaviour
	{
		private Material mat;

		private Canvas cachedCanvas;

		private Transform cachedCanvasTransform;

		private readonly Vector3[] m_WorldCorners = new Vector3[4];

		private readonly Vector3[] m_CanvasCorners = new Vector3[4];

		[Tooltip("The area that is to be used as the container.")]
		public RectTransform MaskArea;

		[Tooltip("Texture to be used to do the soft alpha")]
		public Texture AlphaMask;

		[Tooltip("At what point to apply the alpha min range 0-1")]
		[Range(0f, 1f)]
		public float CutOff;

		[Tooltip("Implement a hard blend based on the Cutoff")]
		public bool HardBlend;

		[Tooltip("Flip the masks alpha value")]
		public bool FlipAlphaMask;

		private Vector2 maskOffset = Vector2.zero;

		private Vector2 maskScale = Vector2.one;

		private void Start()
		{
			if (MaskArea == null)
			{
				MaskArea = GetComponent<RectTransform>();
			}
			Text component = GetComponent<Text>();
			if (component != null)
			{
				mat = new Material(Shader.Find("UI Extensions/SoftMaskShader"));
				component.material = mat;
				cachedCanvas = component.canvas;
				cachedCanvasTransform = cachedCanvas.transform;
				if (base.transform.parent.GetComponent<Mask>() == null)
				{
					base.transform.parent.gameObject.AddComponent<Mask>();
				}
				base.transform.parent.GetComponent<Mask>().enabled = false;
			}
			else
			{
				Graphic component2 = GetComponent<Graphic>();
				if (component2 != null)
				{
					mat = new Material(Shader.Find("UI Extensions/SoftMaskShader"));
					component2.material = mat;
					cachedCanvas = component2.canvas;
					cachedCanvasTransform = cachedCanvas.transform;
				}
			}
		}

		private void Update()
		{
			if (cachedCanvas != null)
			{
				SetMask();
			}
		}

		private void SetMask()
		{
			Rect canvasRect = GetCanvasRect();
			Vector2 size = canvasRect.size;
			maskScale.Set(1f / size.x, 1f / size.y);
			maskOffset = -canvasRect.min;
			maskOffset.Scale(maskScale);
			mat.SetTextureOffset("_AlphaMask", maskOffset);
			mat.SetTextureScale("_AlphaMask", maskScale);
			mat.SetTexture("_AlphaMask", AlphaMask);
			mat.SetFloat("_HardBlend", HardBlend ? 1 : 0);
			mat.SetInt("_FlipAlphaMask", FlipAlphaMask ? 1 : 0);
			mat.SetFloat("_CutOff", CutOff);
		}

		public Rect GetCanvasRect()
		{
			if (cachedCanvas == null)
			{
				return default(Rect);
			}
			MaskArea.GetWorldCorners(m_WorldCorners);
			for (int i = 0; i < 4; i++)
			{
				m_CanvasCorners[i] = cachedCanvasTransform.InverseTransformPoint(m_WorldCorners[i]);
			}
			return new Rect(m_CanvasCorners[0].x, m_CanvasCorners[0].y, m_CanvasCorners[2].x - m_CanvasCorners[0].x, m_CanvasCorners[2].y - m_CanvasCorners[0].y);
		}
	}
