namespace UnityStandardAssets.ImageEffects
{
	[RequireComponent(typeof(Camera))]
	[AddComponentMenu("Image Effects/Noise/Fast Noise")]
	public class FastNoise : PostEffectsBase
	{
		public enum FrameMultiple
		{
			Always = 1,
			Half = 2,
			Third = 3,
			Quarter = 4,
			Fifth = 5,
			Sixth = 6,
			Eighth = 8,
			Tenth = 10
		}

		private bool monochrome = true;

		[Header("Update Rate")]
		public FrameMultiple frameRateMultiplier = FrameMultiple.Always;

		[Header("Intensity")]
		public float intensityMultiplier = 0.25f;

		public float generalIntensity = 0.5f;

		public float blackIntensity = 1f;

		public float whiteIntensity = 1f;

		[Range(0f, 1f)]
		public float midGrey = 0.2f;

		[Header("Noise Shape")]
		public Texture2D noiseTexture;

		public FilterMode filterMode = FilterMode.Bilinear;

		[Range(0f, 0.99f)]
		private Vector3 intensities = new Vector3(1f, 1f, 1f);

		[Range(0f, 0.99f)]
		public float softness = 0.052f;

		[Header("Advanced")]
		public float monochromeTiling = 64f;

		public Shader noiseShader;

		private Material noiseMaterial;

		private static float TILE_AMOUNT = 64f;

		private byte frameCount;

		private RenderTexture softnessTexture;

		protected void OnDisable()
		{
			if (softnessTexture != null)
			{
				UnityEngine.Object.Destroy(softnessTexture);
				softnessTexture = null;
			}
		}

		public override bool CheckResources()
		{
			CheckSupport(needDepth: false);
			noiseMaterial = CheckShaderAndCreateMaterial(noiseShader, noiseMaterial);
			if (!isSupported)
			{
				ReportAutoDisable();
			}
			return isSupported;
		}

		private void OnRenderImage(RenderTexture source, RenderTexture destination)
		{
			if (Application.isEditor && !Application.isPlaying)
			{
				return;
			}
			if (!CheckResources() || null == noiseTexture)
			{
				Graphics.Blit(source, destination);
				if (null == noiseTexture)
				{
					UnityEngine.Debug.LogWarning("FastNoise effect failing as noise texture is not assigned. please assign.", base.transform);
				}
				return;
			}
			softness = Mathf.Clamp(softness, 0f, 0.99f);
			if ((bool)noiseTexture)
			{
				noiseTexture.wrapMode = TextureWrapMode.Repeat;
				noiseTexture.filterMode = filterMode;
			}
			noiseMaterial.SetTexture("_NoiseTex", noiseTexture);
			noiseMaterial.SetVector("_NoisePerChannel", monochrome ? Vector3.one : intensities);
			noiseMaterial.SetVector("_NoiseTilingPerChannel", Vector3.one * monochromeTiling);
			noiseMaterial.SetVector("_MidGrey", new Vector3(midGrey, 1f / (1f - midGrey), -1f / midGrey));
			noiseMaterial.SetVector("_NoiseAmount", new Vector3(generalIntensity, blackIntensity, whiteIntensity) * intensityMultiplier);
			if (softness > Mathf.Epsilon)
			{
				int num = (int)((float)source.width * (1f - softness));
				int num2 = (int)((float)source.height * (1f - softness));
				if (softnessTexture != null && (softnessTexture.width != num || softnessTexture.height != num2))
				{
					UnityEngine.Object.Destroy(softnessTexture);
					softnessTexture = null;
				}
				if (softnessTexture == null)
				{
					softnessTexture = new RenderTexture(num, num2, 0);
				}
				DrawNoiseQuadGrid(source, softnessTexture, noiseMaterial, noiseTexture, 2, (int)frameRateMultiplier);
				noiseMaterial.SetTexture("_NoiseTex", softnessTexture);
				Graphics.Blit(source, destination, noiseMaterial, 1);
			}
			else
			{
				DrawNoiseQuadGrid(source, destination, noiseMaterial, noiseTexture, 0, (int)frameRateMultiplier);
			}
			frameCount++;
		}

		private static void DrawNoiseQuadGrid(RenderTexture source, RenderTexture dest, Material fxMaterial, Texture2D noise, int passNr, int frameMultiple)
		{
			if (Time.frameCount % frameMultiple != 0)
			{
				return;
			}
			RenderTexture.active = dest;
			float num = (float)noise.width * 1f;
			float num2 = 1f * (float)source.width / TILE_AMOUNT;
			fxMaterial.SetTexture("_MainTex", source);
			GL.PushMatrix();
			GL.LoadOrtho();
			float num3 = 1f * (float)source.width / (1f * (float)source.height);
			float num4 = 1f / num2;
			float num5 = num4 * num3;
			float num6 = num / ((float)noise.width * 1f);
			fxMaterial.SetPass(passNr);
			GL.Begin(7);
			for (float num7 = 0f; num7 < 1f; num7 += num4)
			{
				for (float num8 = 0f; num8 < 1f; num8 += num5)
				{
					float num9 = UnityEngine.Random.Range(0f, 1f);
					float num10 = UnityEngine.Random.Range(0f, 1f);
					num9 = Mathf.Floor(num9 * num) / num;
					num10 = Mathf.Floor(num10 * num) / num;
					float num11 = 1f / num;
					GL.MultiTexCoord2(0, num9, num10);
					GL.MultiTexCoord2(1, 0f, 0f);
					GL.Vertex3(num7, num8, 0.1f);
					GL.MultiTexCoord2(0, num9 + num6 * num11, num10);
					GL.MultiTexCoord2(1, 1f, 0f);
					GL.Vertex3(num7 + num4, num8, 0.1f);
					GL.MultiTexCoord2(0, num9 + num6 * num11, num10 + num6 * num11);
					GL.MultiTexCoord2(1, 1f, 1f);
					GL.Vertex3(num7 + num4, num8 + num5, 0.1f);
					GL.MultiTexCoord2(0, num9, num10 + num6 * num11);
					GL.MultiTexCoord2(1, 0f, 1f);
					GL.Vertex3(num7, num8 + num5, 0.1f);
				}
			}
			GL.End();
			GL.PopMatrix();
		}
	}
}
namespace Language
{
	public static class Language
	{
		public static string settingsAssetPath;

		private static LocalizationSettings _settings;

		private static List<string> availableLanguages;

		private static LanguageCode currentLanguage;

		private static Dictionary<string, Dictionary<string, string>> currentEntrySheets;

		private const string LastLanguageKey = "M2H_lastLanguage";

		public static LocalizationSettings settings
		{
			get
			{
				if (_settings == null)
				{
					_settings = (LocalizationSettings)Resources.Load("Languages/" + Path.GetFileNameWithoutExtension(settingsAssetPath), typeof(LocalizationSettings));
				}
				return _settings;
			}
		}

		static Language()
		{
			settingsAssetPath = "Assets/Localization/Resources/Languages/LocalizationSettings.asset";
			_settings = null;
			currentLanguage = LanguageCode.N;
			LoadAvailableLanguages();
			LoadLanguage();
		}

		public static void LoadLanguage()
		{
			string text = RestoreLanguageSelection();
			UnityEngine.Debug.LogFormat("Restored language code '{0}'", text);
			SwitchLanguage(text);
		}

		private static string RestoreLanguageSelection()
		{
			if ((bool)Platform.Current && Platform.Current.SharedData.HasKey("M2H_lastLanguage"))
			{
				string text = Platform.Current.SharedData.GetString("M2H_lastLanguage", "");
				UnityEngine.Debug.LogFormat("Loaded saved language code '{0}'", text);
				if (availableLanguages.Contains(text))
				{
					return text;
				}
				UnityEngine.Debug.LogErrorFormat("Loaded saved language code '{0}' is not an available language", text);
			}
			if (settings.useSystemLanguagePerDefault)
			{
				SystemLanguage systemLanguage = Platform.Current.GetSystemLanguage();
				UnityEngine.Debug.LogFormat("Loaded system language '{0}'", systemLanguage);
				string text2 = LanguageNameToCode(systemLanguage).ToString();
				UnityEngine.Debug.LogFormat("Loaded system language code '{0}'", text2);
				if (availableLanguages.Contains(text2))
				{
					return text2;
				}
				UnityEngine.Debug.LogErrorFormat("System language code '{0}' is not an available language", text2);
			}
			UnityEngine.Debug.LogFormat("Falling back to default language code '{0}'", settings.defaultLangCode);
			return LocalizationSettings.GetLanguageEnum(settings.defaultLangCode).ToString();
		}

		public static void LoadAvailableLanguages()
		{
			availableLanguages = new List<string>();
			if (settings.sheetTitles == null || settings.sheetTitles.Length == 0)
			{
				UnityEngine.Debug.Log("None available");
				return;
			}
			foreach (LanguageCode value in Enum.GetValues(typeof(LanguageCode)))
			{
				if (HasLanguageFile(value.ToString() ?? "", settings.sheetTitles[0]))
				{
					availableLanguages.Add(value.ToString() ?? "");
				}
			}
			StringBuilder stringBuilder = new StringBuilder("Discovered supported languages: ");
			for (int i = 0; i < availableLanguages.Count; i++)
			{
				stringBuilder.Append(availableLanguages[i]);
				if (i < availableLanguages.Count - 1)
				{
					stringBuilder.Append(", ");
				}
			}
			UnityEngine.Debug.Log(stringBuilder.ToString());
			Resources.UnloadUnusedAssets();
		}

		public static string[] GetLanguages()
		{
			return availableLanguages.ToArray();
		}

		public static bool SwitchLanguage(string langCode)
		{
			return SwitchLanguage(LocalizationSettings.GetLanguageEnum(langCode));
		}

		public static bool SwitchLanguage(LanguageCode code)
		{
			if (availableLanguages.Contains(code.ToString() ?? ""))
			{
				DoSwitch(code);
				return true;
			}
			UnityEngine.Debug.LogError("Could not switch from language " + currentLanguage.ToString() + " to " + code);
			if (currentLanguage == LanguageCode.N)
			{
				if (availableLanguages.Count > 0)
				{
					DoSwitch(LocalizationSettings.GetLanguageEnum(availableLanguages[0]));
					UnityEngine.Debug.LogError("Switched to " + currentLanguage.ToString() + " instead");
				}
				else
				{
					UnityEngine.Debug.LogError("Please verify that you have the file: Resources/Languages/" + code);
					UnityEngine.Debug.Break();
				}
			}
			return false;
		}

		private static void DoSwitch(LanguageCode newLang)
		{
			if ((bool)Platform.Current)
			{
				Platform.Current.SharedData.SetString("M2H_lastLanguage", newLang.ToString() ?? "");
				Platform.Current.SharedData.Save();
			}
			currentLanguage = newLang;
			currentEntrySheets = new Dictionary<string, Dictionary<string, string>>();
			string[] sheetTitles = settings.sheetTitles;
			foreach (string text in sheetTitles)
			{
				currentEntrySheets[text] = new Dictionary<string, string>();
				string languageFileContents = GetLanguageFileContents(text);
				if (!(languageFileContents != ""))
				{
					continue;
				}
				using XmlReader xmlReader = XmlReader.Create(new StringReader(languageFileContents));
				while (xmlReader.ReadToFollowing("entry"))
				{
					xmlReader.MoveToFirstAttribute();
					string value = xmlReader.Value;
					xmlReader.MoveToElement();
					string s = xmlReader.ReadElementContentAsString().Trim();
					s = s.UnescapeXML();
					currentEntrySheets[text][value] = s;
				}
			}
			LocalizedAsset[] array = (LocalizedAsset[])UnityEngine.Object.FindObjectsOfType(typeof(LocalizedAsset));
			for (int i = 0; i < array.Length; i++)
			{
				array[i].LocalizeAsset();
			}
			SendMonoMessage("ChangedLanguage", currentLanguage);
			if (!ConfigManager.IsSavingConfig)
			{
				ConfigManager.SaveConfig();
			}
		}

