		}

		public InputControlSource Source
		{
			get
			{
				return source;
			}
			set
			{
				source = value;
			}
		}

		public InputControlType Target
		{
			get
			{
				return target;
			}
			set
			{
				target = value;
			}
		}

		public InputRangeType SourceRange
		{
			get
			{
				return sourceRange;
			}
			set
			{
				sourceRange = value;
			}
		}

		public InputRangeType TargetRange
		{
			get
			{
				return targetRange;
			}
			set
			{
				targetRange = value;
			}
		}

		public float ApplyToValue(float value)
		{
			if (Raw)
			{
				value *= Scale;
				value = (InputRange.Excludes(sourceRange, value) ? 0f : value);
			}
			else
			{
				value = Mathf.Clamp(value * Scale, -1f, 1f);
				value = InputRange.Remap(value, sourceRange, targetRange);
			}
			if (Invert)
			{
				value = 0f - value;
			}
			return value;
		}
	}
	public enum InputControlSourceType
	{
		None,
		Button,
		Analog,
		KeyCode
	}
	[Serializable]
	public struct InputControlSource
	{
		[SerializeField]
		private InputControlSourceType sourceType;

		[SerializeField]
		private int index;

		public InputControlSourceType SourceType
		{
			get
			{
				return sourceType;
			}
			set
			{
				sourceType = value;
			}
		}

		public int Index
		{
			get
			{
				return index;
			}
			set
			{
				index = value;
			}
		}

		public InputControlSource(InputControlSourceType sourceType, int index)
		{
			this.sourceType = sourceType;
			this.index = index;
		}

		public InputControlSource(KeyCode keyCode)
			: this(InputControlSourceType.KeyCode, (int)keyCode)
		{
		}

		public float GetValue(InputDevice inputDevice)
		{
			switch (SourceType)
			{
			case InputControlSourceType.None:
				return 0f;
			case InputControlSourceType.Button:
				if (!GetState(inputDevice))
				{
					return 0f;
				}
				return 1f;
			case InputControlSourceType.Analog:
				return inputDevice.ReadRawAnalogValue(Index);
			case InputControlSourceType.KeyCode:
				if (!GetState(inputDevice))
				{
					return 0f;
				}
				return 1f;
			default:
				throw new ArgumentOutOfRangeException();
			}
		}

		public bool GetState(InputDevice inputDevice)
		{
			return SourceType switch
			{
				InputControlSourceType.None => false, 
				InputControlSourceType.Button => inputDevice.ReadRawButtonState(Index), 
				InputControlSourceType.Analog => Utility.IsNotZero(GetValue(inputDevice)), 
				InputControlSourceType.KeyCode => Input.GetKey((KeyCode)Index), 
				_ => throw new ArgumentOutOfRangeException(), 
			};
		}

		public string ToCode()
		{
			return "new InputControlSource( InputControlSourceType." + SourceType.ToString() + ", " + Index + " )";
		}
	}
	public struct InputControlState
	{
		public bool State;

		public float Value;

		public float RawValue;

		public void Reset()
		{
			State = false;
			Value = 0f;
			RawValue = 0f;
		}

		public void Set(float value)
		{
			Value = value;
			State = Utility.IsNotZero(value);
		}

		public void Set(float value, float threshold)
		{
			Value = value;
			State = Utility.AbsoluteIsOverThreshold(value, threshold);
		}

		public void Set(bool state)
		{
			State = state;
			Value = (state ? 1f : 0f);
			RawValue = Value;
		}

		public static implicit operator bool(InputControlState state)
		{
			return state.State;
		}

		public static implicit operator float(InputControlState state)
		{
			return state.Value;
		}

		public static bool operator ==(InputControlState a, InputControlState b)
		{
			if (a.State == b.State)
			{
				return Utility.Approximately(a.Value, b.Value);
			}
			return false;
		}

		public static bool operator !=(InputControlState a, InputControlState b)
		{
			if (a.State == b.State)
			{
				return !Utility.Approximately(a.Value, b.Value);
			}
			return true;
		}
	}
