	[AddComponentMenu("Event/InControl Input Module")]
	public class InControlInputModule : PointerInputModule
	{
		public enum Button
		{
			Action1 = 19,
			Action2,
			Action3,
			Action4
		}

		public Button submitButton = Button.Action1;

		public Button cancelButton = Button.Action2;

		[Range(0.1f, 0.9f)]
		public float analogMoveThreshold = 0.5f;

		public float moveRepeatFirstDuration = 0.8f;

		public float moveRepeatDelayDuration = 0.1f;

		[FormerlySerializedAs("allowMobileDevice")]
		public bool forceModuleActive;

		public bool allowMouseInput = true;

		public bool focusOnMouseHover;

		public bool allowTouchInput = true;

		private InputDevice inputDevice;

		private Vector3 thisMousePosition;

		private Vector3 lastMousePosition;

		private Vector2 thisVectorState;

		private Vector2 lastVectorState;

		private bool thisSubmitState;

		private bool lastSubmitState;

		private bool thisCancelState;

		private bool lastCancelState;

		private bool moveWasRepeated;

		private float nextMoveRepeatTime;

		private TwoAxisInputControl direction;

		public PlayerAction SubmitAction { get; set; }

		public PlayerAction CancelAction { get; set; }

		public PlayerTwoAxisAction MoveAction { get; set; }

		public InputDevice Device
		{
			get
			{
				return inputDevice ?? InputManager.ActiveDevice;
			}
			set
			{
				inputDevice = value;
			}
		}

		private InputControl SubmitButton => Device.GetControl((InputControlType)submitButton);

		private InputControl CancelButton => Device.GetControl((InputControlType)cancelButton);

		private bool VectorIsPressed => thisVectorState != Vector2.zero;

		private bool VectorIsReleased => thisVectorState == Vector2.zero;

		private bool VectorHasChanged => thisVectorState != lastVectorState;

		private bool VectorWasPressed
		{
			get
			{
				if (!moveWasRepeated)
				{
					if (VectorIsPressed)
					{
						return lastVectorState == Vector2.zero;
					}
					return false;
				}
				return true;
			}
		}

		private bool SubmitWasPressed
		{
			get
			{
				if (thisSubmitState)
				{
					return thisSubmitState != lastSubmitState;
				}
				return false;
			}
		}

		private bool SubmitWasReleased
		{
			get
			{
				if (!thisSubmitState)
				{
					return thisSubmitState != lastSubmitState;
				}
				return false;
			}
		}

		private bool CancelWasPressed
		{
			get
			{
				if (thisCancelState)
				{
					return thisCancelState != lastCancelState;
				}
				return false;
			}
		}

		private bool MouseHasMoved => (thisMousePosition - lastMousePosition).sqrMagnitude > 0f;

		private static bool MouseButtonWasPressed => InputManager.MouseProvider.GetButtonWasPressed(Mouse.LeftButton);

		protected InControlInputModule()
		{
			direction = new TwoAxisInputControl();
			direction.StateThreshold = analogMoveThreshold;
		}

		public override void UpdateModule()
		{
			lastMousePosition = thisMousePosition;
			thisMousePosition = InputManager.MouseProvider.GetPosition();
		}

		public override bool IsModuleSupported()
		{
			if (forceModuleActive || InputManager.MouseProvider.HasMousePresent() || Input.touchSupported)
			{
				return true;
			}
			return false;
		}

		public override bool ShouldActivateModule()
		{
			if (!base.enabled || !base.gameObject.activeInHierarchy)
			{
				return false;
			}
			UpdateInputState();
			bool flag = false;
			flag |= SubmitWasPressed;
			flag |= CancelWasPressed;
			flag |= VectorWasPressed;
			if (allowMouseInput)
			{
				flag |= MouseHasMoved;
				flag |= MouseButtonWasPressed;
			}
			if (allowTouchInput)
			{
				flag |= Input.touchCount > 0;
			}
			return flag;
		}

		public override void ActivateModule()
		{
			base.ActivateModule();
			thisMousePosition = InputManager.MouseProvider.GetPosition();
			lastMousePosition = thisMousePosition;
			GameObject gameObject = base.eventSystem.currentSelectedGameObject;
			if (gameObject == null)
			{
				gameObject = base.eventSystem.firstSelectedGameObject;
			}
			base.eventSystem.SetSelectedGameObject(gameObject, GetBaseEventData());
		}

		public override void Process()
		{
			bool flag = SendUpdateEventToSelectedObject();
			if (base.eventSystem.sendNavigationEvents)
			{
				if (!flag)
				{
					flag = SendVectorEventToSelectedObject();
				}
				if (!flag)
				{
					SendButtonEventToSelectedObject();
				}
			}
			if ((!allowTouchInput || !ProcessTouchEvents()) && allowMouseInput)
			{
				ProcessMouseEvent();
			}
		}

		private bool ProcessTouchEvents()
		{
			int touchCount = Input.touchCount;
			for (int i = 0; i < touchCount; i++)
			{
				UnityEngine.Touch touch = Input.GetTouch(i);
				if (touch.type != UnityEngine.TouchType.Indirect)
				{
					PointerEventData touchPointerEventData = GetTouchPointerEventData(touch, out var pressed, out var released);
					ProcessTouchPress(touchPointerEventData, pressed, released);
					if (!released)
					{
						ProcessMove(touchPointerEventData);
						ProcessDrag(touchPointerEventData);
					}
					else
					{
						RemovePointerData(touchPointerEventData);
					}
				}
			}
			return touchCount > 0;
		}

		private bool SendButtonEventToSelectedObject()
		{
			if (base.eventSystem.currentSelectedGameObject == null)
			{
				return false;
			}
			BaseEventData baseEventData = GetBaseEventData();
			if (SubmitWasPressed)
			{
				ExecuteEvents.Execute(base.eventSystem.currentSelectedGameObject, baseEventData, ExecuteEvents.submitHandler);
			}
			else
			{
				_ = SubmitWasReleased;
			}
			if (CancelWasPressed)
			{
				ExecuteEvents.Execute(base.eventSystem.currentSelectedGameObject, baseEventData, ExecuteEvents.cancelHandler);
			}
			return baseEventData.used;
		}

		private bool SendVectorEventToSelectedObject()
		{
			if (!VectorWasPressed)
			{
				return false;
			}
			AxisEventData axisEventData = GetAxisEventData(thisVectorState.x, thisVectorState.y, 0.5f);
			if (axisEventData.moveDir != MoveDirection.None)
			{
				if (base.eventSystem.currentSelectedGameObject == null)
				{
					base.eventSystem.SetSelectedGameObject(base.eventSystem.firstSelectedGameObject, GetBaseEventData());
				}
				else
				{
					ExecuteEvents.Execute(base.eventSystem.currentSelectedGameObject, axisEventData, ExecuteEvents.moveHandler);
				}
				SetVectorRepeatTimer();
			}
			return axisEventData.used;
		}

		protected override void ProcessMove(PointerEventData pointerEvent)
		{
			GameObject pointerEnter = pointerEvent.pointerEnter;
			base.ProcessMove(pointerEvent);
			if (focusOnMouseHover && pointerEnter != pointerEvent.pointerEnter)
			{
				GameObject eventHandler = ExecuteEvents.GetEventHandler<ISelectHandler>(pointerEvent.pointerEnter);
				base.eventSystem.SetSelectedGameObject(eventHandler, pointerEvent);
			}
		}

		private void Update()
		{
			direction.Filter(Device.Direction, Time.deltaTime);
		}

		private void UpdateInputState()
		{
			lastVectorState = thisVectorState;
			thisVectorState = Vector2.zero;
			TwoAxisInputControl twoAxisInputControl = MoveAction ?? direction;
			if (Utility.AbsoluteIsOverThreshold(twoAxisInputControl.X, analogMoveThreshold))
			{
				thisVectorState.x = Mathf.Sign(twoAxisInputControl.X);
			}
			if (Utility.AbsoluteIsOverThreshold(twoAxisInputControl.Y, analogMoveThreshold))
			{
				thisVectorState.y = Mathf.Sign(twoAxisInputControl.Y);
			}
			moveWasRepeated = false;
			if (VectorIsReleased)
			{
				nextMoveRepeatTime = 0f;
			}
			else if (VectorIsPressed)
			{
				float realtimeSinceStartup = Time.realtimeSinceStartup;
				if (lastVectorState == Vector2.zero)
				{
					nextMoveRepeatTime = realtimeSinceStartup + moveRepeatFirstDuration;
				}
				else if (realtimeSinceStartup >= nextMoveRepeatTime)
				{
					moveWasRepeated = true;
					nextMoveRepeatTime = realtimeSinceStartup + moveRepeatDelayDuration;
				}
			}
			lastSubmitState = thisSubmitState;
			thisSubmitState = ((SubmitAction == null) ? SubmitButton.IsPressed : SubmitAction.IsPressed);
			lastCancelState = thisCancelState;
			thisCancelState = ((CancelAction == null) ? CancelButton.IsPressed : CancelAction.IsPressed);
		}

		private void SetVectorRepeatTimer()
		{
			nextMoveRepeatTime = Mathf.Max(nextMoveRepeatTime, Time.realtimeSinceStartup + moveRepeatDelayDuration);
		}

		protected bool SendUpdateEventToSelectedObject()
		{
			if (base.eventSystem.currentSelectedGameObject == null)
			{
				return false;
			}
			BaseEventData baseEventData = GetBaseEventData();
			ExecuteEvents.Execute(base.eventSystem.currentSelectedGameObject, baseEventData, ExecuteEvents.updateSelectedHandler);
			return baseEventData.used;
		}

		protected void ProcessMouseEvent()
		{
			ProcessMouseEvent(0);
		}

		protected void ProcessMouseEvent(int id)
		{
			MouseState mousePointerEventData = GetMousePointerEventData(id);
			MouseButtonEventData eventData = mousePointerEventData.GetButtonState(PointerEventData.InputButton.Left).eventData;
			ProcessMousePress(eventData);
			ProcessMove(eventData.buttonData);
			ProcessDrag(eventData.buttonData);
			ProcessMousePress(mousePointerEventData.GetButtonState(PointerEventData.InputButton.Right).eventData);
			ProcessDrag(mousePointerEventData.GetButtonState(PointerEventData.InputButton.Right).eventData.buttonData);
			ProcessMousePress(mousePointerEventData.GetButtonState(PointerEventData.InputButton.Middle).eventData);
			ProcessDrag(mousePointerEventData.GetButtonState(PointerEventData.InputButton.Middle).eventData.buttonData);
			if (!Mathf.Approximately(eventData.buttonData.scrollDelta.sqrMagnitude, 0f))
			{
				ExecuteEvents.ExecuteHierarchy(ExecuteEvents.GetEventHandler<IScrollHandler>(eventData.buttonData.pointerCurrentRaycast.gameObject), eventData.buttonData, ExecuteEvents.scrollHandler);
			}
		}

		protected void ProcessMousePress(MouseButtonEventData data)
		{
			PointerEventData buttonData = data.buttonData;
			GameObject gameObject = buttonData.pointerCurrentRaycast.gameObject;
			if (data.PressedThisFrame())
			{
				buttonData.eligibleForClick = true;
				buttonData.delta = Vector2.zero;
				buttonData.dragging = false;
				buttonData.useDragThreshold = true;
				buttonData.pressPosition = buttonData.position;
				buttonData.pointerPressRaycast = buttonData.pointerCurrentRaycast;
				DeselectIfSelectionChanged(gameObject, buttonData);
				GameObject gameObject2 = ExecuteEvents.ExecuteHierarchy(gameObject, buttonData, ExecuteEvents.pointerDownHandler);
				if (gameObject2 == null)
				{
					gameObject2 = ExecuteEvents.GetEventHandler<IPointerClickHandler>(gameObject);
				}
				float unscaledTime = Time.unscaledTime;
				if (gameObject2 == buttonData.lastPress)
				{
					if (unscaledTime - buttonData.clickTime < 0.3f)
					{
						int clickCount = buttonData.clickCount + 1;
						buttonData.clickCount = clickCount;
					}
					else
					{
						buttonData.clickCount = 1;
					}
					buttonData.clickTime = unscaledTime;
				}
				else
				{
					buttonData.clickCount = 1;
				}
				buttonData.pointerPress = gameObject2;
				buttonData.rawPointerPress = gameObject;
				buttonData.clickTime = unscaledTime;
				buttonData.pointerDrag = ExecuteEvents.GetEventHandler<IDragHandler>(gameObject);
				if (buttonData.pointerDrag != null)
				{
					ExecuteEvents.Execute(buttonData.pointerDrag, buttonData, ExecuteEvents.initializePotentialDrag);
				}
			}
			if (data.ReleasedThisFrame())
			{
				ExecuteEvents.Execute(buttonData.pointerPress, buttonData, ExecuteEvents.pointerUpHandler);
				GameObject eventHandler = ExecuteEvents.GetEventHandler<IPointerClickHandler>(gameObject);
				if (buttonData.pointerPress == eventHandler && buttonData.eligibleForClick)
				{
					ExecuteEvents.Execute(buttonData.pointerPress, buttonData, ExecuteEvents.pointerClickHandler);
				}
				else if (buttonData.pointerDrag != null && buttonData.dragging)
				{
					ExecuteEvents.ExecuteHierarchy(gameObject, buttonData, ExecuteEvents.dropHandler);
				}
				buttonData.eligibleForClick = false;
				buttonData.pointerPress = null;
				buttonData.rawPointerPress = null;
				if (buttonData.pointerDrag != null && buttonData.dragging)
				{
					ExecuteEvents.Execute(buttonData.pointerDrag, buttonData, ExecuteEvents.endDragHandler);
				}
				buttonData.dragging = false;
				buttonData.pointerDrag = null;
				if (gameObject != buttonData.pointerEnter)
				{
					HandlePointerExitAndEnter(buttonData, null);
					HandlePointerExitAndEnter(buttonData, gameObject);
				}
			}
		}

		protected void ProcessTouchPress(PointerEventData pointerEvent, bool pressed, bool released)
		{
			GameObject gameObject = pointerEvent.pointerCurrentRaycast.gameObject;
			if (pressed)
			{
				pointerEvent.eligibleForClick = true;
				pointerEvent.delta = Vector2.zero;
				pointerEvent.dragging = false;
				pointerEvent.useDragThreshold = true;
				pointerEvent.pressPosition = pointerEvent.position;
				pointerEvent.pointerPressRaycast = pointerEvent.pointerCurrentRaycast;
				DeselectIfSelectionChanged(gameObject, pointerEvent);
				if (pointerEvent.pointerEnter != gameObject)
				{
					HandlePointerExitAndEnter(pointerEvent, gameObject);
					pointerEvent.pointerEnter = gameObject;
				}
				GameObject gameObject2 = ExecuteEvents.ExecuteHierarchy(gameObject, pointerEvent, ExecuteEvents.pointerDownHandler);
				if (gameObject2 == null)
				{
					gameObject2 = ExecuteEvents.GetEventHandler<IPointerClickHandler>(gameObject);
				}
				float unscaledTime = Time.unscaledTime;
				if (gameObject2 == pointerEvent.lastPress)
				{
					if (unscaledTime - pointerEvent.clickTime < 0.3f)
					{
						int clickCount = pointerEvent.clickCount + 1;
						pointerEvent.clickCount = clickCount;
					}
					else
					{
						pointerEvent.clickCount = 1;
					}
					pointerEvent.clickTime = unscaledTime;
				}
				else
				{
					pointerEvent.clickCount = 1;
				}
				pointerEvent.pointerPress = gameObject2;
				pointerEvent.rawPointerPress = gameObject;
				pointerEvent.clickTime = unscaledTime;
				pointerEvent.pointerDrag = ExecuteEvents.GetEventHandler<IDragHandler>(gameObject);
				if (pointerEvent.pointerDrag != null)
				{
					ExecuteEvents.Execute(pointerEvent.pointerDrag, pointerEvent, ExecuteEvents.initializePotentialDrag);
				}
			}
			if (released)
			{
				ExecuteEvents.Execute(pointerEvent.pointerPress, pointerEvent, ExecuteEvents.pointerUpHandler);
				GameObject eventHandler = ExecuteEvents.GetEventHandler<IPointerClickHandler>(gameObject);
				if (pointerEvent.pointerPress == eventHandler && pointerEvent.eligibleForClick)
				{
					ExecuteEvents.Execute(pointerEvent.pointerPress, pointerEvent, ExecuteEvents.pointerClickHandler);
				}
				else if (pointerEvent.pointerDrag != null && pointerEvent.dragging)
				{
					ExecuteEvents.ExecuteHierarchy(gameObject, pointerEvent, ExecuteEvents.dropHandler);
				}
				pointerEvent.eligibleForClick = false;
				pointerEvent.pointerPress = null;
				pointerEvent.rawPointerPress = null;
				if (pointerEvent.pointerDrag != null && pointerEvent.dragging)
				{
					ExecuteEvents.Execute(pointerEvent.pointerDrag, pointerEvent, ExecuteEvents.endDragHandler);
				}
				pointerEvent.dragging = false;
				pointerEvent.pointerDrag = null;
				if (pointerEvent.pointerDrag != null)
				{
					ExecuteEvents.Execute(pointerEvent.pointerDrag, pointerEvent, ExecuteEvents.endDragHandler);
				}
				pointerEvent.pointerDrag = null;
				ExecuteEvents.ExecuteHierarchy(pointerEvent.pointerEnter, pointerEvent, ExecuteEvents.pointerExitHandler);
				pointerEvent.pointerEnter = null;
			}
		}
	}
	public static class InputManager
	{
		public static readonly VersionInfo Version = VersionInfo.InControlVersion();

		private static readonly List<InputDeviceManager> deviceManagers = new List<InputDeviceManager>();

		private static readonly Dictionary<Type, InputDeviceManager> deviceManagerTable = new Dictionary<Type, InputDeviceManager>();

		private static readonly List<InputDevice> devices = new List<InputDevice>();

		private static InputDevice activeDevice = InputDevice.Null;

		private static readonly List<InputDevice> activeDevices = new List<InputDevice>();

		private static readonly List<PlayerActionSet> playerActionSets = new List<PlayerActionSet>();

		public static ReadOnlyCollection<InputDevice> Devices;

		public static ReadOnlyCollection<InputDevice> ActiveDevices;

		private static bool applicationIsFocused;

		private static float initialTime;

		private static float currentTime;

		private static float lastUpdateTime;

		private static ulong currentTick;

		private static VersionInfo? unityVersion;

		private static bool enabled;

		public static bool CommandWasPressed { get; private set; }

		public static bool InvertYAxis { get; set; }

		public static bool IsSetup { get; private set; }

		public static IMouseProvider MouseProvider { get; private set; }

		public static IKeyboardProvider KeyboardProvider { get; private set; }

		internal static string Platform { get; private set; }

		[Obsolete("Use InputManager.CommandWasPressed instead.")]
		public static bool MenuWasPressed => CommandWasPressed;

		public static bool AnyKeyIsPressed => KeyCombo.Detect(modifiersAsKeys: true).IncludeCount > 0;

		public static InputDevice ActiveDevice
		{
			get
			{
				return activeDevice ?? InputDevice.Null;
			}
			private set
			{
				activeDevice = value ?? InputDevice.Null;
			}
		}

		public static bool Enabled
		{
			get
			{
				return enabled;
			}
			set
			{
				if (enabled != value)
				{
					if (value)
					{
						SetZeroTickOnAllControls();
						UpdateInternal();
					}
					else
					{
						ClearInputState();
						SetZeroTickOnAllControls();
					}
					enabled = value;
				}
			}
		}

		public static bool SuspendInBackground { get; set; }

		public static bool EnableNativeInput { get; internal set; }

		public static bool EnableXInput { get; internal set; }

		public static uint XInputUpdateRate { get; internal set; }

		public static uint XInputBufferSize { get; internal set; }

		public static bool NativeInputEnableXInput { get; internal set; }

		public static bool NativeInputEnableMFi { get; internal set; }

		public static bool NativeInputPreventSleep { get; internal set; }

		public static uint NativeInputUpdateRate { get; internal set; }

		public static bool EnableICade { get; internal set; }

		internal static VersionInfo UnityVersion
		{
			get
			{
				if (!unityVersion.HasValue)
				{
					unityVersion = VersionInfo.UnityVersion();
				}
				return unityVersion.Value;
			}
		}

		public static ulong CurrentTick => currentTick;

		public static event Action OnSetup;

		public static event Action<ulong, float> OnUpdate;

		public static event Action OnReset;

		public static event Action<InputDevice> OnDeviceAttached;

		public static event Action<InputDevice> OnDeviceDetached;

		public static event Action<InputDevice> OnActiveDeviceChanged;

		internal static event Action<ulong, float> OnUpdateDevices;

		internal static event Action<ulong, float> OnCommitDevices;

		internal static bool SetupInternal()
		{
			if (IsSetup)
			{
				return false;
			}
			Platform = Utility.GetPlatformName();
			enabled = true;
			initialTime = 0f;
			currentTime = 0f;
			lastUpdateTime = 0f;
			currentTick = 0uL;
			applicationIsFocused = true;
			deviceManagers.Clear();
			deviceManagerTable.Clear();
			devices.Clear();
			Devices = devices.AsReadOnly();
			activeDevice = InputDevice.Null;
			activeDevices.Clear();
			ActiveDevices = activeDevices.AsReadOnly();
			playerActionSets.Clear();
			MouseProvider = new UnityMouseProvider();
			MouseProvider.Setup();
			KeyboardProvider = new UnityKeyboardProvider();
			KeyboardProvider.Setup();
			IsSetup = true;
			bool flag = true;
			if (EnableNativeInput && NativeInputDeviceManager.Enable())
			{
				flag = false;
			}
			if (EnableXInput & flag)
			{
				XInputDeviceManager.Enable();
			}
			if (OnSetup != null)
			{
				OnSetup();
				OnSetup = null;
			}
			if (flag)
			{
				AddDeviceManager<UnityInputDeviceManager>();
			}
			return true;
		}

		internal static void ResetInternal()
		{
			if (OnReset != null)
			{
				OnReset();
			}
			OnSetup = null;
			OnUpdate = null;
			OnReset = null;
			OnActiveDeviceChanged = null;
			OnDeviceAttached = null;
			OnDeviceDetached = null;
			OnUpdateDevices = null;
			OnCommitDevices = null;
			DestroyDeviceManagers();
			DestroyDevices();
			playerActionSets.Clear();
			MouseProvider.Reset();
			KeyboardProvider.Reset();
			IsSetup = false;
		}

		public static void Update()
		{
			UpdateInternal();
		}

		internal static void UpdateInternal()
		{
			AssertIsSetup();
			if (OnSetup != null)
			{
				OnSetup();
				OnSetup = null;
			}
			if (enabled && (!SuspendInBackground || applicationIsFocused))
			{
				currentTick++;
				UpdateCurrentTime();
				float num = currentTime - lastUpdateTime;
				MouseProvider.Update();
				KeyboardProvider.Update();
				UpdateDeviceManagers(num);
				CommandWasPressed = false;
				UpdateDevices(num);
				CommitDevices(num);
				InputDevice inputDevice = ActiveDevice;
				UpdateActiveDevice();
				UpdatePlayerActionSets(num);
				if (inputDevice != ActiveDevice && OnActiveDeviceChanged != null)
				{
					OnActiveDeviceChanged(ActiveDevice);
				}
				if (OnUpdate != null)
				{
					OnUpdate(currentTick, num);
				}
				lastUpdateTime = currentTime;
			}
		}

		public static void Reload()
		{
			ResetInternal();
			SetupInternal();
		}

		private static void AssertIsSetup()
		{
			if (!IsSetup)
			{
				throw new Exception("InputManager is not initialized. Call InputManager.Setup() first.");
			}
		}

		private static void SetZeroTickOnAllControls()
		{
			int count = devices.Count;
			for (int i = 0; i < count; i++)
			{
				ReadOnlyCollection<InputControl> controls = devices[i].Controls;
				int count2 = controls.Count;
				for (int j = 0; j < count2; j++)
				{
					controls[j]?.SetZeroTick();
				}
			}
		}

		public static void ClearInputState()
		{
			int count = devices.Count;
			for (int i = 0; i < count; i++)
			{
				devices[i].ClearInputState();
			}
			int count2 = playerActionSets.Count;
			for (int j = 0; j < count2; j++)
			{
				playerActionSets[j].ClearInputState();
			}
			activeDevice = InputDevice.Null;
		}

		internal static void OnApplicationFocus(bool focusState)
		{
			if (!focusState)
			{
				if (SuspendInBackground)
				{
					ClearInputState();
				}
				SetZeroTickOnAllControls();
			}
			applicationIsFocused = focusState;
		}

		internal static void OnApplicationPause(bool pauseState)
		{
		}

		internal static void OnApplicationQuit()
		{
			ResetInternal();
		}

		internal static void OnLevelWasLoaded()
		{
			SetZeroTickOnAllControls();
			UpdateInternal();
		}

		public static void AddDeviceManager(InputDeviceManager deviceManager)
		{
			AssertIsSetup();
			Type type = deviceManager.GetType();
			if (deviceManagerTable.ContainsKey(type))
			{
				Logger.LogError("A device manager of type '" + type.Name + "' already exists; cannot add another.");
				return;
			}
			deviceManagers.Add(deviceManager);
			deviceManagerTable.Add(type, deviceManager);
			deviceManager.Update(currentTick, currentTime - lastUpdateTime);
		}

		public static void AddDeviceManager<T>() where T : InputDeviceManager, new()
		{
			AddDeviceManager(new T());
		}

		public static T GetDeviceManager<T>() where T : InputDeviceManager
		{
			if (deviceManagerTable.TryGetValue(typeof(T), out var value))
			{
				return value as T;
			}
			return null;
		}

		public static bool HasDeviceManager<T>() where T : InputDeviceManager
		{
			return deviceManagerTable.ContainsKey(typeof(T));
		}

		private static void UpdateCurrentTime()
		{
			if (initialTime < float.Epsilon)
			{
				initialTime = Time.realtimeSinceStartup;
			}
			currentTime = Mathf.Max(0f, Time.realtimeSinceStartup - initialTime);
		}

		private static void UpdateDeviceManagers(float deltaTime)
		{
			int count = deviceManagers.Count;
			for (int i = 0; i < count; i++)
			{
				deviceManagers[i].Update(currentTick, deltaTime);
			}
		}

		private static void DestroyDeviceManagers()
		{
			int count = deviceManagers.Count;
			for (int i = 0; i < count; i++)
			{
				deviceManagers[i].Destroy();
			}
			deviceManagers.Clear();
			deviceManagerTable.Clear();
		}

		private static void DestroyDevices()
		{
			int count = devices.Count;
			for (int i = 0; i < count; i++)
			{
				devices[i].OnDetached();
			}
			devices.Clear();
			activeDevice = InputDevice.Null;
		}

		private static void UpdateDevices(float deltaTime)
		{
			int count = devices.Count;
			for (int i = 0; i < count; i++)
			{
				devices[i].Update(currentTick, deltaTime);
			}
			if (OnUpdateDevices != null)
			{
				OnUpdateDevices(currentTick, deltaTime);
			}
		}

		private static void CommitDevices(float deltaTime)
		{
			int count = devices.Count;
			for (int i = 0; i < count; i++)
			{
				InputDevice inputDevice = devices[i];
				inputDevice.Commit(currentTick, deltaTime);
				if (inputDevice.CommandWasPressed)
				{
					CommandWasPressed = true;
				}
			}
			if (OnCommitDevices != null)
			{
				OnCommitDevices(currentTick, deltaTime);
			}
		}

		private static void UpdateActiveDevice()
		{
			activeDevices.Clear();
			int count = devices.Count;
			for (int i = 0; i < count; i++)
			{
				InputDevice inputDevice = devices[i];
				if (inputDevice.LastInputAfter(ActiveDevice) && !inputDevice.Passive)
				{
					ActiveDevice = inputDevice;
				}
				if (inputDevice.IsActive)
				{
					activeDevices.Add(inputDevice);
				}
			}
		}

		public static void AttachDevice(InputDevice inputDevice)
		{
			AssertIsSetup();
			if (!inputDevice.IsSupportedOnThisPlatform || inputDevice.IsAttached)
			{
				return;
			}
			if (!devices.Contains(inputDevice))
			{
				devices.Add(inputDevice);
				devices.Sort((InputDevice d1, InputDevice d2) => d1.SortOrder.CompareTo(d2.SortOrder));
			}
			inputDevice.OnAttached();
			if (OnDeviceAttached != null)
			{
				OnDeviceAttached(inputDevice);
			}
		}

		public static void DetachDevice(InputDevice inputDevice)
		{
			if (IsSetup && inputDevice.IsAttached)
			{
				devices.Remove(inputDevice);
				if (ActiveDevice == inputDevice)
				{
					ActiveDevice = InputDevice.Null;
				}
				inputDevice.OnDetached();
				if (OnDeviceDetached != null)
				{
					OnDeviceDetached(inputDevice);
				}
			}
		}

		public static void HideDevicesWithProfile(Type type)
		{
			if (type.IsSubclassOf(typeof(InputDeviceProfile)))
			{
				InputDeviceProfile.Hide(type);
			}
		}

		internal static void AttachPlayerActionSet(PlayerActionSet playerActionSet)
		{
			if (!playerActionSets.Contains(playerActionSet))
			{
				playerActionSets.Add(playerActionSet);
			}
		}

		internal static void DetachPlayerActionSet(PlayerActionSet playerActionSet)
		{
			playerActionSets.Remove(playerActionSet);
		}

		internal static void UpdatePlayerActionSets(float deltaTime)
		{
			int count = playerActionSets.Count;
			for (int i = 0; i < count; i++)
			{
				playerActionSets[i].Update(currentTick, deltaTime);
			}
		}
	}
	public interface IKeyboardProvider
	{
		void Setup();

		void Reset();

		void Update();

		bool AnyKeyIsPressed();

		bool GetKeyIsPressed(Key control);

		string GetNameForKey(Key control);
	}
	public class UnityKeyboardProvider : IKeyboardProvider
	{
		public readonly struct KeyMapping
		{
			private readonly Key source;

			private readonly KeyCode target0;

			private readonly KeyCode target1;

			private readonly string name;

			private readonly string macName;

			public bool IsPressed
			{
				get
				{
					if (target0 != KeyCode.None && Input.GetKey(target0))
					{
						return true;
					}
					if (target1 != KeyCode.None && Input.GetKey(target1))
					{
						return true;
					}
					return false;
				}
			}

			public string Name
			{
				get
				{
					if (Application.platform == RuntimePlatform.OSXEditor || Application.platform == RuntimePlatform.OSXPlayer)
					{
						return macName;
					}
					return name;
				}
			}

			public KeyMapping(Key source, string name, KeyCode target)
			{
				this.source = source;
				this.name = name;
				macName = name;
				target0 = target;
				target1 = KeyCode.None;
			}

			public KeyMapping(Key source, string name, KeyCode target0, KeyCode target1)
			{
				this.source = source;
				this.name = name;
				macName = name;
				this.target0 = target0;
				this.target1 = target1;
			}

			public KeyMapping(Key source, string name, string macName, KeyCode target)
			{
				this.source = source;
				this.name = name;
				this.macName = macName;
				target0 = target;
				target1 = KeyCode.None;
			}

			public KeyMapping(Key source, string name, string macName, KeyCode target0, KeyCode target1)
			{
				this.source = source;
				this.name = name;
				this.macName = macName;
				this.target0 = target0;
				this.target1 = target1;
			}
		}

