	public class SwitchSimpleInputDeviceManager : InputDeviceManager
	{
		private SwitchSimpleInputDevice device;

		private bool isDeviceAttached;

		public SwitchSimpleInputDevice Device => device;

		public SwitchSimpleInputDeviceManager()
		{
			device = new SwitchSimpleInputDevice();
			devices.Add(device);
			Update(0uL, 0f);
		}

		public override void Update(ulong updateTick, float deltaTime)
		{
			if (device.IsConnected != isDeviceAttached)
			{
				if (device.IsConnected)
				{
					InputManager.AttachDevice(device);
				}
				else
				{
					InputManager.DetachDevice(device);
				}
				isDeviceAttached = device.IsConnected;
			}
		}

		public static bool CheckPlatformSupport(ICollection<string> errors)
		{
			return false;
		}

		internal static bool Enable()
		{
			List<string> list = new List<string>();
			try
			{
				if (!CheckPlatformSupport(list))
				{
					return false;
				}
				InputManager.AddDeviceManager<SwitchSimpleInputDeviceManager>();
			}
			finally
			{
				foreach (string item in list)
				{
					Logger.LogError(item);
				}
			}
			return true;
		}
	}
	public class TouchButtonControl : TouchControl
	{
		[Header("Position")]
		[SerializeField]
		private TouchControlAnchor anchor = TouchControlAnchor.BottomRight;

		[SerializeField]
		private TouchUnitType offsetUnitType;

		[SerializeField]
		private Vector2 offset = new Vector2(-10f, 10f);

		[SerializeField]
		private bool lockAspectRatio = true;

		[Header("Options")]
		public ButtonTarget target = ButtonTarget.Action1;

		public bool allowSlideToggle = true;

		public bool toggleOnLeave;

		public bool pressureSensitive;

		[Header("Sprites")]
		public TouchSprite button = new TouchSprite(15f);

		private bool buttonState;

		private Touch currentTouch;

		private bool dirty;

		private bool ButtonState
		{
			get
			{
				return buttonState;
			}
			set
			{
				if (buttonState != value)
				{
					buttonState = value;
					button.State = value;
				}
			}
		}

		public Vector3 ButtonPosition
		{
			get
			{
				if (!button.Ready)
				{
					return base.transform.position;
				}
				return button.Position;
			}
			set
			{
				if (button.Ready)
				{
					button.Position = value;
				}
			}
		}

		public TouchControlAnchor Anchor
		{
			get
			{
