		public override void CreateControl()
		{
			ring.Create("Ring", base.transform, 1000);
			knob.Create("Knob", base.transform, 1001);
		}

		public override void DestroyControl()
		{
			ring.Delete();
			knob.Delete();
			if (currentTouch != null)
			{
				TouchEnded(currentTouch);
				currentTouch = null;
			}
		}

		public override void ConfigureControl()
		{
			resetPosition = OffsetToWorldPosition(anchor, offset, offsetUnitType, lockAspectRatio: true);
			base.transform.position = resetPosition;
			ring.Update(forceUpdate: true);
			knob.Update(forceUpdate: true);
			worldActiveArea = TouchManager.ConvertToWorld(activeArea, areaUnitType);
			worldKnobRange = TouchManager.ConvertToWorld(knobRange, knob.SizeUnitType);
		}

		public override void DrawGizmos()
		{
			ring.DrawGizmos(RingPosition, Color.yellow);
			knob.DrawGizmos(KnobPosition, Color.yellow);
			Utility.DrawCircleGizmo(RingPosition, worldKnobRange, Color.red);
			Utility.DrawRectGizmo(worldActiveArea, Color.green);
		}

		private void Update()
		{
			if (dirty)
			{
				ConfigureControl();
				dirty = false;
			}
			else
			{
				ring.Update();
				knob.Update();
			}
			if (IsNotActive)
			{
				if (resetWhenDone && KnobPosition != resetPosition)
				{
					Vector3 vector = KnobPosition - RingPosition;
					RingPosition = Vector3.MoveTowards(RingPosition, resetPosition, ringResetSpeed * Time.unscaledDeltaTime);
					KnobPosition = RingPosition + vector;
				}
				if (KnobPosition != RingPosition)
				{
					KnobPosition = Vector3.MoveTowards(KnobPosition, RingPosition, knobResetSpeed * Time.unscaledDeltaTime);
				}
			}
		}

		public override void SubmitControlState(ulong updateTick, float deltaTime)
		{
			SubmitAnalogValue(target, value, lowerDeadZone, upperDeadZone, updateTick, deltaTime);
		}

		public override void CommitControlState(ulong updateTick, float deltaTime)
		{
			CommitAnalog(target);
		}

		public override void TouchBegan(Touch touch)
		{
			if (!IsActive)
			{
				beganPosition = TouchManager.ScreenToWorldPoint(touch.position);
				bool flag = worldActiveArea.Contains(beganPosition);
				bool flag2 = ring.Contains(beganPosition);
				if (snapToInitialTouch && (flag | flag2))
				{
					RingPosition = beganPosition;
					KnobPosition = beganPosition;
					currentTouch = touch;
				}
				else if (flag2)
				{
					KnobPosition = beganPosition;
					beganPosition = RingPosition;
					currentTouch = touch;
				}
				if (IsActive)
				{
					TouchMoved(touch);
					ring.State = true;
					knob.State = true;
				}
			}
		}

		public override void TouchMoved(Touch touch)
		{
			if (currentTouch != touch)
			{
				return;
			}
			movedPosition = TouchManager.ScreenToWorldPoint(touch.position);
			if (lockToAxis == LockAxis.Horizontal && allowDraggingAxis == DragAxis.Horizontal)
			{
				movedPosition.y = beganPosition.y;
			}
			else if (lockToAxis == LockAxis.Vertical && allowDraggingAxis == DragAxis.Vertical)
			{
				movedPosition.x = beganPosition.x;
			}
			Vector3 vector = movedPosition - beganPosition;
			Vector3 normalized = vector.normalized;
			float magnitude = vector.magnitude;
			if (allowDragging)
			{
				float num = magnitude - worldKnobRange;
				if (num < 0f)
				{
					num = 0f;
				}
				Vector3 vector2 = num * normalized;
				if (allowDraggingAxis == DragAxis.Horizontal)
				{
					vector2.y = 0f;
				}
				else if (allowDraggingAxis == DragAxis.Vertical)
				{
					vector2.x = 0f;
				}
				beganPosition += vector2;
				RingPosition = beganPosition;
			}
			movedPosition = beganPosition + Mathf.Clamp(magnitude, 0f, worldKnobRange) * normalized;
			if (lockToAxis == LockAxis.Horizontal)
			{
				movedPosition.y = beganPosition.y;
			}
			else if (lockToAxis == LockAxis.Vertical)
			{
				movedPosition.x = beganPosition.x;
			}
			if (snapAngles != SnapAngles.None)
			{
				movedPosition = TouchControl.SnapTo(movedPosition - beganPosition, snapAngles) + beganPosition;
			}
			RingPosition = beganPosition;
			KnobPosition = movedPosition;
			value = (movedPosition - beganPosition) / worldKnobRange;
			value.x = inputCurve.Evaluate(Utility.Abs(value.x)) * Mathf.Sign(value.x);
			value.y = inputCurve.Evaluate(Utility.Abs(value.y)) * Mathf.Sign(value.y);
		}

		public override void TouchEnded(Touch touch)
		{
			if (currentTouch == touch)
			{
				value = Vector3.zero;
				float magnitude = (resetPosition - RingPosition).magnitude;
				ringResetSpeed = (Utility.IsZero(resetDuration) ? magnitude : (magnitude / resetDuration));
				float magnitude2 = (RingPosition - KnobPosition).magnitude;
				knobResetSpeed = (Utility.IsZero(resetDuration) ? knobRange : (magnitude2 / resetDuration));
				currentTouch = null;
				ring.State = false;
				knob.State = false;
			}
		}
	}
	public class TouchSwipeControl : TouchControl
	{
		[Header("Position")]
		[SerializeField]
		private TouchUnitType areaUnitType;

		[SerializeField]
		private Rect activeArea = new Rect(25f, 25f, 50f, 50f);

		[Header("Options")]
		[Range(0f, 1f)]
		public float sensitivity = 0.1f;

		public bool oneSwipePerTouch;

		[Header("Analog Target")]
		public AnalogTarget target;

		public SnapAngles snapAngles;

		[Header("Button Targets")]
		public ButtonTarget upTarget;

		public ButtonTarget downTarget;

		public ButtonTarget leftTarget;

		public ButtonTarget rightTarget;

		public ButtonTarget tapTarget;

		private Rect worldActiveArea;

		private Vector3 currentVector;

		private bool currentVectorIsSet;

		private Vector3 beganPosition;

		private Vector3 lastPosition;

		private Touch currentTouch;

		private bool fireButtonTarget;

		private ButtonTarget nextButtonTarget;

		private ButtonTarget lastButtonTarget;

		private bool dirty;

		public Rect ActiveArea
		{
			get
			{
				return activeArea;
			}
			set
			{
				if (activeArea != value)
				{
					activeArea = value;
					dirty = true;
				}
			}
		}

		public TouchUnitType AreaUnitType
		{
			get
			{
				return areaUnitType;
			}
			set
			{
				if (areaUnitType != value)
				{
					areaUnitType = value;
					dirty = true;
				}
			}
		}

		public override void CreateControl()
		{
		}

		public override void DestroyControl()
		{
			if (currentTouch != null)
			{
				TouchEnded(currentTouch);
				currentTouch = null;
			}
		}

		public override void ConfigureControl()
		{
			worldActiveArea = TouchManager.ConvertToWorld(activeArea, areaUnitType);
		}

		public override void DrawGizmos()
		{
			Utility.DrawRectGizmo(worldActiveArea, Color.yellow);
		}

		private void Update()
		{
			if (dirty)
			{
				ConfigureControl();
				dirty = false;
			}
		}

		public override void SubmitControlState(ulong updateTick, float deltaTime)
		{
			Vector3 vector = TouchControl.SnapTo(currentVector, snapAngles);
			SubmitAnalogValue(target, vector, 0f, 1f, updateTick, deltaTime);
			SubmitButtonState(upTarget, fireButtonTarget && nextButtonTarget == upTarget, updateTick, deltaTime);
			SubmitButtonState(downTarget, fireButtonTarget && nextButtonTarget == downTarget, updateTick, deltaTime);
			SubmitButtonState(leftTarget, fireButtonTarget && nextButtonTarget == leftTarget, updateTick, deltaTime);
			SubmitButtonState(rightTarget, fireButtonTarget && nextButtonTarget == rightTarget, updateTick, deltaTime);
			SubmitButtonState(tapTarget, fireButtonTarget && nextButtonTarget == tapTarget, updateTick, deltaTime);
			if (fireButtonTarget && nextButtonTarget != ButtonTarget.None)
			{
				fireButtonTarget = !oneSwipePerTouch;
				lastButtonTarget = nextButtonTarget;
				nextButtonTarget = ButtonTarget.None;
			}
		}

		public override void CommitControlState(ulong updateTick, float deltaTime)
		{
			CommitAnalog(target);
			CommitButton(upTarget);
			CommitButton(downTarget);
			CommitButton(leftTarget);
			CommitButton(rightTarget);
			CommitButton(tapTarget);
		}

		public override void TouchBegan(Touch touch)
		{
			if (currentTouch == null)
			{
				beganPosition = TouchManager.ScreenToWorldPoint(touch.position);
				if (worldActiveArea.Contains(beganPosition))
				{
					lastPosition = beganPosition;
					currentTouch = touch;
					currentVector = Vector2.zero;
					currentVectorIsSet = false;
					fireButtonTarget = true;
					nextButtonTarget = ButtonTarget.None;
					lastButtonTarget = ButtonTarget.None;
				}
			}
		}

		public override void TouchMoved(Touch touch)
		{
			if (currentTouch != touch)
			{
				return;
			}
			Vector3 vector = TouchManager.ScreenToWorldPoint(touch.position);
			Vector3 vector2 = vector - lastPosition;
			if (!(vector2.magnitude >= sensitivity))
			{
				return;
			}
			lastPosition = vector;
			if (!oneSwipePerTouch || !currentVectorIsSet)
			{
				currentVector = vector2.normalized;
				currentVectorIsSet = true;
			}
			if (fireButtonTarget)
			{
				ButtonTarget buttonTargetForVector = GetButtonTargetForVector(currentVector);
				if (buttonTargetForVector != lastButtonTarget)
				{
					nextButtonTarget = buttonTargetForVector;
				}
			}
		}

		public override void TouchEnded(Touch touch)
		{
			if (currentTouch == touch)
			{
				currentTouch = null;
				currentVector = Vector2.zero;
				currentVectorIsSet = false;
				Vector3 vector = TouchManager.ScreenToWorldPoint(touch.position);
				if ((beganPosition - vector).magnitude < sensitivity)
				{
					fireButtonTarget = true;
					nextButtonTarget = tapTarget;
					lastButtonTarget = ButtonTarget.None;
				}
				else
				{
					fireButtonTarget = false;
					nextButtonTarget = ButtonTarget.None;
					lastButtonTarget = ButtonTarget.None;
				}
			}
		}

		private ButtonTarget GetButtonTargetForVector(Vector2 vector)
		{
			Vector2 vector2 = TouchControl.SnapTo(vector, SnapAngles.Four);
			if (vector2 == Vector2.up)
			{
				return upTarget;
			}
			if (vector2 == Vector2.right)
			{
				return rightTarget;
			}
			if (vector2 == -Vector2.up)
			{
				return downTarget;
			}
			if (vector2 == -Vector2.right)
			{
				return leftTarget;
			}
			return ButtonTarget.None;
		}
	}
	public class TouchTrackControl : TouchControl
