			ConfigureControl();
		}

		public override void DestroyControl()
		{
			if (currentTouch != null)
			{
				TouchEnded(currentTouch);
				currentTouch = null;
			}
		}

		public override void ConfigureControl()
		{
			worldActiveArea = TouchManager.ConvertToWorld(activeArea, areaUnitType);
