		public override void DrawGizmos()
		{
			Utility.DrawRectGizmo(worldActiveArea, Color.yellow);
		}

		private void OnValidate()
		{
			if (maxTapDuration < 0f)
			{
				maxTapDuration = 0f;
			}
		}

		private void Update()
		{
			if (dirty)
			{
				ConfigureControl();
				dirty = false;
			}
		}

		public override void SubmitControlState(ulong updateTick, float deltaTime)
		{
			Vector3 vector = thisPosition - lastPosition;
			SubmitRawAnalogValue(target, vector * scale, updateTick, deltaTime);
			lastPosition = thisPosition;
			SubmitButtonState(tapTarget, fireButtonTarget, updateTick, deltaTime);
			fireButtonTarget = false;
		}

		public override void CommitControlState(ulong updateTick, float deltaTime)
		{
			CommitAnalog(target);
			CommitButton(tapTarget);
		}

		public override void TouchBegan(Touch touch)
		{
			if (currentTouch == null)
			{
				beganPosition = TouchManager.ScreenToWorldPoint(touch.position);
				if (worldActiveArea.Contains(beganPosition))
				{
					thisPosition = TouchManager.ScreenToViewPoint(touch.position * 100f);
					lastPosition = thisPosition;
					currentTouch = touch;
					beganTime = Time.realtimeSinceStartup;
				}
			}
		}

		public override void TouchMoved(Touch touch)
		{
			if (currentTouch == touch)
			{
				thisPosition = TouchManager.ScreenToViewPoint(touch.position * 100f);
			}
		}

		public override void TouchEnded(Touch touch)
		{
			if (currentTouch == touch)
			{
				Vector3 vector = TouchManager.ScreenToWorldPoint(touch.position) - beganPosition;
				float num = Time.realtimeSinceStartup - beganTime;
				if (vector.magnitude <= maxTapMovement && num <= maxTapDuration && tapTarget != ButtonTarget.None)
				{
					fireButtonTarget = true;
				}
				thisPosition = Vector3.zero;
				lastPosition = Vector3.zero;
				currentTouch = null;
			}
		}
	}
	public class Touch
	{
		public const int FingerID_None = -1;

		public const int FingerID_Mouse = -2;

		public int fingerId;

		public int mouseButton;

		public TouchPhase phase;

		public int tapCount;

		public Vector2 position;

		public Vector2 startPosition;

		public Vector2 deltaPosition;

		public Vector2 lastPosition;

		public float deltaTime;

		public ulong updateTick;

		public TouchType type;

		public float altitudeAngle;

		public float azimuthAngle;

		public float maximumPossiblePressure;

		public float pressure;

		public float radius;

		public float radiusVariance;

		[Obsolete("normalizedPressure is deprecated, please use NormalizedPressure instead.")]
		public float normalizedPressure => Mathf.Clamp(pressure / maximumPossiblePressure, 0.001f, 1f);

		public float NormalizedPressure => Mathf.Clamp(pressure / maximumPossiblePressure, 0.001f, 1f);

		public bool IsMouse => type == TouchType.Mouse;

		internal Touch()
		{
			fingerId = -1;
			phase = TouchPhase.Ended;
		}

		internal void Reset()
		{
			fingerId = -1;
			mouseButton = 0;
			phase = TouchPhase.Ended;
			tapCount = 0;
			position = Vector2.zero;
			startPosition = Vector2.zero;
			deltaPosition = Vector2.zero;
			lastPosition = Vector2.zero;
			deltaTime = 0f;
			updateTick = 0uL;
			type = TouchType.Direct;
			altitudeAngle = 0f;
			azimuthAngle = 0f;
			maximumPossiblePressure = 1f;
			pressure = 0f;
			radius = 0f;
			radiusVariance = 0f;
		}

		internal void SetWithTouchData(UnityEngine.Touch touch, ulong updateTick, float deltaTime)
		{
			phase = touch.phase;
			tapCount = touch.tapCount;
			mouseButton = 0;
			altitudeAngle = touch.altitudeAngle;
			azimuthAngle = touch.azimuthAngle;
			maximumPossiblePressure = touch.maximumPossiblePressure;
			pressure = touch.pressure;
			radius = touch.radius;
			radiusVariance = touch.radiusVariance;
			Vector2 vector = touch.position;
			vector.x = Mathf.Clamp(vector.x, 0f, Screen.width);
			vector.y = Mathf.Clamp(vector.y, 0f, Screen.height);
			if (phase == TouchPhase.Began)
			{
				startPosition = vector;
				deltaPosition = Vector2.zero;
				lastPosition = vector;
				position = vector;
			}
			else
			{
				if (phase == TouchPhase.Stationary)
				{
					phase = TouchPhase.Moved;
				}
				deltaPosition = vector - lastPosition;
				lastPosition = position;
				position = vector;
			}
			this.deltaTime = deltaTime;
			this.updateTick = updateTick;
		}

		internal bool SetWithMouseData(int button, ulong updateTick, float deltaTime)
		{
			if (Input.touchCount > 0)
			{
				return false;
			}
			if (button < 0 || button > 2)
			{
				return false;
			}
			Vector2 vector = InputManager.MouseProvider.GetPosition();
			Vector2 vector2 = new Vector2(Mathf.Round(vector.x), Mathf.Round(vector.y));
			Mouse control = (Mouse)(1 + button);
			if (InputManager.MouseProvider.GetButtonWasPressed(control))
			{
				phase = TouchPhase.Began;
				pressure = 1f;
				maximumPossiblePressure = 1f;
				tapCount = 1;
				type = TouchType.Mouse;
				mouseButton = button;
				startPosition = vector2;
				deltaPosition = Vector2.zero;
				lastPosition = vector2;
				position = vector2;
				this.deltaTime = deltaTime;
				this.updateTick = updateTick;
				return true;
			}
			if (InputManager.MouseProvider.GetButtonWasReleased(control))
			{
				phase = TouchPhase.Ended;
				pressure = 0f;
				maximumPossiblePressure = 1f;
				tapCount = 1;
				type = TouchType.Mouse;
				mouseButton = button;
				deltaPosition = vector2 - lastPosition;
				lastPosition = position;
				position = vector2;
				this.deltaTime = deltaTime;
				this.updateTick = updateTick;
				return true;
			}
			if (InputManager.MouseProvider.GetButtonIsPressed(control))
			{
				phase = TouchPhase.Moved;
				pressure = 1f;
				maximumPossiblePressure = 1f;
				tapCount = 1;
				type = TouchType.Mouse;
				mouseButton = button;
				deltaPosition = vector2 - lastPosition;
				lastPosition = position;
				position = vector2;
				this.deltaTime = deltaTime;
				this.updateTick = updateTick;
				return true;
			}
			return false;
		}
	}
	public abstract class TouchControl : MonoBehaviour
	{
		public enum ButtonTarget
		{
			None = 0,
			DPadDown = 12,
			DPadLeft = 13,
			DPadRight = 14,
			DPadUp = 11,
			LeftTrigger = 15,
			RightTrigger = 16,
			LeftBumper = 17,
			RightBumper = 18,
			Action1 = 19,
			Action2 = 20,
			Action3 = 21,
			Action4 = 22,
			Action5 = 23,
			Action6 = 24,
			Action7 = 25,
			Action8 = 26,
			Action9 = 27,
			Action10 = 28,
			Action11 = 29,
			Action12 = 30,
			Menu = 106,
			Button0 = 500,
			Button1 = 501,
			Button2 = 502,
			Button3 = 503,
			Button4 = 504,
			Button5 = 505,
			Button6 = 506,
			Button7 = 507,
			Button8 = 508,
			Button9 = 509,
			Button10 = 510,
			Button11 = 511,
			Button12 = 512,
			Button13 = 513,
			Button14 = 514,
			Button15 = 515,
			Button16 = 516,
			Button17 = 517,
			Button18 = 518,
			Button19 = 519
		}

		public enum AnalogTarget
		{
			None,
			LeftStick,
			RightStick,
			Both
		}

		public enum SnapAngles
		{
			None = 0,
			Four = 4,
			Eight = 8,
			Sixteen = 0x10
		}

		public abstract void CreateControl();

		public abstract void DestroyControl();

		public abstract void ConfigureControl();

		public abstract void SubmitControlState(ulong updateTick, float deltaTime);

		public abstract void CommitControlState(ulong updateTick, float deltaTime);

		public abstract void TouchBegan(Touch touch);

		public abstract void TouchMoved(Touch touch);

		public abstract void TouchEnded(Touch touch);

		public abstract void DrawGizmos();

		private void OnEnable()
		{
			TouchManager.OnSetup += Setup;
		}

		private void OnDisable()
		{
			DestroyControl();
			Resources.UnloadUnusedAssets();
		}

		private void Setup()
		{
			if (base.enabled)
			{
				CreateControl();
				ConfigureControl();
			}
		}

		protected Vector3 OffsetToWorldPosition(TouchControlAnchor anchor, Vector2 offset, TouchUnitType offsetUnitType, bool lockAspectRatio)
		{
			Vector3 vector = ((offsetUnitType == TouchUnitType.Pixels) ? ((Vector3)(TouchUtility.RoundVector(offset) * TouchManager.PixelToWorld)) : ((!lockAspectRatio) ? Vector3.Scale(offset, TouchManager.ViewSize) : ((Vector3)offset * TouchManager.PercentToWorld)));
			return TouchManager.ViewToWorldPoint(TouchUtility.AnchorToViewPoint(anchor)) + vector;
		}

		protected void SubmitButtonState(ButtonTarget target, bool state, ulong updateTick, float deltaTime)
		{
			if (TouchManager.Device != null && target != ButtonTarget.None)
			{
				InputControl control = TouchManager.Device.GetControl((InputControlType)target);
				if (control != null && control != InputControl.Null)
				{
					control.UpdateWithState(state, updateTick, deltaTime);
				}
			}
		}

		protected void SubmitButtonValue(ButtonTarget target, float value, ulong updateTick, float deltaTime)
		{
			if (TouchManager.Device != null && target != ButtonTarget.None)
			{
				InputControl control = TouchManager.Device.GetControl((InputControlType)target);
				if (control != null && control != InputControl.Null)
				{
					control.UpdateWithValue(value, updateTick, deltaTime);
				}
			}
		}

		protected void CommitButton(ButtonTarget target)
		{
			if (TouchManager.Device != null && target != ButtonTarget.None)
			{
				InputControl control = TouchManager.Device.GetControl((InputControlType)target);
				if (control != null && control != InputControl.Null)
				{
					control.Commit();
				}
			}
		}

		protected void SubmitAnalogValue(AnalogTarget target, Vector2 value, float lowerDeadZone, float upperDeadZone, ulong updateTick, float deltaTime)
		{
			if (TouchManager.Device != null && target != AnalogTarget.None)
			{
				Vector2 value2 = DeadZone.Circular(value.x, value.y, lowerDeadZone, upperDeadZone);
				if (target == AnalogTarget.LeftStick || target == AnalogTarget.Both)
				{
					TouchManager.Device.UpdateLeftStickWithValue(value2, updateTick, deltaTime);
				}
				if (target == AnalogTarget.RightStick || target == AnalogTarget.Both)
				{
					TouchManager.Device.UpdateRightStickWithValue(value2, updateTick, deltaTime);
				}
			}
		}

		protected void CommitAnalog(AnalogTarget target)
		{
			if (TouchManager.Device != null)
			{
				switch (target)
				{
				case AnalogTarget.None:
					return;
				case AnalogTarget.LeftStick:
				case AnalogTarget.Both:
					TouchManager.Device.CommitLeftStick();
					break;
				}
				if (target == AnalogTarget.RightStick || target == AnalogTarget.Both)
				{
					TouchManager.Device.CommitRightStick();
				}
			}
		}

		protected void SubmitRawAnalogValue(AnalogTarget target, Vector2 rawValue, ulong updateTick, float deltaTime)
		{
			if (TouchManager.Device != null)
			{
				switch (target)
				{
				case AnalogTarget.None:
					return;
				case AnalogTarget.LeftStick:
				case AnalogTarget.Both:
					TouchManager.Device.UpdateLeftStickWithRawValue(rawValue, updateTick, deltaTime);
					break;
				}
				if (target == AnalogTarget.RightStick || target == AnalogTarget.Both)
				{
					TouchManager.Device.UpdateRightStickWithRawValue(rawValue, updateTick, deltaTime);
				}
			}
		}

		protected static Vector3 SnapTo(Vector2 vector, SnapAngles snapAngles)
		{
			if (snapAngles == SnapAngles.None)
			{
				return vector;
			}
			float snapAngle = 360f / (float)snapAngles;
			return SnapTo(vector, snapAngle);
		}

		protected static Vector3 SnapTo(Vector2 vector, float snapAngle)
		{
			float num = Vector2.Angle(vector, Vector2.up);
			if (num < snapAngle / 2f)
			{
				return Vector2.up * vector.magnitude;
			}
			if (num > 180f - snapAngle / 2f)
			{
				return -Vector2.up * vector.magnitude;
			}
			float angle = Mathf.Round(num / snapAngle) * snapAngle - num;
			Vector3 axis = Vector3.Cross(Vector2.up, vector);
			return Quaternion.AngleAxis(angle, axis) * vector;
		}

		private void OnDrawGizmosSelected()
		{
			if (base.enabled && TouchManager.ControlsShowGizmos == TouchManager.GizmoShowOption.WhenSelected && !Utility.GameObjectIsCulledOnCurrentCamera(base.gameObject))
			{
				if (!Application.isPlaying)
				{
					ConfigureControl();
				}
				DrawGizmos();
			}
		}

		private void OnDrawGizmos()
		{
			if (!base.enabled)
			{
				return;
			}
			if (TouchManager.ControlsShowGizmos == TouchManager.GizmoShowOption.UnlessPlaying)
			{
				if (Application.isPlaying)
				{
					return;
				}
			}
			else if (TouchManager.ControlsShowGizmos != TouchManager.GizmoShowOption.Always)
			{
				return;
			}
			if (!Utility.GameObjectIsCulledOnCurrentCamera(base.gameObject))
			{
				if (!Application.isPlaying)
				{
					ConfigureControl();
				}
				DrawGizmos();
			}
		}
	}
