	public static class TouchUtility
	{
		public static Vector2 AnchorToViewPoint(TouchControlAnchor touchControlAnchor)
		{
			return touchControlAnchor switch
			{
				TouchControlAnchor.TopLeft => new Vector2(0f, 1f), 
				TouchControlAnchor.CenterLeft => new Vector2(0f, 0.5f), 
				TouchControlAnchor.BottomLeft => new Vector2(0f, 0f), 
				TouchControlAnchor.TopCenter => new Vector2(0.5f, 1f), 
				TouchControlAnchor.Center => new Vector2(0.5f, 0.5f), 
				TouchControlAnchor.BottomCenter => new Vector2(0.5f, 0f), 
				TouchControlAnchor.TopRight => new Vector2(1f, 1f), 
				TouchControlAnchor.CenterRight => new Vector2(1f, 0.5f), 
				TouchControlAnchor.BottomRight => new Vector2(1f, 0f), 
				_ => Vector2.zero, 
			};
		}

		public static Vector2 RoundVector(Vector2 vector)
		{
			return new Vector2(Mathf.Round(vector.x), Mathf.Round(vector.y));
		}
	}
	public class UnityInputDevice : InputDevice
	{
		private static string[,] analogQueries;

		private static string[,] buttonQueries;

		public const int MaxDevices = 10;

		public const int MaxButtons = 20;

		public const int MaxAnalogs = 20;

		private readonly InputDeviceProfile profile;

		public int JoystickId { get; private set; }

		public override bool IsSupportedOnThisPlatform
		{
			get
			{
				if (profile != null)
				{
					return profile.IsSupportedOnThisPlatform;
				}
				return true;
			}
		}

		public override bool IsKnown => profile != null;

		public override int NumUnknownButtons => 20;

		public override int NumUnknownAnalogs => 20;

		public UnityInputDevice(int joystickId, string joystickName)
			: this(null, joystickId, joystickName)
		{
		}

		public UnityInputDevice(InputDeviceProfile deviceProfile, int joystickId, string joystickName)
		{
			profile = deviceProfile;
			JoystickId = joystickId;
			if (joystickId != 0)
			{
				base.SortOrder = 100 + joystickId;
			}
			SetupAnalogQueries();
			SetupButtonQueries();
			base.AnalogSnapshot = null;
			if (IsKnown)
			{
				base.Name = profile.DeviceName;
				base.Meta = profile.DeviceNotes;
				base.DeviceClass = profile.DeviceClass;
				base.DeviceStyle = profile.DeviceStyle;
				int analogCount = profile.AnalogCount;
				for (int i = 0; i < analogCount; i++)
				{
					InputControlMapping inputControlMapping = profile.AnalogMappings[i];
					if (Utility.TargetIsAlias(inputControlMapping.Target))
					{
						Logger.LogError("Cannot map control \"" + inputControlMapping.Name + "\" as InputControlType." + inputControlMapping.Target.ToString() + " in profile \"" + deviceProfile.DeviceName + "\" because this target is reserved as an alias. The mapping will be ignored.");
					}
					else
					{
						InputControl inputControl = AddControl(inputControlMapping.Target, inputControlMapping.Name);
						inputControl.Sensitivity = Mathf.Min(profile.Sensitivity, inputControlMapping.Sensitivity);
						inputControl.LowerDeadZone = Mathf.Max(profile.LowerDeadZone, inputControlMapping.LowerDeadZone);
						inputControl.UpperDeadZone = Mathf.Min(profile.UpperDeadZone, inputControlMapping.UpperDeadZone);
						inputControl.Raw = inputControlMapping.Raw;
						inputControl.Passive = inputControlMapping.Passive;
					}
				}
				int buttonCount = profile.ButtonCount;
				for (int j = 0; j < buttonCount; j++)
				{
					InputControlMapping inputControlMapping2 = profile.ButtonMappings[j];
					if (Utility.TargetIsAlias(inputControlMapping2.Target))
					{
						Logger.LogError("Cannot map control \"" + inputControlMapping2.Name + "\" as InputControlType." + inputControlMapping2.Target.ToString() + " in profile \"" + deviceProfile.DeviceName + "\" because this target is reserved as an alias. The mapping will be ignored.");
					}
					else
					{
						AddControl(inputControlMapping2.Target, inputControlMapping2.Name).Passive = inputControlMapping2.Passive;
					}
				}
			}
			else
			{
				base.Name = "Unknown Device";
				base.Meta = "\"" + joystickName + "\"";
				for (int k = 0; k < NumUnknownButtons; k++)
				{
					AddControl((InputControlType)(500 + k), "Button " + k);
				}
				for (int l = 0; l < NumUnknownAnalogs; l++)
				{
					AddControl((InputControlType)(400 + l), "Analog " + l, 0.2f, 0.9f);
				}
			}
		}

		public override void Update(ulong updateTick, float deltaTime)
		{
			if (IsKnown)
			{
				int analogCount = profile.AnalogCount;
				for (int i = 0; i < analogCount; i++)
				{
					InputControlMapping inputControlMapping = profile.AnalogMappings[i];
					float value = inputControlMapping.Source.GetValue(this);
					InputControl control = GetControl(inputControlMapping.Target);
					if (!inputControlMapping.IgnoreInitialZeroValue || !control.IsOnZeroTick || !Utility.IsZero(value))
					{
						float value2 = inputControlMapping.ApplyToValue(value);
						control.UpdateWithValue(value2, updateTick, deltaTime);
					}
				}
				int buttonCount = profile.ButtonCount;
				for (int j = 0; j < buttonCount; j++)
				{
					InputControlMapping inputControlMapping2 = profile.ButtonMappings[j];
					bool state = inputControlMapping2.Source.GetState(this);
					UpdateWithState(inputControlMapping2.Target, state, updateTick, deltaTime);
				}
			}
			else
			{
				for (int k = 0; k < NumUnknownButtons; k++)
				{
					UpdateWithState((InputControlType)(500 + k), ReadRawButtonState(k), updateTick, deltaTime);
				}
				for (int l = 0; l < NumUnknownAnalogs; l++)
				{
					UpdateWithValue((InputControlType)(400 + l), ReadRawAnalogValue(l), updateTick, deltaTime);
				}
			}
		}

		private static void SetupAnalogQueries()
		{
			if (analogQueries != null)
			{
				return;
			}
			analogQueries = new string[10, 20];
			for (int i = 1; i <= 10; i++)
			{
				for (int j = 0; j < 20; j++)
				{
					analogQueries[i - 1, j] = "joystick " + i + " analog " + j;
				}
			}
		}

		private static void SetupButtonQueries()
		{
			if (buttonQueries != null)
			{
				return;
			}
			buttonQueries = new string[10, 20];
			for (int i = 1; i <= 10; i++)
			{
				for (int j = 0; j < 20; j++)
				{
					buttonQueries[i - 1, j] = "joystick " + i + " button " + j;
				}
			}
		}

		public override bool ReadRawButtonState(int index)
		{
			if (index < 20)
			{
				return Input.GetKey(buttonQueries[JoystickId - 1, index]);
			}
			return false;
		}

		public override float ReadRawAnalogValue(int index)
		{
			if (index < 20)
			{
				return Input.GetAxisRaw(analogQueries[JoystickId - 1, index]);
			}
			return 0f;
		}
	}
	public class UnityInputDeviceManager : InputDeviceManager
	{
		private const float deviceRefreshInterval = 1f;

		private float deviceRefreshTimer;

		private readonly List<InputDeviceProfile> systemDeviceProfiles;

		private readonly List<InputDeviceProfile> customDeviceProfiles;

		private string[] joystickNames;

		private int lastJoystickCount;

		private int lastJoystickHash;

		private int joystickCount;

		private int joystickHash;

		private bool JoystickInfoHasChanged
		{
			get
			{
				if (joystickHash == lastJoystickHash)
				{
					return joystickCount != lastJoystickCount;
				}
				return true;
			}
		}

		public UnityInputDeviceManager()
		{
			systemDeviceProfiles = new List<InputDeviceProfile>(UnityInputDeviceProfileList.Profiles.Length);
			customDeviceProfiles = new List<InputDeviceProfile>();
			AddSystemDeviceProfiles();
			QueryJoystickInfo();
			AttachDevices();
		}

		public override void Update(ulong updateTick, float deltaTime)
		{
			deviceRefreshTimer += deltaTime;
			if (deviceRefreshTimer >= 1f)
			{
				deviceRefreshTimer = 0f;
				QueryJoystickInfo();
				if (JoystickInfoHasChanged)
				{
					Logger.LogInfo("Change in attached Unity joysticks detected; refreshing device list.");
					DetachDevices();
					AttachDevices();
				}
			}
		}

		private void QueryJoystickInfo()
		{
			joystickNames = Input.GetJoystickNames();
			joystickCount = joystickNames.Length;
			joystickHash = 527 + joystickCount;
			for (int i = 0; i < joystickCount; i++)
			{
				joystickHash = joystickHash * 31 + joystickNames[i].GetHashCode();
			}
		}

		private void AttachDevices()
		{
			try
			{
				for (int i = 0; i < joystickCount; i++)
				{
					DetectJoystickDevice(i + 1, joystickNames[i]);
				}
			}
			catch (Exception ex)
			{
				Logger.LogError(ex.Message);
				Logger.LogError(ex.StackTrace);
			}
			lastJoystickCount = joystickCount;
			lastJoystickHash = joystickHash;
		}

		private void DetachDevices()
		{
			int count = devices.Count;
			for (int i = 0; i < count; i++)
			{
				InputManager.DetachDevice(devices[i]);
			}
			devices.Clear();
		}

		public void ReloadDevices()
		{
			QueryJoystickInfo();
			DetachDevices();
			AttachDevices();
		}

		private void AttachDevice(UnityInputDevice device)
		{
			devices.Add(device);
			InputManager.AttachDevice(device);
		}

		private bool HasAttachedDeviceWithJoystickId(int unityJoystickId)
		{
			int count = devices.Count;
			for (int i = 0; i < count; i++)
			{
				if (devices[i] is UnityInputDevice unityInputDevice && unityInputDevice.JoystickId == unityJoystickId)
				{
					return true;
				}
			}
			return false;
		}

		private void DetectJoystickDevice(int unityJoystickId, string unityJoystickName)
		{
			if (!HasAttachedDeviceWithJoystickId(unityJoystickId) && unityJoystickName.IndexOf("webcam", StringComparison.OrdinalIgnoreCase) == -1 && (!(InputManager.UnityVersion < new VersionInfo(4, 5, 0, 0)) || (Application.platform != RuntimePlatform.OSXEditor && Application.platform != RuntimePlatform.OSXPlayer) || !(unityJoystickName == "Unknown Wireless Controller")) && (!(InputManager.UnityVersion >= new VersionInfo(4, 6, 3, 0)) || (Application.platform != RuntimePlatform.WindowsEditor && Application.platform != RuntimePlatform.WindowsPlayer) || !string.IsNullOrEmpty(unityJoystickName)))
			{
				InputDeviceProfile inputDeviceProfile = DetectDevice(unityJoystickName);
				if (inputDeviceProfile == null)
				{
					UnityInputDevice device = new UnityInputDevice(unityJoystickId, unityJoystickName);
					AttachDevice(device);
					Logger.LogWarning("Device " + unityJoystickId + " with name \"" + unityJoystickName + "\" does not match any supported profiles and will be considered an unknown controller.");
				}
				else if (!inputDeviceProfile.IsHidden)
				{
					UnityInputDevice device2 = new UnityInputDevice(inputDeviceProfile, unityJoystickId, unityJoystickName);
					AttachDevice(device2);
					Logger.LogInfo("Device " + unityJoystickId + " matched profile " + inputDeviceProfile.GetType().Name + " (" + inputDeviceProfile.DeviceName + ")");
				}
				else
				{
					Logger.LogInfo("Device " + unityJoystickId + " matching profile " + inputDeviceProfile.GetType().Name + " (" + inputDeviceProfile.DeviceName + ") is hidden and will not be attached.");
				}
			}
		}

		private InputDeviceProfile DetectDevice(string unityJoystickName)
		{
			object obj = null;
			InputDeviceInfo deviceInfo = new InputDeviceInfo
			{
				name = unityJoystickName
			};
			if (obj == null)
			{
				obj = customDeviceProfiles.Find((InputDeviceProfile profile) => profile.Matches(deviceInfo));
			}
			if (obj == null)
			{
				obj = systemDeviceProfiles.Find((InputDeviceProfile profile) => profile.Matches(deviceInfo));
			}
			if (obj == null)
			{
				obj = customDeviceProfiles.Find((InputDeviceProfile profile) => profile.LastResortMatches(deviceInfo));
			}
			if (obj == null)
			{
				obj = systemDeviceProfiles.Find((InputDeviceProfile profile) => profile.LastResortMatches(deviceInfo));
			}
			return (InputDeviceProfile)obj;
		}

		private void AddSystemDeviceProfile(InputDeviceProfile deviceProfile)
		{
			if (deviceProfile != null && deviceProfile.IsSupportedOnThisPlatform)
			{
				systemDeviceProfiles.Add(deviceProfile);
			}
		}

		private void AddSystemDeviceProfiles()
		{
			for (int i = 0; i < UnityInputDeviceProfileList.Profiles.Length; i++)
			{
				InputDeviceProfile deviceProfile = InputDeviceProfile.CreateInstanceOfType(UnityInputDeviceProfileList.Profiles[i]);
				AddSystemDeviceProfile(deviceProfile);
			}
		}
	}
