	public static class Reflector
	{
		private static readonly string[] ignoreAssemblies = new string[12]
		{
			"Unity", "UnityEngine", "UnityEditor", "mscorlib", "Microsoft", "System", "Mono", "JetBrains", "nunit", "ExCSS",
			"ICSharpCode", "AssetStoreTools"
		};

		private static IEnumerable<Type> assemblyTypes;

		public static IEnumerable<Type> AllAssemblyTypes => assemblyTypes ?? (assemblyTypes = GetAllAssemblyTypes());

		private static bool IgnoreAssemblyWithName(string assemblyName)
		{
			string[] array = ignoreAssemblies;
			foreach (string value in array)
			{
				if (assemblyName.StartsWith(value))
				{
					return true;
				}
			}
			return false;
		}

		private static IEnumerable<Type> GetAllAssemblyTypes()
		{
			List<Type> list = new List<Type>();
			Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
			foreach (Assembly assembly in assemblies)
			{
				if (!IgnoreAssemblyWithName(assembly.GetName().Name))
				{
					Type[] array = null;
					try
					{
						array = assembly.GetTypes();
					}
					catch
					{
					}
					if (array != null)
					{
						list.AddRange(array);
					}
				}
			}
			return list;
		}
	}
	public abstract class SingletonMonoBehavior<TComponent> : MonoBehaviour where TComponent : MonoBehaviour
	{
		private static TComponent instance;

		private static bool hasInstance;

		private static int instanceId;

		private static readonly object lockObject = new object();

		public static TComponent Instance
		{
			get
			{
				lock (lockObject)
				{
					if (hasInstance)
					{
						return instance;
					}
					instance = FindFirstInstance();
					if (instance == null)
					{
						throw new Exception("The instance of singleton component " + typeof(TComponent)?.ToString() + " was requested, but it doesn't appear to exist in the scene.");
					}
					hasInstance = true;
					instanceId = instance.GetInstanceID();
					return instance;
				}
			}
		}

		protected bool EnforceSingleton
		{
			get
			{
				if (GetInstanceID() == Instance.GetInstanceID())
				{
					return false;
				}
				if (Application.isPlaying)
				{
					base.enabled = false;
				}
				return true;
			}
		}

		protected bool IsTheSingleton
		{
			get
			{
				lock (lockObject)
				{
					return GetInstanceID() == instanceId;
				}
			}
		}

		protected bool IsNotTheSingleton
		{
			get
			{
				lock (lockObject)
				{
					return GetInstanceID() != instanceId;
				}
			}
		}

		private static TComponent[] FindInstances()
		{
			TComponent[] array = UnityEngine.Object.FindObjectsOfType<TComponent>();
			Array.Sort(array, (TComponent a, TComponent b) => a.transform.GetSiblingIndex().CompareTo(b.transform.GetSiblingIndex()));
			return array;
		}

		private static TComponent FindFirstInstance()
		{
			TComponent[] array = FindInstances();
			if (array.Length == 0)
			{
				return null;
			}
			return array[0];
		}

		protected virtual void Awake()
		{
			if (!Application.isPlaying || !Instance)
			{
				return;
			}
			if (GetInstanceID() != instanceId)
			{
				base.enabled = false;
			}
			foreach (TComponent item in from o in FindInstances()
				where o.GetInstanceID() != instanceId
				select o)
			{
				item.enabled = false;
			}
		}

		protected virtual void OnDestroy()
		{
			lock (lockObject)
			{
				if (GetInstanceID() == instanceId)
				{
					hasInstance = false;
				}
			}
		}
	}
	internal class ThreadSafeQueue<T>
	{
		private object sync;

		private Queue<T> data;

		public ThreadSafeQueue()
		{
			sync = new object();
			data = new Queue<T>();
		}

		public ThreadSafeQueue(int capacity)
		{
			sync = new object();
			data = new Queue<T>(capacity);
		}

		public void Enqueue(T item)
		{
			lock (sync)
			{
				data.Enqueue(item);
			}
		}

		public bool Dequeue(out T item)
		{
			lock (sync)
			{
				if (data.Count > 0)
				{
					item = data.Dequeue();
					return true;
				}
			}
			item = default(T);
			return false;
		}

		public T Dequeue()
		{
			lock (sync)
			{
				if (data.Count > 0)
				{
					return data.Dequeue();
				}
			}
			return default(T);
		}

		public int Dequeue(ref IList<T> list)
		{
			lock (sync)
			{
				int count = data.Count;
				for (int i = 0; i < count; i++)
				{
					list.Add(data.Dequeue());
				}
				return count;
			}
		}
	}
	public static class Utility
	{
		public const float Epsilon = 1E-07f;

		private static readonly Vector2[] circleVertexList = new Vector2[25]
		{
			new Vector2(0f, 1f),
			new Vector2(0.2588f, 0.9659f),
			new Vector2(0.5f, 0.866f),
			new Vector2(0.7071f, 0.7071f),
			new Vector2(0.866f, 0.5f),
			new Vector2(0.9659f, 0.2588f),
			new Vector2(1f, 0f),
			new Vector2(0.9659f, -0.2588f),
			new Vector2(0.866f, -0.5f),
			new Vector2(0.7071f, -0.7071f),
			new Vector2(0.5f, -0.866f),
			new Vector2(0.2588f, -0.9659f),
			new Vector2(0f, -1f),
			new Vector2(-0.2588f, -0.9659f),
			new Vector2(-0.5f, -0.866f),
			new Vector2(-0.7071f, -0.7071f),
			new Vector2(-0.866f, -0.5f),
			new Vector2(-0.9659f, -0.2588f),
			new Vector2(-1f, -0f),
			new Vector2(-0.9659f, 0.2588f),
			new Vector2(-0.866f, 0.5f),
			new Vector2(-0.7071f, 0.7071f),
			new Vector2(-0.5f, 0.866f),
			new Vector2(-0.2588f, 0.9659f),
			new Vector2(0f, 1f)
		};

		internal static bool Is32Bit => IntPtr.Size == 4;

		internal static bool Is64Bit => IntPtr.Size == 8;

		public static void DrawCircleGizmo(Vector2 center, float radius)
		{
			Vector2 vector = circleVertexList[0] * radius + center;
			int num = circleVertexList.Length;
			for (int i = 1; i < num; i++)
			{
				Gizmos.DrawLine(vector, vector = circleVertexList[i] * radius + center);
			}
		}

		public static void DrawCircleGizmo(Vector2 center, float radius, Color color)
		{
			Gizmos.color = color;
			DrawCircleGizmo(center, radius);
		}

		public static void DrawOvalGizmo(Vector2 center, Vector2 size)
		{
			Vector2 b = size / 2f;
			Vector2 vector = Vector2.Scale(circleVertexList[0], b) + center;
			int num = circleVertexList.Length;
			for (int i = 1; i < num; i++)
			{
				Gizmos.DrawLine(vector, vector = Vector2.Scale(circleVertexList[i], b) + center);
			}
		}

		public static void DrawOvalGizmo(Vector2 center, Vector2 size, Color color)
		{
			Gizmos.color = color;
			DrawOvalGizmo(center, size);
		}

		public static void DrawRectGizmo(Rect rect)
		{
			Vector3 vector = new Vector3(rect.xMin, rect.yMin);
			Vector3 vector2 = new Vector3(rect.xMax, rect.yMin);
			Vector3 vector3 = new Vector3(rect.xMax, rect.yMax);
			Vector3 vector4 = new Vector3(rect.xMin, rect.yMax);
			Gizmos.DrawLine(vector, vector2);
			Gizmos.DrawLine(vector2, vector3);
			Gizmos.DrawLine(vector3, vector4);
			Gizmos.DrawLine(vector4, vector);
		}

		public static void DrawRectGizmo(Rect rect, Color color)
		{
			Gizmos.color = color;
			DrawRectGizmo(rect);
		}

		public static void DrawRectGizmo(Vector2 center, Vector2 size)
		{
			float num = size.x / 2f;
			float num2 = size.y / 2f;
			Vector3 vector = new Vector3(center.x - num, center.y - num2);
			Vector3 vector2 = new Vector3(center.x + num, center.y - num2);
			Vector3 vector3 = new Vector3(center.x + num, center.y + num2);
			Vector3 vector4 = new Vector3(center.x - num, center.y + num2);
			Gizmos.DrawLine(vector, vector2);
			Gizmos.DrawLine(vector2, vector3);
			Gizmos.DrawLine(vector3, vector4);
			Gizmos.DrawLine(vector4, vector);
		}

		public static void DrawRectGizmo(Vector2 center, Vector2 size, Color color)
		{
			Gizmos.color = color;
			DrawRectGizmo(center, size);
		}

		public static bool GameObjectIsCulledOnCurrentCamera(GameObject gameObject)
		{
			return (Camera.current.cullingMask & (1 << gameObject.layer)) == 0;
		}

		public static Color MoveColorTowards(Color color0, Color color1, float maxDelta)
		{
			float r = Mathf.MoveTowards(color0.r, color1.r, maxDelta);
			float g = Mathf.MoveTowards(color0.g, color1.g, maxDelta);
			float b = Mathf.MoveTowards(color0.b, color1.b, maxDelta);
			float a = Mathf.MoveTowards(color0.a, color1.a, maxDelta);
			return new Color(r, g, b, a);
		}

		public static float ApplyDeadZone(float value, float lowerDeadZone, float upperDeadZone)
		{
			float num = upperDeadZone - lowerDeadZone;
			if (value < 0f)
			{
				if (value > 0f - lowerDeadZone)
				{
					return 0f;
				}
				if (value < 0f - upperDeadZone)
				{
					return -1f;
				}
				return (value + lowerDeadZone) / num;
			}
			if (value < lowerDeadZone)
			{
				return 0f;
			}
			if (value > upperDeadZone)
			{
				return 1f;
			}
			return (value - lowerDeadZone) / num;
		}

		public static float ApplySmoothing(float thisValue, float lastValue, float deltaTime, float sensitivity)
		{
			if (Approximately(sensitivity, 1f))
			{
				return thisValue;
			}
			float maxDelta = deltaTime * sensitivity * 100f;
			if (IsNotZero(thisValue) && Sign(lastValue) != Sign(thisValue))
			{
				lastValue = 0f;
			}
			return Mathf.MoveTowards(lastValue, thisValue, maxDelta);
		}

		public static float ApplySnapping(float value, float threshold)
		{
			if (value < 0f - threshold)
			{
				return -1f;
			}
			if (value > threshold)
			{
				return 1f;
			}
			return 0f;
		}

		internal static bool TargetIsButton(InputControlType target)
		{
			if (target < InputControlType.Action1 || target > InputControlType.Action12)
			{
				if (target >= InputControlType.Button0)
				{
					return target <= InputControlType.Button19;
				}
				return false;
			}
			return true;
		}

		internal static bool TargetIsStandard(InputControlType target)
		{
			if (target < InputControlType.LeftStickUp || target > InputControlType.Action12)
			{
				if (target >= InputControlType.Command)
				{
					return target <= InputControlType.DPadY;
				}
				return false;
			}
			return true;
		}

		internal static bool TargetIsAlias(InputControlType target)
		{
			if (target >= InputControlType.Command)
			{
				return target <= InputControlType.RightCommand;
			}
			return false;
		}

		public static string ReadFromFile(string path)
		{
			StreamReader streamReader = new StreamReader(path);
			string result = streamReader.ReadToEnd();
			streamReader.Close();
			return result;
		}

		public static void WriteToFile(string path, string data)
		{
			StreamWriter streamWriter = new StreamWriter(path);
			streamWriter.Write(data);
			streamWriter.Flush();
			streamWriter.Close();
		}

		public static float Abs(float value)
		{
			if (!(value < 0f))
			{
				return value;
			}
			return 0f - value;
		}

		public static bool Approximately(float v1, float v2)
		{
			float num = v1 - v2;
			if (num >= -1E-07f)
			{
				return num <= 1E-07f;
			}
			return false;
		}

		public static bool Approximately(Vector2 v1, Vector2 v2)
		{
			if (Approximately(v1.x, v2.x))
			{
				return Approximately(v1.y, v2.y);
			}
			return false;
		}

		public static bool IsNotZero(float value)
		{
			if (!(value < -1E-07f))
			{
				return value > 1E-07f;
			}
			return true;
		}

		public static bool IsZero(float value)
		{
			if (value >= -1E-07f)
			{
				return value <= 1E-07f;
			}
			return false;
		}

		public static int Sign(float f)
		{
			if (!((double)f < 0.0))
			{
				return 1;
			}
			return -1;
		}

		public static bool AbsoluteIsOverThreshold(float value, float threshold)
		{
			if (!(value < 0f - threshold))
			{
				return value > threshold;
			}
			return true;
		}

		public static float NormalizeAngle(float angle)
		{
			while (angle < 0f)
			{
				angle += 360f;
			}
			while (angle > 360f)
			{
				angle -= 360f;
			}
			return angle;
		}

		public static float VectorToAngle(Vector2 vector)
		{
			if (IsZero(vector.x) && IsZero(vector.y))
			{
				return 0f;
			}
			return NormalizeAngle(Mathf.Atan2(vector.x, vector.y) * 57.29578f);
		}

		public static float Min(float v0, float v1)
		{
			if (!(v0 >= v1))
			{
				return v0;
			}
			return v1;
		}

		public static float Max(float v0, float v1)
		{
			if (!(v0 <= v1))
			{
				return v0;
			}
			return v1;
		}

		public static float Min(float v0, float v1, float v2, float v3)
		{
			float num = ((v0 >= v1) ? v1 : v0);
			float num2 = ((v2 >= v3) ? v3 : v2);
			if (!(num >= num2))
			{
				return num;
			}
			return num2;
		}

		public static float Max(float v0, float v1, float v2, float v3)
		{
			float num = ((v0 <= v1) ? v1 : v0);
			float num2 = ((v2 <= v3) ? v3 : v2);
			if (!(num <= num2))
			{
				return num;
			}
			return num2;
		}

		internal static float ValueFromSides(float negativeSide, float positiveSide)
		{
			float num = Abs(negativeSide);
			float num2 = Abs(positiveSide);
			if (Approximately(num, num2))
			{
				return 0f;
			}
			if (!(num > num2))
			{
				return num2;
			}
			return 0f - num;
		}

		internal static float ValueFromSides(float negativeSide, float positiveSide, bool invertSides)
		{
			if (invertSides)
			{
				return ValueFromSides(positiveSide, negativeSide);
			}
			return ValueFromSides(negativeSide, positiveSide);
		}

		public static void ArrayResize<T>(ref T[] array, int capacity)
		{
			if (array == null || capacity > array.Length)
			{
				Array.Resize(ref array, NextPowerOfTwo(capacity));
			}
		}

		public static void ArrayExpand<T>(ref T[] array, int capacity)
		{
			if (array == null || capacity > array.Length)
			{
				array = new T[NextPowerOfTwo(capacity)];
			}
		}

		public static void ArrayAppend<T>(ref T[] array, T item)
		{
			if (array == null)
			{
				array = new T[1];
				array[0] = item;
			}
			else
			{
				Array.Resize(ref array, array.Length + 1);
				array[array.Length - 1] = item;
			}
		}

		public static void ArrayAppend<T>(ref T[] array, T[] items)
		{
			if (array == null)
			{
				array = new T[items.Length];
				Array.Copy(items, array, items.Length);
			}
			else
			{
				Array.Resize(ref array, array.Length + items.Length);
				Array.ConstrainedCopy(items, 0, array, array.Length - items.Length, items.Length);
			}
		}

		public static int NextPowerOfTwo(int value)
		{
			if (value > 0)
			{
				value--;
				value |= value >> 1;
				value |= value >> 2;
				value |= value >> 4;
				value |= value >> 8;
				value |= value >> 16;
				value++;
				return value;
			}
			return 0;
		}

		public static string GetPlatformName(bool uppercase = true)
		{
			string windowsVersion = GetWindowsVersion();
			if (!uppercase)
			{
				return windowsVersion;
			}
			return windowsVersion.ToUpper();
		}

		private static string GetHumanUnderstandableWindowsVersion()
		{
			System.Version version = Environment.OSVersion.Version;
			if (version.Major == 6)
			{
				return version.Minor switch
				{
					3 => "8.1", 
					2 => "8", 
					1 => "7", 
					_ => "Vista", 
				};
			}
			if (version.Major == 5)
			{
				int minor = version.Minor;
				if ((uint)(minor - 1) <= 1u)
				{
					return "XP";
				}
				return "2000";
			}
			return version.Major.ToString();
		}

		public static string GetWindowsVersion()
		{
			string humanUnderstandableWindowsVersion = GetHumanUnderstandableWindowsVersion();
			string text = (Is32Bit ? "32Bit" : "64Bit");
			int systemBuildNumber = GetSystemBuildNumber();
			return "Windows " + humanUnderstandableWindowsVersion + " " + text + " Build " + systemBuildNumber;
		}

		public static int GetSystemBuildNumber()
		{
			return Environment.OSVersion.Version.Build;
		}

		public static void LoadScene(string sceneName)
		{
			UnityEngine.SceneManagement.SceneManager.LoadScene(sceneName);
		}

		internal static string PluginFileExtension()
		{
			return ".dll";
		}
	}
	[Serializable]
	public struct VersionInfo(int major, int minor, int patch, int build) : IComparable<VersionInfo>
	{
		[SerializeField]
		private int major = major;

		[SerializeField]
		private int minor = minor;

		[SerializeField]
		private int patch = patch;

		[SerializeField]
		private int build = build;

		public static VersionInfo Min => new VersionInfo(int.MinValue, int.MinValue, int.MinValue, int.MinValue);

		public static VersionInfo Max => new VersionInfo(int.MaxValue, int.MaxValue, int.MaxValue, int.MaxValue);

		public VersionInfo Next => new VersionInfo(major, minor, patch, build + 1);

		public int Build => build;

		public static VersionInfo InControlVersion()
		{
			return new VersionInfo
			{
				major = 1,
				minor = 8,
				patch = 4,
				build = 9364
			};
		}

		public static VersionInfo UnityVersion()
		{
			Match match = Regex.Match(Application.unityVersion, "^(\\d+)\\.(\\d+)\\.(\\d+)[a-zA-Z](\\d+)");
			return new VersionInfo
			{
				major = Convert.ToInt32(match.Groups[1].Value),
				minor = Convert.ToInt32(match.Groups[2].Value),
				patch = Convert.ToInt32(match.Groups[3].Value),
				build = Convert.ToInt32(match.Groups[4].Value)
			};
		}

		public int CompareTo(VersionInfo other)
		{
			if (major < other.major)
			{
				return -1;
			}
			if (major > other.major)
			{
				return 1;
			}
			if (minor < other.minor)
			{
				return -1;
			}
			if (minor > other.minor)
			{
				return 1;
			}
			if (patch < other.patch)
			{
				return -1;
			}
			if (patch > other.patch)
			{
				return 1;
			}
			if (build < other.build)
			{
				return -1;
			}
			if (build > other.build)
			{
				return 1;
			}
			return 0;
		}

		public static bool operator ==(VersionInfo a, VersionInfo b)
		{
			return a.CompareTo(b) == 0;
		}

		public static bool operator !=(VersionInfo a, VersionInfo b)
		{
			return a.CompareTo(b) != 0;
		}

		public static bool operator <=(VersionInfo a, VersionInfo b)
		{
			return a.CompareTo(b) <= 0;
		}

		public static bool operator >=(VersionInfo a, VersionInfo b)
		{
			return a.CompareTo(b) >= 0;
		}

		public static bool operator <(VersionInfo a, VersionInfo b)
		{
			return a.CompareTo(b) < 0;
		}

		public static bool operator >(VersionInfo a, VersionInfo b)
		{
			return a.CompareTo(b) > 0;
		}

		public override bool Equals(object other)
		{
			if (other is VersionInfo)
			{
				return this == (VersionInfo)other;
			}
			return false;
		}

		public override int GetHashCode()
		{
			return major.GetHashCode() ^ minor.GetHashCode() ^ patch.GetHashCode() ^ build.GetHashCode();
		}

		public override string ToString()
		{
			if (build == 0)
			{
				return $"{major}.{minor}.{patch}";
			}
			return $"{major}.{minor}.{patch} build {build}";
		}

		public string ToShortString()
		{
			if (build == 0)
			{
				return $"{major}.{minor}.{patch}";
			}
			return $"{major}.{minor}.{patch}b{build}";
		}
	}
	public class XInputDevice : InputDevice
	{
		private const float LowerDeadZone = 0.2f;

		private const float UpperDeadZone = 0.9f;

		private readonly XInputDeviceManager owner;

		private GamePadState state;

		public int DeviceIndex { get; private set; }

		public bool IsConnected => state.IsConnected;

		public XInputDevice(int deviceIndex, XInputDeviceManager owner)
			: base("XInput Controller")
		{
			this.owner = owner;
			DeviceIndex = deviceIndex;
			base.SortOrder = deviceIndex;
			base.Meta = "XInput Device #" + deviceIndex;
			base.DeviceClass = InputDeviceClass.Controller;
			base.DeviceStyle = InputDeviceStyle.XboxOne;
			AddControl(InputControlType.LeftStickLeft, "Left Stick Left", 0.2f, 0.9f);
			AddControl(InputControlType.LeftStickRight, "Left Stick Right", 0.2f, 0.9f);
			AddControl(InputControlType.LeftStickUp, "Left Stick Up", 0.2f, 0.9f);
			AddControl(InputControlType.LeftStickDown, "Left Stick Down", 0.2f, 0.9f);
			AddControl(InputControlType.RightStickLeft, "Right Stick Left", 0.2f, 0.9f);
			AddControl(InputControlType.RightStickRight, "Right Stick Right", 0.2f, 0.9f);
			AddControl(InputControlType.RightStickUp, "Right Stick Up", 0.2f, 0.9f);
			AddControl(InputControlType.RightStickDown, "Right Stick Down", 0.2f, 0.9f);
			AddControl(InputControlType.LeftTrigger, "Left Trigger", 0.2f, 0.9f);
			AddControl(InputControlType.RightTrigger, "Right Trigger", 0.2f, 0.9f);
			AddControl(InputControlType.DPadUp, "DPad Up", 0.2f, 0.9f);
			AddControl(InputControlType.DPadDown, "DPad Down", 0.2f, 0.9f);
			AddControl(InputControlType.DPadLeft, "DPad Left", 0.2f, 0.9f);
			AddControl(InputControlType.DPadRight, "DPad Right", 0.2f, 0.9f);
			AddControl(InputControlType.Action1, "A");
			AddControl(InputControlType.Action2, "B");
			AddControl(InputControlType.Action3, "X");
			AddControl(InputControlType.Action4, "Y");
			AddControl(InputControlType.LeftBumper, "Left Bumper");
			AddControl(InputControlType.RightBumper, "Right Bumper");
			AddControl(InputControlType.LeftStickButton, "Left Stick Button");
			AddControl(InputControlType.RightStickButton, "Right Stick Button");
			AddControl(InputControlType.View, "View");
			AddControl(InputControlType.Menu, "Menu");
		}

		public override void Update(ulong updateTick, float deltaTime)
		{
			GetState();
			UpdateLeftStickWithValue(state.ThumbSticks.Left.Vector, updateTick, deltaTime);
			UpdateRightStickWithValue(state.ThumbSticks.Right.Vector, updateTick, deltaTime);
			UpdateWithValue(InputControlType.LeftTrigger, state.Triggers.Left, updateTick, deltaTime);
			UpdateWithValue(InputControlType.RightTrigger, state.Triggers.Right, updateTick, deltaTime);
			UpdateWithState(InputControlType.DPadUp, state.DPad.Up == ButtonState.Pressed, updateTick, deltaTime);
			UpdateWithState(InputControlType.DPadDown, state.DPad.Down == ButtonState.Pressed, updateTick, deltaTime);
			UpdateWithState(InputControlType.DPadLeft, state.DPad.Left == ButtonState.Pressed, updateTick, deltaTime);
			UpdateWithState(InputControlType.DPadRight, state.DPad.Right == ButtonState.Pressed, updateTick, deltaTime);
			UpdateWithState(InputControlType.Action1, state.Buttons.A == ButtonState.Pressed, updateTick, deltaTime);
			UpdateWithState(InputControlType.Action2, state.Buttons.B == ButtonState.Pressed, updateTick, deltaTime);
			UpdateWithState(InputControlType.Action3, state.Buttons.X == ButtonState.Pressed, updateTick, deltaTime);
			UpdateWithState(InputControlType.Action4, state.Buttons.Y == ButtonState.Pressed, updateTick, deltaTime);
			UpdateWithState(InputControlType.LeftBumper, state.Buttons.LeftShoulder == ButtonState.Pressed, updateTick, deltaTime);
			UpdateWithState(InputControlType.RightBumper, state.Buttons.RightShoulder == ButtonState.Pressed, updateTick, deltaTime);
			UpdateWithState(InputControlType.LeftStickButton, state.Buttons.LeftStick == ButtonState.Pressed, updateTick, deltaTime);
			UpdateWithState(InputControlType.RightStickButton, state.Buttons.RightStick == ButtonState.Pressed, updateTick, deltaTime);
			UpdateWithState(InputControlType.View, state.Buttons.Start == ButtonState.Pressed, updateTick, deltaTime);
			UpdateWithState(InputControlType.Menu, state.Buttons.Back == ButtonState.Pressed, updateTick, deltaTime);
		}

		public override void Vibrate(float leftMotor, float rightMotor)
		{
			GamePad.SetVibration((PlayerIndex)DeviceIndex, leftMotor, rightMotor);
		}

		internal void GetState()
		{
			state = owner.GetState(DeviceIndex);
		}
	}
	public class XInputDeviceManager : InputDeviceManager
	{
		private readonly bool[] deviceConnected = new bool[4];

		private const int maxDevices = 4;

		private readonly RingBuffer<GamePadState>[] gamePadState = new RingBuffer<GamePadState>[4];

		private Thread thread;

		private readonly int timeStep;

		private int bufferSize;

		public XInputDeviceManager()
		{
			if (InputManager.XInputUpdateRate == 0)
			{
				timeStep = Mathf.FloorToInt(Time.fixedDeltaTime * 1000f);
			}
			else
			{
				timeStep = Mathf.FloorToInt(1f / (float)InputManager.XInputUpdateRate * 1000f);
			}
			bufferSize = (int)Math.Max(InputManager.XInputBufferSize, 1u);
			for (int i = 0; i < 4; i++)
			{
				gamePadState[i] = new RingBuffer<GamePadState>(bufferSize);
			}
			StartWorker();
			for (int j = 0; j < 4; j++)
			{
				devices.Add(new XInputDevice(j, this));
			}
			Update(0uL, 0f);
		}

		private void StartWorker()
		{
			if (thread == null)
			{
				thread = new Thread(Worker);
				thread.IsBackground = true;
				thread.Start();
			}
		}

		private void StopWorker()
		{
			if (thread != null)
			{
				thread.Abort();
				thread.Join();
				thread = null;
			}
		}

		private void Worker()
		{
			while (true)
			{
				for (int i = 0; i < 4; i++)
				{
					gamePadState[i].Enqueue(GamePad.GetState((PlayerIndex)i));
				}
				Thread.Sleep(timeStep);
			}
		}

		internal GamePadState GetState(int deviceIndex)
		{
			return gamePadState[deviceIndex].Dequeue();
		}

		public override void Update(ulong updateTick, float deltaTime)
		{
			for (int i = 0; i < 4; i++)
			{
				XInputDevice xInputDevice = devices[i] as XInputDevice;
				if (!xInputDevice.IsConnected)
				{
					xInputDevice.GetState();
				}
				if (xInputDevice.IsConnected != deviceConnected[i])
				{
					if (xInputDevice.IsConnected)
					{
						InputManager.AttachDevice(xInputDevice);
					}
					else
					{
						InputManager.DetachDevice(xInputDevice);
					}
					deviceConnected[i] = xInputDevice.IsConnected;
				}
			}
		}

		public override void Destroy()
		{
			StopWorker();
		}

		public static bool CheckPlatformSupport(ICollection<string> errors)
		{
			if (Application.platform != RuntimePlatform.WindowsPlayer && Application.platform != RuntimePlatform.WindowsEditor)
			{
				return false;
			}
			try
			{
				GamePad.GetState(PlayerIndex.One);
			}
			catch (DllNotFoundException ex)
			{
				errors?.Add(ex.Message + ".dll could not be found or is missing a dependency.");
				return false;
			}
			return true;
		}

		internal static void Enable()
		{
			List<string> list = new List<string>();
			if (CheckPlatformSupport(list))
			{
				InputManager.HideDevicesWithProfile(typeof(Xbox360WindowsUnityProfile));
				InputManager.HideDevicesWithProfile(typeof(XboxOneWindowsUnityProfile));
				InputManager.HideDevicesWithProfile(typeof(XboxOneWindows10UnityProfile));
				InputManager.HideDevicesWithProfile(typeof(XboxOneWindows10AEUnityProfile));
				InputManager.HideDevicesWithProfile(typeof(LogitechF310ModeXWindowsUnityProfile));
				InputManager.HideDevicesWithProfile(typeof(LogitechF510ModeXWindowsUnityProfile));
				InputManager.HideDevicesWithProfile(typeof(LogitechF710ModeXWindowsUnityProfile));
				InputManager.AddDeviceManager<XInputDeviceManager>();
				return;
			}
			foreach (string item in list)
			{
				Logger.LogError(item);
			}
		}
	}
	public class TestInputManager : MonoBehaviour
	{
		public Font font;

		private readonly GUIStyle style = new GUIStyle();

		private readonly List<LogMessage> logMessages = new List<LogMessage>();

		private bool isPaused;

		private void OnEnable()
		{
			Application.targetFrameRate = -1;
			QualitySettings.vSyncCount = 0;
			isPaused = false;
			Time.timeScale = 1f;
			Logger.OnLogMessage += delegate(LogMessage logMessage)
			{
				logMessages.Add(logMessage);
			};
			InputManager.OnDeviceAttached += delegate(InputDevice inputDevice)
			{
				UnityEngine.Debug.Log("Attached: " + inputDevice.Name);
			};
			InputManager.OnDeviceDetached += delegate(InputDevice inputDevice)
			{
				UnityEngine.Debug.Log("Detached: " + inputDevice.Name);
			};
			InputManager.OnActiveDeviceChanged += delegate(InputDevice inputDevice)
			{
				UnityEngine.Debug.Log("Active device changed to: " + inputDevice.Name);
			};
			InputManager.OnUpdate += HandleInputUpdate;
		}

		private void HandleInputUpdate(ulong updateTick, float deltaTime)
		{
			CheckForPauseButton();
			int count = InputManager.Devices.Count;
			for (int i = 0; i < count; i++)
			{
				InputDevice inputDevice = InputManager.Devices[i];
				inputDevice.Vibrate(inputDevice.LeftTrigger, inputDevice.RightTrigger);
				Color color = Color.HSVToRGB(Mathf.Repeat(Time.realtimeSinceStartup, 1f), 1f, 1f);
				inputDevice.SetLightColor(color.r, color.g, color.b);
			}
		}

		private void Start()
		{
		}

		private void Update()
		{
			if (Input.GetKeyDown(KeyCode.R))
			{
				Utility.LoadScene("TestInputManager");
			}
			if (Input.GetKeyDown(KeyCode.E))
			{
				InputManager.Enabled = !InputManager.Enabled;
			}
		}

		private void CheckForPauseButton()
		{
			if (Input.GetKeyDown(KeyCode.P) || InputManager.CommandWasPressed)
			{
				Time.timeScale = (isPaused ? 1f : 0f);
				isPaused = !isPaused;
			}
		}

		private void SetColor(Color color)
		{
			style.normal.textColor = color;
		}

		private void OnGUI()
		{
			int num = Mathf.FloorToInt(Screen.width / Mathf.Max(1, InputManager.Devices.Count));
			int num2 = 10;
			int num3 = 10;
			GUI.skin.font = font;
			SetColor(Color.white);
			string text = "Devices:";
			text = text + " (Platform: " + InputManager.Platform + ")";
			text = text + " " + InputManager.ActiveDevice.Direction.Vector.ToString();
			if (isPaused)
			{
				SetColor(Color.red);
				text = "+++ PAUSED +++";
			}
			GUI.Label(new Rect(num2, num3, num2 + num, num3 + 10), text, style);
			SetColor(Color.white);
			foreach (InputDevice device in InputManager.Devices)
			{
				Color color = (device.IsActive ? new Color(0.9f, 0.7f, 0.2f) : Color.white);
				bool flag = InputManager.ActiveDevice == device;
				if (flag)
				{
					color = new Color(1f, 0.9f, 0f);
				}
				num3 = 35;
				if (device.IsUnknown)
				{
					SetColor(Color.red);
					GUI.Label(new Rect(num2, num3, num2 + num, num3 + 10), "Unknown Device", style);
				}
				else
				{
					SetColor(color);
					GUI.Label(new Rect(num2, num3, num2 + num, num3 + 10), device.Name, style);
				}
				num3 += 15;
				SetColor(color);
				if (device.IsUnknown)
				{
					GUI.Label(new Rect(num2, num3, num2 + num, num3 + 10), device.Meta, style);
					num3 += 15;
				}
				GUI.Label(new Rect(num2, num3, num2 + num, num3 + 10), "Style: " + device.DeviceStyle, style);
				num3 += 15;
				GUI.Label(new Rect(num2, num3, num2 + num, num3 + 10), "GUID: " + device.GUID.ToString(), style);
				num3 += 15;
				GUI.Label(new Rect(num2, num3, num2 + num, num3 + 10), "SortOrder: " + device.SortOrder, style);
				num3 += 15;
				GUI.Label(new Rect(num2, num3, num2 + num, num3 + 10), "LastInputTick: " + device.LastInputTick, style);
