namespace GUIBlendModes
{
	public static class BlendMaterials
	{
		public static Material[] Materials;

		public static bool Initialized;

		public static void Initialize()
		{
			Materials = new Material[84];
			for (int i = 0; i < 21; i++)
			{
				Materials[i] = Resources.Load<Material>("UIBlend" + (BlendMode)(i + 1)/*cast due to constrained. prefix*/);
			}
			for (int j = 21; j < 42; j++)
			{
				Materials[j] = Resources.Load<Material>("UIBlend" + ((BlendMode)(j - 20)/*cast due to constrained. prefix*/).ToString() + "Optimized");
			}
			for (int k = 42; k < 63; k++)
			{
				Materials[k] = Resources.Load<Material>("UIFontBlend" + (BlendMode)(k - 41)/*cast due to constrained. prefix*/);
			}
			for (int l = 63; l < 84; l++)
			{
				Materials[l] = Resources.Load<Material>("UIFontBlend" + ((BlendMode)(l - 62)/*cast due to constrained. prefix*/).ToString() + "Optimized");
			}
			Initialized = true;
		}

		public static Material GetMaterial(BlendMode mode, bool font, bool optimized)
		{
			if (!Initialized)
			{
				Initialize();
			}
			if (font)
			{
				if (mode != BlendMode.Normal)
				{
					return Materials[(int)(mode - 1 + (optimized ? 63 : 42))];
				}
				return null;
			}
			if (mode != BlendMode.Normal)
			{
				return Materials[(int)(mode - 1 + (optimized ? 21 : 0))];
			}
			return null;
		}
	}
	public enum BlendMode
	{
		Normal,
		Darken,
		Multiply,
		ColorBurn,
		LinearBurn,
		DarkerColor,
		Lighten,
		Screen,
		ColorDodge,
		LinearDodge,
		LighterColor,
		Overlay,
		SoftLight,
		HardLight,
		VividLight,
		LinearLight,
		PinLight,
		HardMix,
		Difference,
		Exclusion,
		Subtract,
		Divide
	}
	[AddComponentMenu("UI/Effects/Blend Mode")]
	[RequireComponent(typeof(MaskableGraphic))]
	[ExecuteInEditMode]
	public class UIBlendMode : MonoBehaviour
	{
		[SerializeField]
		private BlendMode editorBlendMode;

		private BlendMode blendMode;

		[SerializeField]
		private bool editorShaderOptimization;

		private bool shaderOptimization;

		private MaskableGraphic source;

		private bool isDisabled;

		public BlendMode BlendMode
		{
			get
			{
				return blendMode;
			}
			set
			{
				SetBlendMode(value, ShaderOptimization);
			}
		}

		public bool ShaderOptimization
		{
			get
			{
				return shaderOptimization;
			}
			set
			{
				SetBlendMode(BlendMode, value);
			}
		}

		private void OnEnable()
		{
			isDisabled = false;
			SetBlendMode(editorBlendMode, editorShaderOptimization);
		}

		private void OnDisable()
		{
			isDisabled = true;
			SetBlendMode(BlendMode.Normal);
		}

		public void SetBlendMode(BlendMode blendMode, bool shaderOptimization = false)
		{
			if (this.blendMode != blendMode || this.shaderOptimization != shaderOptimization)
			{
				if (!source)
				{
					source = GetComponent<MaskableGraphic>();
				}
				source.material = BlendMaterials.GetMaterial(blendMode, source is Text, shaderOptimization);
				this.blendMode = blendMode;
				this.shaderOptimization = shaderOptimization;
				if (!isDisabled)
				{
					editorBlendMode = blendMode;
					editorShaderOptimization = shaderOptimization;
				}
			}
		}

		public void SyncEditor()
		{
			if (Application.isEditor && !isDisabled && (BlendMode != editorBlendMode || ShaderOptimization != editorShaderOptimization))
			{
				SetBlendMode(editorBlendMode, editorShaderOptimization);
			}
		}
	}
