				PlayMakerFSM.BroadcastEvent(eventName);
			}
			else if (eventTarget.eventTarget == ProxyEventTarget.Owner || eventTarget.eventTarget == ProxyEventTarget.GameObject)
			{
				PlayMakerUtils.SendEventToGameObject(fromFsm, eventTarget.gameObject, eventName, eventTarget.includeChildren);
			}
			else if (eventTarget.eventTarget == ProxyEventTarget.FsmComponent)
			{
				eventTarget.fsmComponent.SendEvent(eventName);
			}
			return true;
		}
	}
	public enum ProxyEventTarget
	{
		Owner,
		GameObject,
		BroadCastAll,
		FsmComponent
	}
	[Serializable]
	public class PlayMakerEventTarget
	{
		public ProxyEventTarget eventTarget;

		public GameObject gameObject;

		public bool includeChildren = true;

		public PlayMakerFSM fsmComponent;

		public PlayMakerEventTarget()
		{
		}

		public PlayMakerEventTarget(bool includeChildren = true)
		{
			this.includeChildren = includeChildren;
		}

		public PlayMakerEventTarget(ProxyEventTarget evenTarget, bool includeChildren = true)
		{
			eventTarget = evenTarget;
			this.includeChildren = includeChildren;
		}
	}
}
namespace HutongGames.PlayMaker.Actions
{
	[ActionCategory("Physics 2d")]
	[Tooltip("Adds a 2d force to a Game Object. Use Vector2 variable and/or Float variables for each axis. I added the ability to limit speed.")]
	public class AddForce2dV2 : RigidBody2dActionBase
	{
		[RequiredField]
		[CheckForComponent(typeof(Rigidbody2D))]
		[Tooltip("The GameObject to apply the force to.")]
		public FsmOwnerDefault gameObject;

		[UIHint(UIHint.Variable)]
		[Tooltip("Optionally apply the force at a position on the object. This will also add some torque. The position is often returned from MousePick or GetCollision2dInfo actions.")]
		public FsmVector2 atPosition;

		[UIHint(UIHint.Variable)]
		[Tooltip("A Vector2 force to add. Optionally override any axis with the X, Y parameters.")]
		public FsmVector2 vector;

		[Tooltip("Force along the X axis. To leave unchanged, set to 'None'.")]
		public FsmFloat x;

		[Tooltip("Force along the Y axis. To leave unchanged, set to 'None'.")]
		public FsmFloat y;

		[Tooltip("A Vector3 force to add. z is ignored")]
		public FsmVector3 vector3;

		public FsmFloat maxSpeed;

		public FsmFloat maxSpeedX;

		public FsmFloat maxSpeedY;

		[Tooltip("Repeat every frame while the state is active.")]
		public bool everyFrame;

		public override void Reset()
		{
			gameObject = null;
			atPosition = new FsmVector2
			{
				UseVariable = true
			};
			vector = null;
			vector3 = new FsmVector3
			{
				UseVariable = true
			};
			x = new FsmFloat
			{
				UseVariable = true
			};
			y = new FsmFloat
			{
				UseVariable = true
			};
			maxSpeed = null;
			maxSpeedX = null;
			maxSpeedY = null;
			everyFrame = false;
		}

		public override void OnPreprocess()
		{
			base.OnPreprocess();
			base.Fsm.HandleFixedUpdate = true;
		}

		public override void OnEnter()
		{
			CacheRigidBody2d(base.Fsm.GetOwnerDefaultTarget(gameObject));
			DoAddForce();
			if (!everyFrame)
			{
				Finish();
			}
		}

		public override void OnFixedUpdate()
		{
			DoAddForce();
		}

		private void DoAddForce()
		{
			if (!rb2d)
			{
				return;
			}
			Vector2 force = (vector.IsNone ? new Vector2(x.Value, y.Value) : vector.Value);
			if (!vector3.IsNone)
			{
				force.x = vector3.Value.x;
				force.y = vector3.Value.y;
			}
			if (!x.IsNone)
			{
				force.x = x.Value;
			}
			if (!y.IsNone)
			{
				force.y = y.Value;
			}
			if (!atPosition.IsNone)
			{
				rb2d.AddForceAtPosition(force, atPosition.Value);
			}
			else
			{
				rb2d.AddForce(force);
			}
			if (maxSpeedX != null)
			{
				Vector2 velocity = rb2d.velocity;
				if (velocity.x > maxSpeedX.Value)
				{
					velocity = new Vector2(maxSpeedX.Value, velocity.y);
				}
				if (velocity.x < 0f - maxSpeedX.Value)
				{
					velocity = new Vector2(0f - maxSpeedX.Value, velocity.y);
				}
				rb2d.velocity = velocity;
			}
			if (maxSpeedY != null)
			{
				Vector2 velocity2 = rb2d.velocity;
				if (velocity2.y > maxSpeedY.Value)
				{
					velocity2 = new Vector2(velocity2.x, maxSpeedY.Value);
				}
				if (velocity2.y < 0f - maxSpeedY.Value)
				{
					velocity2 = new Vector2(velocity2.x, 0f - maxSpeedY.Value);
				}
				rb2d.velocity = velocity2;
			}
			if (maxSpeed != null)
			{
				Vector2 velocity3 = rb2d.velocity;
				velocity3 = Vector2.ClampMagnitude(velocity3, maxSpeed.Value);
				rb2d.velocity = velocity3;
			}
		}
	}
	[ActionCategory(ActionCategory.Audio)]
	[Tooltip("Plays the Audio Clip set with Set Audio Clip or in the Audio Source inspector on a Game Object. Optionally plays a one shot Audio Clip.")]
	public class AudioPlayV2 : FsmStateAction
	{
		[RequiredField]
		[CheckForComponent(typeof(AudioSource))]
		[Tooltip("The GameObject with an AudioSource component.")]
		public FsmOwnerDefault gameObject;

		[HasFloatSlider(0f, 1f)]
		[Tooltip("Set the volume.")]
		public FsmFloat volume;

		[ObjectType(typeof(AudioClip))]
		[Tooltip("Optionally play a 'one shot' AudioClip. NOTE: Volume cannot be adjusted while playing a 'one shot' AudioClip.")]
		public FsmObject oneShotClip;

		[Tooltip("Event to send when the AudioClip finishes playing.")]
		public FsmEvent finishedEvent;

		private AudioSource audio;

		public override void Reset()
		{
			gameObject = null;
			volume = 1f;
			oneShotClip = null;
			finishedEvent = null;
		}

		public override void OnEnter()
		{
			GameObject ownerDefaultTarget = base.Fsm.GetOwnerDefaultTarget(gameObject);
			if (ownerDefaultTarget != null)
			{
				audio = ownerDefaultTarget.GetComponent<AudioSource>();
				if (audio != null)
				{
					AudioClip audioClip = oneShotClip.Value as AudioClip;
					if (audioClip == null)
					{
						if (!audio.isPlaying)
						{
							audio.Play();
						}
						if (!volume.IsNone)
						{
							audio.volume = volume.Value;
						}
					}
					else if (!volume.IsNone)
					{
						audio.PlayOneShot(audioClip, volume.Value);
					}
					else
					{
						audio.PlayOneShot(audioClip);
					}
					return;
				}
			}
			Finish();
		}

		public override void OnUpdate()
		{
			if (audio == null)
			{
				Finish();
			}
			else if (!audio.isPlaying)
			{
				base.Fsm.Event(finishedEvent);
				Finish();
			}
			else if (!volume.IsNone && volume.Value != audio.volume)
			{
				audio.volume = volume.Value;
			}
		}
	}
	[ActionCategory("Physics 2d")]
	[Tooltip("Detect 2D collisions between the Owner of this FSM and other Game Objects that have RigidBody2D components.\nNOTE: The system events, COLLISION ENTER 2D, COLLISION STAY 2D, and COLLISION EXIT 2D are sent automatically on collisions with any object. Use this action to filter collisions by Tag.")]
	public class Collision2dEventLayer : FsmStateAction
	{
		[Tooltip("The type of collision to detect.")]
		public PlayMakerUnity2d.Collision2DType collision;

		[UIHint(UIHint.Tag)]
		[Tooltip("Filter by Tag.")]
		public FsmString collideTag;

		[UIHint(UIHint.Layer)]
		[Tooltip("Filter by Layer.")]
		public FsmInt collideLayer;

		[RequiredField]
		[Tooltip("Event to send if a collision is detected.")]
		public FsmEvent sendEvent;

		[UIHint(UIHint.Variable)]
		[Tooltip("Store the GameObject that collided with the Owner of this FSM.")]
		public FsmGameObject storeCollider;

		[UIHint(UIHint.Variable)]
		[Tooltip("Store the force of the collision. NOTE: Use Get Collision Info to get more info about the collision.")]
		public FsmFloat storeForce;

		private PlayMakerUnity2DProxy _proxy;

		public override void Reset()
		{
			collision = PlayMakerUnity2d.Collision2DType.OnCollisionEnter2D;
			collideTag = new FsmString
			{
				UseVariable = true
			};
			sendEvent = null;
			storeCollider = null;
			storeForce = null;
		}

		public override void OnEnter()
		{
			_proxy = base.Owner.GetComponent<PlayMakerUnity2DProxy>();
			if (_proxy == null)
			{
				_proxy = base.Owner.AddComponent<PlayMakerUnity2DProxy>();
			}
			switch (collision)
			{
			case PlayMakerUnity2d.Collision2DType.OnCollisionEnter2D:
				_proxy.AddOnCollisionEnter2dDelegate(DoCollisionEnter2D);
				break;
			case PlayMakerUnity2d.Collision2DType.OnCollisionStay2D:
				_proxy.AddOnCollisionStay2dDelegate(DoCollisionStay2D);
				break;
			case PlayMakerUnity2d.Collision2DType.OnCollisionExit2D:
				_proxy.AddOnCollisionExit2dDelegate(DoCollisionExit2D);
				break;
			}
		}

		public override void OnExit()
		{
			if (!(_proxy == null))
			{
				switch (collision)
				{
				case PlayMakerUnity2d.Collision2DType.OnCollisionEnter2D:
					_proxy.RemoveOnCollisionEnter2dDelegate(DoCollisionEnter2D);
					break;
				case PlayMakerUnity2d.Collision2DType.OnCollisionStay2D:
					_proxy.RemoveOnCollisionStay2dDelegate(DoCollisionStay2D);
					break;
				case PlayMakerUnity2d.Collision2DType.OnCollisionExit2D:
					_proxy.RemoveOnCollisionExit2dDelegate(DoCollisionExit2D);
					break;
				}
			}
		}

		private void StoreCollisionInfo(Collision2D collisionInfo)
		{
			storeCollider.Value = collisionInfo.gameObject;
			storeForce.Value = collisionInfo.relativeVelocity.magnitude;
		}

		public new void DoCollisionEnter2D(Collision2D collisionInfo)
		{
			if (collision == PlayMakerUnity2d.Collision2DType.OnCollisionEnter2D && (collisionInfo.collider.gameObject.tag == collideTag.Value || collideTag.IsNone || string.IsNullOrEmpty(collideTag.Value)) && (collisionInfo.gameObject.layer == collideLayer.Value || collideLayer.IsNone))
			{
				StoreCollisionInfo(collisionInfo);
				base.Fsm.Event(sendEvent);
			}
		}

		public new void DoCollisionStay2D(Collision2D collisionInfo)
		{
			if (collision == PlayMakerUnity2d.Collision2DType.OnCollisionStay2D && (collisionInfo.collider.gameObject.tag == collideTag.Value || collideTag.IsNone || string.IsNullOrEmpty(collideTag.Value)) && (collisionInfo.gameObject.layer == collideLayer.Value || collideLayer.IsNone))
			{
				StoreCollisionInfo(collisionInfo);
				base.Fsm.Event(sendEvent);
			}
		}

		public new void DoCollisionExit2D(Collision2D collisionInfo)
		{
			if (collision == PlayMakerUnity2d.Collision2DType.OnCollisionExit2D && (collisionInfo.collider.gameObject.tag == collideTag.Value || collideTag.IsNone || string.IsNullOrEmpty(collideTag.Value)) && (collisionInfo.gameObject.layer == collideLayer.Value || collideLayer.IsNone))
			{
				StoreCollisionInfo(collisionInfo);
				base.Fsm.Event(sendEvent);
			}
		}

		public override string ErrorCheck()
		{
			string text = string.Empty;
			if (base.Owner != null && base.Owner.GetComponent<Collider2D>() == null && base.Owner.GetComponent<Rigidbody2D>() == null)
			{
				text += "Owner requires a RigidBody2D or Collider2D!\n";
			}
			return text;
		}
	}
	[ActionCategory(ActionCategory.Transform)]
	[Tooltip("Rotates a 2d Game Object on it's z axis so its forward vector points at a Target. Rotates th eobject per frame via speed.")]
	public class LookAt2dGameObjectSmooth : FsmStateAction
	{
		[RequiredField]
		[Tooltip("The GameObject to rotate.")]
		public FsmOwnerDefault gameObject;

		[Tooltip("The GameObject to Look At.")]
		public FsmGameObject targetObject;

		[Tooltip("Set the GameObject starting offset. In degrees. 0 if your object is facing right, 180 if facing left etc...")]
		public FsmFloat rotationOffset;

		[RequiredField]
		[Tooltip("Speed the object rotates at to meet its target angle (in degrees per frame).")]
		public FsmFloat speed;

		[Title("Draw Debug Line")]
		[Tooltip("Draw a debug line from the GameObject to the Target.")]
		public FsmBool debug;

		[Tooltip("Color to use for the debug line.")]
		public FsmColor debugLineColor;

		private GameObject go;

		private GameObject goTarget;

		private Vector3 lookAtPos;

		public override void Reset()
		{
			gameObject = null;
			targetObject = null;
			debug = false;
			debugLineColor = Color.green;
		}

		public override void OnEnter()
		{
			DoLookAt();
		}

		public override void OnUpdate()
		{
			DoLookAt();
		}

		private void DoLookAt()
		{
			go = base.Fsm.GetOwnerDefaultTarget(gameObject);
			goTarget = targetObject.Value;
			if (go == null || targetObject == null)
			{
				return;
			}
			float y = goTarget.transform.position.y - go.transform.position.y;
			float x = goTarget.transform.position.x - go.transform.position.x;
			float num;
			for (num = Mathf.Atan2(y, x) * (180f / (float)Math.PI); num < 0f; num += 360f)
			{
			}
			if (go.transform.eulerAngles.z < num - rotationOffset.Value)
			{
				go.transform.Rotate(0f, 0f, speed.Value);
				if (go.transform.eulerAngles.z > num - rotationOffset.Value)
				{
					go.transform.rotation = Quaternion.Euler(0f, 0f, num - rotationOffset.Value);
				}
			}
			if (go.transform.eulerAngles.z > num - rotationOffset.Value)
			{
				go.transform.Rotate(0f, 0f, 0f - speed.Value);
				if (go.transform.eulerAngles.z < num - rotationOffset.Value)
				{
					go.transform.rotation = Quaternion.Euler(0f, 0f, num - rotationOffset.Value);
				}
			}
			if (debug.Value)
			{
				UnityEngine.Debug.DrawLine(go.transform.position, goTarget.transform.position, debugLineColor.Value);
			}
		}
	}
