		[Tooltip("Author defined Reference of the PlayMaker ArrayList Proxy component to store the concatenation ( necessary if several component coexists on the same GameObject")]
		public FsmString reference;

		[ActionSection("ArrayLists to concatenate")]
		[CompoundArray("ArrayLists", "ArrayList GameObject", "Reference")]
		[RequiredField]
		[Tooltip("The GameObject with the PlayMaker ArrayList Proxy component to copy to")]
		[ObjectType(typeof(PlayMakerArrayListProxy))]
		public FsmOwnerDefault[] arrayListGameObjectTargets;

		[Tooltip("Author defined Reference of the PlayMaker ArrayList Proxy component to copy to ( necessary if several component coexists on the same GameObject")]
		public FsmString[] referenceTargets;

		public override void Reset()
		{
			gameObject = null;
			reference = null;
			arrayListGameObjectTargets = null;
			referenceTargets = null;
		}

		public override void OnEnter()
		{
			if (SetUpArrayListProxyPointer(base.Fsm.GetOwnerDefaultTarget(gameObject), reference.Value))
			{
				DoArrayListConcat(proxy.arrayList);
			}
			Finish();
		}

		public void DoArrayListConcat(ArrayList source)
		{
			if (!isProxyValid())
			{
				return;
			}
			for (int i = 0; i < arrayListGameObjectTargets.Length; i++)
			{
				if (!SetUpArrayListProxyPointer(base.Fsm.GetOwnerDefaultTarget(arrayListGameObjectTargets[i]), referenceTargets[i].Value) || !isProxyValid())
				{
					continue;
				}
				foreach (object array in proxy.arrayList)
				{
					source.Add(array);
					UnityEngine.Debug.Log("count " + source.Count);
				}
			}
		}
	}
	[ActionCategory("ArrayMaker/ArrayList")]
	[Tooltip("Check if an item is contains in a particula PlayMaker ArrayList Proxy component")]
	public class ArrayListContains : ArrayListActions
	{
		[ActionSection("Set up")]
		[RequiredField]
		[Tooltip("The gameObject with the PlayMaker ArrayList Proxy component")]
		[CheckForComponent(typeof(PlayMakerArrayListProxy))]
		public FsmOwnerDefault gameObject;

		[Tooltip("Author defined Reference of the PlayMaker ArrayList Proxy component (necessary if several component coexists on the same GameObject)")]
		[UIHint(UIHint.FsmString)]
		public FsmString reference;

		[ActionSection("Data")]
		[RequiredField]
		[Tooltip("The variable to check.")]
		public FsmVar variable;

		[ActionSection("Result")]
		[Tooltip("Store in a bool wether it contains or not that element (described below)")]
		[UIHint(UIHint.Variable)]
		public FsmBool isContained;

		[Tooltip("Event sent if this arraList contains that element ( described below)")]
		[UIHint(UIHint.FsmEvent)]
		public FsmEvent isContainedEvent;

		[Tooltip("Event sent if this arraList does not contains that element ( described below)")]
		[UIHint(UIHint.FsmEvent)]
		public FsmEvent isNotContainedEvent;

		public override void Reset()
		{
			gameObject = null;
			reference = null;
			variable = null;
			isContained = null;
			isContainedEvent = null;
			isNotContainedEvent = null;
		}

		public override void OnEnter()
		{
			if (SetUpArrayListProxyPointer(base.Fsm.GetOwnerDefaultTarget(gameObject), reference.Value))
			{
				doesArrayListContains();
			}
			Finish();
		}

		public void doesArrayListContains()
		{
			if (isProxyValid())
			{
				bool flag = false;
				PlayMakerUtils.RefreshValueFromFsmVar(base.Fsm, variable);
				switch (variable.Type)
				{
				case VariableType.Bool:
					flag = proxy.arrayList.Contains(variable.boolValue);
					break;
				case VariableType.Color:
					flag = proxy.arrayList.Contains(variable.colorValue);
					break;
				case VariableType.Float:
					flag = proxy.arrayList.Contains(variable.floatValue);
					break;
				case VariableType.GameObject:
					flag = proxy.arrayList.Contains(variable.gameObjectValue);
					break;
				case VariableType.Int:
					flag = proxy.arrayList.Contains(variable.intValue);
					break;
				case VariableType.Material:
					flag = proxy.arrayList.Contains(variable.materialValue);
					break;
				case VariableType.Object:
					flag = proxy.arrayList.Contains(variable.objectReference);
					break;
				case VariableType.Quaternion:
					flag = proxy.arrayList.Contains(variable.quaternionValue);
					break;
				case VariableType.Rect:
					flag = proxy.arrayList.Contains(variable.rectValue);
					break;
				case VariableType.String:
					flag = proxy.arrayList.Contains(variable.stringValue);
					break;
				case VariableType.Texture:
					flag = proxy.arrayList.Contains(variable.textureValue);
					break;
				case VariableType.Vector3:
					flag = proxy.arrayList.Contains(variable.vector3Value);
					break;
				case VariableType.Vector2:
					flag = proxy.arrayList.Contains(variable.vector2Value);
					break;
				}
				isContained.Value = flag;
				if (flag)
				{
					base.Fsm.Event(isContainedEvent);
				}
				else
				{
					base.Fsm.Event(isNotContainedEvent);
				}
			}
		}
	}
	[ActionCategory("ArrayMaker/ArrayList")]
	[Tooltip("Copy elements from one PlayMaker ArrayList Proxy component to another")]
	public class ArrayListCopyTo : ArrayListActions
	{
		[ActionSection("Set up")]
		[RequiredField]
		[Tooltip("The gameObject with the PlayMaker ArrayList Proxy component to copy from")]
		[CheckForComponent(typeof(PlayMakerArrayListProxy))]
		public FsmOwnerDefault gameObject;

		[Tooltip("Author defined Reference of the PlayMaker ArrayList Proxy component to copy from ( necessary if several component coexists on the same GameObject")]
		public FsmString reference;

		[ActionSection("Result")]
		[RequiredField]
		[Tooltip("The gameObject with the PlayMaker ArrayList Proxy component to copy to")]
		[CheckForComponent(typeof(PlayMakerArrayListProxy))]
		public FsmOwnerDefault gameObjectTarget;

		[Tooltip("Author defined Reference of the PlayMaker ArrayList Proxy component to copy to ( necessary if several component coexists on the same GameObject")]
		public FsmString referenceTarget;

		[Tooltip("Optional start index to copy from the source, if not set, starts from the beginning")]
		public FsmInt startIndex;

		[Tooltip("Optional amount of elements to copy, If not set, will copy all from start index.")]
		public FsmInt count;

		public override void Reset()
		{
			gameObject = null;
			reference = null;
			gameObjectTarget = null;
			referenceTarget = null;
			startIndex = new FsmInt
			{
				UseVariable = true
			};
			count = new FsmInt
			{
				UseVariable = true
			};
		}

		public override void OnEnter()
		{
			if (SetUpArrayListProxyPointer(base.Fsm.GetOwnerDefaultTarget(gameObject), reference.Value))
			{
				DoArrayListCopyTo(proxy.arrayList);
			}
			Finish();
		}

		public void DoArrayListCopyTo(ArrayList source)
		{
			if (!isProxyValid() || !SetUpArrayListProxyPointer(base.Fsm.GetOwnerDefaultTarget(gameObjectTarget), referenceTarget.Value) || !isProxyValid())
			{
				return;
			}
			int value = startIndex.Value;
			int num = source.Count;
			int value2 = source.Count;
			if (!count.IsNone)
			{
				value2 = count.Value;
			}
			if (value < 0 || value >= source.Count)
			{
				LogError("start index out of range");
				return;
			}
			if (count.Value < 0)
			{
				LogError("count can not be negative");
				return;
			}
			num = Mathf.Min(value + value2, source.Count);
			for (int i = value; i < num; i++)
			{
				proxy.arrayList.Add(source[i]);
			}
		}
	}
