	[ActionCategory(ActionCategory.Application)]
	[Tooltip("Set the resolution")]
	public class ScreenSetResolution : FsmStateAction
	{
		[Tooltip("Full Screen mode")]
		public FsmBool fullScreen;

		[Tooltip("The resolution width")]
		public FsmInt width;

		[Tooltip("The resolution height")]
		public FsmInt height;

		[Tooltip("The current resolution refresh rate")]
		[UIHint(UIHint.Variable)]
		public FsmInt preferedRefreshRate;

		[Tooltip("The current resolution ( width, height, refreshRate )")]
		[UIHint(UIHint.Variable)]
		public FsmVector3 orResolution;

		public override void Reset()
		{
			width = null;
			height = null;
			preferedRefreshRate = new FsmInt();
			preferedRefreshRate.UseVariable = true;
			orResolution = null;
			fullScreen = null;
		}

		public override void OnEnter()
		{
			if (!orResolution.IsNone)
			{
				if (preferedRefreshRate.IsNone)
				{
					Screen.SetResolution((int)orResolution.Value.x, (int)orResolution.Value.y, fullScreen.Value);
				}
				else
				{
					Screen.SetResolution((int)orResolution.Value.x, (int)orResolution.Value.y, fullScreen.Value, (int)orResolution.Value.z);
				}
			}
			else if (preferedRefreshRate.IsNone)
			{
				Screen.SetResolution(width.Value, height.Value, fullScreen.Value);
			}
			else
			{
				Screen.SetResolution(width.Value, height.Value, fullScreen.Value, preferedRefreshRate.Value);
			}
			Finish();
		}
	}
	[ActionCategory("ArrayMaker/ArrayList")]
	[Tooltip("Split a text asset or string into an arrayList")]
	public class SplitTextToArrayList : ArrayListActions
	{
		public enum ArrayMakerParseStringAs
		{
			String,
			Int,
			Float
		}

		public enum SplitSpecialChars
		{
			NewLine,
			Tab,
			Space
		}

		[ActionSection("Set up")]
		[RequiredField]
		[Tooltip("The gameObject with the PlayMaker ArrayList Proxy component")]
		[CheckForComponent(typeof(PlayMakerArrayListProxy))]
		public FsmOwnerDefault gameObject;

		[Tooltip("Author defined Reference of the PlayMaker ArrayList Proxy component ( necessary if several component coexists on the same GameObject")]
		public FsmString reference;

		[Tooltip("From where to start parsing, leave to 0 to start from the beginning")]
		public FsmInt startIndex;

		[Tooltip("the range of parsing")]
		public FsmInt parseRange;

		[ActionSection("Source")]
		[Tooltip("Text asset source")]
		public TextAsset textAsset;

		[Tooltip("Text Asset is ignored if this is set.")]
		public FsmString OrThisString;

		[ActionSection("Split")]
		[Tooltip("Split")]
		public SplitSpecialChars split;

		[Tooltip("Split is ignored if this value is not empty. Each chars taken in account for split")]
		public FsmString OrThisChar;

		[ActionSection("Value")]
		[Tooltip("Parse the line as a specific type")]
		public ArrayMakerParseStringAs parseAsType;

		public override void Reset()
		{
			gameObject = null;
			reference = null;
			startIndex = null;
			parseRange = null;
			textAsset = null;
			split = SplitSpecialChars.NewLine;
			parseAsType = ArrayMakerParseStringAs.String;
		}

		public override void OnEnter()
		{
			if (SetUpArrayListProxyPointer(base.Fsm.GetOwnerDefaultTarget(gameObject), reference.Value))
			{
				splitText();
			}
			Finish();
		}

		public void splitText()
		{
			if (!isProxyValid())
			{
				return;
			}
			string text;
			if (OrThisString.Value.Length == 0)
			{
				if (textAsset == null)
				{
					return;
				}
				text = textAsset.text;
			}
			else
			{
				text = OrThisString.Value;
			}
			proxy.arrayList.Clear();
			string[] array;
			if (OrThisChar.Value.Length == 0)
			{
				char c = '\n';
				switch (split)
				{
				case SplitSpecialChars.Tab:
					c = '\t';
					break;
				case SplitSpecialChars.Space:
					c = ' ';
					break;
				}
				array = text.Split(c);
			}
			else
			{
				array = text.Split(OrThisChar.Value.ToCharArray());
			}
			int value = startIndex.Value;
			int num = array.Length;
			if (parseRange.Value > 0)
			{
				num = Mathf.Min(num - value, parseRange.Value);
			}
			string[] array2 = new string[num];
			int num2 = 0;
			for (int i = value; i < value + num; i++)
			{
				array2[num2] = array[i];
				num2++;
			}
			if (parseAsType == ArrayMakerParseStringAs.String)
			{
				proxy.arrayList.InsertRange(0, array2);
			}
			else if (parseAsType == ArrayMakerParseStringAs.Int)
			{
				int[] array3 = new int[array2.Length];
				int num3 = 0;
				string[] array4 = array2;
				for (int j = 0; j < array4.Length; j++)
				{
					int.TryParse(array4[j], out array3[num3]);
					num3++;
				}
				proxy.arrayList.InsertRange(0, array3);
			}
			else if (parseAsType == ArrayMakerParseStringAs.Float)
			{
				float[] array5 = new float[array2.Length];
				int num4 = 0;
				string[] array4 = array2;
				for (int j = 0; j < array4.Length; j++)
				{
					float.TryParse(array4[j], out array5[num4]);
					num4++;
				}
				proxy.arrayList.InsertRange(0, array5);
			}
		}
	}
	public abstract class ArrayListActions : CollectionsActions
	{
		internal PlayMakerArrayListProxy proxy;

		protected bool SetUpArrayListProxyPointer(GameObject aProxyGO, string nameReference)
		{
			if (aProxyGO == null)
			{
				return false;
			}
			proxy = GetArrayListProxyPointer(aProxyGO, nameReference, silent: false);
			return proxy != null;
		}

		protected bool SetUpArrayListProxyPointer(PlayMakerArrayListProxy aProxy, string nameReference)
		{
			if (aProxy == null)
			{
				return false;
			}
			proxy = GetArrayListProxyPointer(aProxy.gameObject, nameReference, silent: false);
			return proxy != null;
		}

		public bool isProxyValid()
		{
			if (proxy == null)
			{
				LogError("ArrayList proxy is null");
				return false;
			}
			if (proxy.arrayList == null)
			{
				LogError("ArrayList undefined");
				return false;
			}
			return true;
		}
	}
	[Tooltip("Collections base action - don't use!")]
	public abstract class CollectionsActions : FsmStateAction
	{
		public enum FsmVariableEnum
		{
			FsmGameObject,
			FsmInt,
			FsmFloat,
			FsmString,
			FsmBool,
			FsmVector2,
			FsmVector3,
			FsmRect,
			FsmQuaternion,
			FsmColor,
			FsmMaterial,
			FsmTexture,
			FsmObject
		}

		protected PlayMakerHashTableProxy GetHashTableProxyPointer(GameObject aProxy, string nameReference, bool silent)
		{
			if (aProxy == null)
			{
				if (!silent)
				{
					UnityEngine.Debug.LogError("Null Proxy");
				}
				return null;
			}
			PlayMakerHashTableProxy[] components = aProxy.GetComponents<PlayMakerHashTableProxy>();
			if (components.Length > 1)
			{
				if (nameReference == "" && !silent)
				{
					UnityEngine.Debug.LogWarning("Several HashTable Proxies coexists on the same GameObject and no reference is given to find the expected HashTable");
				}
				PlayMakerHashTableProxy[] array = components;
				foreach (PlayMakerHashTableProxy playMakerHashTableProxy in array)
				{
					if (playMakerHashTableProxy.referenceName == nameReference)
					{
						return playMakerHashTableProxy;
					}
				}
				if (nameReference != "")
				{
					if (!silent)
					{
						UnityEngine.Debug.LogError("HashTable Proxy not found for reference <" + nameReference + ">");
					}
					return null;
				}
			}
			else if (components.Length != 0)
			{
				if (nameReference != "" && nameReference != components[0].referenceName)
				{
					if (!silent)
					{
						UnityEngine.Debug.LogError("HashTable Proxy reference do not match");
					}
					return null;
				}
				return components[0];
			}
			if (!silent)
			{
				UnityEngine.Debug.LogError("HashTable not found");
			}
			return null;
		}

		protected PlayMakerArrayListProxy GetArrayListProxyPointer(GameObject aProxy, string nameReference, bool silent)
		{
			if (aProxy == null)
			{
				if (!silent)
				{
					UnityEngine.Debug.LogError("Null Proxy");
				}
				return null;
			}
			PlayMakerArrayListProxy[] components = aProxy.GetComponents<PlayMakerArrayListProxy>();
			if (components.Length > 1)
			{
				if (nameReference == "" && !silent)
				{
					UnityEngine.Debug.LogError("Several ArrayList Proxies coexists on the same GameObject and no reference is given to find the expected ArrayList");
				}
				PlayMakerArrayListProxy[] array = components;
				foreach (PlayMakerArrayListProxy playMakerArrayListProxy in array)
				{
					if (playMakerArrayListProxy.referenceName == nameReference)
					{
						return playMakerArrayListProxy;
					}
				}
				if (nameReference != "")
				{
					if (!silent)
					{
						LogError("ArrayList Proxy not found for reference <" + nameReference + ">");
					}
					return null;
				}
			}
			else if (components.Length != 0)
			{
				if (nameReference != "" && nameReference != components[0].referenceName)
				{
					if (!silent)
					{
						UnityEngine.Debug.LogError("ArrayList Proxy reference do not match");
					}
					return null;
				}
				return components[0];
			}
			if (!silent)
			{
				LogError("ArrayList proxy not found");
			}
			return null;
		}
	}
	public abstract class HashTableActions : CollectionsActions
	{
		internal PlayMakerHashTableProxy proxy;

		protected bool SetUpHashTableProxyPointer(GameObject aProxyGO, string nameReference)
		{
			if (aProxyGO == null)
			{
				return false;
			}
			proxy = GetHashTableProxyPointer(aProxyGO, nameReference, silent: false);
			return proxy != null;
		}

		protected bool SetUpHashTableProxyPointer(PlayMakerHashTableProxy aProxy, string nameReference)
		{
			if (aProxy == null)
			{
				return false;
			}
			proxy = GetHashTableProxyPointer(aProxy.gameObject, nameReference, silent: false);
			return proxy != null;
		}

		protected bool isProxyValid()
