		[UIHint(UIHint.FsmVector3)]
		public FsmVector3 scale;

		[ActionSection("")]
		[Tooltip("Repeat every frame.")]
		public bool everyframe;

		private tk2dBaseSprite _sprite;

		private void _getSprite()
		{
			GameObject ownerDefaultTarget = base.Fsm.GetOwnerDefaultTarget(gameObject);
			if (!(ownerDefaultTarget == null))
			{
				_sprite = ownerDefaultTarget.GetComponent<tk2dBaseSprite>();
			}
		}

		public override void Reset()
		{
			gameObject = null;
			scale = new Vector3(1f, 1f, 1f);
			everyframe = false;
		}

		public override void OnEnter()
		{
			_getSprite();
			DoSetSpriteScale();
			if (!everyframe)
			{
				Finish();
			}
		}

		public override void OnUpdate()
		{
			DoSetSpriteScale();
		}

		private void DoSetSpriteScale()
		{
			if (_sprite == null)
			{
				LogWarning("Missing tk2dBaseSprite component");
			}
			else if (_sprite.scale != scale.Value)
			{
				_sprite.scale = scale.Value;
			}
		}
	}
	[ActionCategory("2D Toolkit/Sprite")]
	[Tooltip("Tween a sprite color \nNOTE: The Game Object must have a tk2dBaseSprite or derived component attached ( tk2dSprite, tk2dAnimatedSprite)")]
	public class Tk2dSpriteTweenColor : FsmStateAction
	{
		[RequiredField]
		[Tooltip("The Game Object to work with. NOTE: The Game Object must have a tk2dBaseSprite or derived component attached ( tk2dSprite, tk2dAnimatedSprite).")]
		[CheckForComponent(typeof(tk2dBaseSprite))]
		public FsmOwnerDefault gameObject;

		[RequiredField]
		[UIHint(UIHint.FsmColor)]
		public FsmColor color;

		[RequiredField]
		public FsmFloat duration;

		private tk2dBaseSprite sprite;

		public override void Reset()
		{
			gameObject = null;
			color = null;
			duration = null;
		}

		public override void OnEnter()
		{
			GameObject ownerDefaultTarget = base.Fsm.GetOwnerDefaultTarget(gameObject);
			if (!(ownerDefaultTarget == null))
			{
				sprite = ownerDefaultTarget.GetComponent<tk2dBaseSprite>();
				Hashtable hashtable = new Hashtable();
				hashtable.Add("from", sprite.color);
				hashtable.Add("to", color.Value);
				hashtable.Add("time", duration.Value);
				hashtable.Add("OnUpdate", "updateSpriteColor");
				hashtable.Add("looptype", iTween.LoopType.pingPong);
				hashtable.Add("easetype", iTween.EaseType.linear);
				iTween.ValueTo(ownerDefaultTarget, hashtable);
			}
		}

		private void updateSpriteColor(Color color)
		{
			sprite.color = color;
			UnityEngine.Debug.Log("wow");
		}
	}
