	[ActionCategory(ActionCategory.ScriptControl)]
	public class CallMethodProper : FsmStateAction
	{
		[RequiredField]
		[Tooltip("The game object that owns the Behaviour.")]
		public FsmOwnerDefault gameObject;

		[RequiredField]
		[UIHint(UIHint.Behaviour)]
		[Tooltip("The Behaviour that contains the method to start as a coroutine.")]
		public FsmString behaviour;

		[UIHint(UIHint.Method)]
		[Tooltip("Name of the method to call on the component")]
		public FsmString methodName;

		[Tooltip("Method paramters. NOTE: these must match the method's signature!")]
		public FsmVar[] parameters;

		[ActionSection("Store Result")]
		[UIHint(UIHint.Variable)]
		[Tooltip("Store the result of the method call.")]
		public FsmVar storeResult;

		private UnityEngine.Object cachedBehaviour;

		private Type cachedType;

		private MethodInfo cachedMethodInfo;

		private ParameterInfo[] cachedParameterInfo;

		private object[] parametersArray;

		private string errorString;

		private MonoBehaviour component;

		public override void OnEnter()
		{
			parametersArray = new object[parameters.Length];
			DoMethodCall();
			Finish();
		}

		private void DoMethodCall()
		{
			if (behaviour.Value == null)
			{
				Finish();
				return;
			}
			GameObject ownerDefaultTarget = base.Fsm.GetOwnerDefaultTarget(gameObject);
			if (ownerDefaultTarget == null)
			{
				return;
			}
			component = ownerDefaultTarget.GetComponent(behaviour.Value) as MonoBehaviour;
			if (component == null)
			{
				LogWarning("CallMethodProper: " + ownerDefaultTarget.name + " missing behaviour: " + behaviour.Value);
				return;
			}
			if (cachedMethodInfo == null)
			{
				errorString = string.Empty;
				if (!DoCache())
				{
					UnityEngine.Debug.LogError(errorString);
					Finish();
					return;
				}
			}
			object value = null;
			if (cachedParameterInfo.Length == 0)
			{
				value = cachedMethodInfo.Invoke(cachedBehaviour, null);
			}
			else
			{
				for (int i = 0; i < parameters.Length; i++)
				{
					FsmVar fsmVar = parameters[i];
					fsmVar.UpdateValue();
					parametersArray[i] = fsmVar.GetValue();
				}
				try
				{
					value = cachedMethodInfo.Invoke(cachedBehaviour, parametersArray);
				}
				catch (Exception ex)
				{
					UnityEngine.Debug.LogError("CallMethodProper error on " + base.Fsm.OwnerName + " -> " + ex);
				}
			}
			if (storeResult.Type != VariableType.Unknown)
			{
				storeResult.SetValue(value);
			}
		}

		private bool DoCache()
		{
			cachedBehaviour = component;
			cachedType = component.GetType();
			cachedMethodInfo = cachedType.GetMethod(methodName.Value);
			if (cachedMethodInfo == null)
			{
				errorString = errorString + "Method Name is invalid: " + methodName.Value + "\n";
				Finish();
				return false;
			}
			cachedParameterInfo = cachedMethodInfo.GetParameters();
			return true;
		}
	}
	[ActionCategory(ActionCategory.Camera)]
	[Tooltip("Fade from a fullscreen Color. NOTE: Uses OnGUI so requires a PlayMakerGUI component in the scene.")]
	public class CameraFadeInWithDelay : FsmStateAction
	{
		[RequiredField]
		[Tooltip("Color to fade from. E.g., Fade up from black.")]
		public FsmColor color;

		[RequiredField]
		[HasFloatSlider(0f, 10f)]
		[Tooltip("Delay time in seconds before starting the fade in.")]
		public FsmFloat delay;

		[RequiredField]
		[HasFloatSlider(0f, 10f)]
		[Tooltip("Fade in time in seconds.")]
		public FsmFloat time;

		[Tooltip("Event to send when finished.")]
		public FsmEvent finishEvent;

		[Tooltip("Ignore TimeScale. Useful if the game is paused.")]
		public bool realTime;

		private float startTime;

		private float currentTime;

		private Color colorLerp;

		private bool delayPassed;

		public override void Reset()
		{
			color = Color.black;
			time = 1f;
			delay = 1f;
			finishEvent = null;
			delayPassed = false;
		}

		public override void OnEnter()
		{
			startTime = FsmTime.RealtimeSinceStartup;
			currentTime = 0f;
			colorLerp = color.Value;
		}

		public override void OnUpdate()
		{
			if (realTime)
			{
				currentTime = FsmTime.RealtimeSinceStartup - startTime;
			}
			else
			{
				currentTime += Time.deltaTime;
			}
			if (!delayPassed && currentTime > delay.Value)
			{
				currentTime = 0f;
				delayPassed = true;
			}
			if (!delayPassed)
			{
				return;
			}
			colorLerp = Color.Lerp(color.Value, Color.clear, currentTime / time.Value);
			if (currentTime > time.Value)
			{
				if (finishEvent != null)
				{
					base.Fsm.Event(finishEvent);
				}
				delayPassed = false;
				Finish();
			}
		}

		public override void OnGUI()
		{
			Color obj = GUI.color;
			GUI.color = colorLerp;
			GUI.DrawTexture(new Rect(0f, 0f, Screen.width, Screen.height), ActionHelpers.WhiteTexture);
			GUI.color = obj;
		}
	}
	[ActionCategory("Enemy AI")]
	[Tooltip("Object buzzes towards target")]
	public class ChaseObject : RigidBody2dActionBase
	{
		[RequiredField]
		[CheckForComponent(typeof(Rigidbody2D))]
		[UIHint(UIHint.Variable)]
		public FsmOwnerDefault gameObject;

		[UIHint(UIHint.Variable)]
		public FsmGameObject target;

		public FsmFloat speedMax;

		public FsmFloat acceleration;

		public FsmFloat targetSpread;

		public FsmFloat spreadResetTimeMin;

		public FsmFloat spreadResetTimeMax;

		private bool spreadSet;

		private float spreadResetTime;

		private float spreadX;

		private float spreadY;

		private FsmGameObject self;

		private float timer;

		private float spreadResetTimer;

		public override void Reset()
		{
			gameObject = null;
			target = null;
			acceleration = 0f;
			speedMax = 0f;
		}

		public override void Awake()
		{
			base.Fsm.HandleFixedUpdate = true;
		}

		public override void OnPreprocess()
		{
			base.Fsm.HandleFixedUpdate = true;
		}

		public override void OnEnter()
		{
			CacheRigidBody2d(base.Fsm.GetOwnerDefaultTarget(gameObject));
			self = base.Fsm.GetOwnerDefaultTarget(gameObject);
			DoBuzz();
		}

		public override void OnFixedUpdate()
		{
			DoBuzz();
		}

		private void DoBuzz()
		{
			if (rb2d == null)
			{
				return;
			}
			if (targetSpread.Value > 0f)
			{
				if (timer >= spreadResetTime)
				{
					spreadX = UnityEngine.Random.Range(0f - targetSpread.Value, targetSpread.Value);
					spreadY = UnityEngine.Random.Range(0f - targetSpread.Value, targetSpread.Value);
					timer = 0f;
					spreadResetTime = UnityEngine.Random.Range(spreadResetTimeMin.Value, spreadResetTimeMax.Value);
				}
				else
				{
					timer += Time.deltaTime;
				}
			}
			Vector2 velocity = rb2d.velocity;
			if (self.Value.transform.position.x < target.Value.transform.position.x + spreadX)
			{
				velocity.x += acceleration.Value;
			}
			else
			{
				velocity.x -= acceleration.Value;
			}
			if (self.Value.transform.position.y < target.Value.transform.position.y + spreadY)
			{
				velocity.y += acceleration.Value;
			}
			else
			{
				velocity.y -= acceleration.Value;
			}
			if (velocity.x > speedMax.Value)
			{
				velocity.x = speedMax.Value;
			}
			if (velocity.x < 0f - speedMax.Value)
			{
				velocity.x = 0f - speedMax.Value;
			}
			if (velocity.y > speedMax.Value)
			{
				velocity.y = speedMax.Value;
			}
			if (velocity.y < 0f - speedMax.Value)
			{
				velocity.y = 0f - speedMax.Value;
			}
			rb2d.velocity = velocity;
		}
	}
	[ActionCategory("Enemy AI")]
	[Tooltip("Object runs towards target")]
	public class ChaseObjectGround : RigidBody2dActionBase
	{
		[RequiredField]
		[CheckForComponent(typeof(Rigidbody2D))]
		[UIHint(UIHint.Variable)]
		public FsmOwnerDefault gameObject;

		[UIHint(UIHint.Variable)]
		public FsmGameObject target;

		public FsmFloat speedMax;

		public FsmFloat acceleration;

		public bool animateTurnAndRun;

		public FsmString runAnimation;

		public FsmString turnAnimation;

		public FsmFloat turnRange;

		private FsmGameObject self;

		private tk2dSpriteAnimator animator;

		private bool turning;

		public override void Reset()
		{
			gameObject = null;
			target = null;
			acceleration = 0f;
			speedMax = 0f;
		}

		public override void Awake()
		{
			base.Fsm.HandleFixedUpdate = true;
		}

		public override void OnEnter()
		{
			CacheRigidBody2d(base.Fsm.GetOwnerDefaultTarget(gameObject));
			self = base.Fsm.GetOwnerDefaultTarget(gameObject);
			animator = self.Value.GetComponent<tk2dSpriteAnimator>();
			DoChase();
		}

		public override void OnPreprocess()
		{
			base.Fsm.HandleFixedUpdate = true;
		}

		public override void OnFixedUpdate()
		{
			DoChase();
		}

		private void DoChase()
		{
			if (rb2d == null)
			{
				return;
			}
			Vector2 velocity = rb2d.velocity;
			if (!(self.Value.transform.position.x < target.Value.transform.position.x - turnRange.Value) && !(self.Value.transform.position.x > target.Value.transform.position.x + turnRange.Value))
			{
				return;
			}
			if (self.Value.transform.position.x < target.Value.transform.position.x)
			{
				velocity.x += acceleration.Value;
				if (animateTurnAndRun)
				{
					if (velocity.x < 0f && !turning)
					{
						animator.Play(turnAnimation.Value);
						turning = true;
					}
					if (velocity.x > 0f && turning)
					{
						animator.Play(runAnimation.Value);
						turning = false;
					}
				}
			}
			else
			{
				velocity.x -= acceleration.Value;
				if (animateTurnAndRun)
				{
					if (velocity.x > 0f && !turning)
					{
						animator.Play(turnAnimation.Value);
						turning = true;
					}
					if (velocity.x < 0f && turning)
					{
						animator.Play(runAnimation.Value);
						turning = false;
					}
				}
			}
			if (velocity.x > speedMax.Value)
			{
				velocity.x = speedMax.Value;
			}
			if (velocity.x < 0f - speedMax.Value)
			{
				velocity.x = 0f - speedMax.Value;
			}
			rb2d.velocity = velocity;
		}
	}
	[ActionCategory("Enemy AI")]
	[Tooltip("Object moves more directly toward target")]
	public class ChaseObjectV2 : RigidBody2dActionBase
	{
		[RequiredField]
		[CheckForComponent(typeof(Rigidbody2D))]
		[UIHint(UIHint.Variable)]
		public FsmOwnerDefault gameObject;

		[UIHint(UIHint.Variable)]
		public FsmGameObject target;

		public FsmFloat speedMax;

		public FsmFloat accelerationForce;

		public FsmFloat offsetX;

		public FsmFloat offsetY;

		private FsmGameObject self;

		public override void Reset()
		{
			gameObject = null;
			target = null;
			accelerationForce = 0f;
			speedMax = 0f;
			offsetX = 0f;
			offsetY = 0f;
		}

		public override void Awake()
		{
			base.Fsm.HandleFixedUpdate = true;
		}

		public override void OnPreprocess()
		{
			base.Fsm.HandleFixedUpdate = true;
		}

		public override void OnEnter()
		{
			CacheRigidBody2d(base.Fsm.GetOwnerDefaultTarget(gameObject));
			self = base.Fsm.GetOwnerDefaultTarget(gameObject);
			DoChase();
		}

		public override void OnFixedUpdate()
		{
			DoChase();
		}

		private void DoChase()
		{
			if (!(rb2d == null))
			{
				Vector2 vector = new Vector2(target.Value.transform.position.x + offsetX.Value - self.Value.transform.position.x, target.Value.transform.position.y + offsetY.Value - self.Value.transform.position.y);
				vector = Vector2.ClampMagnitude(vector, 1f);
				vector = new Vector2(vector.x * accelerationForce.Value, vector.y * accelerationForce.Value);
				rb2d.AddForce(vector);
				Vector2 velocity = rb2d.velocity;
				velocity = Vector2.ClampMagnitude(velocity, speedMax.Value);
				rb2d.velocity = velocity;
			}
		}
	}
