	[ActionCategory(ActionCategory.Physics)]
	[Tooltip("Detect additional collisions between the Owner of this FSM and other object with additional raycasting.")]
	public class CheckCollisionSide : FsmStateAction
	{
		public enum CollisionSide
		{
			top,
			left,
			right,
			bottom,
			other
		}

		[UIHint(UIHint.Variable)]
		public FsmBool topHit;

		[UIHint(UIHint.Variable)]
		public FsmBool rightHit;

		[UIHint(UIHint.Variable)]
		public FsmBool bottomHit;

		[UIHint(UIHint.Variable)]
		public FsmBool leftHit;

		public FsmEvent topHitEvent;

		public FsmEvent rightHitEvent;

		public FsmEvent bottomHitEvent;

		public FsmEvent leftHitEvent;

		public bool otherLayer;

		public int otherLayerNumber;

		public FsmBool ignoreTriggers;

		private PlayMakerUnity2DProxy _proxy;

		private Collider2D col2d;

		private const float RAYCAST_LENGTH = 0.08f;

		private List<Vector2> topRays;

		private List<Vector2> rightRays;

		private List<Vector2> bottomRays;

		private List<Vector2> leftRays;

		private bool checkUp;

		private bool checkDown;

		private bool checkLeft;

		private bool checkRight;

		public override void Reset()
		{
			checkUp = false;
			checkDown = false;
			checkLeft = false;
			checkRight = false;
		}

		public override void OnEnter()
		{
			col2d = base.Fsm.GameObject.GetComponent<Collider2D>();
			topRays = new List<Vector2>(3);
			rightRays = new List<Vector2>(3);
			bottomRays = new List<Vector2>(3);
			leftRays = new List<Vector2>(3);
			_proxy = base.Owner.GetComponent<PlayMakerUnity2DProxy>();
			if (_proxy == null)
			{
				_proxy = base.Owner.AddComponent<PlayMakerUnity2DProxy>();
			}
			_proxy.AddOnCollisionStay2dDelegate(DoCollisionStay2D);
			if (!topHit.IsNone || topHitEvent != null)
			{
				checkUp = true;
			}
			else
			{
				checkUp = false;
			}
			if (!rightHit.IsNone || rightHitEvent != null)
			{
				checkRight = true;
			}
			else
			{
				checkRight = false;
			}
			if (!bottomHit.IsNone || bottomHitEvent != null)
			{
				checkDown = true;
			}
			else
			{
				checkDown = false;
			}
			if (!leftHit.IsNone || leftHitEvent != null)
			{
				checkLeft = true;
			}
			else
			{
				checkLeft = false;
			}
		}

		public override void OnExit()
		{
			_proxy.RemoveOnCollisionStay2dDelegate(DoCollisionStay2D);
		}

		public override void OnUpdate()
		{
			if (topHit.Value || bottomHit.Value || rightHit.Value || leftHit.Value)
			{
				if (!otherLayer)
				{
					CheckTouching(8);
				}
				else
				{
					CheckTouching(otherLayerNumber);
				}
			}
		}

		public new void DoCollisionStay2D(Collision2D collision)
		{
			if (!otherLayer)
			{
				if (collision.gameObject.layer == 8)
				{
					CheckTouching(8);
				}
			}
			else
			{
				CheckTouching(otherLayerNumber);
			}
		}

		public new void DoCollisionExit2D(Collision2D collision)
		{
			topHit.Value = false;
			rightHit.Value = false;
			bottomHit.Value = false;
			leftHit.Value = false;
		}

		private void CheckTouching(LayerMask layer)
		{
			if (checkUp)
			{
				topRays.Clear();
				topRays.Add(new Vector2(col2d.bounds.min.x, col2d.bounds.max.y));
				topRays.Add(new Vector2(col2d.bounds.center.x, col2d.bounds.max.y));
				topRays.Add(col2d.bounds.max);
				topHit.Value = false;
				for (int i = 0; i < 3; i++)
				{
					RaycastHit2D raycastHit2D = Physics2D.Raycast(topRays[i], Vector2.up, 0.08f, 1 << (int)layer);
					if (raycastHit2D.collider != null && (!ignoreTriggers.Value || !raycastHit2D.collider.isTrigger))
					{
						topHit.Value = true;
						base.Fsm.Event(topHitEvent);
						break;
					}
				}
			}
			if (checkRight)
			{
				rightRays.Clear();
				rightRays.Add(col2d.bounds.max);
				rightRays.Add(new Vector2(col2d.bounds.max.x, col2d.bounds.center.y));
				rightRays.Add(new Vector2(col2d.bounds.max.x, col2d.bounds.min.y));
				rightHit.Value = false;
				for (int j = 0; j < 3; j++)
				{
					RaycastHit2D raycastHit2D2 = Physics2D.Raycast(rightRays[j], Vector2.right, 0.08f, 1 << (int)layer);
					if (raycastHit2D2.collider != null && (!ignoreTriggers.Value || !raycastHit2D2.collider.isTrigger))
					{
						rightHit.Value = true;
						base.Fsm.Event(rightHitEvent);
						break;
					}
				}
			}
			if (checkDown)
			{
				bottomRays.Clear();
				bottomRays.Add(new Vector2(col2d.bounds.max.x, col2d.bounds.min.y));
				bottomRays.Add(new Vector2(col2d.bounds.center.x, col2d.bounds.min.y));
				bottomRays.Add(col2d.bounds.min);
				bottomHit.Value = false;
				for (int k = 0; k < 3; k++)
				{
					RaycastHit2D raycastHit2D3 = Physics2D.Raycast(bottomRays[k], -Vector2.up, 0.08f, 1 << (int)layer);
					if (raycastHit2D3.collider != null && (!ignoreTriggers.Value || !raycastHit2D3.collider.isTrigger))
					{
						bottomHit.Value = true;
						base.Fsm.Event(bottomHitEvent);
						break;
					}
				}
			}
			if (!checkLeft)
			{
				return;
			}
			leftRays.Clear();
			leftRays.Add(col2d.bounds.min);
			leftRays.Add(new Vector2(col2d.bounds.min.x, col2d.bounds.center.y));
			leftRays.Add(new Vector2(col2d.bounds.min.x, col2d.bounds.max.y));
			leftHit.Value = false;
			for (int l = 0; l < 3; l++)
			{
				RaycastHit2D raycastHit2D4 = Physics2D.Raycast(leftRays[l], -Vector2.right, 0.08f, 1 << (int)layer);
				if (raycastHit2D4.collider != null && (!ignoreTriggers.Value || !raycastHit2D4.collider.isTrigger))
				{
					leftHit.Value = true;
					base.Fsm.Event(leftHitEvent);
					break;
				}
			}
		}
	}
	[ActionCategory(ActionCategory.Physics)]
	[Tooltip("Detect additional collisions between the Owner of this FSM and other object with additional raycasting.")]
	public class CheckCollisionSideEnter : FsmStateAction
	{
		public enum CollisionSide
		{
			top,
			left,
			right,
			bottom,
			other
		}

		[UIHint(UIHint.Variable)]
		public FsmBool topHit;

		[UIHint(UIHint.Variable)]
		public FsmBool rightHit;

		[UIHint(UIHint.Variable)]
		public FsmBool bottomHit;

		[UIHint(UIHint.Variable)]
		public FsmBool leftHit;

		public FsmEvent topHitEvent;

		public FsmEvent rightHitEvent;

		public FsmEvent bottomHitEvent;

		public FsmEvent leftHitEvent;

		public bool otherLayer;

		public int otherLayerNumber;

		public FsmBool ignoreTriggers;

		private PlayMakerUnity2DProxy _proxy;

		private Collider2D col2d;

		private const float RAYCAST_LENGTH = 0.08f;

		private List<Vector2> topRays;

		private List<Vector2> rightRays;

		private List<Vector2> bottomRays;

		private List<Vector2> leftRays;

		public override void Reset()
		{
		}

		public override void OnEnter()
		{
			col2d = base.Fsm.GameObject.GetComponent<Collider2D>();
			_proxy = base.Owner.GetComponent<PlayMakerUnity2DProxy>();
			if (_proxy == null)
			{
				_proxy = base.Owner.AddComponent<PlayMakerUnity2DProxy>();
			}
			_proxy.AddOnCollisionEnter2dDelegate(DoCollisionEnter2D);
		}

		public override void OnExit()
		{
			_proxy.RemoveOnCollisionEnter2dDelegate(DoCollisionEnter2D);
		}

		public override void OnUpdate()
		{
		}

		public new void DoCollisionEnter2D(Collision2D collision)
		{
			if (!otherLayer)
			{
				if (LayerMask.LayerToName(collision.gameObject.layer) == "Terrain")
				{
					CheckTouching(8);
				}
			}
			else
			{
				CheckTouching(otherLayerNumber);
			}
		}

		private void CheckTouching(LayerMask layer)
		{
			topRays = new List<Vector2>();
			topRays.Add(new Vector2(col2d.bounds.min.x, col2d.bounds.max.y));
			topRays.Add(new Vector2(col2d.bounds.center.x, col2d.bounds.max.y));
			topRays.Add(col2d.bounds.max);
			rightRays = new List<Vector2>();
			rightRays.Add(col2d.bounds.max);
			rightRays.Add(new Vector2(col2d.bounds.max.x, col2d.bounds.center.y));
			rightRays.Add(new Vector2(col2d.bounds.max.x, col2d.bounds.min.y));
			bottomRays = new List<Vector2>();
			bottomRays.Add(new Vector2(col2d.bounds.max.x, col2d.bounds.min.y));
			bottomRays.Add(new Vector2(col2d.bounds.center.x, col2d.bounds.min.y));
			bottomRays.Add(col2d.bounds.min);
			leftRays = new List<Vector2>();
			leftRays.Add(col2d.bounds.min);
			leftRays.Add(new Vector2(col2d.bounds.min.x, col2d.bounds.center.y));
			leftRays.Add(new Vector2(col2d.bounds.min.x, col2d.bounds.max.y));
			topHit.Value = false;
			rightHit.Value = false;
			bottomHit.Value = false;
			leftHit.Value = false;
			foreach (Vector2 topRay in topRays)
			{
				RaycastHit2D raycastHit2D = Physics2D.Raycast((Vector3)topRay, Vector2.up, 0.08f, 1 << (int)layer);
				if (raycastHit2D.collider != null && (!ignoreTriggers.Value || !raycastHit2D.collider.isTrigger))
				{
					topHit.Value = true;
					base.Fsm.Event(topHitEvent);
					break;
				}
			}
			foreach (Vector2 rightRay in rightRays)
			{
				RaycastHit2D raycastHit2D2 = Physics2D.Raycast((Vector3)rightRay, Vector2.right, 0.08f, 1 << (int)layer);
				if (raycastHit2D2.collider != null && (!ignoreTriggers.Value || !raycastHit2D2.collider.isTrigger))
				{
					rightHit.Value = true;
					base.Fsm.Event(rightHitEvent);
					break;
				}
			}
			foreach (Vector2 bottomRay in bottomRays)
			{
				RaycastHit2D raycastHit2D3 = Physics2D.Raycast((Vector3)bottomRay, -Vector2.up, 0.08f, 1 << (int)layer);
				if (raycastHit2D3.collider != null && (!ignoreTriggers.Value || !raycastHit2D3.collider.isTrigger))
				{
					bottomHit.Value = true;
					base.Fsm.Event(bottomHitEvent);
					break;
				}
			}
			foreach (Vector2 leftRay in leftRays)
			{
				RaycastHit2D raycastHit2D4 = Physics2D.Raycast((Vector3)leftRay, -Vector2.right, 0.08f, 1 << (int)layer);
				if (raycastHit2D4.collider != null && (!ignoreTriggers.Value || !raycastHit2D4.collider.isTrigger))
				{
					leftHit.Value = true;
					base.Fsm.Event(leftHitEvent);
					break;
				}
			}
		}
	}
	[ActionCategory("Enemy AI")]
	[Tooltip("Check whether target is left/right/up/down relative to object")]
	public class CheckTargetDirection : FsmStateAction
	{
		[RequiredField]
		public FsmOwnerDefault gameObject;

		[RequiredField]
		public FsmGameObject target;

		public FsmEvent aboveEvent;

		public FsmEvent belowEvent;

		public FsmEvent rightEvent;

		public FsmEvent leftEvent;

		[UIHint(UIHint.Variable)]
		public FsmBool aboveBool;

		[UIHint(UIHint.Variable)]
		public FsmBool belowBool;

		[UIHint(UIHint.Variable)]
		public FsmBool rightBool;

		[UIHint(UIHint.Variable)]
		public FsmBool leftBool;

		private FsmGameObject self;

		private FsmFloat x;

		private FsmFloat y;

		public bool everyFrame;

		public override void Reset()
		{
			gameObject = null;
			target = null;
			everyFrame = false;
		}

		public override void OnEnter()
		{
			self = base.Fsm.GetOwnerDefaultTarget(gameObject);
			DoCheckDirection();
			if (!everyFrame)
			{
				Finish();
			}
		}

		public override void OnUpdate()
		{
			DoCheckDirection();
			if (!everyFrame)
			{
				Finish();
			}
		}

		private void DoCheckDirection()
		{
			float num = self.Value.transform.position.x;
			float num2 = self.Value.transform.position.y;
			float num3 = target.Value.transform.position.x;
			float num4 = target.Value.transform.position.y;
			if (num < num3)
			{
				base.Fsm.Event(rightEvent);
				rightBool.Value = true;
			}
			else
			{
				rightBool.Value = false;
			}
			if (num > num3)
			{
				base.Fsm.Event(leftEvent);
				leftBool.Value = true;
			}
			else
			{
				leftBool.Value = false;
			}
			if (num2 < num4)
			{
				base.Fsm.Event(aboveEvent);
				aboveBool.Value = true;
			}
			else
			{
				aboveBool.Value = false;
			}
			if (num2 > num4)
			{
				base.Fsm.Event(belowEvent);
				belowBool.Value = true;
			}
			else
			{
				belowBool.Value = false;
			}
		}
	}
	[ActionCategory("Math")]
	[Tooltip("Calculate the distance between two points and compare it against a known distance value.")]
	public class CompareDistance2D : FsmStateAction
	{
		[RequiredField]
		public FsmVector2 point1;

		[RequiredField]
		public FsmVector2 point2;

		[RequiredField]
		public FsmFloat knownDistance;

		public bool everyFrame;

		private float sqrDistanceTest;

		public override void Reset()
		{
			point1 = null;
			point2 = null;
			knownDistance = null;
			everyFrame = false;
		}

		public override void OnEnter()
		{
			sqrDistanceTest = knownDistance.Value * knownDistance.Value;
			DoCompareDistance();
			if (!everyFrame)
			{
				Finish();
			}
		}

		public override void OnUpdate()
		{
			DoCompareDistance();
		}

		private void DoCalcDistance()
		{
		}

		private void DoCompareDistance()
		{
			Vector2 vector = new Vector2(point1.Value.x, point1.Value.y);
			Vector2 vector2 = new Vector2(point2.Value.x, point2.Value.y);
			_ = (vector - vector2).magnitude;
			_ = knownDistance.Value;
		}
	}
	[ActionCategory(ActionCategory.Transform)]
	[Tooltip("Limits the distance the object can move in X/Y per update. Used to stop Climbers/Laser bugs etc from going into space when framerate dips")]
	public class ConstrainMovement : FsmStateAction
	{
		[RequiredField]
		[Tooltip("The GameObject to constrain.")]
		public FsmOwnerDefault gameObject;

		[Tooltip("Max difference in x pos allowed per update")]
		public FsmFloat xConstrain;

		[Tooltip("Max difference in y pos allowed per update")]
		public FsmFloat yConstrain;

		private float xPrev;

		private float yPrev;

		public override void Reset()
		{
			gameObject = null;
			xConstrain = new FsmFloat();
			yConstrain = new FsmFloat();
			xPrev = 0f;
			yPrev = 0f;
		}

		public override void OnEnter()
		{
			GameObject ownerDefaultTarget = base.Fsm.GetOwnerDefaultTarget(gameObject);
			xPrev = ownerDefaultTarget.transform.position.x;
			yPrev = ownerDefaultTarget.transform.position.y;
		}

		public override void OnUpdate()
		{
			GameObject ownerDefaultTarget = base.Fsm.GetOwnerDefaultTarget(gameObject);
			float num = ownerDefaultTarget.transform.position.x;
			float num2 = ownerDefaultTarget.transform.position.y;
			if (num > xPrev + xConstrain.Value)
			{
				num = xPrev + xConstrain.Value;
			}
			else if (num < xPrev - xConstrain.Value)
			{
				num = xPrev - xConstrain.Value;
			}
			if (num2 > yPrev + yConstrain.Value)
			{
				num2 = yPrev + yConstrain.Value;
			}
			else if (num2 < yPrev - yConstrain.Value)
			{
				num2 = yPrev - yConstrain.Value;
			}
			ownerDefaultTarget.transform.position = new Vector3(num, num2, ownerDefaultTarget.transform.position.z);
			xPrev = ownerDefaultTarget.transform.position.x;
			yPrev = ownerDefaultTarget.transform.position.y;
		}

		public override void OnLateUpdate()
		{
		}
	}
