		public override void Reset()
		{
			logLevel = LogLevel.Info;
			text = "";
			base.Reset();
		}

		public override void OnEnter()
		{
			if (!string.IsNullOrEmpty(text.Value))
			{
				if (logLevel == LogLevel.Info)
