	[ActionCategory(ActionCategory.GameObject)]
	[Tooltip("Destroy all children on a GameObject.")]
	public class DestroyAllChildren : FsmStateAction
	{
		[RequiredField]
		public FsmGameObject gameObject;

		public FsmBool disable;

