		private void DoBuzz()
		{
			if (rb2d == null)
			{
				return;
			}
			distanceAway = Mathf.Sqrt(Mathf.Pow(self.Value.transform.position.x - target.Value.transform.position.x, 2f) + Mathf.Pow(self.Value.transform.position.y - target.Value.transform.position.y, 2f));
			Vector2 velocity = rb2d.velocity;
			if (distanceAway > distance.Value)
			{
				if (stayLeft.Value && self.Value.transform.position.x > target.Value.transform.position.x + 1f)
				{
					velocity.x -= acceleration.Value;
				}
				else if (stayRight.Value && self.Value.transform.position.x < target.Value.transform.position.x - 1f)
				{
					velocity.x += acceleration.Value;
				}
				else if (self.Value.transform.position.x < target.Value.transform.position.x)
				{
					velocity.x += acceleration.Value;
				}
				else
				{
					velocity.x -= acceleration.Value;
				}
				if (!targetsHeight)
				{
					if (self.Value.transform.position.y < target.Value.transform.position.y)
					{
						velocity.y += acceleration.Value;
					}
					else
					{
						velocity.y -= acceleration.Value;
					}
				}
			}
			else
			{
				if (stayLeft.Value && self.Value.transform.position.x > target.Value.transform.position.x + 1f)
				{
					velocity.x -= acceleration.Value;
				}
				else if (stayRight.Value && self.Value.transform.position.x < target.Value.transform.position.x - 1f)
				{
					velocity.x += acceleration.Value;
				}
				else if (self.Value.transform.position.x < target.Value.transform.position.x)
				{
					velocity.x -= acceleration.Value;
				}
				else
				{
					velocity.x += acceleration.Value;
				}
				if (!targetsHeight)
				{
					if (self.Value.transform.position.y < target.Value.transform.position.y)
					{
						velocity.y -= acceleration.Value;
					}
					else
					{
						velocity.y += acceleration.Value;
					}
				}
			}
			if (targetsHeight)
			{
				if (self.Value.transform.position.y < target.Value.transform.position.y + height.Value)
				{
					velocity.y += acceleration.Value;
				}
				if (self.Value.transform.position.y > target.Value.transform.position.y + height.Value)
				{
					velocity.y -= acceleration.Value;
				}
			}
			if (velocity.x > speedMax.Value)
			{
				velocity.x = speedMax.Value;
			}
			if (velocity.x < 0f - speedMax.Value)
			{
				velocity.x = 0f - speedMax.Value;
			}
			if (velocity.y > speedMax.Value)
			{
				velocity.y = speedMax.Value;
			}
			if (velocity.y < 0f - speedMax.Value)
			{
				velocity.y = 0f - speedMax.Value;
			}
			rb2d.velocity = velocity;
		}
	}
	[ActionCategory("Enemy AI")]
	[Tooltip("Try to keep a certain distance from target.")]
	public class DistanceWalk : RigidBody2dActionBase
	{
		[RequiredField]
		[CheckForComponent(typeof(Rigidbody2D))]
		[UIHint(UIHint.Variable)]
		public FsmOwnerDefault gameObject;

		[UIHint(UIHint.Variable)]
		public FsmGameObject target;

		public FsmFloat distance;

		public FsmFloat speed;

		public FsmFloat range;

		public bool changeAnimation;

		public bool spriteFacesRight;

		public FsmString forwardAnimation;

		public FsmString backAnimation;

		private float distanceAway;

		private FsmGameObject self;

		private tk2dSpriteAnimator animator;

		private bool movingRight;

		private float ANIM_CHANGE_TIME = 0.6f;

		private float changeTimer;

		private bool randomStart;

		public override void Reset()
		{
			gameObject = null;
			target = null;
			speed = 0f;
		}

		public override void Awake()
		{
			base.Fsm.HandleFixedUpdate = true;
		}

		public override void OnPreprocess()
		{
			base.Fsm.HandleFixedUpdate = true;
		}

		public override void OnEnter()
		{
			CacheRigidBody2d(base.Fsm.GetOwnerDefaultTarget(gameObject));
			self = base.Fsm.GetOwnerDefaultTarget(gameObject);
			if (changeAnimation)
			{
				animator = self.Value.GetComponent<tk2dSpriteAnimator>();
			}
			DoWalk();
		}

		public override void OnUpdate()
		{
			if (changeTimer > 0f)
			{
				changeTimer -= Time.deltaTime;
			}
		}

		public override void OnFixedUpdate()
		{
			DoWalk();
		}

		private void DoWalk()
		{
			if (rb2d == null)
			{
				return;
			}
			distanceAway = self.Value.transform.position.x - target.Value.transform.position.x;
			if (distanceAway < 0f)
			{
				distanceAway *= -1f;
			}
			Vector2 velocity = rb2d.velocity;
			if (distanceAway > distance.Value + range.Value)
			{
				if (self.Value.transform.position.x < target.Value.transform.position.x)
				{
					if (!movingRight && changeTimer <= 0f)
					{
						velocity.x = speed.Value;
						movingRight = true;
						changeTimer = ANIM_CHANGE_TIME;
					}
				}
				else if (movingRight && changeTimer <= 0f)
				{
					velocity.x = 0f - speed.Value;
					movingRight = false;
					changeTimer = ANIM_CHANGE_TIME;
				}
			}
			else if (distanceAway < distance.Value - range.Value)
			{
				if (self.Value.transform.position.x < target.Value.transform.position.x)
				{
					if (movingRight && changeTimer <= 0f)
					{
						velocity.x = 0f - speed.Value;
						movingRight = false;
						changeTimer = ANIM_CHANGE_TIME;
					}
				}
				else if (!movingRight && changeTimer <= 0f)
				{
					velocity.x = speed.Value;
					movingRight = true;
					changeTimer = ANIM_CHANGE_TIME;
				}
			}
			if (rb2d.velocity.x > -0.1f && rb2d.velocity.x < 0.1f)
			{
				if (UnityEngine.Random.value > 0.5f)
				{
					velocity.x = speed.Value;
					movingRight = true;
				}
				else
				{
					velocity.x = 0f - speed.Value;
					movingRight = false;
				}
				randomStart = true;
			}
			rb2d.velocity = velocity;
			if (!changeAnimation)
			{
				return;
			}
			if (self.Value.transform.localScale.x > 0f)
			{
				if ((spriteFacesRight && movingRight) || (!spriteFacesRight && !movingRight))
				{
					animator.Play(forwardAnimation.Value);
				}
				if ((!spriteFacesRight && movingRight) || (spriteFacesRight && !movingRight))
				{
					animator.Play(backAnimation.Value);
				}
			}
			else
			{
				if ((spriteFacesRight && movingRight) || (!spriteFacesRight && !movingRight))
				{
					animator.Play(backAnimation.Value);
				}
				if ((!spriteFacesRight && movingRight) || (spriteFacesRight && !movingRight))
				{
					animator.Play(forwardAnimation.Value);
				}
			}
		}
	}
	[ActionCategory("Enemy AI")]
	[Tooltip("Object rotates to face direction it is travelling in.")]
