	[ActionCategory("Enemy AI")]
	[Tooltip("Object will flip to face the direction it is moving on X Axis.")]
	public class FaceDirection : RigidBody2dActionBase
	{
		[RequiredField]
		[CheckForComponent(typeof(Rigidbody2D))]
		public FsmOwnerDefault gameObject;

		[Tooltip("Does the target's sprite face right?")]
		public FsmBool spriteFacesRight;

		public bool playNewAnimation;

		public FsmString newAnimationClip;

		public bool everyFrame;

		public bool pauseBetweenTurns;

		public FsmFloat pauseTime;

		private FsmGameObject target;

		private tk2dSpriteAnimator _sprite;

		private float xScale;

		private float pauseTimer;

		public override void Reset()
		{
			gameObject = null;
			spriteFacesRight = false;
			everyFrame = false;
			playNewAnimation = false;
			newAnimationClip = null;
		}

		public override void OnEnter()
		{
			CacheRigidBody2d(base.Fsm.GetOwnerDefaultTarget(gameObject));
			target = base.Fsm.GetOwnerDefaultTarget(gameObject);
			_sprite = target.Value.GetComponent<tk2dSpriteAnimator>();
			xScale = target.Value.transform.localScale.x;
			if (xScale < 0f)
			{
				xScale *= -1f;
			}
			DoFace();
			if (!everyFrame)
			{
				Finish();
			}
		}

		public override void OnUpdate()
		{
			DoFace();
		}

		private void DoFace()
		{
			if (rb2d == null)
			{
				return;
			}
			Vector2 velocity = rb2d.velocity;
			Vector3 localScale = target.Value.transform.localScale;
			float x = velocity.x;
			if (pauseTimer <= 0f || !pauseBetweenTurns)
			{
				if (x > 0f)
				{
					if (spriteFacesRight.Value)
					{
						if (localScale.x != xScale)
						{
							pauseTimer = pauseTime.Value;
							localScale.x = xScale;
							if (playNewAnimation)
							{
								_sprite.Play(newAnimationClip.Value);
								_sprite.PlayFromFrame(0);
							}
						}
					}
					else if (localScale.x != 0f - xScale)
					{
						pauseTimer = pauseTime.Value;
						localScale.x = 0f - xScale;
						if (playNewAnimation)
						{
							_sprite.Play(newAnimationClip.Value);
							_sprite.PlayFromFrame(0);
						}
					}
				}
				else if (x <= 0f)
				{
					if (spriteFacesRight.Value)
					{
						if (localScale.x != 0f - xScale)
						{
							pauseTimer = pauseTime.Value;
							localScale.x = 0f - xScale;
							if (playNewAnimation)
							{
								_sprite.Play(newAnimationClip.Value);
								_sprite.PlayFromFrame(0);
							}
						}
					}
					else if (localScale.x != xScale)
					{
						pauseTimer = pauseTime.Value;
						localScale.x = xScale;
						if (playNewAnimation)
						{
							_sprite.Play(newAnimationClip.Value);
							_sprite.PlayFromFrame(0);
						}
					}
				}
			}
			else
			{
				pauseTimer -= Time.deltaTime;
			}
			target.Value.transform.localScale = new Vector3(localScale.x, target.Value.transform.localScale.y, target.Value.transform.localScale.z);
		}
	}
	[ActionCategory("Enemy AI")]
	[Tooltip("Object A will flip to face Object B horizontally.")]
	public class FaceObject : FsmStateAction
	{
		[RequiredField]
		public FsmGameObject objectA;

		[RequiredField]
		[UIHint(UIHint.Variable)]
		public FsmGameObject objectB;

		[Tooltip("Does object A's sprite face right?")]
		public FsmBool spriteFacesRight;

		public bool playNewAnimation;

		public FsmString newAnimationClip;

		public bool resetFrame = true;

		[Tooltip("Repeat every frame.")]
		public bool everyFrame;

		private float xScale;

		private FsmVector3 vector;

		private tk2dSpriteAnimator _sprite;

		public override void Reset()
		{
			objectA = null;
			objectB = null;
			newAnimationClip = null;
			spriteFacesRight = false;
			everyFrame = false;
			resetFrame = false;
			playNewAnimation = false;
		}

		public override void OnEnter()
		{
			_sprite = objectA.Value.GetComponent<tk2dSpriteAnimator>();
			if (_sprite == null)
			{
				Finish();
			}
			xScale = objectA.Value.transform.localScale.x;
			if (xScale < 0f)
			{
				xScale *= -1f;
			}
			DoFace();
			if (!everyFrame)
			{
				Finish();
			}
		}

		public override void OnUpdate()
		{
			DoFace();
		}

		private void DoFace()
		{
			Vector3 localScale = objectA.Value.transform.localScale;
			if (objectB.Value == null || objectB.IsNone)
			{
				Finish();
			}
			if (objectA.Value.transform.position.x < objectB.Value.transform.position.x)
			{
				if (spriteFacesRight.Value)
				{
					if (localScale.x != xScale)
					{
						localScale.x = xScale;
						if (resetFrame)
						{
							_sprite.PlayFromFrame(0);
						}
						if (playNewAnimation)
						{
							_sprite.Play(newAnimationClip.Value);
						}
					}
				}
				else if (localScale.x != 0f - xScale)
				{
					localScale.x = 0f - xScale;
					if (resetFrame)
					{
						_sprite.PlayFromFrame(0);
					}
					if (playNewAnimation)
					{
						_sprite.Play(newAnimationClip.Value);
					}
				}
			}
			else if (spriteFacesRight.Value)
			{
				if (localScale.x != 0f - xScale)
				{
					localScale.x = 0f - xScale;
					if (resetFrame)
					{
						_sprite.PlayFromFrame(0);
					}
					if (playNewAnimation)
					{
						_sprite.Play(newAnimationClip.Value);
					}
				}
			}
			else if (localScale.x != xScale)
			{
				localScale.x = xScale;
				if (resetFrame)
				{
					_sprite.PlayFromFrame(0);
				}
				if (playNewAnimation)
				{
					_sprite.Play(newAnimationClip.Value);
				}
			}
			objectA.Value.transform.localScale = new Vector3(localScale.x, objectA.Value.transform.localScale.y, objectA.Value.transform.localScale.z);
		}
	}
	[ActionCategory("Enemy AI")]
	[Tooltip("Travel in a straight line towards target at set speed.")]
	public class FireAtTarget : RigidBody2dActionBase
	{
		[RequiredField]
		[CheckForComponent(typeof(Rigidbody2D))]
		public FsmOwnerDefault gameObject;

		[RequiredField]
		public FsmGameObject target;

		[RequiredField]
		public FsmFloat speed;

		public FsmVector3 position;

		public FsmFloat spread;

		private FsmGameObject self;

		private FsmFloat x;

		private FsmFloat y;

		public bool everyFrame;

		public override void Reset()
		{
			gameObject = null;
			target = null;
			speed = new FsmFloat
			{
				UseVariable = true
			};
			everyFrame = false;
		}

		public override void Awake()
		{
			base.Fsm.HandleFixedUpdate = true;
		}

		public override void OnPreprocess()
		{
			base.Fsm.HandleFixedUpdate = true;
		}

		public override void OnEnter()
		{
			self = base.Fsm.GetOwnerDefaultTarget(gameObject);
			CacheRigidBody2d(base.Fsm.GetOwnerDefaultTarget(gameObject));
			DoSetVelocity();
			if (!everyFrame)
			{
				Finish();
			}
		}

		public override void OnFixedUpdate()
		{
			DoSetVelocity();
			if (!everyFrame)
			{
				Finish();
			}
		}

		private void DoSetVelocity()
		{
			if (!(rb2d == null))
			{
				float num = target.Value.transform.position.y + position.Value.y - self.Value.transform.position.y;
				float num2 = target.Value.transform.position.x + position.Value.x - self.Value.transform.position.x;
				float num3 = Mathf.Atan2(num, num2) * (180f / (float)Math.PI);
				if (!spread.IsNone)
				{
					num3 += UnityEngine.Random.Range(0f - spread.Value, spread.Value);
				}
				x = speed.Value * Mathf.Cos(num3 * ((float)Math.PI / 180f));
				y = speed.Value * Mathf.Sin(num3 * ((float)Math.PI / 180f));
				Vector2 velocity = default(Vector2);
				velocity.x = x.Value;
				velocity.y = y.Value;
				rb2d.velocity = velocity;
			}
		}
	}
	[ActionCategory(ActionCategory.GameObject)]
	[Tooltip("Spawns a random amount of chosen GameObject from global pool and fires them off in random directions. used for flashing geo generated by fragile greed.")]
	public class FlingFlashingGeo : RigidBody2dActionBase
	{
		[RequiredField]
		[Tooltip("GameObject to spawn.")]
		public FsmGameObject gameObject;

		[Tooltip("GameObject to spawn at (optional).")]
		public FsmGameObject spawnPoint;

		[Tooltip("Position. If a Spawn Point is defined, this is used as a local offset from the Spawn Point position.")]
		public FsmVector3 position;

		[Tooltip("Minimum amount of objects to be spawned.")]
		public FsmInt spawnMin;

		[Tooltip("Maximum amount of objects to be spawned.")]
		public FsmInt spawnMax;

		[Tooltip("Minimum speed objects are fired at.")]
		public FsmFloat speedMin;

		[Tooltip("Maximum speed objects are fired at.")]
		public FsmFloat speedMax;

		[Tooltip("Minimum angle objects are fired at.")]
		public FsmFloat angleMin;

		[Tooltip("Maximum angle objects are fired at.")]
		public FsmFloat angleMax;

		[Tooltip("Randomises spawn points of objects within this range. Leave as 0 and all objects will spawn at same point.")]
		public FsmFloat originVariationX;

		public FsmFloat originVariationY;

		private float vectorX;

		private float vectorY;

		private bool originAdjusted;

		public override void Reset()
		{
			gameObject = null;
			spawnPoint = null;
			position = new FsmVector3
			{
				UseVariable = true
			};
			spawnMin = null;
			spawnMax = null;
			speedMin = null;
			speedMax = null;
			angleMin = null;
			angleMax = null;
			originVariationX = null;
			originVariationY = null;
		}

		public override void OnEnter()
		{
			if (this.gameObject.Value != null)
			{
				Vector3 vector = Vector3.zero;
				Vector3 zero = Vector3.zero;
				if (spawnPoint.Value != null)
				{
					vector = spawnPoint.Value.transform.position;
					if (!position.IsNone)
					{
						vector += position.Value;
					}
				}
				else if (!position.IsNone)
				{
					vector = position.Value;
				}
				int num = UnityEngine.Random.Range(spawnMin.Value, spawnMax.Value + 1);
				Vector2 velocity = default(Vector2);
				for (int i = 1; i <= num; i++)
				{
					GameObject gameObject = this.gameObject.Value.Spawn(vector, Quaternion.Euler(zero));
					float x = gameObject.transform.position.x;
					float y = gameObject.transform.position.y;
					float z = gameObject.transform.position.z;
					if (originVariationX != null)
					{
						x = gameObject.transform.position.x + UnityEngine.Random.Range(0f - originVariationX.Value, originVariationX.Value);
						originAdjusted = true;
					}
					if (originVariationY != null)
					{
						y = gameObject.transform.position.y + UnityEngine.Random.Range(0f - originVariationY.Value, originVariationY.Value);
						originAdjusted = true;
					}
					if (originAdjusted)
					{
						gameObject.transform.position = new Vector3(x, y, z);
					}
					CacheRigidBody2d(gameObject);
					float num2 = UnityEngine.Random.Range(speedMin.Value, speedMax.Value);
					float num3 = UnityEngine.Random.Range(angleMin.Value, angleMax.Value);
					vectorX = num2 * Mathf.Cos(num3 * ((float)Math.PI / 180f));
					vectorY = num2 * Mathf.Sin(num3 * ((float)Math.PI / 180f));
					velocity.x = vectorX;
					velocity.y = vectorY;
					rb2d.velocity = velocity;
					gameObject.GetComponent<SpriteFlash>().GeoFlash();
				}
			}
			Finish();
		}
	}
