	[ActionCategory(ActionCategory.Logic)]
	[Tooltip("Set bools based on the comparison of 2 Floats.")]
	public class FloatTestToBool : FsmStateAction
	{
		[RequiredField]
		[Tooltip("The first float variable.")]
		public FsmFloat float1;

		[RequiredField]
		[Tooltip("The second float variable.")]
		public FsmFloat float2;

		[RequiredField]
		[Tooltip("Tolerance for the Equal test (almost equal).")]
		public FsmFloat tolerance;

		[Tooltip("Bool set if Float 1 equals Float 2")]
		[UIHint(UIHint.Variable)]
		public FsmBool equalBool;

		[Tooltip("Bool set if Float 1 is less than Float 2")]
		[UIHint(UIHint.Variable)]
		public FsmBool lessThanBool;

		[Tooltip("Bool set if Float 1 is greater than Float 2")]
		[UIHint(UIHint.Variable)]
		public FsmBool greaterThanBool;

		[Tooltip("Repeat every frame. Useful if the variables are changing and you're waiting for a particular result.")]
		public bool everyFrame;

		public override void Reset()
		{
			float1 = 0f;
			float2 = 0f;
			tolerance = 0f;
			everyFrame = false;
		}

		public override void OnEnter()
		{
			DoCompare();
			if (!everyFrame)
			{
				Finish();
			}
		}

		public override void OnUpdate()
		{
			DoCompare();
		}

		private void DoCompare()
		{
			if (Mathf.Abs(float1.Value - float2.Value) <= tolerance.Value)
			{
				equalBool.Value = true;
			}
			else
			{
				equalBool.Value = false;
			}
			if (float1.Value < float2.Value)
			{
				lessThanBool.Value = true;
			}
			else
			{
				lessThanBool.Value = false;
			}
			if (float1.Value > float2.Value)
			{
				greaterThanBool.Value = true;
			}
			else
			{
				greaterThanBool.Value = false;
			}
		}
	}
	[ActionCategory(ActionCategory.GameObject)]
	[Tooltip("Checks to see if a Game Object exists in the scene by Name and/or Tag.")]
	public class GameObjectExists : FsmStateAction
	{
		[Tooltip("The name of the GameObject to find. You can leave this empty if you specify a Tag.")]
		public FsmString objectName;

		[UIHint(UIHint.Tag)]
		[Tooltip("Find a GameObject with this tag. If Object Name is specified then both name and Tag must match.")]
		public FsmString withTag;

		[RequiredField]
		[UIHint(UIHint.Variable)]
		[Tooltip("Store the result in a boolean variable.")]
		public FsmBool result;

		public override void Reset()
		{
			objectName = "";
			withTag = "Untagged";
			result = null;
		}

		public override void OnEnter()
		{
			Finish();
			if (withTag.Value != "Untagged")
			{
				if (!string.IsNullOrEmpty(objectName.Value))
				{
					GameObject[] array = GameObject.FindGameObjectsWithTag(withTag.Value);
					for (int i = 0; i < array.Length; i++)
					{
						if (array[i].name == objectName.Value)
						{
							result.Value = true;
							return;
						}
					}
					result.Value = false;
				}
				else if (GameObject.FindGameObjectWithTag(withTag.Value) != null)
				{
					result.Value = true;
				}
				else
				{
					result.Value = false;
				}
			}
			else if (GameObject.Find(objectName.Value) == null)
			{
				result.Value = true;
			}
		}

		public override string ErrorCheck()
		{
			if (string.IsNullOrEmpty(objectName.Value) && string.IsNullOrEmpty(withTag.Value))
			{
				return "Please specify Name, Tag, or both for the object you are looking for.";
			}
			return null;
		}
	}
	[ActionCategory("Math")]
