	[ActionCategory(ActionCategory.Material)]
	[Tooltip("Gets a named color value from a game object's material.")]
	public class GetMaterialColor : FsmStateAction
	{
		[Tooltip("The GameObject that the material is applied to.")]
		[CheckForComponent(typeof(Renderer))]
		public FsmOwnerDefault gameObject;

		[Tooltip("GameObjects can have multiple materials. Specify an index to target a specific material.")]
		public FsmInt materialIndex;

		[Tooltip("Alternatively specify a Material instead of a GameObject and Index.")]
		public FsmMaterial material;

		[UIHint(UIHint.NamedColor)]
		[Tooltip("The named color parameter in the shader.")]
		public FsmString namedColor;

		[RequiredField]
		[UIHint(UIHint.Variable)]
		[Tooltip("Get the parameter value.")]
		public FsmColor color;

		public FsmEvent fail;

		public override void Reset()
		{
			gameObject = null;
			materialIndex = 0;
			material = null;
			namedColor = "_Color";
			color = null;
			fail = null;
		}

		public override void OnEnter()
		{
			DoGetMaterialColor();
			Finish();
		}

		private void DoGetMaterialColor()
		{
			if (color.IsNone)
			{
				return;
			}
			string text = namedColor.Value;
			if (text == "")
			{
				text = "_Color";
			}
			if (material.Value != null)
			{
				if (!material.Value.HasProperty(text))
				{
					base.Fsm.Event(fail);
				}
				else
				{
					color.Value = material.Value.GetColor(text);
				}
				return;
			}
			GameObject ownerDefaultTarget = base.Fsm.GetOwnerDefaultTarget(gameObject);
			if (ownerDefaultTarget == null)
			{
				return;
			}
			if (ownerDefaultTarget.GetComponent<Renderer>() == null)
			{
				LogError("Missing Renderer!");
			}
			else if (ownerDefaultTarget.GetComponent<Renderer>().material == null)
			{
				LogError("Missing Material!");
			}
			else if (materialIndex.Value == 0)
			{
				if (!ownerDefaultTarget.GetComponent<Renderer>().material.HasProperty(text))
				{
					base.Fsm.Event(fail);
				}
				else
				{
					color.Value = ownerDefaultTarget.GetComponent<Renderer>().material.GetColor(text);
				}
			}
			else if (ownerDefaultTarget.GetComponent<Renderer>().materials.Length > materialIndex.Value)
			{
				Material[] materials = ownerDefaultTarget.GetComponent<Renderer>().materials;
				if (!materials[materialIndex.Value].HasProperty(text))
				{
					base.Fsm.Event(fail);
				}
				else
				{
					color.Value = materials[materialIndex.Value].GetColor(text);
				}
			}
		}
	}
	[ActionCategory("GameObject")]
	[Tooltip("Set Mesh Renderer to active or inactive. Can only be one Mesh Renderer on object. ")]
	public class GetMeshRendererBounds : FsmStateAction
	{
		[RequiredField]
		public FsmOwnerDefault gameObject;

		[UIHint(UIHint.Variable)]
		public FsmFloat width;

		[UIHint(UIHint.Variable)]
		public FsmFloat height;

		public FsmFloat widthMax;

		public FsmFloat heightMax;

		public override void Reset()
		{
			gameObject = null;
			width = null;
			height = null;
			widthMax = null;
			heightMax = null;
		}

		public override void OnEnter()
		{
			if (gameObject != null)
			{
				GameObject ownerDefaultTarget = base.Fsm.GetOwnerDefaultTarget(gameObject);
				MeshRenderer component = ownerDefaultTarget.GetComponent<MeshRenderer>();
				if (component != null)
				{
					width.Value = component.bounds.size.x;
				}
				foreach (Transform item in ownerDefaultTarget.transform)
				{
					MeshRenderer component2 = item.GetComponent<MeshRenderer>();
					if (component2 != null)
					{
						float x = component2.bounds.size.x;
						float y = component2.bounds.size.y;
						if (x > width.Value)
						{
							width.Value = x;
						}
						if (y > height.Value)
						{
							height.Value = y;
						}
					}
				}
				if (!widthMax.IsNone && width.Value > widthMax.Value)
				{
					width.Value = 0f;
				}
				height.Value = component.bounds.size.y;
				if (!heightMax.IsNone && height.Value > heightMax.Value)
				{
					height.Value = 0f;
				}
			}
			Finish();
		}
	}
	[ActionCategory(ActionCategory.Transform)]
	[Tooltip("Gets the mid point between two objects")]
	public class GetMidPoint : FsmStateAction
	{
		[RequiredField]
		public FsmOwnerDefault gameObject;

		public FsmGameObject target;

		[UIHint(UIHint.Variable)]
		public FsmVector3 midPoint;

		public bool everyFrame;

		public override void Reset()
		{
			gameObject = null;
			target = null;
			midPoint = null;
			everyFrame = false;
		}

		public override void OnEnter()
		{
			DoGetPosition();
			if (!everyFrame)
			{
				Finish();
			}
		}

		public override void OnUpdate()
		{
			DoGetPosition();
		}

		private void DoGetPosition()
		{
			GameObject ownerDefaultTarget = base.Fsm.GetOwnerDefaultTarget(gameObject);
			if (ownerDefaultTarget == null)
			{
				UnityEngine.Debug.Log("lol");
				return;
			}
			Vector3 position = ownerDefaultTarget.transform.position;
			Vector3 position2 = target.Value.transform.position;
			Vector3 value = new Vector3(position.x + (position2.x - position.x) / 2f, position.y + (position2.y - position.y) / 2f, position.z + (position2.z - position.z) / 2f);
			midPoint.Value = value;
		}
	}
	[ActionCategory("Hollow Knight")]
	public class GetNamedParent : FsmStateAction
	{
		[RequiredField]
		[Tooltip("The GameObject to search.")]
		public FsmOwnerDefault gameObject;

		[Tooltip("The name of the parent to search for.")]
		public FsmString parentName;

		[UIHint(UIHint.Tag)]
		[Tooltip("The Tag to search for. If Parent Name is set, both name and Tag need to match.")]
		public FsmString withTag;

		[RequiredField]
		[UIHint(UIHint.Variable)]
		[Tooltip("Store the result in a GameObject variable.")]
		public FsmGameObject storeResult;

		public override void Reset()
		{
			gameObject = null;
			parentName = "";
			withTag = null;
			storeResult = null;
		}

		public override void OnEnter()
		{
			storeResult.Value = DoGetParentByName(base.Fsm.GetOwnerDefaultTarget(gameObject), parentName.Value, withTag.IsNone ? null : withTag.Value);
			Finish();
		}

		private static GameObject DoGetParentByName(GameObject root, string name, string tag)
		{
			if (root == null)
			{
				return null;
			}
			Transform parent = root.transform.parent;
			if (parent == null)
			{
				return null;
			}
			if (parent.name == name && (string.IsNullOrEmpty(tag) || parent.CompareTag(tag)))
			{
				return parent.gameObject;
			}
			return DoGetParentByName(parent.gameObject, name, tag);
		}

		public override string ErrorCheck()
		{
			if (string.IsNullOrEmpty(parentName.Value) && string.IsNullOrEmpty(withTag.Value))
			{
				return "Specify Parent Name, Tag, or both.";
			}
			return null;
		}
	}
