	[ActionCategory("Controls")]
	[Tooltip("Listens for an action button press (using HeroActions InControl mappings).")]
	public class ListenForUp : FsmStateAction
	{
		[Tooltip("Where to send the event.")]
		public FsmEventTarget eventTarget;

		public FsmEvent wasPressed;

		public FsmEvent wasReleased;

		public FsmEvent isPressed;

		public FsmEvent isNotPressed;

		[UIHint(UIHint.Variable)]
		public FsmBool isPressedBool;

		public bool stateEntryOnly;

		private GameManager gm;

		private InputHandler inputHandler;

		public override void Reset()
		{
			eventTarget = null;
		}

		public override void OnEnter()
		{
			gm = GameManager.instance;
			inputHandler = gm.GetComponent<InputHandler>();
			CheckForInput();
			if (stateEntryOnly)
			{
				Finish();
			}
		}

		public override void OnUpdate()
		{
			CheckForInput();
		}

		private void CheckForInput()
		{
			if (gm.isPaused)
			{
				return;
			}
			if (inputHandler.inputActions.up.WasPressed)
			{
				base.Fsm.Event(wasPressed);
			}
			if (inputHandler.inputActions.up.WasReleased)
			{
				base.Fsm.Event(wasReleased);
			}
			if (inputHandler.inputActions.up.IsPressed)
			{
				base.Fsm.Event(isPressed);
				if (!isPressedBool.IsNone)
				{
					isPressedBool.Value = true;
				}
			}
			if (!inputHandler.inputActions.up.IsPressed)
			{
				base.Fsm.Event(isNotPressed);
				if (!isPressedBool.IsNone)
				{
					isPressedBool.Value = false;
				}
			}
		}
	}
	[ActionCategory(ActionCategory.Transform)]
	[Tooltip("Jitter an object around using its Transform.")]
	public class ObjectJitter : FsmStateAction
	{
		[RequiredField]
		[Tooltip("The game object to translate.")]
		public FsmOwnerDefault gameObject;

		[Tooltip("Jitter along x axis.")]
		public FsmFloat x;

		[Tooltip("Jitter along y axis.")]
		public FsmFloat y;

		[Tooltip("Jitter along z axis.")]
		public FsmFloat z;

		[Tooltip("If true, don't jitter around start pos")]
		public FsmBool allowMovement;

		private float startX;

		private float startY;

		private float startZ;

		public override void Reset()
		{
			gameObject = null;
			x = new FsmFloat
			{
				UseVariable = true
			};
			y = new FsmFloat
			{
				UseVariable = true
			};
			z = new FsmFloat
			{
				UseVariable = true
			};
		}

		public override void OnPreprocess()
		{
			base.Fsm.HandleFixedUpdate = true;
		}

		public override void OnEnter()
		{
			GameObject ownerDefaultTarget = base.Fsm.GetOwnerDefaultTarget(gameObject);
			if (!(ownerDefaultTarget == null))
			{
				startX = ownerDefaultTarget.transform.position.x;
				startY = ownerDefaultTarget.transform.position.y;
				startZ = ownerDefaultTarget.transform.position.z;
			}
		}

		public override void OnFixedUpdate()
		{
			DoTranslate();
		}

		private void DoTranslate()
		{
			GameObject ownerDefaultTarget = base.Fsm.GetOwnerDefaultTarget(gameObject);
			if (!(ownerDefaultTarget == null))
			{
				if (allowMovement.Value)
				{
					ownerDefaultTarget.transform.Translate(UnityEngine.Random.Range(0f - x.Value, x.Value), UnityEngine.Random.Range(0f - y.Value, y.Value), UnityEngine.Random.Range(0f - z.Value, z.Value));
					return;
				}
				Vector3 position = new Vector3(startX + UnityEngine.Random.Range(0f - x.Value, x.Value), startY + UnityEngine.Random.Range(0f - y.Value, y.Value), startZ + UnityEngine.Random.Range(0f - z.Value, z.Value));
				ownerDefaultTarget.transform.position = position;
			}
		}
	}
	[ActionCategory(ActionCategory.Transform)]
	[Tooltip("Jitter an object around using its Transform.")]
