				Vector3 localPosition = new Vector3(startX + UnityEngine.Random.Range(0f - x.Value, x.Value), startY + UnityEngine.Random.Range(0f - y.Value, y.Value), startZ + UnityEngine.Random.Range(0f - z.Value, z.Value));
