	[ActionCategory("2D Toolkit/SpriteAnimator")]
	[Tooltip("Goto a specific frame for current animation.")]
	public class Tk2dPlayFrame : FsmStateAction
	{
		[RequiredField]
		[Tooltip("The Game Object to work with. NOTE: The Game Object must have a tk2dSpriteAnimator component attached.")]
		[CheckForComponent(typeof(tk2dSpriteAnimator))]
		public FsmOwnerDefault gameObject;

		[RequiredField]
		public FsmInt frame;

		private tk2dSpriteAnimator _sprite;

		private void _getSprite()
		{
			GameObject ownerDefaultTarget = base.Fsm.GetOwnerDefaultTarget(gameObject);
			if (!(ownerDefaultTarget == null))
			{
				_sprite = ownerDefaultTarget.GetComponent<tk2dSpriteAnimator>();
			}
		}

		public override void Reset()
		{
			gameObject = null;
			frame = 0;
		}

		public override void OnEnter()
		{
			_getSprite();
			if ((bool)_sprite)
			{
				_sprite.PlayFromFrame(frame.Value);
			}
			else
			{
				UnityEngine.Debug.LogWarning("No tk2d sprite animator found on " + base.Owner.name);
			}
			Finish();
		}
	}
	[ActionCategory("Particle System")]
	[Tooltip("Set particle emission on or off on an object with a particle emitter")]
	public class PlayParticleEmitter : FsmStateAction
	{
		[RequiredField]
		[Tooltip("The particle emitting GameObject")]
		public FsmOwnerDefault gameObject;

		public FsmInt emit;

		public override void Reset()
		{
			gameObject = null;
			emit = new FsmInt(0);
		}

		public override void OnEnter()
		{
			if (gameObject != null)
			{
				GameObject ownerDefaultTarget = base.Fsm.GetOwnerDefaultTarget(gameObject);
				if (ownerDefaultTarget != null)
				{
					ParticleSystem component = ownerDefaultTarget.GetComponent<ParticleSystem>();
					if ((bool)component && !component.isPlaying && emit.Value <= 0)
					{
						component.Play();
					}
					else if (emit.Value > 0)
					{
						component.Emit(emit.Value);
					}
				}
			}
			Finish();
		}
	}
	[ActionCategory("Particle System")]
	[Tooltip("Set particle emission on or off on an object with a particle emitter")]
	public class PlayParticleEmitterInState : FsmStateAction
	{
		[RequiredField]
		[Tooltip("The particle emitting GameObject")]
		public FsmOwnerDefault gameObject;

		public override void Reset()
		{
			gameObject = null;
		}

		public override void OnEnter()
		{
			if (gameObject == null)
			{
				return;
			}
			GameObject ownerDefaultTarget = base.Fsm.GetOwnerDefaultTarget(gameObject);
			if (ownerDefaultTarget != null)
			{
				ParticleSystem component = ownerDefaultTarget.GetComponent<ParticleSystem>();
				if ((bool)component && !component.isPlaying)
				{
					component.Play();
				}
			}
		}

		public override void OnExit()
		{
			if (gameObject == null)
			{
				return;
			}
			GameObject ownerDefaultTarget = base.Fsm.GetOwnerDefaultTarget(gameObject);
			if (ownerDefaultTarget != null)
			{
				ParticleSystem component = ownerDefaultTarget.GetComponent<ParticleSystem>();
				if ((bool)component && component.isPlaying)
				{
					component.Stop();
				}
			}
		}
	}
	[ActionCategory(ActionCategory.Logic)]
	[Tooltip("Sends Events based on the value of a Boolean Variable.")]
	public class PlayerDataBoolAllTrue : FsmStateAction
	{
		[RequiredField]
		[Tooltip("GameManager reference, set this to the global variable GameManager.")]
		public FsmOwnerDefault gameObject;

		[RequiredField]
		public FsmString[] stringVariables;

		[Tooltip("Event to send if all the Bool variables are True.")]
		public FsmEvent trueEvent;

		[Tooltip("Event to send if not all the bool variables are true.")]
		public FsmEvent falseEvent;

		[UIHint(UIHint.Variable)]
		[Tooltip("Store the result in a Bool variable.")]
		public FsmBool storeResult;

		[Tooltip("Repeat every frame while the state is active.")]
		public bool everyFrame;

		private bool boolCheck;

		private GameManager gm;

		public override void Reset()
		{
			gameObject = null;
			stringVariables = null;
			trueEvent = null;
			falseEvent = null;
			storeResult = null;
			everyFrame = false;
		}

		public override void OnEnter()
		{
			GameObject ownerDefaultTarget = base.Fsm.GetOwnerDefaultTarget(gameObject);
			if (ownerDefaultTarget == null)
			{
				return;
			}
			gm = ownerDefaultTarget.GetComponent<GameManager>();
			if (!(gm == null))
			{
				DoAllTrue();
				if (!everyFrame)
				{
					Finish();
				}
			}
		}

		public override void OnUpdate()
		{
			DoAllTrue();
		}

		private void DoAllTrue()
		{
			if (stringVariables.Length == 0)
			{
				return;
			}
			bool flag = true;
			for (int i = 0; i < stringVariables.Length; i++)
			{
				if (!gm.GetPlayerDataBool(stringVariables[i].Value))
				{
					flag = false;
					break;
				}
			}
			if (flag)
			{
				base.Fsm.Event(trueEvent);
			}
			else
			{
				base.Fsm.Event(falseEvent);
			}
			storeResult.Value = flag;
		}
	}
