	[ActionCategory("Physics 2d")]
	[Tooltip("Casts a Ray against all Colliders in the scene. A raycast is conceptually like a laser beam that is fired from a point in space along a particular direction. Any object making contact with the beam can be detected and reported. Use GetRaycastHit2dInfo to get more detailed info. CHERRYNOTE: Added ability to measure distance in units to hit point.")]
	public class RayCast2dV2 : FsmStateAction
	{
		[ActionSection("Setup")]
		[Tooltip("Start ray at game object position. \nOr use From Position parameter.")]
		public FsmOwnerDefault fromGameObject;

		[Tooltip("Start ray at a vector2 world position. \nOr use Game Object parameter.")]
		public FsmVector2 fromPosition;

		[Tooltip("A vector2 direction vector")]
		public FsmVector2 direction;

		[Tooltip("Cast the ray in world or local space. Note if no Game Object is specified, the direction is in world space.")]
		public Space space;

		[Tooltip("The length of the ray. Set to -1 for infinity.")]
		public FsmFloat distance;

		[Tooltip("Only include objects with a Z coordinate (depth) greater than this value. leave to none for no effect")]
		public FsmInt minDepth;

		[Tooltip("Only include objects with a Z coordinate (depth) less than this value. leave to none")]
		public FsmInt maxDepth;

		[ActionSection("Result")]
		[Tooltip("Event to send if the ray hits an object.")]
		[UIHint(UIHint.Variable)]
		public FsmEvent hitEvent;

		[Tooltip("Set a bool variable to true if hit something, otherwise false.")]
		[UIHint(UIHint.Variable)]
		public FsmBool storeDidHit;

		[Tooltip("Store the game object hit in a variable.")]
		[UIHint(UIHint.Variable)]
		public FsmGameObject storeHitObject;

		[UIHint(UIHint.Variable)]
		[Tooltip("Get the 2d position of the ray hit point and store it in a variable.")]
		public FsmVector2 storeHitPoint;

		[UIHint(UIHint.Variable)]
		[Tooltip("Get the 2d normal at the hit point and store it in a variable.")]
		public FsmVector2 storeHitNormal;

		[UIHint(UIHint.Variable)]
		[Tooltip("Get the distance along the ray to the hit point and store it in a variable.")]
		public FsmFloat storeHitDistance;

		[UIHint(UIHint.Variable)]
		[Tooltip("Get the distance in units... hopefully.")]
		public FsmFloat storeDistance;

		[ActionSection("Filter")]
		[Tooltip("Set how often to cast a ray. 0 = once, don't repeat; 1 = everyFrame; 2 = every other frame... \nSince raycasts can get expensive use the highest repeat interval you can get away with.")]
		public FsmInt repeatInterval;

		[UIHint(UIHint.Layer)]
		[Tooltip("Pick only from these layers.")]
		public FsmInt[] layerMask;

		[Tooltip("Invert the mask, so you pick from all layers except those defined above.")]
		public FsmBool invertMask;

		[ActionSection("Debug")]
		[Tooltip("The color to use for the debug line.")]
		public FsmColor debugColor;

		[Tooltip("Draw a debug line. Note: Check Gizmos in the Game View to see it in game.")]
		public FsmBool debug;

		private Transform _trans;

		private int repeat;

		public override void Reset()
		{
			fromGameObject = null;
			fromPosition = new FsmVector2
			{
				UseVariable = true
			};
			direction = new FsmVector2
			{
				UseVariable = true
			};
			space = Space.Self;
			minDepth = new FsmInt
			{
				UseVariable = true
			};
			maxDepth = new FsmInt
			{
				UseVariable = true
			};
			distance = 100f;
			hitEvent = null;
			storeDidHit = null;
			storeHitObject = null;
			storeHitPoint = null;
			storeHitNormal = null;
			storeHitDistance = null;
			repeatInterval = 1;
			layerMask = new FsmInt[0];
			invertMask = false;
			debugColor = Color.yellow;
			debug = false;
		}

		public override void OnEnter()
		{
			GameObject ownerDefaultTarget = base.Fsm.GetOwnerDefaultTarget(fromGameObject);
			if (ownerDefaultTarget != null)
			{
				_trans = ownerDefaultTarget.transform;
			}
			DoRaycast();
			if (repeatInterval.Value == 0)
			{
				Finish();
			}
		}

		public override void OnUpdate()
		{
			repeat--;
			if (repeat == 0)
			{
				DoRaycast();
			}
		}

		private void DoRaycast()
		{
			repeat = repeatInterval.Value;
			if (distance.Value != 0f)
			{
				Vector2 value = fromPosition.Value;
				if (_trans != null)
				{
					value.x += _trans.position.x;
					value.y += _trans.position.y;
				}
				float a = float.PositiveInfinity;
				if (distance.Value > 0f)
				{
					a = distance.Value;
				}
				Vector2 normalized = direction.Value.normalized;
				if (_trans != null && space == Space.Self)
				{
					Vector3 vector = _trans.TransformDirection(new Vector3(direction.Value.x, direction.Value.y, 0f));
					normalized.x = vector.x;
					normalized.y = vector.y;
				}
				RaycastHit2D info;
				if (minDepth.IsNone && maxDepth.IsNone)
				{
					info = Physics2D.Raycast(value, normalized, a, ActionHelpers.LayerArrayToLayerMask(layerMask, invertMask.Value));
				}
				else
				{
					float num = (minDepth.IsNone ? float.NegativeInfinity : ((float)minDepth.Value));
					float num2 = (maxDepth.IsNone ? float.PositiveInfinity : ((float)maxDepth.Value));
					info = Physics2D.Raycast(value, normalized, a, ActionHelpers.LayerArrayToLayerMask(layerMask, invertMask.Value), num, num2);
				}
				PlayMakerUnity2d.RecordLastRaycastHitInfo(base.Fsm, info);
				bool flag = info.collider != null;
				storeDidHit.Value = flag;
				if (flag)
				{
					storeHitObject.Value = info.collider.gameObject;
					storeHitPoint.Value = info.point;
					storeHitNormal.Value = info.normal;
					storeHitDistance.Value = info.fraction;
					storeDistance.Value = info.distance;
					base.Fsm.Event(hitEvent);
				}
				if (debug.Value)
				{
					float num3 = Mathf.Min(a, 1000f);
					Vector3 vector2 = new Vector3(value.x, value.y, 0f);
					Vector3 vector3 = new Vector3(normalized.x, normalized.y, 0f);
					Vector3 end = vector2 + vector3 * num3;
					UnityEngine.Debug.DrawLine(vector2, end, debugColor.Value);
				}
			}
		}
	}
	[ActionCategory("Combat")]
	[Tooltip("Detect 2D entry collisions or triggers between the Owner of this FSM and other Game Objects that have a Damager FSM.")]
	public class ReceivedDamage : FsmStateAction
	{
		[UIHint(UIHint.Tag)]
		[Tooltip("Filter by Tag.")]
		public FsmString collideTag;

		[RequiredField]
		[Tooltip("Event to send if a collision is detected.")]
		public FsmEvent sendEvent;

		[Tooltip("Name of FSM to look for on colliding object.")]
		public FsmString fsmName;

		[UIHint(UIHint.Variable)]
		[Tooltip("Store the GameObject that collided with the Owner of this FSM.")]
		public FsmGameObject storeGameObject;

		[Tooltip("Ignore damage from Acid")]
		public FsmBool ignoreAcid;

		[Tooltip("Ignore damage from Water")]
		public FsmBool ignoreWater;

		private PlayMakerUnity2DProxy _proxy;

		public override void Reset()
		{
			collideTag = new FsmString
			{
				UseVariable = true
			};
			sendEvent = null;
			storeGameObject = null;
		}

		public override void OnEnter()
		{
			_proxy = base.Owner.GetComponent<PlayMakerUnity2DProxy>();
			if (_proxy == null)
			{
				_proxy = base.Owner.AddComponent<PlayMakerUnity2DProxy>();
			}
			_proxy.AddOnCollisionEnter2dDelegate(DoCollisionEnter2D);
			_proxy.AddOnTriggerEnter2dDelegate(DoTriggerEnter2D);
			_proxy.AddOnTriggerStay2dDelegate(DoTriggerStay2D);
		}

		public override void OnExit()
		{
			if (!(_proxy == null))
			{
				_proxy.RemoveOnCollisionEnter2dDelegate(DoCollisionEnter2D);
				_proxy.RemoveOnTriggerEnter2dDelegate(DoTriggerEnter2D);
				_proxy.RemoveOnTriggerStay2dDelegate(DoTriggerStay2D);
			}
		}

		public new void DoCollisionEnter2D(Collision2D collisionInfo)
		{
			if ((collisionInfo.collider.gameObject.tag == collideTag.Value || collideTag.IsNone || string.IsNullOrEmpty(collideTag.Value)) && (!ignoreAcid.Value || collisionInfo.gameObject.tag != "Acid") && (!ignoreWater.Value || collisionInfo.gameObject.tag != "Water Surface"))
			{
				StoreCollisionInfo(collisionInfo);
			}
		}

		public new void DoTriggerEnter2D(Collider2D collisionInfo)
		{
			if ((collisionInfo.gameObject.tag == collideTag.Value || collideTag.IsNone || string.IsNullOrEmpty(collideTag.Value)) && (!ignoreAcid.Value || collisionInfo.gameObject.tag != "Acid") && (!ignoreWater.Value || collisionInfo.gameObject.tag != "Water Surface"))
			{
				StoreTriggerInfo(collisionInfo);
			}
		}

		public new void DoTriggerStay2D(Collider2D collisionInfo)
		{
			if ((collisionInfo.gameObject.tag == collideTag.Value || collideTag.IsNone || string.IsNullOrEmpty(collideTag.Value)) && (!ignoreAcid.Value || collisionInfo.gameObject.tag != "Acid") && (!ignoreWater.Value || collisionInfo.gameObject.tag != "Water Surface"))
			{
				StoreTriggerInfo(collisionInfo);
			}
		}

		private void StoreCollisionInfo(Collision2D collisionInfo)
		{
			storeGameObject.Value = collisionInfo.gameObject;
			StoreIfDamagingObject(collisionInfo.gameObject);
		}

		private void StoreTriggerInfo(Collider2D collisionInfo)
		{
			storeGameObject.Value = collisionInfo.gameObject;
			StoreIfDamagingObject(collisionInfo.gameObject);
		}

		private void StoreIfDamagingObject(GameObject go)
		{
			PlayMakerFSM playMakerFSM = FSMUtility.LocateFSM(go, fsmName.Value);
			if (playMakerFSM != null && playMakerFSM.FsmVariables.GetFsmInt("damageDealt").Value > 0)
			{
				storeGameObject.Value = go;
				base.Fsm.Event(sendEvent);
			}
		}

		public override string ErrorCheck()
		{
			string text = string.Empty;
			if (base.Owner != null && base.Owner.GetComponent<Collider2D>() == null && base.Owner.GetComponent<Rigidbody2D>() == null)
			{
				text += "Owner requires a RigidBody2D or Collider2D!\n";
			}
			return text;
		}
	}
