	[ActionCategory(ActionCategory.ScriptControl)]
	[Tooltip("Sends a Message to a Game Object. See Unity docs for SendMessage.")]
	public class SendMessageV2 : FsmStateAction
	{
		public enum MessageType
		{
			SendMessage,
			SendMessageUpwards,
			BroadcastMessage
		}

		[RequiredField]
		[Tooltip("GameObject that sends the message.")]
		public FsmOwnerDefault gameObject;

		[Tooltip("Where to send the message.\nSee Unity docs.")]
		public MessageType delivery;

		[Tooltip("Send options.\nSee Unity docs.")]
		public SendMessageOptions options;

		[RequiredField]
		public FunctionCall functionCall;

		public bool everyFrame;

		public override void Reset()
		{
			gameObject = null;
			delivery = MessageType.SendMessage;
			options = SendMessageOptions.DontRequireReceiver;
			functionCall = null;
		}

		public override void OnUpdate()
		{
			DoSendMessage();
			if (!everyFrame)
			{
				Finish();
			}
		}

		private void DoSendMessage()
		{
			GameObject ownerDefaultTarget = base.Fsm.GetOwnerDefaultTarget(gameObject);
			if (!(ownerDefaultTarget == null))
			{
				object obj = null;
				switch (functionCall.ParameterType)
				{
				case "bool":
					obj = functionCall.BoolParameter.Value;
					break;
				case "int":
					obj = functionCall.IntParameter.Value;
					break;
				case "float":
					obj = functionCall.FloatParameter.Value;
					break;
				case "string":
					obj = functionCall.StringParameter.Value;
					break;
				case "Vector2":
					obj = functionCall.Vector2Parameter.Value;
					break;
				case "Vector3":
					obj = functionCall.Vector3Parameter.Value;
					break;
				case "Rect":
					obj = functionCall.RectParamater.Value;
					break;
				case "GameObject":
					obj = functionCall.GameObjectParameter.Value;
					break;
				case "Material":
					obj = functionCall.MaterialParameter.Value;
					break;
				case "Texture":
					obj = functionCall.TextureParameter.Value;
					break;
				case "Color":
					obj = functionCall.ColorParameter.Value;
					break;
				case "Quaternion":
					obj = functionCall.QuaternionParameter.Value;
					break;
				case "Object":
					obj = functionCall.ObjectParameter.Value;
					break;
				}
				switch (delivery)
				{
				case MessageType.SendMessage:
					ownerDefaultTarget.SendMessage(functionCall.FunctionName, obj, options);
					break;
				case MessageType.SendMessageUpwards:
					ownerDefaultTarget.SendMessageUpwards(functionCall.FunctionName, obj, options);
					break;
				case MessageType.BroadcastMessage:
					ownerDefaultTarget.BroadcastMessage(functionCall.FunctionName, obj, options);
					break;
				}
			}
		}
	}
	[ActionCategory(ActionCategory.StateMachine)]
	[Tooltip("Sends a Random Event picked from an array of Events. Optionally set the relative weight of each event. Use ints to keep events from being fired x times in a row.")]
	public class SendRandomEventV2 : FsmStateAction
	{
		[CompoundArray("Events", "Event", "Weight")]
		public FsmEvent[] events;

		[HasFloatSlider(0f, 1f)]
		public FsmFloat[] weights;

		[UIHint(UIHint.Variable)]
		public FsmInt[] trackingInts;

		public FsmInt[] eventMax;

		private DelayedEvent delayedEvent;

		public override void Reset()
		{
			events = new FsmEvent[3];
			weights = new FsmFloat[3] { 1f, 1f, 1f };
		}

		public override void OnEnter()
		{
			bool flag = false;
			while (!flag)
			{
				int randomWeightedIndex = ActionHelpers.GetRandomWeightedIndex(weights);
				if (randomWeightedIndex != -1 && trackingInts[randomWeightedIndex].Value < eventMax[randomWeightedIndex].Value)
				{
					int value = ++trackingInts[randomWeightedIndex].Value;
					for (int i = 0; i < trackingInts.Length; i++)
					{
						trackingInts[i].Value = 0;
					}
					trackingInts[randomWeightedIndex].Value = value;
					flag = true;
					base.Fsm.Event(events[randomWeightedIndex]);
				}
			}
			Finish();
		}
	}
	[ActionCategory(ActionCategory.StateMachine)]
	[Tooltip("Sends a Random Event picked from an array of Events. Optionally set the relative weight of each event. Use ints to keep events from being fired x times in a row.")]
	public class SendRandomEventV3 : FsmStateAction
	{
		[CompoundArray("Events", "Event", "Weight")]
		public FsmEvent[] events;

		[HasFloatSlider(0f, 1f)]
		public FsmFloat[] weights;

		[UIHint(UIHint.Variable)]
		public FsmInt[] trackingInts;

		public FsmInt[] eventMax;

		[UIHint(UIHint.Variable)]
		public FsmInt[] trackingIntsMissed;

		public FsmInt[] missedMax;

		private int loops;

		private DelayedEvent delayedEvent;

		public override void Reset()
		{
			events = new FsmEvent[3];
			weights = new FsmFloat[3] { 1f, 1f, 1f };
		}

		public override void OnEnter()
		{
			bool flag = false;
			bool flag2 = false;
			int num = 0;
			while (!flag)
			{
				int randomWeightedIndex = ActionHelpers.GetRandomWeightedIndex(weights);
				if (randomWeightedIndex != -1)
				{
					for (int i = 0; i < trackingIntsMissed.Length; i++)
					{
						if (trackingIntsMissed[i].Value >= missedMax[i].Value)
						{
							flag2 = true;
							num = i;
						}
					}
					if (flag2)
					{
						flag = true;
						for (int j = 0; j < trackingInts.Length; j++)
						{
							trackingInts[j].Value = 0;
							trackingIntsMissed[j].Value++;
						}
						trackingIntsMissed[num].Value = 0;
						trackingInts[num].Value = 1;
						base.Fsm.Event(events[num]);
					}
					else if (trackingInts[randomWeightedIndex].Value < eventMax[randomWeightedIndex].Value)
					{
						int value = ++trackingInts[randomWeightedIndex].Value;
						for (int k = 0; k < trackingInts.Length; k++)
						{
							trackingInts[k].Value = 0;
							trackingIntsMissed[k].Value++;
						}
						trackingInts[randomWeightedIndex].Value = value;
						trackingIntsMissed[randomWeightedIndex].Value = 0;
						flag = true;
						base.Fsm.Event(events[randomWeightedIndex]);
					}
				}
				loops++;
				if (loops > 100)
				{
					base.Fsm.Event(events[0]);
					flag = true;
					Finish();
				}
			}
			Finish();
		}
	}
	[ActionCategory("Physics 2d")]
	[Tooltip("Detect 2D trigger collisions between the Owner of this FSM and other Game Objects that have RigidBody2D components.\nNOTE: The system events, TRIGGER ENTER 2D, TRIGGER STAY 2D, and TRIGGER EXIT 2D are sent automatically on collisions triggers with any object. Use this action to filter collision triggers by Tag.")]
	public class SendTrigger2DEvent : FsmStateAction
	{
		[Tooltip("Where to send the event.")]
		public FsmEventTarget eventTarget;

		[Tooltip("The type of trigger to detect.")]
		public PlayMakerUnity2d.Trigger2DType trigger;

		[UIHint(UIHint.Tag)]
		[Tooltip("Filter by Tag.")]
		public FsmString collideTag;

		[UIHint(UIHint.Layer)]
		[Tooltip("Filter by Layer.")]
		public FsmInt collideLayer;

		[RequiredField]
		[Tooltip("Event to send if a collision is detected.")]
		public FsmEvent sendEvent;

		[UIHint(UIHint.Variable)]
		[Tooltip("Store the GameObject that collided with the Owner of this FSM.")]
		public FsmGameObject storeCollider;

		private PlayMakerUnity2DProxy _proxy;

		public override void Reset()
		{
			trigger = PlayMakerUnity2d.Trigger2DType.OnTriggerEnter2D;
			collideTag = new FsmString
			{
				UseVariable = true
			};
			collideLayer = new FsmInt
			{
				UseVariable = true
			};
			sendEvent = null;
			storeCollider = null;
		}

		public override void OnEnter()
		{
			_proxy = base.Owner.GetComponent<PlayMakerUnity2DProxy>();
			if (_proxy == null)
			{
				_proxy = base.Owner.AddComponent<PlayMakerUnity2DProxy>();
			}
			switch (trigger)
			{
			case PlayMakerUnity2d.Trigger2DType.OnTriggerEnter2D:
				_proxy.AddOnTriggerEnter2dDelegate(DoTriggerEnter2D);
				break;
			case PlayMakerUnity2d.Trigger2DType.OnTriggerStay2D:
				_proxy.AddOnTriggerStay2dDelegate(DoTriggerStay2D);
				break;
			case PlayMakerUnity2d.Trigger2DType.OnTriggerExit2D:
				_proxy.AddOnTriggerExit2dDelegate(DoTriggerExit2D);
				break;
			}
		}

		public override void OnExit()
		{
			if (!(_proxy == null))
			{
				switch (trigger)
				{
				case PlayMakerUnity2d.Trigger2DType.OnTriggerEnter2D:
					_proxy.RemoveOnTriggerEnter2dDelegate(DoTriggerEnter2D);
					break;
				case PlayMakerUnity2d.Trigger2DType.OnTriggerStay2D:
					_proxy.RemoveOnTriggerStay2dDelegate(DoTriggerStay2D);
					break;
				case PlayMakerUnity2d.Trigger2DType.OnTriggerExit2D:
					_proxy.RemoveOnTriggerExit2dDelegate(DoTriggerExit2D);
					break;
				}
			}
		}

		private void StoreCollisionInfo(Collider2D collisionInfo)
		{
			storeCollider.Value = collisionInfo.gameObject;
		}

		public new void DoTriggerEnter2D(Collider2D collisionInfo)
		{
			if (trigger == PlayMakerUnity2d.Trigger2DType.OnTriggerEnter2D && (collisionInfo.gameObject.tag == collideTag.Value || collideTag.IsNone || string.IsNullOrEmpty(collideTag.Value)) && (collisionInfo.gameObject.layer == collideLayer.Value || collideLayer.IsNone))
			{
				StoreCollisionInfo(collisionInfo);
				base.Fsm.Event(eventTarget, sendEvent);
			}
		}

		public new void DoTriggerStay2D(Collider2D collisionInfo)
		{
			if (trigger == PlayMakerUnity2d.Trigger2DType.OnTriggerStay2D && (collisionInfo.gameObject.tag == collideTag.Value || collideTag.IsNone || string.IsNullOrEmpty(collideTag.Value)) && (collisionInfo.gameObject.layer == collideLayer.Value || collideLayer.IsNone))
			{
				StoreCollisionInfo(collisionInfo);
				base.Fsm.Event(eventTarget, sendEvent);
			}
		}

		public new void DoTriggerExit2D(Collider2D collisionInfo)
		{
			if (trigger == PlayMakerUnity2d.Trigger2DType.OnTriggerExit2D && (collisionInfo.gameObject.tag == collideTag.Value || collideTag.IsNone || string.IsNullOrEmpty(collideTag.Value)) && (collisionInfo.gameObject.layer == collideLayer.Value || collideLayer.IsNone))
			{
				StoreCollisionInfo(collisionInfo);
				base.Fsm.Event(eventTarget, sendEvent);
			}
		}

		public override string ErrorCheck()
		{
			string text = string.Empty;
			if (base.Owner != null && base.Owner.GetComponent<Collider2D>() == null && base.Owner.GetComponent<Rigidbody2D>() == null)
			{
				text += "Owner requires a RigidBody2D or Collider2D!\n";
			}
			return text;
		}
	}
