	[ActionCategory("Hollow Knight")]
	[Tooltip("Randomly shakes a GameObject's position by a diminishing amount over time.")]
	public class ShakePosition : FsmStateAction
	{
		[RequiredField]
		public FsmOwnerDefault gameObject;

		[RequiredField]
		public FsmVector3 extents;

		public FsmFloat duration;

		public FsmBool isLooping;

		public FsmEvent stopEvent;

		private float timer;

		private Transform target;

		private Vector3 startingWorldPosition;

		public override void Reset()
		{
			base.Reset();
			gameObject = new FsmOwnerDefault
			{
				OwnerOption = OwnerDefaultOption.UseOwner
			};
			duration = 1f;
			isLooping = false;
			stopEvent = null;
		}

		public override void OnEnter()
		{
			base.OnEnter();
			timer = 0f;
			GameObject safe = gameObject.GetSafe(this);
			if (safe != null)
			{
				target = safe.transform;
				startingWorldPosition = target.position;
			}
			else
			{
				target = null;
			}
			UpdateShaking();
		}

		public override void OnUpdate()
		{
			base.OnUpdate();
			UpdateShaking();
		}

		public override void OnExit()
		{
			StopAndReset();
			base.OnExit();
		}

		private void UpdateShaking()
		{
			if (target != null)
			{
				bool value = isLooping.Value;
				float num = Mathf.Clamp01(1f - timer / duration.Value);
				Vector3 vector = Vector3.Scale(extents.Value, new Vector3(UnityEngine.Random.Range(-1f, 1f), UnityEngine.Random.Range(-1f, 1f), UnityEngine.Random.Range(-1f, 1f)));
				target.position = startingWorldPosition + vector * (value ? 1f : num);
				timer += Time.deltaTime;
				if (!value && timer > duration.Value)
				{
					StopAndReset();
					base.Fsm.Event(stopEvent);
					Finish();
				}
			}
			else
			{
				StopAndReset();
				base.Fsm.Event(stopEvent);
				Finish();
			}
		}

		private void StopAndReset()
		{
			if (target != null)
			{
				target.position = startingWorldPosition;
				target = null;
			}
		}
	}
	[ActionCategory("Hollow Knight")]
	[Tooltip("Randomly shakes a GameObject's position by a diminishing amount over time.")]
	public class ShakePositionV2 : FsmStateAction
	{
		[RequiredField]
		public FsmOwnerDefault Target;

		[RequiredField]
		public FsmVector3 Extents;

		public FsmFloat Duration;

		public FsmBool IsLooping;

		public FsmEvent StopEvent;

		public FsmFloat FpsLimit;

		public FsmBool IsCameraShake;

		private float timer;

		private float nextUpdateTime;

		private Transform target;

		private Vector3 startingWorldPosition;

		public override void Reset()
		{
			base.Reset();
			Target = new FsmOwnerDefault
			{
				OwnerOption = OwnerDefaultOption.UseOwner
			};
			Extents = null;
			Duration = 1f;
			IsLooping = false;
			StopEvent = null;
			FpsLimit = null;
			IsCameraShake = null;
		}

		public override void OnEnter()
		{
			base.OnEnter();
			timer = 0f;
			GameObject safe = Target.GetSafe(this);
			if (safe != null)
			{
				target = safe.transform;
				startingWorldPosition = target.position;
			}
			else
			{
				target = null;
			}
			UpdateShaking();
		}

		public override void OnUpdate()
		{
			base.OnUpdate();
			UpdateShaking();
		}

		public override void OnExit()
		{
			StopAndReset();
			base.OnExit();
		}

		private void UpdateShaking()
		{
			if (target != null)
			{
				timer += Time.deltaTime;
				if (FpsLimit.Value > 0f)
				{
					if (Time.unscaledTime < nextUpdateTime)
					{
						return;
					}
					nextUpdateTime = Time.unscaledTime + 1f / FpsLimit.Value;
				}
				bool value = IsLooping.Value;
				float num = (value ? 1f : Mathf.Clamp01(1f - timer / Duration.Value));
				if (IsCameraShake.Value)
				{
					num *= ConfigManager.CameraShakeMultiplier;
				}
				Vector3 vector = Vector3.Scale(Extents.Value, new Vector3(UnityEngine.Random.Range(-1f, 1f), UnityEngine.Random.Range(-1f, 1f), UnityEngine.Random.Range(-1f, 1f)));
				target.position = startingWorldPosition + vector * num;
				if (!value && timer > Duration.Value)
				{
					StopAndReset();
					base.Fsm.Event(StopEvent);
					Finish();
				}
			}
			else
			{
				StopAndReset();
				base.Fsm.Event(StopEvent);
				Finish();
			}
		}

		private void StopAndReset()
		{
			if (target != null)
			{
				target.position = startingWorldPosition;
				target = null;
			}
		}
	}
	[ActionCategory("Enemy AI")]
	[Tooltip("Flies and keeps a certain distance from target, with smoother movement")]
	public class SmoothFlyTo : RigidBody2dActionBase
	{
		[RequiredField]
		[CheckForComponent(typeof(Rigidbody2D))]
		[UIHint(UIHint.Variable)]
		public FsmOwnerDefault gameObject;

		[UIHint(UIHint.Variable)]
		public FsmGameObject target;

		public FsmFloat distance;

		public FsmFloat speedMax;

		public FsmFloat accelerationForce;

		public FsmFloat targetRadius;

		public FsmFloat deceleration;

		public FsmVector3 offset;

		private float distanceAway;

		private FsmGameObject self;

		public override void Reset()
		{
			gameObject = null;
			target = null;
			accelerationForce = 0f;
			speedMax = 0f;
		}

		public override void Awake()
		{
			base.Fsm.HandleFixedUpdate = true;
		}

		public override void OnPreprocess()
		{
			base.Fsm.HandleFixedUpdate = true;
		}

		public override void OnEnter()
		{
			CacheRigidBody2d(base.Fsm.GetOwnerDefaultTarget(gameObject));
			self = base.Fsm.GetOwnerDefaultTarget(gameObject);
			DoChase();
		}

		public override void OnFixedUpdate()
		{
			DoChase();
		}

		private void DoChase()
		{
			if (rb2d == null)
			{
				return;
			}
			distanceAway = Mathf.Sqrt(Mathf.Pow(self.Value.transform.position.x - (target.Value.transform.position.x + offset.Value.x), 2f) + Mathf.Pow(self.Value.transform.position.y - (target.Value.transform.position.y + offset.Value.y), 2f));
			Vector2 velocity = rb2d.velocity;
			if (!(distanceAway > distance.Value - targetRadius.Value) || !(distanceAway < distance.Value + targetRadius.Value))
			{
				Vector2 vector = new Vector2(target.Value.transform.position.x + offset.Value.x - self.Value.transform.position.x, target.Value.transform.position.y + offset.Value.y - self.Value.transform.position.y);
				vector = Vector2.ClampMagnitude(vector, 1f);
				vector = new Vector2(vector.x * accelerationForce.Value, vector.y * accelerationForce.Value);
				if (distanceAway < distance.Value)
				{
					vector = new Vector2(0f - vector.x, 0f - vector.y);
				}
				rb2d.AddForce(vector);
				velocity = Vector2.ClampMagnitude(velocity, speedMax.Value);
				rb2d.velocity = velocity;
				return;
			}
			velocity = rb2d.velocity;
			if (velocity.x < 0f)
			{
				velocity.x *= deceleration.Value;
				if (velocity.x > 0f)
				{
					velocity.x = 0f;
				}
			}
			else if (velocity.x > 0f)
			{
				velocity.x *= deceleration.Value;
				if (velocity.x < 0f)
				{
					velocity.x = 0f;
				}
			}
			if (velocity.y < 0f)
			{
				velocity.y *= deceleration.Value;
				if (velocity.y > 0f)
				{
					velocity.y = 0f;
				}
			}
			else if (velocity.y > 0f)
			{
				velocity.y *= deceleration.Value;
				if (velocity.y < 0f)
				{
					velocity.y = 0f;
				}
			}
			rb2d.velocity = velocity;
		}
	}
	[ActionCategory(ActionCategory.Camera)]
	[Tooltip("Follows a target GameObject smoothly in 2D space")]
	public class SmoothFollowTarget2D : FsmStateAction
	{
		[RequiredField]
		[Tooltip("Camera to control.")]
		[CheckForComponent(typeof(Camera))]
		public FsmOwnerDefault gameObject;

		[Tooltip("The GameObject to follow.")]
		public FsmGameObject targetObject;

		[RequiredField]
		public float dampTime;

		private Camera camera;

		private GameObject target;

		private Transform transform;

		public override void Reset()
		{
			dampTime = 0.1f;
		}

		public override void OnEnter()
		{
			camera = base.Fsm.GetOwnerDefaultTarget(gameObject).GetComponent<Camera>();
			if (targetObject != null && !(camera == null))
			{
				target = targetObject.Value;
			}
		}

		public override void OnUpdate()
		{
			Vector3 vector = camera.WorldToViewportPoint(target.transform.position);
			Vector3 vector2 = target.transform.position - camera.ViewportToWorldPoint(new Vector3(0.5f, 0.5f, vector.z));
			Vector3 vector3 = camera.transform.position + vector2;
			Vector3 currentVelocity = Vector3.zero;
			camera.transform.position = Vector3.SmoothDamp(camera.transform.position, vector3, ref currentVelocity, dampTime);
		}
	}
	[ActionCategory(ActionCategory.GameObject)]
	[Tooltip("Activates a certain amount of objects held in designated Object Pool and fires them off")]
	public class SpawnFromPool : RigidBody2dActionBase
	{
		[RequiredField]
		[Tooltip("Pool object to draw from.")]
		public FsmGameObject pool;

		public FsmVector3 adjustPosition;

		[Tooltip("Minimum amount of objects to be spawned.")]
		public FsmInt spawnMin;

		[Tooltip("Maximum amount of clones to be spawned.")]
		public FsmInt spawnMax;

		[Tooltip("Minimum speed clones are fired at.")]
		public FsmFloat speedMin;

		[Tooltip("Maximum speed clones are fired at.")]
		public FsmFloat speedMax;

		[Tooltip("Minimum angle clones are fired at.")]
		public FsmFloat angleMin;

		[Tooltip("Maximum angle clones are fired at.")]
		public FsmFloat angleMax;

		private float vectorX;

		private float vectorY;

		private bool originAdjusted;

		public override void Reset()
		{
			pool = null;
			adjustPosition = null;
			spawnMin = null;
			spawnMax = null;
			speedMin = null;
			speedMax = null;
			angleMin = null;
			angleMax = null;
		}

		public override void OnEnter()
		{
			GameObject value = pool.Value;
			if (value != null)
			{
				int num = UnityEngine.Random.Range(spawnMin.Value, spawnMax.Value + 1);
				Vector2 velocity = default(Vector2);
				for (int i = 1; i <= num; i++)
				{
					int childCount = value.transform.childCount;
					if (childCount <= 0)
					{
						Finish();
					}
					if (childCount == 0)
					{
						return;
					}
					GameObject gameObject = value.transform.GetChild(UnityEngine.Random.Range(0, childCount)).gameObject;
					gameObject.SetActive(value: true);
					CacheRigidBody2d(gameObject);
					float num2 = UnityEngine.Random.Range(speedMin.Value, speedMax.Value);
					float num3 = UnityEngine.Random.Range(angleMin.Value, angleMax.Value);
					vectorX = num2 * Mathf.Cos(num3 * ((float)Math.PI / 180f));
					vectorY = num2 * Mathf.Sin(num3 * ((float)Math.PI / 180f));
					velocity.x = vectorX;
					velocity.y = vectorY;
					rb2d.velocity = velocity;
					if (!adjustPosition.IsNone)
					{
						gameObject.transform.position += adjustPosition.Value;
					}
					gameObject.transform.parent = null;
				}
			}
			Finish();
		}
	}
