		public override void Reset()
		{
			pool = null;
			setPosition = null;
			spawnMin = null;
			spawnMax = null;
			speedMin = null;
			speedMax = null;
			angleMin = null;
			angleMax = null;
		}

		public override void OnEnter()
		{
			GameObject value = pool.Value;
			if (value != null)
			{
				int num = UnityEngine.Random.Range(spawnMin.Value, spawnMax.Value + 1);
				Vector2 velocity = default(Vector2);
				for (int i = 1; i <= num; i++)
				{
					int childCount = value.transform.childCount;
					if (childCount <= 0)
					{
						Finish();
					}
					if (childCount == 0)
					{
						return;
					}
					GameObject gameObject = value.transform.GetChild(UnityEngine.Random.Range(0, childCount)).gameObject;
					gameObject.SetActive(value: true);
					CacheRigidBody2d(gameObject);
					float num2 = UnityEngine.Random.Range(speedMin.Value, speedMax.Value);
					float num3 = UnityEngine.Random.Range(angleMin.Value, angleMax.Value);
					vectorX = num2 * Mathf.Cos(num3 * ((float)Math.PI / 180f));
					vectorY = num2 * Mathf.Sin(num3 * ((float)Math.PI / 180f));
					velocity.x = vectorX;
					velocity.y = vectorY;
					rb2d.velocity = velocity;
					if (!FSM.IsNone)
					{
						FSMUtility.LocateFSM(gameObject, FSM.Value).SendEvent(FSMEvent.Value);
					}
					if (!setPosition.IsNone)
					{
						gameObject.transform.position = setPosition.Value;
					}
					gameObject.transform.parent = null;
				}
			}
			Finish();
		}
	}
