		[Tooltip("GameObject to spawn at (optional).")]
		public FsmGameObject spawnPoint;

		[Tooltip("Position. If a Spawn Point is defined, this is used as a local offset from the Spawn Point position.")]
		public FsmVector3 position;

		[Tooltip("Minimum amount of clones to be spawned.")]
		public FsmInt spawnMin;

		[Tooltip("Maximum amount of clones to be spawned.")]
		public FsmInt spawnMax;

		public FsmFloat speedMinX;

		public FsmFloat speedMaxX;

		public FsmFloat speedMinY;

		public FsmFloat speedMaxY;

		[Tooltip("Randomises spawn points of objects within this range. Leave as 0 and all objects will spawn at same point.")]
		public FsmFloat originVariationX;

		public FsmFloat originVariationY;

		private float vectorX;

		private float vectorY;

		private bool originAdjusted;

		public override void Reset()
		{
			gameObject = null;
			spawnPoint = null;
			position = new FsmVector3
			{
				UseVariable = true
			};
			spawnMin = null;
			spawnMax = null;
			speedMinX = null;
			speedMaxX = null;
			speedMinY = null;
			speedMaxY = null;
			originVariationX = null;
			originVariationY = null;
		}

		public override void OnEnter()
		{
			GameObject value = this.gameObject.Value;
			if (value != null)
			{
				Vector3 vector = Vector3.zero;
				Vector3 zero = Vector3.zero;
				if (spawnPoint.Value != null)
				{
					vector = spawnPoint.Value.transform.position;
					if (!position.IsNone)
					{
						vector += position.Value;
					}
				}
				else if (!position.IsNone)
				{
					vector = position.Value;
				}
				int num = UnityEngine.Random.Range(spawnMin.Value, spawnMax.Value + 1);
				for (int i = 1; i <= num; i++)
				{
					GameObject gameObject = UnityEngine.Object.Instantiate(value, vector, Quaternion.Euler(zero));
					float x = gameObject.transform.position.x;
					float y = gameObject.transform.position.y;
					float z = gameObject.transform.position.z;
					if (originVariationX != null)
					{
						x = gameObject.transform.position.x + UnityEngine.Random.Range(0f - originVariationX.Value, originVariationX.Value);
						originAdjusted = true;
					}
					if (originVariationY != null)
					{
						y = gameObject.transform.position.y + UnityEngine.Random.Range(0f - originVariationY.Value, originVariationY.Value);
						originAdjusted = true;
					}
					if (originAdjusted)
					{
						gameObject.transform.position = new Vector3(x, y, z);
					}
					CacheRigidBody2d(gameObject);
					float x2 = UnityEngine.Random.Range(speedMinX.Value, speedMaxX.Value);
					float y2 = UnityEngine.Random.Range(speedMinY.Value, speedMaxY.Value);
					Vector2 velocity = new Vector2(x2, y2);
					rb2d.velocity = velocity;
				}
			}
			Finish();
		}
	}
	[ActionCategory("Particle System")]
	[Tooltip("Set particle emission on or off on an object with a particle emitter")]
	public class StopParticleEmitter : FsmStateAction
	{
		[RequiredField]
		[Tooltip("The particle emitting GameObject")]
		public FsmOwnerDefault gameObject;

		public override void Reset()
		{
			gameObject = null;
		}

		public override void OnEnter()
		{
			if (gameObject != null)
			{
				GameObject ownerDefaultTarget = base.Fsm.GetOwnerDefaultTarget(gameObject);
				if (ownerDefaultTarget != null)
				{
					ParticleSystem component = ownerDefaultTarget.GetComponent<ParticleSystem>();
					if ((bool)component && component.isPlaying)
					{
						component.Stop();
					}
				}
			}
			Finish();
		}
	}
	[ActionCategory("Particle System")]
	[Tooltip("Set particle emission on or off on an object with a particle emitter")]
	public class StopParticleEmittersInChildren : FsmStateAction
	{
		[RequiredField]
		[Tooltip("The particle emitting GameObject")]
		public FsmOwnerDefault gameObject;

		public override void Reset()
		{
			gameObject = null;
		}

		public override void OnEnter()
		{
			if (gameObject != null)
			{
				GameObject ownerDefaultTarget = base.Fsm.GetOwnerDefaultTarget(gameObject);
				if (ownerDefaultTarget != null)
				{
					ParticleSystem[] componentsInChildren = ownerDefaultTarget.GetComponentsInChildren<ParticleSystem>();
					foreach (ParticleSystem particleSystem in componentsInChildren)
					{
						if (particleSystem.isPlaying)
						{
							particleSystem.Stop();
						}
					}
				}
			}
			Finish();
		}
	}
	[ActionCategory("Hollow Knight")]
	[Tooltip("Change behaviour based on platform.")]
	public class SwitchOnPlatform : FsmStateAction
	{
		public FsmEvent Standalone;

		public FsmEvent Switch;

		public FsmEvent PS4;

		public FsmEvent XB1;

		public FsmEvent Other;

		public override void Reset()
		{
			Standalone = null;
			Switch = null;
			PS4 = null;
			XB1 = null;
			Other = null;
		}

		public override void OnEnter()
		{
			switch (Application.platform)
			{
			case RuntimePlatform.OSXPlayer:
			case RuntimePlatform.WindowsPlayer:
			case RuntimePlatform.LinuxPlayer:
				base.Fsm.Event(Standalone);
				break;
			case RuntimePlatform.Switch:
				base.Fsm.Event(Switch);
				break;
			case RuntimePlatform.PS4:
				base.Fsm.Event(PS4);
				break;
			case RuntimePlatform.XboxOne:
				base.Fsm.Event(XB1);
				break;
			default:
				base.Fsm.Event(Other);
				break;
			}
			Finish();
		}
	}
