	[ActionCategory("2D Toolkit/SpriteAnimator")]
	[Tooltip("Plays a sprite animation. \nNOTE: The Game Object must have a tk2dSpriteAnimator attached.")]
	public class Tk2dPlayAnimationV2 : FsmStateAction
	{
		[RequiredField]
		[Tooltip("The Game Object to work with. NOTE: The Game Object must have a tk2dSpriteAnimator component attached.")]
		[CheckForComponent(typeof(tk2dSpriteAnimator))]
		public FsmOwnerDefault gameObject;

		[Tooltip("The anim Lib name. Leave empty to use the one current selected")]
		public FsmString animLibName;

		[RequiredField]
		[Tooltip("The clip name to play")]
		public FsmString clipName;

		[Tooltip("If true and requested anim clip is same as current clip, don't replay clip from the start")]
		public bool doNotResetCurrentClip;

		private tk2dSpriteAnimator _sprite;

		private void _getSprite()
		{
			GameObject ownerDefaultTarget = base.Fsm.GetOwnerDefaultTarget(gameObject);
			if (!(ownerDefaultTarget == null))
			{
				_sprite = ownerDefaultTarget.GetComponent<tk2dSpriteAnimator>();
			}
		}

		public override void Reset()
		{
			gameObject = null;
			animLibName = null;
			clipName = null;
			doNotResetCurrentClip = false;
		}

		public override void OnEnter()
		{
			_getSprite();
			DoPlayAnimation();
			Finish();
		}

		private void DoPlayAnimation()
		{
			if (_sprite == null)
			{
				LogWarning("Missing tk2dSpriteAnimator component");
			}
			else if (!doNotResetCurrentClip || !(clipName.Value == _sprite.CurrentClip.name))
			{
				_sprite.Play(clipName.Value);
			}
		}
	}
	[ActionCategory("2D Toolkit/Sprite")]
	[Tooltip("Randomly set the sprite id of a sprite. \nNOTE: The Game Object must have a tk2dBaseSprite or derived component attached ( tk2dSprite, tk2dAnimatedSprite)")]
	public class Tk2dSpriteSetIdRandom : FsmStateAction
	{
		[RequiredField]
		[Tooltip("The Game Object to work with. NOTE: The Game Object must have a tk2dBaseSprite or derived component attached ( tk2dSprite, tk2dAnimatedSprite).")]
		[CheckForComponent(typeof(tk2dBaseSprite))]
		public FsmOwnerDefault gameObject;

		[CheckForComponent(typeof(tk2dSpriteCollection))]
		public FsmGameObject spriteCollection;

		private tk2dBaseSprite _sprite;

		private void _getSprite()
		{
			GameObject ownerDefaultTarget = base.Fsm.GetOwnerDefaultTarget(gameObject);
			if (!(ownerDefaultTarget == null))
			{
				_sprite = ownerDefaultTarget.GetComponent<tk2dBaseSprite>();
			}
		}

		public override void Reset()
		{
			gameObject = null;
			spriteCollection = new FsmGameObject
			{
				UseVariable = true
			};
		}

		public override void OnEnter()
		{
			_getSprite();
			DoSetSpriteID();
			Finish();
		}

		private void DoSetSpriteID()
		{
			if (_sprite == null)
			{
				LogWarning("Missing tk2dBaseSprite component: " + _sprite.gameObject.name);
				return;
			}
			tk2dSpriteCollectionData collection = _sprite.Collection;
			if (!spriteCollection.IsNone)
			{
				GameObject value = spriteCollection.Value;
				if (value != null)
				{
					tk2dSpriteCollection component = value.GetComponent<tk2dSpriteCollection>();
					if (component != null)
					{
						collection = component.spriteCollection;
					}
				}
			}
			int newSpriteId = UnityEngine.Random.Range(0, collection.Count + 1);
			_sprite.SetSprite(collection, newSpriteId);
		}
	}
