	[ActionCategory(ActionCategory.Transform)]
	[Tooltip("Translates a Game Object per FixedUpdate, and also raycasts to detect if terrain is passed through. Move on EITHER x or y only! Ie cardinal directions ")]
	public class TranslateContinuous : FsmStateAction
	{
		[RequiredField]
		[Tooltip("The game object to translate.")]
		public FsmOwnerDefault gameObject;

		[Tooltip("Translation along x axis.")]
		public FsmFloat x;

		[Tooltip("Translation along y axis.")]
		public FsmFloat y;

		public FsmInt[] layerMask;

		private GameObject go;

		private int moveDirection;

		private BoxCollider2D collider;

		private Vector2 point1Offset;

		private Vector2 point2Offset;

		private Vector2 point3Offset;

		private Vector2 rayOrigin1;

		private Vector2 rayOrigin2;

		private Vector2 rayOrigin3;

		private Vector2 rayCastDirection;

		private Vector2 debugDirection;

		private float moveDistance;

		private Vector2 translate;

		private bool hitWall;

		public override void Reset()
		{
			gameObject = null;
			x = new FsmFloat
			{
				UseVariable = true
			};
			y = new FsmFloat
			{
				UseVariable = true
			};
		}

		public override void Awake()
		{
			base.Fsm.HandleFixedUpdate = true;
		}

		public override void OnPreprocess()
		{
			base.Fsm.HandleFixedUpdate = true;
		}

		public override void OnEnter()
		{
			go = base.Fsm.GetOwnerDefaultTarget(gameObject);
			if (go == null)
			{
				UnityEngine.Debug.Log("Tried to translate, but GameObject is null???? Wow.");
				Finish();
			}
			collider = go.GetComponent<BoxCollider2D>();
			if (x.Value < 0f)
			{
				moveDirection = 2;
				rayCastDirection = new Vector2(1f, 0f);
				moveDistance = x.Value - collider.bounds.size.x;
				debugDirection = new Vector2(x.Value, 0f);
			}
			else if (x.Value > 0f)
			{
				moveDirection = 0;
				rayCastDirection = new Vector2(1f, 0f);
				moveDistance = x.Value + collider.bounds.size.x;
				debugDirection = new Vector2(x.Value, 0f);
			}
			else if (y.Value < 0f)
			{
				moveDirection = 3;
				rayCastDirection = new Vector2(0f, 1f);
				moveDistance = y.Value - collider.bounds.size.y;
				debugDirection = new Vector2(0f, y.Value);
			}
			else if (y.Value > 0f)
			{
				moveDirection = 1;
				rayCastDirection = new Vector2(0f, 1f);
				moveDistance = y.Value + collider.bounds.size.y;
				debugDirection = new Vector2(0f, y.Value);
			}
			if (moveDirection == 0 || moveDirection == 3)
			{
				point1Offset = new Vector2(collider.offset.x - collider.bounds.size.x / 2f, collider.offset.y + collider.bounds.size.y / 2f);
			}
			if (moveDirection == 1 || moveDirection == 2)
			{
				point1Offset = new Vector2(collider.offset.x + collider.bounds.size.x / 2f, collider.offset.y - collider.bounds.size.y / 2f);
			}
			if (moveDirection == 2 || moveDirection == 3)
			{
				point2Offset = new Vector2(collider.offset.x + collider.bounds.size.x / 2f, collider.offset.y + collider.bounds.size.y / 2f);
			}
			if (moveDirection == 0 || moveDirection == 1)
			{
				point2Offset = new Vector2(collider.offset.x - collider.bounds.size.x / 2f, collider.offset.y - collider.bounds.size.y / 2f);
			}
			if (moveDirection == 0)
			{
				point3Offset = new Vector2(collider.offset.x - collider.bounds.size.x / 2f, collider.offset.y);
			}
			else if (moveDirection == 1)
			{
				point3Offset = new Vector2(collider.offset.x, collider.offset.y - collider.bounds.size.y / 2f);
			}
			else if (moveDirection == 2)
			{
				point3Offset = new Vector2(collider.offset.x + collider.bounds.size.x / 2f, collider.offset.y);
			}
			else if (moveDirection == 3)
			{
				point3Offset = new Vector2(collider.offset.x, collider.offset.y + collider.bounds.size.y / 2f);
			}
			DoTranslate();
		}

		public override void OnFixedUpdate()
		{
			DoTranslate();
		}

		private void DoTranslate()
		{
			hitWall = false;
			translate = new Vector2(x.Value, y.Value);
			rayOrigin1 = new Vector2(go.transform.position.x + point1Offset.x, go.transform.position.y + point1Offset.y);
			rayOrigin2 = new Vector2(go.transform.position.x + point2Offset.x, go.transform.position.y + point2Offset.y);
			rayOrigin3 = new Vector2(go.transform.position.x + point3Offset.x, go.transform.position.y + point3Offset.y);
			UnityEngine.Debug.DrawLine(rayOrigin2, new Vector2(rayOrigin2.x + moveDistance, rayOrigin2.y), Color.yellow);
			RaycastHit2D raycastHit2D = Physics2D.Raycast(rayOrigin1, rayCastDirection, moveDistance, 256);
			RaycastHit2D raycastHit2D2 = Physics2D.Raycast(rayOrigin2, rayCastDirection, moveDistance, 256);
			RaycastHit2D raycastHit2D3 = Physics2D.Raycast(rayOrigin3, rayCastDirection, moveDistance, 256);
			bool flag = raycastHit2D.collider != null;
			bool flag2 = raycastHit2D2.collider != null;
			bool flag3 = raycastHit2D3.collider != null;
			if (flag | flag2 | flag3)
			{
				float num = 0f;
				if (moveDirection == 2)
				{
					if (flag)
					{
						num = raycastHit2D.point.x;
						if (flag2)
						{
							num = Mathf.Max(num, raycastHit2D2.point.x);
						}
						if (flag3)
						{
							num = Mathf.Max(num, raycastHit2D3.point.x);
						}
					}
					else if (flag2)
					{
						num = raycastHit2D2.point.x;
						if (flag3)
						{
							num = Mathf.Max(num, raycastHit2D3.point.x);
						}
					}
					else if (flag3)
					{
						num = raycastHit2D3.point.x;
					}
					translate.x += num - (rayOrigin1.x + rayCastDirection.x * moveDistance);
					hitWall = true;
				}
				if (moveDirection == 0)
				{
					if (flag)
					{
						num = raycastHit2D.point.x;
						if (flag2)
						{
							num = Mathf.Min(num, raycastHit2D2.point.x);
						}
						if (flag3)
						{
							num = Mathf.Min(num, raycastHit2D3.point.x);
						}
					}
					else if (flag2)
					{
						num = raycastHit2D2.point.x;
						if (flag3)
						{
							num = Mathf.Min(num, raycastHit2D3.point.x);
						}
					}
					else if (flag3)
					{
						num = raycastHit2D3.point.x;
					}
					translate.x += num - (rayOrigin1.x + rayCastDirection.x * moveDistance);
					hitWall = true;
				}
				if (moveDirection == 1)
				{
					if (flag)
					{
						num = raycastHit2D.point.y;
						if (flag2)
						{
							num = Mathf.Min(num, raycastHit2D2.point.y);
						}
						if (flag3)
						{
							num = Mathf.Min(num, raycastHit2D3.point.y);
						}
					}
					else if (flag2)
					{
						num = raycastHit2D2.point.y;
						if (flag3)
						{
							num = Mathf.Min(num, raycastHit2D3.point.y);
						}
					}
					else if (flag3)
					{
						num = raycastHit2D3.point.y;
					}
					translate.y += num - (rayOrigin1.y + rayCastDirection.y * moveDistance);
					hitWall = true;
				}
				if (moveDirection == 3)
				{
					if (flag)
					{
						num = raycastHit2D.point.y;
						if (flag2)
						{
							num = Mathf.Max(num, raycastHit2D2.point.y);
						}
						if (flag3)
						{
							num = Mathf.Max(num, raycastHit2D3.point.y);
						}
					}
					else if (flag2)
					{
						num = raycastHit2D2.point.y;
						if (flag3)
						{
							num = Mathf.Max(num, raycastHit2D3.point.y);
						}
					}
					else if (flag3)
					{
						num = raycastHit2D3.point.y;
					}
					translate.y += num - (rayOrigin1.y + rayCastDirection.y * moveDistance);
					hitWall = true;
				}
			}
			else
			{
				hitWall = false;
			}
			if (hitWall)
			{
				Finish();
			}
			else
			{
				go.transform.Translate(translate, Space.World);
			}
		}
	}
	[ActionCategory(ActionCategory.Transform)]
	[Tooltip("Translates a Game Object. Use a Vector3 variable and/or XYZ components. To leave any axis unchanged, set variable to 'None'.")]
	public class TranslateV2 : FsmStateAction
	{
		[RequiredField]
		[Tooltip("The game object to translate.")]
		public FsmOwnerDefault gameObject;

		[UIHint(UIHint.Variable)]
		[Tooltip("A translation vector. NOTE: You can override individual axis below.")]
		public FsmVector3 vector;

		[Tooltip("Translation along x axis.")]
		public FsmFloat x;

		[Tooltip("Translation along y axis.")]
		public FsmFloat y;

		[Tooltip("Translation along z axis.")]
		public FsmFloat z;

		[Tooltip("Translate in local or world space.")]
		public Space space;

		[Tooltip("Translate over one second")]
		public bool perSecond;

		[Tooltip("Repeat every frame.")]
		public bool everyFrame;

		[Tooltip("Perform the translate in LateUpdate. This is useful if you want to override the position of objects that are animated or otherwise positioned in Update.")]
		public bool lateUpdate;

		[Tooltip("Perform the translate in FixedUpdate. This is useful when working with rigid bodies and physics.")]
		public bool fixedUpdate;

		public bool alwaysOnStart;

		public FsmFloat yMin;

		public FsmFloat yMax;

		public override void Reset()
		{
			gameObject = null;
			vector = null;
			x = new FsmFloat
			{
				UseVariable = true
			};
			y = new FsmFloat
			{
				UseVariable = true
			};
			z = new FsmFloat
			{
				UseVariable = true
			};
			space = Space.Self;
			perSecond = true;
			everyFrame = true;
			lateUpdate = false;
			fixedUpdate = false;
			alwaysOnStart = false;
		}

		public override void Awake()
		{
			if (fixedUpdate)
			{
				base.Fsm.HandleFixedUpdate = true;
			}
			if (lateUpdate)
			{
				base.Fsm.HandleLateUpdate = true;
			}
		}

		public override void OnPreprocess()
		{
			if (fixedUpdate)
			{
				base.Fsm.HandleFixedUpdate = true;
			}
			if (lateUpdate)
			{
				base.Fsm.HandleLateUpdate = true;
			}
		}

		public override void OnEnter()
		{
			if (!everyFrame && !lateUpdate && !fixedUpdate)
			{
				DoTranslate();
				Finish();
			}
			if (alwaysOnStart)
			{
				DoTranslate();
			}
		}

		public override void OnUpdate()
		{
			if (!lateUpdate && !fixedUpdate)
			{
				DoTranslate();
			}
		}

		public override void OnLateUpdate()
		{
			if (lateUpdate)
			{
				DoTranslate();
			}
			if (!everyFrame)
			{
				Finish();
			}
		}

		public override void OnFixedUpdate()
		{
			if (fixedUpdate)
			{
				DoTranslate();
			}
			if (!everyFrame)
			{
				Finish();
			}
		}

		private void DoTranslate()
		{
			GameObject ownerDefaultTarget = base.Fsm.GetOwnerDefaultTarget(gameObject);
			if (!(ownerDefaultTarget == null))
			{
				Vector3 vector = (this.vector.IsNone ? new Vector3(x.Value, y.Value, z.Value) : this.vector.Value);
				if (!x.IsNone)
				{
					vector.x = x.Value;
				}
				if (!y.IsNone)
				{
					vector.y = y.Value;
				}
				if (!z.IsNone)
				{
					vector.z = z.Value;
				}
				if (!perSecond)
				{
					ownerDefaultTarget.transform.Translate(vector, space);
				}
				else
				{
					ownerDefaultTarget.transform.Translate(vector * Time.deltaTime, space);
				}
				if (!yMin.IsNone && ownerDefaultTarget.transform.position.y < yMin.Value)
				{
					ownerDefaultTarget.transform.position = new Vector3(ownerDefaultTarget.transform.position.x, yMin.Value, ownerDefaultTarget.transform.position.z);
				}
				if (!yMax.IsNone && ownerDefaultTarget.transform.position.y > yMax.Value)
				{
					ownerDefaultTarget.transform.position = new Vector3(ownerDefaultTarget.transform.position.x, yMax.Value, ownerDefaultTarget.transform.position.z);
				}
			}
		}
	}
	[ActionCategory(ActionCategory.Time)]
	[Tooltip("Delays a State from finishing by the specified time. NOTE: Other actions continue, but FINISHED can't happen before Time.")]
	public class WaitRandom : FsmStateAction
	{
		[RequiredField]
		public FsmFloat timeMin;

		public FsmFloat timeMax;

		public FsmEvent finishEvent;

		public bool realTime;

		private float time;

		private float startTime;

		private float timer;

		public override void Reset()
		{
			timeMin = 0f;
			timeMax = 1f;
			finishEvent = null;
			realTime = false;
		}

		public override void OnEnter()
		{
			time = UnityEngine.Random.Range(timeMin.Value, timeMax.Value);
			if (time <= 0f)
			{
				base.Fsm.Event(finishEvent);
				Finish();
			}
			else
			{
				startTime = FsmTime.RealtimeSinceStartup;
				timer = 0f;
			}
		}

		public override void OnUpdate()
		{
			if (realTime)
			{
				timer = FsmTime.RealtimeSinceStartup - startTime;
			}
			else
			{
				timer += Time.deltaTime;
			}
			if (timer >= time)
			{
				Finish();
				if (finishEvent != null)
				{
					base.Fsm.Event(finishEvent);
				}
			}
		}
	}
	public class WalkLeftRight : FsmStateAction
	{
		public FsmOwnerDefault gameObject;

		public float walkSpeed = 4f;

		public bool spriteFacesLeft;

		public FsmString groundLayer = "Terrain";

		public float turnDelay = 1f;

		private float nextTurnTime;

		[Header("Animation")]
		public FsmString walkAnimName;

		public FsmString turnAnimName;

		public FsmBool startLeft;

		public FsmBool startRight;

		public FsmBool keepDirection;

		private float scaleX_pos;

		private float scaleX_neg;

		private const float wallRayHeight = 0.5f;

		private const float wallRayLength = 0.1f;

		private const float groundRayLength = 1f;

		private GameObject target;

		private Rigidbody2D body;

		private tk2dSpriteAnimator spriteAnimator;

		private Collider2D collider;

		private Coroutine walkRoutine;

		private Coroutine turnRoutine;

		private bool shouldTurn;

		private float Direction
		{
			get
			{
				if ((bool)target)
				{
					return Mathf.Sign(target.transform.localScale.x) * (float)((!spriteFacesLeft) ? 1 : (-1));
				}
				return 0f;
			}
		}

		public override void OnEnter()
		{
			UpdateIfTargetChanged();
			SetupStartingDirection();
			walkRoutine = StartCoroutine(Walk());
		}

		public override void OnExit()
		{
			if (walkRoutine != null)
			{
				StopCoroutine(walkRoutine);
				walkRoutine = null;
			}
			if (turnRoutine != null)
			{
				StopCoroutine(turnRoutine);
				turnRoutine = null;
			}
		}

		private void UpdateIfTargetChanged()
		{
			GameObject ownerDefaultTarget = base.Fsm.GetOwnerDefaultTarget(gameObject);
			if (ownerDefaultTarget != target)
			{
				target = ownerDefaultTarget;
				body = target.GetComponent<Rigidbody2D>();
				spriteAnimator = target.GetComponent<tk2dSpriteAnimator>();
				collider = target.GetComponent<Collider2D>();
			}
		}

		private IEnumerator Walk()
		{
			if ((bool)spriteAnimator)
			{
				spriteAnimator.Play(walkAnimName.Value);
			}
			while (true)
			{
				if ((bool)body)
				{
					Vector2 velocity = body.velocity;
					velocity.x = walkSpeed * Direction;
					body.velocity = velocity;
					if (shouldTurn || (CheckIsGrounded() && (CheckWall() || CheckFloor()) && Time.time >= nextTurnTime))
					{
						shouldTurn = false;
						nextTurnTime = Time.time + turnDelay;
						turnRoutine = StartCoroutine(Turn());
						yield return turnRoutine;
					}
				}
				yield return new WaitForFixedUpdate();
			}
		}

		private IEnumerator Turn()
		{
			Vector2 velocity = body.velocity;
			velocity.x = 0f;
			body.velocity = velocity;
			tk2dSpriteAnimationClip clipByName = spriteAnimator.GetClipByName(turnAnimName.Value);
			if (clipByName != null)
			{
				float seconds = (float)clipByName.frames.Length / clipByName.fps;
				spriteAnimator.Play(clipByName);
				yield return new WaitForSeconds(seconds);
			}
			Vector3 localScale = target.transform.localScale;
			localScale.x *= -1f;
			target.transform.localScale = localScale;
			if ((bool)spriteAnimator)
			{
				spriteAnimator.Play(walkAnimName.Value);
			}
			turnRoutine = null;
		}

		private bool CheckWall()
		{
			Vector2 vector = (Vector2)collider.bounds.center + new Vector2(0f, 0f - collider.bounds.size.y / 2f + 0.5f);
			Vector2 vector2 = Vector2.right * Direction;
			float num = collider.bounds.size.x / 2f + 0.1f;
			UnityEngine.Debug.DrawLine(vector, vector + vector2 * num);
			if (Physics2D.Raycast(vector, vector2, num, 256).collider != null)
			{
				return true;
			}
			return false;
		}

		private bool CheckFloor()
		{
			Vector2 vector = (Vector2)collider.bounds.center + new Vector2((collider.bounds.size.x / 2f + 0.1f) * Direction, 0f - collider.bounds.size.y / 2f + 0.5f);
			UnityEngine.Debug.DrawLine(vector, vector + Vector2.down * 1f);
			if (Physics2D.Raycast(vector, Vector2.down, 1f, 256).collider != null)
			{
				return false;
			}
			return true;
		}

		private bool CheckIsGrounded()
		{
			Vector2 vector = (Vector2)collider.bounds.center + new Vector2(0f, 0f - collider.bounds.size.y / 2f + 0.5f);
			UnityEngine.Debug.DrawLine(vector, vector + Vector2.down * 1f);
			if (Physics2D.Raycast(vector, Vector2.down, 1f, 256).collider != null)
			{
				return true;
			}
			return false;
		}

		private void SetupStartingDirection()
		{
			if (target.transform.localScale.x < 0f)
			{
				if (!spriteFacesLeft && startRight.Value)
				{
					shouldTurn = true;
				}
				if (spriteFacesLeft && startLeft.Value)
				{
					shouldTurn = true;
				}
			}
			else
			{
				if (spriteFacesLeft && startRight.Value)
				{
					shouldTurn = true;
				}
				if (!spriteFacesLeft && startLeft.Value)
				{
					shouldTurn = true;
				}
			}
			if (!startLeft.Value && !startRight.Value && !keepDirection.Value && UnityEngine.Random.Range(0f, 100f) <= 50f)
			{
				shouldTurn = true;
			}
			startLeft.Value = false;
			startRight.Value = false;
		}
	}
	public abstract class FsmStateActionAdvanced : FsmStateAction
	{
		public enum FrameUpdateSelector
		{
			OnUpdate,
			OnLateUpdate,
			OnFixedUpdate
		}

		[ActionSection("Update type")]
		[Tooltip("Repeat every frame.")]
		public bool everyFrame;

		public FrameUpdateSelector updateType;

		public abstract void OnActionUpdate();

		public override void Reset()
		{
			everyFrame = false;
			updateType = FrameUpdateSelector.OnUpdate;
		}

		public override void OnPreprocess()
		{
			base.OnPreprocess();
			base.Fsm.HandleFixedUpdate = true;
		}

		public override void OnUpdate()
		{
			if (updateType == FrameUpdateSelector.OnUpdate)
			{
				OnActionUpdate();
			}
			if (!everyFrame)
			{
				Finish();
			}
		}

		public override void OnLateUpdate()
		{
			if (updateType == FrameUpdateSelector.OnLateUpdate)
			{
				OnActionUpdate();
			}
			if (!everyFrame)
			{
				Finish();
			}
		}

		public override void OnFixedUpdate()
		{
			if (updateType == FrameUpdateSelector.OnFixedUpdate)
			{
				OnActionUpdate();
			}
			if (!everyFrame)
			{
				Finish();
			}
		}
	}
	[ActionCategory("iTween")]
	[Tooltip("Changes a GameObject's opacity over time.")]
	public class iTweenFadeTo : iTweenFsmAction
	{
		[RequiredField]
		public FsmOwnerDefault gameObject;

		[Tooltip("iTween ID. If set you can use iTween Stop action to stop it by its id.")]
		public FsmString id;

		[Tooltip("The end alpha value of the animation.")]
		public FsmFloat alpha;

		[Tooltip("Whether or not to include children of this GameObject. True by default.")]
		public FsmBool includeChildren;

		[Tooltip("Which color of a shader to use. Uses '_Color' by default.")]
		public FsmString namedValueColor;

		[Tooltip("The time in seconds the animation will take to complete.")]
		public FsmFloat time;

		[Tooltip("The time in seconds the animation will wait before beginning.")]
		public FsmFloat delay;

		[Tooltip("The shape of the easing curve applied to the animation.")]
		public iTween.EaseType easeType = iTween.EaseType.linear;

		[Tooltip("The type of loop to apply once the animation has completed.")]
		public iTween.LoopType loopType;

		public override void Reset()
		{
			base.Reset();
			id = new FsmString
			{
				UseVariable = true
			};
			alpha = 0f;
			includeChildren = true;
			namedValueColor = "_Color";
			time = 1f;
			delay = 0f;
		}

		public override void OnEnter()
		{
			OnEnteriTween(gameObject);
			if (loopType != iTween.LoopType.none)
			{
				IsLoop(aValue: true);
			}
			DoiTween();
		}

		public override void OnExit()
		{
			OnExitiTween(gameObject);
		}

		private void DoiTween()
		{
			GameObject ownerDefaultTarget = base.Fsm.GetOwnerDefaultTarget(gameObject);
			if (!(ownerDefaultTarget == null))
			{
				itweenType = "fade";
				iTween.FadeTo(ownerDefaultTarget, iTween.Hash("name", id.IsNone ? "" : id.Value, "alpha", alpha.Value, "includechildren", includeChildren.IsNone || includeChildren.Value, "NamedValueColor", namedValueColor.Value, "time", time.Value, "delay", delay.IsNone ? 0f : delay.Value, "easetype", easeType, "looptype", loopType, "oncomplete", "iTweenOnComplete", "oncompleteparams", itweenID, "onstart", "iTweenOnStart", "onstartparams", itweenID, "ignoretimescale", !realTime.IsNone && realTime.Value));
			}
		}
	}
	[ActionCategory(ActionCategory.Logic)]
	[Tooltip("Sends Events based on the comparison of 2 Vector3's.")]
	public class Vector3Compare : FsmStateAction
	{
		[RequiredField]
		public FsmVector3 vector3Variable1;

		[RequiredField]
		public FsmVector3 vector3Variable2;

		[RequiredField]
		public FsmFloat tolerance;

		[Tooltip("Event sent if Vector3 1 equals Vector3 2 (within Tolerance)")]
		public FsmEvent equal;

		[Tooltip("Event sent if the Vector3's are not equal")]
		public FsmEvent notEqual;

		public bool everyFrame;

		public override void Reset()
		{
			vector3Variable1 = null;
			vector3Variable2 = null;
			tolerance = 0f;
			equal = null;
			notEqual = null;
			everyFrame = false;
		}

		public override void OnEnter()
		{
			DoCompare();
			if (!everyFrame)
			{
				Finish();
			}
		}

		public override void OnUpdate()
		{
			DoCompare();
		}

		private void DoCompare()
		{
			if (vector3Variable1 != null && vector3Variable2 != null)
			{
				if (Mathf.Abs(vector3Variable1.Value.x - vector3Variable2.Value.x) <= tolerance.Value && Mathf.Abs(vector3Variable1.Value.y - vector3Variable2.Value.y) <= tolerance.Value && Mathf.Abs(vector3Variable1.Value.z - vector3Variable2.Value.z) <= tolerance.Value)
				{
					base.Fsm.Event(equal);
				}
				else
				{
					base.Fsm.Event(notEqual);
				}
			}
		}

		public override string ErrorCheck()
		{
			if (FsmEvent.IsNullOrEmpty(equal) && FsmEvent.IsNullOrEmpty(notEqual))
			{
				return "Action sends no events!";
			}
			return "";
		}
	}
