		{
			DoWakeAll();
		}

		private void DoWakeAll()
		{
			if (UnityEngine.Object.FindObjectsOfType(typeof(Rigidbody2D)) is Rigidbody2D[] array)
			{
				Rigidbody2D[] array2 = array;
				for (int i = 0; i < array2.Length; i++)
