		}

		public override void OnEnter()
		{
			DoDeleteAt();
			Finish();
		}

		private void DoDeleteAt()
		{
			if (index.Value >= 0 && index.Value < array.Length)
			{
				List<object> list = new List<object>(array.Values);
				list.RemoveAt(index.Value);
