		{
			floatValue = null;
			storeResult = null;
			everyFrame = false;
		}

		public override void OnEnter()
		{
			DoPerSecond();
			if (!everyFrame)
			{
				Finish();
			}
		}

		public override void OnUpdate()
		{
			DoPerSecond();
		}

		private void DoPerSecond()
		{
			if (storeResult != null)
			{
				storeResult.Value = floatValue.Value * Time.deltaTime;
			}
		}
