	[ActionCategory(ActionCategory.Camera)]
	[Tooltip("Transforms position from world space into screen space. NOTE: Uses the MainCamera!")]
	public class WorldToScreenPoint : FsmStateAction
	{
		[UIHint(UIHint.Variable)]
		[Tooltip("World position to transform into screen coordinates.")]
		public FsmVector3 worldPosition;

		[Tooltip("World X position.")]
		public FsmFloat worldX;

		[Tooltip("World Y position.")]
		public FsmFloat worldY;

		[Tooltip("World Z position.")]
		public FsmFloat worldZ;

		[UIHint(UIHint.Variable)]
		[Tooltip("Store the screen position in a Vector3 Variable. Z will equal zero.")]
		public FsmVector3 storeScreenPoint;

		[UIHint(UIHint.Variable)]
		[Tooltip("Store the screen X position in a Float Variable.")]
		public FsmFloat storeScreenX;

		[UIHint(UIHint.Variable)]
		[Tooltip("Store the screen Y position in a Float Variable.")]
		public FsmFloat storeScreenY;

		[Tooltip("Normalize screen coordinates (0-1). Otherwise coordinates are in pixels.")]
		public FsmBool normalize;

		[Tooltip("Repeat every frame")]
		public bool everyFrame;

		public override void Reset()
		{
			worldPosition = null;
			worldX = new FsmFloat
			{
				UseVariable = true
			};
			worldY = new FsmFloat
			{
				UseVariable = true
			};
			worldZ = new FsmFloat
			{
				UseVariable = true
			};
			storeScreenPoint = null;
			storeScreenX = null;
			storeScreenY = null;
			everyFrame = false;
		}

		public override void OnEnter()
		{
			DoWorldToScreenPoint();
			if (!everyFrame)
			{
				Finish();
			}
		}

		public override void OnUpdate()
		{
			DoWorldToScreenPoint();
		}

		private void DoWorldToScreenPoint()
		{
			if (Camera.main == null)
			{
				LogError("No MainCamera defined!");
				Finish();
				return;
			}
			Vector3 position = Vector3.zero;
			if (!worldPosition.IsNone)
			{
				position = worldPosition.Value;
			}
			if (!worldX.IsNone)
			{
				position.x = worldX.Value;
			}
			if (!worldY.IsNone)
			{
				position.y = worldY.Value;
			}
			if (!worldZ.IsNone)
			{
				position.z = worldZ.Value;
			}
			position = Camera.main.WorldToScreenPoint(position);
			if (normalize.Value)
			{
				position.x /= Screen.width;
				position.y /= Screen.height;
			}
			storeScreenPoint.Value = position;
			storeScreenX.Value = position.x;
			storeScreenY.Value = position.y;
		}
	}
	[Tooltip("iTween base action - don't use!")]
	public abstract class iTweenFsmAction : FsmStateAction
	{
		public enum AxisRestriction
		{
			none,
			x,
			y,
			z,
			xy,
			xz,
			yz
		}

		[ActionSection("Events")]
		public FsmEvent startEvent;

		public FsmEvent finishEvent;

		[Tooltip("Setting this to true will allow the animation to continue independent of the current time which is helpful for animating menus after a game has been paused by setting Time.timeScale=0.")]
		public FsmBool realTime;

		public FsmBool stopOnExit;

		public FsmBool loopDontFinish;

		internal iTweenFSMEvents itweenEvents;

		protected string itweenType = "";

		protected int itweenID = -1;

		public override void Reset()
		{
			startEvent = null;
			finishEvent = null;
			realTime = new FsmBool
			{
				Value = false
			};
			stopOnExit = new FsmBool
			{
				Value = true
			};
			loopDontFinish = new FsmBool
			{
				Value = true
			};
			itweenType = "";
		}

		protected void OnEnteriTween(FsmOwnerDefault anOwner)
		{
			GameObject ownerDefaultTarget = base.Fsm.GetOwnerDefaultTarget(anOwner);
			if (!(ownerDefaultTarget == null))
			{
				itweenEvents = ownerDefaultTarget.AddComponent<iTweenFSMEvents>();
				itweenEvents.itweenFSMAction = this;
				iTweenFSMEvents.itweenIDCount++;
				itweenID = iTweenFSMEvents.itweenIDCount;
				itweenEvents.itweenID = iTweenFSMEvents.itweenIDCount;
				itweenEvents.donotfinish = !loopDontFinish.IsNone && loopDontFinish.Value;
			}
		}

		protected void IsLoop(bool aValue)
		{
			if (itweenEvents != null)
			{
				itweenEvents.islooping = aValue;
			}
		}

		protected void OnExitiTween(FsmOwnerDefault anOwner)
		{
			GameObject ownerDefaultTarget = base.Fsm.GetOwnerDefaultTarget(anOwner);
			if (!(ownerDefaultTarget == null))
			{
				if ((bool)itweenEvents)
				{
					UnityEngine.Object.Destroy(itweenEvents);
				}
				if (stopOnExit.IsNone)
				{
					iTween.Stop(ownerDefaultTarget, itweenType);
				}
				else if (stopOnExit.Value)
				{
					iTween.Stop(ownerDefaultTarget, itweenType);
