		{
			hash.Remove("looktarget");
			if (transformTarget.IsNone)
			{
				hash.Add("looktarget", vectorTarget.IsNone ? Vector3.zero : vectorTarget.Value);
			}
			else if (vectorTarget.IsNone)
			{
