		public static GameObject CreateButton(GameObject parent, Action<int> action, int id, Sprite spr, string text, int fontSize, TextAnchor textAnchor, RectData rectData, bool bold = true, params Sprite[] extraSprites)
		{
			GameObject gameObject = CreateBasePanel(parent, rectData);
			CreateTextPanel(gameObject, text, fontSize, textAnchor, rectData, bold);
			Image image = gameObject.AddComponent<Image>();
			image.sprite = spr;
			Button button = gameObject.AddComponent<Button>();
			button.targetGraphic = image;
			button.onClick.AddListener(delegate
			{
				action(id);
			});
			if (extraSprites.Length == 3)
			{
				button.transition = Selectable.Transition.SpriteSwap;
				button.targetGraphic = image;
				SpriteState spriteState = new SpriteState
				{
					highlightedSprite = extraSprites[0],
					pressedSprite = extraSprites[1],
					disabledSprite = extraSprites[2]
				};
				button.spriteState = spriteState;
				return gameObject;
			}
			button.transition = Selectable.Transition.None;
			return gameObject;
		}

		public static GameObject CreateToggle(GameObject parent, Action<bool> action, Sprite boxBgSprite, Sprite boxFgSprite, string text, int fontSize, TextAnchor textAnchor, RectData rectData, bool bold = true, bool isOn = false)
		{
			GameObject gameObject = CreateBasePanel(parent, rectData);
			GameObject gameObject2 = CreateImagePanel(gameObject, boxBgSprite, rectData);
			GameObject gameObject3 = CreateImagePanel(gameObject2, boxFgSprite, rectData);
			Toggle toggle = gameObject.AddComponent<Toggle>();
			toggle.isOn = isOn;
			toggle.targetGraphic = gameObject2.GetComponent<Image>();
			toggle.graphic = gameObject3.GetComponent<Image>();
			toggle.transition = Selectable.Transition.ColorTint;
			ColorBlock colors = new ColorBlock
			{
				normalColor = new Color(1f, 1f, 1f, 1f),
				highlightedColor = new Color(1f, 1f, 1f, 1f),
				pressedColor = new Color(0.8f, 0.8f, 0.8f, 1f),
				disabledColor = new Color(0.8f, 0.8f, 0.8f, 0.5f),
				fadeDuration = 0.1f
			};
			toggle.colors = colors;
			toggle.onValueChanged.AddListener(delegate(bool b)
			{
				action(b);
			});
			ToggleGroup component = parent.GetComponent<ToggleGroup>();
			if (component != null)
			{
				toggle.group = component;
			}
			return gameObject;
		}

