		{
			GameObject gameObject = new GameObject();
			AddRectTransform(gameObject, new RectData(new Vector2(0f, 0f), new Vector2(0f, 0f), new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f)));
			gameObject.AddComponent<ToggleGroup>();
			return gameObject;
		}

