			gameObject.AddComponent<RectMask2D>();
			return gameObject;
		}

		public static IEnumerator FadeInCanvasGroup(CanvasGroup cg)
		{
			float loopFailsafe = 0f;
			cg.alpha = 0f;
			cg.gameObject.SetActive(value: true);
			while (cg.alpha < 1f)
			{
				cg.alpha += Time.unscaledDeltaTime * 3.2f;
				loopFailsafe += Time.unscaledDeltaTime;
				if (cg.alpha >= 0.95f)
				{
					cg.alpha = 1f;
					break;
				}
				if (loopFailsafe >= 2f)
				{
					break;
				}
				yield return null;
			}
			cg.alpha = 1f;
			cg.interactable = true;
			cg.gameObject.SetActive(value: true);
			yield return null;
		}

		public static IEnumerator FadeOutCanvasGroup(CanvasGroup cg)
		{
			float loopFailsafe = 0f;
			cg.interactable = false;
			while (cg.alpha > 0.05f)
			{
				cg.alpha -= Time.unscaledDeltaTime * 3.2f;
				loopFailsafe += Time.unscaledDeltaTime;
				if (cg.alpha <= 0.05f || loopFailsafe >= 2f)
				{
					break;
				}
				yield return null;
			}
			cg.alpha = 0f;
			cg.gameObject.SetActive(value: false);
			yield return null;
		}
	}
	internal class Console : MonoBehaviour
	{
		private static GameObject _overlayCanvas;

		private static GameObject _textPanel;

		private static Font _font;

		private bool _enabled = true;

		private readonly List<string> _messages = new List<string>(25);

		private KeyCode _toggleKey = KeyCode.F10;

		private int _maxMessageCount = 25;

		private int _fontSize = 12;

		private const int MSG_LENGTH = 80;

		private static readonly string[] OSFonts = new string[4] { "Consolas", "Menlo", "Courier New", "DejaVu Mono" };

		[PublicAPI]
		public void Start()
		{
			LoadSettings();
			if (_font == null)
			{
				_font = Font.CreateDynamicFontFromOSFont(OSFonts, _fontSize);
			}
			if (_font == null)
			{
				_font = Resources.GetBuiltinResource(typeof(Font), "Arial.ttf") as Font;
			}
			UnityEngine.Object.DontDestroyOnLoad(base.gameObject);
			if (!(_overlayCanvas != null))
			{
				_overlayCanvas = CanvasUtil.CreateCanvas(RenderMode.ScreenSpaceOverlay, new Vector2(1920f, 1080f));
				_overlayCanvas.name = "ModdingApiConsoleLog";
				CanvasGroup component = _overlayCanvas.GetComponent<CanvasGroup>();
				component.interactable = false;
				component.blocksRaycasts = false;
				UnityEngine.Object.DontDestroyOnLoad(_overlayCanvas);
				_textPanel = CanvasUtil.CreateTextPanel(CanvasUtil.CreateImagePanel(_overlayCanvas, CanvasUtil.NullSprite(new byte[4] { 128, 0, 0, 0 }), new CanvasUtil.RectData(new Vector2(500f, 800f), Vector2.zero, Vector2.zero, Vector2.zero, Vector2.zero)), string.Join(string.Empty, _messages.ToArray()), _fontSize, TextAnchor.LowerLeft, new CanvasUtil.RectData(new Vector2(-5f, -5f), Vector2.zero, Vector2.zero, Vector2.one), _font);
				_textPanel.GetComponent<Text>().horizontalOverflow = HorizontalWrapMode.Wrap;
			}
		}

		private void LoadSettings()
		{
			InGameConsoleSettings consoleSettings = ModHooks.GlobalSettings.ConsoleSettings;
			_toggleKey = consoleSettings.ToggleHotkey;
			if (_toggleKey == KeyCode.Escape)
			{
				Logger.APILogger.LogError("Esc cannot be used as hotkey for console togging");
				_toggleKey = (consoleSettings.ToggleHotkey = KeyCode.F10);
			}
			_maxMessageCount = consoleSettings.MaxMessageCount;
			if (_maxMessageCount <= 0)
			{
				Logger.APILogger.LogError($"Specified max console message count {_maxMessageCount} is invalid");
				_maxMessageCount = (consoleSettings.MaxMessageCount = 24);
			}
			_fontSize = consoleSettings.FontSize;
			if (_fontSize <= 0)
			{
				Logger.APILogger.LogError($"Specified console font size {_fontSize} is invalid");
				_fontSize = (consoleSettings.FontSize = 12);
			}
			string font = consoleSettings.Font;
			if (!string.IsNullOrEmpty(font))
			{
				_font = Font.CreateDynamicFontFromOSFont(font, _fontSize);
				if (_font == null)
				{
					Logger.APILogger.LogError("Specified font " + font + " not found.");
				}
			}
		}

		[PublicAPI]
		public void Update()
		{
			if (Input.GetKeyDown(_toggleKey))
			{
				StartCoroutine(_enabled ? CanvasUtil.FadeOutCanvasGroup(_overlayCanvas.GetComponent<CanvasGroup>()) : CanvasUtil.FadeInCanvasGroup(_overlayCanvas.GetComponent<CanvasGroup>()));
				_enabled = !_enabled;
			}
		}

		public void AddText(string message, LogLevel level)
		{
			IEnumerable<string> enumerable = Chunks(message, 80);
			string text = "<color=" + ModHooks.GlobalSettings.ConsoleSettings.DefaultColor + ">";
			if (ModHooks.GlobalSettings.ConsoleSettings.UseLogColors)
			{
				text = level switch
				{
					LogLevel.Fine => "<color=" + ModHooks.GlobalSettings.ConsoleSettings.FineColor + ">", 
					LogLevel.Info => "<color=" + ModHooks.GlobalSettings.ConsoleSettings.InfoColor + ">", 
					LogLevel.Debug => "<color=" + ModHooks.GlobalSettings.ConsoleSettings.DebugColor + ">", 
					LogLevel.Warn => "<color=" + ModHooks.GlobalSettings.ConsoleSettings.WarningColor + ">", 
					LogLevel.Error => "<color=" + ModHooks.GlobalSettings.ConsoleSettings.ErrorColor + ">", 
					_ => text, 
				};
			}
			foreach (string item in enumerable)
			{
				_messages.Add(text + item + "</color>");
			}
			while (_messages.Count > _maxMessageCount)
			{
				_messages.RemoveAt(0);
			}
			if (_textPanel != null)
			{
				_textPanel.GetComponent<Text>().text = string.Join(string.Empty, _messages.ToArray());
			}
		}

		private static IEnumerable<string> Chunks(string str, int maxChunkSize)
		{
			for (int i = 0; i < str.Length; i += maxChunkSize)
			{
				yield return str.Substring(i, Math.Min(maxChunkSize, str.Length - i));
			}
		}
	}
