	public static class KeybindUtil
	{
		public static InputHandler.KeyOrMouseBinding GetKeyOrMouseBinding(this PlayerAction action)
		{
			foreach (BindingSource binding in action.Bindings)
			{
				InputHandler.KeyOrMouseBinding keyOrMouseBinding;
				if (binding is KeyBindingSource { Control: var control } keyBindingSource)
				{
					if (control.IncludeCount != 1)
					{
						goto IL_006d;
					}
					keyOrMouseBinding = new InputHandler.KeyOrMouseBinding(keyBindingSource.Control.GetInclude(0));
				}
				else
				{
					if (!(binding is MouseBindingSource mouseBindingSource))
					{
						goto IL_006d;
					}
					keyOrMouseBinding = new InputHandler.KeyOrMouseBinding(mouseBindingSource.Control);
				}
				goto IL_0079;
				IL_0079:
				InputHandler.KeyOrMouseBinding keyOrMouseBinding2 = keyOrMouseBinding;
				if (!InputHandler.KeyOrMouseBinding.IsNone(keyOrMouseBinding2))
				{
					return keyOrMouseBinding2;
				}
				continue;
				IL_006d:
				keyOrMouseBinding = default(InputHandler.KeyOrMouseBinding);
				goto IL_0079;
			}
			return default(InputHandler.KeyOrMouseBinding);
		}

		public static void AddKeyOrMouseBinding(this PlayerAction action, InputHandler.KeyOrMouseBinding binding)
		{
			if (binding.Key != Key.None)
			{
				action.AddBinding(new KeyBindingSource(new KeyCombo(binding.Key)));
			}
			else if (binding.Mouse != Mouse.None)
			{
				action.AddBinding(new MouseBindingSource(binding.Mouse));
			}
		}

		public static InputHandler.KeyOrMouseBinding? ParseBinding(string src)
		{
			if (Enum.TryParse<Key>(src, out var result))
			{
				return new InputHandler.KeyOrMouseBinding(result);
			}
			if (Enum.TryParse<Mouse>(src, out var result2))
			{
				return new InputHandler.KeyOrMouseBinding(result2);
			}
			return null;
		}

		public static InputControlType GetControllerButtonBinding(this PlayerAction ac)
		{
			foreach (BindingSource binding in ac.Bindings)
			{
				if (binding is DeviceBindingSource deviceBindingSource)
				{
					return deviceBindingSource.Control;
				}
			}
			return InputControlType.None;
		}

		public static void AddInputControlType(this PlayerAction action, InputControlType binding)
		{
			if (binding != InputControlType.None)
			{
				action.AddBinding(new DeviceBindingSource(binding));
			}
		}

		public static InputControlType? ParseInputControlTypeBinding(string src)
		{
			if (Enum.TryParse<InputControlType>(src, out var result))
			{
				return result;
			}
			return null;
		}
	}
	public abstract class Loggable : ILogger
	{
		internal string ClassName;

		protected Loggable()
		{
			ClassName = GetType().Name;
		}

		public void LogFine(string message)
		{
			Logger.LogFine(FormatLogMessage(message));
		}

		public void LogFine(object message)
		{
			Logger.LogFine(FormatLogMessage(message));
		}

		public void LogDebug(string message)
		{
			Logger.LogDebug(FormatLogMessage(message));
		}

		public void LogDebug(object message)
		{
			Logger.LogDebug(FormatLogMessage(message));
		}

		public void Log(string message)
		{
			Logger.Log(FormatLogMessage(message));
		}

		public void Log(object message)
		{
			Logger.Log(FormatLogMessage(message));
		}

		public void LogWarn(string message)
		{
			Logger.LogWarn(FormatLogMessage(message));
		}

		public void LogWarn(object message)
		{
			Logger.LogWarn(FormatLogMessage(message));
		}

		public void LogError(string message)
		{
			Logger.LogError(FormatLogMessage(message));
		}

		public void LogError(object message)
		{
			Logger.LogError(FormatLogMessage(message));
		}

		private string FormatLogMessage(string message)
		{
			return ("[" + ClassName + "] - " + message).Replace("\n", "\n[" + ClassName + "] - ");
		}

		private string FormatLogMessage(object message)
		{
			return FormatLogMessage(message?.ToString() ?? "null");
		}
	}
	[PublicAPI]
	public static class Logger
	{
		private static readonly object Locker = new object();

		private static StreamWriter Writer;

		private static LogLevel _logLevel;

		private static bool _shortLoggingLevel;

		private static bool _includeTimestamps;

		private static string OldLogDir = Path.Combine(Application.persistentDataPath, "Old ModLogs");

		internal static readonly SimpleLogger APILogger = new SimpleLogger("API");

		internal static void InitializeFileStream()
		{
			UnityEngine.Debug.Log("Creating Mod Logger");
			_logLevel = LogLevel.Debug;
			Directory.CreateDirectory(OldLogDir);
			string path = Path.Combine(Application.persistentDataPath, "ModLog.txt");
			BackupLog(path, OldLogDir);
			FileStream stream = new FileStream(path, FileMode.Create, FileAccess.Write, FileShare.ReadWrite);
			lock (Locker)
			{
				Writer = new StreamWriter(stream, Encoding.UTF8)
				{
					AutoFlush = true
				};
			}
			File.SetCreationTimeUtc(path, DateTime.UtcNow);
		}

		private static void BackupLog(string path, string dir)
		{
			if (File.Exists(path))
			{
				string text = File.GetCreationTimeUtc(path).ToString("MM dd yyyy (HH mm ss)", CultureInfo.InvariantCulture);
				File.Move(path, Path.Combine(dir, "ModLog " + text + ".txt"));
			}
		}

		internal static void ClearOldModlogs()
		{
			string path = Path.Combine(Application.persistentDataPath, "Old ModLogs");
			APILogger.Log($"Deleting modlogs older than {ModHooks.GlobalSettings.ModlogMaxAge} days ago");
			DateTime limit = DateTime.UtcNow.AddDays(-ModHooks.GlobalSettings.ModlogMaxAge);
			foreach (string item in from f in Directory.GetFiles(path)
				where File.GetCreationTimeUtc(f) < limit
				select f)
			{
				File.Delete(item);
			}
		}

		internal static void SetLogLevel(LogLevel level)
		{
			_logLevel = level;
		}

		internal static void SetUseShortLogLevel(bool value)
		{
			_shortLoggingLevel = value;
		}

		internal static void SetIncludeTimestampt(bool value)
		{
			_includeTimestamps = value;
		}

		public static void Log(string message, LogLevel level)
		{
			if (_logLevel <= level)
			{
				string text = "[" + DateTime.Now.ToUniversalTime().ToString("HH:mm:ss") + "]:";
				string text2 = (_shortLoggingLevel ? ("[" + LogLevelExt.ToShortString(level).ToUpper() + "]:") : ("[" + level.ToString().ToUpper() + "]:"));
				WriteToFile(ExpandLines(_includeTimestamps ? (text + text2) : text2, message), level);
			}
		}

		private static string ExpandLines(string prefixText, string message)
		{
			string[] value = message.Split(new string[2] { "\r\n", "\n" }, StringSplitOptions.None);
			return prefixText + string.Join(Environment.NewLine + prefixText, value) + Environment.NewLine;
		}

		public static void Log(object message, LogLevel level)
		{
			Log(message.ToString(), level);
		}

		public static void LogFine(string message)
		{
			Log(message, LogLevel.Fine);
		}

		public static void LogFine(object message)
		{
			Log(message.ToString(), LogLevel.Fine);
		}

		public static void LogDebug(string message)
		{
			Log(message, LogLevel.Debug);
		}

		public static void LogDebug(object message)
		{
			Log(message, LogLevel.Debug);
		}

		public static void Log(string message)
		{
			Log(message, LogLevel.Info);
		}

		public static void Log(object message)
		{
			Log(message, LogLevel.Info);
		}

		public static void LogWarn(string message)
		{
			Log(message, LogLevel.Warn);
		}

		public static void LogWarn(object message)
		{
			Log(message, LogLevel.Warn);
		}

		public static void LogError(string message)
		{
			Log(message, LogLevel.Error);
		}

		public static void LogError(object message)
		{
			Log(message, LogLevel.Error);
		}

		private static void WriteToFile(string text, LogLevel level)
		{
			lock (Locker)
			{
				ModHooks.LogConsole(text, level);
				Writer?.Write(text);
			}
		}
	}
	[PublicAPI]
	public enum LogLevel
	{
		Fine,
		Debug,
		Info,
		Warn,
		Error,
		[UsedImplicitly]
		Off
	}
	public static class LogLevelExt
	{
		public static string ToShortString(LogLevel level)
		{
			return level switch
			{
				LogLevel.Fine => "F", 
				LogLevel.Debug => "D", 
				LogLevel.Info => "I", 
				LogLevel.Warn => "W", 
				LogLevel.Error => "E", 
				_ => "", 
			};
		}
	}
	[PublicAPI]
	public abstract class Mod : Loggable, IMod, ILogger
	{
		private readonly string _globalSettingsPath;

		private readonly Type globalSettingsType;

		private readonly FastReflectionDelegate onLoadGlobalSettings;

		private readonly FastReflectionDelegate onSaveGlobalSettings;

		private readonly Type saveSettingsType;

		private readonly FastReflectionDelegate onLoadSaveSettings;

		private readonly FastReflectionDelegate onSaveSaveSettings;

		public readonly string Name;

		protected Mod(string name = null)
		{
			if (string.IsNullOrEmpty(name))
			{
				name = GetType().Name;
			}
			Type type = GetType().GetInterfaces().FirstOrDefault((Type x) => x.IsGenericType && x.GetGenericTypeDefinition() == typeof(IGlobalSettings<>));
			if ((object)type != null)
			{
				globalSettingsType = type.GetGenericArguments()[0];
				MethodInfo[] methods = type.GetMethods();
				foreach (MethodInfo methodInfo in methods)
				{
					string name2 = methodInfo.Name;
					if (!(name2 == "OnLoadGlobal"))
					{
						if (name2 == "OnSaveGlobal")
						{
							onSaveGlobalSettings = methodInfo.GetFastDelegate();
						}
					}
					else
					{
						onLoadGlobalSettings = methodInfo.GetFastDelegate();
					}
				}
			}
			Type type2 = GetType().GetInterfaces().FirstOrDefault((Type x) => x.IsGenericType && x.GetGenericTypeDefinition() == typeof(ILocalSettings<>));
			if ((object)type2 != null)
			{
				saveSettingsType = type2.GetGenericArguments()[0];
				MethodInfo[] methods = type2.GetMethods();
				foreach (MethodInfo methodInfo2 in methods)
				{
					string name2 = methodInfo2.Name;
					if (!(name2 == "OnLoadLocal"))
					{
						if (name2 == "OnSaveLocal")
						{
							onSaveSaveSettings = methodInfo2.GetFastDelegate();
						}
					}
					else
					{
						onLoadSaveSettings = methodInfo2.GetFastDelegate();
					}
				}
			}
			Name = name;
			Log("Initializing");
			if (_globalSettingsPath == null)
			{
				_globalSettingsPath = GetGlobalSettingsPath();
			}
			LoadGlobalSettings();
			HookSaveMethods();
		}

		private string GetGlobalSettingsPath()
		{
			string path = GetType().Name + ".GlobalSettings.json";
			string text = Path.Combine(Path.GetDirectoryName(GetType().Assembly.Location), path);
			if (File.Exists(text))
			{
				Log("Overriding Global Settings path with Mod directory");
				return text;
			}
			return Path.Combine(Application.persistentDataPath, path);
		}

		public string GetName()
		{
			return Name;
		}

		public virtual List<(string, string)> GetPreloadNames()
		{
			return null;
		}

		public virtual (string, Func<IEnumerator>)[] PreloadSceneHooks()
		{
			return Array.Empty<(string, Func<IEnumerator>)>();
		}

		public virtual void Initialize(Dictionary<string, Dictionary<string, GameObject>> preloadedObjects)
		{
			Initialize();
		}

		public virtual string GetVersion()
		{
			return "UNKNOWN";
		}

		public virtual int LoadPriority()
		{
			return 1;
		}

		public virtual void Initialize()
		{
		}

		public virtual string GetMenuButtonText()
		{
			return GetName() + " " + global::Language.Language.Get("MAIN_OPTIONS", "MainMenu");
		}

		private void HookSaveMethods()
		{
			ModHooks.ApplicationQuitHook += SaveGlobalSettings;
			ModHooks.SaveLocalSettings += SaveLocalSettings;
			ModHooks.LoadLocalSettings += LoadLocalSettings;
			UnityEngine.SceneManagement.SceneManager.activeSceneChanged += SceneChanged;
		}

		private void SceneChanged(Scene arg0, Scene arg1)
		{
			if (!(arg1.name != "Menu_Title"))
			{
				Type type = saveSettingsType;
				if ((object)type != null)
				{
					onLoadSaveSettings(this, Activator.CreateInstance(type));
				}
			}
		}

		private void LoadGlobalSettings()
		{
			try
			{
				Type type = globalSettingsType;
				if ((object)type == null || !File.Exists(_globalSettingsPath))
				{
					return;
				}
				Log("Loading Global Settings");
				if (TryLoadGlobalSettings(_globalSettingsPath, type))
				{
					return;
				}
				LogError("Null global settings passed to " + GetName());
				string text = _globalSettingsPath + ".bak";
				if (File.Exists(text))
				{
					if (TryLoadGlobalSettings(text, type))
					{
						Log("Successfully loaded global settings from backup");
						File.Delete(_globalSettingsPath);
						File.Copy(text, _globalSettingsPath);
					}
					LogError("Failed to load global settings from backup");
				}
			}
			catch (Exception message)
			{
				LogError(message);
			}
		}

		private bool TryLoadGlobalSettings(string path, Type saveType)
		{
			using FileStream stream = File.OpenRead(_globalSettingsPath);
			using StreamReader streamReader = new StreamReader(stream);
			object obj = JsonConvert.DeserializeObject(streamReader.ReadToEnd(), saveType, new JsonSerializerSettings
			{
				ContractResolver = ShouldSerializeContractResolver.Instance,
				TypeNameHandling = TypeNameHandling.Auto,
				ObjectCreationHandling = ObjectCreationHandling.Replace,
				Converters = JsonConverterTypes.ConverterTypes
			});
			if (obj == null)
			{
				return false;
			}
			onLoadGlobalSettings(this, obj);
			return true;
		}

		protected void SaveGlobalSettings()
		{
			try
			{
				if ((object)globalSettingsType == null)
				{
					return;
				}
				Log("Saving Global Settings");
				object obj = onSaveGlobalSettings(this);
				if (obj == null)
				{
					return;
				}
				if (File.Exists(_globalSettingsPath + ".bak"))
				{
					File.Delete(_globalSettingsPath + ".bak");
				}
				if (File.Exists(_globalSettingsPath))
				{
					File.Move(_globalSettingsPath, _globalSettingsPath + ".bak");
				}
				using FileStream stream = File.Create(_globalSettingsPath);
				using StreamWriter streamWriter = new StreamWriter(stream);
				streamWriter.Write(JsonConvert.SerializeObject(obj, Newtonsoft.Json.Formatting.Indented, new JsonSerializerSettings
				{
					ContractResolver = ShouldSerializeContractResolver.Instance,
					TypeNameHandling = TypeNameHandling.Auto,
					Converters = JsonConverterTypes.ConverterTypes
				}));
			}
			catch (Exception message)
			{
				LogError(message);
			}
		}

		private void LoadLocalSettings(ModSavegameData data)
		{
			try
			{
				Type type = saveSettingsType;
				if ((object)type != null && data.modData.TryGetValue(GetName(), out var value))
				{
					onLoadSaveSettings(this, value.ToObject(type, JsonSerializer.Create(new JsonSerializerSettings
					{
						ContractResolver = ShouldSerializeContractResolver.Instance,
						TypeNameHandling = TypeNameHandling.Auto,
						ObjectCreationHandling = ObjectCreationHandling.Replace,
						Converters = JsonConverterTypes.ConverterTypes
					})));
				}
			}
			catch (Exception message)
			{
				LogError(message);
			}
		}

		private void SaveLocalSettings(ModSavegameData data)
		{
			try
			{
				if ((object)saveSettingsType != null)
				{
					object obj = onSaveSaveSettings(this);
					if (obj != null)
					{
						data.modData[GetName()] = JToken.FromObject(obj, JsonSerializer.Create(new JsonSerializerSettings
						{
							ContractResolver = ShouldSerializeContractResolver.Instance,
							TypeNameHandling = TypeNameHandling.Auto,
							Converters = JsonConverterTypes.ConverterTypes
						}));
					}
				}
			}
			catch (Exception message)
			{
				LogError(message);
			}
		}
	}
