		private static event Action _finishedLoadingModsHook;

		public static event Action FinishedLoadingModsHook
		{
			add
			{
				_finishedLoadingModsHook += value;
				if (!ModLoader.LoadState.HasFlag(ModLoader.ModLoadState.Loaded))
				{
					return;
				}
				try
				{
					value();
				}
				catch (Exception message)
				{
					Logger.APILogger.LogError(message);
				}
			}
			remove
			{
				_finishedLoadingModsHook -= value;
			}
		}

		static ModHooks()
		{
			SettingsPath = Path.Combine(Application.persistentDataPath, "ModdingApi.GlobalSettings.json");
			LoadedModsWithVersions = new Dictionary<string, string>();
			GlobalSettings = new ModHooksGlobalSettings();
			GameVersion gameVersion = default(GameVersion);
			try
			{
				string[] array = "1.5.78.11833".Split('.');
				gameVersion.major = Convert.ToInt32(array[0]);
				gameVersion.minor = Convert.ToInt32(array[1]);
				gameVersion.revision = Convert.ToInt32(array[2]);
				gameVersion.package = Convert.ToInt32(array[3]);
			}
			catch (Exception ex)
			{
				gameVersion.major = 0;
				gameVersion.minor = 0;
				gameVersion.revision = 0;
				gameVersion.package = 0;
				Logger.APILogger.LogError("Failed obtaining game version:\n" + ex);
			}
			version = new GameVersionData
			{
				gameVersion = gameVersion
			};
			ModVersion = version.GetGameVersionString() + "-" + 77;
			FinishedLoadingModsHook += delegate
			{
				ApplicationQuitHook += SaveGlobalSettings;
			};
		}

		internal static void LoadGlobalSettings()
		{
			try
			{
				if (!File.Exists(SettingsPath))
				{
					return;
				}
				Logger.APILogger.Log("Loading Global Settings");
				using FileStream stream = File.OpenRead(SettingsPath);
				using StreamReader streamReader = new StreamReader(stream);
				ModHooksGlobalSettings modHooksGlobalSettings = JsonConvert.DeserializeObject<ModHooksGlobalSettings>(streamReader.ReadToEnd(), new JsonSerializerSettings
				{
					ContractResolver = ShouldSerializeContractResolver.Instance,
					TypeNameHandling = TypeNameHandling.Auto,
					ObjectCreationHandling = ObjectCreationHandling.Replace,
					Converters = JsonConverterTypes.ConverterTypes
				});
				if (modHooksGlobalSettings != null)
				{
					GlobalSettings = modHooksGlobalSettings;
					Logger.SetLogLevel(GlobalSettings.LoggingLevel);
					Logger.SetUseShortLogLevel(GlobalSettings.ShortLoggingLevel);
					Logger.SetIncludeTimestampt(GlobalSettings.IncludeTimestamps);
				}
			}
			catch (Exception message)
			{
				Logger.APILogger.LogError(message);
			}
		}

		internal static void SaveGlobalSettings()
		{
			try
			{
				Logger.APILogger.Log("Saving Global Settings");
				ModHooksGlobalSettings globalSettings = GlobalSettings;
				if (globalSettings == null)
				{
					return;
				}
				globalSettings.ModEnabledSettings = new Dictionary<string, bool>();
				foreach (ModLoader.ModInstance modInstance in ModLoader.ModInstances)
				{
					if (modInstance.Mod is ITogglableMod)
					{
						ModLoader.ModErrorState? error = modInstance.Error;
						if (!error.HasValue)
						{
							globalSettings.ModEnabledSettings.Add(modInstance.Name, modInstance.Enabled);
						}
					}
				}
				if (File.Exists(SettingsPath + ".bak"))
				{
					File.Delete(SettingsPath + ".bak");
				}
				if (File.Exists(SettingsPath))
				{
					File.Move(SettingsPath, SettingsPath + ".bak");
				}
				using FileStream stream = File.Create(SettingsPath);
				using StreamWriter streamWriter = new StreamWriter(stream);
				streamWriter.Write(JsonConvert.SerializeObject(globalSettings, Newtonsoft.Json.Formatting.Indented, new JsonSerializerSettings
				{
					ContractResolver = ShouldSerializeContractResolver.Instance,
					TypeNameHandling = TypeNameHandling.Auto,
					Converters = JsonConverterTypes.ConverterTypes
				}));
			}
			catch (Exception message)
			{
				Logger.APILogger.LogError(message);
			}
		}

		internal static void LogConsole(string message, LogLevel level)
		{
			try
			{
				if (GlobalSettings.ShowDebugLogInGame)
				{
					if (_console == null)
					{
						GameObject gameObject = new GameObject();
						UnityEngine.Object.DontDestroyOnLoad(gameObject);
						_console = gameObject.AddComponent<Console>();
					}
					_console.AddText(message, level);
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}

		internal static string LanguageGet(string key, string sheet)
		{
			string text = global::Language.Language.GetInternal(key, sheet);
			if (LanguageGetHook == null)
			{
				return text;
			}
			Delegate[] invocationList = LanguageGetHook.GetInvocationList();
			for (int i = 0; i < invocationList.Length; i++)
			{
				LanguageGetProxy languageGetProxy = (LanguageGetProxy)invocationList[i];
				try
				{
					text = languageGetProxy(key, sheet, text);
				}
				catch (Exception message)
				{
					Logger.APILogger.LogError(message);
				}
			}
			return text;
		}

		internal static void OnCursor(GameManager gm)
		{
			Cursor.lockState = CursorLockMode.None;
			if (CursorHook != null)
			{
				CursorHook();
			}
			else if (gm.isPaused)
			{
				Cursor.visible = true;
			}
			else
			{
				Cursor.visible = false;
			}
		}

