		internal static void SetPlayerVariable<T>(string target, T orig, PlayerData pd)
		{
			Type typeFromHandle = typeof(T);
			if (typeFromHandle == typeof(bool))
			{
				SetPlayerBool(target, (bool)(object)orig, pd);
				return;
			}
			if (typeFromHandle == typeof(int))
			{
				SetPlayerInt(target, (int)(object)orig, pd);
				return;
			}
			if (typeFromHandle == typeof(float))
			{
				SetPlayerFloat(target, (float)(object)orig, pd);
				return;
			}
			if (typeFromHandle == typeof(string))
			{
				SetPlayerString(target, (string)(object)orig, pd);
				return;
			}
			if (typeFromHandle == typeof(Vector3))
			{
				SetPlayerVector3(target, (Vector3)(object)orig, pd);
				return;
			}
			T val = orig;
			if (SetPlayerVariableHook != null)
			{
				Delegate[] invocationList = SetPlayerVariableHook.GetInvocationList();
				for (int i = 0; i < invocationList.Length; i++)
				{
					SetVariableProxy setVariableProxy = (SetVariableProxy)invocationList[i];
					try
					{
						val = (T)setVariableProxy(typeFromHandle, target, val);
					}
					catch (Exception message)
					{
						Logger.APILogger.LogError(message);
					}
				}
			}
			pd.SetVariableInternal(target, val);
		}

		internal static T GetPlayerVariable<T>(string target, PlayerData pd)
		{
			Type typeFromHandle = typeof(T);
			if (typeFromHandle == typeof(bool))
			{
				return (T)(object)GetPlayerBool(target, pd);
			}
			if (typeFromHandle == typeof(int))
			{
				return (T)(object)GetPlayerInt(target, pd);
			}
			if (typeFromHandle == typeof(float))
			{
				return (T)(object)GetPlayerFloat(target, pd);
			}
			if (typeFromHandle == typeof(string))
			{
				return (T)(object)GetPlayerString(target, pd);
			}
			if (typeFromHandle == typeof(Vector3))
			{
				return (T)(object)GetPlayerVector3(target, pd);
			}
			T val = pd.GetVariableInternal<T>(target);
			if (GetPlayerVariableHook == null)
			{
				return val;
			}
			Delegate[] invocationList = GetPlayerVariableHook.GetInvocationList();
			for (int i = 0; i < invocationList.Length; i++)
			{
				GetVariableProxy getVariableProxy = (GetVariableProxy)invocationList[i];
				try
				{
					val = (T)getVariableProxy(typeFromHandle, target, val);
				}
				catch (Exception message)
				{
					Logger.APILogger.LogError(message);
				}
			}
			return val;
		}

