				Func<string, string> func = (Func<string, string>)invocationList[i];
				try
				{
					sceneName = func(sceneName);
				}
				catch (Exception message)
				{
					Logger.APILogger.LogError(message);
				}
			}
			return sceneName;
		}

		public static IMod GetMod(string name, bool onlyEnabled = false, bool allowLoadError = false)
		{
			if (ModLoader.ModInstanceNameMap.TryGetValue(name, out var value) && (!onlyEnabled || value.Enabled))
			{
				if (!allowLoadError)
				{
					ModLoader.ModErrorState? error = value.Error;
					if (error.HasValue)
					{
						goto IL_002d;
					}
				}
				return value.Mod;
			}
			goto IL_002d;
			IL_002d:
			return null;
		}

		public static IMod GetMod(Type type, bool onlyEnabled = false, bool allowLoadError = false)
		{
			if (ModLoader.ModInstanceTypeMap.TryGetValue(type, out var value) && (!onlyEnabled || value.Enabled))
			{
				if (!allowLoadError)
				{
					ModLoader.ModErrorState? error = value.Error;
					if (error.HasValue)
					{
						goto IL_002d;
					}
				}
				return value.Mod;
			}
			goto IL_002d;
			IL_002d:
			return null;
		}

		public static bool ModEnabled(ITogglableMod mod)
		{
			return ModEnabled(mod.GetType());
		}

		public static bool ModEnabled(string name)
		{
			if (!ModLoader.ModInstanceNameMap.TryGetValue(name, out var value))
			{
				return true;
			}
			return value.Enabled;
		}

		public static bool ModEnabled(Type type)
		{
			if (!ModLoader.ModInstanceTypeMap.TryGetValue(type, out var value))
			{
				return true;
			}
			return value.Enabled;
		}

		public static IEnumerable<IMod> GetAllMods(bool onlyEnabled = false, bool allowLoadError = false)
		{
			return from x in ModLoader.ModInstances.Where(delegate(ModLoader.ModInstance x)
				{
					if (!onlyEnabled || x.Enabled)
					{
						if (!allowLoadError)
						{
							ModLoader.ModErrorState? error = x.Error;
							return !error.HasValue;
						}
						return true;
					}
					return false;
				})
				select x.Mod;
		}

		internal static void OnFinishedLoadingMods()
		{
			if (_finishedLoadingModsHook == null)
			{
				return;
			}
			Delegate[] invocationList = _finishedLoadingModsHook.GetInvocationList();
			for (int i = 0; i < invocationList.Length; i++)
			{
				Action action = (Action)invocationList[i];
				try
				{
					action();
				}
				catch (Exception message)
				{
					Logger.APILogger.LogError(message);
				}
			}
		}
	}
