		private void ToggleMods()
		{
			foreach (var (modInstance2, flag2) in changedMods)
			{
				_ = modInstance2.Name;
				if (flag2)
				{
					ModLoader.LoadMod(modInstance2);
				}
				else
				{
					ModLoader.UnloadMod(modInstance2);
				}
			}
			changedMods.Clear();
		}

		private void ApplyChanges()
		{
			ToggleMods();
			UIManager.instance.UILeaveDynamicMenu(UIManager.instance.optionsMenuScreen, MainMenuState.OPTIONS_MENU);
