	internal class Preloader : MonoBehaviour
	{
		private ProgressBar progressBar;

		private static string DataPath
		{
			get
			{
				if (Application.platform != RuntimePlatform.OSXPlayer)
				{
					return Application.dataPath;
				}
				return Path.Combine(Application.dataPath, "Resources", "Data");
			}
		}

		private void Start()
		{
			progressBar = base.gameObject.AddComponent<ProgressBar>();
		}

		public IEnumerator Preload(Dictionary<string, List<(ModLoader.ModInstance, List<string>)>> toPreload, Dictionary<ModLoader.ModInstance, Dictionary<string, Dictionary<string, GameObject>>> preloadedObjects, Dictionary<string, List<Func<IEnumerator>>> sceneHooks)
		{
			Stopwatch stopwatch = Stopwatch.StartNew();
			MuteAllAudio();
			bool flag = sceneHooks.Sum((KeyValuePair<string, List<Func<IEnumerator>>> kvp) => kvp.Value.Count) > 0;
			Logger.APILogger.Log($"Preloading using mode {ModHooks.GlobalSettings.PreloadMode}");
			PreloadMode preloadMode = ModHooks.GlobalSettings.PreloadMode;
			if (preloadMode != PreloadMode.FullScene)
			{
				try
				{
					Marshal.PrelinkAll(typeof(UnitySceneRepacker));
				}
				catch (DllNotFoundException)
				{
					Logger.APILogger.LogWarn("Unable to load UnitySceneRepacker, falling back to full scene loads.");
					preloadMode = PreloadMode.FullScene;
				}
			}
			switch (preloadMode)
			{
			case PreloadMode.FullScene:
				yield return DoPreloadScenes(toPreload, preloadedObjects, sceneHooks);
				break;
			case PreloadMode.RepackScene:
				yield return DoPreloadRepackedScenes(toPreload, preloadedObjects, sceneHooks);
				break;
			case PreloadMode.RepackAssets:
				if (flag)
				{
					Logger.APILogger.LogWarn("Some mods (" + string.Join(", ", sceneHooks.Keys) + ") use scene hooks, falling back to \"RepackScene\" preload mode");
					yield return DoPreloadRepackedScenes(toPreload, preloadedObjects, sceneHooks);
				}
				else
				{
					yield return DoPreloadAssetBundle(toPreload, preloadedObjects, sceneHooks);
				}
				break;
			default:
				Logger.APILogger.LogError($"Unknown preload mode {ModHooks.GlobalSettings.PreloadMode}. Expected one of: full-scene, repack-scene, repack-assets");
				break;
			}
			yield return CleanUpPreloading();
			UnmuteAllAudio();
			Logger.APILogger.LogError($"Finished preloading in {stopwatch.ElapsedMilliseconds / 1000:F2}s");
		}

		private static void MuteAllAudio()
		{
			AudioListener.pause = true;
		}

		private IEnumerator DoPreloadAssetBundle(Dictionary<string, List<(ModLoader.ModInstance Mod, List<string> Preloads)>> toPreload, IDictionary<ModLoader.ModInstance, Dictionary<string, Dictionary<string, GameObject>>> preloadedObjects, Dictionary<string, List<Func<IEnumerator>>> sceneHooks)
		{
			string preloadsJson = JsonConvert.SerializeObject(toPreload.ToDictionary((KeyValuePair<string, List<(ModLoader.ModInstance Mod, List<string> Preloads)>> k) => k.Key, (KeyValuePair<string, List<(ModLoader.ModInstance Mod, List<string> Preloads)>> v) => v.Value.SelectMany(((ModLoader.ModInstance Mod, List<string> Preloads) x) => x.Preloads).Distinct()));
			byte[] array = null;
			try
			{
				RepackStats repackStats;
				(array, repackStats) = UnitySceneRepacker.Repack("modding_api_asset_bundle", DataPath, preloadsJson, UnitySceneRepacker.Mode.AssetBundle);
				Logger.APILogger.Log($"Repacked {toPreload.Count} preload scenes from {repackStats.ObjectsBefore} to {repackStats.ObjectsAfter} objects ({(float)array.Length / 1024f / 1024f:F2}MB)");
			}
			catch (Exception arg)
			{
				Logger.APILogger.LogError($"Error trying to repack preloads into asset bundle: {arg}");
			}
			if (array == null)
			{
				yield return DoPreloadScenes(toPreload, preloadedObjects, sceneHooks);
				yield break;
			}
			AssetBundleCreateRequest op = AssetBundle.LoadFromMemoryAsync(array);
			if (op == null)
			{
				progressBar.Progress = 1f;
				yield break;
			}
			yield return op;
			AssetBundle assetBundle = op.assetBundle;
			HashSet<AssetBundleRequest> queue = new HashSet<AssetBundleRequest>();
			foreach (var (sceneName, list2) in toPreload)
			{
				foreach (var (mod, list3) in list2)
				{
					if (!preloadedObjects.TryGetValue(mod, out var value))
					{
						value = new Dictionary<string, Dictionary<string, GameObject>>();
						preloadedObjects[mod] = value;
					}
					if (!value.TryGetValue(sceneName, out var modScenePreloads))
					{
						modScenePreloads = new Dictionary<string, GameObject>();
						value[sceneName] = modScenePreloads;
					}
					foreach (string path in list3)
					{
						if (modScenePreloads.ContainsKey(path))
						{
							continue;
						}
						string assetName = sceneName + "/" + path + ".prefab";
						AssetBundleRequest request = assetBundle.LoadAssetAsync<GameObject>(assetName);
						request.completed += delegate
						{
							queue.Remove(request);
							GameObject gameObject = (GameObject)request.asset;
							if (!gameObject)
							{
								Logger.APILogger.LogError("    could not load '" + assetName + "'");
							}
							else if (modScenePreloads.ContainsKey(path))
							{
								Logger.APILogger.LogWarn("Duplicate preload by " + mod.Name + ": '" + path + "' in '" + sceneName + "'");
							}
							else
							{
								modScenePreloads.Add(path, gameObject);
							}
						};
						queue.Add(request);
					}
				}
			}
			int total = queue.Count;
			while (queue.Count > 0)
			{
				float progress = (float)(total - queue.Count) / (float)total;
				progressBar.Progress = progress;
				yield return null;
			}
		}

		private IEnumerator DoPreloadRepackedScenes(Dictionary<string, List<(ModLoader.ModInstance Mod, List<string> Preloads)>> toPreload, IDictionary<ModLoader.ModInstance, Dictionary<string, Dictionary<string, GameObject>>> preloadedObjects, Dictionary<string, List<Func<IEnumerator>>> sceneHooks)
		{
			string preloadJson = JsonConvert.SerializeObject(toPreload.ToDictionary((KeyValuePair<string, List<(ModLoader.ModInstance Mod, List<string> Preloads)>> k) => k.Key, (KeyValuePair<string, List<(ModLoader.ModInstance Mod, List<string> Preloads)>> v) => v.Value.SelectMany(((ModLoader.ModInstance Mod, List<string> Preloads) x) => x.Preloads).Distinct()));
			byte[] bundleData = null;
			Task task = Task.Run(delegate
			{
				try
				{
					RepackStats repackStats;
					(bundleData, repackStats) = UnitySceneRepacker.Repack("modding_api_scene_bundle", DataPath, preloadJson, UnitySceneRepacker.Mode.SceneBundle);
					Logger.APILogger.Log($"Repacked {toPreload.Count} preload scenes from {repackStats.ObjectsBefore} to {repackStats.ObjectsAfter} objects ({(float)bundleData.Length / 1024f / 1024f:F2}MB)");
				}
				catch (Exception arg)
				{
					Logger.APILogger.LogError($"Error trying to repack preloads into assetbundle: {arg}");
				}
			});
			yield return new WaitUntil(() => task.IsCompleted);
			if (bundleData == null)
			{
				yield return DoPreloadScenes(toPreload, preloadedObjects, sceneHooks);
				yield break;
			}
			AssetBundle repackBundle = AssetBundle.LoadFromMemory(bundleData);
			if (repackBundle == null)
			{
				Logger.APILogger.LogWarn("Scene repacking during preloading produced an unloadable asset bundle");
				yield return DoPreloadScenes(toPreload, preloadedObjects, sceneHooks);
				yield break;
			}
			HashSet<string> hashSet = new HashSet<string>(sceneHooks.Select((KeyValuePair<string, List<Func<IEnumerator>>> x) => x.Key));
			Dictionary<string, List<(ModLoader.ModInstance, List<string>)>> shared = new Dictionary<string, List<(ModLoader.ModInstance, List<string>)>>();
			Dictionary<string, List<(ModLoader.ModInstance, List<string>)>> dictionary = new Dictionary<string, List<(ModLoader.ModInstance, List<string>)>>();
			foreach (var (text2, value) in toPreload)
			{
				(hashSet.Contains(text2) ? shared : dictionary)[text2] = value;
			}
			yield return DoPreloadScenes(dictionary, preloadedObjects, new Dictionary<string, List<Func<IEnumerator>>>(), "modding_api_scene_bundle_", 0.5f);
			yield return DoPreloadScenes(shared, preloadedObjects, sceneHooks, "", 0.5f, 0.5f);
			repackBundle.Unload(unloadAllLoadedObjects: true);
		}

		private IEnumerator DoPreloadScenes(Dictionary<string, List<(ModLoader.ModInstance Mod, List<string> Preloads)>> toPreload, IDictionary<ModLoader.ModInstance, Dictionary<string, Dictionary<string, GameObject>>> preloadedObjects, Dictionary<string, List<Func<IEnumerator>>> sceneHooks, string scenePrefix = "", float progressAlpha = 1f, float progressBeta = 0f)
		{
			List<string> sceneNames = toPreload.Keys.Union(sceneHooks.Keys).ToList();
			Dictionary<string, int> scenePriority = new Dictionary<string, int>();
			Dictionary<string, (AsyncOperation load, AsyncOperation unload)> sceneAsyncOperationHolder = new Dictionary<string, (AsyncOperation, AsyncOperation)>();
			foreach (string item in sceneNames)
			{
				int num = 0;
				if (toPreload.TryGetValue(item, out List<(ModLoader.ModInstance, List<string>)> value))
				{
					num += value.Select<(ModLoader.ModInstance, List<string>), int>(((ModLoader.ModInstance Mod, List<string> Preloads) x) => x.Preloads.Count).Sum();
				}
				scenePriority[item] = num;
				sceneAsyncOperationHolder[item] = (null, null);
			}
			List<AsyncOperation> preloadOperationQueue = new List<AsyncOperation>(ModHooks.GlobalSettings.PreloadBatchSize);
			int i = 0;
			float num2 = 0f;
			while (num2 < 1f)
			{
				while (preloadOperationQueue.Count < ModHooks.GlobalSettings.PreloadBatchSize && i < sceneNames.Count && num2 < 1f)
				{
					StartPreloadOperation(sceneNames[i++]);
				}
				yield return null;
				num2 = sceneAsyncOperationHolder.Values.Select(((AsyncOperation load, AsyncOperation unload) x) => (x.load?.progress ?? 0f) * 0.5f + (x.unload?.progress ?? 0f) * 0.5f).Average();
				progressBar.Progress = num2 * progressAlpha + progressBeta;
			}
			progressBar.Progress = 1f * progressAlpha + progressBeta;
			void CleanupPreloadOperation(string sceneName)
			{
				Logger.APILogger.LogFine("Unloading scene \"" + sceneName + "\"");
				AsyncOperation unloadOp = UnityEngine.SceneManagement.SceneManager.UnloadSceneAsync(scenePrefix + sceneName);
				sceneAsyncOperationHolder[sceneName] = (sceneAsyncOperationHolder[sceneName].load, unloadOp);
				unloadOp.completed += delegate
				{
					preloadOperationQueue.Remove(unloadOp);
				};
				preloadOperationQueue.Add(unloadOp);
			}
			Dictionary<string, GameObject> GetModScenePreloadedObjects(ModLoader.ModInstance mod, string sceneName)
			{
				if (!preloadedObjects.TryGetValue(mod, out var value2))
				{
					value2 = (preloadedObjects[mod] = new Dictionary<string, Dictionary<string, GameObject>>());
				}
				if (!value2.TryGetValue(sceneName, out var value3))
				{
					value3 = (value2[sceneName] = new Dictionary<string, GameObject>());
				}
				return value3;
			}
			IEnumerator GetPreloadObjectsOperation(string sceneName)
			{
				Scene sceneByName = UnityEngine.SceneManagement.SceneManager.GetSceneByName(scenePrefix + sceneName);
				GameObject[] rootObjects = sceneByName.GetRootGameObjects();
				GameObject[] array = rootObjects;
				for (int j = 0; j < array.Length; j++)
				{
					array[j].SetActive(value: false);
				}
				if (sceneHooks.TryGetValue(sceneByName.name, out var value2))
				{
					IEnumerator[] array2 = value2.Select((Func<IEnumerator> x) => x()).ToArray();
					for (int num3 = 0; num3 < array2.Length; num3++)
					{
						yield return array2[num3];
					}
				}
				if (!toPreload.TryGetValue(sceneName, out List<(ModLoader.ModInstance, List<string>)> value3))
				{
					yield break;
				}
				foreach (var (modInstance, list) in value3)
				{
					Logger.APILogger.LogFine("Fetching objects for mod \"" + modInstance.Mod.GetName() + "\"");
					Dictionary<string, GameObject> dictionary = GetModScenePreloadedObjects(modInstance, sceneName);
					foreach (string item2 in list)
					{
						Logger.APILogger.LogFine("Fetching object \"" + item2 + "\"");
						GameObject gameObjectFromArray;
						try
						{
							gameObjectFromArray = UnityExtensions.GetGameObjectFromArray(rootObjects, item2);
						}
						catch (ArgumentException)
						{
							Logger.APILogger.LogWarn("Invalid GameObject name " + item2);
							continue;
						}
						if (gameObjectFromArray == null)
						{
							Logger.APILogger.LogWarn("Could not find object \"" + item2 + "\" in scene \"" + sceneName + "\", requested by mod `" + modInstance.Mod.GetName() + "`");
						}
						else
						{
							gameObjectFromArray = UnityEngine.Object.Instantiate(gameObjectFromArray);
							UnityEngine.Object.DontDestroyOnLoad(gameObjectFromArray);
							gameObjectFromArray.SetActive(value: false);
							dictionary[item2] = gameObjectFromArray;
						}
					}
				}
			}
			void StartPreloadOperation(string sceneName)
			{
				Logger.APILogger.LogFine("Loading scene \"" + sceneName + "\"");
				AsyncOperation asyncOperation = UnityEngine.SceneManagement.SceneManager.LoadSceneAsync(scenePrefix + sceneName, LoadSceneMode.Additive);
				StartCoroutine(DoLoad(asyncOperation));
				sceneAsyncOperationHolder[sceneName] = (asyncOperation, null);
				asyncOperation.priority = scenePriority[sceneName];
				preloadOperationQueue.Add(asyncOperation);
				IEnumerator DoLoad(AsyncOperation load)
				{
					yield return load;
					preloadOperationQueue.Remove(load);
					yield return GetPreloadObjectsOperation(sceneName);
					CleanupPreloadOperation(sceneName);
				}
			}
		}

		private IEnumerator CleanUpPreloading()
		{
			Logger.APILogger.LogDebug("Preload done, returning to main menu");
			ModLoader.LoadState |= ModLoader.ModLoadState.Preloaded;
			yield return UnityEngine.SceneManagement.SceneManager.LoadSceneAsync("Quit_To_Menu");
			while (UnityEngine.SceneManagement.SceneManager.GetActiveScene().name != "Menu_Title")
			{
				yield return new WaitForEndOfFrame();
			}
			UnityEngine.Object.Destroy(progressBar);
		}

		private static void UnmuteAllAudio()
		{
			AudioListener.pause = false;
		}
	}
	internal class ProgressBar : MonoBehaviour
	{
		private const int CanvasResolutionWidth = 1920;

		private const int CanvasResolutionHeight = 1080;

		private const int LoadingBarBackgroundWidth = 1000;

		private const int LoadingBarBackgroundHeight = 100;

		private const int LoadingBarMargin = 12;

		private const int LoadingBarWidth = 976;

		private const int LoadingBarHeight = 76;

		private GameObject _blanker;

		private GameObject _loadingBarBackground;

		private GameObject _loadingBar;

		private RectTransform _loadingBarRect;

		private float _commandedProgress;

		private float _shownProgress;

		public float Progress
		{
			get
			{
				return _commandedProgress;
			}
			set
			{
				_commandedProgress = value;
			}
		}

		public void Start()
		{
			CreateBlanker();
			CreateLoadingBarBackground();
			CreateLoadingBar();
		}

		private static float ExpDecay(float a, float b, float decay)
		{
			return b + (a - b) * Mathf.Exp((0f - decay) * Time.deltaTime);
		}

		public void Update()
		{
			_shownProgress = ExpDecay(_shownProgress, _commandedProgress, 16f);
		}

		public void LateUpdate()
		{
			_loadingBarRect.sizeDelta = new Vector2(_shownProgress * 976f, _loadingBarRect.sizeDelta.y);
		}

		private void CreateBlanker()
		{
			_blanker = CanvasUtil.CreateCanvas(RenderMode.ScreenSpaceOverlay, new Vector2(1920f, 1080f));
			UnityEngine.Object.DontDestroyOnLoad(_blanker);
			CanvasUtil.CreateImagePanel(_blanker, CanvasUtil.NullSprite(new byte[4] { 0, 0, 0, 255 }), new CanvasUtil.RectData(Vector2.zero, Vector2.zero, Vector2.zero, Vector2.one)).GetComponent<Image>().preserveAspect = false;
		}

		private void CreateLoadingBarBackground()
		{
			_loadingBarBackground = CanvasUtil.CreateImagePanel(_blanker, CanvasUtil.NullSprite(new byte[4] { 255, 255, 255, 255 }), new CanvasUtil.RectData(new Vector2(1000f, 100f), Vector2.zero, new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f)));
			_loadingBarBackground.GetComponent<Image>().preserveAspect = false;
		}

		private void CreateLoadingBar()
		{
			_loadingBar = CanvasUtil.CreateImagePanel(_blanker, CanvasUtil.NullSprite(new byte[4] { 153, 153, 153, 255 }), new CanvasUtil.RectData(new Vector2(0f, 76f), Vector2.zero, new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f)));
			_loadingBar.GetComponent<Image>().preserveAspect = false;
			_loadingBarRect = _loadingBar.GetComponent<RectTransform>();
		}

		private void OnDestroy()
		{
			UnityEngine.Object.Destroy(_loadingBar);
			UnityEngine.Object.Destroy(_loadingBarBackground);
			UnityEngine.Object.Destroy(_blanker);
		}
	}
	public static class ReflectionHelper
	{
		private static readonly ConcurrentDictionary<Type, ConcurrentDictionary<string, FieldInfo>> Fields = new ConcurrentDictionary<Type, ConcurrentDictionary<string, FieldInfo>>();

		private static readonly ConcurrentDictionary<FieldInfo, Delegate> FieldGetters = new ConcurrentDictionary<FieldInfo, Delegate>();

		private static readonly ConcurrentDictionary<FieldInfo, Delegate> FieldSetters = new ConcurrentDictionary<FieldInfo, Delegate>();

		private static readonly ConcurrentDictionary<Type, ConcurrentDictionary<string, PropertyInfo>> Properties = new ConcurrentDictionary<Type, ConcurrentDictionary<string, PropertyInfo>>();

		private static readonly ConcurrentDictionary<PropertyInfo, Delegate> PropertyGetters = new ConcurrentDictionary<PropertyInfo, Delegate>();

		private static readonly ConcurrentDictionary<PropertyInfo, Delegate> PropertySetters = new ConcurrentDictionary<PropertyInfo, Delegate>();

		private static readonly ConcurrentDictionary<Type, ConcurrentDictionary<string, MethodInfo>> Methods = new ConcurrentDictionary<Type, ConcurrentDictionary<string, MethodInfo>>();

		private static readonly ConcurrentDictionary<MethodInfo, FastReflectionDelegate> MethodsDelegates = new ConcurrentDictionary<MethodInfo, FastReflectionDelegate>();

		private static bool _preloaded;

		private static void CacheFields<T>()
		{
			Type t = typeof(T);
			if (!Fields.TryGetValue(t, out var tFields))
			{
				tFields = new ConcurrentDictionary<string, FieldInfo>();
			}
			MethodInfo getInstanceFieldGetter = typeof(ReflectionHelper).GetMethod("GetInstanceFieldGetter", BindingFlags.Static | BindingFlags.NonPublic);
			MethodInfo getStaticFieldGetter = typeof(ReflectionHelper).GetMethod("GetStaticFieldGetter", BindingFlags.Static | BindingFlags.NonPublic);
			MethodInfo getInstanceFieldSetter = typeof(ReflectionHelper).GetMethod("GetInstanceFieldSetter", BindingFlags.Static | BindingFlags.NonPublic);
			MethodInfo getStaticFieldSetter = typeof(ReflectionHelper).GetMethod("GetStaticFieldSetter", BindingFlags.Static | BindingFlags.NonPublic);
			Parallel.ForEach(t.GetFields(BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic), delegate(FieldInfo field)
			{
				tFields[field.Name] = field;
				if (!field.IsLiteral)
				{
					object[] parameters = new object[1] { field };
					if (field.IsStatic)
					{
						getStaticFieldGetter?.MakeGenericMethod(field.FieldType).Invoke(null, parameters);
					}
					else
					{
						getInstanceFieldGetter?.MakeGenericMethod(t, field.FieldType).Invoke(null, parameters);
					}
					if (!field.IsInitOnly)
					{
						if (field.IsStatic)
						{
							getStaticFieldSetter?.MakeGenericMethod(field.FieldType).Invoke(null, parameters);
						}
						else
						{
							getInstanceFieldSetter?.MakeGenericMethod(t, field.FieldType).Invoke(null, parameters);
						}
					}
				}
			});
		}

		internal static void PreloadCommonTypes()
		{
			if (!_preloaded)
			{
				Stopwatch stopwatch = new Stopwatch();
				stopwatch.Start();
				Parallel.Invoke(CacheFields<PlayerData>, CacheFields<HeroController>, CacheFields<HeroControllerStates>, CacheFields<GameManager>, CacheFields<UIManager>);
				stopwatch.Stop();
				Logger.APILogger.Log($"Preloaded reflection in {stopwatch.ElapsedMilliseconds}ms");
				_preloaded = true;
			}
		}

