	{
		public int ObjectsBefore;

		public int ObjectsAfter;
	}
	internal class UnitySceneRepackerException : Exception
	{
		public UnitySceneRepackerException(string message)
			: base(message)
		{
		}
	}
	internal static class UnitySceneRepacker
	{
		public enum Mode
		{
			SceneBundle,
			AssetBundle
		}

		public static (byte[], RepackStats) Repack(string bundleName, string gamePath, string preloadsJson, Mode mode)
		{
			byte[] embeddedTypetreeDump = GetEmbeddedTypetreeDump();
			export(bundleName, gamePath, preloadsJson, out var error, out var bundleSize, out var bundleData, out var repackStats, embeddedTypetreeDump, embeddedTypetreeDump.Length, (byte)mode);
			if (error != IntPtr.Zero)
			{
				throw new UnitySceneRepackerException(PtrToStringAndFree(error));
			}
			return (PtrToByteArrayAndFree(bundleSize, bundleData), repackStats);
		}

		[DllImport("unityscenerepacker", CallingConvention = CallingConvention.Cdecl, CharSet = CharSet.Ansi)]
		private static extern void export([MarshalAs(UnmanagedType.LPUTF8Str)] string bundleName, [MarshalAs(UnmanagedType.LPUTF8Str)] string gameDir, [MarshalAs(UnmanagedType.LPUTF8Str)] string preloadJson, out IntPtr error, out int bundleSize, out IntPtr bundleData, out RepackStats repackStats, byte[] monobehaviourTypetreeExport, int monobehaviourTypetreeExportLen, byte mode);

		[DllImport("unityscenerepacker", CallingConvention = CallingConvention.Cdecl)]
		private static extern void free_str(IntPtr str);

		[DllImport("unityscenerepacker", CallingConvention = CallingConvention.Cdecl)]
		private static extern void free_array(int len, IntPtr data);

		private static string PtrToStringAndFree(IntPtr ptr)
		{
			if (ptr == IntPtr.Zero)
			{
				return null;
			}
			string result = Marshal.PtrToStringAnsi(ptr);
			free_str(ptr);
			return result;
		}

		private static byte[] PtrToByteArrayAndFree(int size, IntPtr ptr)
		{
			if (ptr == IntPtr.Zero || size == 0)
			{
				return new byte[0];
			}
			byte[] array = new byte[size];
			Marshal.Copy(ptr, array, 0, size);
			free_array(size, ptr);
			return array;
		}

		private static byte[] GetEmbeddedTypetreeDump()
		{
			using Stream stream = typeof(UnitySceneRepacker).Assembly.GetManifestResourceStream("Modding.monobehaviour-typetree-dump.lz4");
			using MemoryStream memoryStream = new MemoryStream();
			stream.CopyTo(memoryStream);
			return memoryStream.ToArray();
		}
	}
