namespace Modding.Utils
{
	public static class AssemblyExtensions
	{
		public static IEnumerable<Type> GetTypesSafely(this Assembly asm)
		{
			try
			{
				return asm.GetTypes();
			}
			catch (ReflectionTypeLoadException ex)
			{
				return ex.Types.Where((Type x) => (object)x != null);
			}
		}

		public static Sprite LoadEmbeddedSprite(this Assembly asm, string path, float pixelsPerUnit = 64f)
		{
			using Stream stream = asm.GetManifestResourceStream(path);
			byte[] array = new byte[stream.Length];
			stream.Read(array, 0, array.Length);
			Texture2D texture2D = new Texture2D(2, 2);
			texture2D.LoadImage(array, markNonReadable: true);
			return Sprite.Create(texture2D, new Rect(0f, 0f, texture2D.width, texture2D.height), Vector2.one * 0.5f, pixelsPerUnit);
		}
	}
	public static class UnityExtensions
	{
		public static T GetOrAddComponent<T>(this GameObject go) where T : Component
		{
			T val = go.GetComponent<T>();
			if (val == null)
			{
				val = go.AddComponent<T>();
			}
			return val;
		}

		public static GameObject FindGameObject(this Scene scene, string objName)
		{
			return GetGameObjectFromArray(scene.GetRootGameObjects(), objName);
		}

		internal static GameObject GetGameObjectFromArray(GameObject[] objects, string objName)
		{
			string text = null;
			int num = objName.IndexOf('/');
			string rootName;
			if (num == -1)
			{
				rootName = objName;
			}
			else
			{
				if (num == 0 || num == objName.Length - 1)
				{
					throw new ArgumentException("Invalid GameObject path");
				}
				rootName = objName.Substring(0, num);
				text = objName.Substring(num + 1);
			}
			GameObject gameObject = objects.FirstOrDefault((GameObject o) => o.name == rootName);
			if (gameObject == null)
			{
				return null;
			}
			if (text != null)
			{
				Transform transform = gameObject.transform.Find(text);
				if (!(transform == null))
				{
					return transform.gameObject;
				}
				return null;
			}
			return gameObject;
		}
	}
