			rectTransform4.anchorMin = new Vector2(0.5f, 1f);
			rectTransform4.anchorMax = new Vector2(0.5f, 1f);
			rectTransform4.anchoredPosition = new Vector2(0.8f, 0f);
			rectTransform4.localScale = new Vector3(2f, 2f, 1f);
