			gameObject4.AddComponent<Image>().sprite = MenuResources.ScrollbarHandleSprite;
			gameObject4.AddComponent<ScrollBarHandle>().scrollBar = scrollbar;
			GameObject gameObject5 = new GameObject("Background");
