	public interface IContentLayout
	{
		void ModifyNext(RectTransform rt);
	}
	[StructLayout(LayoutKind.Sequential, Size = 1)]
	public struct NullContentLayout : IContentLayout
	{
		public void ModifyNext(RectTransform rt)
		{
		}
	}
	public class RegularGridLayout : IContentLayout
	{
		public RelVector2 ItemAdvance { get; set; }

		public AnchoredPosition Start { get; set; }

		public int Columns { get; set; }

		public int Index { get; set; }

		public Vector2Int IndexPos => new Vector2Int(Index % Columns, Index / Columns);

		public RegularGridLayout(AnchoredPosition start, RelVector2 itemAdvance, int columns)
		{
			Start = start;
			ItemAdvance = itemAdvance;
			Columns = columns;
		}

		public static RegularGridLayout CreateVerticalLayout(float itemHeight, Vector2 start = default(Vector2))
		{
			return new RegularGridLayout(new AnchoredPosition
			{
				ChildAnchor = new Vector2(0.5f, 1f),
				ParentAnchor = new Vector2(0.5f, 1f),
				Offset = start
			}, new RelVector2(new Vector2(0f, 0f - itemHeight)), 1);
		}

		public void ModifyNext(RectTransform rt)
		{
			(Start + ItemAdvance * IndexPos).Reposition(rt);
			Index++;
		}

		public void ChangeColumns(int columns, float originalAnchor = 0.5f, RelVector2? newSize = null, float newAnchor = 0.5f)
		{
			RelVector2 itemAdvance = newSize ?? ItemAdvance;
			RelLength y = ItemAdvance.y * IndexPos.y;
			RelLength relLength = ItemAdvance.x * Columns * originalAnchor - itemAdvance.x * columns * newAnchor;
			RelLength x = Start.ChildAnchor.x * itemAdvance.x + relLength;
			Index = 0;
			Columns = columns;
			Start += new RelVector2(x, y);
			ItemAdvance = itemAdvance;
		}
	}
	public class EnumeratorLayout : IContentLayout
	{
		private IEnumerator<AnchoredPosition> generator;

		public EnumeratorLayout(IEnumerable<AnchoredPosition> src)
		{
			generator = src.GetEnumerator();
		}

		public EnumeratorLayout(IEnumerator<AnchoredPosition> generator)
		{
			this.generator = generator;
		}

		public void ModifyNext(RectTransform rt)
		{
			if (generator.MoveNext())
			{
				generator.Current.Reposition(rt);
			}
		}
	}
	public class SingleContentLayout : IContentLayout
	{
		public AnchoredPosition Position { get; set; }

		public SingleContentLayout(Vector2 anchor)
			: this(new AnchoredPosition(anchor, anchor))
		{
		}

		public SingleContentLayout(AnchoredPosition pos)
		{
			Position = pos;
		}

		public void ModifyNext(RectTransform rt)
		{
			Position.Reposition(rt);
		}
	}
	public struct AnchoredPosition(Vector2 parentAnchor, Vector2 childAnchor, Vector2 offset = default(Vector2))
	{
		public Vector2 ParentAnchor = parentAnchor;

		public Vector2 ChildAnchor = childAnchor;

		public Vector2 Offset = offset;

		public void Reposition(RectTransform rt)
		{
			GetRepositioned(rt).Apply(rt);
		}

		public RectTransformData GetRepositioned(RectTransformData rt)
		{
			Vector2 vector = ParentAnchor - ParentPointFromChild(rt, ChildAnchor);
			rt.pivot = ChildAnchor;
			rt.anchorMin += vector;
			rt.anchorMax += vector;
			rt.anchoredPosition = Offset;
			return rt;
		}

		public static AnchoredPosition FromSiblingAnchor(Vector2 selfAnchor, RectTransformData sibling, Vector2 siblingAnchor, Vector2 offset)
		{
			return new AnchoredPosition(ParentPointFromChild(sibling, siblingAnchor), selfAnchor, sibling.anchoredPosition + offset);
		}

		public static Vector2 ParentPointFromChild(RectTransformData child, Vector2 childPoint)
		{
			return child.anchorMin + (child.anchorMax - child.anchorMin) * childPoint;
		}

		public static AnchoredPosition operator +(AnchoredPosition lhs, RelVector2 rhs)
		{
			return new AnchoredPosition(lhs.ParentAnchor + rhs.Relative, lhs.ChildAnchor, lhs.Offset + rhs.Delta);
		}

		public static AnchoredPosition operator +(RelVector2 lhs, AnchoredPosition rhs)
		{
			return rhs + lhs;
		}
	}
	public struct RelVector2
	{
		public Vector2 Delta;

		public Vector2 Relative;

		public RelLength x
		{
			get
			{
				return new RelLength(Delta.x, Relative.x);
			}
			set
			{
				Delta.x = value.Delta;
				Relative.x = value.Relative;
			}
		}

		public RelLength y
		{
			get
			{
				return new RelLength(Delta.y, Relative.y);
			}
			set
			{
				Delta.y = value.Delta;
				Relative.y = value.Relative;
			}
		}

		public RelVector2(RelLength x, RelLength y)
		{
			Delta = new Vector2(x.Delta, y.Delta);
			Relative = new Vector2(x.Relative, y.Relative);
		}

		public RelVector2(Vector2 sizeDelta, Vector2 parentRelSize)
		{
			Delta = sizeDelta;
			Relative = parentRelSize;
		}

		public RelVector2(Vector2 size)
			: this(size, default(Vector2))
		{
		}

		public RectTransformData GetBaseTransformData()
		{
			return new RectTransformData
			{
				sizeDelta = Delta,
				anchorMin = default(Vector2),
				anchorMax = Relative
			};
		}

		public static RelVector2 operator -(RelVector2 self)
		{
			return new RelVector2(-self.Delta, -self.Relative);
		}

		public static RelVector2 operator +(RelVector2 lhs, RelVector2 rhs)
		{
			return new RelVector2(lhs.Delta + rhs.Delta, lhs.Relative + rhs.Relative);
		}

		public static RelVector2 operator -(RelVector2 lhs, RelVector2 rhs)
		{
			return new RelVector2(lhs.Delta - rhs.Delta, lhs.Relative - rhs.Relative);
		}

		public static RelVector2 operator *(RelVector2 lhs, float rhs)
		{
			return new RelVector2(lhs.Delta * rhs, lhs.Relative * rhs);
		}

		public static RelVector2 operator *(float lhs, RelVector2 rhs)
		{
			return rhs * lhs;
		}

		public static RelVector2 operator *(RelVector2 lhs, Vector2 rhs)
		{
			return new RelVector2(lhs.Delta * rhs, lhs.Relative * rhs);
		}

		public static RelVector2 operator /(RelVector2 lhs, float rhs)
		{
			return new RelVector2(lhs.Delta / rhs, lhs.Relative / rhs);
		}
	}
	public struct RelLength(float lengthDelta, float parentRelLength)
	{
		public float Delta = lengthDelta;

		public float Relative = parentRelLength;

		public RelLength(float length)
			: this(length, 0f)
		{
		}

		public static RelLength operator -(RelLength self)
		{
			return new RelLength(0f - self.Delta, 0f - self.Relative);
		}

		public static RelLength operator +(RelLength lhs, RelLength rhs)
		{
			return new RelLength(lhs.Delta + rhs.Delta, lhs.Relative + rhs.Relative);
		}

		public static RelLength operator -(RelLength lhs, RelLength rhs)
		{
			return new RelLength(lhs.Delta - rhs.Delta, lhs.Relative - rhs.Relative);
		}

		public static RelLength operator *(RelLength lhs, float rhs)
		{
			return new RelLength(lhs.Delta * rhs, lhs.Relative * rhs);
		}

		public static RelLength operator *(float lhs, RelLength rhs)
		{
			return rhs * lhs;
		}

		public static RelLength operator /(RelLength lhs, float rhs)
		{
			return new RelLength(lhs.Delta / rhs, lhs.Relative / rhs);
		}
	}
	public struct RectTransformData(RectTransform rt)
	{
		public Vector2 sizeDelta = rt.sizeDelta;

		public Vector2 anchorMin = rt.anchorMin;

		public Vector2 anchorMax = rt.anchorMax;

		public Vector2 anchoredPosition = rt.anchoredPosition;

		public Vector2 pivot = rt.pivot;

		public static RectTransformData FromSizeAndPos(RelVector2 size, AnchoredPosition pos)
		{
			return pos.GetRepositioned(size.GetBaseTransformData());
		}

		public void Apply(RectTransform rt)
		{
			rt.sizeDelta = sizeDelta;
			rt.anchorMin = anchorMin;
			rt.anchorMax = anchorMax;
			rt.anchoredPosition = anchoredPosition;
			rt.pivot = pivot;
		}

		public RectTransform AddRectTransform(GameObject obj)
		{
			RectTransform rectTransform = obj.AddComponent<RectTransform>();
			Apply(rectTransform);
			return rectTransform;
		}

		public static implicit operator RectTransformData(RectTransform r)
		{
			return new RectTransformData(r);
		}

		public static implicit operator RectTransformData(CanvasUtil.RectData r)
		{
			return new RectTransformData
			{
				sizeDelta = r.RectSizeDelta,
				anchorMin = r.AnchorMin,
				anchorMax = r.AnchorMax,
				anchoredPosition = r.AnchorPosition,
				pivot = r.AnchorPivot
			};
		}

		public static implicit operator CanvasUtil.RectData(RectTransformData r)
		{
			return new CanvasUtil.RectData(r.sizeDelta, r.anchoredPosition, r.anchorMin, r.anchorMax, r.pivot);
		}
	}
	public class MenuBuilder
	{
