		public MenuBuilder(GameObject canvas, string name)
		{
			MenuObject = new GameObject(name);
			UnityEngine.Object.DontDestroyOnLoad(MenuObject);
			MenuObject.transform.SetParent(canvas.transform, worldPositionStays: false);
			MenuObject.SetActive(value: false);
			Screen = MenuObject.AddComponent<MenuScreen>();
			MenuObject.AddComponent<CanvasRenderer>();
			RectTransform rectTransform = MenuObject.AddComponent<RectTransform>();
			rectTransform.sizeDelta = new Vector2(0f, 463f);
