			GameObject gameObject = new GameObject("Control");
			UnityEngine.Object.DontDestroyOnLoad(gameObject);
			gameObject.transform.SetParent(MenuObject.transform, worldPositionStays: false);
			style.Apply(gameObject.AddComponent<RectTransform>());
			Screen.controls = gameObject.AddComponent<CanvasGroup>();
			gameObject.AddComponent<CanvasRenderer>();
			gameObject.AddComponent<ZeroAlphaOnStart>();
			return this;
		}

		public MenuBuilder SetDefaultNavGraph(INavigationGraph navGraph)
		{
			DefaultNavGraph = (INavigationGraph)(navGraph ?? ((object)default(NullNavigationGraph)));
			return this;
		}
	}
