	public interface INavigationGraph
	{
		void AddNavigationNode(Selectable selectable);

		Selectable BuildNavigation();
	}
	[StructLayout(LayoutKind.Sequential, Size = 1)]
	public struct NullNavigationGraph : INavigationGraph
	{
		public void AddNavigationNode(Selectable selectable)
		{
		}

		public Selectable BuildNavigation()
		{
			return null;
		}
	}
	public class ChainedNavGraph : INavigationGraph
	{
		public enum ChainDir
		{
			Down,
			Up,
			Right,
			Left
		}

		private Selectable first;

		private Selectable last;

		private ChainDir dir;

		public ChainedNavGraph(ChainDir dir = ChainDir.Down)
		{
			this.dir = dir;
		}

		public void AddNavigationNode(Selectable selectable)
		{
			if (first == null)
			{
				first = selectable;
				last = selectable;
				first.navigation = new Navigation
				{
					mode = Navigation.Mode.Explicit
				};
				return;
			}
			switch (dir)
			{
			case ChainDir.Down:
			{
				selectable.navigation = new Navigation
				{
					selectOnDown = first,
					selectOnUp = last,
					mode = Navigation.Mode.Explicit
				};
				Navigation navigation7 = first.navigation;
				navigation7.selectOnUp = selectable;
				first.navigation = navigation7;
				Navigation navigation8 = last.navigation;
				navigation8.selectOnDown = selectable;
				last.navigation = navigation8;
				last = selectable;
				break;
			}
			case ChainDir.Up:
			{
				selectable.navigation = new Navigation
				{
					selectOnUp = first,
					selectOnDown = last,
					mode = Navigation.Mode.Explicit
				};
				Navigation navigation5 = first.navigation;
				navigation5.selectOnDown = selectable;
				first.navigation = navigation5;
				Navigation navigation6 = last.navigation;
				navigation6.selectOnUp = selectable;
				last.navigation = navigation6;
				last = selectable;
				break;
			}
			case ChainDir.Right:
			{
				selectable.navigation = new Navigation
				{
					selectOnRight = first,
					selectOnLeft = last,
					mode = Navigation.Mode.Explicit
				};
				Navigation navigation3 = first.navigation;
				navigation3.selectOnLeft = selectable;
				first.navigation = navigation3;
				Navigation navigation4 = last.navigation;
				navigation4.selectOnRight = selectable;
				last.navigation = navigation4;
				last = selectable;
				break;
			}
			case ChainDir.Left:
			{
				selectable.navigation = new Navigation
				{
					selectOnLeft = first,
					selectOnRight = last,
					mode = Navigation.Mode.Explicit
				};
				Navigation navigation = first.navigation;
				navigation.selectOnRight = selectable;
				first.navigation = navigation;
				Navigation navigation2 = last.navigation;
				navigation2.selectOnLeft = selectable;
				last.navigation = navigation2;
				last = selectable;
				break;
			}
			}
		}

		public Selectable BuildNavigation()
		{
			return first;
		}
	}
	public class GridNavGraph : INavigationGraph
	{
		private List<List<Selectable>> grid;

		public int Columns { get; private set; }

		public GridNavGraph(int columns)
		{
			Columns = columns;
			grid = new List<List<Selectable>>
			{
				new List<Selectable>()
			};
		}

		public void ChangeColumns(int columns)
		{
			Columns = columns;
			grid.Add(new List<Selectable>());
		}

		public void AddNavigationNode(Selectable selectable)
		{
			List<Selectable> list = grid[grid.Count - 1];
			if (list == null || list.Count >= Columns)
			{
				list = new List<Selectable>();
				grid.Add(list);
			}
			list.Add(selectable);
		}

		public Selectable BuildNavigation()
		{
			for (int i = 0; i < grid.Count; i++)
			{
				List<Selectable> wrapped = GetWrapped(grid, i - 1);
				List<Selectable> list = grid[i];
				List<Selectable> wrapped2 = GetWrapped(grid, i + 1);
				Selectable selectable = ((wrapped.Count != list.Count) ? wrapped[0] : null);
				Selectable selectable2 = ((wrapped2.Count != list.Count) ? wrapped2[0] : null);
				for (int j = 0; j < list.Count; j++)
				{
					list[j].navigation = new Navigation
					{
						mode = Navigation.Mode.Explicit,
						selectOnUp = (selectable ?? wrapped[j]),
						selectOnDown = (selectable2 ?? wrapped2[j]),
						selectOnLeft = GetWrapped(list, j - 1),
						selectOnRight = GetWrapped(list, j + 1)
					};
				}
			}
			return grid[0]?[0];
		}

		private static T GetWrapped<T>(List<T> list, int index)
		{
			if (index == -1)
			{
				return list[list.Count - 1];
			}
			if (index == list.Count)
			{
				return list[0];
			}
			return list[index];
		}
	}
	public class MenuResources
	{
		public static Font TrajanRegular { get; private set; }

		public static Font TrajanBold { get; private set; }

		public static Font Perpetua { get; private set; }

		public static Font NotoSerifCJKSCRegular { get; private set; }

		public static RuntimeAnimatorController MenuTopFleurAnimator { get; private set; }

		public static RuntimeAnimatorController MenuCursorAnimator { get; private set; }

		public static RuntimeAnimatorController MenuButtonFlashAnimator { get; private set; }

		public static AnimatorOverrideController TextHideShowAnimator { get; private set; }

		public static Sprite ScrollbarHandleSprite { get; private set; }

		public static Sprite ScrollbarBackgroundSprite { get; private set; }

		static MenuResources()
		{
			ReloadResources();
		}

		public static void ReloadResources()
		{
			RuntimeAnimatorController[] array = Resources.FindObjectsOfTypeAll<RuntimeAnimatorController>();
			foreach (RuntimeAnimatorController runtimeAnimatorController in array)
			{
				if (runtimeAnimatorController != null)
				{
					switch (runtimeAnimatorController.name)
					{
					case "Menu Animate In Out":
						MenuTopFleurAnimator = runtimeAnimatorController;
						break;
					case "Menu Fleur":
						MenuCursorAnimator = runtimeAnimatorController;
						break;
					case "Menu Flash Effect":
						MenuButtonFlashAnimator = runtimeAnimatorController;
						break;
					}
				}
			}
			AnimatorOverrideController[] array2 = Resources.FindObjectsOfTypeAll<AnimatorOverrideController>();
			foreach (AnimatorOverrideController animatorOverrideController in array2)
			{
				if (animatorOverrideController != null && animatorOverrideController.name == "TextHideShow")
				{
					TextHideShowAnimator = animatorOverrideController;
				}
			}
			Font[] array3 = Resources.FindObjectsOfTypeAll<Font>();
			foreach (Font font in array3)
			{
				if (font != null)
				{
					switch (font.name)
					{
					case "TrajanPro-Regular":
						TrajanRegular = font;
						break;
					case "TrajanPro-Bold":
						TrajanBold = font;
						break;
					case "Perpetua":
						Perpetua = font;
						break;
					case "NotoSerifCJKsc-Regular":
						NotoSerifCJKSCRegular = font;
						break;
					}
				}
			}
			Sprite[] array4 = Resources.FindObjectsOfTypeAll<Sprite>();
			foreach (Sprite sprite in array4)
			{
				if (!(sprite != null))
				{
					continue;
				}
				string name = sprite.name;
				if (!(name == "scrollbar_fleur_new"))
				{
					if (name == "scrollbar_single")
					{
						ScrollbarBackgroundSprite = sprite;
					}
				}
				else
				{
					ScrollbarHandleSprite = sprite;
				}
			}
		}
	}
	public static class MenuUtils
	{
		public static MenuBuilder CreateMenuBuilder(string title)
		{
			return new MenuBuilder(title).CreateTitle(title, MenuTitleStyle.vanillaStyle).CreateContentPane(RectTransformData.FromSizeAndPos(new RelVector2(new Vector2(1920f, 903f)), new AnchoredPosition(new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f), new Vector2(0f, -60f)))).CreateControlPane(RectTransformData.FromSizeAndPos(new RelVector2(new Vector2(1920f, 259f)), new AnchoredPosition(new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f), new Vector2(0f, -502f))))
				.SetDefaultNavGraph(new ChainedNavGraph());
		}

		public static MenuBuilder CreateMenuBuilderWithBackButton(string title, MenuScreen returnScreen, out MenuButton backButton)
		{
			MenuButton _backButton = null;
			MenuBuilder result = CreateMenuBuilder(title).AddControls(new SingleContentLayout(new AnchoredPosition(new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f), new Vector2(0f, -64f))), delegate(ContentArea c)
			{
				c.AddMenuButton("BackButton", new MenuButtonConfig
				{
					Label = global::Language.Language.Get("NAV_BACK", "MainMenu"),
					CancelAction = delegate
					{
						UIManager.instance.UIGoToDynamicMenu(returnScreen);
					},
					SubmitAction = delegate
					{
						UIManager.instance.UIGoToDynamicMenu(returnScreen);
					},
					Proceed = true,
					Style = MenuButtonStyle.VanillaStyle
				}, out _backButton);
			});
			backButton = _backButton;
			return result;
		}

		public static void AddModMenuContent(List<IMenuMod.MenuEntry> entries, ContentArea c, MenuScreen returnScreen)
		{
			foreach (IMenuMod.MenuEntry entry in entries)
			{
				c.AddHorizontalOption(entry.Name, new HorizontalOptionConfig
				{
					ApplySetting = delegate(MenuSetting _, int i)
					{
						entry.Saver(i);
					},
					RefreshSetting = delegate(MenuSetting s, bool _)
					{
						s.optionList.SetOptionTo(entry.Loader());
					},
					CancelAction = delegate
					{
						UIManager.instance.UIGoToDynamicMenu(returnScreen);
					},
					Description = (string.IsNullOrEmpty(entry.Description) ? ((DescriptionInfo?)null) : new DescriptionInfo?(new DescriptionInfo
					{
						Text = entry.Description
					})),
					Label = entry.Name,
					Options = entry.Values,
					Style = HorizontalOptionStyle.VanillaStyle
				}, out var horizontalOption);
				horizontalOption.menuSetting.RefreshValueFromGameSettings();
			}
		}

		public static MenuScreen CreateMenuScreen(string title, List<IMenuMod.MenuEntry> menuData, MenuScreen returnScreen)
		{
			MenuBuilder menuBuilder = CreateMenuBuilderWithBackButton(title, returnScreen, out var backButton);
			if (menuData.Count > 5)
			{
				menuBuilder.AddContent(default(NullContentLayout), delegate(ContentArea c)
				{
					c.AddScrollPaneContent(new ScrollbarConfig
					{
						CancelAction = delegate
						{
							UIManager.instance.UIGoToDynamicMenu(returnScreen);
						},
						Navigation = new Navigation
						{
							mode = Navigation.Mode.Explicit,
							selectOnUp = backButton,
							selectOnDown = backButton
						},
						Position = new AnchoredPosition
						{
							ChildAnchor = new Vector2(0f, 1f),
							ParentAnchor = new Vector2(1f, 1f),
							Offset = new Vector2(-310f, 0f)
						}
					}, new RelLength((float)menuData.Count * 105f), RegularGridLayout.CreateVerticalLayout(105f), delegate(ContentArea c2)
					{
						AddModMenuContent(menuData, c2, returnScreen);
					});
				});
			}
			else
			{
				menuBuilder.AddContent(RegularGridLayout.CreateVerticalLayout(105f), delegate(ContentArea c)
				{
					AddModMenuContent(menuData, c, returnScreen);
				});
			}
			return menuBuilder.Build();
		}
	}
}
