namespace Modding.Menu.Components
{
	public class AutoSelector : MonoBehaviour
	{
		public Selectable Start { get; set; }

		private void OnEnable()
		{
			if (Start != null)
			{
				StartCoroutine(SelectDelayed(Start));
			}
		}

		private IEnumerator SelectDelayed(Selectable selectable)
		{
			while (!selectable.gameObject.activeInHierarchy)
			{
				yield return null;
			}
			if (selectable is MenuSelectable menuSelectable)
			{
				menuSelectable.DontPlaySelectSound = true;
				selectable.Select();
				menuSelectable.DontPlaySelectSound = false;
			}
			else
			{
				selectable.Select();
			}
			Animator[] componentsInChildren = selectable.GetComponentsInChildren<Animator>();
			foreach (Animator animator in componentsInChildren)
			{
				if (animator.HasParameter("hide"))
				{
					animator.ResetTrigger("hide");
				}
				if (animator.HasParameter("show"))
				{
					animator.SetTrigger("show");
				}
			}
		}
	}
	public class ScrollPaneSelector : MonoBehaviour, ISelectHandler, IEventSystemHandler
	{
		public RectTransform PaneRect { get; set; }

		public RectTransform MaskRect { get; set; }

		public Scrollbar Scrollbar { get; set; }

		public Func<RectTransform, (float, float)> SelectionPadding { get; set; }

		public void OnSelect(BaseEventData eventData)
		{
			if (eventData is AxisEventData)
			{
				RectTransform component = base.gameObject.GetComponent<RectTransform>();
				(float, float) tuple = SelectionPadding(component);
				float item = tuple.Item1;
				float item2 = tuple.Item2;
				Matrix4x4 matrix4x = MaskRect.worldToLocalMatrix * component.localToWorldMatrix;
				float num = matrix4x.MultiplyPoint(new Vector3(0f, component.rect.yMax, 0f)).y + item;
				matrix4x.MultiplyPoint(new Vector3(0f, component.rect.yMin, 0f));
				float num2 = PaneRect.anchoredPosition.y + (MaskRect.rect.yMax - num) * 2f;
				Scrollbar.value = (PaneRect.rect.height - MaskRect.rect.height) / num2;
			}
		}
	}
}
