namespace Modding.Converters
{
	public abstract class JsonConverter<TClass> : JsonConverter
	{
		public override bool CanConvert(Type objectType)
		{
			return typeof(TClass) == objectType;
		}

		public override object ReadJson(JsonReader reader, Type objectType, object existingValue, JsonSerializer serializer)
		{
			if (typeof(TClass) == objectType)
			{
				Dictionary<string, object> dictionary = new Dictionary<string, object>();
				reader.Read();
				while (reader.TokenType == JsonToken.PropertyName)
				{
					string key = (string)reader.Value;
					reader.Read();
					dictionary.Add(key, reader.Value);
					reader.Read();
				}
				return ReadJson(dictionary, existingValue);
			}
			return serializer.Deserialize(reader);
		}

		public override void WriteJson(JsonWriter writer, object value, JsonSerializer serializer)
		{
			writer.WriteStartObject();
			WriteJson(writer, (TClass)value);
			writer.WriteEndObject();
		}

		[PublicAPI]
		public abstract TClass ReadJson(Dictionary<string, object> token, object existingValue);

		[PublicAPI]
		public abstract void WriteJson(JsonWriter writer, TClass value);
	}
	public class PlayerActionSetConverter : JsonConverter
	{
		public override bool CanConvert(Type objectType)
		{
			return objectType.IsSubclassOf(typeof(PlayerActionSet));
		}

		public override object ReadJson(JsonReader reader, Type objectType, object existingValue, JsonSerializer serializer)
		{
			PlayerActionSet playerActionSet = (PlayerActionSet)Activator.CreateInstance(objectType);
			Predicate<string> predicate = ((playerActionSet is IMappablePlayerActions mappablePlayerActions) ? new Predicate<string>(mappablePlayerActions.IsMappable) : ((Predicate<string>)((string _) => true)));
			reader.Read();
			while (reader.TokenType == JsonToken.PropertyName)
			{
				string text = (string)reader.Value;
				if (!predicate(text))
				{
					reader.Read();
					reader.Read();
					continue;
				}
				PlayerAction playerActionByName = playerActionSet.GetPlayerActionByName(text);
				reader.Read();
				if (playerActionByName != null)
				{
					if (reader.Value is string text2)
					{
						if (text2 == default(InputHandler.KeyOrMouseBinding).ToString() || text2 == InputControlType.None.ToString())
						{
							playerActionByName.ClearBindings();
						}
						else
						{
							InputHandler.KeyOrMouseBinding? keyOrMouseBinding = KeybindUtil.ParseBinding(text2);
							if (keyOrMouseBinding.HasValue)
							{
								InputHandler.KeyOrMouseBinding valueOrDefault = keyOrMouseBinding.GetValueOrDefault();
								playerActionByName.ClearBindings();
								playerActionByName.AddKeyOrMouseBinding(valueOrDefault);
							}
							else
							{
								InputControlType? inputControlType = KeybindUtil.ParseInputControlTypeBinding(text2);
								if (inputControlType.HasValue)
								{
									InputControlType valueOrDefault2 = inputControlType.GetValueOrDefault();
									playerActionByName.ClearBindings();
									playerActionByName.AddInputControlType(valueOrDefault2);
								}
								else
								{
									Logger.APILogger.LogWarn("Invalid keybinding " + text2);
								}
							}
						}
					}
					else
					{
						Logger.APILogger.LogWarn($"Expected string for keybind, got `{reader.Value}");
					}
				}
				else
				{
					Logger.APILogger.LogWarn("Invalid keybind name " + text);
				}
				reader.Read();
			}
			return playerActionSet;
		}

		public override void WriteJson(JsonWriter writer, object value, JsonSerializer serializer)
		{
			PlayerActionSet obj = (PlayerActionSet)value;
			Predicate<string> predicate = ((!(obj is IMappablePlayerActions mappablePlayerActions)) ? ((Predicate<string>)((string _) => true)) : new Predicate<string>(mappablePlayerActions.IsMappable));
			writer.WriteStartObject();
			foreach (PlayerAction action in obj.Actions)
			{
				if (predicate(action.Name))
				{
					writer.WritePropertyName(action.Name);
					InputHandler.KeyOrMouseBinding keyOrMouseBinding = action.GetKeyOrMouseBinding();
					InputControlType controllerButtonBinding = action.GetControllerButtonBinding();
					if (keyOrMouseBinding.Key != Key.None)
					{
						writer.WriteValue(keyOrMouseBinding.ToString());
					}
					else if (controllerButtonBinding != InputControlType.None)
					{
						writer.WriteValue(controllerButtonBinding.ToString());
					}
					else
					{
						writer.WriteValue("None");
					}
				}
			}
			writer.WriteEndObject();
		}
	}
	public interface IMappablePlayerActions
	{
		bool IsMappable(string name);
	}
	public class Vector2Converter : JsonConverter<Vector2>
	{
		public override Vector2 ReadJson(Dictionary<string, object> token, object existingValue)
		{
			float x = Convert.ToSingle(token["x"]);
			float y = Convert.ToSingle(token["y"]);
			return new Vector2(x, y);
		}

		public override void WriteJson(JsonWriter writer, Vector2 value)
		{
			writer.WritePropertyName("x");
			writer.WriteValue(value.x);
			writer.WritePropertyName("y");
			writer.WriteValue(value.y);
		}
	}
	public class Vector3Converter : JsonConverter<Vector3>
	{
		public override Vector3 ReadJson(Dictionary<string, object> token, object existingValue)
		{
			float x = Convert.ToSingle(token["x"]);
			float y = Convert.ToSingle(token["y"]);
			float z = Convert.ToSingle(token["z"]);
			return new Vector3(x, y, z);
		}

		public override void WriteJson(JsonWriter writer, Vector3 value)
		{
			writer.WritePropertyName("x");
			writer.WriteValue(value.x);
			writer.WritePropertyName("y");
			writer.WriteValue(value.y);
			writer.WritePropertyName("z");
			writer.WriteValue(value.z);
		}
	}
